  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Cuisses ou hauts de cuisse de poulet à la place des blancs, comptés trente à quarante-cinq minutes de cuisson (une source)','Moutarde à l''ancienne en grains, que deux sources préfèrent à la moutarde lisse','Oignon jaune à la place de l''échalote : le dossier se partage exactement, deux sources contre deux','Beurre à la place de l''huile d''olive pour la saisie (deux sources)','Déglaçage au vin blanc sec à la place du bouillon de volaille (une source)','Estragon remplacé par du persil ou de l''aneth (deux sources)','Filet de jus de citron en fin de cuisson (une source)','Tomates séchées ajoutées avec les champignons (une source)','Sauce montée au fromage blanc et relevée de curcuma, sans crème (une source)']::text[]) AS variant(name);

