  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:FR-009', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('eead340944d6ceda490b30954831668c'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":3,"acidic":1,"bitter":0,"umami":4,"heat":0,"pungency":3,"richness":3,"freshness":2,"intensity":3},"dominant_flavors":["moutarde","champignon_terreux","crème"],"aroma_families":["moutarde","champignon","échalote","estragon"],"target_textures":["volaille_moelleuse","sauce_nappante","champignon_ferme"],"signature_ingredients":["Blanc de poulet cru, sans peau","Champignon de Paris frais","Moutarde de Dijon"],"identity_guardrails":["La moutarde entre hors du feu et ne bout jamais ensuite : bouillie, elle perd son piquant et ne laisse qu''une amertume.","Les champignons se colorent à part avant d''entrer dans la sauce ; jetés directement dans la crème, ils la délavent de leur eau.","Le nom porte la moutarde ET les champignons : retirer l''un des deux fait un autre plat, pas une variante."]}'::jsonb, 'myko_v3_sensory_contract')
