  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:IT-002', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('987233709475ce81bc93cceb12282de9'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"earthy_herbal","scores":{"sweet":1,"salty":3,"acidic":2,"bitter":2,"umami":4,"heat":1,"pungency":2,"richness":3,"freshness":3,"intensity":4},"dominant_flavors":["terreux","herbacé","savoureux"],"aroma_families":["échalote","vin_blanc_réduit","champignon_terreux","beurre","parmesan"],"target_textures":["tendre","contraste_léger"],"signature_ingredients":["Riz arborio cru","Champignon de Paris frais","Bouillon de légumes non salé","Échalote crue"],"identity_guardrails":["conserver_les_ingrédients_signatures","conserver_la_technique_centrale","ne_pas_remplacer_par_un_simple_équivalent_nutritionnel"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
