DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Gnocchi tomate et mozzarella', 'gnocchi tomate et mozzarella', 'Italie / cuisine domestique française', 'Italie / cuisine domestique française',
     'meal', 'pâtes gratinées', 'domestic_standard', 'tomato_herbal',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Gnocchi tomate et mozzarella', 'Gnocchi de pomme de terre pochés dans une sauce tomate, gratinés à la mozzarella', ds.id, 'IT-006',
    'Myko', 'editorial', 4, 15, 30, 'facile',
    NULL, NULL,
    'B', 'candidate', '0268814d845cd9404e7b854839b435ea',
    '{"sweet":2,"salty":3,"acidic":3,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":3}'::jsonb, ARRAY['tomate cuite','fromage fondu','basilic']::text[],
    ARRAY['tomate_cuite','oignon_compoté','fromage_gratiné','basilic']::text[], ARRAY['gnocchi_moelleux','sauce_nappante','croûte_gratinée']::text[],
    ARRAY['Gnocchi de pomme de terre frais','Mozzarella','Tomate concassée en conserve','Basilic frais']::text[], ARRAY['Les trois éléments du nom doivent être là et rester distincts : des gnocchi moelleux, une sauce tomate réduite, une mozzarella fondue en surface. Fondue dans la sauce, elle disparaît et le plat n''est plus qu''un gnocchi à la tomate.','La mozzarella s''égoutte avant de passer au four : son eau de saumure délave la sauce et la rend filandreuse, et c''est la faute qui défait ce plat le plus souvent.','La sauce doit être réduite avant l''assemblage — les gnocchi ne rendent pas d''eau à la cuisson mais n''en absorbent pas non plus, et rien ne rattrapera au four une sauce trop liquide.','Le basilic entre à la sortie du four : passé au gril, il noircit et le plat perd la seule note fraîche qui l''équilibre.']::text[],
    ARRAY['suer','réduction de sauce tomate','pochage des gnocchi','gratinage']::text[], ARRAY['Gnocchi alla Sorrentina complet (une source) : une aubergine en dés rissolée ajoutée à la sauce et une dizaine de tomates confites','Tomates confites ou séchées à l''huile, 120 g pour la garniture (deux sources sur trois) — forme absente du catalogue','Poêlée sans four (une source) : gnocchi à poêler au beurre avec un poireau émincé et des tomates cerise, mozzarella fondue hors du feu','Oignons frits croustillants en garniture au lieu de l''oignon fondu, 120 g (une source) — forme absente du catalogue','Mozzarella di bufala à la place de la mozzarella au lait de vache (une source)','Trente grammes de parmesan râpé sur le gratin (une source)']::text[], ARRAY['gluten','lait']::text[],
    'Trois jours au réfrigérateur, couvert. Le gratin se réchauffe au four à 180 °C, quinze minutes, plutôt qu''au micro-ondes qui détend les gnocchi et fait rendre son gras à la mozzarella. La congélation est déconseillée sur le plat monté : les gnocchi de pomme de terre se délitent à la décongélation. On peut en revanche congeler la sauce seule trois mois et monter le gratin ensuite.', '{"fridge_hours":72,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

