    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['La trame marmiton au champagne troque le bouillon contre 35 cl de champagne et 3 cl de porto, et lie la soupe de deux jaunes d''œuf battus avant de la passer au gril.','Le comté et le beaufort tiennent le rôle du gruyère sur deux des six pages : le comté sale davantage, le beaufort donne une croûte plus souple et plus grasse.','Deux auteurs de chefsimon relèvent la soupe d''une pincée de quatre-épices ou de muscade râpée ajoutée au bouillon.','Une cuillerée à soupe de sucre jetée sur les oignons en début de cuisson accélère leur coloration, comme le fait une page de chefsimon.','Chef Simon jette une poignée de vermicelles fins dans le bouillon en fin de cuisson, en option, pour épaissir la soupe sans farine.','Une page de chefsimon prend du pain complet ou aux céréales pour les croûtons, ce qui donne un gratin plus rustique et plus dense.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"FR-012","variants":["La trame marmiton au champagne troque le bouillon contre 35 cl de champagne et 3 cl de porto, et lie la soupe de deux jaunes d''œuf battus avant de la passer au gril.","Le comté et le beaufort tiennent le rôle du gruyère sur deux des six pages : le comté sale davantage, le beaufort donne une croûte plus souple et plus grasse.","Deux auteurs de chefsimon relèvent la soupe d''une pincée de quatre-épices ou de muscade râpée ajoutée au bouillon.","Une cuillerée à soupe de sucre jetée sur les oignons en début de cuisson accélère leur coloration, comme le fait une page de chefsimon.","Chef Simon jette une poignée de vermicelles fins dans le bouillon en fin de cuisson, en option, pour épaissir la soupe sans farine.","Une page de chefsimon prend du pain complet ou aux céréales pour les croûtons, ce qui donne un gratin plus rustique et plus dense."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:FR-012', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('e3aaf56f15d50ad1a4abff3357db99dd'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"brothy_umami","scores":{"sweet":3,"salty":3,"acidic":1,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":0,"intensity":4},"dominant_flavors":["oignon caramélisé","bouillon de volaille réduit","gruyère gratiné","vin blanc réduit"],"aroma_families":["allium caramélisé","bouillon de volaille","fromage gratiné","pain grillé"],"target_textures":["bouillon nappant","oignons fondants","croûte de fromage gratinée","pain imbibé"],"signature_ingredients":["Oignon jaune cru","Bouillon de volaille","Pain de campagne","Gruyère râpé"],"identity_guardrails":["L''oignon doit atteindre une coloration acajou franche : simplement fondu et blond, il donne une soupe d''oignons, pas la soupe à l''oignon gratinée.","Le gratin est le plat autant que le bouillon : sans la tranche de pain couverte de fromage et passée au gril, il ne reste qu''une soupe d''oignons.","Le mouillement doit rester un bouillon clair et peu lié ; la farine ne sert qu''à donner du corps, et une soupe liée comme une sauce cesse d''être ce plat.","Aucune crème n''entre ici : sur les six pages du dossier, pas une n''en met, et la richesse vient du beurre de départ et du fromage fondu."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Velouté de champignons', 'veloute de champignons', 'France', 'France',
     'meal', 'soupe', 'domestic_standard', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Velouté de champignons', 'Champignons de Paris mixés en velouté sur une base de béchamel, liés à la crème fraîche', ds.id, 'FR-013',
    'Myko', 'editorial', 6, 20, 35, 'facile',
    NULL, NULL,
    'B', 'candidate', 'ce0bcd27f30e71f21e4668946b0e9faf',
    '{"sweet":1,"salty":3,"acidic":1,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['champignon terreux','lait et crème','beurre','oignon fondu']::text[],
    ARRAY['champignon','lacté','beurre','persil frais']::text[], ARRAY['velouté lisse','nappant','sans fibre','champignons poêlés fermes']::text[],
    ARRAY['Champignon de Paris frais','Lait entier','Crème fraîche liquide entière']::text[], ARRAY['Le champignon doit rester l''ingrédient dominant en masse : dès qu''un autre légume prend le dessus — poireau, pomme de terre, carotte — le velouté change de nom, comme le montrent les deux titres dérivants du dossier.','Le liquide est lacté : remplacer entièrement le lait par de l''eau ou du bouillon donne une soupe de champignons, pas un velouté.','Les champignons doivent avoir rendu puis évaporé leur eau avant le mouillement ; noyés trop tôt, ils bouillent au lieu de concentrer et le velouté reste plat.','La texture doit être entièrement mixée et sans fibre : des lamelles laissées entières en feraient une soupe rustique.']::text[],
    ARRAY['parage','suer','roux blanc','mijotage','mixage','poêlage']::text[], ARRAY['Chef Simon lie le velouté hors du feu de deux jaunes d''œuf battus avec la crème : la texture s''épaissit sans farine supplémentaire, mais toute ébullition est ensuite interdite.','Une page chefsimon déglace les champignons de 10 cl de vin blanc sec avant de mouiller, ce qui apporte une acidité plus franche que le citron.','La version express de marmiton part de 460 g de champignons de Paris en boîte égouttés, remplace le lait par 25 cl de crème liquide et lie au pain sec émietté.','Deux pages se passent de roux et lient le velouté d''une pomme de terre cuite avec les champignons puis mixée avec eux.','750g monte un velouté aux champignons des bois où les champignons de Paris cèdent la place à des sauvages, relevés de poudre de chili, de gingembre râpé et de paprika fumé.','Deux cuillerées à café de madère ajoutées en fin de cuisson, en option chez marmiton.','Une page chefsimon monte le même velouté sur une base de poireaux et de gingembre frais, les champignons n''y étant plus qu''une garniture poêlée avec du bacon grillé.']::text[], ARRAY['gluten','lait']::text[],
    'Se garde trois jours au réfrigérateur entre 0 et 4 °C dans un contenant bien fermé — le champignon capte vite les odeurs voisines. Réchauffer à feu doux sans jamais bouillir, la crème tranchant à l''ébullition. Pour la congélation, congeler la base mixée non crémée jusqu''à trois mois et n''incorporer la crème qu''au réchauffage : congelée crémée, elle se déphase et rend le velouté granuleux. Les champignons poêlés de garniture se font au dernier moment, ils ramollissent en quelques heures.', '{"fridge_hours":72,"eat_immediately":false,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

