  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Deux pages du dossier, une marmiton et une chefsimon, ajoutent 200 g de châtaignes cuites au mouillement : le velouté s''épaissit et la note de châtaigne double. La forme n''existe pas au catalogue et la variante reste une indication tant qu''elle n''est pas arbitrée.','Une page marmiton complète le potimarron de quatre carottes et de trois pommes de terre, ce qui donne un velouté plus dense, plus terreux et moins sucré.','Chef Simon marie le potimarron à un gros panais, mouillé simplement à l''eau et à deux cubes de bouillon de légumes.','Une page chefsimon parfume le velouté d''une dizaine de pistils de safran, d''une cuillerée à café de cumin en poudre et d''un trait de jus d''orange, et remplace la crème par de la crème de soja.','Marmiton mouille au lait entier plutôt qu''au bouillon, après l''avoir infusé de deux clous de girofle, de grains de poivre noir et de lamelles de gingembre frais, et termine chaque assiette de ciboulette ciselée.','750g monte la crème liquide en chantilly non sucrée et en dépose une cuillerée sur chaque assiette au moment de servir ; une autre page y ajoute des morilles séchées réhydratées.','L''échalote remplace l''oignon sur deux des huit pages ; ailleurs le beurre cède la place à l''huile d''olive, à l''huile de colza ou à l''huile de noisette, une page chacune.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"FR-014","variants":["Deux pages du dossier, une marmiton et une chefsimon, ajoutent 200 g de châtaignes cuites au mouillement : le velouté s''épaissit et la note de châtaigne double. La forme n''existe pas au catalogue et la variante reste une indication tant qu''elle n''est pas arbitrée.","Une page marmiton complète le potimarron de quatre carottes et de trois pommes de terre, ce qui donne un velouté plus dense, plus terreux et moins sucré.","Chef Simon marie le potimarron à un gros panais, mouillé simplement à l''eau et à deux cubes de bouillon de légumes.","Une page chefsimon parfume le velouté d''une dizaine de pistils de safran, d''une cuillerée à café de cumin en poudre et d''un trait de jus d''orange, et remplace la crème par de la crème de soja.","Marmiton mouille au lait entier plutôt qu''au bouillon, après l''avoir infusé de deux clous de girofle, de grains de poivre noir et de lamelles de gingembre frais, et termine chaque assiette de ciboulette ciselée.","750g monte la crème liquide en chantilly non sucrée et en dépose une cuillerée sur chaque assiette au moment de servir ; une autre page y ajoute des morilles séchées réhydratées.","L''échalote remplace l''oignon sur deux des huit pages ; ailleurs le beurre cède la place à l''huile d''olive, à l''huile de colza ou à l''huile de noisette, une page chacune."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:FR-014', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('f029d5d2ce3721dea0b5282ae4b244ef'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":3,"salty":2,"acidic":0,"bitter":0,"umami":2,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":2},"dominant_flavors":["potimarron sucré","crème lactée","beurre","muscade"],"aroma_families":["courge","lacté","beurre","muscade"],"target_textures":["velouté lisse","nappant","sans fibre"],"signature_ingredients":["Potimarron frais, épépiné","Crème fraîche liquide entière","Bouillon de légumes"],"identity_guardrails":["Le potimarron reste seul en scène, à 200 g de chair par portion : l''adjonction massive de carotte, de pomme de terre ou de panais en fait un autre velouté.","La peau ne s''enlève pas : c''est ce qui distingue le potimarron d''une courge à éplucher, et son parfum de châtaigne en dépend.","L''oignon doit suer sans coloration ; une base caramélisée écrase la douceur qui est tout l''intérêt du plat.","La crème s''incorpore hors du feu, en finition, et jamais en début de cuisson."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Minestrone', 'minestrone', 'Italie', 'Italie',
     'meal', 'soupe complète', 'named_traditional_dish', 'brothy_umami',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Minestrone', 'Soupe de légumes de saison avec haricots blancs, pommes de terre et petites pâtes dans un bouillon', ds.id, 'IT-008',
    'Myko', 'editorial', 8, 30, 55, 'facile',
    NULL, NULL,
    'B', 'candidate', 'e025c905732f0a1574fb91aad6ae39bb',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":2,"freshness":3,"intensity":3}'::jsonb, ARRAY['bouillon de légumes','tomate','basilic']::text[],
    ARRAY['bouillon','tomate_cuite','oignon_compoté','basilic','céleri']::text[], ARRAY['légumes_tendres_distincts','bouillon_lié','pâtes_fermes']::text[],
    ARRAY['Haricot blanc cuit, égoutté','Petites pâtes sèches','Tomate fraîche mûre','Courgette fraîche','Basilic frais']::text[], ARRAY['Un minestrone porte à la fois une légumineuse et un féculent en grain — haricot blanc et petites pâtes ici : sans eux, il reste une soupe de légumes, et six sources sur huit portent l''un ou l''autre.','Les légumes restent en dés distincts sous la cuillère : mixé, le plat devient un velouté et perd la définition qui fait son nom.','Les légumes entrent par ordre de tenue, les durs d''abord et les tendres dix minutes avant la fin ; tous ensemble, la courgette disparaît et la carotte reste crue.','Les pâtes cuisent dans le bouillon et non à part : leur amidon est le seul liant de la soupe, et cuites séparément elles laissent un bouillon clair.']::text[],
    ARRAY['suer','cuisson séquencée par tenue des légumes','cuisson des pâtes dans le bouillon','finition à l''huile crue']::text[], ARRAY['Grosse boîte de tomates pelées à la place des tomates fraîches, hors saison (une source sur huit)','Trois cents grammes de haricots rouges pour quatre à la place du haricot blanc (une source)','Cent grammes d''épeautre à la place des pâtes, mis avec les légumes durs (une source)','Deux poireaux émincés ou un blanc de poireau ajoutés au soffritto (deux sources)','Trois cuillerées de persil haché avec le basilic en finition (deux sources)','Version épicée (une source) : un chorizo fort en rondelles avec les lardons, herbes de Provence, et une boîte de petits pois avec les légumes tendres','Deux navets en dés avec les légumes durs (une source)','Version d''hiver (une source) : potimarron et chou-rave à la place de la courgette et des haricots verts','Soupe au pistou (une source) : basilic, ail et parmesan pilés à l''huile, montés en pistou et servis à part à la place du basilic déchiré','Deux feuilles de sauge dans le bouillon (une source)','Beurre à la place de l''huile d''olive au départ, soixante grammes (une source)']::text[], ARRAY['gluten','céleri','lait']::text[],
    'Quatre jours au réfrigérateur, et la soupe gagne du goût la deuxième journée. Réserve faite des pâtes : elles continuent d''absorber le bouillon au froid et la soupe se resserre en plat épais — allonger d''un demi-litre de bouillon au réchauffage, ou cuire les pâtes le jour même dans la portion qu''on va servir et garder le reste sans elles. Se congèle trois mois, sans les pâtes ni la pomme de terre, qui se délitent à la décongélation. Réchauffer à frémissement et ajouter le basilic seulement au moment de servir.', '{"fridge_hours":96,"eat_immediately":false,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

