  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:FR-016', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('f17d32833033c7fdfd35f2ad74728502'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"rich_winey","scores":{"sweet":1,"salty":3,"acidic":2,"bitter":1,"umami":5,"heat":0,"pungency":2,"richness":5,"freshness":1,"intensity":5},"dominant_flavors":["umami","rôti","vinique"],"aroma_families":["oignon_compoté","vin_rouge_réduit","champignon_terreux","fumé"],"target_textures":["protéine_fondante","sauce_nappante"],"signature_ingredients":["Cuisse de poulet crue, avec os, avec peau","Vin rouge sec","Lardon fumé cru","Champignon de Paris frais"],"identity_guardrails":["conserver_les_ingrédients_signatures","conserver_la_technique_centrale","ne_pas_remplacer_par_un_simple_équivalent_nutritionnel"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
