  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Version moutarde et miel : une cuillerée de miel ajoutée avec la moutarde (une source)','Deux moutardes, forte et Savora, mélangées à parts égales (une source)','Moutarde à l''ancienne en grains à la place de la moutarde lisse (une source)','Champignons de Paris en boîte, égouttés, ajoutés à la sauce (deux sources)','Sauce montée sur un bouillon de légumes en plus du vin blanc (deux sources)','Oignon rouge à la place de l''échalote (une source)','Ail en semoule et herbes de Provence frottés sur la viande avant la saisie (une source)','Tournedos panés d''amandes effilées, sauce liée au mascarpone (une source)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"FR-018","variants":["Version moutarde et miel : une cuillerée de miel ajoutée avec la moutarde (une source)","Deux moutardes, forte et Savora, mélangées à parts égales (une source)","Moutarde à l''ancienne en grains à la place de la moutarde lisse (une source)","Champignons de Paris en boîte, égouttés, ajoutés à la sauce (deux sources)","Sauce montée sur un bouillon de légumes en plus du vin blanc (deux sources)","Oignon rouge à la place de l''échalote (une source)","Ail en semoule et herbes de Provence frottés sur la viande avant la saisie (une source)","Tournedos panés d''amandes effilées, sauce liée au mascarpone (une source)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
