    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:GR-001', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('c59d147b07c9070a7b4b05d37d639fc7'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"rich_winey","scores":{"sweet":1,"salty":3,"acidic":2,"bitter":1,"umami":5,"heat":0,"pungency":2,"richness":5,"freshness":1,"intensity":5},"dominant_flavors":["umami","rôti","vinique"],"aroma_families":["ail","oignon_compoté","vin_rouge_réduit","tomate_cuite","beurre","parmesan","cannelle"],"target_textures":["dessus_doré","intérieur_fondant_ou_crémeux"],"signature_ingredients":["Aubergine fraîche","Agneau haché cru","Tomate concassée en conserve","Oignon jaune cru"],"identity_guardrails":["conserver_les_ingrédients_signatures","conserver_la_technique_centrale","ne_pas_remplacer_par_un_simple_équivalent_nutritionnel"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
