  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Fendre chaque poireau en deux dans la longueur et le passer sous l''eau claire en écartant les feuilles une à une : le sable se dépose entre elles et un rinçage extérieur ne l''emporte pas. Émincer ensuite en demi-rondelles de trois à quatre millimètres, régulières, pour que tout s''affaisse en même temps.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
