     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"DESS-006","variants":["Sans pâte","chocolat","praliné"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:DESS-006', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('6c45edc57766750f5a59eca14d08c85c'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"sweet_spiced","scores":{"sweet":5,"salty":1,"acidic":1,"bitter":1,"umami":1,"heat":1,"pungency":2,"richness":4,"freshness":2,"intensity":4},"dominant_flavors":["sucré","beurré","épices douces"],"aroma_families":["beurre","lacté","vanille"],"target_textures":["dessus_doré","intérieur_fondant_ou_crémeux"],"signature_ingredients":["Pâte brisée crue","Lait entier","Crème fraîche liquide entière","Œuf cru"],"identity_guardrails":["conserver_les_ingrédients_signatures","conserver_la_technique_centrale","ne_pas_remplacer_par_un_simple_équivalent_nutritionnel"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
