    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:FR-025', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('0d6255cee3eaee200a153353b00a0085'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":1,"heat":0,"pungency":0,"richness":5,"freshness":0,"intensity":2},"dominant_flavors":["beurre","pomme de terre","lait chaud"],"aroma_families":["lacté","beurre","muscade"],"target_textures":["velouté","lisse","souple à la cuillère"],"signature_ingredients":["Pomme de terre crue, épluchée","Beurre doux","Lait entier"],"identity_guardrails":["Une variété farineuse et un écrasement mécanique, jamais de lame : passée au robot, la préparation devient une colle élastique qui n''est plus une purée.","Le beurre entre avant le liquide et à froid ; versé après le lait, il ne s''émulsionne plus et la purée reste grasse au palais au lieu d''être veloutée.","La proportion d''un dixième de beurre pour la pomme de terre est ce qui distingue la purée de la pomme de terre écrasée : divisée par trois, il ne reste qu''un légume mouillé."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
