  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('2d6bce8c62a220c7ca1302827a34b6f6'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":0,"intensity":3},"dominant_flavors":["fromage_affiné","beurre","muscade"],"aroma_families":["beurre","gruyère","pâte_à_choux"],"target_textures":["coque_croustillante","intérieur_creux","mie_soufflée"],"signature_ingredients":["Gruyère râpé","Beurre doux","Œuf cru","Farine de blé T55"],"identity_guardrails":["Sans fromage, ce sont des choux salés et non des gougères : les neuf sources en mettent en moyenne 100 g pour 100 g de farine, autant que la farine elle-même.","La panade doit être desséchée sur le feu avant les œufs ; sans ce passage la pâte ne gonfle pas et on obtient des galettes, quelle que soit la température du four.","Le fromage est râpé et incorporé dans la pâte, pas seulement parsemé dessus : la gougère est creuse, et si le goût n''est pas dans la coque il n''est nulle part."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
