  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:FR-036', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('f6b001f96bc9b18a3e14e8cad7f26333'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_delicate","scores":{"sweet":1,"salty":3,"acidic":1,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":2,"intensity":3},"dominant_flavors":["crémeux","doux","savoureux"],"aroma_families":["beurre","lacté","fumé"],"target_textures":["dessus_doré","intérieur_fondant_ou_crémeux"],"signature_ingredients":["Pâte brisée crue","Poireau cru","Lardon fumé cru","Œuf cru"],"identity_guardrails":["conserver_les_ingrédients_signatures","conserver_la_technique_centrale","ne_pas_remplacer_par_un_simple_équivalent_nutritionnel"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Parmentier de canard', 'parmentier de canard', 'France (Sud-Ouest)', 'France (Sud-Ouest)',
     'meal', 'gratin parmentier', 'named_traditional_dish', 'rich_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Parmentier de canard', 'Confit de canard effiloché recouvert d''une purée de pommes de terre, gratiné au comté', ds.id, 'FR-037',
    'Myko', 'editorial', 6, 40, 50, 'facile',
    NULL, NULL,
    'B', 'candidate', '278f3115d38665381cf0d2f3ce150ae5',
    '{"sweet":2,"salty":3,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":4}'::jsonb, ARRAY['canard confit','beurre','oignon fondu','fromage gratiné']::text[],
    ARRAY['graisse de canard','oignon compoté','croûte grillée','muscade']::text[], ARRAY['chair filandreuse','purée souple','croûte croustillante']::text[],
    ARRAY['Confit de canard cuit, effiloché','Pomme de terre crue, épluchée','Beurre doux']::text[], ARRAY['Sans confit de canard ce n''est plus qu''un hachis parmentier : la chair effilochée cuite dans sa graisse est le plat lui-même','Deux couches distinctes, garniture dessous et purée dessus — mélangées, c''est une autre préparation','Une croûte dorée au four : un parmentier servi sans gratiner n''est pas fini','Aucune viande hachée crue en remplacement du confit, même à protéines égales']::text[],
    ARRAY['confit tiédi','effilochage','fondue d''oignons','purée au presse-purée','montage en couches','gratinage']::text[], ARRAY['Au potiron vanillé, moitié potiron moitié pomme de terre, la purée mouillée au lait de soja (marmiton)','Aux noisettes concassées dans la garniture et au comté sur le dessus (chefsimon)','Aux petits pois écossés et oignons nouveaux à la place de la purée de pomme de terre (chefsimon)','Aux courgettes et panais mêlés à la purée, finition ciboulette (750g)','Garniture déglacée au madère ou au porto et liée d''un fond de canard, montée sur des tranches de pain (chefsimon)','Purée enrichie de crème fraîche en plus du lait (marmiton, chefsimon)','Une pointe de miel dans le canard effiloché (marmiton)','Dessus de chapelure plutôt que de fromage, éventuellement avec un éclat de foie gras dans la garniture (750g)']::text[], ARRAY['lait']::text[],
    'Se garde 3 jours au réfrigérateur, couvert, et se réchauffe 25 minutes à 170 °C plutôt qu''au micro-ondes, qui détrempe la croûte. Se congèle 2 mois, cru ou cuit, dans son plat filmé : décongeler une nuit au froid avant de cuire ou de réchauffer. Ne pas recongeler un confit déjà décongelé.', '{"fridge_hours":72,"eat_immediately":false,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

