  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('e4a9f5453f6bbf955e7f2272d9d50339'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"sweet_fresh","scores":{"sweet":5,"salty":0,"acidic":3,"bitter":0,"umami":0,"heat":0,"pungency":1,"richness":2,"freshness":5,"intensity":3},"dominant_flavors":["fruité","frais","acidulé"],"aroma_families":["lacté","vanille"],"target_textures":["tendre","contraste_léger"],"signature_ingredients":["Crème fraîche liquide entière","Sucre semoule","Gélatine feuille","Gousse de vanille"],"identity_guardrails":["conserver_les_ingrédients_signatures","conserver_la_technique_centrale","ne_pas_remplacer_par_un_simple_équivalent_nutritionnel"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
