  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:REAL-078', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('399a2ee5c6a9a4a8b98dbd20002bb5bd'::text), 'myko_v3_canonical_recipe'),
