  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:REAL-084', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('53d4017fdb341d10d2c3cefcc966b7ff'::text), 'myko_v3_canonical_recipe'),
