  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Détacher les feuilles de frisée, écarter le trognon et les côtes les plus dures, puis laver dans un grand volume d''eau froide en soulevant la verdure hors de l''eau plutôt qu''en la versant dans une passoire — le sable descend et reste au fond. Essorer longuement, en essoreuse ou dans un torchon claqué à bout de bras : une feuille encore mouillée refuse la vinaigrette, qui glisse et se ramasse au fond du saladier. Réserver au frais dans un linge.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Couper le pain rassis en dés d''environ un centimètre, croûte comprise. Le prendre de la veille et non frais : un pain frais absorbe la graisse comme une éponge et rend le croûton lourd, alors qu''un pain sec sèche encore et croustille. Réserver.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Faire revenir les lardons à sec dans une poêle froide, à feu moyen, sans ajouter de matière grasse. Le froid au départ laisse le gras fondre avant que la chair ne se contracte, et on obtient des lardons dorés au lieu de lardons durs nageant dans leur eau. Compter huit à dix minutes, en remuant. Les égoutter à l''écumoire et les garder au chaud, en laissant toute la graisse dans la poêle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Jeter les dés de pain dans cette graisse chaude et les faire dorer trois à quatre minutes en secouant la poêle sans arrêt, pour qu''ils prennent couleur sur toutes leurs faces. C''est ici que le plat se lie : le croûton porte le goût du lard et non celui d''un corps gras neutre. Les débarrasser sur du papier absorbant dès qu''ils sont bruns, ils continueraient à cuire dans la poêle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Monter la vinaigrette dans le fond du saladier : délayer la moutarde avec le vinaigre et une pincée de sel, fouetter jusqu''à ce que le sel soit dissous, puis verser l''huile en filet en fouettant pour obtenir une sauce liée et courte. Dissoudre le sel dans le vinaigre avant l''huile, et non l''inverse : dans un corps gras il ne se dissout pas et reste en grains sur la salade. Poivrer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Pocher les œufs un par un. Porter une casserole large d''eau à petits frémissements, ajouter une cuillerée de vinaigre, casser chaque œuf dans une louche puis le glisser au ras de l''eau. Compter trois minutes exactement : le blanc doit prendre et le jaune rester liquide, puisque c''est lui qui viendra napper la salade quand on le percera. Retirer à l''écumoire, égoutter sur un linge et parer les filaments de blanc aux ciseaux. Ne pas saler l''eau, le sel disperse le blanc.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Verser la frisée sur la vinaigrette, ajouter les lardons encore chauds et retourner largement à la main, du fond vers la surface, une dizaine de gestes seulement. La chaleur des lardons attendrit à peine la feuille et libère l''huile de la vinaigrette : c''est ce contraste de tiède et de cru qui fait la salade lyonnaise, et il ne dure pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Répartir aussitôt dans quatre assiettes creuses, semer les croûtons sur le dessus pour qu''ils restent secs, poser un œuf poché au centre de chacune et parsemer de ciboulette ciselée. Donner un tour de moulin et porter à table sans attendre : au bout de cinq minutes la frisée s''affaisse et les croûtons ramollissent.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'REAL-087', 'recipe_family', 'Salade lyonnaise',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'REAL-087', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Avec un saucisson lyonnais à cuire, poché et servi en rondelles tièdes sur la salade (marmiton, deux sources)','Cerneaux de noix concassés ajoutés aux croûtons (marmiton)','Une échalote ciselée fondue dans la vinaigrette (chefsimon)','Pissenlits à la place de la frisée, racine ôtée (marmiton, chefsimon)','Batavia ou roquette à la place de la frisée (chefsimon)','Croûtons dorés au beurre plutôt qu''à la graisse de lard (chefsimon)','Une pointe de sauce Maggi dans la vinaigrette (marmiton)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"REAL-087","variants":["Avec un saucisson lyonnais à cuire, poché et servi en rondelles tièdes sur la salade (marmiton, deux sources)","Cerneaux de noix concassés ajoutés aux croûtons (marmiton)","Une échalote ciselée fondue dans la vinaigrette (chefsimon)","Pissenlits à la place de la frisée, racine ôtée (marmiton, chefsimon)","Batavia ou roquette à la place de la frisée (chefsimon)","Croûtons dorés au beurre plutôt qu''à la graisse de lard (chefsimon)","Une pointe de sauce Maggi dans la vinaigrette (marmiton)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:REAL-087', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('ebd56eb6b404a588659583ac16481de7'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"fresh_acidic","scores":{"sweet":1,"salty":4,"acidic":4,"bitter":3,"umami":3,"heat":0,"pungency":2,"richness":3,"freshness":4,"intensity":3},"dominant_flavors":["amertume de la frisée","vinaigre de vin","lard fumé","moutarde"],"aroma_families":["fumé","vinaigre de vin rouge","moutarde","pain grillé"],"target_textures":["feuille croquante","lardon doré","croûton sec","jaune coulant"],"signature_ingredients":["Frisée fraîche","Lardon fumé cru","Œuf cru"],"identity_guardrails":["Une verdure amère : sur une laitue douce, la vinaigrette et le lard n''ont plus rien à équilibrer","Un jaune coulant qui fait sauce quand on le perce — œuf cuit dur, le plat perd sa liaison","Lardons et croûtons ajoutés chauds sur la salade crue : le contraste tiède-cru est le plat","Vinaigrette au vinaigre de vin et à la moutarde, jamais une sauce crémée"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
