         'v3:REAL-088', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('1f432d29c4a4ca328618367068022bd0'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_delicate","scores":{"sweet":1,"salty":3,"acidic":1,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":2,"intensity":3},"dominant_flavors":["crémeux","doux","savoureux"],"aroma_families":["beurre","lacté","poireau","crème","muscade"],"target_textures":["fondant_de_poireau","pâte_croustillante","appareil_moelleux"],"signature_ingredients":[],"identity_guardrails":["poireau_dominant","pas_de_lardons_obligatoires","garniture_non_aqueuse"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
