     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 6, 'g', 'required',
     'assaisonnement', false, 5);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 2, 'g', 'required',
     'assaisonnement', false, 6);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Compter environ 700 g de pommes de terre en robe pour obtenir les 600 g épluchés déclarés. Les éplucher et les couper en rondelles de trois millimètres, ou en petits morceaux irréguliers d''un centimètre — les deux écoles existent, mais l''épaisseur importe : plus épais, elles restent fermes au cœur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Émincer l''oignon en fines demi-lunes. Chauffer l''huile dans une poêle de vingt-quatre centimètres à feu MOYEN-DOUX et y verser pommes de terre et oignon avec la moitié du sel. Ils doivent frémir doucement et non frire : c''est un pochage à l''huile, pas une friture, et une huile trop chaude donne des pommes de terre croustillantes qui ne se lieront pas aux œufs.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Laisser confire quinze à vingt minutes en remuant de temps en temps, jusqu''à ce qu''une rondelle s''écrase entre deux doigts. Les pommes de terre ne doivent pas colorer, ou à peine. Elles s''attendrissent en absorbant une partie de l''huile — c''est ce que la recette recherche, et c''est aussi pourquoi il en faut plus qu''on n''en mangera.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser le contenu de la poêle dans une passoire posée sur un bol et laisser ÉGOUTTER cinq minutes. L''huile récupérée — la moitié environ — se garde et se réutilise ; c''est elle que la recette précédente comptait dans le plat alors qu''elle n''y entre pas. Réserver deux cuillerées pour la cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Battre les œufs dans un grand saladier avec le reste du sel et le poivre, juste assez pour les mêler. Y verser les pommes de terre égouttées encore chaudes et mélanger doucement à la spatule, en écrasant un peu les morceaux contre la paroi. Laisser reposer dix minutes : l''amidon et l''œuf se lient, et c''est ce repos qui donne à la tortilla sa tenue à la découpe.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Chauffer deux cuillerées de l''huile réservée dans la poêle à feu moyen, y verser l''appareil, l''égaliser et rabattre les bords vers le centre à la spatule pendant la première minute. Baisser à feu doux et laisser prendre six à huit minutes : le dessous doit être doré et le dessus encore liquide.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Poser une grande assiette plate sur la poêle, la plaquer d''une main et RETOURNER l''ensemble d''un geste franc et rapide, au-dessus de l''évier. L''hésitation est ce qui rate ce geste, pas la maladresse. Refaire glisser la tortilla dans la poêle côté cru dessous et cuire cinq à six minutes de plus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'La tortilla est prête quand elle est ferme sur les bords et souple au centre sous le doigt : les Espagnols la préfèrent « jugosa », c''est-à-dire encore un peu coulante à cœur. La faire glisser sur un plat et attendre au moins dix minutes avant de couper — chaude, elle s''effondre ; tiède, elle se tranche net et se mange aussi bien froide le lendemain.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'REAL-108', 'recipe_family', 'Tortilla española',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'REAL-108', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Au chorizo doux et au persil, 50 g pour quatre (chefsimon)','Au manchego râpé et à la crème, avec du jambon ibérique (chefsimon)','À la carotte râpée et à la feta, avec moutarde et ciboulette (marmiton)','Aux blancs de poulet et au fromage râpé (750g)','Sur des pommes de terre déjà cuites en robe des champs et refroidies, en galette (chefsimon)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"REAL-108","variants":["Au chorizo doux et au persil, 50 g pour quatre (chefsimon)","Au manchego râpé et à la crème, avec du jambon ibérique (chefsimon)","À la carotte râpée et à la feta, avec moutarde et ciboulette (marmiton)","Aux blancs de poulet et au fromage râpé (750g)","Sur des pommes de terre déjà cuites en robe des champs et refroidies, en galette (chefsimon)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:REAL-108', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('e900fc4494069bf921be02957515a0ab'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"rich_savory","scores":{"sweet":2,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":0,"richness":4,"freshness":0,"intensity":3},"dominant_flavors":["pomme de terre","œuf","oignon confit","huile d’olive"],"aroma_families":["œuf cuit","oignon compoté","fruité olive"],"target_textures":["fondant","appareil pris","dessus doré"],"signature_ingredients":["Pomme de terre crue, épluchée","Œuf cru","Oignon jaune cru"],"identity_guardrails":["Les pommes de terre confisent à l''huile douce, elles ne frissent pas","L''huile de pochage s''égoutte : ce qui est déclaré est ce qui reste dans la galette","Le cœur reste souple — une tortilla cuite à sec est ratée","C''est un plat de pommes de terre liées à l''œuf, pas une omelette garnie"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
