      ('sensory_contract', '{"profile":"smoky_sweet","scores":{"sweet":3,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":2,"pungency":2,"richness":4,"freshness":2,"intensity":5},"dominant_flavors":["fumé","caramélisé","savoureux"],"aroma_families":["ail","agrume","aubergine_fumée","tahini","citron"],"target_textures":["crémeux_avec_fibres_légères"],"signature_ingredients":["Aubergine fraîche","Tahini","Jus de citron frais","Ail cru"],"identity_guardrails":["aubergine_vraiment_fumée","tahini","citron","pas_de_purée_neutre"]}'::jsonb, 'myko_v3_sensory_contract')
