      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":3,"pungency":3,"richness":4,"freshness":2,"intensity":5},"dominant_flavors":["épices chaudes","aromatique","profond"],"aroma_families":["oignon_compoté","beurre","coriandre","fenugrec","ras_el_hanout","oignon","poulet"],"target_textures":["pain_imprégné","lentilles_tendres","poulet_fondant"],"signature_ingredients":["Cuisse de poulet crue, avec os, sans peau","Msemen cuit","Lentille brune sèche, crue","Oignon jaune cru"],"identity_guardrails":["msemen_déchiré","fenugrec","lentilles","poulet"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
