    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:REAL-153', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('13e92ecbe91adc7089a784465be7ac1b'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"spicy_umami","scores":{"sweet":1,"salty":4,"acidic":2,"bitter":1,"umami":5,"heat":5,"pungency":4,"richness":3,"freshness":2,"intensity":5},"dominant_flavors":["pimenté","fermenté","umami"],"aroma_families":["ail","tomate_cuite","piment","poisson","tomate","persil","huile_arachide"],"target_textures":["riz_imbibé","poisson_tendre","légumes_entiers"],"signature_ingredients":["Mérou cru entier","Riz brisé cru","Tomate concentrée","Carotte crue"],"identity_guardrails":["poisson_farcis_au_roff","riz_brisé","légumes_entiers"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
