     'aromate', false, 8);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Mariner le poulet avec citron, moutarde, ail et une partie des oignons.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Griller ou saisir fortement le poulet.');

