     jsonb_build_object('recipe_code', 'REAL-154', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:REAL-154', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('8eee5b6a0201ee722e9a50b94b53b93a'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"fresh_acidic","scores":{"sweet":1,"salty":3,"acidic":5,"bitter":1,"umami":2,"heat":1,"pungency":2,"richness":1,"freshness":5,"intensity":3},"dominant_flavors":["frais","acidulé","herbacé"],"aroma_families":["ail","oignon_compoté","moutarde","agrume","laurier","piment","citron","oignon"],"target_textures":["poulet_aux_bords_grillés","oignons_confits","sauce_acidulée"],"signature_ingredients":["Cuisse de poulet crue, avec os, sans peau","Oignon jaune cru","Jus de citron frais","Moutarde de Dijon"],"identity_guardrails":["beaucoup_d_oignons","citron_moutarde","grillade_préalable"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
