  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:REAL-169', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('b42871c6e333d953dadeb1a95105e778'::text), 'myko_v3_canonical_recipe'),
