      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":3,"pungency":3,"richness":4,"freshness":2,"intensity":5},"dominant_flavors":["épices chaudes","aromatique","profond"],"aroma_families":["oignon_compoté","piment","gingembre","cannelle","cardamome","piment_cachemire","fenouil","agneau"],"target_textures":["viande_fondante","sauce_rouge_nappante"],"signature_ingredients":["Épaule d’agneau crue","Yaourt nature","Oignon jaune cru","Piment du Cachemire moulu"],"identity_guardrails":["couleur_du_piment_non_tomate","fenouil","yaourt"]}'::jsonb, 'myko_v3_sensory_contract')
