    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:REAL-203', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('8a9397ec09ce4a5990aad26b09d660dc'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"brothy_umami","scores":{"sweet":1,"salty":4,"acidic":1,"bitter":1,"umami":5,"heat":1,"pungency":2,"richness":2,"freshness":3,"intensity":4},"dominant_flavors":["bouillon","umami","aromatique"],"aroma_families":["soja_fermenté","sésame_toasté","lap_cheong","shiitaké","soja","sésame"],"target_textures":["riz_tendre","croûte_croustillante","garnitures_juteuses"],"signature_ingredients":["Riz jasmin cru","Saucisse chinoise lap cheong","Poulet cru désossé","Shiitaké séché"],"identity_guardrails":["pot_en_terre","croûte_de_riz","garnitures_cuites_sur_riz"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
