  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:REAL-228', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('e9a4466fa39461490bdeb453c23ebb2d'::text), 'myko_v3_canonical_recipe'),
