    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:REAL-230', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('8e11e011ff1f2c8c6a91128e55d52033'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":4,"acidic":1,"bitter":1,"umami":4,"heat":1,"pungency":2,"richness":4,"freshness":2,"intensity":4},"dominant_flavors":["croustillant","salé","rôti"],"aroma_families":["oignon_compoté","soja_fermenté","sésame_toasté","sésame","soja","shiitaké","bœuf"],"target_textures":["nouilles_élastiques","légumes_distincts"],"signature_ingredients":["Nouille de patate douce sèche","Bœuf cru finement tranché","Épinard frais","Carotte crue"],"identity_guardrails":["cuissons_séparées","nouilles_translucides","huile_sésame"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
