  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:REAL-231', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('a0a05327f4110d67c12cb8a06c6c9840'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"spicy_umami","scores":{"sweet":1,"salty":4,"acidic":2,"bitter":1,"umami":5,"heat":5,"pungency":4,"richness":3,"freshness":2,"intensity":5},"dominant_flavors":["pimenté","fermenté","umami"],"aroma_families":["gochujang","anchois","poisson","sucre"],"target_textures":["tteok_très_moelleux_et_chewy","sauce_collante"],"signature_ingredients":["Gâteau de riz coréen tteok","Gochujang","Gochugaru","Bouillon d’anchois et algue"],"identity_guardrails":["gâteaux_de_riz","gochujang","sauce_épaisse"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
