  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:REAL-238', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('b6e2d1a25423926f3a11923cb7230d0d'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"fermented_pungent","scores":{"sweet":1,"salty":5,"acidic":4,"bitter":1,"umami":5,"heat":4,"pungency":5,"richness":3,"freshness":2,"intensity":5},"dominant_flavors":["fermenté","piquant","umami"],"aroma_families":["ail","gingembre","café","porc","doenjang","crevette_fermentée"],"target_textures":["porc_tendre_en_tranches","chou_croquant"],"signature_ingredients":["Poitrine de porc crue","Doenjang pâte de soja fermentée","Café moulu","Ail cru"],"identity_guardrails":["porc_bouilli_non_rôti","wraps_de_chou","sauces_fermentées"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
