      WHERE ff.canonical_name_normalized = 'sucre brun' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sucre brun', 20, 'g', 'optional',
     'équilibre', true, 7);

