  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:REAL-262', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('d990293c0978d4b9f9df873f570e6dda'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"smoky_sweet","scores":{"sweet":3,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":2,"pungency":2,"richness":4,"freshness":2,"intensity":5},"dominant_flavors":["fumé","caramélisé","savoureux"],"aroma_families":["ail","oignon_compoté","laurier","cannelle","porc","orange","graisse"],"target_textures":["extérieur_croustillant","intérieur_conf it"],"signature_ingredients":["Épaule de porc crue","Saindoux","Orange fraîche","Oignon blanc cru"],"identity_guardrails":["confit_puis_croustillage","épaule_de_porc","jus_réutilisé"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
