    ARRAY['ail','tomate_cuite','cumin','piment','cannelle','piments_secs','clou_girofle','bœuf']::text[], ARRAY['viande_effilochée','consommé_gélatineux']::text[],
    ARRAY['Paleron de bœuf cru','Jarret de bœuf cru avec os','Piment guajillo séché','Piment ancho séché']::text[], ARRAY['adobo_de_piments','viande_avec_os','consommé_servi']::text[],
