     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Moqueca baiana', NULL, ds.id, 'REAL-277',
    'Myko', 'editorial', 6, 35, 40, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '47adc90ec66efc5af6d6b78ad996add6',
    '{"sweet":1,"salty":3,"acidic":4,"bitter":0,"umami":3,"heat":2,"pungency":2,"richness":4,"freshness":3,"intensity":4}'::jsonb, ARRAY['acidulé','crémeux','épices']::text[],
    ARRAY['ail','oignon_compoté','tomate_cuite','agrume','coriandre','coco','dendê','citron_vert']::text[], ARRAY['poisson_entier_non_défait','sauce_crémeuse','légumes_tendres']::text[],
    ARRAY['Filet de poisson blanc ferme cru','Crevette crue décortiquée','Lait de coco','Huile de dendê']::text[], ARRAY['huile_de_dendê','coco','cuisson_en_couches','coriandre']::text[],
    ARRAY['marinade','montage en couches','cuisson étouffée']::text[], ARRAY[]::text[], ARRAY['crustacés','lait','poisson']::text[],
    '3 jours au réfrigérateur.', '{"fridge_hours":72,"eat_immediately":false,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
