  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'La veille, mettre les haricots noirs à tremper dans trois fois leur volume d''eau froide, à température ambiante. Un haricot noir non trempé demande le double de cuisson et sa peau éclate bien avant que le cœur ne devienne crémeux. Le lendemain, jeter l''eau de trempage, qui a pris l''amertume des peaux, et rincer les haricots à l''eau claire.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Poser le bœuf en un seul morceau dans une grande casserole, le couvrir largement d''eau froide, ajouter une feuille de laurier, un des oignons coupé en deux et une pointe de sel. Porter à frémissement et laisser pocher une heure et demie à deux heures, la surface tremblante et jamais bouillonnante. Si l''on prend du jarret plutôt que de la macreuse, compter environ 1,4 kg avec l''os pour obtenir le kilo de chair annoncé. Laisser tiédir la viande dans son bouillon : refroidie à sec, elle se rétracte et refuse de s''effilocher.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pendant ce temps, couvrir les haricots d''eau froide non salée, ajouter la seconde feuille de laurier, un quart des oignons émincés, deux gousses d''ail écrasées et un filet d''huile. Cuire une heure à une heure et quart à petit feu et ne saler que les dix dernières minutes : le sel précoce durcit la peau et le haricot reste ferme sous la dent quelle que soit la durée. Ils sont prêts quand la fourchette les écrase sans effort ; garder un peu de leur jus de cuisson, il fait toute la liaison.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Effiler la viande tiède à la main, dans le sens de la fibre, en filaments et non en cubes — c''est cet effilochage qui donne son nom à la carne mechada. Faire suer le reste des oignons et les poivrons rouges taillés en fines lanières dans deux cuillerées d''huile, dix minutes à feu moyen, puis ajouter l''ail haché et le cumin. Verser les tomates pelées écrasées à la main avec leur jus, laisser réduire un quart d''heure, puis incorporer les filaments de bœuf et deux louches du bouillon de pochage. Poursuivre vingt minutes à découvert : la sauce doit napper la viande, pas baigner autour d''elle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Rincer le riz à l''eau froide jusqu''à ce qu''elle ressorte claire, puis le faire nacrer une minute dans un filet d''huile avec une pincée de sel. Mouiller d''une fois et demie son volume d''eau bouillante, couvrir et cuire quinze minutes sans jamais soulever le couvercle — chaque coup d''œil coûte de la vapeur et laisse le dessus cru. Laisser reposer cinq minutes hors du feu avant de l''égrener à la fourchette : le riz du pabellón se sert blanc et détaché, il fait le fond neutre sur lequel les trois autres éléments se lisent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Choisir des plantains dont la peau est noircie par plaques ; verts, ils sont farineux et ne caramélisent pas. Les éplucher — compter environ 1,1 kg avec la peau pour les 800 g de chair déclarés — et les trancher en biais, en lames d''un centimètre. Les frire dans le reste de l''huile bien chaude, deux à trois minutes par face, jusqu''à ce que les bords brunissent et que le cœur devienne moelleux. Les égoutter sur du papier et les saler à la sortie, jamais avant : le sel fait perler l''eau et l''huile crache.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Dresser chaque assiette en quartiers distincts et non mélangés : le riz blanc, les haricots noirs avec un peu de leur jus, la viande effilochée en sauce, les tranches de plantain rangées en éventail sur le bord. Le plat tire son nom de ce drapeau — c''est l''assemblage qui fait le pabellón, et tout brasser en ferait une autre préparation.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Parsemer le persil ciselé sur la viande, donner un tour de moulin à poivre et rectifier le sel élément par élément plutôt qu''à l''ensemble : chacun arrive séparément en bouche et doit être juste pour lui-même. Servir aussitôt, tant que les plantains croustillent encore sur les bords et que le riz est chaud.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'REAL-287', 'recipe_family', 'Pabellón criollo',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'REAL-287', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Version végétale : le bœuf effiloché remplacé par 400 g de fruit du jacquier en saumure égoutté, effiloché de même, relevé de paprika fumé, de piment en poudre et de sauce sriracha (chefsimon)','Câpres égouttées ajoutées à la viande en sauce (marmiton)','Un poireau émincé dans le sofrito, avec les oignons (marmiton)','Riz safrané plutôt que blanc, cuit avec une pointe de safran et une noix de beurre (marmiton)','Bœuf poché au bouillon cube plutôt qu''à l''eau aromatisée, deux cubes pour six (marmiton)','Plantains poudrés d''un voile de fécule avant friture, pour une croûte plus sèche (chefsimon)','Une pincée de cumin sur les plantains à la sortie du bain de friture (chefsimon)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"REAL-287","variants":["Version végétale : le bœuf effiloché remplacé par 400 g de fruit du jacquier en saumure égoutté, effiloché de même, relevé de paprika fumé, de piment en poudre et de sauce sriracha (chefsimon)","Câpres égouttées ajoutées à la viande en sauce (marmiton)","Un poireau émincé dans le sofrito, avec les oignons (marmiton)","Riz safrané plutôt que blanc, cuit avec une pointe de safran et une noix de beurre (marmiton)","Bœuf poché au bouillon cube plutôt qu''à l''eau aromatisée, deux cubes pour six (marmiton)","Plantains poudrés d''un voile de fécule avant friture, pour une croûte plus sèche (chefsimon)","Une pincée de cumin sur les plantains à la sortie du bain de friture (chefsimon)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:REAL-287', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('8e8f8ab1283b1ea19dfbed82c36d9474'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":3,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":1,"pungency":2,"richness":3,"freshness":2,"intensity":4},"dominant_flavors":["bœuf effiloché","tomate et poivron confits","haricot noir","plantain caramélisé"],"aroma_families":["sofrito","oignon compoté","tomate cuite","cumin","banane frite"],"target_textures":["filaments de viande en sauce courte","haricots crémeux","riz détaché","plantain fondant à bords croustillants"],"signature_ingredients":["Bœuf à braiser cru","Haricot noir sec","Riz long blanc cru","Banane plantain mûre"],"identity_guardrails":["Quatre éléments dressés séparément — riz, haricots noirs, bœuf effiloché, plantain frit : mélangés en un seul appareil, ce n''est plus un pabellón","Le bœuf se poche puis s''effiloche à la main ; du bœuf haché ou taillé en cubes ne fait pas la carne mechada","Les plantains doivent être mûrs à peau noircie : verts et farineux, ils ne donnent pas le sucre qui répond aux haricots","Aucun autre haricot ne remplace le haricot noir dans ce plat, c''est lui qui fait le noir du drapeau","Le riz reste blanc et neutre, sans sofrito ni tomate : il sépare les trois autres éléments au lieu de se mêler à eux"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Jerk chicken', 'jerk chicken', 'Jamaïque', 'Jamaïque',
     'meal', 'poulet grillé épicé', 'named_traditional_dish', 'spicy_umami',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Jerk chicken', 'Poulet en morceaux marinés dans un mélange de piment scotch bonnet, piment de la Jamaïque et thym, grillé', ds.id, 'REAL-288',
    'Myko', 'editorial', 8, 35, 60, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '159f9e139e51368761072f16e6f2f718',
    '{"sweet":1,"salty":4,"acidic":2,"bitter":1,"umami":5,"heat":5,"pungency":4,"richness":3,"freshness":2,"intensity":5}'::jsonb, ARRAY['pimenté','fermenté','umami']::text[],
    ARRAY['ail','agrume','thym','piment','gingembre','soja_fermenté','fumé','allspice']::text[], ARRAY['peau_noircie','chair_juteuse']::text[],
    ARRAY['Poulet entier cru en morceaux','Piment scotch bonnet','Piment de la Jamaïque en grains','Thym frais']::text[], ARRAY['scotch_bonnet','allspice','thym','fumée','marinade_longue']::text[],
    ARRAY['mixage','marinade','grillade fumée','repos']::text[], ARRAY[]::text[], ARRAY['soja']::text[],
    '3 jours au réfrigérateur.', '{"fridge_hours":72,"eat_immediately":false,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
