      WHERE ff.canonical_name_normalized = 'poulet entier cru en morceaux' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poulet entier cru en morceaux', 1800, 'g', 'required',
     'viande', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
