    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Servi avec des galuska, pâte de farine et d''œufs battus à l''eau salée puis pochée en petits morceaux, comptée à part du ragoût (marmiton, deux versions sur quatre)','Version soupe : viande taillée plus menue, mouillement doublé, carotte et poivron vert ajoutés, une cuillerée de crème fraîche au service (marmiton)','Une demi-cuillerée à café de paprika fort en plus du doux, pour six (marmiton)','Marjolaine séchée mêlée au cumin, à parts égales (marmiton)','À la mijoteuse : 300 g de lard fumé taillé épais, du double concentré de tomate à la place des tomates fraîches, et une liaison farine-fécule de maïs en fin de cuisson (chefsimon)','Finition à la crème fraîche semi-épaisse, 20 cl versés dans la cocotte (chefsimon)','Panachage des poivrons, un rouge et un vert (marmiton)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"REAL-295","variants":["Servi avec des galuska, pâte de farine et d''œufs battus à l''eau salée puis pochée en petits morceaux, comptée à part du ragoût (marmiton, deux versions sur quatre)","Version soupe : viande taillée plus menue, mouillement doublé, carotte et poivron vert ajoutés, une cuillerée de crème fraîche au service (marmiton)","Une demi-cuillerée à café de paprika fort en plus du doux, pour six (marmiton)","Marjolaine séchée mêlée au cumin, à parts égales (marmiton)","À la mijoteuse : 300 g de lard fumé taillé épais, du double concentré de tomate à la place des tomates fraîches, et une liaison farine-fécule de maïs en fin de cuisson (chefsimon)","Finition à la crème fraîche semi-épaisse, 20 cl versés dans la cocotte (chefsimon)","Panachage des poivrons, un rouge et un vert (marmiton)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:REAL-295', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('b75b998965bea176d792b839963257c4'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":2,"pungency":2,"richness":4,"freshness":1,"intensity":4},"dominant_flavors":["paprika doux","oignon fondu","bœuf braisé","tomate cuite"],"aroma_families":["paprika","oignon compoté","bœuf mijoté","tomate cuite"],"target_textures":["viande fondante","pomme de terre juste tenue","bouillon rouge lié"],"signature_ingredients":["Bœuf à braiser cru","Paprika doux","Oignon jaune cru"],"identity_guardrails":["Sans paprika doux en quantité — 15 g pour huit, ajoutés hors du feu — ce n''est qu''un ragoût de bœuf : la couleur et le parfum du plat ne viennent de rien d''autre","L''oignon se compte en centaines de grammes, un tiers du poids de la viande, et c''est lui qui lie la sauce","Le paprika brûlé rend le plat amer et rien ne le rattrape : il n''entre jamais sur le feu","Une liaison à la farine ou une base de crème en feraient un paprikás, pas un goulash","Le bouillon reste franchement liquide : la sauce nappe à peine, elle ne se réduit pas en sauce brune"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Chicken paprikash', 'chicken paprikash', 'Hongrie', 'Hongrie',
     'meal', 'poulet au paprika', 'named_traditional_dish', 'tangy_creamy',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Chicken paprikash', 'Cuisses de poulet cuites avec des oignons dans une sauce paprika doux hongrois liée à la crème aigre', ds.id, 'REAL-296',
    'Myko', 'editorial', 6, 25, 70, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '7c5df34f3098bc2a7240778faabf24fa',
    '{"sweet":1,"salty":3,"acidic":4,"bitter":0,"umami":3,"heat":2,"pungency":2,"richness":4,"freshness":3,"intensity":4}'::jsonb, ARRAY['acidulé','crémeux','épices']::text[],
    ARRAY['ail','oignon_compoté','lacté','paprika','crème_aigre','oignon','poulet']::text[], ARRAY['poulet_fondant','sauce_lisse_acidulée']::text[],
    ARRAY['Cuisse de poulet crue, avec os, avec peau','Oignon jaune cru','Paprika doux hongrois','Crème aigre']::text[], ARRAY['paprika_non_brûlé','crème_aigre_tempérée','cuisses_avec_os']::text[],
    ARRAY['saisie','fondue','liaison crème aigre']::text[], ARRAY[]::text[], ARRAY['gluten','lait']::text[],
    '3 jours au réfrigérateur.', '{"fridge_hours":72,"eat_immediately":false,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
