  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Dans la même sauteuse, faire suer le reste d’oignon ciselé et l’ail, ajouter les champignons émincés et les laisser rendre puis reprendre leur eau, 6 à 7 minutes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
