    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'PROT-006', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:PROT-006', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('6b1ef84e1b269ab79c8f1399e44335aa'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"earthy_herbal","scores":{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":1,"pungency":3,"richness":2,"freshness":3,"intensity":3},"dominant_flavors":["moutarde","lentille terreuse","estragon"],"aroma_families":["moutarde","vin_blanc_reduit","champignon_terreux","estragon","oignon_compoté"],"target_textures":["médaillon_nacré","lentille_ferme","haricot_croquant"],"signature_ingredients":["moutarde de Dijon","estragon","lentille verte"],"identity_guardrails":["moutarde_ajoutee_hors_du_feu","pas_de_creme","lentilles_non_ecrasees"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
