    ARRAY['saisie à sec','déglaçage','braisage','cuisson des légumineuses dans le braisage','liaison à la moutarde hors du feu']::text[], ARRAY['Lentilles corail à la place des vertes pour une texture plus liée','Chou frisé à la place des épinards','Version cocotte-minute : 45 min sous pression puis 15 min lentilles']::text[], ARRAY['moutarde']::text[],
    '4 jours au réfrigérateur ; 3 mois au congélateur sans les épinards (les ajouter au réchauffage). Meilleur le lendemain, le jus prend en gelée grâce au collagène du jarret.', '{"fridge_hours":96,"eat_immediately":false,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
