    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Sans farce, en pot-au-feu de volaille','Avec chou vert blanchi à part']::text[]) AS variant(name);

