  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-005', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('b33bf100263d6db058c77e5ab0d06735'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":1,"salty":3,"acidic":1,"bitter":0,"umami":1,"heat":3,"pungency":0,"richness":2,"freshness":4,"intensity":1},"dominant_flavors":["tomate_cuite","veau_moelleux","champignon"],"aroma_families":["tomate_cuite","oignon_compoté","vin_blanc"],"target_textures":["chair_moelleuse","sauce_nappante","champignon_fondant"],"signature_ingredients":["Escalope de veau crue fine","Tomate fraîche mûre","Champignon de Paris frais"],"identity_guardrails":["La paupiette est roulée et ficelée : sans farce à l''intérieur, ce n''est qu''une escalope roulée.","Vingt minutes de mijotage suffisent — au-delà le veau se dessèche."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
