  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Blanquette de dinde', 'Escalopes de dinde pochées dans un bouillon avec carottes, champignons et poireau, liées à la crème', ds.id, 'SRC-008',
    'Myko', 'editorial', 4, 25, 60, 'facile',
    NULL, NULL,
    'B', 'candidate', 'ab0b819ba6786d70aaab24d6479ea10f',
    '{"sweet":2,"salty":3,"acidic":1,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['volaille','crème','champignon']::text[],
    ARRAY['lacté','herbacé','aillé']::text[], ARRAY['sauce nappante','viande fondante','légumes tendres']::text[],
    ARRAY['Escalope de dinde crue','Crème fraîche liquide entière','Champignon de Paris frais']::text[], ARRAY['La viande ne doit pas colorer : une dinde saisie brune donne un sauté en sauce brune, plus une blanquette.','Sans liaison crémée blanche (crème et farine), il ne reste qu''un bouillon de volaille aux légumes.','Pas de tomate ni de concentré de tomates : la sauce doit rester ivoire.','La crème s''incorpore hors ébullition, sinon elle tranche et la texture nappante est perdue.']::text[],
    ARRAY['mijotage','déglaçage','réduction']::text[], ARRAY['Version aux poireaux dominants : doubler le poireau et réduire la carotte de moitié, pour une blanquette plus douce et plus verte.','Cuisson accélérée en autocuiseur : 25 minutes sous pression après le déglaçage, crème et liaison ajoutées seulement à l''ouverture.','Version allégée sans crème : remplacer la crème par un supplément de bouillon lié à la fécule de maïs.','Blanquette au four : transvaser après le mouillement dans une cocotte fermée et laisser confire à 150 °C pendant 1 h 30.']::text[], ARRAY['gluten','lait','sulfites']::text[],
    'Se garde 3 jours au réfrigérateur à 4 °C dans un contenant hermétique ; réchauffer à feu doux sans laisser bouillir pour que la sauce ne tranche pas. La congélation tient 2 mois mais uniquement sur la base non crémée (viande, légumes, bouillon lié) : la crème se rajoute après décongélation, sinon la sauce grène au réchauffage.', '{"fridge_hours":72,"eat_immediately":false,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
