  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Détailler la dinde en cubes d''environ 4 cm. Émincer l''oignon, couper les carottes en rondelles épaisses, fendre le poireau dans la longueur, le rincer et le tronçonner. Dégermer et hacher l''ail. Brosser les champignons et les partager en quartiers.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire chauffer l''huile d''olive avec la moitié du beurre dans une cocotte à fond épais. Y déposer les cubes de dinde et les remuer sur feu moyen : ils doivent seulement blanchir et raidir, sans jamais prendre de couleur. Assaisonner de sel et de poivre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Ajouter l''oignon et l''ail, poursuivre deux à trois minutes toujours sans coloration, puis poudrer de farine. Remuer une minute pleine pour que la farine perde son goût cru et enrobe la viande.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser le vin blanc en grattant le fond à la spatule, laisser l''alcool s''évaporer une minute. Mouiller avec le bouillon et l''eau, ajouter le thym, les carottes et les poireaux, puis amener doucement au frémissement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Couvrir et laisser mijoter à tout petits bouillons environ 45 minutes, en remuant de loin en loin et en rallongeant d''un filet d''eau si le niveau descend sous les légumes. La dinde doit se défaire sous la fourchette.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Pendant ce temps, saisir les champignons dans le beurre restant à feu vif jusqu''à ce que leur eau se soit évaporée et qu''ils brillent. Les verser dans la cocotte pour les dix dernières minutes de cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Couper le feu, attendre que le bouillonnement cesse puis incorporer la crème. Si la sauce reste trop fluide, délayer la fécule dans deux cuillères de jus refroidi, l''ajouter et laisser épaissir deux minutes sans jamais faire bouillir. Rectifier l''assaisonnement et parsemer de persil ciselé au moment de servir.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-008', 'recipe_family', 'Blanquette de dinde',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-008', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Version aux poireaux dominants : doubler le poireau et réduire la carotte de moitié, pour une blanquette plus douce et plus verte.','Cuisson accélérée en autocuiseur : 25 minutes sous pression après le déglaçage, crème et liaison ajoutées seulement à l''ouverture.','Version allégée sans crème : remplacer la crème par un supplément de bouillon lié à la fécule de maïs.','Blanquette au four : transvaser après le mouillement dans une cocotte fermée et laisser confire à 150 °C pendant 1 h 30.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-008","variants":["Version aux poireaux dominants : doubler le poireau et réduire la carotte de moitié, pour une blanquette plus douce et plus verte.","Cuisson accélérée en autocuiseur : 25 minutes sous pression après le déglaçage, crème et liaison ajoutées seulement à l''ouverture.","Version allégée sans crème : remplacer la crème par un supplément de bouillon lié à la fécule de maïs.","Blanquette au four : transvaser après le mouillement dans une cocotte fermée et laisser confire à 150 °C pendant 1 h 30."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-008', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('ab0b819ba6786d70aaab24d6479ea10f'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":2,"salty":3,"acidic":1,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["volaille","crème","champignon"],"aroma_families":["lacté","herbacé","aillé"],"target_textures":["sauce nappante","viande fondante","légumes tendres"],"signature_ingredients":["Escalope de dinde crue","Crème fraîche liquide entière","Champignon de Paris frais"],"identity_guardrails":["La viande ne doit pas colorer : une dinde saisie brune donne un sauté en sauce brune, plus une blanquette.","Sans liaison crémée blanche (crème et farine), il ne reste qu''un bouillon de volaille aux légumes.","Pas de tomate ni de concentré de tomates : la sauce doit rester ivoire.","La crème s''incorpore hors ébullition, sinon elle tranche et la texture nappante est perdue."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Bouchées à la reine', 'bouchees a la reine', 'France', 'France',
     'meal', 'plat mijoté', 'named_traditional_dish', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Bouchées à la reine', 'Bouchées feuilletées garnies d''une fricassée de poulet et veau dans une sauce liée avec champignons', ds.id, 'SRC-009',
    'Myko', 'editorial', 6, 30, 90, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'e6094bbad33ad9a5beb84cec1ef8b469',
    '{"sweet":1,"salty":3,"acidic":1,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":3}'::jsonb, ARRAY['volaille','champignon','crème','vin blanc']::text[],
    ARRAY['beurré','lacté','épicé doux','champignon']::text[], ARRAY['sauce nappante','viande fondante','lamelles de champignon tendres']::text[],
    ARRAY['Champignon de Paris frais','Escalope de veau crue fine','Bouillon de volaille','Jaune d''œuf cru']::text[], ARRAY['Sans la liaison finale au Jaune d''œuf cru et à la Crème fraîche liquide entière, le velouté retombe au rang de simple béchamel et le plat perd son caractère de sauce à la reine.','Retirer le Champignon de Paris frais ou la volaille pochée vide la garniture de sa substance : ce sont les deux éléments présents dans presque toutes les sources du dossier.','Le bouillon de volaille doit être celui du pochage des viandes, pas de l''eau salée : c''est lui qui porte tout l''umami de la sauce.','La sauce ne doit jamais bouillir après l''ajout des jaunes, sous peine de grainer irrémédiablement.']::text[],
    ARRAY['pochage','mijotage','réduction','liaison']::text[], ARRAY['Version aux fruits de mer inspirée de chefsimon.com : remplacer les viandes par du Pavé de saumon cru, sans peau taillé en cubes et poché 3 minutes dans le velouté en fin de cuisson, avec un zeste de citron et un peu d''estragon dans la sauce.','Version alsacienne de fête : augmenter la part de viandes, ajouter des quenelles coupées en tronçons au moment de réunir la garniture, et servir avec des spätzle.','Version apéritive d''après 750g.com : garnir des mini-bouchées de champignons de Paris crémés, parsemer de fromage râpé et gratiner 8 à 15 minutes à 170 °C.','Version express : sauter les viandes déjà cuites au lieu de les pocher et monter le velouté directement sur du bouillon de volaille reconstitué, en 20 minutes chrono.']::text[], ARRAY['gluten','lait','œuf','sulfites']::text[],
    'Se garde 2 jours au réfrigérateur à 4 °C dans une boîte hermétique, la garniture bien refroidie avant fermeture. Réchauffer à feu très doux ou au bain-marie en remuant, sans jamais laisser frémir. La congélation est déconseillée : la liaison jaune d''œuf et crème tranche à la décongélation et les champignons relâchent leur eau.', '{"fridge_hours":48,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
