  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Faire tiedir 20 g de beurre doux a feu tres bas jusqu''a ce qu''il soit liquide mais encore blond, puis en badigeonner au pinceau une seule face de chacune des huit tranches de pain de mie.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Poser quatre tranches face beurree contre le plan de travail, repartir dessus la moitie de l''emmental rape, ajouter une tranche de jambon blanc cuit repliee pour epouser exactement le format du pain, puis saler et poivrer legerement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Recouvrir du reste d''emmental rape, refermer avec les quatre tranches restantes face beurree vers le haut et tasser d''un coup de paume pour que les couches adherent entre elles.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Chauffer une grande poele a feu moyen avec les 10 g de beurre doux restants, y coucher les croques et les laisser prendre couleur environ trois minutes par face, en pressant a la spatule pour que la chaleur atteigne le coeur et fasse fondre le fromage.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Transferer les croques sur une plaque, les couvrir de gruyere rape et les glisser deux minutes sous le gril du four, juste le temps que la surface prenne une croute doree sans que le pain ne noircisse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Pendant ce temps, baisser le feu sous la poele encore grasse, y casser les quatre oeufs, assaisonner de sel fin et de poivre noir moulu, puis couvrir une minute pour que le blanc se fige alors que le jaune reste liquide.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Deposer un oeuf au plat sur chaque croque, ebarber les bords du blanc si besoin et servir aussitot, tant que le jaune coule encore a l''entaille.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-011', 'recipe_family', 'Croque-madame',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-011', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Version integralement au four : monter les croques beurres, enfourner a 210 degres pendant quinze minutes, puis coiffer chacun d''un oeuf au plat cuit a part.','Version a l''oeuf encastre : decouper un disque au centre de la tranche superieure avant cuisson, retourner le croque a mi-cuisson et casser l''oeuf directement dans l''ouverture.','Version jaune ferme : prolonger la cuisson de l''oeuf de deux minutes a couvert, pour un croque qui se mange a la main sans couler.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-011","variants":["Version integralement au four : monter les croques beurres, enfourner a 210 degres pendant quinze minutes, puis coiffer chacun d''un oeuf au plat cuit a part.","Version a l''oeuf encastre : decouper un disque au centre de la tranche superieure avant cuisson, retourner le croque a mi-cuisson et casser l''oeuf directement dans l''ouverture.","Version jaune ferme : prolonger la cuisson de l''oeuf de deux minutes a couvert, pour un croque qui se mange a la main sans couler."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-011', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('90e32e269593a097bb24e18d678949dc'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":4,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":0,"intensity":3},"dominant_flavors":["fromage fondu","jambon sale","beurre dore"],"aroma_families":["lactee","grillee","beurree"],"target_textures":["pain grille croustillant","coeur fondant","jaune coulant"],"signature_ingredients":["Pain de mie","Œuf cru","Jambon blanc cuit","Emmental râpé"],"identity_guardrails":["Sans l''oeuf pose sur le dessus, le plat redevient un croque-monsieur et perd son nom.","Le pain de mie est la seule enveloppe admise : remplace par une baguette ou un pain de campagne, ce n''est plus un croque.","Le couple jambon blanc cuit et fromage fondu forme le coeur du plat ; retirer l''un des deux le denature."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Gratin de brocolis', 'gratin de brocolis', 'France', 'France',
     'meal', 'gratin de légumes', 'domestic_standard', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Gratin de brocolis', 'Bouquets de brocolis blanchis nappés d''une sauce béchamel crémeuse, gratinés au four', ds.id, 'SRC-012',
    'Myko', 'editorial', 4, 25, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', '641f0188646a2d4a60d3a374eba3f5fe',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":2,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['lacté','fromagé','végétal vert']::text[],
    ARRAY['lacté','alliacé','épicé doux']::text[], ARRAY['fondant','croûte gratinée croustillante','appareil pris']::text[],
    ARRAY['Brocoli cru','Lait entier','Gruyère râpé']::text[], ARRAY['Sans brocoli, le plat n''existe plus : c''est lui qui donne le nom, la couleur et la légère amertume végétale du gratin.','Sans liaison lactée à base de lait entier et de farine, on obtient des bouquets gratinés et non un gratin : la béchamel est ce qui lie le légume.','Sans couverture de gruyère râpé et de chapelure, il manque la croûte dorée qui définit le gratinage.','Le brocoli doit rester ferme et bien égoutté : trop cuit ou détrempé, il délave la sauce et fait rendre de l''eau au plat.']::text[],
    ARRAY['blanchiment','gratinage','réduction']::text[], ARRAY['Version végétarienne : retirer le jambon blanc cuit et compenser en portant le gruyère râpé à 120 g pour garder du corps à l''appareil.','Version allégée : supprimer la crème fraîche liquide entière et compléter avec 150 ml de lait entier supplémentaire, quitte à cuire la béchamel deux minutes de plus.','Croûte renforcée : doubler la chapelure de blé et l''arroser d''un filet d''huile d''olive vierge extra avant d''enfourner.','Sans œuf : omettre l''œuf cru et augmenter la farine de blé T55 à 50 g, ce qui donne un gratin plus coulant et moins compact.']::text[], ARRAY['gluten','lait','œuf']::text[],
    'Se conserve 3 jours au réfrigérateur entre 0 et 4 °C, dans le plat filmé ou en boîte hermétique une fois refroidi à cœur. Réchauffer 15 à 20 minutes à 160 °C plutôt qu''au micro-ondes, pour retrouver la croûte. La congélation est déconseillée : l''appareil aux œufs et à la crème se dissocie en rendant de l''eau à la décongélation et le brocoli devient filandreux ; si on y tient, congeler avant cuisson au four, jusqu''à 1 mois à -18 °C, et enfourner sans décongeler en ajoutant 20 minutes.', '{"fridge_hours":72,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

