  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'La veille, installer la langue dans un grand récipient, la noyer sous l''eau froide additionnée d''un tiers du vinaigre blanc, puis la laisser dégorger au réfrigérateur une nuit entière en renouvelant l''eau une ou deux fois.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Le lendemain, jeter l''eau de trempage, rincer la pièce et la remettre dans une cocotte sous une hauteur d''eau froide propre. Porter à frémissement et compter un quart d''heure, en retirant l''écume grise qui remonte, puis égoutter et rincer de nouveau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Piquer l''oignon jaune épluché des clous de girofle. Replacer la langue dans la cocotte avec cet oignon, la carotte pelée coupée en gros tronçons, le laurier, le thym, les grains de poivre et le bouillon de bœuf émietté. Recouvrir largement d''eau chaude.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Maintenir un frémissement discret, couvercle entrouvert, pendant deux heures à deux heures trente : la lame d''un couteau doit traverser la partie la plus épaisse sans résistance. Laisser tiédir la pièce dans son bouillon pour qu''elle reste moelleuse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Sortir la langue encore chaude, la poser côté bombé contre la planche et retirer la membrane épaisse, qui se décolle alors sans effort. Parer la base, réserver au chaud. Filtrer un litre de bouillon de cuisson et le garder frémissant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Pour la sauce, fondre le beurre doux dans une casserole à fond épais, y faire suer les échalotes ciselées sans qu''elles prennent couleur, puis mouiller avec le vin blanc et le reste du vinaigre blanc. Laisser réduire jusqu''à ce qu''il ne subsiste qu''un fond sirupeux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Pluvioriser la farine sur les échalotes, remuer deux minutes à feu doux pour cuire le roux, incorporer le concentré de tomate, puis verser le bouillon filtré louche après louche en fouettant. Laisser épaissir vingt minutes à petit feu, en remuant régulièrement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Hors du bouillonnement, ajouter les cornichons taillés en fines rondelles pour qu''ils gardent leur mordant, rectifier en sel fin et poivre noir moulu, puis parsemer de persil haché.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Détailler la langue en tranches d''un demi-centimètre, les ranger en éventail dans un plat chaud et les napper généreusement de sauce piquante ; servir le reste de sauce à part en saucière.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-013', 'recipe_family', 'Langue de boeuf sauce piquante',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-013', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Remplacer le vinaigre blanc de la sauce par du vinaigre de vin rouge, pour une acidité plus ronde et une couleur plus soutenue.','Version tomatée du Sud : doubler le concentré de tomate, ajouter une pointe de piment et servir la sauce plus courte, sans roux.','Cuisson accélérée en autocuiseur : quarante-cinq minutes sous pression après le blanchiment, le bouillon restant utilisé de la même façon pour la sauce.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-013","variants":["Remplacer le vinaigre blanc de la sauce par du vinaigre de vin rouge, pour une acidité plus ronde et une couleur plus soutenue.","Version tomatée du Sud : doubler le concentré de tomate, ajouter une pointe de piment et servir la sauce plus courte, sans roux.","Cuisson accélérée en autocuiseur : quarante-cinq minutes sous pression après le blanchiment, le bouillon restant utilisé de la même façon pour la sauce."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-013', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('46686993371eb19b25a76e3f71b78ec8'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"bright_acidic","scores":{"sweet":1,"salty":3,"acidic":4,"bitter":1,"umami":4,"heat":0,"pungency":3,"richness":3,"freshness":2,"intensity":4},"dominant_flavors":["acidité vinaigrée","umami de bouillon de bœuf","cornichon saumuré","aromates de court-bouillon"],"aroma_families":["vinaigré","épices chaudes","herbacé"],"target_textures":["viande fondante","sauce nappante","éclats croquants de cornichon"],"signature_ingredients":["Langue de bœuf crue","Cornichon au vinaigre","Vinaigre blanc"],"identity_guardrails":["Sans langue de bœuf pochée puis pelée, le plat n''existe plus : aucune autre pièce de bœuf ne peut s''y substituer.","Sans l''acidité conjointe du vinaigre réduit et des cornichons, la sauce n''est plus piquante mais une simple sauce brune.","La sauce doit être liée au roux avec le bouillon de cuisson de la langue, et non avec un fond étranger : c''est ce recyclage qui fait sa profondeur."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Lentilles en salade tiède', 'lentilles en salade tiede', 'France', 'France',
     'meal', 'salade tiède', 'domestic_standard', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Lentilles en salade tiède', 'Lentilles corail tièdes avec œuf poché, carottes, poireau et vinaigrette à l''huile d''olive', ds.id, 'SRC-014',
    'Myko', 'editorial', 4, 20, 25, 'facile',
    NULL, NULL,
    'B', 'candidate', 'a4d866a621c3cb26b185923da1d7ba95',
    '{"sweet":1,"salty":2,"acidic":3,"bitter":1,"umami":2,"heat":0,"pungency":3,"richness":3,"freshness":3,"intensity":3}'::jsonb, ARRAY['terreux','acidulé','herbacé','alliacé']::text[],
    ARRAY['herbacé','aromates séchés','alliacé']::text[], ARRAY['lentilles fondantes mais entières','jaune d''œuf coulant','éclats de noix croquants','oignon cru croquant']::text[],
    ARRAY['Lentille corail sèche, crue','Huile d''olive vierge extra','Vinaigre de vin rouge','Persil frais']::text[], ARRAY['Les lentilles doivent être assaisonnées encore tièdes : une fois froides elles n''absorbent plus la vinaigrette et le plat bascule en salade froide banale.','L''eau de cuisson reste non salée jusqu''à la fin, sinon la peau durcit et le grain ne s''attendrit plus uniformément.','La garniture aromatique carotte-poireau-oignon cuite avec la légumineuse et le duo thym-laurier constituent la base commune à toutes les sources : les retirer viderait le plat de son fond de goût.','La vinaigrette doit rester une émulsion huile d''olive et vinaigre franchement acide ; adoucie ou crémée, le contraste avec la lentille disparaît.']::text[],
    ARRAY['mijotage','pochage','émulsion']::text[], ARRAY['Remplacer l''œuf mollet par des lardons rissolés jusqu''au croustillant, égouttés de leur gras et parsemés tièdes sur les lentilles.','Version plus copieuse : effilocher un jambonneau cuit à l''eau pendant une heure avec oignon et carotte, et l''incorporer aux lentilles avant la vinaigrette.','Substituer le vinaigre de vin rouge par du vinaigre de cidre, plus doux, en augmentant légèrement la dose.','Ajouter des dés de patate douce rôtis au four et des dés de betterave cuite pour une salade plus sucrée et plus colorée.','Faire fondre le poireau à la poêle avec un peu d''huile et de thym au lieu de le cuire avec les lentilles, pour un goût plus confit.','Troquer les noix contre des noisettes torréfiées à sec.']::text[], ARRAY['œuf','fruits à coque','sulfites']::text[],
    'Se garde 3 jours au réfrigérateur entre 0 et 4 °C en boîte hermétique, vinaigrette déjà incorporée. Sortir 30 minutes avant le service ou réchauffer 1 minute à la poêle à feu doux pour retrouver la tiédeur. Les œufs mollets ne se conservent pas plus de 24 h et se posent au dernier moment. Congélation à proscrire : la lentille corail se délite en purée à la décongélation et les herbes fraîches noircissent.', '{"fridge_hours":72,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":false,"source":"manual"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

