  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Rincer les lentilles sous l''eau froide dans une passoire fine jusqu''à ce que l''eau ressorte claire. Peler la carotte et la tailler en rondelles de 3 mm, fendre le poireau et le débiter en fines demi-rondelles après l''avoir bien lavé. Peler l''oignon et le couper en deux : une moitié partira entière à la cuisson, l''autre sera émincée crue au dernier moment.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Réunir dans une casserole les lentilles, la carotte, le poireau, la demi-moitié d''oignon entière, le laurier et le thym. Recouvrir de deux fois leur volume d''eau froide, sans sel : une eau salée dès le départ durcit la peau de la légumineuse et l''empêche de s''attendrir régulièrement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Monter doucement jusqu''au frémissement, puis baisser le feu au minimum et laisser cuire à découvert 12 à 15 minutes. La lentille corail se défait beaucoup plus vite que la verte : goûter dès la dixième minute et couper le feu à l''instant où le grain cède sous la dent tout en restant entier.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Saler seulement à ce moment-là, puis égoutter immédiatement et sans rincer pour stopper la cuisson. Retirer la moitié d''oignon et la feuille de laurier, garder carotte et poireau. Étaler le tout dans un saladier large : la chaleur retombe vite et les grains cessent de se coller entre eux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Pendant que les lentilles cuisent, plonger les œufs dans une casserole d''eau à petits bouillons et compter exactement 6 minutes pour un jaune encore coulant. Les basculer dans un bol d''eau glacée, attendre deux minutes, puis les écaler délicatement en commençant par le côté le plus large.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Dans un bol, écraser l''ail au presse-ail, ajouter le vinaigre, le poivre et une pincée de sel, puis verser l''huile d''olive en mince filet en fouettant sans arrêt jusqu''à ce que la sauce épaississe et cesse de se séparer. Verser sur les lentilles encore tièdes, mélanger à la spatule souple et laisser reposer 5 minutes : c''est en refroidissant qu''elles boivent la vinaigrette.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Ciseler le persil et la ciboulette, concasser grossièrement les noix au couteau. Les ajouter au saladier avec l''oignon cru émincé très finement, mélanger une dernière fois, répartir dans les assiettes puis poser sur chacune un œuf ouvert en deux. Rectifier en poivre et servir sans attendre, à peine tiède.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-014', 'recipe_family', 'Lentilles en salade tiède',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-014', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Remplacer l''œuf mollet par des lardons rissolés jusqu''au croustillant, égouttés de leur gras et parsemés tièdes sur les lentilles.','Version plus copieuse : effilocher un jambonneau cuit à l''eau pendant une heure avec oignon et carotte, et l''incorporer aux lentilles avant la vinaigrette.','Substituer le vinaigre de vin rouge par du vinaigre de cidre, plus doux, en augmentant légèrement la dose.','Ajouter des dés de patate douce rôtis au four et des dés de betterave cuite pour une salade plus sucrée et plus colorée.','Faire fondre le poireau à la poêle avec un peu d''huile et de thym au lieu de le cuire avec les lentilles, pour un goût plus confit.','Troquer les noix contre des noisettes torréfiées à sec.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-014","variants":["Remplacer l''œuf mollet par des lardons rissolés jusqu''au croustillant, égouttés de leur gras et parsemés tièdes sur les lentilles.","Version plus copieuse : effilocher un jambonneau cuit à l''eau pendant une heure avec oignon et carotte, et l''incorporer aux lentilles avant la vinaigrette.","Substituer le vinaigre de vin rouge par du vinaigre de cidre, plus doux, en augmentant légèrement la dose.","Ajouter des dés de patate douce rôtis au four et des dés de betterave cuite pour une salade plus sucrée et plus colorée.","Faire fondre le poireau à la poêle avec un peu d''huile et de thym au lieu de le cuire avec les lentilles, pour un goût plus confit.","Troquer les noix contre des noisettes torréfiées à sec."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-014', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('a4d866a621c3cb26b185923da1d7ba95'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":2,"acidic":3,"bitter":1,"umami":2,"heat":0,"pungency":3,"richness":3,"freshness":3,"intensity":3},"dominant_flavors":["terreux","acidulé","herbacé","alliacé"],"aroma_families":["herbacé","aromates séchés","alliacé"],"target_textures":["lentilles fondantes mais entières","jaune d''œuf coulant","éclats de noix croquants","oignon cru croquant"],"signature_ingredients":["Lentille corail sèche, crue","Huile d''olive vierge extra","Vinaigre de vin rouge","Persil frais"],"identity_guardrails":["Les lentilles doivent être assaisonnées encore tièdes : une fois froides elles n''absorbent plus la vinaigrette et le plat bascule en salade froide banale.","L''eau de cuisson reste non salée jusqu''à la fin, sinon la peau durcit et le grain ne s''attendrit plus uniformément.","La garniture aromatique carotte-poireau-oignon cuite avec la légumineuse et le duo thym-laurier constituent la base commune à toutes les sources : les retirer viderait le plat de son fond de goût.","La vinaigrette doit rester une émulsion huile d''olive et vinaigre franchement acide ; adoucie ou crémée, le contraste avec la lentille disparaît."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Œufs mimosa', 'oeufs mimosa', 'France', 'France',
     'meal', 'entrée froide', 'named_traditional_dish', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Œufs mimosa', 'Œufs durs farcis d''un mélange de jaunes tamisés avec mayonnaise et moutarde', ds.id, 'SRC-015',
    'Myko', 'editorial', 4, 25, 10, 'facile',
    NULL, NULL,
    'B', 'candidate', 'a39ede7012c74da1c0c983da9ab8e2b0',
    '{"sweet":0,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":2,"richness":4,"freshness":2,"intensity":2}'::jsonb, ARRAY['jaune d''œuf cuit','mayonnaise','moutarde']::text[],
    ARRAY['œuf cuit','moutardé','herbacé']::text[], ARRAY['blanc ferme et lisse','farce crémeuse','poudre sèche de jaune tamisé']::text[],
    ARRAY['Œuf cru','Mayonnaise','Moutarde de Dijon']::text[], ARRAY['La finition en jaune dur tamisé saupoudré sur le dessus est ce qui fait le mimosa : sans elle, le plat n''est qu''un œuf dur garni.','Les demi-blancs doivent rester entiers et servir de contenant ; hachés ou mixés, on bascule sur une salade d''œufs.','La liaison est une mayonnaise froide montée à l''huile, jamais une sauce cuite ni une crème chaude.','Le plat se sert froid, après passage au réfrigérateur ; tiède, la farce se délite et l''identité se perd.']::text[],
    ARRAY['pochage','émulsion','tamisage']::text[], ARRAY['Œufs mimosa au thon : émietter le thon au naturel en conserve, égoutté et l''incorporer à la farce de jaunes avant de garnir les blancs.','Montage en verrine : n''utiliser que les jaunes, les mixer avec la mayonnaise et le thon jusqu''à une crème lisse, dresser en verrines et saupoudrer de jaunes tamisés.','Farce à l''avocat : remplacer la mayonnaise par de la chair d''avocat écrasée avec les jaunes, du jus de citron frais, sel et poivre, dressée à la poche à douille cannelée.','Œufs mimosa frits : paner les demi-blancs (farine, œuf battu, chapelure), les frire une à deux minutes en huile chaude, puis les garnir de la farce mimosa au moment de servir.']::text[], ARRAY['œuf','moutarde','poisson']::text[],
    'Se garde 24 heures au réfrigérateur entre 0 et 4 °C, à plat, filmé sans contact avec la farce ; les œufs durs entiers non écalés tiennent jusqu''à trois jours. La congélation est à exclure : le blanc cuit devient caoutchouteux et la mayonnaise tranche à la décongélation. La variante au thon se consomme dans les 12 heures.', '{"fridge_hours":24,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":true,"source":"manual"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
