     'Sel fin', 10, 'g', 'optional',
     'assaisonnement', true, 9);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'optional',
     'assaisonnement', true, 10);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Ranger les œufs dans une casserole, les couvrir d''eau froide salée et porter sur feu vif ; dès les premiers bouillons, baisser à frémissement et compter dix minutes, en faisant rouler les œufs à la cuillère pendant la première minute pour que les jaunes restent au centre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Sortir les œufs à l''écumoire et les plonger sans attendre dans un saladier d''eau très froide, le temps qu''ils refroidissent à cœur ; les écaler ensuite sous un mince filet d''eau, la coquille se détachant alors sans arracher le blanc.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Fendre chaque œuf en deux dans la longueur, lame essuyée entre chaque coupe, puis faire glisser le jaune hors de son logement en préservant l''intégrité du blanc ; aligner les demi-blancs creux vers le haut sur le plat de service.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Pour une liaison maison, travailler le jaune d''œuf cru avec la moutarde de Dijon, verser l''huile d''olive vierge extra en filet très mince sans cesser de fouetter jusqu''à ce que la sauce se tienne, puis détendre au jus de citron frais au dernier moment ; sinon, partir directement de la mayonnaise.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Passer les deux tiers des jaunes durs au travers d''un tamis fin, les écraser à la fourchette avec la mayonnaise, le sel fin, le poivre noir moulu et le persil frais finement ciselé, jusqu''à une farce lisse, souple et sans grumeaux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Remplir chaque demi-blanc de cette farce, à la petite cuillère en bombant la surface ou à la poche à douille pour un dressage plus net, sans faire déborder sur les bords du blanc.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Tamiser le dernier tiers des jaunes réservés directement au-dessus des œufs garnis pour obtenir la neige jaune caractéristique, ajouter quelques pluches de persil frais, filmer sans écraser et laisser raffermir trente minutes au réfrigérateur avant de servir bien frais.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-015', 'recipe_family', 'Œufs mimosa',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-015', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Œufs mimosa au thon : émietter le thon au naturel en conserve, égoutté et l''incorporer à la farce de jaunes avant de garnir les blancs.','Montage en verrine : n''utiliser que les jaunes, les mixer avec la mayonnaise et le thon jusqu''à une crème lisse, dresser en verrines et saupoudrer de jaunes tamisés.','Farce à l''avocat : remplacer la mayonnaise par de la chair d''avocat écrasée avec les jaunes, du jus de citron frais, sel et poivre, dressée à la poche à douille cannelée.','Œufs mimosa frits : paner les demi-blancs (farine, œuf battu, chapelure), les frire une à deux minutes en huile chaude, puis les garnir de la farce mimosa au moment de servir.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-015","variants":["Œufs mimosa au thon : émietter le thon au naturel en conserve, égoutté et l''incorporer à la farce de jaunes avant de garnir les blancs.","Montage en verrine : n''utiliser que les jaunes, les mixer avec la mayonnaise et le thon jusqu''à une crème lisse, dresser en verrines et saupoudrer de jaunes tamisés.","Farce à l''avocat : remplacer la mayonnaise par de la chair d''avocat écrasée avec les jaunes, du jus de citron frais, sel et poivre, dressée à la poche à douille cannelée.","Œufs mimosa frits : paner les demi-blancs (farine, œuf battu, chapelure), les frire une à deux minutes en huile chaude, puis les garnir de la farce mimosa au moment de servir."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-015', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('a39ede7012c74da1c0c983da9ab8e2b0'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":0,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":2,"richness":4,"freshness":2,"intensity":2},"dominant_flavors":["jaune d''œuf cuit","mayonnaise","moutarde"],"aroma_families":["œuf cuit","moutardé","herbacé"],"target_textures":["blanc ferme et lisse","farce crémeuse","poudre sèche de jaune tamisé"],"signature_ingredients":["Œuf cru","Mayonnaise","Moutarde de Dijon"],"identity_guardrails":["La finition en jaune dur tamisé saupoudré sur le dessus est ce qui fait le mimosa : sans elle, le plat n''est qu''un œuf dur garni.","Les demi-blancs doivent rester entiers et servir de contenant ; hachés ou mixés, on bascule sur une salade d''œufs.","La liaison est une mayonnaise froide montée à l''huile, jamais une sauce cuite ni une crème chaude.","Le plat se sert froid, après passage au réfrigérateur ; tiède, la farce se délite et l''identité se perd."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Omelette paysanne', 'omelette paysanne', 'France', 'France',
     'meal', 'omelette', 'named_traditional_dish', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Omelette paysanne', 'Omelette roulée aux pommes de terre et lardons avec oignon, garnie de ciboulette', ds.id, 'SRC-016',
    'Myko', 'editorial', 4, 10, 12, 'facile',
    NULL, NULL,
    'B', 'candidate', 'c7ead1a350ceecf09089ddbef2d38db9',
    '{"sweet":0,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":2}'::jsonb, ARRAY['œuf','ciboulette','poivre']::text[],
    ARRAY['œuf cuit','alliacé frais','poivré']::text[], ARRAY['moelleux','baveux à cœur','surface souple']::text[],
    ARRAY['Pomme de terre cuite','Lardon fumé cru','Œuf cru']::text[], ARRAY['Sans pomme de terre ni lardons, c''est une omelette nature : la garniture est ce qui fait la paysanne.','Les pommes de terre sont colorées à part avant d''être noyées dans l''œuf, sinon elles rendent leur eau dans l''omelette.','L''omelette quitte le feu encore crémeuse au centre ; trop cuite elle devient sèche et caoutchouteuse.']::text[],
    ARRAY['saisie','omelette roulée','rissolage']::text[], ARRAY['Version marmiton.org : faire dorer des lardons à la poêle, y ajouter des croûtons de pain rassis et de l''ail pressé, puis verser l''appareil additionné d''une cuillerée de crème fraîche sur cette garniture.','Version 750g.com : blanchir brièvement du lard, râper finement des pommes de terre bien séchées dans un linge et émincer un oignon en rondelles, le tout mélangé aux œufs battus avant cuisson.','Omelette plate à l''espagnole : ne pas plier, terminer la cuisson à couvert sur feu doux ou sous le gril pour obtenir un disque entier que l''on découpe en parts.','Sans matière grasse laitière ni pliage, laisser l''omelette légèrement plus cuite à cœur pour un service froid, coupée en lanières.']::text[], ARRAY['œuf','lait']::text[],
    'Se mange dans la minute qui suit la cuisson, quand le cœur est encore crémeux. À défaut, conserver au réfrigérateur entre 0 et 4 °C pendant 24 heures maximum, dans une boîte hermétique, et consommer froide ou juste tiédie à la poêle sur feu doux. La congélation est déconseillée : l''œuf coagulé rend son eau à la décongélation et la texture devient caoutchouteuse et spongieuse.', '{"fridge_hours":24,"eat_immediately":true,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
