  CROSS JOIN unnest(ARRAY['Version tout à l''ail : supprimer l''oignon jaune et doubler l''ail cru, écrasé et à peine blondi dans l''huile, pour une sauce plus vive et plus rapide.','Version longuement mijotée : doubler le temps de réduction de la tomate à couvert et à feu très doux, en ajoutant un peu d''eau de cuisson des pâtes si la sauce attache, pour un goût plus rond et moins acide.','Version sans herbes séchées : omettre les herbes de Provence et compter uniquement sur l''ail et l''huile d''olive crue ajoutée au dressage.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
