  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 6, 'g', 'optional',
     'assaisonnement', true, 5);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 2, 'g', 'optional',
     'assaisonnement', true, 6);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Ôter des poireaux les feuilles vertes les plus coriaces et l''extrémité racinaire, fendre les blancs sur toute leur longueur, puis les passer sous un filet d''eau froide en écartant les épaisseurs pour déloger la terre. Détailler ensuite en tronçons d''environ trois centimètres.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Porter un grand volume d''eau salée à frémissement, y plonger les tronçons et compter une quinzaine de minutes de cuisson : la lame d''un couteau doit s''enfoncer sans buter dans le cœur du poireau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Verser le contenu de la casserole dans une passoire et appuyer franchement sur les poireaux avec le dos d''une louche pour en chasser le plus d''eau possible. C''est ce pressage qui évite au gratin de rendre du jus en cuisant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Faire chauffer l''huile d''olive vierge extra dans une sauteuse large et y remuer les poireaux égouttés trois à quatre minutes sur feu vif, le temps que l''humidité restante s''évapore et que les tronçons prennent une légère coloration. Saler et poivrer à ce moment-là.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Retirer la sauteuse du feu, arroser de crème fraîche liquide entière et mélanger doucement jusqu''à ce que chaque tronçon soit enrobé d''un voile crémeux. Goûter et rectifier le sel et le poivre avant de dresser.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Étaler la préparation dans un plat à gratin en une couche régulière, sans tasser, puis recouvrir uniformément de gruyère râpé jusqu''aux bords du plat.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Enfourner à 210 °C sur la grille haute pendant quinze à vingt minutes, jusqu''à obtenir une surface dorée et boursouflée. Rester à proximité sur la fin : le fromage bascule très vite du doré au brûlé. Laisser reposer cinq minutes hors du four avant de servir à même le plat de cuisson.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-020', 'recipe_family', 'Poireaux gratinés à la béchamel',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-020', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Version béchamel classique : remplacer la crème par une sauce blanche montée au roux beurre-farine-lait, muscadée, dès que ces formes sont disponibles au catalogue.','Montage à la tomate façon marmiton.org : alterner des couches de tomates pelées et épépinées mijotées à l''oignon et à l''ail avec les poireaux et le fromage.','Finition croustillante : parsemer de chapelure avant le passage au four pour une croûte plus sèche et plus craquante.','Portions individuelles : répartir en ramequins et gratiner huit à dix minutes seulement, comme le fait 750g.com.','Cuisson vapeur : passer les tronçons cinq minutes au panier vapeur au lieu de l''eau bouillante, pour un poireau moins gorgé d''eau.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-020","variants":["Version béchamel classique : remplacer la crème par une sauce blanche montée au roux beurre-farine-lait, muscadée, dès que ces formes sont disponibles au catalogue.","Montage à la tomate façon marmiton.org : alterner des couches de tomates pelées et épépinées mijotées à l''oignon et à l''ail avec les poireaux et le fromage.","Finition croustillante : parsemer de chapelure avant le passage au four pour une croûte plus sèche et plus craquante.","Portions individuelles : répartir en ramequins et gratiner huit à dix minutes seulement, comme le fait 750g.com.","Cuisson vapeur : passer les tronçons cinq minutes au panier vapeur au lieu de l''eau bouillante, pour un poireau moins gorgé d''eau."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-020', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('76b58a18a19452f35a033acad577b657'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":2,"salty":3,"acidic":0,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["poireau doux","crème lactée","fromage gratiné"],"aroma_families":["lactée","alliacée","grillée"],"target_textures":["fondant","croûte gratinée","nappage crémeux"],"signature_ingredients":["Poireau cru","Gruyère râpé","Crème fraîche liquide entière"],"identity_guardrails":["Le poireau doit être précuit puis pressé : sans cet égouttage, le plat rend son eau et devient une soupe gratinée.","Sans gruyère râpé sur le dessus, il n''y a plus de croûte dorée et le plat cesse d''être un gratin.","Le liant blanc et onctueux est obligatoire : privé de crème, l''appareil n''est plus qu''un plat de poireaux rôtis."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Poivrons farcis au riz', 'poivrons farcis au riz', 'France', 'France',
     'meal', 'légume farci', 'named_traditional_dish', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Poivrons farcis au riz', 'Poivrons rouges blanchis farcis de riz, lardons et tomate liés à l''œuf, rôtis au four', ds.id, 'SRC-021',
    'Myko', 'editorial', 4, 25, 40, 'facile',
    NULL, NULL,
    'B', 'candidate', '2cd6de07fd962bc8e504f790469ff854',
    '{"sweet":3,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":3}'::jsonb, ARRAY['poivron rôti','lard fumé','tomate cuite','ail doux']::text[],
    ARRAY['végétal grillé','fumé','aillé','herbacé']::text[], ARRAY['poivron fondant','riz moelleux','farce liée','surface légèrement grillée']::text[],
    ARRAY['Poivron rouge frais','Riz cru','Lardon fumé cru']::text[], ARRAY['Le poivron entier évidé sert de contenant et cuit avec la farce : farcir un autre légume ou servir la garniture à part change le plat.','Le riz est engagé à mi-cuisson et finit de gonfler au four dans les sucs du poivron ; un riz déjà cuit à cœur donne une farce pâteuse qui n''est plus la recette.','La cuisson se termine au four, pas à la casserole : le poivron doit s''affaisser et caraméliser en surface.']::text[],
    ARRAY['blanchiment','saisie','réduction','rôtissage']::text[], ARRAY['Version sans viande : supprimer le lardon fumé cru et cuire le riz avec du curry en poudre pour compenser la perte de profondeur.','Farce très herbacée : doubler la coriandre fraîche et le persil frais, ajoutés seulement hors du feu, et servir les poivrons tièdes plutôt que brûlants.','Cuisson à découvert du début à la fin pour une farce plus sèche et une peau nettement plus grillée, en surveillant le fond de plat qui s''assèche plus vite.','Poivrons coupés en deux dans la longueur et couchés dans le plat : cuisson raccourcie d''une dizaine de minutes, portions plus faciles à répartir.']::text[], ARRAY['œuf']::text[],
    'Trois jours au réfrigérateur entre 0 et 4 °C dans une boîte hermétique, réchauffés vingt minutes à 160 °C plutôt qu''au micro-ondes qui détrempe la peau. La congélation tient deux mois mais ramollit beaucoup le poivron à la décongélation : mieux vaut congeler la farce seule et garnir des poivrons frais le jour du repas.', '{"fridge_hours":72,"eat_immediately":false,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

