      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'optional',
     'assaisonnement', true, 8);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Peler les pommes de terre, les rincer sous l''eau claire puis les débiter en cubes réguliers d''environ deux centimètres ; les maintenir dans un saladier d''eau froide le temps de préparer le reste.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Fendre les poireaux en deux sur la longueur, les laver feuille à feuille pour chasser la terre, puis les détailler en fines demi-rondelles en gardant surtout le blanc et le vert tendre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Faire mousser le beurre — avec l''huile d''olive si l''on veut une matière grasse plus stable — dans une cocotte à fond épais, y verser les poireaux et les laisser suer huit minutes à feu doux, sans jamais les laisser prendre couleur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Égoutter les cubes de pomme de terre, les mêler aux poireaux fondus, mouiller avec le bouillon de volaille bien chaud jusqu''à recouvrir les légumes, saler modérément et amener au frémissement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Couvrir et laisser cuire à petits bouillons vingt-cinq à trente minutes : la pointe d''un couteau doit traverser un cube de pomme de terre sans la moindre résistance.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Mixer le potage encore chaud jusqu''à une texture veloutée, le passer au chinois pour une finesse parfaite, puis incorporer la crème hors du feu, rectifier en sel et poivre et servir aussitôt en assiette creuse.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-022', 'recipe_family', 'Potage Parmentier',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-022', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Servi glacé et bien lissé, additionné d''un trait de crème supplémentaire, il devient une vichyssoise d''été.','Couronner chaque assiette de croûtons frits égouttés sur papier absorbant et de quelques pluches de cerfeuil.','Remplacer le bouillon de volaille par de l''eau salée pour une version maigre plus végétale, comme le fait la trame chefsimon.','Réduire la crème de moitié et allonger d''un peu de bouillon pour un potage plus léger, moins nappant.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-022","variants":["Servi glacé et bien lissé, additionné d''un trait de crème supplémentaire, il devient une vichyssoise d''été.","Couronner chaque assiette de croûtons frits égouttés sur papier absorbant et de quelques pluches de cerfeuil.","Remplacer le bouillon de volaille par de l''eau salée pour une version maigre plus végétale, comme le fait la trame chefsimon.","Réduire la crème de moitié et allonger d''un peu de bouillon pour un potage plus léger, moins nappant."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-022', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('ce742794102a4736dfbec84ecf59e636'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":2,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":2},"dominant_flavors":["poireau fondu","pomme de terre douce","crème lactée","bouillon de volaille"],"aroma_families":["allium doux","lacté","bouillon de volaille","beurre noisette"],"target_textures":["velouté lisse","nappant","sans fibre"],"signature_ingredients":["Poireau cru","Pomme de terre cuite","Crème fraîche liquide entière"],"identity_guardrails":["Le couple poireau + pomme de terre est le plat lui-même : sans l''un des deux, ce n''est plus un potage parmentier.","Les poireaux doivent suer sans coloration ; toute caraméliisation ou saisie brune fait basculer le potage vers une soupe rustique étrangère à l''identité du plat.","La texture doit rester un velouté entièrement mixé : laisser des morceaux entiers en ferait une soupe paysanne, pas un potage.","La crème s''ajoute hors du feu en fin de cuisson, jamais en début de mijotage."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Riz cantonais', 'riz cantonais', 'France', 'France',
     'meal', 'plat sauté', 'named_traditional_dish', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Riz cantonais', 'Riz sauté à la poêle avec œufs brouillés, jambon blanc et petits pois', ds.id, 'SRC-023',
    'Myko', 'editorial', 4, 15, 20, 'facile',
    NULL, NULL,
    'B', 'candidate', '133e3944eb013dedc89f06acf64f09c2',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":2,"freshness":1,"intensity":2}'::jsonb, ARRAY['salé','umami','douceur végétale']::text[],
    ARRAY['alliacé','grillé','céréalier']::text[], ARRAY['grains détachés','moelleux','lanières fondantes']::text[],
    ARRAY['Riz cru','Œuf cru','Jambon blanc cuit','Petit pois surgelé']::text[], ARRAY['L''œuf doit être cuit à part en omelette fine puis retaillé en lanières : des œufs brouillés directement dans le riz donnent un autre plat.','Le riz doit être cuit à l''avance et refroidi avant d''être sauté ; un riz encore chaud colle et fait perdre la texture en grains détachés qui définit le plat.','Le trio riz, œuf et petit pois est présent dans les sept sources du dossier : retirer l''un des trois fait sortir de l''identité du riz cantonais.','Le sauté se fait sur feu vif et court, jamais en mijotage : le plat n''est pas un riz cuisiné en sauce.']::text[],
    ARRAY['saisie','blanchiment']::text[], ARRAY['Version aux crevettes : remplacer tout ou partie du jambon blanc par des crevettes décortiquées jetées trente secondes dans le wok très chaud avant les légumes.','Version végétarienne : supprimer le jambon, doubler la dose de petit pois et de carotte, et relever d''un trait supplémentaire de sauce soja.','Version aux lardons, courante chez marmiton.org : substituer des lardons fumés au jambon blanc et les faire rendre leur gras avant d''ajouter l''huile.','Riz sauté beurré à la façon de chefsimon.com : brouiller les œufs à la spatule dans le beurre au lieu de dresser une omelette, et les réincorporer en fin de sauté.']::text[], ARRAY['œuf','lait','gluten','soja','sésame']::text[],
    'Se garde 2 jours au réfrigérateur entre 0 et 4 °C dans une boîte hermétique, à refroidir rapidement après cuisson car le riz cuit tiède est un terrain favorable à Bacillus cereus. Réchauffer à la poêle bien chaude, jamais tiède. La congélation est possible 1 mois mais dégrade nettement la texture : les petits pois rendent de l''eau et l''omelette devient caoutchouteuse — décongeler au réfrigérateur puis sauter à feu vif.', '{"fridge_hours":48,"eat_immediately":false,"freezable":true,"freezer_months":1,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
