    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-026', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('8362361b45252395a040da1a808b0acf'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":3,"salty":3,"acidic":1,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["sucré du fruit sec","porc caramélisé","fumé du lard","oignon confit"],"aroma_families":["fruit sec","fumé","viande rôtie","légume fondu"],"target_textures":["viande fondante à la fourchette","pruneau moelleux et gonflé","sauce nappante"],"signature_ingredients":["Épaule de porc crue","Pruneau dénoyauté","Lardon fumé cru"],"identity_guardrails":["Sans pruneau dénoyauté, il ne reste qu''un sauté de porc ordinaire : c''est le fruit sec qui porte le contraste sucré-salé du plat.","La viande doit être saisie et colorée avant le mouillement ; un porc simplement poché dans l''eau donne un plat pâle et sans sucs.","La cuisson reste longue et à couvert : un passage rapide à la poêle ne rend pas l''épaule fondante et ne laisse pas les pruneaux parfumer le jus.","Le mouillement se limite à un fond d''eau, pas à un bain : la sauce doit finir réduite et nappante, jamais aqueuse."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Sauté de veau aux olives', 'saute de veau aux olives', 'France', 'France',
     'meal', 'plat mijoté', 'named_traditional_dish', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Sauté de veau aux olives', 'Épaule de veau braisée au vin blanc avec olives vertes et noires dans une sauce tomate', ds.id, 'SRC-027',
    'Myko', 'editorial', 4, 25, 120, 'facile',
    NULL, NULL,
    'B', 'candidate', 'd308110f1b970281337d0d9c162ada17',
    '{"sweet":1,"salty":3,"acidic":2,"bitter":2,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3}'::jsonb, ARRAY['olive saumurée','veau braisé','ail fondu','vin blanc réduit']::text[],
    ARRAY['herbacé méditerranéen','oignon compoté','tomate concentrée']::text[], ARRAY['viande fondante','sauce nappante','olive charnue']::text[],
    ARRAY['Épaule de veau crue','Olive verte dénoyautée','Olive noire']::text[], ARRAY['Les olives sont ajoutées en fin de mijotage et jamais dès le départ : cuites trop longtemps elles rendent le plat amer et perdent leur mâche.','Sans veau en gros cubes saisis puis braisés dans leur propre jus, ce n''est plus un sauté de veau mais un simple ragoût.','La sauce reste courte et liée par la farine de singeage, sans crème ni liaison finale.']::text[],
    ARRAY['blanchiment','saisie','déglaçage','mijotage','réduction']::text[], ARRAY['Version corse : doubler les lardons fumés et allonger le mijotage à deux heures pour une sauce plus courte et plus fumée.','Version au citron : ajouter des rondelles de citron avec les olives et réduire la cuisson à trente minutes en utilisant des tranches fines de veau plutôt que des cubes.','Version tout-en-un : glisser des pommes de terre en quartiers en même temps que les olives, ce qui fait passer le plat en rôle complet.','Version sans alcool : remplacer le vin blanc par la même quantité d''eau et une pointe supplémentaire de concentré de tomate.']::text[], ARRAY['gluten','sulfites']::text[],
    'Se garde trois jours au réfrigérateur entre 0 et 4 °C dans un récipient hermétique, et gagne même à être réchauffé doucement le lendemain. La congélation est possible trois mois à -18 °C, mais mieux vaut congeler la viande et sa sauce sans les olives, dont la chair se ramollit à la décongélation, et les ajouter au réchauffage.', '{"fridge_hours":72,"eat_immediately":false,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

