     'Poivre noir moulu', 2, 'g', 'optional',
     'assaisonnement', true, 16);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Parez l''épaule de veau et taillez-la en cubes réguliers d''environ quatre centimètres, puis roulez-les dans la farine et secouez-les pour ne garder qu''un voile mince.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Portez une petite casserole d''eau à frémissement, immergez-y les olives vertes et noires une quinzaine de secondes pour adoucir la saumure, égouttez-les et gardez-les de côté.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chauffez l''huile d''olive dans une cocotte à fond épais et colorez les cubes de veau par petites poignées, sans jamais surcharger le fond, jusqu''à une croûte ambrée sur toutes les faces ; débarrassez la viande et faites rendre leur gras aux lardons au même endroit.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Baissez le feu, jetez l''oignon finement émincé et la carotte en rondelles dans la graisse de cuisson, laissez-les fondre sans brunir, ajoutez l''ail écrasé puis le concentré de tomate et tournez deux minutes pour qu''il perde son mordant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Mouillez avec le vin blanc en raclant les sucs collés au fond à la spatule, laissez-le réduire de moitié, remettez la viande et les lardons, versez l''eau à hauteur, parsemez de thym et de romarin, salez et poivrez.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Couvrez et maintenez un frémissement à peine perceptible pendant une heure et quart, en remuant délicatement de loin en loin pour que rien n''attache.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Ajoutez les olives égouttées, retirez le couvercle et prolongez trente minutes : la viande doit céder sous la fourchette et la sauce napper le dos d''une cuillère. Goûtez et rectifiez le sel en tenant compte des olives avant d''envoyer à table.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-027', 'recipe_family', 'Sauté de veau aux olives',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-027', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Version corse : doubler les lardons fumés et allonger le mijotage à deux heures pour une sauce plus courte et plus fumée.','Version au citron : ajouter des rondelles de citron avec les olives et réduire la cuisson à trente minutes en utilisant des tranches fines de veau plutôt que des cubes.','Version tout-en-un : glisser des pommes de terre en quartiers en même temps que les olives, ce qui fait passer le plat en rôle complet.','Version sans alcool : remplacer le vin blanc par la même quantité d''eau et une pointe supplémentaire de concentré de tomate.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-027","variants":["Version corse : doubler les lardons fumés et allonger le mijotage à deux heures pour une sauce plus courte et plus fumée.","Version au citron : ajouter des rondelles de citron avec les olives et réduire la cuisson à trente minutes en utilisant des tranches fines de veau plutôt que des cubes.","Version tout-en-un : glisser des pommes de terre en quartiers en même temps que les olives, ce qui fait passer le plat en rôle complet.","Version sans alcool : remplacer le vin blanc par la même quantité d''eau et une pointe supplémentaire de concentré de tomate."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-027', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('d308110f1b970281337d0d9c162ada17'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":3,"acidic":2,"bitter":2,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3},"dominant_flavors":["olive saumurée","veau braisé","ail fondu","vin blanc réduit"],"aroma_families":["herbacé méditerranéen","oignon compoté","tomate concentrée"],"target_textures":["viande fondante","sauce nappante","olive charnue"],"signature_ingredients":["Épaule de veau crue","Olive verte dénoyautée","Olive noire"],"identity_guardrails":["Les olives sont ajoutées en fin de mijotage et jamais dès le départ : cuites trop longtemps elles rendent le plat amer et perdent leur mâche.","Sans veau en gros cubes saisis puis braisés dans leur propre jus, ce n''est plus un sauté de veau mais un simple ragoût.","La sauce reste courte et liée par la farine de singeage, sans crème ni liaison finale."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Socca niçoise', 'socca nicoise', 'France', 'France',
     'meal', 'galette', 'named_traditional_dish', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Socca niçoise', 'Galette croustillante de farine de pois chiche à l''huile d''olive, cuite à haute température au four', ds.id, 'SRC-028',
    'Myko', 'editorial', 4, 15, 15, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '4bb5c3a70d81634d7762a2fc5739f393',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":2,"heat":0,"pungency":3,"richness":3,"freshness":1,"intensity":3}'::jsonb, ARRAY['pois chiche torréfié','huile d''olive','poivre']::text[],
    ARRAY['légumineuse grillée','fruité olive','notes fumées de croûte']::text[], ARRAY['croûte dorée et craquante','cœur souple et fondant','bords fins presque brûlés']::text[],
    ARRAY['Farine de pois chiche','Huile d''olive vierge extra']::text[], ARRAY['Sans farine de pois chiche, ce n''est plus une socca : aucune autre farine ne peut s''y substituer sans détruire le plat.','Sans cuisson à chaleur maximale finie sous le gril, le contraste entre croûte tachée de brun et intérieur moelleux disparaît et la galette devient une simple crêpe pâle.','Sans huile d''olive généreuse dans la pâte et sur la plaque brûlante, la socca perd son parfum et sa surface craquante.','Sans étalement très fin, de deux à trois millimètres, la galette cuit en épaisseur et perd sa texture caractéristique.']::text[],
    ARRAY['rôtissage','gratinage']::text[], ARRAY['Cuisson traditionnelle en tourtière de cuivre légèrement huilée, dans un four à bois très chaud, comme le décrit la version niçoise historique.','Découpe en petits carrés servis à la main plutôt qu''en grandes parts irrégulières.','Répartition de la pâte sur deux plaques de quarante centimètres au lieu d''une seule grande, pour une galette plus fine et plus craquante.','Finition très poivrée au moulin juste avant de servir, jusqu''à couvrir visiblement la surface.']::text[], ARRAY[]::text[],
    'La socca se mange dans les minutes qui suivent la sortie du four, quand la croûte est encore craquante. À défaut, la garder quelques heures à température ambiante sous un linge, ou deux jours au réfrigérateur entre 0 et 4 °C en boîte hermétique, puis la repasser deux à trois minutes sous le gril pour lui rendre du croustillant. La congélation est déconseillée : la décongélation détrempe la croûte et rend le cœur caoutchouteux.', '{"fridge_hours":48,"eat_immediately":true,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'farine de pois chiche' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Farine de pois chiche', 125, 'g', 'required',
     'base farineuse', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'eau' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Eau', 250, 'ml', 'required',
     'liquide', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'huile d olive vierge extra' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Huile d''olive vierge extra', 76, 'g', 'required',
     'matière grasse', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 2.4, 'g', 'optional',
     'assaisonnement', true, 4);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'optional',
     'assaisonnement', true, 5);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Verser l''eau froide dans un grand saladier, puis y faire tomber la farine de pois chiche en pluie sans cesser de fouetter, jusqu''à obtenir un liquide parfaitement lisse. Si des grains résistent, passer l''appareil au tamis fin.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Incorporer un tiers environ de l''huile d''olive vierge extra ainsi que le sel fin, et battre vigoureusement. La pâte doit rester aussi fluide qu''un lait entier ; l''allonger d''une cuillerée d''eau si elle a épaissi en reposant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pousser le four à sa puissance maximale, chaleur du haut privilégiée, et le laisser monter au moins dix minutes avec à l''intérieur une grande plaque ronde ou deux plaques d''une quarantaine de centimètres.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Sortir la plaque brûlante, y verser le reste de l''huile d''olive vierge extra et l''incliner pour en tapisser tout le fond, puis la renfourner cinq minutes afin que le corps gras soit fumant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser la pâte d''un seul geste sur la plaque huilée et l''étaler aussitôt sur deux à trois millimètres d''épaisseur, en une couche régulière. Enfourner sans attendre sur le gradin le plus haut.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Au bout de deux minutes, basculer le four en position gril et poursuivre cinq à sept minutes, le temps que la surface prenne une couleur profonde piquée de taches brunes. Percer à la pointe du couteau les cloques qui gonflent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Décoller la galette à la spatule, la débiter en morceaux irréguliers ou en petits carrés, poivrer généreusement avec le poivre noir moulu et servir brûlant, à la main.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-028', 'recipe_family', 'Socca niçoise',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-028', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Cuisson traditionnelle en tourtière de cuivre légèrement huilée, dans un four à bois très chaud, comme le décrit la version niçoise historique.','Découpe en petits carrés servis à la main plutôt qu''en grandes parts irrégulières.','Répartition de la pâte sur deux plaques de quarante centimètres au lieu d''une seule grande, pour une galette plus fine et plus craquante.','Finition très poivrée au moulin juste avant de servir, jusqu''à couvrir visiblement la surface.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-028","variants":["Cuisson traditionnelle en tourtière de cuivre légèrement huilée, dans un four à bois très chaud, comme le décrit la version niçoise historique.","Découpe en petits carrés servis à la main plutôt qu''en grandes parts irrégulières.","Répartition de la pâte sur deux plaques de quarante centimètres au lieu d''une seule grande, pour une galette plus fine et plus craquante.","Finition très poivrée au moulin juste avant de servir, jusqu''à couvrir visiblement la surface."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-028', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('4bb5c3a70d81634d7762a2fc5739f393'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":2,"heat":0,"pungency":3,"richness":3,"freshness":1,"intensity":3},"dominant_flavors":["pois chiche torréfié","huile d''olive","poivre"],"aroma_families":["légumineuse grillée","fruité olive","notes fumées de croûte"],"target_textures":["croûte dorée et craquante","cœur souple et fondant","bords fins presque brûlés"],"signature_ingredients":["Farine de pois chiche","Huile d''olive vierge extra"],"identity_guardrails":["Sans farine de pois chiche, ce n''est plus une socca : aucune autre farine ne peut s''y substituer sans détruire le plat.","Sans cuisson à chaleur maximale finie sous le gril, le contraste entre croûte tachée de brun et intérieur moelleux disparaît et la galette devient une simple crêpe pâle.","Sans huile d''olive généreuse dans la pâte et sur la plaque brûlante, la socca perd son parfum et sa surface craquante.","Sans étalement très fin, de deux à trois millimètres, la galette cuit en épaisseur et perd sa texture caractéristique."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Soupe au pistou', 'soupe au pistou', 'France', 'France',
     'meal', 'soupe', 'named_traditional_dish', 'fresh_herbal',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Soupe au pistou', 'Soupe provençale de légumes variés et haricots avec pâtes, servie avec un pistou de basilic et ail', ds.id, 'SRC-029',
    'Myko', 'editorial', 6, 30, 60, 'facile',
    NULL, NULL,
    'B', 'candidate', '3f03654db174ed1bdc86f2c8bf8f9525',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":3,"richness":3,"freshness":4,"intensity":3}'::jsonb, ARRAY['basilic','ail','légumes mijotés','fromage affiné']::text[],
    ARRAY['herbacé','alliacé','végétal','huile d''olive']::text[], ARRAY['bouillon lié par l''amidon','légumes fondants en dés','pistou onctueux et émulsionné']::text[],
    ARRAY['Basilic frais','Ail cru','Huile d''olive vierge extra','Haricot blanc sec']::text[], ARRAY['Le pistou est incorporé hors du feu, jamais bouilli : c''est ce qui garde l''arôme de basilic cru intact.','Le basilic doit être frais et pilé avec l''ail cru et l''huile d''olive ; un basilic séché ou une sauce cuite fait perdre son nom au plat.','La garniture repose sur les haricots (blancs secs et verts) avec courgette et pomme de terre, cuits à l''eau sans bouillon de viande.']::text[],
    ARRAY['mijotage','émulsion','blanchiment']::text[], ARRAY['Pistou sans tomate, monte seulement a l''ail, au basilic, au parmesan et a l''huile d''olive, comme dans la version la plus depouillee du dossier.','Remplacer le parmesan du pistou par du gruyere rape, ou partager la quantite entre les deux fromages.','Utiliser de la tomate rapee incorporee directement au bouillon plutot que de la tomate fraiche pelee.','Supprimer les pates courtes et augmenter la part de pomme de terre pour une soupe plus rustique et sans gluten.','Ajouter les haricots rouges secs aux haricots blancs pour une version deux legumineuses, plus dense et plus coloree.']::text[], ARRAY['gluten','lait']::text[],
    'Se garde 3 jours au réfrigérateur à 4 °C dans un récipient fermé ; le goût de pistou s''estompe dès le lendemain, mieux vaut en réserver une part fraîche à ajouter au réchauffage. Le bouillon garni se congèle 3 mois s''il est préparé sans pâtes ni pommes de terre, qui se délitent à la décongélation ; le pistou, lui, ne supporte pas la congélation car l''émulsion se sépare.', '{"fridge_hours":72,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
