  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Comptez à l''achat quatre pommes à chair ferme, soit environ 450 g de fruits entiers : une fois pelées, évidées et débarrassées des pépins, il en reste près de 320 g de chair. Détaillez-les en quartiers épais et arrosez-les aussitôt du jus de citron pour qu''ils gardent leur teinte claire.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Épluchez 280 g d''oignons pour en obtenir 250 g nets, émincez-les finement et laissez-les fondre à couvert dans un tiers du beurre, sur feu très doux : une quinzaine de minutes suffisent pour qu''ils deviennent translucides puis prennent une couleur dorée, sans jamais accrocher au fond.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Dans une seconde poêle, faites mousser la moitié du beurre restant et couchez-y les quartiers de pomme à plat. Poudrez-les de sucre, laissez-les prendre couleur cinq minutes à couvert, retournez chaque morceau, puis poursuivez à découvert jusqu''à ce que les faces soient laquées. Réservez au chaud.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Le boudin se vend en boyau : prévoyez quatre tronçons d''environ 150 g, soit près de 600 g sur la balance du charcutier, qui donnent les 560 g de chair annoncés une fois les extrémités parées et le boyau fendu d''un coup de lame — retirez-le entièrement si vous préférez cuire la chair nue, gardez-le pour servir les tronçons entiers.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Essuyez la poêle des pommes, chauffez-y le reste du beurre et posez le boudin sur feu vif juste le temps de le colorer, puis baissez immédiatement l''allure. Huit à dix minutes de cuisson douce en le tournant avec délicatesse suffisent : ne le piquez jamais, sous peine de voir le boyau se rompre et le gras s''échapper.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Salez et donnez deux tours de moulin à poivre au dressage. Répartissez les oignons fondus au fond d''assiettes chaudes, posez le boudin par-dessus, rangez les quartiers de pomme caramélisés autour et nappez le tout du beurre de cuisson resté dans la poêle.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-032', 'recipe_family', 'Boudin noir aux pommes',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-032', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Tourte feuilletée : compote de pomme, tronçons de blanc de poireau et rondelles de boudin sans peau entre deux abaisses, dorées à l''œuf, 35 min à 210 °C (750g.com).','Version tatin : quartiers de pomme beurrés et rondelles de boudin recouverts de pâte feuilletée piquée, 30 min à 200 °C (marmiton.org).','Assiette complète : purée de pomme de terre et oignons confits au miel servis avec le boudin poêlé (marmiton.org).','Poêlée de rattes en rondelles avec dés de pomme et raisins secs, boudin doré à part et ajouté au dernier moment (750g.com).','Pommes entières évidées, passées au four puis garnies du hachis de boudin grillé et d''oignons fondus (750g.com).','Flambage au calvados sur les pommes caramélisées, ou mousse froide de boudin et de pomme montée en verrine (chefsimon.com).']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-032","variants":["Tourte feuilletée : compote de pomme, tronçons de blanc de poireau et rondelles de boudin sans peau entre deux abaisses, dorées à l''œuf, 35 min à 210 °C (750g.com).","Version tatin : quartiers de pomme beurrés et rondelles de boudin recouverts de pâte feuilletée piquée, 30 min à 200 °C (marmiton.org).","Assiette complète : purée de pomme de terre et oignons confits au miel servis avec le boudin poêlé (marmiton.org).","Poêlée de rattes en rondelles avec dés de pomme et raisins secs, boudin doré à part et ajouté au dernier moment (750g.com).","Pommes entières évidées, passées au four puis garnies du hachis de boudin grillé et d''oignons fondus (750g.com).","Flambage au calvados sur les pommes caramélisées, ou mousse froide de boudin et de pomme montée en verrine (chefsimon.com)."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-032', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('c1e39df3fb4f9ea810dd9ef8bc353f8d'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":3,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":4},"dominant_flavors":["caramélisé","sucré","profond","beurré"],"aroma_families":["beurre","oignon_compoté","porc"],"target_textures":["protéine_fondante","tendre","contraste_léger"],"signature_ingredients":["Boudin noir à cuire","Pomme fraîche"],"identity_guardrails":["Sans boudin noir, le plat n''existe plus : la chair de sang poêlée en est l''axe et aucune autre charcuterie ne la remplace.","La pomme doit rester en morceaux identifiables et caramélisés ; réduite en compote lisse ou remplacée par de la pomme de terre, l''accord sucré-salé se défait.","Saisie brève puis feu doux : cuit à feu vif d''un bout à l''autre, le boyau éclate et le gras se perd dans la poêle.","Le poivre reste un assaisonnement de finition : la médiane du dossier est faussée par des pesées de boudin et ne doit jamais être appliquée telle quelle."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Bouillabaisse', 'bouillabaisse', 'France', 'France',
     'meal', 'plat mijoté', 'named_traditional_dish', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Bouillabaisse', 'Soupe de moules et pommes de terre dans un bouillon de poisson avec tomates et vin blanc', ds.id, 'SRC-033',
    'Myko', 'editorial', 4, 35, 40, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'bfc3fabb49002024a1e431a3dcf889e4',
    '{"sweet":1,"salty":4,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":2,"freshness":2,"intensity":4}'::jsonb, ARRAY['iodé','safran','tomate cuite','ail']::text[],
    ARRAY['marine','épice safranée','anisée','agrume']::text[], ARRAY['bouillon fluide et soyeux','pomme de terre fondante','chair de moule tendre']::text[],
    ARRAY['Sauce poisson','Moule commune crue','Safran']::text[], ARRAY['Sans safran, le bouillon perd sa robe orangée et son parfum : ce n''est plus une bouillabaisse mais une soupe de pommes de terre à la tomate.','Sans base marine — fond de poisson et coquillages — il ne reste qu''un ragoût de légumes ; l''iode est la colonne vertébrale du plat.','La garniture reste strictement marine et provençale : ni viande, ni condiment asiatique, quoi qu''en disent les relevés d''ingrédients aberrants.','Le bouillon ne doit jamais bouillir franchement, sous peine de troubler et de durcir les coquillages.']::text[],
    ARRAY['mijotage','pochage','réduction','infusion']::text[], ARRAY['Version pêcheur : remplacer une partie des moules par des filets de poisson de roche déposés sur le bouillon et pochés hors du feu cinq minutes.','Service à la marseillaise : passer le bouillon et le servir à part, brûlant, avec des croûtons frottés d''ail, la garniture étant présentée à côté sur un plat creux.','Sans alcool : supprimer le vin blanc, ouvrir les moules dans un fond d''eau et rattraper la vivacité par un trait de jus de citron au moment de servir.']::text[], ARRAY['poisson','mollusques','sulfites']::text[],
    'Se garde 24 heures au réfrigérateur entre 0 et 4 °C dans un récipient couvert, coquillages et bouillon ensemble ; ne réchauffer qu''une seule fois, à frémissement doux et sans ébullition. La congélation est déconseillée : le bouillon safrané la supporte, mais les moules deviennent caoutchouteuses et les pommes de terre farineuses à la décongélation.', '{"fridge_hours":24,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
