  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir environ 500 g de carottes entières, ou une botte d''à peu près 700 g si elles sont vendues avec leurs fanes, pour arriver aux 400 g de chair nette de la recette : ôter le feuillage, gratter la peau à l''économe et retirer les deux extrémités.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Râper les carottes sur la grille à gros trous, à la main ou au robot, et les laisser tomber sans les tasser dans un grand saladier afin que les filaments restent aérés.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Faire gonfler les raisins secs une dizaine de minutes dans un fond d''eau tiède, puis les égoutter et les presser doucement entre les doigts.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Presser l''orange au-dessus d''un bol, y délayer la moutarde à la fourchette jusqu''à disparition des grumeaux, ajouter le vinaigre puis verser l''huile en mince filet en fouettant, jusqu''à ce que la sauce épaississe et cesse de se séparer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Saler, poivrer et incorporer le cumin à la vinaigrette, puis goûter : elle doit sembler un cran trop franche dans le bol, car l''eau des carottes va l''adoucir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Verser la sauce sur les carottes, ajouter les raisins égouttés et mélanger longuement à deux fourchettes en soulevant la masse, de façon à enrober chaque filament plutôt que d''écraser le tas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Couvrir et laisser reposer trente minutes au réfrigérateur, remuer une dernière fois, rectifier le sel et servir bien frais.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-035', 'recipe_family', 'Carottes râpées',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-035', 'missing_required_count', v_missing), 'open');
  END IF;

