    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Version marocaine : doubler le cumin et servir tiède les raisins secs regonflés dans le jus d''orange chaud','Version douce sans vinaigre : monter la vinaigrette au seul jus d''orange et à la moutarde, pour des convives sensibles à l''acidité','Version agrumes entiers : lever des suprêmes d''orange et les mêler aux carottes juste avant le service']::text[]) AS variant(name);

