  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Choisir une boule de céleri-rave d''environ 800 g, le calibre courant chez le primeur, la brosser sous l''eau puis retirer au couteau la peau et les zones fibreuses ou creuses : il doit rester à peu près 600 g de chair nette, le parage emportant près d''un quart du poids acheté. Frotter aussitôt les faces mises à nu avec un filet de jus de citron pour qu''elles ne brunissent pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Râper la chair en filaments fins, à la mandoline ou au robot muni de la grille à râper. Arroser du reste de jus de citron, saler, mélanger à pleines mains et laisser reposer un quart d''heure : les filaments s''assouplissent et rendent un peu d''eau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Dans un bol qui n''est pas sorti du froid, fouetter le jaune d''œuf avec la moutarde de Dijon jusqu''à obtenir une pâte lisse et homogène. Verser l''huile d''olive en filet mince sans cesser de fouetter, jusqu''à ce que l''émulsion se tienne au fouet, puis la détendre avec le vinaigre blanc.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Assouplir cette base avec le yaourt nature, donner un tour de moulin à poivre et ajouter la pincée de sucre seulement si la moutarde domine trop. La sauce doit napper le dos d''une cuillère sans couler.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Presser le céleri râpé entre les paumes pour chasser l''eau de dégorgement, puis l''incorporer à la sauce en trois fois, en soulevant la masse à la fourchette pour enrober chaque filament sans l''écraser. Rectifier le sel et l''acidité.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Couvrir et laisser reposer au moins trente minutes au réfrigérateur, le temps que le céleri s''imprègne et que la sauce s''accroche. Au moment de servir, tailler la pomme en fins bâtonnets et la répartir sur le dessus avec le persil ciselé.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-037', 'recipe_family', 'Céleri rémoulade',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-037', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Version allégée sans jaune d''œuf ni huile : yaourt nature, moutarde et jus de citron simplement fouettés ensemble.','Céleri plongé trente secondes dans l''eau bouillante salée puis rafraîchi à l''eau glacée, pour des filaments plus tendres et moins piquants.','Sauce relevée de câpres rincées et grossièrement hachées, comme dans la variante marmiton.','Bâtonnets de pomme acidulée mêlés à la masse plutôt que posés dessus, pour une rémoulade franchement fruitée.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-037","variants":["Version allégée sans jaune d''œuf ni huile : yaourt nature, moutarde et jus de citron simplement fouettés ensemble.","Céleri plongé trente secondes dans l''eau bouillante salée puis rafraîchi à l''eau glacée, pour des filaments plus tendres et moins piquants.","Sauce relevée de câpres rincées et grossièrement hachées, comme dans la variante marmiton.","Bâtonnets de pomme acidulée mêlés à la masse plutôt que posés dessus, pour une rémoulade franchement fruitée."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-037', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('741159e7b559260e5cf32c6b8e5a8cda'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":2,"acidic":3,"bitter":1,"umami":1,"heat":0,"pungency":3,"richness":4,"freshness":3,"intensity":3},"dominant_flavors":["moutarde","citron","céleri"],"aroma_families":["moutardé","agrume","herbacé"],"target_textures":["croquant","crémeux"],"signature_ingredients":["Céleri branche cru","Moutarde de Dijon","Jus de citron frais"],"identity_guardrails":["Le céleri reste cru et taillé en filaments : cuit ou réduit en purée, ce n''est plus une rémoulade.","La moutarde doit rester perceptible dans l''émulsion, c''est elle qui donne son mordant au nom du plat.","L''acidité du citron est structurelle, elle empêche l''oxydation et équilibre le gras de la sauce ; la supprimer donne une salade grise et lourde."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Chou farci', 'chou farci', 'France', 'France',
     'meal', 'plat mijoté', 'named_traditional_dish', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Chou farci', 'Feuilles de chou vert blanchies farcies d''un mélange bœuf-porc haché, mijotées longuement', ds.id, 'SRC-038',
    'Myko', 'editorial', 6, 40, 135, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '0f5c4e43c7002b6a8e2e4929291f6d53',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['viande braisée','chou fondant','bouillon de volaille','tomate cuite']::text[],
    ARRAY['végétal cuit','gras animal','aromates verts']::text[], ARRAY['feuilles fondantes','farce moelleuse et serrée','jus court et nappant']::text[],
    ARRAY['Chou vert frais','Bœuf haché cru 15 % MG','Porc haché cru','Poitrine de porc crue']::text[], ARRAY['Les feuilles de chou vert entières doivent envelopper la farce et le chou être reconstitué en boule : émincé et mélangé à la viande, ce n''est plus un chou farci mais une potée','La farce reste une viande hachée grasse liée à la mie de pain et à l''œuf ; sans le gras de la poitrine de porc elle se dessèche et le plat perd son moelleux','La cuisson est un mijotage long à couvert dans un mouillement court, pas un rôtissage à sec']::text[],
    ARRAY['blanchiment','mijotage','farcissage']::text[], ARRAY['Chou farci en petits paquets : une boulette de farce par feuille blanchie, refermée en aumônière et mijotée dans la tomate râpée','Version dombiste : la moitié de la viande est remplacée par de la chair de brochet crue, pour une farce plus fine et plus pâle','Montage en gratin : couches alternées de feuilles et de farce dans un plat, nappées de tomate râpée et cuites une heure à 180 °C','Au chou blanc frais quand le chou vert manque : les feuilles sont plus serrées, allonger le blanchiment de cinq minutes']::text[], ARRAY['gluten','lait','œuf']::text[],
    'Se garde 3 jours au réfrigérateur entre 0 et 4 °C, entier ou en quartiers, immergé dans son jus et couvert ; réchauffer à couvert et à feu doux, jamais à gros bouillons. La congélation est possible en parts jusqu''à 3 mois, mais les feuilles rendent de l''eau à la décongélation et perdent de leur tenue : congeler le jus séparément et le réduire au réchauffage.', '{"fridge_hours":72,"eat_immediately":false,"freezable":true,"freezer_months":3,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

