     'assaisonnement', true, 8);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'muscade moulue' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Muscade moulue', 0.5, 'g', 'optional',
     'épice', true, 9);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir un chou-fleur entier d''environ 1,2 kg chez le primeur : une fois les grosses feuilles retirées et le trognon éliminé, il reste à peu près les 650 g de bouquets utiles. Détacher ces bouquets à la main en gardant une taille régulière, de la grosseur d''une grosse noix, puis les rincer à l''eau froide et les laisser s''égoutter.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Plonger les bouquets dans un grand volume d''eau salée en pleine ébullition et les laisser huit à dix minutes. La pointe d''un couteau doit traverser la tige sans résistance mais le bouquet doit rester ferme : trop cuit, il s''affaissera au four. Égoutter aussitôt et laisser reposer dans la passoire, bouquets retournés, le temps que l''eau s''écoule complètement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Allumer le four à 200 °C en chaleur tournante. Prélever une noisette sur le beurre pour graisser généreusement le fond et les bords d''un plat à gratin.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Faire fondre le reste du beurre à feu doux dans une casserole, verser la farine d''un coup et remuer une bonne minute jusqu''à ce que le mélange mousse sans colorer. Retirer du feu quelques secondes, puis incorporer le lait tiédi en trois fois, en fouettant à chaque ajout pour éviter les grumeaux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Remettre sur feu doux et laisser épaissir cinq à six minutes en fouettant sans arrêt, jusqu''à ce que la sauce nappe la spatule. Détendre avec la crème, saler, poivrer, râper la muscade, puis fouetter hors du feu un tiers du gruyère pour qu''il fonde dans la sauce encore chaude.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Étaler une louche de sauce au fond du plat beurré, ranger les bouquets serrés et tête vers le bas afin que la sauce s''infiltre entre les fleurettes, puis napper du reste de sauce jusqu''à recouvrir les sommets.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Répartir le gruyère restant sur toute la surface et enfourner trente minutes à mi-hauteur. Si le dessus manque de couleur, terminer cinq minutes sous le gril en surveillant. Laisser reposer le plat cinq minutes avant de servir, le temps que la sauce se raffermisse.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-041', 'recipe_family', 'Gratin de chou-fleur',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-041', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Version au bouillon, comme sur marmiton : remplacer le lait entier par du bouillon de volaille bien chaud pour une sauce plus légère, et ne garder la crème qu''en filet final.','Version au curry de chefsimon : fouetter une petite cuillerée de curry en poudre dans la béchamel juste avant de napper, en rallongeant d''un peu de lait si la sauce s''épaissit trop.','Version à l''oignon : faire blondir un oignon jaune finement émincé dans le beurre avant d''ajouter la farine, ce qui donne une sauce plus douce et plus sucrée.','Version croquante : parsemer une poignée de noix grossièrement concassées avec le fromage du dessus, à ajouter en fin de cuisson pour qu''elles ne brûlent pas.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-041","variants":["Version au bouillon, comme sur marmiton : remplacer le lait entier par du bouillon de volaille bien chaud pour une sauce plus légère, et ne garder la crème qu''en filet final.","Version au curry de chefsimon : fouetter une petite cuillerée de curry en poudre dans la béchamel juste avant de napper, en rallongeant d''un peu de lait si la sauce s''épaissit trop.","Version à l''oignon : faire blondir un oignon jaune finement émincé dans le beurre avant d''ajouter la farine, ce qui donne une sauce plus douce et plus sucrée.","Version croquante : parsemer une poignée de noix grossièrement concassées avec le fromage du dessus, à ajouter en fin de cuisson pour qu''elles ne brûlent pas."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-041', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('ab2324b94c8d06892e641985d87d5883'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["lacté crémeux","fromage affiné","légume crucifère doux"],"aroma_families":["lacté","beurré","épices douces"],"target_textures":["bouquets fondants","sauce nappante","croûte gratinée"],"signature_ingredients":["Chou-fleur frais","Gruyère râpé","Lait entier"],"identity_guardrails":["Les bouquets de chou-fleur doivent rester entiers et identifiables sous la sauce : réduits en purée, le plat devient un flan de légume et non un gratin.","La sauce blanche liée au roux beurre-farine-lait est la colonne vertébrale du plat ; la remplacer par de la crème seule ou par un simple jus de cuisson en change la nature.","La couche de fromage gratinée en surface est obligatoire : sans croûte dorée, il ne reste qu''un chou-fleur à la béchamel."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Lentilles au lard', 'lentilles au lard', 'France', 'France',
     'meal', 'plat mijoté', 'named_traditional_dish', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Lentilles au lard', 'Lentilles vertes mijotées avec lardons fumés, carottes et oignons parfumés au thym', ds.id, 'SRC-042',
    'Myko', 'editorial', 4, 20, 40, 'facile',
    NULL, NULL,
    'B', 'candidate', 'b0271b0d3cd29812773168928c6e09cd',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['fumé','terreux']::text[],
    ARRAY['fumé','herbacé sec','végétal cuit']::text[], ARRAY['lentille fondante restée entière','lardon doré aux arêtes croustillantes','jus court et légèrement lié']::text[],
    ARRAY['Lentille verte sèche, crue','Lardon fumé cru','Thym séché']::text[], ARRAY['Sans lardon fumé, il ne reste que des lentilles mijotées : le fumé du porc est la moitié du nom du plat','Les grains doivent tenir entiers ; passés au mixeur, le plat bascule en velouté et change d''identité','Le sel ne s''ajoute qu''en fin de cuisson et à petite dose, le lard ayant déjà salé le bouillon']::text[],
    ARRAY['saisie','mijotage','réduction']::text[], ARRAY['Version veloutée du dossier : mixer la moitié de la casserole, remonter à la crème et remettre les lardons entiers par-dessus','Avec de la lentille corail, qui se délite en purée en une vingtaine de minutes et donne un plat plus fondant que grainé','Sans crème, simplement lustrée d''un filet d''huile d''olive crue et relevée de persil et d''un tour de moulin']::text[], ARRAY['lait']::text[],
    'Trois jours au réfrigérateur à 4 °C dans une boîte fermée ; les lentilles boivent leur jus en refroidissant, rallonger d''un fond d''eau à la réchauffe douce. Congélation possible deux mois à condition de n''avoir pas mis la crème, celle-ci tranchant à la décongélation : la verser plutôt après réchauffage.', '{"fridge_hours":72,"eat_immediately":false,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed+manual"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

