  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-042","variants":["Version veloutée du dossier : mixer la moitié de la casserole, remonter à la crème et remettre les lardons entiers par-dessus","Avec de la lentille corail, qui se délite en purée en une vingtaine de minutes et donne un plat plus fondant que grainé","Sans crème, simplement lustrée d''un filet d''huile d''olive crue et relevée de persil et d''un tour de moulin"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-042', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('b0271b0d3cd29812773168928c6e09cd'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["fumé","terreux"],"aroma_families":["fumé","herbacé sec","végétal cuit"],"target_textures":["lentille fondante restée entière","lardon doré aux arêtes croustillantes","jus court et légèrement lié"],"signature_ingredients":["Lentille verte sèche, crue","Lardon fumé cru","Thym séché"],"identity_guardrails":["Sans lardon fumé, il ne reste que des lentilles mijotées : le fumé du porc est la moitié du nom du plat","Les grains doivent tenir entiers ; passés au mixeur, le plat bascule en velouté et change d''identité","Le sel ne s''ajoute qu''en fin de cuisson et à petite dose, le lard ayant déjà salé le bouillon"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
