  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoyez environ 850 g d''aubergines entières chez le primeur, soit deux belles pièces : une fois le pédoncule coupé et les extrémités parées, il reste à peu près les 750 g de chair utile de la liste. Lavez-les, essuyez-les et détaillez-les dans la longueur en tranches d''environ 8 mm, peau comprise.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Empilez les tranches en couches dans une passoire en salant légèrement chaque couche au gros sel, posez dessus une assiette lestée d''un poids et laissez la chair rendre son eau 45 minutes au-dessus de l''évier. Rincez ensuite à l''eau froide et épongez chaque tranche jusqu''à ce qu''elle soit sèche au toucher : ce sel-là s''en va avec l''amertume et ne compte pas dans l''assaisonnement du plat.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pendant ce temps, comptez à peu près 750 g de tomates mûres entières pour arriver aux 633 g de pulpe annoncés. Entaillez-les en croix, plongez-les 30 secondes dans l''eau frémissante puis dans l''eau glacée, retirez peau, pédoncule et graines, et concassez grossièrement la chair.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Dans une sauteuse, faites tomber l''oignon haché et l''ail dégermé finement émincé dans un tiers de l''huile d''olive, à feu doux et sans coloration. Ajoutez la pulpe de tomate et la feuille de laurier, puis laissez réduire à découvert 25 à 30 minutes, en remuant de temps en temps, jusqu''à ce que la sauce tienne sur la cuillère. Retirez le laurier, rectifiez avec une partie du sel et du poivre, puis incorporez la moitié du basilic ciselé hors du feu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Battez l''œuf à la fourchette dans une assiette creuse et versez la chapelure dans une seconde assiette, en en réservant environ 15 g pour la finition. Passez chaque tranche d''aubergine dans l''œuf, laissez l''excédent s''égoutter, puis pressez-la des deux côtés dans la chapelure pour obtenir une couche fine et régulière.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Chauffez une large poêle avec un fond d''huile d''olive et saisissez les tranches panées par petites fournées, deux à trois minutes par face, jusqu''à une couleur noisette franche. Débarrassez-les au fur et à mesure sur du papier absorbant et ajoutez un filet d''huile entre chaque tournée plutôt que tout d''un coup.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Préchauffez le four à 190 °C. Nappez le fond d''un plat à gratin d''une louche de sauce, couchez une première rangée de tranches côte à côte, parsemez de mozzarella coupée en dés et d''un peu de parmesan râpé, puis recouvrez de sauce. Répétez l''opération en croisant le sens des tranches à chaque étage, jusqu''à épuisement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Terminez par une couche de sauce, le reste du parmesan et la chapelure réservée, puis enfournez 35 à 40 minutes : le plat doit frémir sur les bords et la surface prendre une croûte dorée. Si elle colore trop vite, posez une feuille d''aluminium pendant les dix dernières minutes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Sortez le plat et laissez-le reposer au moins 15 minutes avant de le découper, le temps que les couches se tiennent. Répartissez le basilic restant en feuilles entières juste avant de servir, pour garder son parfum.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-046', 'recipe_family', 'Parmigiana d''aubergines',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-046', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Parmigiana bianca : on supprime la tomate et on monte les aubergines dorées avec seulement les deux fromages et le basilic.','Version allégée : au lieu d''être panées et poêlées, les tranches sont badigeonnées d''huile d''olive et rôties au four à 210 °C jusqu''à coloration, ce qui supprime la chapelure et l''œuf.','Version napolitaine plus riche : on glisse à chaque étage quelques rondelles d''œuf dur et de la charcuterie coupée fin entre les aubergines et la sauce.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-046","variants":["Parmigiana bianca : on supprime la tomate et on monte les aubergines dorées avec seulement les deux fromages et le basilic.","Version allégée : au lieu d''être panées et poêlées, les tranches sont badigeonnées d''huile d''olive et rôties au four à 210 °C jusqu''à coloration, ce qui supprime la chapelure et l''œuf.","Version napolitaine plus riche : on glisse à chaque étage quelques rondelles d''œuf dur et de la charcuterie coupée fin entre les aubergines et la sauce."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-046', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('1249c934e3c0d5e3f42952e5d844a8db'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":2,"intensity":3},"dominant_flavors":["tomate cuite","fromage affiné","aubergine dorée"],"aroma_families":["herbacé","lacté","végétal grillé"],"target_textures":["fondant","filant","croûte gratinée"],"signature_ingredients":["Aubergine fraîche","Tomate fraîche mûre","Mozzarella","Parmesan affiné","Basilic frais"],"identity_guardrails":["Les aubergines doivent être dégorgées puis dorées avant montage : montées crues, le plat rend de l''eau et cesse d''être une parmigiana.","Le duo mozzarella fondante et parmesan affiné est obligatoire ; un seul fromage, ou un fromage à gratin neutre, casse l''identité du plat.","Ni béchamel ni pâtes : ce n''est pas un gratin de lasagnes, la structure repose uniquement sur les tranches d''aubergine et la sauce tomate."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Petits pois à la française', 'petits pois a la francaise', 'France', 'France',
     'meal', 'légume mijoté', 'named_traditional_dish', 'fresh_herbal',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Petits pois à la française', 'Petits pois mijotés avec de la laitue effilée, oignons blancs et beurre', ds.id, 'SRC-047',
    'Myko', 'editorial', 4, 20, 25, 'facile',
    NULL, NULL,
    'B', 'candidate', 'f0bdc4d9fc7f70d91091f94f1b7cbba7',
    '{"sweet":3,"salty":2,"acidic":0,"bitter":1,"umami":2,"heat":0,"pungency":1,"richness":3,"freshness":4,"intensity":2}'::jsonb, ARRAY['douceur végétale du petit pois','beurre frais','oignon fondu']::text[],
    ARRAY['végétal frais','lacté beurré','herbacé anisé']::text[], ARRAY['petit pois fondant qui garde sa peau','laitue tombée et soyeuse','jus court et nappant']::text[],
    ARRAY['Petit pois surgelé','Laitue fraîche','Beurre doux']::text[], ARRAY['Sans la laitue braisée avec les pois, ce ne sont plus des petits pois à la française mais de simples petits pois au beurre.','Le mouillement doit rester un fond d''eau réduit en jus court et monté au beurre : noyer les légumes dans du bouillon fait perdre au plat sa concentration sucrée.','Ni crème ni farine : la liaison vient uniquement du beurre froid incorporé hors du feu.']::text[],
    ARRAY['mijotage','réduction','émulsion']::text[], ARRAY['Version Chef Simon : pois cuits à l''anglaise puis rafraîchis à l''eau glacée, laitue étuvée séparément au beurre, les deux réunis au dernier moment et complétés de petits oignons glacés à blanc.','Version Marmiton : tous les légumes roulés à cru dans le beurre pommade avec le sel et le sucre, laissés reposer au frais une demi-heure, puis cuits en cocotte fermée par une assiette creuse remplie d''eau froide qui joue le rôle de condenseur.','Sans lardons pour une garniture entièrement maigre, en compensant par une noisette de beurre supplémentaire à la fin.','En plat unique : poser une cuisse de poulet avec os et peau sur le lit de légumes en début de cuisson et prolonger à couvert jusqu''à ce que la chair se détache.']::text[], ARRAY['lait']::text[],
    'Se garde 2 à 3 jours au réfrigérateur à 4 °C dans une boîte hermétique, et se réchauffe à couvert sur feu très doux avec une cuillère d''eau. La congélation est déconseillée : la laitue rend son eau et se défait, et les pois, déjà congelés une fois, s''écrasent à la décongélation.', '{"fridge_hours":48,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

