  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Les 400 g indiqués sont du grain net, prêt à cuire. Avec des pois surgelés, sortez simplement le sachet du congélateur : nul besoin de les décongeler. Si vous partez de pois frais, prévoyez environ 1,1 kg de cosses à l''achat, le rendement en grains tournant autour de 35 %, et écossez-les juste avant de cuisiner.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Débarrassez deux petites laitues d''environ 300 g pièce de leurs feuilles extérieures flétries et de leur pied dur : il doit vous rester à peu près 200 g de feuilles nettes. Rincez-les à l''eau froide, essorez-les soigneusement puis taillez-les en larges rubans.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pelez l''oignon blanc et débitez-le en lamelles très fines. Dégermez la gousse d''ail et hachez-la menu. Ciselez le cerfeuil et réservez-le à couvert, il n''interviendra qu''à la toute fin.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Faites tiédir un tiers du beurre dans une cocotte à fond épais, à feu très doux. Jetez-y les lardons et laissez-les rendre leur graisse cinq minutes sans qu''ils prennent couleur, puis ajoutez l''oignon et l''ail et prolongez cinq minutes : l''oignon doit devenir translucide, jamais doré.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Versez les petits pois encore glacés par-dessus, puis les rubans de laitue, le sucre, le sel et le poivre blanc. Mouillez de 10 cl d''eau seulement : le légume doit cuire dans sa propre vapeur et dans l''eau que rend la salade, pas nager dans un bouillon.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Couvrez, ramenez à léger frémissement et laissez aller de 20 à 25 minutes à petit feu, en secouant la cocotte par son anse toutes les cinq minutes plutôt qu''en remuant à la cuillère, ce qui écraserait les grains. Les pois doivent céder sans résistance sous la pression du doigt.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Découvrez et montez le feu une minute ou deux pour faire partir l''excédent de liquide, jusqu''à ce qu''il ne reste qu''un fond sirupeux au niveau des légumes. Coupez alors le feu et incorporez le beurre restant, très froid et coupé en dés, en imprimant à la cocotte un mouvement circulaire : le jus s''épaissit et se met à napper.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Rectifiez le sel, parsemez le cerfeuil ciselé au dernier moment pour qu''il garde son parfum, et servez aussitôt dans un plat creux en versant tout le jus par-dessus.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-047', 'recipe_family', 'Petits pois à la française',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-047', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Version Chef Simon : pois cuits à l''anglaise puis rafraîchis à l''eau glacée, laitue étuvée séparément au beurre, les deux réunis au dernier moment et complétés de petits oignons glacés à blanc.','Version Marmiton : tous les légumes roulés à cru dans le beurre pommade avec le sel et le sucre, laissés reposer au frais une demi-heure, puis cuits en cocotte fermée par une assiette creuse remplie d''eau froide qui joue le rôle de condenseur.','Sans lardons pour une garniture entièrement maigre, en compensant par une noisette de beurre supplémentaire à la fin.','En plat unique : poser une cuisse de poulet avec os et peau sur le lit de légumes en début de cuisson et prolonger à couvert jusqu''à ce que la chair se détache.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-047","variants":["Version Chef Simon : pois cuits à l''anglaise puis rafraîchis à l''eau glacée, laitue étuvée séparément au beurre, les deux réunis au dernier moment et complétés de petits oignons glacés à blanc.","Version Marmiton : tous les légumes roulés à cru dans le beurre pommade avec le sel et le sucre, laissés reposer au frais une demi-heure, puis cuits en cocotte fermée par une assiette creuse remplie d''eau froide qui joue le rôle de condenseur.","Sans lardons pour une garniture entièrement maigre, en compensant par une noisette de beurre supplémentaire à la fin.","En plat unique : poser une cuisse de poulet avec os et peau sur le lit de légumes en début de cuisson et prolonger à couvert jusqu''à ce que la chair se détache."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-047', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('f0bdc4d9fc7f70d91091f94f1b7cbba7'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"fresh_herbal","scores":{"sweet":3,"salty":2,"acidic":0,"bitter":1,"umami":2,"heat":0,"pungency":1,"richness":3,"freshness":4,"intensity":2},"dominant_flavors":["douceur végétale du petit pois","beurre frais","oignon fondu"],"aroma_families":["végétal frais","lacté beurré","herbacé anisé"],"target_textures":["petit pois fondant qui garde sa peau","laitue tombée et soyeuse","jus court et nappant"],"signature_ingredients":["Petit pois surgelé","Laitue fraîche","Beurre doux"],"identity_guardrails":["Sans la laitue braisée avec les pois, ce ne sont plus des petits pois à la française mais de simples petits pois au beurre.","Le mouillement doit rester un fond d''eau réduit en jus court et monté au beurre : noyer les légumes dans du bouillon fait perdre au plat sa concentration sucrée.","Ni crème ni farine : la liaison vient uniquement du beurre froid incorporé hors du feu."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Piperade', 'piperade', 'France', 'France',
     'meal', 'plat mijoté', 'named_traditional_dish', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Piperade', 'Compotée de poivrons rouges, tomates et oignons au piment d''Espelette avec des œufs', ds.id, 'SRC-048',
    'Myko', 'editorial', 4, 20, 30, 'facile',
    NULL, NULL,
    'B', 'candidate', 'cd3a6ac97516099df6bd80b5779203d7',
    '{"sweet":3,"salty":2,"acidic":2,"bitter":0,"umami":3,"heat":1,"pungency":2,"richness":3,"freshness":1,"intensity":3}'::jsonb, ARRAY['poivron doux confit','tomate mûre','ail','piment doux']::text[],
    ARRAY['végétal cuit','fruité','épicé doux']::text[], ARRAY['fondant','nappant','moelleux']::text[],
    ARRAY['Poivron rouge frais','Tomate râpée','Piment d''Espelette moulu']::text[], ARRAY['Le poivron rouge fondu longuement à l''huile d''olive est la base du plat : sans lui il ne reste qu''une sauce tomate aux œufs.','Le piment d''Espelette signe l''origine basque ; le remplacer par un piment fort ou par du paprika déplace le plat hors de son identité.','Les légumes doivent être menés jusqu''à la fondue, ni laissés croquants ni réduits en purée mixée.','Les œufs sont brouillés dans les légumes et restent crémeux : cuits en omelette prise à part, ce n''est plus une piperade.']::text[],
    ARRAY['mijotage','réduction']::text[], ARRAY['Piperade au jambon de Bayonne : deux tranches par personne poêlées à part puis coupées en lanières et mêlées à la fondue juste avant les œufs — saler alors la préparation d''une main très légère, le jambon étant déjà salé. La forme n''existe pas au catalogue Myko, l''ajout reste hors nomenclature.','Fondue de piperade sans œuf : arrêter la recette à la fin de la réduction et servir la préparation en accompagnement d''un poulet basquaise, d''une morue ou d''un thon grillé.','Piperade au piment doux vert : remplacer un tiers du poivron rouge par du piment doux d''Anglet, pour une fondue moins sucrée et plus végétale.','Œufs entiers pochés dans la fondue : creuser quatre nids dans la préparation réduite, y casser les œufs et couvrir cinq minutes plutôt que de les battre.']::text[], ARRAY['œuf']::text[],
    'La fondue de légumes seule se garde 4 jours au réfrigérateur à 4 °C dans un contenant fermé et se congèle très bien 3 mois, sa texture ne souffrant pas de la décongélation. Une fois les œufs incorporés, en revanche, consommez dans les 24 heures et ne congelez pas : les œufs brouillés rendent leur eau et deviennent granuleux. Réchauffez la fondue à feu doux avant d''y lier des œufs frais.', '{"fridge_hours":24,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
