  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Partez d''environ 1 kg de pommes de terre à chair ferme achetées avec leur peau : une fois pelées et parées, il en reste à peu près les 800 g comestibles de la liste. Détaillez-les en rondelles régulières de 5 mm, ni transparentes ni trop épaisses.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Rincez rapidement les rondelles à l''eau froide pour retirer l''amidon de surface, puis séchez-les longuement dans un linge propre. Une rondelle encore humide s''étuve au lieu de colorer : c''est le point qui décide de la réussite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Prenez une cuisse de confit d''environ 220 g avec son os et son gras, qui donnera les 75 g de chair annoncés. Tiédissez-la à feu doux pour que la graisse se détache, effilochez la viande et réservez-la, en gardant trois bonnes cuillerées de gras fondu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Faites frémir ce gras dans une poêle à fond épais ou une sauteuse large, versez-y les rondelles en couche pas trop haute et patientez deux à trois minutes sans y toucher, le temps que la première face accroche une croûte.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Salez, poivrez, puis faites-les sauter d''un mouvement de poignet toutes les deux minutes pendant une douzaine de minutes, jusqu''à obtenir une coloration dorée assez régulière sur l''ensemble.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Couvrez, baissez le feu et laissez le cœur devenir moelleux une dizaine de minutes, en secouant la poêle de temps à autre. Évitez la cuillère à ce stade, elle écraserait les rondelles ramollies.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Hachez finement l''ail dégermé avec le persil. Découvrez, dispersez cette persillade et la chair de confit effilochée, remontez le feu deux minutes tout au plus pour réveiller les parfums sans brûler l''ail, et servez aussitôt.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-049', 'recipe_family', 'Pommes de terre sarladaises',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

