  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'optional',
     'assaisonnement', true, 13);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Rincer les aubergines achetées entières, environ 350 g sur la balance, ôter le pédoncule sans les peler, les débiter en tranches d''un centimètre puis recouper ces tranches en cubes : il reste à peu près 335 g de chair prête à cuire.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Traiter les courgettes de la même façon, peau comprise, en visant des dés du même calibre que ceux d''aubergine ; 350 g bruts donnent environ 335 g une fois les deux extrémités supprimées.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Fendre les poivrons, retirer la queue, les côtes blanches et les pépins — deux poivrons rouges pesés 350 g à l''achat laissent près de 300 g de chair — puis les tailler en carrés d''un centimètre. Réserver le poivron vert paré de la même manière s''il entre dans la version choisie.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Éplucher et émincer finement les oignons, en comptant 340 g bruts pour 300 g nets, écraser les gousses d''ail du plat de la lame puis les hacher menu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Inciser la base des tomates d''une croix, les plonger dix secondes dans l''eau frémissante, les rafraîchir aussitôt, retirer peau et graines : 550 g de tomates bien mûres fournissent environ 500 g de pulpe à concasser grossièrement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Chauffer un tiers de l''huile dans une large sauteuse et y colorer les dés d''aubergine à feu vif, en remuant le moins possible pour qu''ils dorent sans se défaire, puis les débarrasser dans un plat creux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Répéter l''opération avec les courgettes, puis avec les poivrons, en versant un peu d''huile à chaque tour ; chaque légume doit conserver du mordant au cœur et attendre à part, hors de la sauteuse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Dans le même récipient, faire tomber les oignons à feu doux jusqu''à ce qu''ils deviennent translucides, ajouter l''ail une minute, puis la pulpe de tomate, le thym, le laurier, le sel et le poivre ; laisser réduire à découvert un quart d''heure, en complétant avec la tomate râpée si les tomates manquent de maturité.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Remettre tous les légumes réservés dans la sauteuse avec le jus qu''ils ont rendu, mélanger avec précaution pour ne pas les écraser, couvrir et laisser mijoter à tout petit feu une vingtaine de minutes, puis découvrir une dizaine de minutes si le fond reste trop liquide.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 10, 'Retirer les feuilles de laurier, rectifier l''assaisonnement et laisser reposer hors du feu au moins un quart d''heure : la ratatouille se sert tiède, ou réchauffée le lendemain, jamais brûlante.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-051', 'recipe_family', 'Ratatouille',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-051', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Version confite au four : les légumes sont empilés crus en couches dans une cocotte en fonte, salés et parfumés entre chaque étage, puis cuits couvercle fermé une heure à four moyen, sans une goutte d''eau ajoutée.','Version rapide en un seul récipient : tous les dés sont saisis ensemble à feu moyen puis mijotés vingt minutes, le résultat est plus fondu et moins distinct.','Ajout d''olives noires dénoyautées et tranchées dans les dix dernières minutes de cuisson.','Basilic ciselé jeté hors du feu au moment de servir, à la place ou en plus du thym.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-051","variants":["Version confite au four : les légumes sont empilés crus en couches dans une cocotte en fonte, salés et parfumés entre chaque étage, puis cuits couvercle fermé une heure à four moyen, sans une goutte d''eau ajoutée.","Version rapide en un seul récipient : tous les dés sont saisis ensemble à feu moyen puis mijotés vingt minutes, le résultat est plus fondu et moins distinct.","Ajout d''olives noires dénoyautées et tranchées dans les dix dernières minutes de cuisson.","Basilic ciselé jeté hors du feu au moment de servir, à la place ou en plus du thym."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-051', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('58ce91cdb4c20575f9c10cf6d42505f1'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":3,"salty":2,"acidic":2,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":3},"dominant_flavors":["tomate cuite","poivron confit","ail","huile d''olive"],"aroma_families":["herbacé méditerranéen","végétal grillé","aillé"],"target_textures":["dés fondants gardant leur forme","sauce courte et nappante"],"signature_ingredients":["Aubergine fraîche","Courgette fraîche","Poivron rouge frais","Tomate fraîche mûre","Huile d''olive vierge extra"],"identity_guardrails":["Les quatre légumes d''été — aubergine, courgette, poivron, tomate — sont indissociables : en retirer un fait sortir du plat.","L''huile d''olive est le seul corps gras admis ; beurre ou crème déplacent la recette vers une autre famille.","Aucun bouillon ni liquide ajouté : la liaison vient de l''eau et des sucs rendus par les légumes eux-mêmes.","Ni viande ni féculent dans la cocotte, sous peine de basculer vers un ragoût ou une poêlée composée."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Riz pilaf', 'riz pilaf', 'France', 'France',
     'meal', 'accompagnement', 'named_traditional_dish', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Riz pilaf', 'Riz nacré à l''oignon puis absorbant un bouillon de volaille, finit au beurre', ds.id, 'SRC-052',
    'Myko', 'editorial', 4, 10, 20, 'facile',
    NULL, NULL,
    'B', 'candidate', 'b5df3340e0bb15777d2d4704dbbee118',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":2}'::jsonb, ARRAY['bouillon de volaille','oignon fondu','beurre']::text[],
    ARRAY['alliacé','lacté','céréalier']::text[], ARRAY['grains égrenés et détachés','riz fondant sans être collant']::text[],
    ARRAY['Riz cru','Bouillon de volaille','Oignon jaune cru']::text[], ARRAY['Le riz doit être nacré dans le corps gras avant tout mouillement : sans cette étape d''enrobage, on obtient du riz bouillonné, plus un pilaf.','Le liquide est versé chaud et en une seule fois, à environ une fois et demie le volume du riz, puis le plat cuit à couvert sans être remué : remuer libère l''amidon et fait glisser le plat vers le risotto.','Le mouillement se fait au bouillon et non à l''eau nue : c''est lui qui porte tout l''assaisonnement du grain.']::text[],
    ARRAY['nacrage','mijotage']::text[], ARRAY['Pilaf au curry : ajouter une cuillerée de curry en poudre au moment de l''assaisonnement, sur les oignons blondis, comme le fait 750g.com.','Pilaf aux vermicelles : faire roussir une poignée de vermicelles dans le corps gras avant d''ajouter le riz rincé, version décrite par marmiton.org.','Pilaf au four aux dés de courge : ajouter des cubes de potimarron avec le bouillon et cuire 40 minutes en cocotte fermée à 180 °C.','Version végétarienne : remplacer le bouillon de volaille par un bouillon de légumes et démarrer sur des lanières de poivron revenues à l''huile.','Garniture aromatique de restaurant : ajouter des échalotes ciselées et un bouquet garni au suage, retirés avant de servir.']::text[], ARRAY['lait']::text[],
    'Se conserve 2 à 3 jours au réfrigérateur à 4 °C dans une boîte hermétique, refroidi rapidement après le service. Réchauffer à couvert avec une à deux cuillerées de bouillon ou d''eau pour réhydrater les grains. La congélation est possible 2 mois en portions étalées à plat, mais le riz ressort un peu plus mou et moins égrené au décongelage.', '{"fridge_hours":48,"eat_immediately":false,"freezable":true,"freezer_months":2,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'riz cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Riz cru', 275, 'g', 'required',
     'féculent', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'oignon jaune cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Oignon jaune cru', 120, 'g', 'required',
     'aromate', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'bouillon de volaille' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Bouillon de volaille', 500, 'ml', 'required',
     'liquide de cuisson', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'huile d olive vierge extra' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Huile d''olive vierge extra', 40, 'g', 'required',
     'matière grasse', false, 4);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'beurre doux' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Beurre doux', 25, 'g', 'required',
     'matière grasse', false, 5);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'ail cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Ail cru', 8, 'g', 'optional',
     'aromate', true, 6);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 5, 'g', 'optional',
     'assaisonnement', true, 7);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 2, 'g', 'optional',
     'assaisonnement', true, 8);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Éplucher un oignon jaune d''environ 150 g pour en obtenir 120 g de chair nette, le tailler en dés fins. Fendre les gousses d''ail, retirer le germe central et les hacher menu. Mettre le bouillon à chauffer dans une petite casserole à côté : il devra être fumant au moment du mouillement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Dans une sauteuse large à fond épais, faire tiédir l''huile d''olive avec la moitié du beurre. Y laisser fondre l''oignon et l''ail à feu doux pendant 4 à 5 minutes, en remuant : ils doivent devenir translucides et rendre leur eau sans jamais prendre de couleur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Retirer la sauteuse du feu et y verser le riz sec d''un seul coup. Mélanger une minute à la spatule pour que chaque grain se couvre de matière grasse : le riz passe du mat au brillant puis se voile de blanc laiteux. C''est le nacrage, l''étape qui empêchera les grains de coller.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Remettre sur le feu, verser le bouillon chaud d''un seul trait, saler et poivrer. Compter en volume un et demi de liquide pour un de céréale. Porter au premier frémissement en mélangeant une fois pour répartir l''oignon, puis ne plus toucher.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Poser à même le riz un disque de papier cuisson percé d''un trou au centre, coiffer du couvercle et laisser cuire 18 à 20 minutes sur la plus petite flamme, sans remuer ni soulever. Variante au four : enfourner la cocotte couverte à 200 °C pour la même durée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Hors du feu, laisser reposer 5 minutes à couvert pour que l''humidité résiduelle finisse d''être bue. Ôter le papier, déposer le reste du beurre en parcelles et égrainer délicatement à la fourchette, dents à plat. Goûter un grain, rectifier en sel et servir aussitôt.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-052', 'recipe_family', 'Riz pilaf',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-052', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Pilaf au curry : ajouter une cuillerée de curry en poudre au moment de l''assaisonnement, sur les oignons blondis, comme le fait 750g.com.','Pilaf aux vermicelles : faire roussir une poignée de vermicelles dans le corps gras avant d''ajouter le riz rincé, version décrite par marmiton.org.','Pilaf au four aux dés de courge : ajouter des cubes de potimarron avec le bouillon et cuire 40 minutes en cocotte fermée à 180 °C.','Version végétarienne : remplacer le bouillon de volaille par un bouillon de légumes et démarrer sur des lanières de poivron revenues à l''huile.','Garniture aromatique de restaurant : ajouter des échalotes ciselées et un bouquet garni au suage, retirés avant de servir.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-052","variants":["Pilaf au curry : ajouter une cuillerée de curry en poudre au moment de l''assaisonnement, sur les oignons blondis, comme le fait 750g.com.","Pilaf aux vermicelles : faire roussir une poignée de vermicelles dans le corps gras avant d''ajouter le riz rincé, version décrite par marmiton.org.","Pilaf au four aux dés de courge : ajouter des cubes de potimarron avec le bouillon et cuire 40 minutes en cocotte fermée à 180 °C.","Version végétarienne : remplacer le bouillon de volaille par un bouillon de légumes et démarrer sur des lanières de poivron revenues à l''huile.","Garniture aromatique de restaurant : ajouter des échalotes ciselées et un bouquet garni au suage, retirés avant de servir."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-052', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('b5df3340e0bb15777d2d4704dbbee118'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":2},"dominant_flavors":["bouillon de volaille","oignon fondu","beurre"],"aroma_families":["alliacé","lacté","céréalier"],"target_textures":["grains égrenés et détachés","riz fondant sans être collant"],"signature_ingredients":["Riz cru","Bouillon de volaille","Oignon jaune cru"],"identity_guardrails":["Le riz doit être nacré dans le corps gras avant tout mouillement : sans cette étape d''enrobage, on obtient du riz bouillonné, plus un pilaf.","Le liquide est versé chaud et en une seule fois, à environ une fois et demie le volume du riz, puis le plat cuit à couvert sans être remué : remuer libère l''amidon et fait glisser le plat vers le risotto.","Le mouillement se fait au bouillon et non à l''eau nue : c''est lui qui porte tout l''assaisonnement du grain."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Salade de chèvre chaud', 'salade de chevre chaud', 'France', 'France',
     'meal', 'salade composée', 'named_traditional_dish', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Salade de chèvre chaud', 'Salade verte avec tranches de fromage de chèvre gratinées sur croûtons, vinaigrette au miel', ds.id, 'SRC-053',
    'Myko', 'editorial', 4, 20, 10, 'facile',
    NULL, NULL,
    'B', 'candidate', '883b8c481a89114b916da2d81e9cb3e8',
    '{"sweet":2,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":4,"freshness":3,"intensity":3}'::jsonb, ARRAY['chèvre lactique','acidité vinaigrée','miel','fumé']::text[],
    ARRAY['lactée','herbacée','toastée']::text[], ARRAY['fromage fondant','pain croustillant','feuilles croquantes','éclats de noix']::text[],
    ARRAY['Fromage de chèvre bûche','Pain de campagne','Miel']::text[], ARRAY['Le chèvre doit arriver chaud et coulant sur l''assiette : servi froid ou émietté à cru, le plat perd son nom','Le pain de campagne grillé sous le fromage est le socle du plat, pas une garniture — sans lui il ne reste qu''une salade au fromage','La vinaigrette reste franchement acidulée pour trancher la richesse du fromage et du gras des lardons']::text[],
    ARRAY['gratinage','émulsion','saisie']::text[], ARRAY['Chèvre pané : tremper les rondelles dans l''œuf cru puis dans la chapelure de blé et les dorer à la poêle au lieu de les gratiner sur le pain','Remplacer la tomate râpée par des tomates cerises coupées en deux, comme le font la moitié des sources','Version sans porc : troquer les lardons contre des pignons de pin grillés à sec dans une poêle chaude','Ajouter de fines lamelles de poire ou quelques feuilles de basilic frais pour une note sucrée et parfumée']::text[], ARRAY['gluten','lait','fruits à coque','moutarde','sulfites']::text[],
    'La vinaigrette se garde cinq jours en bocal fermé à 4 °C et les lardons cuits deux jours au réfrigérateur. Les toasts gratinés se mangent dans la minute : réchauffés, le fromage se dessèche et le pain devient cassant. La salade assaisonnée ne se conserve pas, les feuilles tombent en une heure. Rien dans ce plat ne supporte la congélation, ni le chèvre frais qui rend son eau à la décongélation, ni la laitue.', '{"fridge_hours":48,"eat_immediately":true,"freezable":false,"freezer_months":null,"serve_cold":false,"source":"manual"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

