  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir chez le poissonnier un tronçon de saumon d''environ 800 g avec sa peau : une fois la peau détachée au couteau souple et les arêtes retirées à la pince, il reste les 600 g de chair nette de la liste, à recouper en quatre pavés réguliers de 150 g. Les garder au frais, à plat sur une assiette.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Compter à peu près 300 g d''oseille en bottes pour obtenir les 200 g de feuilles nettes : effeuiller, ôter la côte centrale en tirant la nervure de la base vers la pointe, laver à grande eau, essorer sans écraser puis tailler grossièrement en larges lanières.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Peler et hacher menu les échalotes. Les laisser suer dans le beurre à feu doux, en sauteuse large, jusqu''à ce qu''elles perdent leur mordant et deviennent translucides sans prendre la moindre couleur, environ trois minutes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Mouiller au vin blanc, remonter le feu et conduire la réduction jusqu''au sirop, presque à sec, le temps que l''odeur d''alcool s''efface complètement du dessus de la sauteuse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter la crème, ramener à petits frémissements et laisser épaissir quelques minutes, jusqu''à ce qu''un trait tracé au doigt tienne au dos de la cuillère. Rectifier en sel et en poivre à ce stade, la sauce ne se resalera plus ensuite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Jeter les lanières d''oseille dans la crème chaude, feu coupé ou très doux : elles s''affaissent et virent au vert olive en moins d''une minute. Arrêter là et réserver à couvert sans bouillir — une cuisson prolongée brunit l''oseille et efface l''acidité qui fait tout le plat.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Chauffer l''huile d''olive dans une poêle jusqu''à ce qu''elle ondule. Assaisonner les pavés sur les deux faces, les poser sans les serrer et les saisir environ trois minutes sur la première face, deux sur la seconde : le cœur doit rester légèrement translucide et se détacher en larges feuillets.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Dresser les pavés dans des assiettes chaudes, les napper de sauce à l''oseille au tout dernier moment et servir aussitôt, avec des pommes de terre vapeur ou de larges pâtes fraîches.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-055', 'recipe_family', 'Saumon à l''oseille',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-055', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Version Troisgros : aplatir les escalopes de saumon très finement entre deux feuilles, ne les saisir que vingt-cinq secondes sur une seule face et monter la sauce sur un fumet de poisson réduit.','Remplacer le vin blanc sec par la même quantité de vermouth sec, comme le fait l''une des sources du dossier.','Servir la sauce et le saumon effeuillé sur de larges pâtes fraîches, en parsemant au dressage quelques lanières d''oseille crue pour relancer l''acidité.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-055","variants":["Version Troisgros : aplatir les escalopes de saumon très finement entre deux feuilles, ne les saisir que vingt-cinq secondes sur une seule face et monter la sauce sur un fumet de poisson réduit.","Remplacer le vin blanc sec par la même quantité de vermouth sec, comme le fait l''une des sources du dossier.","Servir la sauce et le saumon effeuillé sur de larges pâtes fraîches, en parsemant au dressage quelques lanières d''oseille crue pour relancer l''acidité."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-055', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('5cd5a59983c84f5e24e69624456d270d'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":5,"freshness":3,"intensity":3},"dominant_flavors":["acidulé végétal","lacté beurré","gras iodé du saumon"],"aroma_families":["lactée","végétale acidulée","marine"],"target_textures":["chair nacrée qui se détache en feuillets","sauce nappante","oseille fondue"],"signature_ingredients":["Pavé de saumon cru, sans peau","Oseille crue","Crème fraîche liquide entière"],"identity_guardrails":["Sans oseille fondue dans la crème, ce n''est plus un saumon à l''oseille : c''est son acidité citronnée qui coupe le gras du poisson et de la crème, aucun jus de citron ne la remplace.","Le saumon est saisi à part et nappé au dernier moment, jamais cuit dans la sauce : pochée dedans, la chair grise, se dessèche et perd le nacré qui fait le plat.","La liaison se fait à la crème réduite, sans farine ni roux — une sauce épaissie à la farine transforme le plat en gratin de poisson."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Soufflé au fromage', 'souffle au fromage', 'France', 'France',
     'meal', 'plat au four', 'named_traditional_dish', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Soufflé au fromage', 'Appareil de béchamel au gruyère et emmental allégé avec des blancs montés, cuit aussitôt au four', ds.id, 'SRC-056',
    'Myko', 'editorial', 4, 20, 35, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'ad8cc13d3b8fa54788417130362746ce',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['fromage affiné','beurre','jaune d''œuf']::text[],
    ARRAY['lactée','beurrée','épicée douce']::text[], ARRAY['mousseux','aérien','croûte dorée','cœur crémeux']::text[],
    ARRAY['Œuf cru','Gruyère râpé','Emmental râpé']::text[], ARRAY['Les blancs doivent être montés à part et incorporés à la maryse en fin d''appareil : mélangés au batteur ou battus avec les jaunes, la préparation ne lève plus et devient une omelette au four.','Le fromage à pâte pressée cuite râpé, emmental et gruyère, porte tout le goût du plat : sans lui il ne reste qu''un soufflé nature.','La base doit être une béchamel épaisse au beurre et à la farine, seule assez ferme pour tenir les bulles d''air ; un liant à la fécule délayée donne une texture caoutchouteuse hors identité.','Le moule se remplit aux deux tiers au maximum et la porte du four reste fermée en début de cuisson, sinon la levée s''effondre.']::text[],
    ARRAY['béchamel','blancs en neige','cuisson au four']::text[], ARRAY['Soufflés individuels : répartir l''appareil dans six ramequins beurrés et chemisés de gruyère, cuisson ramenée à 18-20 minutes.','Fromage plus typé : remplacer tout ou partie de l''emmental par un comté vieux, ou ajouter une soixantaine de grammes de mimolette vieille comme le fait l''une des sources du dossier.','Version express sans roux relevée dans le corpus : œufs battus en omelette avec fromage blanc, fécule et fromage râpé, versés dans un moule huilé — plus dense, plus rustique, et sans véritable levée.','Soufflé aux herbes : une cuillerée de ciboulette ou d''estragon ciselé ajoutée aux jaunes, sans jamais dépasser cette dose sous peine d''alourdir l''appareil.']::text[], ARRAY['lait','œuf','gluten']::text[],
    'Un soufflé se mange dans la minute où il sort du four : il commence à retomber en deux à trois minutes et ne se rattrape pas. Les restes se gardent couverts 48 heures au réfrigérateur à 4 °C et se réchauffent 10 minutes à 150 °C, en acceptant qu''ils restent plats et se rapprochent d''un flan au fromage. L''appareil cru ne se garde pas et ne s''anticipe pas, les blancs retombant en une quinzaine de minutes. La congélation est à proscrire, avant comme après cuisson : elle détruit la mousse et fait rendre son eau à la béchamel.', '{"fridge_hours":48,"eat_immediately":true,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
