  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-057', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('1cf33ba4dc676a639fbeef89738c4e8d'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":3,"salty":3,"acidic":1,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["oignon compoté sucré","lard fumé","crème cuite"],"aroma_families":["allium doux","fumé","lacté","beurré"],"target_textures":["feuilletage croustillant","appareil crémeux tout juste pris","oignons fondants"],"signature_ingredients":["Oignon jaune cru","Crème fraîche liquide entière","Pâte feuilletée crue"],"identity_guardrails":["Sans oignon jaune longuement compoté à feu doux jusqu''au blond, ce n''est plus une tarte à l''oignon mais une quiche quelconque.","L''appareil œuf-crème doit rester salé et prendre au four : le remplacer par du fromage fondu ou une sauce blanche change de plat.","La garniture doit reposer sur un fond de pâte cuit dans un moule, jamais sur une base de pain ou de pizza."],"profile_note":null}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Terrine de campagne', 'terrine de campagne', 'France', 'France',
     'meal', 'charcuterie', 'named_traditional_dish', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Terrine de campagne', 'Hachis de porc gras et maigre avec échine, ail et persil, cuit en bain-marie et pressé froid', ds.id, 'SRC-058',
    'Myko', 'editorial', 8, 40, 120, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'f56f62307052b172c97f08fc4b30a2d9',
    '{"sweet":0,"salty":3,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":5,"freshness":1,"intensity":4}'::jsonb, ARRAY['porc gras','poivre noir','ail','eau-de-vie']::text[],
    ARRAY['herbacé','alliacé','boisé']::text[], ARRAY['farce grossière','tranche compacte','fondant gras']::text[],
    ARRAY['Échine de porc crue','Poitrine de porc crue','Cognac']::text[], ARRAY['Sans la part de gras apportee par la poitrine de porc, la farce cuit sec et s''effrite : ce n''est plus une terrine mais un pain de viande.','Sans hachage grossier, la texture devient lisse et mousseuse et le plat bascule du cote du pate de foie.','Sans cuisson lente au bain-marie puis pressage et repos de 24 heures au froid, la tranche ne se tient pas et la terrine perd son identite de charcuterie de garde.']::text[],
    ARRAY['marinade','hachage','bain-marie','pressage']::text[], ARRAY['Version volaille de chefsimon.com : une partie du porc remplacee par du Blanc de poulet cru, sans peau juste colore a la poele, taille en lanieres et monte en etages entre deux couches de farce.','Version meridionale : ajout de Poivron rouge frais confit et d''olives detaillees, incorpores en fin de melange pour garder les morceaux entiers.','Version 750g.com en bocaux : la farce est repartie dans des bocaux cuits au bain-marie 45 minutes a 200 degres, puis coloree 10 minutes a decouvert.','Version douce : quelques miettes de Pain d''epices dans la farce, qui apportent une note miel-epices et arrondissent le poivre.']::text[], ARRAY['œuf']::text[],
    'Repos obligatoire de 24 a 48 heures entre 0 et 4 degres avant la premiere tranche. Entiere et couverte de sa graisse figee, la terrine se garde 8 a 10 jours au refrigerateur ; une fois entamee, filmez la coupe au contact et consommez sous 4 jours. La congelation est possible en portions filmees jusqu''a 2 mois, mais elle detend la farce et rend la tranche plus friable a la decongelation, qui doit se faire une nuit au refrigerateur.', '{"fridge_hours":96,"eat_immediately":false,"freezable":true,"freezer_months":2,"serve_cold":true,"source":"manual"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

