     'assaisonnement', false, 10);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 5, 'g', 'optional',
     'assaisonnement', true, 11);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'thym seche' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Thym séché', 4, 'g', 'optional',
     'aromate', true, 12);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Faites vos courses en poids d''achat, pas en poids net : demandez 250 g de poitrine de porc avec sa couenne, qui ne laissera qu''environ 200 g de chair une fois paree, 300 g d''echine a desosser pour 275 g de viande, et 400 g de porc deja hache. Une tete d''ail fournit les 15 g de gousses epluchees, une petite botte de persil les 18 g de feuilles, deux gros oeufs les 100 g hors coquille.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Otez la couenne, les cartilages et les esquilles de la poitrine, desossez l''echine, puis taillez les deux viandes en cubes de deux centimetres sans retirer le gras : c''est lui qui donnera sa tenue et son moelleux a la tranche.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Reunissez les cubes dans un grand saladier avec le cognac, le sel fin, le poivre noir moulu et le thym seche, melangez a pleines mains, couvrez et laissez macerer deux heures au refrigerateur pour que l''assaisonnement penetre le muscle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Pendant ce temps, epluchez l''oignon jaune et les echalotes, hachez-les finement et faites-les fondre a feu doux dans une poele a peine huilee, sans les colorer ; ajoutez l''ail ecrase a la toute fin, debarrassez et laissez refroidir completement avant tout contact avec la viande.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Passez la viande maceree au hachoir muni de la grille de 8 mm, puis repassez seulement un gros tiers du hachis a la grille fine : ce tiers apportera le liant, le reste doit rester franchement grossier, c''est la signature d''une campagne face a une mousse de foie.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Incorporez le porc hache cru, les oeufs battus, la fondue d''aromates refroidie et le persil cisele, puis travaillez la farce a la main pendant deux a trois minutes, jusqu''a ce qu''elle devienne franchement collante et se decolle des parois en un seul bloc.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Poelez une petite boulette de farce, laissez-la tiedir et goutez-la froide avant de rectifier : crue, une farce de terrine trompe systematiquement le palais sur le sel et le poivre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Tassez la farce par couches dans un moule a terrine d''environ 1,2 litre en chassant chaque poche d''air du poing, lissez la surface en la bombant legerement, puis fermez avec le couvercle ou une double feuille d''aluminium bien serree.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Posez la terrine dans un plat creux, versez de l''eau bouillante jusqu''a mi-hauteur du moule et enfournez a 150 degres pendant deux heures ; le coeur doit atteindre 72 degres au thermometre a sonde, la terrine doit nager dans un jus clair et non rose.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 10, 'Sortez le moule du bain-marie, decouvrez-le, posez une planchette a sa taille lestee d''environ 500 g et laissez refroidir ainsi a temperature ambiante, puis reservez la terrine pressee 24 a 48 heures au refrigerateur avant de tailler la premiere tranche.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-058', 'recipe_family', 'Terrine de campagne',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-058', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Version volaille de chefsimon.com : une partie du porc remplacee par du Blanc de poulet cru, sans peau juste colore a la poele, taille en lanieres et monte en etages entre deux couches de farce.','Version meridionale : ajout de Poivron rouge frais confit et d''olives detaillees, incorpores en fin de melange pour garder les morceaux entiers.','Version 750g.com en bocaux : la farce est repartie dans des bocaux cuits au bain-marie 45 minutes a 200 degres, puis coloree 10 minutes a decouvert.','Version douce : quelques miettes de Pain d''epices dans la farce, qui apportent une note miel-epices et arrondissent le poivre.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-058","variants":["Version volaille de chefsimon.com : une partie du porc remplacee par du Blanc de poulet cru, sans peau juste colore a la poele, taille en lanieres et monte en etages entre deux couches de farce.","Version meridionale : ajout de Poivron rouge frais confit et d''olives detaillees, incorpores en fin de melange pour garder les morceaux entiers.","Version 750g.com en bocaux : la farce est repartie dans des bocaux cuits au bain-marie 45 minutes a 200 degres, puis coloree 10 minutes a decouvert.","Version douce : quelques miettes de Pain d''epices dans la farce, qui apportent une note miel-epices et arrondissent le poivre."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-058', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('f56f62307052b172c97f08fc4b30a2d9'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":0,"salty":3,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":5,"freshness":1,"intensity":4},"dominant_flavors":["porc gras","poivre noir","ail","eau-de-vie"],"aroma_families":["herbacé","alliacé","boisé"],"target_textures":["farce grossière","tranche compacte","fondant gras"],"signature_ingredients":["Échine de porc crue","Poitrine de porc crue","Cognac"],"identity_guardrails":["Sans la part de gras apportee par la poitrine de porc, la farce cuit sec et s''effrite : ce n''est plus une terrine mais un pain de viande.","Sans hachage grossier, la texture devient lisse et mousseuse et le plat bascule du cote du pate de foie.","Sans cuisson lente au bain-marie puis pressage et repos de 24 heures au froid, la tranche ne se tient pas et la terrine perd son identite de charcuterie de garde."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Thon à la basquaise', 'thon a la basquaise', 'France', 'France',
     'meal', 'plat mijoté', 'named_traditional_dish', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Thon à la basquaise', 'Thon en conserve mijoté avec une compotée de poivrons rouges et verts, tomates et ail', ds.id, 'SRC-059',
    'Myko', 'editorial', 4, 25, 35, 'facile',
    NULL, NULL,
    'B', 'candidate', '00be7aa4218789a2307a8ee72745129b',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":1,"pungency":2,"richness":2,"freshness":2,"intensity":3}'::jsonb, ARRAY['tomate cuite','poivron confit','thon salé']::text[],
    ARRAY['végétal cuit','fruité olive','piment doux']::text[], ARRAY['légumes fondants','pétales de thon effeuillés','sauce nappante']::text[],
    ARRAY['Thon au naturel en conserve, égoutté','Poivron rouge frais','Piment d''Espelette moulu']::text[], ARRAY['Sans le duo de poivrons rouge et vert fondus dans la tomate, il ne reste qu''un thon à la sauce tomate et le caractère basquaise disparaît.','Le thon doit rester en pétales entiers ajoutés hors du feu : mijoté avec les légumes, il se délite en rillettes et le plat change de nature.','Le piment d''Espelette est l''épice d''ancrage régional ; le poivre seul ou le piment fort le remplacent mal.']::text[],
    ARRAY['mijotage','réduction']::text[], ARRAY['Remplacer le piment doux vert par un second poivron vert quand la variété basque manque à l''étal.','Ajouter un œuf battu en fin de réduction pour glisser vers la piperade liée, et servir le thon dessus.','Étendre la piperade dans un plat, coucher le thon par-dessus et passer trois minutes sous le gril pour une version tiède gratinée.']::text[], ARRAY['poisson']::text[],
    'Se garde trois jours au réfrigérateur entre 0 et 4 °C dans une boîte fermée, et gagne même en rondeur le lendemain. Réchauffer en douceur à couvert, jamais à gros bouillon. La congélation est déconseillée : la chair de thon en conserve devient cotonneuse et les poivrons rendent leur eau à la décongélation.', '{"fridge_hours":72,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

