  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir environ 260 g de poivrons rouges entiers et autant de verts pour obtenir les 200 g de chair utiles de chaque couleur. Les fendre, arracher le pédoncule, secouer les graines, raser les cloisons blanches puis débiter la chair en lanières larges comme un doigt. Si le piment doux vert est de la partie, le fendre et le vider de la même façon.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Peler 230 g d''oignons pour en garder 200 g nets et les trancher en fines demi-lunes. Écraser puis hacher les gousses d''ail. Râper environ 450 g de tomates mûres, face coupée contre la grille moyenne, jusqu''à ce que la peau reste vide dans la paume : on récupère à peu près 350 g de pulpe.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Tiédir l''huile d''olive dans une sauteuse large, y verser les oignons et laisser fondre à feu modéré une bonne huitaine de minutes sans coloration, en raclant le fond de temps à autre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser les lanières de poivrons et le piment doux, remonter légèrement la flamme et poursuivre douze minutes à découvert : les bords doivent s''assouplir et prendre quelques marques dorées.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Incorporer l''ail haché, attendre une minute que le parfum monte, puis ajouter la pulpe de tomate, les herbes de Provence et le piment d''Espelette. Laisser réduire quinze minutes à petit frémissement, sans couvercle, jusqu''à ce que le jus nappe les légumes au lieu de baigner la sauteuse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Pendant ce temps, ouvrir trois boîtes de thon au naturel de 185 g net, renverser leur contenu dans une passoire et presser du dos d''une cuillère : il reste environ 390 g de chair une fois le jus de conserve évacué. La séparer en gros pétales sans la réduire en miettes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Couper le feu, glisser les pétales de thon dans la piperade et les enrober par mouvements amples de la spatule. Remettre trente secondes sur la plaque éteinte encore chaude, juste le temps de réchauffer, sans jamais laisser bouillir sous peine de dessécher les fibres.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Goûter à ce moment seulement et rectifier avec le sel fin et le poivre noir, en se souvenant que la saumure du thon a déjà salé le plat. Laisser reposer cinq minutes hors du feu avant de servir avec un riz blanc.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-059', 'recipe_family', 'Thon à la basquaise',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-059', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Remplacer le piment doux vert par un second poivron vert quand la variété basque manque à l''étal.','Ajouter un œuf battu en fin de réduction pour glisser vers la piperade liée, et servir le thon dessus.','Étendre la piperade dans un plat, coucher le thon par-dessus et passer trois minutes sous le gril pour une version tiède gratinée.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-059","variants":["Remplacer le piment doux vert par un second poivron vert quand la variété basque manque à l''étal.","Ajouter un œuf battu en fin de réduction pour glisser vers la piperade liée, et servir le thon dessus.","Étendre la piperade dans un plat, coucher le thon par-dessus et passer trois minutes sous le gril pour une version tiède gratinée."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-059', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('00be7aa4218789a2307a8ee72745129b'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":1,"pungency":2,"richness":2,"freshness":2,"intensity":3},"dominant_flavors":["tomate cuite","poivron confit","thon salé"],"aroma_families":["végétal cuit","fruité olive","piment doux"],"target_textures":["légumes fondants","pétales de thon effeuillés","sauce nappante"],"signature_ingredients":["Thon au naturel en conserve, égoutté","Poivron rouge frais","Piment d''Espelette moulu"],"identity_guardrails":["Sans le duo de poivrons rouge et vert fondus dans la tomate, il ne reste qu''un thon à la sauce tomate et le caractère basquaise disparaît.","Le thon doit rester en pétales entiers ajoutés hors du feu : mijoté avec les légumes, il se délite en rillettes et le plat change de nature.","Le piment d''Espelette est l''épice d''ancrage régional ; le poivre seul ou le piment fort le remplacent mal."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Truite aux amandes', 'truite aux amandes', 'France', 'France',
     'meal', 'plat de poisson', 'named_traditional_dish', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Truite aux amandes', 'Truite farineuse saisie au beurre, garnie d''amandes effilées torréfiées', ds.id, 'SRC-060',
    'Myko', 'editorial', 4, 20, 15, 'facile',
    NULL, NULL,
    'B', 'candidate', 'dcd9184e728bff7b6f64a98af773814e',
    '{"sweet":1,"salty":3,"acidic":2,"bitter":1,"umami":2,"heat":0,"pungency":0,"richness":4,"freshness":2,"intensity":3}'::jsonb, ARRAY['beurre noisette','amande grillée','citron']::text[],
    ARRAY['lacté','fruit à coque torréfié','agrume']::text[], ARRAY['chair floconneuse','amandes croquantes','surface farinée dorée']::text[],
    ARRAY['Truite crue','Amande effilée','Beurre doux']::text[], ARRAY['L''amande doit être effilée et blondie juste avant le service : réduite en poudre, mixée en crème ou laissée crue, le plat perd le croquant qui le nomme.','Le beurre est la matière grasse de la sauce ; remplacé par une crème ou une sauce montée à l''huile seule, ce n''est plus une truite aux amandes.','La truite est farinée puis saisie à la poêle, peau comprise ; pochée, fumée ou gratinée, elle sort de l''identité du plat.']::text[],
    ARRAY['saisie','déglaçage','torréfaction']::text[], ARRAY['Amandes blondies à sec dans une poêle sans matière grasse, puis parsemées au dernier moment sur les truites : sauce plus légère, croquant plus sec.','Version flambée : arroser les truites saisies d''un alcool ambré chauffé puis enflammé avant d''ajouter les amandes.','Version au four : filets couverts d''une crème aux amandes effilées et enfournés à couvert une vingtaine de minutes, plus moelleuse mais sans croûte dorée.','Filets levés et dépouillés plutôt que poissons entiers : cuisson ramenée à deux minutes par face, service plus facile à table.']::text[], ARRAY['poisson','fruits à coque','lait','gluten']::text[],
    'Se mange immédiatement, la sauce et les amandes perdant leur croquant en quelques minutes. Les restes se gardent 24 h à 4 °C dans une boîte hermétique, amandes séparées du poisson si possible, et se réchauffent doucement à la poêle ou se mangent froids. La truite cuite supporte mal la congélation (chair qui rend son eau) et les amandes blondies ramollissent au dégel : ne pas congeler le plat monté.', '{"fridge_hours":24,"eat_immediately":true,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'truite crue' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Truite crue', 520, 'g', 'required',
     'protéine', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'amande effilee' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Amande effilée', 65, 'g', 'required',
     'garniture', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
