      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 6, 'g', 'optional',
     'assaisonnement', true, 7);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 2, 'g', 'optional',
     'assaisonnement', true, 8);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir quatre truites entières d''environ 250 g, soit un kilo au comptoir du poissonnier : demandez-lui de les écailler, de les vider et d''ôter l''arête centrale. Une fois la tête et les nageoires retirées, il reste environ 520 g de chair, ce qui correspond à la quantité utile de la recette. Rincer à l''eau froide et sécher soigneusement avec du papier absorbant : une chair humide ne dore pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Saler et poivrer les deux faces des poissons, puis les passer dans la farine T55 étalée sur une assiette. Tapoter franchement pour ne garder qu''un voile : le surplus brûlerait dans la poêle et masquerait le goût de l''amande.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Faire chauffer l''huile d''olive avec le tiers du beurre dans une grande poêle sur feu moyen-vif. Déposer les truites côté peau et les laisser prendre couleur environ cinq minutes sans y toucher, puis les retourner deux à trois minutes côté chair. La chair doit se détacher en lamelles opaques sous la pointe d''un couteau. Réserver au chaud sur le plat de service.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Essuyer la poêle avec du papier absorbant pour retirer la farine roussie, y faire fondre le reste du beurre sur feu doux et verser les amandes effilées. Remuer sans arrêt trois à quatre minutes : elles doivent virer au blond noisette de façon homogène, un instant d''inattention suffit à les faire noircir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Retirer la poêle du feu, verser le jus de citron sur les amandes et faire tourner la poêle pour lier le beurre et l''acidité. Napper aussitôt les truites de cette sauce mousseuse et servir sans attendre, tant que les amandes croquent encore.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-060', 'recipe_family', 'Truite aux amandes',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-060', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Amandes blondies à sec dans une poêle sans matière grasse, puis parsemées au dernier moment sur les truites : sauce plus légère, croquant plus sec.','Version flambée : arroser les truites saisies d''un alcool ambré chauffé puis enflammé avant d''ajouter les amandes.','Version au four : filets couverts d''une crème aux amandes effilées et enfournés à couvert une vingtaine de minutes, plus moelleuse mais sans croûte dorée.','Filets levés et dépouillés plutôt que poissons entiers : cuisson ramenée à deux minutes par face, service plus facile à table.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
