  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'huile d olive vierge extra' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Huile d''olive vierge extra', 50, 'g', 'required',
     'pâte', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 8, 'g', 'required',
     'pâte', false, 4);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'levure boulangere seche' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Levure boulangère sèche', 8, 'g', 'required',
     'levain', false, 5);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sucre semoule' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sucre semoule', 7, 'g', 'optional',
     'levain', true, 6);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Tiédir l''eau à la main : elle doit être à peine plus chaude que la peau, jamais brûlante. Y délayer la levure sèche et, si on l''emploie, le sucre, puis laisser reposer dix minutes. Une mousse fine doit se former en surface ; si rien ne vient, la levure est morte et il vaut mieux le découvrir maintenant qu''après deux heures d''attente.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Verser la farine dans un grand saladier, y creuser un puits et disposer le sel sur le pourtour, contre la paroi. Le sel tue la levure au contact direct : c''est la seule raison de ce détour, et c''est aussi pourquoi on ne le jette pas dans l''eau levurée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Verser au centre l''eau levurée puis l''huile d''olive, et mélanger du bout des doigts en ramenant la farine vers le puits, jusqu''à obtenir une masse grossière sans farine sèche au fond. La pâte colle à ce stade, et c''est normal : à 60 % d''hydratation elle doit coller.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Renverser sur un plan de travail à peine fariné et travailler dix minutes en poussant la pâte de la paume, en la repliant sur elle-même et en pivotant d''un quart de tour. Résister à l''envie d''ajouter de la farine : elle sécherait la pâte. Le pétrissage est fini quand la boule est lisse, souple, et qu''un morceau étiré entre les doigts laisse passer la lumière sans se déchirer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Rouler en boule, déposer dans un saladier huilé, couvrir d''un linge humide et laisser pousser une à deux heures à température ambiante, jusqu''au doublement du volume. C''est du temps de repos, pas du travail : la pâte se fait seule pendant qu''on prépare autre chose.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Dégazer d''un coup de poing, diviser en deux pâtons d''environ 430 g, les bouler et les laisser détendre quinze minutes sous le linge — sans ce repos, la pâte se rétracte dès qu''on l''étale et revient toujours à sa forme.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Étaler chaque pâton à la main, du centre vers le bord, en laissant un bourrelet d''un centimètre tout autour. Au rouleau, on chasserait les bulles de gaz que la pousse vient de fabriquer et qui font l''alvéolage du bord. La pâte est alors prête à être garnie et enfournée très chaud.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-003', 'recipe_family', 'Pâte à pizza',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'RAP-003', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['À la levure fraîche, 25 g pour 500 g de farine, délayée de la même façon (marmiton)','À la farine Manitoba T00 spéciale pizza, sans pétrissage et à fermentation lente (chefsimon)','Avec 20 g de fécule de pomme de terre ajoutés à la farine, pour une pâte plus souple (marmiton)','Herbes de Provence pétries dans la pâte, et fromage râpé dans le bourrelet (marmiton)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"RAP-003","variants":["À la levure fraîche, 25 g pour 500 g de farine, délayée de la même façon (marmiton)","À la farine Manitoba T00 spéciale pizza, sans pétrissage et à fermentation lente (chefsimon)","Avec 20 g de fécule de pomme de terre ajoutés à la farine, pour une pâte plus souple (marmiton)","Herbes de Provence pétries dans la pâte, et fromage râpé dans le bourrelet (marmiton)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-003', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('32875fba1f2cc48d968398c547743058'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"nutty_savory","scores":{"sweet":1,"salty":2,"acidic":1,"bitter":0,"umami":1,"heat":0,"pungency":0,"richness":2,"freshness":0,"intensity":2},"dominant_flavors":["blé","levure","huile d’olive"],"aroma_families":["céréalier","levure","fruité olive"],"target_textures":["croûte souple","moelleux"],"signature_ingredients":["Farine de blé T55","Levure boulangère sèche"],"identity_guardrails":["Une pâte à pizza lève : sans levure boulangère et sans pousse, c''est une abaisse, pas une pizza","Elle s''étale à la main et jamais au rouleau, qui écrase l''alvéolage du bord","Aucun œuf, aucun lait, aucun beurre : ce qui gras dans cette pâte est l''huile d''olive","Hydratation autour de 60 % — une pâte sèche ne s''étend pas et se rétracte au four"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Pâte brisée', 'pate brisee', 'France', 'France',
     'meal', 'pâte à foncer', 'named_traditional_dish', 'nutty_savory',
     'candidate', 'A')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Pâte brisée', 'Deux fois plus de farine que de beurre, sablée du bout des doigts et rassemblée à l''eau froide', ds.id, 'RAP-004',
    'Myko', 'editorial', 6, 10, 0, 'facile',
    NULL, NULL,
    'A', 'candidate', 'e43f1f2801324e3036059fc5bd88c09c',
    '{"sweet":0,"salty":2,"acidic":0,"bitter":0,"umami":1,"heat":0,"pungency":0,"richness":4,"freshness":0,"intensity":2}'::jsonb, ARRAY['beurre','blé']::text[],
    ARRAY['beurre','céréalier']::text[], ARRAY['croûte de chapelure cassante','friable']::text[],
    ARRAY['Farine de blé T55','Beurre doux']::text[], ARRAY['Le beurre pèse la moitié de la farine : les sept sources du dossier le disent sans exception, et c''est ce rapport qui fait une brisée','Le beurre entre froid et en cubes ; fondu, la pâte devient dure et cesse d''être brisée','On ne pétrit pas : la pâte est rassemblée, pas travaillée','Aucun sucre dans la version de base — la brisée sucrée est une autre pâte, et le dossier la donne comme telle']::text[],
    ARRAY['sablage','repos','fonçage','mélange']::text[], ARRAY['Version sucrée, trois cuillerées à soupe de sucre dans la farine et le liquide remplacé par du lait tiède (marmiton, 750g)','Version sucrée à 50 g de sucre pour 250 g de farine (chefsimon)','Au robot, beurre très froid et farine mixés par à-coups jusqu''à la semoule (marmiton)','À la machine à pain, tous les ingrédients ensemble en programme pâte (marmiton, 750g)']::text[], ARRAY['gluten','lait','œuf']::text[],
    'Crue, la pâte se garde 3 jours au réfrigérateur, emballée serrée en disque aplati, et 3 mois au congélateur ; décongeler une nuit au réfrigérateur, jamais à température ambiante, qui ramollit le beurre en surface avant que le cœur soit dégelé. Un fond déjà foncé dans son moule se congèle aussi, et s''enfourne alors sans décongélation.', '{"fridge_hours":72,"eat_immediately":false,"freezable":true,"freezer_months":3,"serve_cold":null,"source":"manual"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'farine de ble t55' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Farine de blé T55', 250, 'g', 'required',
     'pâte', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'beurre doux' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Beurre doux', 125, 'g', 'required',
     'pâte', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'eau' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Eau', 65, 'ml', 'required',
     'pâte', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 3, 'g', 'required',
     'pâte', false, 4);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'jaune d oeuf cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Jaune d''œuf cru', 1, 'u', 'optional',
     'pâte', true, 5);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Sortir le beurre du réfrigérateur et le couper en petits cubes d''un centimètre, puis le remettre au froid le temps de peser le reste. Un beurre froid et divisé est le point de départ obligé : fondu ou mou, il enrobe la farine trop complètement et la pâte devient dure au lieu de friable.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Verser la farine et le sel dans un saladier, mélanger, puis ajouter les cubes de beurre. Les écraser entre le pouce et les doigts, sans jamais pétrir, jusqu''à obtenir une semoule grossière piquée de petits éclats de beurre encore visibles. Ce sont ces éclats qui feront les feuillets ; les faire disparaître ferait une pâte compacte.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Verser l''eau froide d''un coup, et le jaune d''œuf si on l''emploie, puis rassembler la pâte à la main en la ramenant sur elle-même. Compter vingt secondes, pas davantage : on cherche une masse qui tienne, pas une pâte homogène. Le gluten se développe en quelques tours de main, et c''est lui qui rétracte les fonds de tarte au four.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Écraser deux fois la pâte devant soi avec le talon de la main, en la poussant loin, puis la rassembler : c''est le fraisage, et il suffit à répartir le beurre sans travailler la farine. Aplatir en un disque de deux centimètres plutôt qu''en boule — un disque refroidit plus vite et s''abaisse ensuite sans se fendre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Emballer serré et laisser reposer au moins trente minutes au réfrigérateur. Ce repos fait deux choses à la fois : il raffermit le beurre, qui restera en éclats à l''abaisse, et il détend le gluten, ce qui évite qu''un fond bien étalé se rétracte de deux centimètres à la cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Abaisser sur un plan fariné en tournant d''un quart de tour entre chaque passage du rouleau, jusqu''à trois millimètres, puis foncer le moule en laissant la pâte retomber d''elle-même dans l''angle plutôt qu''en l''étirant. Une pâte étirée se rétracte toujours. Piquer le fond à la fourchette et remettre au froid en attendant la garniture.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-004', 'recipe_family', 'Pâte brisée',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
