  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Faire fondre le beurre à feu doux et le laisser tiédir hors du feu. Le verser brûlant dans la pâte cuirait les œufs en filaments qu''aucun fouet ne rattrape ensuite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Verser la farine et le sel dans un grand saladier, ainsi que le sucre si la pâte est destinée à des crêpes sucrées. Creuser un puits large au centre et y casser les quatre œufs.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Fouetter les œufs seuls dans le puits, puis élargir le mouvement pour ramener la farine du bord petit à petit. Cette progression est ce qui évite les grumeaux : ils ne naissent pas d''un mauvais fouet mais d''un liquide versé trop vite sur une farine sèche, qui s''agglomère en billes farinées à cœur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Quand la pâte forme une crème épaisse et lisse, détendre avec le lait versé en trois fois, en fouettant entre chaque, puis incorporer le beurre fondu tiède. La pâte doit napper la cuillère et couler en ruban continu ; si elle reste épaisse, c''est qu''elle attend encore du lait.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'S''il reste des grumeaux, passer la pâte au chinois plutôt que de la fouetter plus fort — au-delà d''un certain point le fouet développe le gluten et rend les crêpes caoutchouteuses au lieu de les lisser.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Couvrir et laisser reposer une heure à température ambiante. Ce repos hydrate complètement l''amidon et détend le réseau formé par le fouet : une pâte reposée s''étale plus fin, se déchire moins et donne une crêpe souple. La pâte épaissit légèrement en reposant ; la détendre alors d''un peu de lait avant de la couler.');

