      ('sensory_contract', '{"profile":"creamy_delicate","scores":{"sweet":1,"salty":1,"acidic":0,"bitter":0,"umami":1,"heat":0,"pungency":0,"richness":3,"freshness":0,"intensity":1},"dominant_flavors":["lait","beurre","œuf"],"aroma_families":["lactée","beurre","œuf cuit"],"target_textures":["nappant","moelleux"],"signature_ingredients":["Lait demi-écrémé","Farine de blé T55","Œuf cru"],"identity_guardrails":["Deux volumes de lait pour un poids de farine : cinq sources sur sept écrivent ce rapport, et c''est lui qui donne une crêpe fine","La pâte repose avant d''être coulée, faute de quoi la crêpe se déchire","Le sucre est optionnel, parce qu''une pâte sucrée d''office ne peut plus recevoir une garniture salée","Aucune levure : une crêpe n''est pas un pancake"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
