  CROSS JOIN unnest(ARRAY['Version d''été aux poivrons de trois couleurs, courgettes et deux oignons (marmiton)','Aux panais et au potimarron, relevés de trois cuillerées de sucre roux (chefsimon)','À la courge — potiron ou potimarron — à la place d''une partie des racines (marmiton)','Aux légumes primeurs : baby carottes, mini-poireaux et pointes d''asperges (750g)','À la graisse de canard plutôt qu''à l''huile d''olive (chefsimon)','Relevés d''une cuillerée à café de curcuma, de curry ou de piment en poudre (marmiton)']::text[]) AS variant(name);

