    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"RAP-010","variants":["Version d''été aux poivrons de trois couleurs, courgettes et deux oignons (marmiton)","Aux panais et au potimarron, relevés de trois cuillerées de sucre roux (chefsimon)","À la courge — potiron ou potimarron — à la place d''une partie des racines (marmiton)","Aux légumes primeurs : baby carottes, mini-poireaux et pointes d''asperges (750g)","À la graisse de canard plutôt qu''à l''huile d''olive (chefsimon)","Relevés d''une cuillerée à café de curcuma, de curry ou de piment en poudre (marmiton)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-010', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('28dc3acb34dfc0253ea903a2fddffbd3'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"earthy_herbal","scores":{"sweet":3,"salty":2,"acidic":0,"bitter":1,"umami":2,"heat":0,"pungency":1,"richness":2,"freshness":1,"intensity":3},"dominant_flavors":["légume caramélisé","ail confit","thym"],"aroma_families":["végétal grillé","aillé","thym"],"target_textures":["bords_grillés","dés fondants gardant leur forme"],"signature_ingredients":["Carotte crue","Navet cru","Ail cru entier"],"identity_guardrails":["Une seule couche sur la plaque : entassés, les légumes s''étuvent et ne rôtissent plus","Four vif à 200 °C — en dessous, ils cuisent sans colorer et le plat perd sa raison d''être","L''ail rôtit en chemise, entier : pelé, il brûle avant que les racines soient cuites","Des morceaux de taille égale, faute de quoi la même cuisson donne des crus et des brûlés"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
