  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-011', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('d2e3612aa9860f353f9a1dcac46d8d8c'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"smoky_sweet","scores":{"sweet":4,"salty":2,"acidic":1,"bitter":1,"umami":2,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":3},"dominant_flavors":["poivron grillé","huile d’olive","ail"],"aroma_families":["végétal grillé","fumé","fruité olive"],"target_textures":["fondant","sans fibre"],"signature_ingredients":["Poivron rouge frais","Poivron jaune frais","Huile d''olive vierge extra"],"identity_guardrails":["La peau doit noircir : un poivron doré ne se pèle pas et le plat rate au premier geste","Le repos sous couvercle après le four n''est pas facultatif, c''est lui qui décolle la peau","Aucun rinçage à l''eau après pelage — le jus fumé est le goût du plat","Une marinade à l''huile, pas une conserve au vinaigre : l''acide reste une variante"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
