  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Presser le citron dans un grand saladier avant même de toucher aux pommes. Éplucher, épépiner et couper les pommes en morceaux de deux centimètres, en les jetant dans le jus au fur et à mesure et en remuant : une pomme coupée brunit en trois minutes, et une compote montée sur des morceaux déjà oxydés ressort grise.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Verser les pommes et tout le jus dans une casserole à fond épais avec l''eau, le beurre et la cassonade. La casserole doit être assez large pour que les morceaux tiennent sur deux couches au plus : entassés, ceux du fond sont en bouillie quand ceux du dessus sont encore crus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Couvrir et cuire à feu doux vingt minutes, en remuant toutes les cinq minutes. Le couvercle est ce qui décide : à couvert la pomme cuit dans sa propre vapeur et n''a besoin que de six centilitres d''eau ; à découvert il en faudrait un verre, et la compote serait diluée d''autant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Retirer le couvercle dès que les morceaux se percent sans résistance et poursuivre deux à trois minutes à feu vif si le fond est encore liquide. Une compote se juge à la cuillère : elle doit tenir en tas, pas s''étaler.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter la cannelle hors du feu et écraser à la fourchette ou au presse-purée, en gardant autant de morceaux qu''on veut. Au mixeur elle devient une purée lisse et uniforme, ce qui est un autre produit — les sources qui gardent des morceaux le disent dans leur titre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Goûter tiède plutôt que brûlant, le chaud masquant le sucre : une compote qui paraît juste assez sucrée à la sortie du feu sera trop sucrée froide. Mettre en pots pendant qu''elle est chaude et fermer aussitôt si on veut la garder plus de trois jours.');

