    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'oeuf cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Œuf cru', 6, 'u', 'required',
     'base', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'eau' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Eau', 1500, 'ml', 'required',
     'cuisson', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 10, 'g', 'required',
     'eau de cuisson', false, 3);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Sortir les œufs du réfrigérateur dix minutes à l''avance, ou les tremper une minute dans un bol d''eau tiède. Un œuf glacé plongé dans l''eau bouillante se fend sur le côté et rend son blanc en filaments — c''est l''écart de température qui casse la coquille, pas la cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Porter l''eau salée à pleine ébullition dans une casserole assez large pour que les œufs tiennent en une seule couche. Le départ à l''eau BOUILLANTE et non à l''eau froide est le choix qui rend la cuisson reproductible : le compte à rebours commence à un instant précis, alors qu''un départ à froid dépend du volume d''eau et de la puissance du feu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Descendre les œufs un à un dans l''eau avec une écumoire, sans les lâcher de haut, et régler le feu pour garder un frémissement franc plutôt qu''une ébullition violente qui les entrechoque. Compter dix minutes à partir de la reprise du bouillon.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Pendant ce temps, remplir un saladier d''eau très froide avec des glaçons. C''est le geste que la page consacrée à l''œuf dur parfait traite comme son sujet, et il fait deux choses : il arrête net la cuisson, ce qui évite le cerne vert-gris autour du jaune, et il rétracte le blanc en décollant la membrane de la coquille.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Transférer les œufs dans l''eau glacée dès la dixième minute et les y laisser cinq minutes au moins. Les écaler alors sous un filet d''eau froide, en fêlant d''abord la base, où la poche d''air offre une prise ; la coquille vient en larges plaques quand l''œuf a été refroidi assez vite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Garder les œufs écalés dans une boîte fermée avec un fond d''eau froide, ou entiers dans leur coquille, qui les protège mieux. Un œuf écalé sèche et prend l''odeur du réfrigérateur en deux jours ; dans sa coquille il tient une semaine.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-015', 'recipe_family', 'Œufs durs',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'RAP-015', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Marbrés au thé et à la sauce soja : écalés à demi puis remis à infuser dans le thé salé (chefsimon)','À l''air fryer, douze minutes, sans eau du tout (750g)','Cuisson raccourcie à six minutes pour un œuf mollet, jaune coulant (chefsimon)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"RAP-015","variants":["Marbrés au thé et à la sauce soja : écalés à demi puis remis à infuser dans le thé salé (chefsimon)","À l''air fryer, douze minutes, sans eau du tout (750g)","Cuisson raccourcie à six minutes pour un œuf mollet, jaune coulant (chefsimon)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-015', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('75c3c16924ec11acf34c390ea68bb8d3'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_delicate","scores":{"sweet":0,"salty":1,"acidic":0,"bitter":0,"umami":2,"heat":0,"pungency":0,"richness":3,"freshness":0,"intensity":1},"dominant_flavors":["œuf","jaune cuit"],"aroma_families":["œuf cuit","lactée"],"target_textures":["blanc ferme et lisse","sans fibre"],"signature_ingredients":["Œuf cru","Sel fin"],"identity_guardrails":["Départ à l''eau bouillante : c''est ce qui rend les dix minutes reproductibles","Le bain glacé n''est pas facultatif — sans lui le jaune se cerne de vert et la coquille colle","Dix minutes et pas quinze : au-delà le blanc devient caoutchouteux","Frémissement et non gros bouillon, qui fait s''entrechoquer et fendre les coquilles"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
