      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Eau', 1800, 'ml', 'required',
     'cuisson', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'riz cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Riz cru', 240, 'g', 'required',
     'féculent', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 18, 'g', 'required',
     'eau de cuisson', false, 3);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Rincer le riz dans une passoire sous l''eau froide en le remuant à la main, jusqu''à ce que l''eau qui s''écoule cesse d''être laiteuse — deux à trois passages suffisent. C''est l''amidon de surface qu''on emporte, celui qui colle les grains entre eux ; sans ce rinçage, aucune cuisson ne rendra le riz détaché.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Porter l''eau salée à pleine ébullition dans un grand faitout. Six fois le volume du riz paraît excessif et c''est le principe même de la méthode créole : dans un grand volume, la température ne chute pas quand le riz arrive, et les grains circulent librement au lieu de s''écraser au fond.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Verser le riz en pluie dans l''eau bouillante et remuer une seule fois pour décoller le fond. Ne plus y toucher ensuite : chaque coup de cuillère casse la surface des grains et libère l''amidon qu''on vient de rincer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Laisser cuire à découvert et à gros frémissement une quinzaine de minutes, puis goûter un grain. Il doit être tendre de part en part sans point blanc au centre et sans se déliter entre les doigts. Le temps varie selon le riz, et c''est le grain qui décide, pas la minuterie.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Égoutter aussitôt dans une passoire large, sans rincer à l''eau froide si le riz se sert chaud — le rinçage emporte le peu de sel absorbé et refroidit tout. Secouer la passoire deux ou trois fois et laisser la vapeur s''échapper une minute : c''est elle qui, retenue, ramollirait les grains.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Verser dans un plat et aérer à la fourchette en soulevant plutôt qu''en remuant. Pour un réemploi en riz sauté ou en salade, étaler le riz en couche mince sur une plaque et le laisser refroidir à découvert : refroidi vite et à plat, il ne s''agglomère pas et se détache encore le lendemain.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-016', 'recipe_family', 'Riz créole',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'RAP-016', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Aromatisé, oignon et ail revenus à l''huile avec une cuillerée de curcuma ou de safran, puis cuisson par absorption dans 50 cl d''eau (marmiton)','Par absorption simple, un volume de riz pour deux volumes d''eau, à couvert (marmiton)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"RAP-016","variants":["Aromatisé, oignon et ail revenus à l''huile avec une cuillerée de curcuma ou de safran, puis cuisson par absorption dans 50 cl d''eau (marmiton)","Par absorption simple, un volume de riz pour deux volumes d''eau, à couvert (marmiton)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-016', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('e3c5c143502f9d2f31003558262c4812'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"nutty_savory","scores":{"sweet":1,"salty":2,"acidic":0,"bitter":0,"umami":1,"heat":0,"pungency":0,"richness":0,"freshness":0,"intensity":1},"dominant_flavors":["riz","sel"],"aroma_families":["céréalier","végétal cuit"],"target_textures":["riz_moelleux","sans fibre"],"signature_ingredients":["Riz cru","Sel fin"],"identity_guardrails":["Grande eau et égouttage : cuit par absorption, ce n''est plus un riz créole mais un pilaf","Le riz se rince avant cuisson, sans quoi les grains collent","Aucune matière grasse, aucun aromate : c''est un riz nature, et c''est ce qui le rend réemployable","On ne remue pas pendant la cuisson"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
