  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Râper l''oignon à la grosse grille plutôt que de le hacher au couteau, et presser le jus qu''il rend entre les doigts avant de l''ajouter. Râpé, il disparaît dans la farce et cuit en même temps que la viande ; en dés, il reste croquant au cœur des boulettes et les fait se fendre à la cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Mélanger dans un grand saladier la viande, l''oignon râpé, les œufs battus, la chapelure, l''ail en purée, le persil ciselé, le sel et le poivre. Travailler du bout des doigts et s''arrêter dès que le mélange est homogène : une farce pétrie longuement devient élastique et donne des boulettes fermes et rebondissantes au lieu de moelleuses.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Laisser reposer la farce quinze minutes au frais. La chapelure a besoin de ce temps pour boire le jus de la viande et de l''oignon ; roulées tout de suite, les boulettes rendent ce jus dans la poêle et se dessèchent d''autant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Former à la main des billes d''environ 35 g — le volume d''une balle de ping-pong un peu tassée — entre des paumes légèrement humides — l''eau empêche la farce de coller sans ajouter de gras. Compter une vingtaine de boulettes pour 420 g de viande. Les poser au fur et à mesure sur une assiette sans qu''elles se touchent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Chauffer l''huile à feu moyen-vif dans une grande poêle et y déposer les boulettes en une seule couche, sans les serrer. Les laisser colorer deux à trois minutes SANS y toucher : c''est la croûte qui se forme au contact qui les tient ensemble, et une boulette retournée trop tôt se déchire et laisse sa peau dans la poêle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Les rouler ensuite d''un quart de tour toutes les deux minutes en secouant la poêle plutôt qu''avec une pince, jusqu''à ce qu''elles soient dorées sur toute la surface — dix minutes environ. Baisser alors le feu, couvrir et laisser six à huit minutes pour que le cœur cuise sans que l''extérieur brûle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Vérifier une boulette en la coupant : la chair doit être grise de part en part et le jus qui perle limpide. Les débarrasser sur du papier absorbant si on les sert nature, ou les verser directement dans une sauce tomate, un curry ou un bouillon, où elles finiront de cuire en rendant leurs sucs.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-017', 'recipe_family', 'Boulettes de viande',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'RAP-017', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['À l''italienne, 100 g de parmesan ou de pecorino râpé pour quatre, avec basilic et menthe (marmiton, chefsimon, 750g)','Au pain rassis trempé dans du lait à la place de la chapelure (chefsimon, 750g)','En kefta marocaine, cumin, paprika et gingembre, mijotées dans des tomates pelées (marmiton)','Danoises, moitié porc moitié veau, servies dans une sauce au curry et aux pommes (chefsimon)','Napolitaines, avec mortadelle, raisins secs et pignons de pin, mijotées dans la tomate (750g)','À l''oignon déshydraté quand on n''a pas d''oignon frais (marmiton)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"RAP-017","variants":["À l''italienne, 100 g de parmesan ou de pecorino râpé pour quatre, avec basilic et menthe (marmiton, chefsimon, 750g)","Au pain rassis trempé dans du lait à la place de la chapelure (chefsimon, 750g)","En kefta marocaine, cumin, paprika et gingembre, mijotées dans des tomates pelées (marmiton)","Danoises, moitié porc moitié veau, servies dans une sauce au curry et aux pommes (chefsimon)","Napolitaines, avec mortadelle, raisins secs et pignons de pin, mijotées dans la tomate (750g)","À l''oignon déshydraté quand on n''a pas d''oignon frais (marmiton)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-017', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('ef9a8a0fe58ebc046eaea256ecc220f6'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"rich_savory","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["bœuf","oignon","persil"],"aroma_families":["bœuf","oignon","grillé"],"target_textures":["farce moelleuse","bords_grillés"],"signature_ingredients":["Bœuf haché cru 15 % MG","Chapelure de blé","Œuf cru"],"identity_guardrails":["L''œuf et la chapelure sont le liant : sans eux la boulette se défait dans la poêle","La farce se mélange et ne se pétrit pas, sous peine d''une boulette élastique","L''oignon est râpé et non en dés — en morceaux il fend la boulette","La base s''écrit sans fromage, pour qu''elle puisse devenir aussi bien un plat de tomate qu''un curry"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
