  CROSS JOIN unnest(ARRAY['Moitié farine, moitié semoule de blé dur fine, pour une pâte plus mordante (marmiton)','Version express, deux œufs et 20 cl d''eau pour 650 g de farine et semoule (750g)','Colorée d''une cuillerée à café de concentré de tomate dans les œufs (marmiton)','Cuites directement dans un bouillon de poule plutôt qu''à l''eau (marmiton)']::text[]) AS variant(name);

