  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-018', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('0ddd2f07b440b1b7e578a4dd67b7a6e8'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"nutty_savory","scores":{"sweet":1,"salty":2,"acidic":0,"bitter":0,"umami":1,"heat":0,"pungency":0,"richness":2,"freshness":0,"intensity":1},"dominant_flavors":["blé","œuf"],"aroma_families":["céréalier","œuf cuit"],"target_textures":["pâtes_fermes","moelleux"],"signature_ingredients":["Farine de blé T55","Œuf cru"],"identity_guardrails":["Un œuf pour 100 g de farine : c''est le rapport que trois des quatre pages écrivent","La pâte est ferme et sèche au pétrissage — souple, elle ne s''abaisse pas fin","Une heure de repos avant d''abaisser, sinon la pâte se rétracte sans fin","Trois à quatre minutes de cuisson et pas davantage"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
