  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Égoutter les pois chiches et les rincer longuement à l''eau froide pour retirer le jus de conserve, qui est salé et visqueux. Les étaler ensuite sur un torchon et les rouler doucement dessous : le séchage est l''étape qui décide de tout, un pois chiche encore humide cuit à la vapeur dans le four au lieu de rôtir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Frotter les pois chiches entre les mains ou dans le torchon pour décoller les peaux qui se détachent, et les retirer. Ce n''est pas indispensable mais c''est ce qui donne la coque nette : les peaux se séparent au four, brunissent plus vite que le reste et donnent un goût de brûlé.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Préchauffer le four à 180 °C en chaleur tournante. Mélanger les pois chiches à l''huile et au sel dans un saladier, sans l''épice pour l''instant, et les étaler en une seule couche sur une plaque garnie de papier cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
