  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-021', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('042bfcc74dc5b8cc33cbc66e6eb25eed'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"rich_savory","scores":{"sweet":0,"salty":3,"acidic":2,"bitter":0,"umami":1,"heat":0,"pungency":1,"richness":5,"freshness":3,"intensity":3},"dominant_flavors":["beurre","persil","citron"],"aroma_families":["beurre","herbacé","agrume"],"target_textures":["fondant","crémeux"],"signature_ingredients":["Beurre doux","Persil frais","Jus de citron frais"],"identity_guardrails":["Le beurre est pommade et jamais fondu : fondu, il ne reprend pas et rend son eau","Le persil est la seule herbe — avec cerfeuil et ciboulette c''est un beurre aux herbes, autre chose","Le citron entre en trois fois, faute de quoi il perle et le beurre se sépare","La rondelle se pose hors du feu, sur l''assiette"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
