      ('sensory_contract', '{"profile":"creamy_delicate","scores":{"sweet":1,"salty":2,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":0,"richness":5,"freshness":0,"intensity":2},"dominant_flavors":["œuf","crème","beurre"],"aroma_families":["œuf cuit","lactée","beurre"],"target_textures":["jaune d''œuf coulant","blanc ferme et lisse","crémeux"],"signature_ingredients":["Œuf cru","Crème fraîche liquide entière","Beurre doux"],"identity_guardrails":["Bain-marie obligatoire : sans lui les bords caoutchoutent avant que le blanc prenne","Le jaune reste coulant — un jaune cuit fait un œuf en cocotte raté, pas un autre plat","Un œuf par ramequin, les huit sources du dossier sans exception","Sortir du bain-marie dès la fin de la cuisson, sinon la chaleur résiduelle finit le jaune"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
