  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Inciser une croix sous les tomates, les ébouillanter trente secondes puis les rafraîchir à l''eau glacée et les peler. Les couper en deux, presser les graines et l''eau, et concasser la chair. C''est la demi-heure de préparation que les deux sources déclarent, et il n''y a pas de raccourci — sauf à partir d''une sauce tomate déjà faite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Fendre le piment en deux dans la longueur et retirer les graines et les cloisons blanches si l''on veut doser le feu : la capsaïcine y est concentrée bien plus que dans la chair. L''émincer finement. Peler et émincer l''ail.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chauffer l''huile d''olive dans une sauteuse à feu doux et y mettre l''ail et le piment ENSEMBLE, à froid ou presque. Il ne s''agit pas de les faire revenir mais de les faire infuser dans l''huile deux ou trois minutes, jusqu''à ce que l''ail blondisse à peine : c''est cette huile parfumée qui est le socle du plat, et un ail brûlé la rend amère pour de bon.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ajouter la tomate concassée, saler et poivrer, monter le feu jusqu''au bouillonnement puis laisser réduire quinze minutes à feu moyen, à découvert, en remuant de temps en temps. La sauce est prête quand elle nappe et qu''un sillon de spatule se referme lentement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Pendant ce temps, cuire les penne dans un grand volume d''eau bouillante salée, une à deux minutes de MOINS que le temps du paquet. Prélever une louche d''eau de cuisson avant d''égoutter : cette eau chargée d''amidon est ce qui liera la sauce aux pâtes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Verser les penne égouttées directement dans la sauteuse et les faire sauter deux minutes à feu vif avec la sauce, en ajoutant un peu d''eau de cuisson si l''ensemble s''assèche. Ce mariage final dans la poêle est ce qui distingue un plat de pâtes d''une assiette de pâtes nappées : les penne finissent de cuire dans la sauce et l''absorbent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Goûter et rectifier le piquant — un arrabbiata doit chauffer franchement en fin de bouche — puis servir aussitôt, sans fromage. Les deux sources n''en mettent pas dans la sauce, et le pecorino, quand il est là, se râpe à table.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-026', 'recipe_family', 'Penne arrabiata',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'RAP-026', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Aux tomates jaunes et tomates cerises rouges, avec basilic, parmesan et un trait de vinaigre balsamique (750g)','À la poitrine fumée et à l''oignon, 125 g pour quatre, ce qui la rapproche d''une amatriciana (marmiton)','Montée au beurre plutôt qu''à l''huile d''olive, 25 g pour quatre (marmiton)','Aux fruits de mer, 400 g de mélange marin déglacés au vin blanc (chefsimon)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"RAP-026","variants":["Aux tomates jaunes et tomates cerises rouges, avec basilic, parmesan et un trait de vinaigre balsamique (750g)","À la poitrine fumée et à l''oignon, 125 g pour quatre, ce qui la rapproche d''une amatriciana (marmiton)","Montée au beurre plutôt qu''à l''huile d''olive, 25 g pour quatre (marmiton)","Aux fruits de mer, 400 g de mélange marin déglacés au vin blanc (chefsimon)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-026', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('2c0b1c6bec6abffc281a133c65659f99'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":2,"salty":3,"acidic":3,"bitter":0,"umami":3,"heat":4,"pungency":3,"richness":2,"freshness":2,"intensity":4},"dominant_flavors":["tomate","piment","ail","huile d’olive"],"aroma_families":["tomate_cuite","piment","aillé","fruité olive"],"target_textures":["pâtes_fermes","sauce nappante"],"signature_ingredients":["Tomate fraîche mûre","Piment rouge frais","Ail cru"],"identity_guardrails":["Le piment n''est pas une option : sans lui ce n''est plus une arrabbiata mais une sauce tomate","Ail et piment infusent dans l''huile tiède, ils ne rissolent pas","Aucun oignon, aucune viande : ce sont d''autres sauces romaines","Les penne finissent leur cuisson dans la sauce, avec un peu d''eau de cuisson"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Salade César', 'salade cesar', 'États-Unis / Mexique', 'États-Unis / Mexique',
     'meal', 'salade complète', 'named_traditional_dish', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Salade César', 'Romaine, poulet grillé et croûtons à l''ail liés d''une sauce montée au jaune d''œuf, moutarde, citron et parmesan', ds.id, 'RAP-027',
    'Myko', 'editorial', 4, 15, 10, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '863720b8bd123a3b49722bbbd0b40838',
    '{"sweet":1,"salty":4,"acidic":3,"bitter":1,"umami":4,"heat":0,"pungency":3,"richness":5,"freshness":3,"intensity":4}'::jsonb, ARRAY['parmesan','moutarde','citron','poulet grillé']::text[],
    ARRAY['fromage_affiné','moutarde','agrume','grillé']::text[], ARRAY['feuilles croquantes','pain croustillant','crémeux']::text[],
    ARRAY['Laitue fraîche','Parmesan affiné','Jaune d''œuf cru']::text[], ARRAY['La sauce se monte au jaune d''œuf comme une mayonnaise : une vinaigrette n''en est pas une','Croûtons faits maison et frottés à l''ail — le sachet donne un autre plat','On assemble au dernier moment, sinon les feuilles s''affaissent et les croûtons ramollissent','Romaine et non mesclun : c''est la nervure croquante qui tient la sauce']::text[],
    ARRAY['émulsion','grillade','assemblage']::text[], ARRAY['À l''anchois, six filets à l''huile écrasés dans la sauce avec une cuillerée de sauce Worcestershire (chefsimon)','Sauce crémeuse montée sur une mayonnaise toute faite détendue au lait (marmiton)','Aux câpres, deux cuillerées à café dans la sauce (marmiton)','Au lard fumé grillé émietté sur la salade (marmiton, chefsimon)','Poulet pané au panko plutôt que grillé (chefsimon)','Version allégée, sauce à la crème légère et au citron, avec œufs durs (marmiton)']::text[], ARRAY['gluten','œuf','lait','moutarde']::text[],
    'Assemblée, elle ne se garde pas : compter vingt minutes avant que les croûtons ramollissent. En revanche chaque élément se prépare d''avance — la sauce 2 jours au réfrigérateur, les croûtons 3 jours en boîte hermétique à température ambiante, le poulet grillé 2 jours au froid — et le montage prend alors cinq minutes. La sauce contient un jaune cru : 48 heures au maximum, et à écarter pour les publics sensibles.', '{"fridge_hours":48,"eat_immediately":true,"freezable":false,"freezer_months":null,"serve_cold":true,"source":"manual"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
