  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Couper le pain en cubes de deux centimètres, croûte comprise. Les faire dorer dix minutes à 180 °C sur une plaque, ou à la poêle dans une cuillerée d''huile, en les remuant à mi-parcours. Frotter ensuite les croûtons chauds avec une demi-gousse d''ail crue : l''ail fond au contact et parfume sans jamais brûler, ce qu''il ferait si on l''ajoutait avant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Aplatir les blancs de poulet sous un film à 1,5 cm d''épaisseur régulière, les saler et les poivrer, puis les saisir cinq minutes par face dans une poêle très chaude à peine huilée. L''aplatissement n''est pas un raffinement : un blanc de poulet a une extrémité deux fois plus épaisse que l''autre, et sans cela la pointe est sèche quand le milieu est cuit.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Laisser reposer le poulet cinq minutes sur une planche avant de le trancher en aiguillettes. Découpé brûlant, il perd son jus, et c''est un poulet sec qu''on trouvera dans la salade une heure plus tard.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Monter la sauce comme une mayonnaise : le jaune d''œuf, la moutarde, le reste de l''ail en purée, le sel et le poivre dans un bol, fouettés vingt secondes, puis l''huile versée goutte à goutte au début et en filet ensuite, sans jamais cesser de fouetter. Elle doit devenir ferme et pâle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Détendre la sauce avec le jus de citron et la moitié du parmesan finement râpé. Elle doit napper la cuillère en coulant lentement : trop épaisse, elle colle en paquets sur les feuilles au lieu de les enrober. L''allonger d''une cuillerée d''eau froide si besoin.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Laver et essorer soigneusement la romaine, puis la couper en larges morceaux à la main plutôt qu''au couteau — la lame oxyde les nervures, qui brunissent en une heure. L''essorage compte autant : une feuille mouillée repousse la sauce, qui glisse au fond du saladier.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Assembler AU DERNIER MOMENT : verser les deux tiers de la sauce sur la salade, mélanger longuement pour que chaque feuille soit enrobée, puis ajouter le poulet, les croûtons et le reste de sauce. Finir par les copeaux de parmesan taillés à l''économe. Assemblée à l''avance, une César a des croûtons mous et des feuilles affaissées en vingt minutes.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-027', 'recipe_family', 'Salade César',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'RAP-027', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['À l''anchois, six filets à l''huile écrasés dans la sauce avec une cuillerée de sauce Worcestershire (chefsimon)','Sauce crémeuse montée sur une mayonnaise toute faite détendue au lait (marmiton)','Aux câpres, deux cuillerées à café dans la sauce (marmiton)','Au lard fumé grillé émietté sur la salade (marmiton, chefsimon)','Poulet pané au panko plutôt que grillé (chefsimon)','Version allégée, sauce à la crème légère et au citron, avec œufs durs (marmiton)']::text[]) AS variant(name);

