      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":4,"acidic":3,"bitter":1,"umami":4,"heat":0,"pungency":3,"richness":5,"freshness":3,"intensity":4},"dominant_flavors":["parmesan","moutarde","citron","poulet grillé"],"aroma_families":["fromage_affiné","moutarde","agrume","grillé"],"target_textures":["feuilles croquantes","pain croustillant","crémeux"],"signature_ingredients":["Laitue fraîche","Parmesan affiné","Jaune d''œuf cru"],"identity_guardrails":["La sauce se monte au jaune d''œuf comme une mayonnaise : une vinaigrette n''en est pas une","Croûtons faits maison et frottés à l''ail — le sachet donne un autre plat","On assemble au dernier moment, sinon les feuilles s''affaissent et les croûtons ramollissent","Romaine et non mesclun : c''est la nervure croquante qui tient la sauce"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
