    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Salade grecque', 'Tomates, concombre, poivron vert, oignon rouge et olives noires sous un pavé de feta, à l''origan', ds.id, 'RAP-028',
    'Myko', 'editorial', 4, 15, 0, 'facile',
    NULL, NULL,
    'B', 'candidate', '815443d7a824a03a5cf30e5c82c5076b',
    '{"sweet":2,"salty":4,"acidic":3,"bitter":2,"umami":3,"heat":0,"pungency":2,"richness":4,"freshness":5,"intensity":3}'::jsonb, ARRAY['feta','tomate','olive noire','origan']::text[],
    ARRAY['fromage_affiné','végétal frais','aromates séchés','fruité olive']::text[], ARRAY['feuilles croquantes','crémeux','oignon cru croquant']::text[],
    ARRAY['Feta','Concombre frais','Olive noire dénoyautée']::text[], ARRAY['Aucune salade verte : une salade grecque n''en porte pas, et aucune des quatre sources n''en met','La feta se pose en pavé entier sur le dessus, elle ne s''émiette pas dedans','Origan sec et rien d''autre comme herbe','Gros morceaux : coupée en dés, la salade rend son eau et s''affaisse']::text[],
    ARRAY['assemblage','dégorgement']::text[], ARRAY['En buddha bowl, sur 250 g de boulgour, avec courgette et pignons de pin (marmiton)','En salade de riz, sur 180 g de basmati, avec cœurs d''artichaut et tomates cerises (chefsimon)','Aux olives Kalamata plutôt qu''aux olives noires ordinaires (marmiton, chefsimon)','Au jus de citron et au persil plat en plus du vinaigre (750g)','Montée en panna cotta de feta, avec la salade en garniture (chefsimon)']::text[], ARRAY['lait']::text[],
    'Se mange dans les vingt minutes qui suivent l''assaisonnement : le sel tire l''eau des tomates et du concombre, et une salade grecque d''une heure baigne dans son jus. Les légumes se coupent en revanche jusqu''à 4 heures d''avance et se gardent au froid séparément, feta et assaisonnement à part. Ne se congèle pas.', '{"fridge_hours":4,"eat_immediately":true,"freezable":false,"freezer_months":null,"serve_cold":true,"source":"manual"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
