  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Sortir la mozzarella de son eau vingt minutes à l''avance et la poser sur du papier absorbant. Un fromage glacé n''a aucun goût — le lactique et le lacté ne se libèrent qu''à température ambiante — et son eau, si on la laisse, dilue l''huile en fond d''assiette.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Choisir des tomates réellement mûres, qui cèdent sous le pouce et sentent la tomate au pédoncule, et ne JAMAIS les mettre au réfrigérateur avant : le froid détruit les composés aromatiques d''une tomate de façon irréversible. Les trois sources écrivent toutes « bien mûres » ou nomment une variété ancienne, et c''est le seul vrai secret de ce plat à trois ingrédients.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Trancher les tomates et la mozzarella à un demi-centimètre d''épaisseur, avec un couteau bien aiguisé et sans appuyer — une lame émoussée écrase la tomate et lui fait rendre son jus sur la planche.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Alterner les tranches en les faisant se chevaucher sur un plat, en glissant une feuille de basilic entre certaines. Déchirer le basilic à la main plutôt que de le ciseler : la lame écrase les cellules et le fait noircir en quelques minutes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Saler les tomates seulement, jamais la mozzarella, qui est déjà salée et rendrait de l''eau. Poivrer l''ensemble. Arroser d''huile d''olive en filet puis du vinaigre balsamique en gouttes, sans mélanger — ils doivent rester lisibles à l''œil et au goût plutôt que de se fondre en vinaigrette.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Servir dans les dix minutes, à température ambiante. Une caprese ne se prépare pas d''avance : le sel tire l''eau de la tomate, le basilic noircit, et l''assiette baigne. C''est le prix de sa simplicité.');

