  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-030', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('b6eed6b1c28970336e2ece4b9c5b7f3a'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"fresh_herbal","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":3,"heat":0,"pungency":0,"richness":3,"freshness":4,"intensity":2},"dominant_flavors":["mozzarella","tomate","basilic","olive"],"aroma_families":["lactée","végétal frais","basilic","fruité olive"],"target_textures":["pâtes_fermes","crémeux","pulpe de tomate fraîche"],"signature_ingredients":["Pâtes sèches courtes","Mozzarella","Tomate cerise fraîche"],"identity_guardrails":["Pâtes cuites une minute en moins et rincées à froid : c''est la seule salade où le rinçage se justifie","L''huile entre sur les pâtes encore tièdes, sinon elles collent","Les tomates se dégorgent avant l''assemblage","Servie à température ambiante et non glacée, faute de quoi elle n''a aucun goût"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
