      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 4, 'g', 'required',
     'assaisonnement', false, 7);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'required',
     'assaisonnement', false, 8);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Retirer les premières feuilles du chou, le couper en quartiers et ôter le trognon dur au centre de chacun. Émincer ensuite en lanières AUSSI FINES QUE POSSIBLE, à la mandoline ou au couteau bien aiguisé — un chou coupé gros reste dur et sec quoi qu''on fasse ensuite, et l''épaisseur de la coupe est ce qui décide de la salade.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Saler le chou émincé et le laisser dégorger vingt minutes dans une passoire, puis le presser à la main. Ce passage, que seule la source du chou mariné pratique, est ce qui l''attendrit sans le cuire : il perd son eau, sa raideur, et cesse de délayer la sauce une heure après.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Râper la carotte à la grosse grille. Couper la pomme en fins bâtonnets ou la râper en dernier, juste avant l''assemblage, et la citronner si elle attend : elle brunit en dix minutes à l''air.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Préparer la sauce en fouettant la moutarde et le vinaigre ensemble d''abord, puis en incorporant la mayonnaise. Cet ordre compte : la moutarde et le vinaigre se lient facilement, et la mayonnaise ajoutée ensuite les absorbe sans se casser, alors que du vinaigre versé sur une mayonnaise la fait trancher.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Mélanger le chou pressé, la carotte et la pomme avec la sauce, poivrer, et travailler longuement à la main ou à la cuillère pour enrober chaque lanière. Goûter et rectifier : cette salade demande plus d''acide qu''on ne le pense, le chou et la mayonnaise l''absorbant tous les deux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Laisser reposer au moins une heure au réfrigérateur avant de servir. Contrairement aux autres salades de ce lot, celle-ci gagne à attendre : le chou continue de s''attendrir dans l''acide, et la sauce le pénètre. Elle est meilleure le lendemain.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-031', 'recipe_family', 'Salade de chou blanc',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
