  CROSS JOIN unnest(ARRAY['Aux lardons fumés, œufs durs, crème et curry, relevée de tabasco (marmiton)','Aux raisins secs et à l''oignon, 60 g de raisins pour huit (marmiton)','Au jambon d''épaule et au gruyère râpé, parfumée au cumin (marmiton)','Marinée à l''huile d''olive et au vinaigre blanc, sans mayonnaise, aux cerneaux de noix et au persil (chefsimon)','Au yaourt à la grecque, miel, moutarde en grains et huile de sésame, avec graines de courge (chefsimon)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
