  SELECT
    v_family, 3, 'Poulet au citron', 'Émincé de poulet saisi puis mijoté dans une sauce crème, citron et sauge déglacée au vin blanc', ds.id, 'RAP-034',
    'Myko', 'editorial', 4, 15, 40, 'facile',
