  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-035', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('6ce3de9b7787cd5d395b8c95dbfacce4'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":3,"salty":3,"acidic":1,"bitter":1,"umami":3,"heat":1,"pungency":3,"richness":2,"freshness":2,"intensity":3},"dominant_flavors":["poivron","poulet","gingembre","oignon"],"aroma_families":["végétal grillé","poulet","gingembre","allium"],"target_textures":["feuilles croquantes","chair_moelleuse","bords_grillés"],"signature_ingredients":["Poivron rouge frais","Blanc de poulet cru, sans peau","Gingembre frais"],"identity_guardrails":["Feu vif du début à la fin : à feu doux les poivrons compotent et le plat change de nature","Le poulet est saisi puis réservé, il ne mijote pas avec les légumes","Trois couleurs de poivron : c''est ce que la source principale annonce dans son titre","Ail et gingembre entrent en dernier, pour ne pas brûler"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
