DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Escalope de dinde à la crème', 'escalope de dinde a la creme', 'France', 'France',
     'meal', 'volaille en sauce', 'domestic_standard', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Escalope de dinde à la crème', 'Escalopes de dinde saisies, sauce échalote, champignons et crème moutardée montée dans la poêle', ds.id, 'RAP-036',
    'Myko', 'editorial', 4, 20, 10, 'facile',
    NULL, NULL,
    'B', 'candidate', '76e8ff9044858317a971946160f5861a',
    '{"sweet":1,"salty":3,"acidic":1,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":4,"freshness":0,"intensity":3}'::jsonb, ARRAY['crème','champignon','échalote','moutarde']::text[],
    ARRAY['lactée','champignon_terreux','échalote','moutarde']::text[], ARRAY['chair_moelleuse','sauce nappante','champignon_fondant']::text[],
    ARRAY['Escalope de dinde crue','Crème fraîche liquide entière','Champignon de Paris frais']::text[], ARRAY['Six minutes de cuisson pour la dinde, pas davantage : plus maigre que le poulet, elle sèche vite','Les champignons rendent leur eau à sec dans la poêle de la dinde, ce qui déglace les sucs','Crème entière et non allégée : une crème allégée tranche à la réduction','Les escalopes reviennent dans la sauce pour se réchauffer, pas pour cuire']::text[],
    ARRAY['saisie','sauté','déglaçage','liaison à la crème']::text[], ARRAY['Panées à la poudre d''amandes et à l''œuf, sur une crème d''oignons longuement fondus (marmiton)','Aux légumes et à la crème de curry, avec carottes, poivron rouge et raisins secs (marmiton)','Déglacée au vin blanc et parfumée à l''ail des ours (chefsimon)','Aux lardons fumés ajoutés aux champignons (750g)']::text[], ARRAY['lait','moutarde']::text[],
    'Se garde 2 jours au réfrigérateur. Réchauffer très doucement à la poêle, à couvert, avec une cuillerée d''eau : la dinde réchauffée fort devient cotonneuse. Se congèle 2 mois, la sauce se rattrapant d''un coup de fouet au réchauffage. Ne pas réchauffer deux fois.', '{"fridge_hours":48,"eat_immediately":false,"freezable":true,"freezer_months":2,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
