    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 2, 'g', 'required',
     'assaisonnement', false, 7);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Préchauffer le four à 200 °C. Découper quatre grandes feuilles de papier cuisson, d''au moins quarante centimètres : une papillote trop juste s''ouvre en gonflant et perd sa vapeur, qui est tout l''intérêt du procédé.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Trancher les courgettes en rondelles de trois millimètres et les tomates un peu plus épaisses. La finesse de la courgette n''est pas décorative : elle doit cuire en vingt minutes à la vapeur douce d''une papillote, ce qu''une rondelle d''un centimètre ne fait pas — et un légume encore ferme sous un poisson trop cuit est le défaut classique de ce plat.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Répartir les rondelles de courgette au centre de chaque feuille, en les faisant se chevaucher sur la taille du poisson, puis les tomates par-dessus. Saler et poivrer ce lit : il tiendra le poisson hors du jus et l''empêchera de bouillir dans l''eau des légumes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Poser un dos de cabillaud sur chaque lit, saler, poivrer, arroser d''une cuillerée d''huile d''olive et d''une cuillerée de jus de citron. Vérifier qu''il ne reste pas d''arête en passant le doigt le long du dos — le cabillaud en garde souvent deux ou trois.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Fermer chaque papillote en rabattant les deux grands bords l''un sur l''autre et en les pliant deux fois ensemble, puis en tortillant les extrémités. L''étanchéité est le seul point technique : c''est la vapeur emprisonnée qui cuit, et une papillote qui fuit rend un poisson sec.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Enfourner vingt minutes sur une plaque. Les papillotes gonflent, ce qui est le signe que la vapeur travaille ; ne pas les ouvrir pour vérifier avant la fin, chaque ouverture coûtant plusieurs minutes de cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Servir les papillotes fermées, à ouvrir dans l''assiette. Le parfum qui s''en échappe est la moitié du plat, et le jus de cuisson accumulé au fond — poisson, citron, tomate et huile — se mange avec du pain ou se verse sur du riz. Le cabillaud est cuit quand sa chair se sépare en gros feuillets nacrés sous la fourchette ; s''il résiste, refermer et remettre trois minutes.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-037', 'recipe_family', 'Papillote de cabillaud',
                            'position', req.position, 'strictness', req.strictness),
