  CROSS JOIN unnest(ARRAY['Au lieu noir plutôt qu''au cabillaud, y compris surgelé (marmiton)','Au curry de Madras, crème fleurette, céleri vert et oignons rouges (chefsimon)','Au beurre citron-gingembre, carottes et poireau, dans une feuille de brick croustillante (chefsimon)','Au concombre, à l''aneth et au fromage blanc, avec des baies roses (chefsimon)','À la moutarde et à la crème fraîche, avec poivrons et romarin (750g)','À l''orientale, au miel, cumin, coriandre et safran, avec une aumônière de légumes (750g)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
