  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-037', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('39087a971eafd7557e61c2228abf2a45'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"fresh_herbal","scores":{"sweet":2,"salty":2,"acidic":3,"bitter":0,"umami":2,"heat":0,"pungency":0,"richness":2,"freshness":4,"intensity":2},"dominant_flavors":["cabillaud","citron","courgette","tomate"],"aroma_families":["marin","agrume","végétal cuit","fruité olive"],"target_textures":["chair nacrée et moelleuse","légumes fondants"],"signature_ingredients":["Dos de cabillaud cru","Courgette fraîche","Jus de citron frais"],"identity_guardrails":["La papillote doit être hermétique : une fuite et le poisson sèche au lieu de cuire à la vapeur","Les légumes sont tranchés fin — ils cuisent moins vite que le poisson qu''ils portent","Le poisson repose SUR les légumes et ne baigne pas dans le jus","Vingt minutes et pas trente : un cabillaud trop cuit s''effrite au lieu de se détacher en feuillets"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
