  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Au miel, aux baies roses et à la moutarde, avec ail et oignon (marmiton)','Sauce aux épinards, 250 g d''épinards frais fondus dans la crème avec du vin blanc (marmiton)','Au soja cuisine et aux échalotes, sans crème laitière (marmiton)','Sauce au poivron jaune et au mascarpone, servi sur des farfalle (chefsimon)','Au sirop d''érable et au chipotle, laqué à la poêle (chefsimon)','Crème de ciboulette liée à la maïzena (chefsimon)','En salade, sur mesclun avec œufs durs, tomates cerises et citron (750g)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
