  CROSS JOIN unnest(ARRAY['Au tofu ferme, 300 g pour quatre, sautés à part et remis à la fin (marmiton)','Aux légumes de printemps : pointes d''asperges et mini-poireaux (750g)','Au miel et à la citronnelle dans la sauce soja (marmiton)','Aux oignons cébettes ciselés en finition (marmiton)']::text[]) AS variant(name);

