  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Cuire les nouilles une minute de MOINS que le temps du paquet, les rincer à l''eau froide et les égoutter à fond, puis les mélanger à un filet d''huile. Elles finiront de cuire dans le wok, et des nouilles cuites à point à l''eau deviennent molles au sauté. Le rinçage retire l''amidon qui les colle en bloc.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Mélanger dans un bol la sauce soja, le nuoc-mâm et le sucre : la sauce doit être prête avant d''allumer le feu. Le sucre n''est pas là pour sucrer mais pour équilibrer deux condiments très salés et pour laquer les nouilles au contact de la poêle chaude.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Trancher le poulet en lanières fines, détailler le brocoli en petits bouquets, émincer l''oignon, hacher l''ail et râper le gingembre. Tout doit être à portée de main : à partir de l''étape suivante, le plat se fait en huit minutes et ne laisse aucun répit.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Chauffer la moitié de l''huile à feu maximum dans un wok ou une grande poêle et saisir le poulet en une seule couche, deux minutes sans y toucher puis deux minutes en remuant, jusqu''à ce qu''il soit doré et juste cuit. Réserver.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser le reste de l''huile, jeter le brocoli et l''oignon et sauter quatre minutes à feu vif. Ajouter deux cuillerées à soupe d''eau et couvrir trente secondes : la vapeur cuit le cœur des bouquets sans que l''extérieur brûle, ce qu''un sauté à sec ne fait pas sur un légume aussi épais.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Ajouter l''ail et le gingembre, remuer trente secondes, puis les nouilles et le poulet réservé. Verser la sauce sur les bords chauds de la poêle et sauter deux à trois minutes en soulevant l''ensemble à la pince plutôt qu''en le remuant à la cuillère, ce qui casserait les nouilles.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Hors du feu, verser l''huile de sésame et ajouter la coriandre ciselée. Goûter avant de saler quoi que ce soit : entre le soja et le nuoc-mâm, le plat est presque toujours salé à point, et c''est plutôt d''un trait de citron ou d''un peu de piment qu''il manque.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-042', 'recipe_family', 'Nouilles sautées au poulet',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'RAP-042', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Aux nouilles de riz plutôt qu''aux nouilles de blé (marmiton)','Aux nouilles soba de sarrasin, avec noix de cajou (chefsimon)','Au pak choï et aux germes de soja frais, relevé de sriracha (marmiton)','À la julienne de légumes toute prête, 500 g pour quatre (marmiton)','Au poivron vert, poireau et germes de soja, à l''huile d''arachide (marmiton)','Au sirop d''érable ou au miel à la place du sucre, avec graines de sésame (chefsimon)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"RAP-042","variants":["Aux nouilles de riz plutôt qu''aux nouilles de blé (marmiton)","Aux nouilles soba de sarrasin, avec noix de cajou (chefsimon)","Au pak choï et aux germes de soja frais, relevé de sriracha (marmiton)","À la julienne de légumes toute prête, 500 g pour quatre (marmiton)","Au poivron vert, poireau et germes de soja, à l''huile d''arachide (marmiton)","Au sirop d''érable ou au miel à la place du sucre, avec graines de sésame (chefsimon)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-042', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('7d0f7c0e8a8a9a35fcc2386d30096ea3'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"spicy_umami","scores":{"sweet":2,"salty":4,"acidic":1,"bitter":1,"umami":5,"heat":1,"pungency":3,"richness":3,"freshness":2,"intensity":4},"dominant_flavors":["sauce soja","gingembre","poulet","sésame grillé"],"aroma_families":["soja","gingembre","poulet","sésame_toasté"],"target_textures":["pâtes_fermes","feuilles croquantes","chair_moelleuse"],"signature_ingredients":["Nouille de blé chinoise sèche","Blanc de poulet cru, sans peau","Sauce soja"],"identity_guardrails":["Nouilles cuites une minute en moins et rincées : elles finissent dans le wok","Feu maximum, et le poulet saisi puis réservé — jamais cuit avec les légumes","La sauce est mélangée d''avance et versée sur les bords chauds, pas au centre","L''huile de sésame et la coriandre arrivent hors du feu"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Wok de légumes', 'wok de legumes', 'Chine / cuisine domestique internationale', 'Chine / cuisine domestique internationale',
     'meal', 'wok de légumes', 'domestic_standard', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Wok de légumes', 'Carottes, poivrons, courgette et haricots verts sautés à feu vif, laqués soja, vinaigre et sésame', ds.id, 'RAP-043',
    'Myko', 'editorial', 4, 15, 15, 'facile',
    NULL, NULL,
    'B', 'candidate', 'c64d6923945832a7fc1656048e5f0b39',
    '{"sweet":3,"salty":3,"acidic":2,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":2,"freshness":3,"intensity":3}'::jsonb, ARRAY['légumes sautés','sauce soja','sésame','ail']::text[],
    ARRAY['végétal grillé','soja','sésame_toasté','aillé']::text[], ARRAY['feuilles croquantes','bords_grillés']::text[],
    ARRAY['Carotte crue','Poivron rouge frais','Sauce soja']::text[], ARRAY['Feu maximum et poêle brûlante avant l''huile : tiède, les légumes bouillent','Les légumes entrent par ordre de densité, du plus dur au plus tendre','Les haricots verts sont blanchis à part, ou pris surgelés','Ils restent croquants — cuits à cœur, ce n''est plus un wok']::text[],
    ARRAY['blanchiment','sauté','cuisson courte']::text[], ARRAY['En sauce aigre-douce, au sucre roux, vinaigre de vin, ketchup et ananas, liée à la fécule (750g)','Aux champignons de Paris et aux germes de soja, au vinaigre de xérès (750g)','Au miel, gingembre, citron et arachides concassées (marmiton)','À la coriandre moulue et aux noix de cajou (750g)','Aux légumes surgelés — poivrons, haricots verts, courgettes — sans étape de blanchiment (marmiton)','Aux poivrons verts en plus du rouge et du jaune (750g)']::text[], ARRAY['soja','sésame']::text[],
    'Se garde 2 jours au réfrigérateur mais perd son croquant : le meilleur réemploi est froid, en salade avec un trait de vinaigre, ou dans un wrap. Se réchauffe uniquement à la poêle très chaude et brièvement. Ne se congèle pas — les légumes en ressortent détrempés, ce qui est précisément le contraire du plat.', '{"fridge_hours":48,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

