  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Tailler tous les légumes AVANT d''allumer le feu, en morceaux d''épaisseur voisine : carottes en bâtonnets fins, haricots verts équeutés et coupés en deux, poivrons en lanières, courgette en demi-rondelles, oignon en demi-lunes. Un wok se conduit sans jamais quitter la poêle des yeux, et la mise en place est ce qui rend cela possible.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Blanchir les haricots verts trois minutes à l''eau bouillante salée puis les rafraîchir à l''eau glacée. C''est le seul légume du plat qui ne peut pas cuire au sauté seul : il lui faudrait dix minutes, pendant lesquelles tout le reste brûlerait. Des haricots verts SURGELÉS remplacent cette étape à eux seuls, la source la plus détaillée les proposant expressément.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chauffer le wok ou une grande poêle à feu maximum jusqu''à ce qu''une goutte d''eau y danse, puis verser l''huile. Un wok tiède fait bouillir les légumes dans leur eau ; c''est la faute qui transforme ce plat en poêlée molle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Jeter les carottes seules et sauter deux minutes en remuant sans arrêt, puis ajouter les poivrons et l''oignon pour trois minutes, puis la courgette pour deux, puis les haricots blanchis et l''ail pour une minute. Cet ordre suit la densité : la carotte est le plus dur, la courgette le plus tendre, et tout arrive cuit en même temps.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ne pas surcharger : si la poêle est pleine à ras bord, faire deux fournées. Un wok fonctionne par contact direct avec le métal brûlant, et une masse de légumes trop épaisse fait chuter la température de cent degrés en dix secondes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Verser la sauce soja et le vinaigre sur les bords chauds de la poêle, remuer trente secondes pour enrober, poivrer, et goûter avant de saler — la sauce soja en apporte déjà beaucoup. Les légumes doivent être marqués par endroits et rester croquants sous la dent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Parsemer de sésame grillé hors du feu et servir aussitôt. Un wok de légumes qui attend dix minutes au chaud a perdu exactement ce qu''on est allé chercher en le faisant sauter.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-043', 'recipe_family', 'Wok de légumes',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'RAP-043', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['En sauce aigre-douce, au sucre roux, vinaigre de vin, ketchup et ananas, liée à la fécule (750g)','Aux champignons de Paris et aux germes de soja, au vinaigre de xérès (750g)','Au miel, gingembre, citron et arachides concassées (marmiton)','À la coriandre moulue et aux noix de cajou (750g)','Aux légumes surgelés — poivrons, haricots verts, courgettes — sans étape de blanchiment (marmiton)','Aux poivrons verts en plus du rouge et du jaune (750g)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"RAP-043","variants":["En sauce aigre-douce, au sucre roux, vinaigre de vin, ketchup et ananas, liée à la fécule (750g)","Aux champignons de Paris et aux germes de soja, au vinaigre de xérès (750g)","Au miel, gingembre, citron et arachides concassées (marmiton)","À la coriandre moulue et aux noix de cajou (750g)","Aux légumes surgelés — poivrons, haricots verts, courgettes — sans étape de blanchiment (marmiton)","Aux poivrons verts en plus du rouge et du jaune (750g)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-043', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('c64d6923945832a7fc1656048e5f0b39'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":3,"salty":3,"acidic":2,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":2,"freshness":3,"intensity":3},"dominant_flavors":["légumes sautés","sauce soja","sésame","ail"],"aroma_families":["végétal grillé","soja","sésame_toasté","aillé"],"target_textures":["feuilles croquantes","bords_grillés"],"signature_ingredients":["Carotte crue","Poivron rouge frais","Sauce soja"],"identity_guardrails":["Feu maximum et poêle brûlante avant l''huile : tiède, les légumes bouillent","Les légumes entrent par ordre de densité, du plus dur au plus tendre","Les haricots verts sont blanchis à part, ou pris surgelés","Ils restent croquants — cuits à cœur, ce n''est plus un wok"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Galette complète', 'galette complete', 'France (Bretagne)', 'France (Bretagne)',
     'meal', 'galette', 'named_traditional_dish', 'nutty_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Galette complète', 'Galette de sarrasin garnie de jambon, gruyère et d''un œuf cuit sur place, bords rabattus en carré', ds.id, 'RAP-044',
    'Myko', 'editorial', 4, 20, 10, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '69097699586830ee88db9e0dfed31f44',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":0,"richness":4,"freshness":0,"intensity":3}'::jsonb, ARRAY['sarrasin','jambon','gruyère fondu','œuf']::text[],
    ARRAY['céréalier','porc','fromage_affiné','beurre']::text[], ARRAY['croûte souple','fromage fondant','jaune d''œuf coulant']::text[],
    ARRAY['Farine de sarrasin','Jambon blanc cuit','Œuf cru']::text[], ARRAY['Farine de sarrasin, pas de froment : c''est ce qui fait une galette et non une crêpe','Hydratation à 230 % — deux fois celle d''une pâte à crêpes','Le jaune reste coulant et visible au centre du carré','Deux heures de repos au minimum, sans quoi la galette se déchire']::text[],
    ARRAY['mélange','repos','poêlage','pliage']::text[], ARRAY['Pâte coupée de froment, 150 g de blé pour 500 g de sarrasin (marmiton)','Sur galette de sarrasin achetée, garnie et réchauffée à la poêle (chefsimon)','À l''emmental râpé plutôt qu''au gruyère (chefsimon)','Parfumée d''un brin de thym sur la garniture (750g)']::text[], ARRAY['gluten','œuf','lait']::text[],
    'La pâte crue se garde 3 jours au réfrigérateur, ce qui est son intérêt : on en coule quatre le mardi et quatre le jeudi. Les galettes NATURE se gardent 3 jours empilées avec un papier entre chacune, et se congèlent 2 mois — elles se garnissent alors directement à la poêle, ce qui ramène le plat à cinq minutes. La galette garnie, elle, ne se conserve pas : l''œuf coulant est le plat.', '{"fridge_hours":null,"eat_immediately":true,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed+manual"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
