    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'required',
     'assaisonnement', false, 8);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Verser la farine de sarrasin et le sel dans un saladier, creuser un puits et y casser UN œuf — le cinquième de la liste, les quatre autres étant pour la garniture. Ajouter un quart de l''eau et fouetter énergiquement au centre jusqu''à obtenir une pâte épaisse et parfaitement lisse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Battre cette pâte épaisse deux bonnes minutes avant de la détendre. Le sarrasin n''a pas de gluten et la pâte ne peut pas devenir élastique : ce battage sert à emprisonner de l''air, ce qui donne à la galette ses dentelles à la cuisson. C''est un geste que les crêpiers bretons appellent « faire chanter la pâte ».');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Détendre avec le reste de l''eau en trois fois, en fouettant entre chaque, puis ajouter 20 g de beurre fondu tiède. La pâte doit être très liquide, comme une crème à peine épaissie — 230 % d''hydratation, ce qui est près du double d''une pâte à crêpes de froment.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Couvrir et laisser reposer au moins deux heures au réfrigérateur, une nuit si possible. Le sarrasin a besoin de ce temps pour s''hydrater complètement ; une pâte non reposée donne des galettes qui se déchirent au décollage et gardent un goût farineux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Chauffer une grande poêle ou une crêpière à feu vif, la beurrer légèrement, verser une louche de pâte et l''étaler d''un mouvement tournant du poignet ou à la raclette. La galette doit être FINE et translucide par endroits ; épaisse, elle ne croustillera jamais et le pli se cassera.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Laisser cuire deux minutes, jusqu''à ce que les bords se soulèvent et brunissent, retourner et compter trente secondes. Retourner à nouveau côté déjà cuit dessous, poser une noisette de beurre, répartir 30 g de jambon en morceaux et 25 g de gruyère au centre, puis casser un œuf au milieu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Rabattre les quatre bords vers le centre pour former un carré, en laissant le jaune apparent. Baisser le feu, couvrir une minute et demie : le blanc prend par la chaleur du dessous et la vapeur, tandis que le jaune reste coulant. Poivrer le jaune et servir aussitôt, la galette n''attendant pas.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-044', 'recipe_family', 'Galette complète',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'RAP-044', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Pâte coupée de froment, 150 g de blé pour 500 g de sarrasin (marmiton)','Sur galette de sarrasin achetée, garnie et réchauffée à la poêle (chefsimon)','À l''emmental râpé plutôt qu''au gruyère (chefsimon)','Parfumée d''un brin de thym sur la garniture (750g)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
