  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Couper le poulet en petits dés d''un centimètre et le mélanger au paprika, au cumin, au sel et au poivre. Les laisser dix minutes s''imprégner pendant qu''on taille le reste — les épices sèches ont besoin d''humidité pour cesser d''être poudreuses, et le jus du poulet suffit. On peut aussi partir de 300 g de restes de poulet rôti, déjà cuits, qu''on épice de la même façon : c''est ce que font deux des sept sources et c''est la voie la plus rapide.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Émincer l''oignon rouge finement, épépiner la tomate et la couper en dés. L''épépinage est aussi important ici que dans un wrap : une tortilla détrempée ne dore pas et se déchire au retournement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chauffer la moitié de l''huile à feu vif dans une poêle et saisir le poulet quatre à cinq minutes en remuant, jusqu''à ce qu''il soit doré et cuit à cœur. Ajouter l''oignon deux minutes, puis la tomate une minute, et débarrasser. La garniture doit être SÈCHE : s''il reste du jus dans la poêle, le laisser s''évaporer avant de débarrasser.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Essuyer la poêle et la reposer sur feu moyen, SANS matière grasse. Poser une tortilla, répartir un quart du fromage sur une moitié seulement, puis un quart de la garniture, puis rabattre l''autre moitié par-dessus. Le fromage va sous ET sur la garniture si l''on veut : c''est lui qui colle les deux faces ensemble.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Laisser dorer deux à trois minutes, jusqu''à ce que le dessous porte des taches brunes et que le fromage commence à filer sur les bords. Appuyer légèrement avec une spatule pour souder. Retourner d''un geste franc et compter deux minutes de plus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'La poêle sèche est le point qui surprend et qui compte : une quesadilla huilée frit au lieu de griller, la tortilla boit le gras et devient molle en refroidissant. L''huile de la liste sert à la garniture, pas au pliage.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Faire glisser sur une planche et laisser reposer une minute avant de couper en trois ou quatre triangles : coupée brûlante, le fromage fondu coule par la tranche. Servir aussitôt, avec un guacamole ou un coulis de tomate à part.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-046', 'recipe_family', 'Quesadillas au poulet',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'RAP-046', 'missing_required_count', v_missing), 'open');
  END IF;

