  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"RAP-046","variants":["Aux restes de poulet rôti et de légumes rôtis, sans cuisson préalable (marmiton)","Tex-mex, aux deux poivrons et au guacamole crémeux, avec chips nachos (chefsimon)","Au maïs et à la tomme de Savoie, sur tortillas maison (chefsimon)","Au coulis de tomate et à l''emmental, épices mexicaines (750g)","Au maïs, cheddar, épinards frais et sauce piquante (750g)","Au fromage frais ail et fines herbes, salsa de tomates et maïs (750g)","Au cheddar et à la crème liquide, relevé de curry (marmiton)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-046', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('3e6f0494eea04f6afb879f4bb955352a'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"smoky_sweet","scores":{"sweet":2,"salty":3,"acidic":1,"bitter":1,"umami":4,"heat":1,"pungency":2,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["fromage fondu","paprika","poulet","oignon rouge"],"aroma_families":["fromage_affiné","paprika","poulet","grillé"],"target_textures":["croûte croustillante","fromage fondant"],"signature_ingredients":["Tortilla de blé","Emmental râpé","Blanc de poulet cru, sans peau"],"identity_guardrails":["La poêle est SÈCHE : huilée, la tortilla frit et ramollit au lieu de griller","La garniture doit être sèche avant le pliage, sinon la galette se déchire","Le fromage est ce qui soude les deux faces — sans lui la quesadilla s''ouvre","Une minute de repos avant de couper, faute de quoi le fromage s''échappe"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
