  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Laver les épinards dans un grand volume d''eau froide en les soulevant à la main plutôt qu''en versant l''eau dessus : le sable tombe au fond et les feuilles restent en surface. Recommencer jusqu''à ce que l''eau soit claire, ce qui demande deux ou trois bains. Équeuter les feuilles dont la tige est épaisse, en pliant la feuille en deux et en tirant la côte.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire fondre la moitié du beurre dans une très grande sauteuse ou une cocotte, à feu vif, et y jeter les épinards par poignées, en ajoutant la suivante dès que la précédente est retombée. Un kilo de feuilles ne rentre dans aucune poêle au départ et tient dans un bol à la fin ; c''est l''affaire de quatre à cinq minutes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Saler dès que tout est tombé et laisser cuire trois minutes de plus à feu vif, à découvert. Le sel accélère le rendu d''eau, et c''est ce qu''on veut ici : mieux vaut qu''elle sorte maintenant, dans la poêle, que plus tard dans l''assiette.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser les épinards dans une passoire et LES PRESSER franchement avec le dos d''une louche, jusqu''à ce qu''ils ne rendent plus rien. On en tire un grand verre d''eau. Cette étape est la seule qui sépare des épinards à la crème d''une soupe verte, et c''est aussi celle que tout le monde escamote.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Hacher grossièrement les épinards pressés au couteau — ils forment une masse compacte qu''il faut défaire — et les remettre dans la sauteuse essuyée, avec le reste du beurre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Ajouter la crème, la muscade râpée et le poivre, et laisser mijoter deux à trois minutes à feu moyen en remuant, jusqu''à ce que la crème enrobe sans être liquide. Goûter et rectifier le sel généreusement : l''épinard en absorbe beaucoup et un plat sous-salé y paraît métallique.');

  INSERT INTO quality.review_tasks
