  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['À l''ail écrasé, une gousse pour six (marmiton)','À l''échalote fondue et au fromage frais à tartiner plutôt qu''à la crème (750g)','Aux épinards surgelés, un kilo, sans lavage ni équeutage (750g)','Liés au parmesan et à un jaune d''œuf, pour servir sur des pâtes (marmiton)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"RAP-047","variants":["À l''ail écrasé, une gousse pour six (marmiton)","À l''échalote fondue et au fromage frais à tartiner plutôt qu''à la crème (750g)","Aux épinards surgelés, un kilo, sans lavage ni équeutage (750g)","Liés au parmesan et à un jaune d''œuf, pour servir sur des pâtes (marmiton)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-047', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('bfc633112876657925acabc981562109'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_delicate","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":2,"umami":2,"heat":0,"pungency":1,"richness":4,"freshness":2,"intensity":2},"dominant_flavors":["épinard","crème","muscade","beurre"],"aroma_families":["végétal cuit","lactée","muscade","beurre"],"target_textures":["fondant","crémeux"],"signature_ingredients":["Épinard frais","Crème fraîche épaisse","Muscade moulue"],"identity_guardrails":["Les épinards se pressent après cuisson : sans cela le plat est une soupe verte","Un kilo de frais donne 200 g cuits — la quantité déclarée n''est pas une erreur","La muscade est le marqueur du plat, elle n''est pas facultative","Aucune farine ni béchamel : la crème seule lie"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Haricots verts à l''ail', 'haricots verts a l ail', 'France', 'France',
     'meal', 'accompagnement', 'domestic_standard', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Haricots verts à l''ail', 'Haricots verts blanchis puis sautés au beurre avec de l''ail émincé, croquants et brillants', ds.id, 'RAP-048',
    'Myko', 'editorial', 4, 10, 12, 'facile',
    NULL, NULL,
    'B', 'candidate', '06ca2a0e2f66c45f97e54153d75b6b99',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":1,"heat":0,"pungency":3,"richness":3,"freshness":3,"intensity":2}'::jsonb, ARRAY['haricot vert','ail','beurre']::text[],
    ARRAY['végétal cuit','aillé','beurre']::text[], ARRAY['feuilles croquantes','fondant']::text[],
    ARRAY['Haricot vert cru','Ail cru','Beurre doux']::text[], ARRAY['Blanchiment à grande eau très salée puis eau glacée : c''est ce qui tient le vert','L''ail est émincé en lamelles et blondit sans brunir — brûlé, il gâche tout le plat','Les haricots restent croquants sous la dent','On saute deux minutes, on ne mijote pas']::text[],
    ARRAY['blanchiment','refroidissement','sauté']::text[], ARRAY['À la crème et au fromage frais ail et fines herbes, avec des lardons (marmiton)','Au citron et au sirop d''érable, saupoudrés de levure alimentaire et de graines de chanvre (chefsimon)','Aux haricots verts surgelés, sans équeutage ni blanchiment (marmiton)','En accompagnement d''un gigot, avec oignons, thym et laurier (marmiton)']::text[], ARRAY['lait']::text[],
    'Blanchis et refroidis, les haricots se gardent 3 jours au réfrigérateur et se sautent en trois minutes le moment venu : c''est la bonne façon de préparer ce plat d''avance. Sautés, ils se gardent 2 jours mais perdent leur croquant. Les haricots blanchis se congèlent 6 mois, égouttés et à plat.', '{"fridge_hours":48,"eat_immediately":false,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed+manual"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'haricot vert cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Haricot vert cru', 500, 'g', 'required',
     'légume', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'beurre doux' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Beurre doux', 30, 'g', 'required',
     'matière grasse', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'ail cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Ail cru', 18, 'g', 'required',
     'aromatique', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 4, 'g', 'required',
     'assaisonnement', false, 4);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'required',
     'assaisonnement', false, 5);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Équeuter les haricots en cassant l''extrémité du pédoncule à la main : la queue vient, le fil aussi s''il y en a. Garder l''autre pointe, qui est fine et ne gêne pas. Des haricots verts SURGELÉS, déjà équeutés, dispensent entièrement de cette étape et de la suivante — ils sont blanchis à l''usine et se jettent directement dans la poêle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Porter à ébullition un grand volume d''eau très salée — une cuillerée à soupe de sel par litre — et y plonger les haricots. Le volume compte : jetés dans peu d''eau, ils la refroidissent et cuisent en la remontant, ce qui les fait virer au kaki. Compter huit à dix minutes selon leur grosseur, en goûtant à huit.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Les égoutter et les plonger AUSSITÔT dans un saladier d''eau glacée. Ce choc thermique fait deux choses : il arrête la cuisson au point exact où on l''a laissée, et il fixe la chlorophylle, ce qui donne le vert franc qu''un haricot laissé refroidir seul perd en dix minutes. Les égoutter à fond dès qu''ils sont froids.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Éplucher les gousses d''ail, retirer le germe et les émincer en fines lamelles plutôt que de les hacher : en lamelles elles dorent sans brûler et se mangent, hachées elles brûlent en trente secondes dans une poêle chaude.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Faire mousser le beurre dans une grande poêle à feu moyen, y jeter l''ail et le laisser blondir une minute à peine, en remuant. L''ail doit devenir doré et parfumé ; s''il brunit, tout recommencer — un ail brûlé rend le plat amer et rien ne le rattrape.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Ajouter les haricots égouttés, monter le feu et sauter deux à trois minutes en secouant la poêle, jusqu''à ce qu''ils soient brillants, chauds et marqués par endroits. Saler, poivrer, goûter et servir aussitôt : ils tiennent leur croquant dix minutes et pas davantage.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-048', 'recipe_family', 'Haricots verts à l''ail',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'RAP-048', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
