    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'required',
     'assaisonnement', false, 10);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Inciser une croix sous les tomates, les ébouillanter trente secondes, les rafraîchir et les peler. On peut s''en dispenser si l''on passe la soupe au moulin à légumes, qui retiendra les peaux — mais pas si l''on mixe au plongeant, qui les hache en confettis rêches impossibles à rattraper.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Couper les tomates en quartiers en gardant leur jus. Émincer l''oignon et écraser l''ail. Chauffer l''huile d''olive dans une casserole et faire suer l''oignon six minutes à feu moyen sans le colorer, puis ajouter l''ail pour trente secondes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Ajouter les tomates et le sucre, monter le feu et laisser réduire cinq minutes à découvert en remuant. Cette réduction préalable, avant tout mouillement, est ce qui concentre le goût : les tomates rendent leur eau et la perdent tout de suite au lieu de la diluer dans le bouillon.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser le bouillon, saler légèrement — il sale déjà — et laisser mijoter vingt minutes à couvert, à petits frémissements. Le sucre a eu le temps d''agir : goûter à ce stade et en rajouter une pincée si la soupe pique, ce qui dépend entièrement des tomates.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter le basilic déchiré, laisser infuser deux minutes hors du feu, puis mixer longuement. Passer au chinois si l''on veut la finesse d''un velouté ; laisser tel quel si l''on préfère une soupe qui a du corps.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Remettre sur feu doux, incorporer la crème sans faire bouillir — une soupe de tomate est acide et l''acidité fait trancher la crème à ébullition. Poivrer, rectifier le sel et servir, éventuellement avec des croûtons frottés à l''ail.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-051', 'recipe_family', 'Soupe de tomates',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'RAP-051', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
