  CROSS JOIN unnest(ARRAY['Au pistou et au parmesan, avec poireau et céleri dans le bouillon (marmiton)','Aux vermicelles cuits dedans, sur une base de concentré de tomate (marmiton)','Express, à la boîte de tomates pelées, avec une pointe de cumin (marmiton)','Au riz basmati cuit dans la soupe, à l''origan et au basilic séchés (chefsimon)','Aux tomates cerises rôties au four quarante minutes avec l''ail, servie avec des tartines grillées (750g)','Aux courgettes et à la pulpe de tomate en conserve, en version d''hiver (750g)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"RAP-051","variants":["Au pistou et au parmesan, avec poireau et céleri dans le bouillon (marmiton)","Aux vermicelles cuits dedans, sur une base de concentré de tomate (marmiton)","Express, à la boîte de tomates pelées, avec une pointe de cumin (marmiton)","Au riz basmati cuit dans la soupe, à l''origan et au basilic séchés (chefsimon)","Aux tomates cerises rôties au four quarante minutes avec l''ail, servie avec des tartines grillées (750g)","Aux courgettes et à la pulpe de tomate en conserve, en version d''hiver (750g)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:RAP-051', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('732d683f8ef7a9bcd6b48e8c7a7cab0e'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":3,"salty":3,"acidic":4,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":2,"freshness":3,"intensity":3},"dominant_flavors":["tomate","basilic","oignon","crème"],"aroma_families":["tomate_cuite","basilic","oignon","lactée"],"target_textures":["velouté lisse","nappant"],"signature_ingredients":["Tomate fraîche mûre","Bouillon de volaille","Basilic frais"],"identity_guardrails":["Les tomates se pèlent si l''on mixe au plongeant : les peaux hachées sont rêches et irrattrapables","Le sucre n''est pas un sucrant mais un correcteur d''acidité","Les tomates réduisent cinq minutes AVANT le bouillon","La crème n''entre jamais dans une soupe qui bout — l''acide la ferait trancher"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Chou-fleur rôti', 'chou fleur roti', 'France / cuisine domestique internationale', 'France / cuisine domestique internationale',
     'meal', 'accompagnement', 'domestic_standard', 'earthy_herbal',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Chou-fleur rôti', 'Bouquets de chou-fleur huilés au paprika et à l''ail, rôtis à four vif jusqu''aux pointes brunies', ds.id, 'RAP-052',
    'Myko', 'editorial', 4, 15, 30, 'facile',
    NULL, NULL,
    'B', 'candidate', '335a63693b4a5ff24d3bd5f90df9e0c4',
    '{"sweet":3,"salty":3,"acidic":0,"bitter":2,"umami":3,"heat":1,"pungency":2,"richness":3,"freshness":1,"intensity":3}'::jsonb, ARRAY['chou-fleur rôti','paprika','ail']::text[],
    ARRAY['végétal grillé','paprika','aillé']::text[], ARRAY['bords_grillés','bouquets fondants']::text[],
    ARRAY['Chou-fleur frais','Paprika doux','Huile d''olive vierge extra']::text[], ARRAY['Four très vif, 220 °C : en dessous le chou-fleur sèche sans brunir','Une seule couche, faces coupées contre la plaque','Les pointes doivent brunir franchement — c''est là que le soufre devient sucre','Bouquets et non chou entier : c''est ce qui ramène la cuisson de soixante à trente minutes']::text[],
    ARRAY['rôtissage','cuisson au four']::text[], ARRAY['Entier, badigeonné de beurre et rôti soixante à soixante-quinze minutes (marmiton, chefsimon)','En tranches épaisses, huilées au pinceau et parsemées de paprika fumé (chefsimon)','Aux deux moutardes, sauce soja, estragon et vinaigre de xérès (chefsimon)','Au curcuma, servi avec une crème de tahini au citron et une sauce miel-citron (marmiton)','À l''air fryer, trente minutes, avec ail et paprika (marmiton)','Au curry plutôt qu''au paprika (chefsimon)']::text[], ARRAY[]::text[],
    'Se garde 3 jours au réfrigérateur en boîte fermée, refroidi à découvert d''abord. Se réchauffe huit minutes à 220 °C et retrouve son croustillant, ce qui est rare. Excellent froid le lendemain, en salade avec des pois chiches rôtis et un filet de citron. Se congèle mal — le chou-fleur rôti décongelé est mou et aqueux.', '{"fridge_hours":72,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'chou fleur frais' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Chou-fleur frais', 700, 'g', 'required',
     'légume', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'huile d olive vierge extra' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Huile d''olive vierge extra', 60, 'ml', 'required',
     'matière grasse', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'ail cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Ail cru', 10, 'g', 'required',
     'aromatique', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'persil frais' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Persil frais', 10, 'g', 'required',
     'aromate', false, 4);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 6, 'g', 'required',
     'assaisonnement', false, 5);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'paprika doux' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Paprika doux', 5, 'g', 'required',
     'épice', false, 6);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 2, 'g', 'required',
     'assaisonnement', false, 7);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Acheter un chou-fleur d''environ 1,2 kg avec ses feuilles : paré, il rendra les 700 g de bouquets que la liste déclare. Retirer les feuilles extérieures, couper le trognon et détacher les bouquets, puis fendre les plus gros pour que tous fassent environ trois centimètres. Les petites feuilles tendres se rôtissent avec le reste et deviennent croustillantes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Sécher les bouquets si le chou a été lavé, en les roulant dans un torchon. C''est la règle de tout légume rôti : mouillé, il cuit à la vapeur de sa propre eau et sort pâle et mou, quel que soit le four.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Préchauffer le four à 220 °C en chaleur tournante, avec la plaque à l''intérieur. Un chou-fleur posé sur une plaque déjà brûlante se saisit au contact, ce qui donne la face caramélisée qui fait tout l''intérêt de ce plat.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Mélanger les bouquets dans un saladier avec l''huile, le sel, le poivre, le paprika et l''ail écrasé, à la main et longuement, jusqu''à ce que chaque morceau brille et soit coloré par l''épice. Un mélange fait sur la plaque laisse toujours des bouquets nus, qui restent blancs.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Étaler en une seule couche sur la plaque chaude, en posant les faces coupées CONTRE le métal — ce sont elles qui brunissent. Laisser de l''espace entre les bouquets : entassés, ils s''étuvent et ne rôtissent jamais.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Rôtir trente minutes en retournant à mi-cuisson. Le chou-fleur est prêt quand les pointes sont franchement brunes, presque noires par endroits, et qu''une lame traverse un bouquet sans effort. Ce brunissement paraît excessif et il ne l''est pas : c''est là que le chou-fleur cesse d''être soufré et devient sucré et noiseté.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Parsemer de persil ciselé à la sortie du four et servir aussitôt. Si les bouquets doivent attendre, les laisser sur la plaque à découvert plutôt que de les couvrir, la vapeur ramollissant en cinq minutes ce que le four a mis une demi-heure à sécher.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-052', 'recipe_family', 'Chou-fleur rôti',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
