    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Entier, badigeonné de beurre et rôti soixante à soixante-quinze minutes (marmiton, chefsimon)','En tranches épaisses, huilées au pinceau et parsemées de paprika fumé (chefsimon)','Aux deux moutardes, sauce soja, estragon et vinaigre de xérès (chefsimon)','Au curcuma, servi avec une crème de tahini au citron et une sauce miel-citron (marmiton)','À l''air fryer, trente minutes, avec ail et paprika (marmiton)','Au curry plutôt qu''au paprika (chefsimon)']::text[]) AS variant(name);

