      ('sensory_contract', '{"profile":"earthy_herbal","scores":{"sweet":3,"salty":3,"acidic":0,"bitter":2,"umami":3,"heat":1,"pungency":2,"richness":3,"freshness":1,"intensity":3},"dominant_flavors":["chou-fleur rôti","paprika","ail"],"aroma_families":["végétal grillé","paprika","aillé"],"target_textures":["bords_grillés","bouquets fondants"],"signature_ingredients":["Chou-fleur frais","Paprika doux","Huile d''olive vierge extra"],"identity_guardrails":["Four très vif, 220 °C : en dessous le chou-fleur sèche sans brunir","Une seule couche, faces coupées contre la plaque","Les pointes doivent brunir franchement — c''est là que le soufre devient sucre","Bouquets et non chou entier : c''est ce qui ramène la cuisson de soixante à trente minutes"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
