  CROSS JOIN unnest(ARRAY['À l''escalope de poulet, panure au parmesan et à la poudre d''amande, sans chapelure (chefsimon)','Chapelure de biscottes écrasées à la place de la chapelure du commerce (marmiton)','Panure aromatisée d''un mélange d''origan et de thym séchés (chefsimon)','Servie sur un lit de roquette avec des dés de tomate, huile d''olive et basilic (marmiton)','Accompagnée de coquillettes gratinées à la mozzarella et d''une sauce de tomates cerises (750g)']::text[]) AS variant(name);

