     'finition', false, 10);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Délayer la levure dans l''eau à température ambiante, ajouter la farine puis le sel, et pétrir dix minutes jusqu''à une pâte lisse et élastique. Avec un gramme de levure pour un demi-kilo de farine, la pousse est longue et c''est voulu : le temps fait ici le travail que ferait sinon la quantité, et donne une mie alvéolée que la levée rapide ne donne pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Bouler la pâte, la couvrir et la laisser lever six à huit heures à température ambiante, ou toute une nuit au réfrigérateur. Une pâte qui a poussé longtemps s''étale à la main sans se rétracter ; une pâte pressée résiste et revient sur elle-même dès qu''on la lâche.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Émincer les oignons en fines lamelles et les faire compoter dans la moitié de l''huile d''olive à feu doux, vingt minutes, à couvert puis à découvert, jusqu''à ce qu''ils soient translucides et sucrés. Trois oignons et demi pour quatre parts font une couche épaisse : ce n''est pas un aromate, c''est la base de la garniture, et elle doit être cuite avant d''entrer au four sinon elle reste crue et piquante.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Pendant ce temps, monder les tomates, les épépiner et les couper en gros dés, puis les faire réduire dix minutes à feu vif dans une poêle à part avec l''ail haché et le thym effeuillé. Sept cents grammes de tomates fraîches rendent beaucoup d''eau ; posées crues sur la pâte, elles la noient.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Diviser la pâte en deux pâtons et les étaler à la main sur des plaques huilées, en poussant l''air du centre vers le bord pour garder une bordure épaisse. Le rouleau écrase les bulles que la longue pousse a formées et donne une pâte plate et sèche : ici, on étire du bout des doigts.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Étaler la compotée de tomate, répartir les oignons, poser les filets d''anchois en croix ou en rayons et arroser du reste d''huile d''olive. Les anchois se posent avant cuisson et non après : leur sel a besoin des dix minutes de four pour se diffuser dans la tomate, sinon on ne rencontre que des points salés.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Enfourner à 250 °C, four bien préchauffé, dix à quinze minutes selon la puissance, jusqu''à ce que la bordure soit boursouflée et tachée de brun. Ne pas saler la garniture : les anchois s''en chargent, et le sel de la pâte est déjà haut. Servir aussitôt, coupée en parts.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-006', 'recipe_family', 'Pizza napolitaine',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-006', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Version italienne : coulis de tomate et mozzarella di bufala sur la même pâte, origan sec et basilic frais, sans oignon ni anchois (chefsimon)','Huile d''olive pimentée en finition à la place de l''huile d''olive nature (chefsimon)','Pâte laissée à fermenter 24 heures au froid, avec la même dose de levure (chefsimon)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-006","variants":["Version italienne : coulis de tomate et mozzarella di bufala sur la même pâte, origan sec et basilic frais, sans oignon ni anchois (chefsimon)","Huile d''olive pimentée en finition à la place de l''huile d''olive nature (chefsimon)","Pâte laissée à fermenter 24 heures au froid, avec la même dose de levure (chefsimon)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-006', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('2cf432415e664db04466573bd9896b47'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":3,"salty":4,"acidic":3,"bitter":1,"umami":5,"heat":0,"pungency":2,"richness":2,"freshness":1,"intensity":4},"dominant_flavors":["anchois","oignon compoté","tomate cuite","thym"],"aroma_families":["marin","oignon_compoté","tomate_cuite","thym"],"target_textures":["croûte alvéolée","légumes fondants","contraste_léger"],"signature_ingredients":["Anchois à l''huile, égoutté","Oignon jaune cru","Tomate fraîche mûre"],"identity_guardrails":["Aucune des deux sources retenues ne met de fromage : cette napolitaine-là n''en porte pas, et en ajouter en ferait une autre pizza","Les oignons se comptent en centaines de grammes et se compotent avant : crus, ils restent piquants et ne fondent pas en dix minutes de four","Les anchois entrent avant la cuisson pour que leur sel se diffuse dans la tomate","Tomates fraîches réduites à la poêle, jamais posées crues : elles noieraient la pâte"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Patatas bravas', 'patatas bravas', 'Espagne', 'Espagne',
     'meal', 'accompagnement', 'named_traditional_dish', 'smoky_sweet',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Patatas bravas', 'Cubes de pommes de terre frits, servis avec une sauce tomate relevée au vinaigre', ds.id, 'VAR-009',
    'Myko', 'editorial', 4, 20, 30, 'facile',
    NULL, NULL,
    'B', 'candidate', 'd1bc76c38152abea297f5f0007bd69de',
    '{"sweet":2,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":3,"pungency":2,"richness":3,"freshness":1,"intensity":4}'::jsonb, ARRAY['paprika fumé','tomate réduite','vinaigre','pomme de terre frite']::text[],
    ARRAY['fumé','tomate_cuite','piment','ail']::text[], ARRAY['croûte croustillante','intérieur_fondant_ou_crémeux','sauce_nappante']::text[],
    ARRAY['Pomme de terre crue, épluchée','Paprika fumé','Tomate fraîche mûre']::text[], ARRAY['Le paprika fumé entre hors du feu : cuit, il devient amer et la sauce est perdue','Double friture obligatoire — une seule passe donne soit un cœur cru, soit une croûte molle','Les cubes se cassent au couteau plutôt que se trancher : les faces rompues retiennent la sauce','La sauce se verse au moment de servir, jamais en cuisine, sous peine de détremper la croûte']::text[],
    ARRAY['compotage','réduction','mixage','friture en deux bains']::text[], ARRAY['Rôties au four à l''huile d''olive plutôt que frites, avec une sauce alioli à côté (chefsimon)','Sauce montée au tabasco, de cinq à douze gouttes selon les pages (marmiton, chefsimon, 750g)','Piment d''Espelette entier épépiné et émietté, ou en purée, à la place du cayenne (marmiton, 750g)','Version au ketchup relevé de paprika, sans sauce cuite (750g)','Sauce brava au poivron rouge : un poivron compoté avec l''oignon avant mixage, laurier, thym et romarin (chefsimon)']::text[], ARRAY[]::text[],
    'La sauce brava se garde 5 jours au réfrigérateur en bocal fermé et se congèle 3 mois : c''est elle qui prend le temps, et la préparer d''avance ramène le plat à un quart d''heure. Les pommes de terre frites ne se gardent pas — elles ramollissent en une heure — mais la première friture peut se faire la veille : les cubes précuits se conservent 24 heures au réfrigérateur et se terminent en trois minutes de second bain. Le plat monté ne se réchauffe pas.', '{"fridge_hours":null,"eat_immediately":true,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed+manual"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
