  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Émincer l''oignon et l''ail, les faire fondre à feu doux dans l''huile d''olive une dizaine de minutes sans coloration, puis ajouter les tomates coupées en dés avec le sucre et le sel. La pincée de sucre n''est pas là pour sucrer : elle corrige l''acidité des tomates de plein champ, qui deviendrait mordante en réduisant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Laisser réduire vingt minutes à découvert, jusqu''à ce que la sauce ait perdu son eau et qu''un sillon tracé au fond de la casserole reste ouvert. Ajouter alors le paprika fumé et le piment de Cayenne hors du feu, puis le vinaigre. Le paprika ne supporte pas le feu vif : il vire à l''amer en quelques secondes et rien ne le rattrape ensuite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Mixer la sauce jusqu''à obtenir une texture lisse et nappante, puis goûter et rectifier le vinaigre. La sauce doit être franchement relevée, plus que ce qui paraît raisonnable à la cuillère : elle sera répartie sur un demi-kilo de pomme de terre neutre qui va tout absorber.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Éplucher les pommes de terre et les tailler en cubes irréguliers de trois centimètres, en cassant chaque morceau au couteau plutôt qu''en le tranchant net. Les faces rompues offrent plus de surface et accrochent la sauce ; des cubes lisses la laissent glisser.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Rincer les cubes à l''eau froide jusqu''à ce que l''eau soit claire, puis les sécher soigneusement dans un linge. L''amidon de surface fait coller les morceaux entre eux dans l''huile ; l''eau restée dessus fait projeter le bain et empêche la croûte de se former.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Frire les pommes de terre en deux fois dans l''huile chaude : une première cuisson de huit minutes à 150 °C pour cuire l''intérieur, un repos hors du feu, puis une seconde de trois minutes à 180 °C pour la croûte. La double cuisson est le seul moyen d''avoir un cœur fondant sous une croûte sèche ; en une seule passe, l''un des deux est toujours sacrifié.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Égoutter sur une grille, saler aussitôt, dresser en tas dans un plat creux et napper de sauce au dernier moment. La sauce se verse à table et non en cuisine : posée cinq minutes trop tôt, elle ramollit la croûte qu''on vient de passer un quart d''heure à obtenir.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-009', 'recipe_family', 'Patatas bravas',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-009', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Rôties au four à l''huile d''olive plutôt que frites, avec une sauce alioli à côté (chefsimon)','Sauce montée au tabasco, de cinq à douze gouttes selon les pages (marmiton, chefsimon, 750g)','Piment d''Espelette entier épépiné et émietté, ou en purée, à la place du cayenne (marmiton, 750g)','Version au ketchup relevé de paprika, sans sauce cuite (750g)','Sauce brava au poivron rouge : un poivron compoté avec l''oignon avant mixage, laurier, thym et romarin (chefsimon)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-009","variants":["Rôties au four à l''huile d''olive plutôt que frites, avec une sauce alioli à côté (chefsimon)","Sauce montée au tabasco, de cinq à douze gouttes selon les pages (marmiton, chefsimon, 750g)","Piment d''Espelette entier épépiné et émietté, ou en purée, à la place du cayenne (marmiton, 750g)","Version au ketchup relevé de paprika, sans sauce cuite (750g)","Sauce brava au poivron rouge : un poivron compoté avec l''oignon avant mixage, laurier, thym et romarin (chefsimon)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-009', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('d1bc76c38152abea297f5f0007bd69de'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"smoky_sweet","scores":{"sweet":2,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":3,"pungency":2,"richness":3,"freshness":1,"intensity":4},"dominant_flavors":["paprika fumé","tomate réduite","vinaigre","pomme de terre frite"],"aroma_families":["fumé","tomate_cuite","piment","ail"],"target_textures":["croûte croustillante","intérieur_fondant_ou_crémeux","sauce_nappante"],"signature_ingredients":["Pomme de terre crue, épluchée","Paprika fumé","Tomate fraîche mûre"],"identity_guardrails":["Le paprika fumé entre hors du feu : cuit, il devient amer et la sauce est perdue","Double friture obligatoire — une seule passe donne soit un cœur cru, soit une croûte molle","Les cubes se cassent au couteau plutôt que se trancher : les faces rompues retiennent la sauce","La sauce se verse au moment de servir, jamais en cuisine, sous peine de détremper la croûte"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Paella aux fruits de mer', 'paella aux fruits de mer', 'Espagne', 'Espagne',
     'meal', 'plat de fruits de mer', 'named_traditional_dish', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Paella aux fruits de mer', 'Riz bomba cuit au bouillon avec moules, calamars et crevettes', ds.id, 'VAR-011',
    'Myko', 'editorial', 6, 60, 45, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '6e0ed91f819bd0b293e7d3816d67a477',
    '{"sweet":2,"salty":4,"acidic":2,"bitter":1,"umami":5,"heat":0,"pungency":1,"richness":2,"freshness":2,"intensity":4}'::jsonb, ARRAY['safran','fruits de mer','tomate réduite','poivron']::text[],
    ARRAY['safran','marin','tomate_cuite','ail']::text[], ARRAY['grains séparés','socarrat croustillant','chair nacrée et moelleuse']::text[],
    ARRAY['Riz bomba cru','Safran','Moule commune crue']::text[], ARRAY['On ne remue plus après le mouillement : remuer donne un risotto, et une paella se reconnaît à ses grains séparés','Le jus de cuisson des moules, filtré, remplace une partie du bouillon — c''est le goût de mer du plat','Les calamars se saisissent à part deux minutes : laissés dans le riz vingt minutes, ils deviennent caoutchouteux','Le socarrat se fait à la fin, au son : quand le bouillonnement devient crépitement, il reste moins d''une minute']::text[],
    ARRAY['ouverture des coquillages','infusion','sofrito','cuisson sans remuer','socarrat','repos']::text[], ARRAY['Paella mixte : 1 kg de filets de poulet et un chorizo ajoutés aux fruits de mer, bouillon de volaille (marmiton)','Aux langoustines et gambas, deux ou trois pièces par personne, avec un congre pour le fumet (marmiton, 750g)','Avec seiche et clovisses en plus des calamars et des moules (marmiton)','Aux haricots plats, six gousses ajoutées avec le sofrito (750g)','Colorant alimentaire à la place du safran, ou en complément (marmiton)']::text[], ARRAY['mollusques','crustacés']::text[],
    'Se mange dans le quart d''heure : le riz continue de sécher et les fruits de mer se raffermissent. Les restes se gardent 2 jours au réfrigérateur et se réchauffent à couvert avec deux cuillerées d''eau, à feu doux — jamais deux fois. Ne se congèle pas : les moules et les calamars rendent leur eau à la décongélation et le riz se délite. Le sofrito, lui, se prépare 3 jours à l''avance et se congèle 3 mois, ce qui retire vingt minutes au jour J.', '{"fridge_hours":48,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

