  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Gratter et ébarber les moules, jeter celles qui restent ouvertes après un choc sur le plan de travail, puis les faire ouvrir à couvert et à feu vif dans une casserole, trois minutes, sans eau. Filtrer le jus qu''elles rendent au chinois fin doublé d''un linge et le réserver : c''est le fond de mer du plat, et il vaut mieux que n''importe quel cube.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire chauffer le bouillon de volaille avec le jus des moules et y jeter le safran, puis maintenir à frémissement. Le safran a besoin d''une dizaine de minutes dans un liquide chaud pour libérer sa couleur ; jeté sec sur le riz, il reste en filaments rouges au milieu d''un riz blanc.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Dans une grande poêle large, saisir les calamars coupés en anneaux deux minutes à feu vif dans l''huile, puis les retirer. Ils cuisent en deux minutes ou en quarante ; entre les deux ils sont caoutchouteux, et c''est pourquoi on ne les laisse pas dans le riz du début à la fin.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Faire fondre dans la même poêle l''oignon et le poivron taillés en dés, dix minutes, ajouter l''ail haché puis les tomates concassées et laisser réduire jusqu''à obtenir une base épaisse et presque sèche. Ce sofrito est le socle du goût : mal réduit, il laisse de l''eau qui fera un riz collant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser le riz et le remuer deux minutes dans le sofrito pour l''enrober, puis étaler le tout en couche régulière et mouiller de tout le bouillon safrané d''un seul coup. À partir de cet instant, on ne remue plus jamais : c''est ce qui distingue une paella d''un risotto, et remuer donnerait une bouillie au lieu de grains séparés.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Cuire dix minutes à feu vif puis huit minutes à feu doux, en répartissant les crevettes, les petits pois encore surgelés et les calamars à mi-cuisson, et les moules décoquillées dans les trois dernières minutes. Les petits pois n''ont pas besoin d''être décongelés : jetés tels quels, ils cuisent en cinq minutes et gardent leur couleur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Quand le liquide a disparu en surface, monter le feu trente à quarante-cinq secondes pour former le socarrat, cette croûte de riz caramélisée au fond de la poêle : on la reconnaît à l''oreille, un crépitement sec qui remplace le bouillonnement. Couvrir alors d''un linge et laisser reposer cinq minutes hors du feu avant de servir directement dans la poêle.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
