  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Gyros de poulet', 'Pain pita garni de poulet grillé, de crudités et d''une sauce au yaourt et au concombre', ds.id, 'VAR-013',
    'Myko', 'editorial', 4, 25, 25, 'facile',
    NULL, NULL,
    'B', 'candidate', 'dd2e3450a12deb11f1dcda0dddf861ec',
    '{"sweet":2,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":1,"pungency":3,"richness":3,"freshness":3,"intensity":4}'::jsonb, ARRAY['poulet grillé','yaourt à l''ail','citron','paprika']::text[],
    ARRAY['origan','cumin','ail','agrume']::text[], ARRAY['pain moelleux','viande grillée','contraste_léger']::text[],
    ARRAY['Blanc de poulet cru, sans peau','Pain pita','Yaourt nature']::text[], ARRAY['Le poulet est saisi en deux fois dans une poêle brûlante : entassé, il bout et perd les arêtes grillées qui font le gyros','Le yaourt s''égoutte une heure — non égoutté, la sauce traverse le pain','Le concombre se dégorge et se presse, sinon il liquéfie la sauce en une demi-heure','Sauce en dessous et au-dessus de la garniture : la couche du bas protège le pain du jus des légumes']::text[],
    ARRAY['marinade','égouttage du yaourt','dégorgement','saisie à feu vif','assemblage']::text[], ARRAY['Gyros de porc : un rôti de 800 g braisé une heure dans une sauce tomate au cumin, au piment et à l''origan, servi avec trois couleurs de poivron (marmiton)','Au tzatziki du commerce, 250 g pour quatre, à la place de la sauce au yaourt maison (chefsimon, 750g)','Avec 100 g de beaufort râpé dans le pita (chefsimon)','Version végétarienne : aubergines panées à la chapelure et au parmesan, roquette et tzatziki dans un wrap (chefsimon)','Mélange d''épices à gyros maison : ail en poudre, paprika, herbes de Provence, coriandre, cumin, poivre, sel, céleri en poudre et graines de moutarde à parts décroissantes (chefsimon)']::text[], ARRAY['gluten','lait']::text[],
    'Le poulet mariné cru se garde 24 heures au réfrigérateur et se congèle 2 mois dans sa marinade — c''est la façon d''avoir un dîner en un quart d''heure. Le poulet cuit se garde 3 jours, la sauce au yaourt 3 jours également, dans deux boîtes séparées. Les pitas se congèlent 2 mois et se réchauffent sans décongélation. Le sandwich monté ne se garde pas : le pain est détrempé en une demi-heure. Ne jamais réchauffer la sauce.', '{"fridge_hours":72,"eat_immediately":true,"freezable":false,"freezer_months":null,"serve_cold":false,"source":"manual"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

