  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Émincer les oignons et les faire fondre dix minutes dans l''huile d''olive, puis monter le feu et ajouter le bœuf haché en l''écrasant à la fourchette pour qu''il se défasse en grains. Le laisser colorer sans le remuer sans arrêt : une viande hachée qu''on brasse en permanence rend son eau et bout au lieu de saisir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Ajouter la cannelle, saler, poivrer, puis verser les tomates concassées et laisser mijoter à découvert vingt-cinq minutes, jusqu''à ce que la sauce soit épaisse et qu''il ne reste plus d''eau libre. La cannelle dans la viande est ce qui distingue un pastitsio d''une bolognaise gratinée ; elle doit cuire avec la tomate pour se fondre, jetée à la fin elle reste en poudre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Cuire les pâtes dans une grande eau salée, trois minutes de moins que le temps indiqué, les égoutter et les rincer à l''eau froide. Elles finiront de cuire au four dans la béchamel ; cuites à point maintenant, elles ressortiront molles au bout d''une heure.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Faire un roux avec le beurre et la farine, cuire deux minutes en remuant, puis verser le lait froid d''un coup en fouettant. Cuire à feu moyen jusqu''à ce que la béchamel nappe franchement la cuillère : elle doit être nettement plus épaisse qu''une béchamel de lasagnes, car c''est elle qui tiendra les parts à la découpe. Râper la muscade, saler.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Laisser tiédir la béchamel cinq minutes puis y battre les œufs entiers un à un. Les œufs sont ce qui la fait prendre en flan au four et donne au pastitsio sa couche supérieure qui se tranche net ; incorporés dans une béchamel brûlante ils coaguleraient en grains.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Mélanger les pâtes à un tiers de la béchamel et à la moitié du gruyère, les étaler dans un grand plat beurré, couvrir de toute la viande à la tomate, puis napper du reste de béchamel et parsemer du gruyère restant. Les pâtes liées de béchamel avant montage ne se dessèchent pas et ne se soudent pas en bloc.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Enfourner à 180 °C pour cinquante à soixante minutes, jusqu''à ce que le dessus soit doré et gonflé et que le plat ne tremble plus au centre quand on le secoue. Laisser reposer un quart d''heure avant de couper : sorti du four et tranché aussitôt, le pastitsio s''affaisse et coule dans l''assiette. C''est le repos qui donne les parts nettes.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-014', 'recipe_family', 'Pastitsio',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-014', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Aux bucatini plutôt qu''aux macaronis, avec un verre de vin rouge, une carotte en petits dés, trois feuilles de laurier et de l''origan dans la viande (chefsimon)','Au pecorino ou à un fromage râpé grec à la place du gruyère, moitié dans les pâtes, moitié dans la béchamel (chefsimon)','Viande de bœuf, porc et agneau mélangés à parts égales (chefsimon)','Sauce montée au bouillon de légumes, 35 cl, à la place d''une partie de la tomate (750g)','Deux oignons rouges et une gousse d''ail entière retirée avant montage, avec des grains de coriandre écrasés (marmiton)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-014","variants":["Aux bucatini plutôt qu''aux macaronis, avec un verre de vin rouge, une carotte en petits dés, trois feuilles de laurier et de l''origan dans la viande (chefsimon)","Au pecorino ou à un fromage râpé grec à la place du gruyère, moitié dans les pâtes, moitié dans la béchamel (chefsimon)","Viande de bœuf, porc et agneau mélangés à parts égales (chefsimon)","Sauce montée au bouillon de légumes, 35 cl, à la place d''une partie de la tomate (750g)","Deux oignons rouges et une gousse d''ail entière retirée avant montage, avec des grains de coriandre écrasés (marmiton)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-014', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('b17ea44f827bac7123d1d8daec5ade23'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":0,"intensity":4},"dominant_flavors":["cannelle","bœuf","tomate mijotée","béchamel"],"aroma_families":["cannelle","bœuf","tomate_cuite","lacté"],"target_textures":["croûte gratinée","pâtes_fermes","sauce_épaisse"],"signature_ingredients":["Bœuf haché cru","Pâtes sèches courtes","Cannelle moulue"],"identity_guardrails":["La cannelle dans la viande fait le pastitsio ; sans elle c''est un gratin de pâtes à la bolognaise","La béchamel est liée aux œufs — c''est elle qui prend en flan et permet de trancher des parts nettes","Les pâtes se cuisent trois minutes en moins : elles terminent au four","Un quart d''heure de repos avant la découpe, sinon le plat s''affaisse dans l''assiette"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Chich taouk', 'chich taouk', 'Levant', 'Levant',
     'meal', 'brochette', 'named_traditional_dish', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
