  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Tajine de kefta', 'Boulettes de bœuf haché mijotées dans une sauce tomate aux olives vertes et à la coriandre', ds.id, 'VAR-018',
    'Myko', 'editorial', 4, 20, 30, 'facile',
    NULL, NULL,
    'B', 'candidate', 'b33730e1878e4a0f3570b13be1aa15b3',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":1,"pungency":3,"richness":3,"freshness":2,"intensity":4}'::jsonb, ARRAY['cumin','coriandre fraîche','tomate mijotée','bœuf']::text[],
    ARRAY['cumin','coriandre','tomate_cuite','paprika']::text[], ARRAY['farce moelleuse','sauce_nappante','jaune d''œuf coulant']::text[],
    ARRAY['Bœuf haché cru','Cumin moulu','Coriandre fraîche']::text[], ARRAY['Cumin et coriandre fraîche ensemble : ce sont les deux marqueurs du plat, présents dans six et huit pages sur neuf','L''oignon de la farce se râpe et ne se hache pas — en morceaux, il fait éclater les boulettes','Les œufs se cassent dans la sauce déjà réduite et cuisent à couvert cinq à sept minutes : le jaune reste coulant','On ne remue pas les boulettes à la cuillère, on secoue le plat']::text[],
    ARRAY['hachage','façonnage','mijotage','réduction','pochage des œufs']::text[], ARRAY['Aux pommes de terre : 600 g en quartiers ajoutés à la sauce et mijotés une heure, sans œufs (chefsimon, 750g)','Aux petits pois : 500 g ajoutés en fin de cuisson avec six œufs pour trois personnes (marmiton)','Aux patates douces et haricots rouges : trois patates douces, une boîte de haricots rouges et deux courgettes, une heure et demie de cuisson (marmiton)','Épicée au ras el-hanout, une à deux cuillerées à café en plus du cumin et du paprika (chefsimon, 750g)','À la cannelle : une demi-cuillerée à soupe mêlée au cumin dans la farce des boulettes (chefsimon)','Aux poivrons grillés : deux poivrons pelés et taillés en lanières ajoutés à la sauce (chefsimon)']::text[], ARRAY['œuf']::text[],
    'Se garde 3 jours au réfrigérateur, mais sans les œufs, qu''on ajoute au réchauffage : un jaune cuit deux fois devient sableux. Les boulettes crues se gardent 24 heures et se congèlent 3 mois, crues et espacées sur une plaque avant d''être mises en sac — elles cuisent alors sans décongélation en ajoutant cinq minutes de mijotage. La sauce seule se congèle 3 mois. Réchauffer à couvert et à feu doux avec une cuillerée d''eau.', '{"fridge_hours":72,"eat_immediately":false,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
