      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 2, 'g', 'required',
     'assaisonnement', false, 13);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Râper la moitié de l''oignon très finement au-dessus d''un saladier et le mêler au bœuf haché avec l''ail écrasé, la moitié de la coriandre ciselée, un tiers du cumin, un tiers du paprika, le gingembre, du sel et du poivre. Râpé plutôt que haché, l''oignon rend son jus dans la viande et la garde moelleuse ; en morceaux il fait éclater les boulettes à la cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Travailler la viande une minute à la main, en la ramenant sur elle-même, jusqu''à ce qu''elle devienne collante, puis la laisser reposer un quart d''heure au frais. Ce pétrissage court développe assez de liant pour que les boulettes tiennent sans œuf ni mie de pain, ce qu''aucune des pages du dossier n''ajoute d''ailleurs.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Façonner, les mains humides, des boulettes de trente grammes environ, et les réserver au frais. Compter une quinzaine pour quatre personnes : plus grosses, elles restent crues au centre quand la sauce est réduite ; plus petites, elles se dessèchent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Faire fondre le reste de l''oignon émincé dans l''huile d''olive à feu moyen, huit minutes, ajouter le cumin et le paprika restants hors du feu et remuer, puis verser les tomates concassées avec un demi-verre d''eau. Le paprika et le cumin s''ouvrent dans le gras tiède ; jetés dans la tomate froide, ils restent en poudre au fond de la sauce.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Déposer les boulettes dans la sauce frémissante sans les superposer, couvrir et laisser mijoter vingt minutes à feu doux, en secouant le plat de temps en temps plutôt qu''en remuant à la cuillère. On ne les retourne pas non plus : elles se tiennent d''elles-mêmes une fois saisies par la chaleur de la sauce, et les manipuler les casse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Découvrir, ajouter les olives, laisser réduire cinq minutes jusqu''à ce que la sauce nappe, puis creuser quatre puits entre les boulettes et y casser les œufs. Couvrir et laisser cinq à sept minutes à feu très doux : le blanc doit être pris et le jaune encore coulant, ce qui est le point exact de ce plat — un jaune cuit dur en fait un autre plat, plus sec.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Parsemer du reste de coriandre, poivrer et servir dans le plat de cuisson, avec du pain pour saucer. Ne pas saler à la fin sans goûter : les olives ont rendu du sel pendant les cinq dernières minutes.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-018', 'recipe_family', 'Tajine de kefta',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-018', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Aux pommes de terre : 600 g en quartiers ajoutés à la sauce et mijotés une heure, sans œufs (chefsimon, 750g)','Aux petits pois : 500 g ajoutés en fin de cuisson avec six œufs pour trois personnes (marmiton)','Aux patates douces et haricots rouges : trois patates douces, une boîte de haricots rouges et deux courgettes, une heure et demie de cuisson (marmiton)','Épicée au ras el-hanout, une à deux cuillerées à café en plus du cumin et du paprika (chefsimon, 750g)','À la cannelle : une demi-cuillerée à soupe mêlée au cumin dans la farce des boulettes (chefsimon)','Aux poivrons grillés : deux poivrons pelés et taillés en lanières ajoutés à la sauce (chefsimon)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-018","variants":["Aux pommes de terre : 600 g en quartiers ajoutés à la sauce et mijotés une heure, sans œufs (chefsimon, 750g)","Aux petits pois : 500 g ajoutés en fin de cuisson avec six œufs pour trois personnes (marmiton)","Aux patates douces et haricots rouges : trois patates douces, une boîte de haricots rouges et deux courgettes, une heure et demie de cuisson (marmiton)","Épicée au ras el-hanout, une à deux cuillerées à café en plus du cumin et du paprika (chefsimon, 750g)","À la cannelle : une demi-cuillerée à soupe mêlée au cumin dans la farce des boulettes (chefsimon)","Aux poivrons grillés : deux poivrons pelés et taillés en lanières ajoutés à la sauce (chefsimon)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-018', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('b33730e1878e4a0f3570b13be1aa15b3'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":1,"pungency":3,"richness":3,"freshness":2,"intensity":4},"dominant_flavors":["cumin","coriandre fraîche","tomate mijotée","bœuf"],"aroma_families":["cumin","coriandre","tomate_cuite","paprika"],"target_textures":["farce moelleuse","sauce_nappante","jaune d''œuf coulant"],"signature_ingredients":["Bœuf haché cru","Cumin moulu","Coriandre fraîche"],"identity_guardrails":["Cumin et coriandre fraîche ensemble : ce sont les deux marqueurs du plat, présents dans six et huit pages sur neuf","L''oignon de la farce se râpe et ne se hache pas — en morceaux, il fait éclater les boulettes","Les œufs se cassent dans la sauce déjà réduite et cuisent à couvert cinq à sept minutes : le jaune reste coulant","On ne remue pas les boulettes à la cuillère, on secoue le plat"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Tajine de légumes', 'tajine de legumes', 'Maroc', 'Maroc',
     'meal', 'légume mijoté', 'named_traditional_dish', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Tajine de légumes', 'Pommes de terre, courgettes, carottes et navets mijotés ensemble à la tomate', ds.id, 'VAR-019',
    'Myko', 'editorial', 6, 20, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', 'eb4f3c2368f923575a3065b15e416e84',
    '{"sweet":3,"salty":2,"acidic":2,"bitter":1,"umami":2,"heat":0,"pungency":3,"richness":2,"freshness":2,"intensity":3}'::jsonb, ARRAY['cumin','curcuma','légumes fondants','coriandre fraîche']::text[],
    ARRAY['cumin','épices chaudes','végétal cuit','coriandre']::text[], ARRAY['légumes fondants','jus court et nappant','morceaux entiers']::text[],
    ARRAY['Pomme de terre crue, épluchée','Cumin moulu','Curcuma moulu']::text[], ARRAY['Aucune viande et aucun poisson : trois pages du dossier en portent sous ce titre, et c''est exactement ce que cette recette n''est pas','Les épices s''ouvrent dans l''huile avant les légumes, sinon elles restent en poudre','Morceaux gros et montage en dôme, les longs à cuire au fond : c''est ce qui permet de tout cuire ensemble','On ne remue jamais : un tajine remué devient une ratatouille']::text[],
    ARRAY['suer','épices ouvertes dans le gras','cuisson à l''étouffée','montage en dôme','repos']::text[], ARRAY['Aux olives, 80 g égouttées ajoutées dans les dix dernières minutes (marmiton)','Aux pois chiches et fruits secs : 250 g de pois chiches, 100 g d''abricots secs et 100 g de raisins secs, sur un lit de quinoa (marmiton)','Aux haricots verts et petits pois : 250 g de chaque, ajoutés à mi-cuisson, avec deux aubergines et deux branches de céleri (750g)','Au ras el-hanout, une cuillerée à café en plus des épices moulues (marmiton, 750g)','Au safran : une pincée infusée dans le bouillon, avec un piment fort entier (chefsimon)']::text[], ARRAY[]::text[],
    'Se garde 4 jours au réfrigérateur et se réchauffe à couvert, à feu doux, avec deux cuillerées d''eau. Il gagne au réchauffage, les épices continuant de diffuser. Se congèle 3 mois, mais en retirant les pommes de terre, qui ressortent granuleuses — les courgettes, elles, s''affaissent sans nuire au plat. C''est un bon candidat au double : la moitié se sert en plat, l''autre se mixe en soupe épaisse ou se glisse dans une semoule.', '{"fridge_hours":96,"eat_immediately":false,"freezable":true,"freezer_months":3,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

