  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Émincer les oignons et les faire fondre dix minutes dans l''huile d''olive au fond d''un plat à tajine ou d''une cocotte large, avec l''ail haché, le cumin, le curcuma et le gingembre. Les épices doivent grésiller dans le gras avant que le moindre légume n''arrive : c''est le seul moment où elles peuvent s''ouvrir, ensuite l''eau des légumes les fige.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Tailler les carottes et les navets en gros bâtonnets, les pommes de terre en quartiers, les courgettes en tronçons épais et le poivron en larges lanières, en gardant les morceaux nettement plus gros que dans un ragoût. Un tajine cuit à couvert dans peu de liquide et longtemps : des dés fins s''y délitent en purée avant la fin.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Ranger les légumes en dôme sur le lit d''oignons, les plus longs à cuire en dessous — carottes, navets, pommes de terre — les courgettes et le poivron par-dessus. Ce n''est pas une décoration : le fond du plat est plus chaud et plus humide que le sommet du dôme, et ce classement est ce qui permet de tout cuire ensemble sans rien surcuire.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Concasser les tomates et les répartir sur le dessus, saler, poivrer, verser le bouillon de légumes le long de la paroi sans arroser le dôme. Le liquide doit monter à deux ou trois centimètres, pas davantage : les légumes vont rendre leur eau et la sauce se ferait soupe.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Couvrir et laisser mijoter quarante-cinq minutes à feu doux, sans remuer une seule fois. Vérifier la cuisson à la pointe du couteau dans une carotte, qui est le légume le plus long. Si le fond attache, ajouter deux cuillerées d''eau et baisser encore, mais ne pas mélanger : c''est ce qui distingue un tajine d''une ratatouille.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Découvrir cinq minutes en fin de cuisson si le jus est trop abondant, parsemer de coriandre ciselée et laisser reposer dix minutes hors du feu avant de servir. Le repos permet aux légumes de réabsorber une partie du jus et au plat de se tenir dans l''assiette.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-019', 'recipe_family', 'Tajine de légumes',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-019', 'missing_required_count', v_missing), 'open');
  END IF;

