  FROM axis
  CROSS JOIN unnest(ARRAY['Aux olives, 80 g égouttées ajoutées dans les dix dernières minutes (marmiton)','Aux pois chiches et fruits secs : 250 g de pois chiches, 100 g d''abricots secs et 100 g de raisins secs, sur un lit de quinoa (marmiton)','Aux haricots verts et petits pois : 250 g de chaque, ajoutés à mi-cuisson, avec deux aubergines et deux branches de céleri (750g)','Au ras el-hanout, une cuillerée à café en plus des épices moulues (marmiton, 750g)','Au safran : une pincée infusée dans le bouillon, avec un piment fort entier (chefsimon)']::text[]) AS variant(name);

