  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Peler les aubergines une bande sur deux et les couper en gros cubes. Retirer toute la peau donne une purée uniforme et un peu fade ; la garder entièrement laisse des lanières coriaces dans la bouche. Les bandes alternées sont le compromis que la texture du plat demande.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Monder les tomates — trente secondes dans l''eau bouillante, puis dans l''eau froide — et les couper en dés en gardant leur jus. La peau de tomate ne se défait jamais dans un zaalouk : elle s''enroule en petits tubes qu''on retrouve à chaque bouchée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chauffer l''huile d''olive dans une sauteuse large, y jeter l''ail haché, le cumin et le paprika, remuer vingt secondes, puis ajouter aussitôt les aubergines et les tomates avec un demi-verre d''eau. Vingt secondes suffisent aux épices : au-delà, le cumin grille et devient âcre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Couvrir et laisser cuire vingt-cinq minutes à feu moyen, en remuant deux ou trois fois, jusqu''à ce que les aubergines s''écrasent d''elles-mêmes sous la cuillère. Le repère est franc : tant qu''un cube garde sa forme, ce n''est pas prêt, et cinq minutes de plus ne gâchent rien.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Découvrir et laisser l''eau s''évaporer à feu vif cinq à dix minutes, en écrasant à la fourchette pour obtenir une purée grossière où quelques morceaux subsistent. Un zaalouk mixé au robot devient une crème lisse qui n''est plus le plat : c''est la fourchette qui donne la texture, et l''irrégularité fait partie de la définition.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Hors du feu, incorporer le persil et la coriandre ciselés, saler, poivrer et goûter. Servir tiède ou froid, jamais brûlant : le cumin et l''ail ne se lisent qu''en dessous de cinquante degrés, et le plat gagne à attendre une heure.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-020', 'recipe_family', 'Zaalouk d''aubergines',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-020', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Au jus de citron, deux cuillerées à soupe ajoutées hors du feu (750g)','Au ras el-hanout, une cuillerée à café en plus du cumin (chefsimon)','Aux graines de cumin entières en plus du cumin moulu, à parts égales (chefsimon)','Enrichi d''une courgette et d''un gros poivron rouge cuits avec les aubergines (750g)','Avec une cuillerée à soupe de concentré de tomate pour une couleur plus soutenue (750g)','Relevé d''une pincée de cayenne (chefsimon)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-020","variants":["Au jus de citron, deux cuillerées à soupe ajoutées hors du feu (750g)","Au ras el-hanout, une cuillerée à café en plus du cumin (chefsimon)","Aux graines de cumin entières en plus du cumin moulu, à parts égales (chefsimon)","Enrichi d''une courgette et d''un gros poivron rouge cuits avec les aubergines (750g)","Avec une cuillerée à soupe de concentré de tomate pour une couleur plus soutenue (750g)","Relevé d''une pincée de cayenne (chefsimon)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-020', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('cbbc2367be63fddadd3beeee77427a8f'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"earthy_herbal","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":3,"heat":1,"pungency":3,"richness":2,"freshness":3,"intensity":3},"dominant_flavors":["aubergine fondue","cumin","ail","tomate cuite"],"aroma_families":["cumin","ail","végétal cuit","herbacé"],"target_textures":["purée grossière","morceaux entiers","fondant"],"signature_ingredients":["Aubergine fraîche","Cumin moulu","Ail cru"],"identity_guardrails":["L''aubergine doit s''effondrer entièrement : tant qu''un cube tient sa forme, la cuisson n''est pas finie","Écrasé à la fourchette et non mixé — la texture irrégulière fait partie de la définition du plat","Le cumin est le second marqueur après l''aubergine, présent dans les six pages du dossier","Se mange tiède ou froid : brûlant, ni le cumin ni l''ail ne se lisent"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Salade méchouia', 'salade mechouia', 'Tunisie', 'Tunisie',
     'meal', 'entrée froide', 'named_traditional_dish', 'earthy_herbal',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Salade méchouia', 'Poivrons et tomates grillés puis écrasés, relevés au piment vert et à l''huile d''olive', ds.id, 'VAR-021',
    'Myko', 'editorial', 6, 25, 30, 'facile',
    NULL, NULL,
    'B', 'candidate', '731043add84b6e530b382a9f7eecf884',
    '{"sweet":3,"salty":3,"acidic":2,"bitter":2,"umami":3,"heat":3,"pungency":5,"richness":3,"freshness":2,"intensity":4}'::jsonb, ARRAY['poivron grillé','ail cru','piment','huile d''olive']::text[],
    ARRAY['végétal grillé','ail','piment','huile_olive']::text[], ARRAY['hachis grossier','fondant','contraste_léger']::text[],
    ARRAY['Poivron rouge frais','Ail cru','Piment vert frais']::text[], ARRAY['La peau des poivrons doit noircir vraiment : sans ce brûlé, il n''y a pas de méchouia mais une salade de poivrons cuits','L''ail reste cru et se compte en dizaines de grammes — vingt-cinq pour six, c''est la signature','Les légumes pelés ne se rincent jamais : l''eau emporte le jus fumé','Haché au couteau, pas mixé : la salade garde du grain']::text[],
    ARRAY['grillade','sudation','épluchage','hachage au couteau','repos']::text[], ARRAY['Au thon : une boîte de thon en miettes égouttée, environ 25 g par personne, émiettée sur le dessus avec les œufs (marmiton, deux pages)','Panachée rouge et vert, moitié-moitié de poivrons (marmiton, chefsimon, 750g)','Au cumin, trois grosses pincées pour six (750g)','Au carvi et à la coriandre en poudre, une cuillerée à café de chaque pour six (chefsimon)','Au jus de citron, deux cuillerées à soupe pour trois, avec des olives vertes (marmiton)','Avec thym, romarin et origan frais mêlés aux légumes grillés (chefsimon)']::text[], ARRAY['œuf']::text[],
    'Se garde 4 jours au réfrigérateur sous un film d''huile d''olive et gagne à reposer une nuit, l''ail cru s''assagissant. Sortir une demi-heure avant de servir. Se congèle 3 mois, les légumes étant déjà écrasés — mais sans les œufs ni les olives, qu''on ajoute après décongélation. Les poivrons grillés et pelés se gardent d''ailleurs seuls 5 jours sous huile et servent aussi bien à cette salade qu''à une garniture de pizza ou de sandwich.', '{"fridge_hours":96,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":true,"source":"manual"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
