      WHERE ff.canonical_name_normalized = 'tomate fraiche mure' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Tomate fraîche mûre', 700, 'g', 'required',
     'légume', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
