  CROSS JOIN unnest(ARRAY['À l''eau de fleur d''oranger : 6 cl dans la farce, ou deux cuillerées à soupe, forme absente du catalogue et donc non écrite ici (marmiton, 750g)','Amandes et noisettes à parts égales, avec de la gomme arabique et deux gouttes d''arôme d''amande (chefsimon)','Briouates au poulet : un kilo de poulet effiloché, oignon, gingembre, coriandre, safran, œufs brouillés et amandes grillées, avec du miel (chefsimon, 750g)','Briouates à la kefta : steak haché, oignon, poivron, vermicelles de soja, harissa et coriandre (750g)','Briouates aux épinards : épinards hachés, ail, fromage râpé, olives vertes, câpres et paprika (chefsimon)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
