  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-024","variants":["À l''eau de fleur d''oranger : 6 cl dans la farce, ou deux cuillerées à soupe, forme absente du catalogue et donc non écrite ici (marmiton, 750g)","Amandes et noisettes à parts égales, avec de la gomme arabique et deux gouttes d''arôme d''amande (chefsimon)","Briouates au poulet : un kilo de poulet effiloché, oignon, gingembre, coriandre, safran, œufs brouillés et amandes grillées, avec du miel (chefsimon, 750g)","Briouates à la kefta : steak haché, oignon, poivron, vermicelles de soja, harissa et coriandre (750g)","Briouates aux épinards : épinards hachés, ail, fromage râpé, olives vertes, câpres et paprika (chefsimon)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-024', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('f979ada3479a06fb0cb46fde96c70359'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"sweet_spiced","scores":{"sweet":5,"salty":0,"acidic":0,"bitter":0,"umami":0,"heat":0,"pungency":1,"richness":5,"freshness":0,"intensity":4},"dominant_flavors":["amande","miel","cannelle"],"aroma_families":["amande","miel","cannelle"],"target_textures":["croûte croustillante","farce moelleuse","contraste_léger"],"signature_ingredients":["Amande","Miel","Feuille de brick"],"identity_guardrails":["Les amandes se mixent en poudre grossière : réduites en pâte, elles rendent leur huile et la farce devient grasse","Les feuilles de brick restent sous un linge humide — elles sèchent et cassent en trois minutes à l''air","Le trempage se fait briouate brûlante dans un miel tiède : l''inverse laisse le miel en surface","Refroidir sur grille et à plat ; empilées chaudes, elles se collent et perdent leur croustillant"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
