  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Tailler le bœuf en cubes de trois centimètres, les couvrir du bouillon froid et porter lentement à frémissement. Écumer soigneusement la mousse grise pendant le premier quart d''heure : c''est elle qui trouble le bouillon, et dans une soupe dont la couleur est l''argument principal, un bouillon terne se voit tout de suite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Laisser cuire une heure à couvert et à petits frémissements, jusqu''à ce que la viande cède sous la fourchette. Une ébullition franche resserre les fibres et fait une viande dure dans un bouillon gras : le bortsch se cuit à la surface juste tremblante.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pendant ce temps, râper la betterave crue à la grosse grille et la faire revenir dix minutes dans l''huile avec l''oignon émincé, le concentré de tomate et le vinaigre. C''est l''étape qui décide de la couleur : l''acide fixe le pigment de la betterave, qui vire au brun quand il cuit longtemps en milieu neutre. Sans vinaigre à ce moment-là, le bortsch finit terre de Sienne.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ajouter au bouillon les pommes de terre en dés et les carottes en rondelles, cuire quinze minutes, puis le chou finement émincé et cuire dix minutes de plus. Le chou en dernier : il passe de croquant à filandreux en un quart d''heure et c''est lui qui donne au bortsch sa mâche.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser enfin la betterave revenue avec son jus dans la marmite et laisser dix minutes à feu doux, sans faire bouillir. Elle entre en dernier et ne bout pas : c''est la seconde condition de la couleur, et c''est aussi pourquoi une betterave déjà cuite, si l''on en emploie, se contente de ces dix minutes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Saler, poivrer, goûter et rectifier l''acidité — le bortsch doit être franchement acidulé, sensiblement plus que ce que l''on croit en le goûtant chaud. Couper le feu, jeter le persil ciselé, couvrir et laisser reposer une demi-heure : la soupe se stabilise et le goût s''arrondit.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Servir très chaud, avec une cuillerée de crème aigre déposée dans chaque assiette pour qui en veut. La crème se met dans l''assiette et non dans la marmite : elle tranche à l''ébullition, et le reste de la soupe se conserve mieux sans elle.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-026', 'recipe_family', 'Bortsch',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-026', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Au jus de citron à la place du vinaigre, deux cuillerées à soupe pour six (chefsimon, 750g)','À l''aneth : un petit bouquet ciselé avec le persil en fin de cuisson (chefsimon)','Végétarien : bouillon de légumes, betteraves déjà cuites avec leur jus, tomates pelées en boîte et une pincée de piment d''Espelette (chefsimon)','Aux deux choux, moitié vert et moitié rouge, avec du cumin (marmiton)','Avec 100 g de poitrine de porc taillée en lardons cuits avec le bœuf, et du céleri-rave (marmiton)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-026","variants":["Au jus de citron à la place du vinaigre, deux cuillerées à soupe pour six (chefsimon, 750g)","À l''aneth : un petit bouquet ciselé avec le persil en fin de cuisson (chefsimon)","Végétarien : bouillon de légumes, betteraves déjà cuites avec leur jus, tomates pelées en boîte et une pincée de piment d''Espelette (chefsimon)","Aux deux choux, moitié vert et moitié rouge, avec du cumin (marmiton)","Avec 100 g de poitrine de porc taillée en lardons cuits avec le bœuf, et du céleri-rave (marmiton)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-026', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('3d1bf85efdd3f409689190fceeb80d14'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"brothy_umami","scores":{"sweet":3,"salty":3,"acidic":4,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":2,"freshness":2,"intensity":3},"dominant_flavors":["betterave","bœuf mijoté","vinaigre","chou"],"aroma_families":["betterave","bœuf mijoté","végétal cuit","vinaigre"],"target_textures":["bouillon_clair","viande fondante","légumes fondants"],"signature_ingredients":["Betterave crue","Chou blanc frais","Bœuf à braiser cru"],"identity_guardrails":["Sans betterave il n''y a pas de bortsch : une page du dossier en fait la démonstration par l''absurde en n''en mettant aucune","La betterave se revient avec le vinaigre et le concentré, à part, et entre en dernier — sinon la couleur vire au brun","La soupe doit rester franchement acidulée : c''est l''acidité qui distingue un bortsch d''un pot-au-feu à la betterave","La crème aigre se dépose dans l''assiette, jamais dans la marmite, où elle trancherait"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Bœuf Stroganoff', 'boeuf stroganoff', 'Russie', 'Russie',
     'meal', 'plat sauté', 'named_traditional_dish', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Bœuf Stroganoff', 'Lamelles de bœuf sautées aux champignons dans une sauce à la crème et au vin blanc', ds.id, 'VAR-027',
    'Myko', 'editorial', 4, 15, 25, 'facile',
    NULL, NULL,
    'B', 'candidate', 'a0adc1210872aa16fcc0fe955c852188',
    '{"sweet":2,"salty":3,"acidic":3,"bitter":0,"umami":4,"heat":1,"pungency":3,"richness":4,"freshness":1,"intensity":4}'::jsonb, ARRAY['moutarde','crème','champignon','bœuf saisi']::text[],
    ARRAY['moutarde','champignon_terreux','lactée','paprika']::text[], ARRAY['sauce_nappante','tendre','champignon_fondant']::text[],
    ARRAY['Bœuf à griller cru, en fines lamelles','Moutarde de Dijon','Crème fraîche épaisse']::text[], ARRAY['Le bœuf se taille en lanières et se saisit en plusieurs fois : entassé, il bout et durcit sans retour','La moutarde entre hors ébullition et en dernier — bouillie, elle perd tout son piquant','Ce n''est jamais un plat de viande hachée ni de bœuf à mijoter : la cuisson totale de la viande est de deux minutes','Les champignons se sautent à sec et sans sel avant la sauce, sinon ils rendent leur eau dedans']::text[],
    ARRAY['saisie','sauté à feu vif','singer','déglaçage','réduction','liaison à la crème']::text[], ARRAY['À la crème aigre, 80 à 125 ml, ou à la crème additionnée de jus de citron (chefsimon)','Au gingembre frais râpé, avec du fond de veau à la place du bouillon (marmiton)','De luxe : viande à fondue, six oignons blancs, 500 g de champignons, trois cuillerées à soupe de moutarde et un demi-litre de crème (marmiton)','Sans farine, liaison à la fécule de maïs pour une version sans gluten (chefsimon)','Avec une pincée de sucre pour corriger l''acidité de la moutarde et du vin (marmiton)']::text[], ARRAY['lait','gluten','moutarde']::text[],
    'Se garde 2 jours au réfrigérateur, mais la viande se raffermit au réchauffage — c''est un plat qui se mange le jour même. Réchauffer à feu très doux sans jamais faire bouillir, la crème et la moutarde ne le supportant pas. Ne se congèle pas : la sauce à la crème tranche et les lanières deviennent fibreuses. La sauce seule, sans viande, se prépare la veille et se garde 3 jours ; il ne reste alors que deux minutes de poêle le soir venu.', '{"fridge_hours":48,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

