  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Tailler le bœuf en lanières de un centimètre de large sur cinq de long, en travaillant perpendiculairement au sens des fibres, puis les éponger. Coupée dans le sens du grain, la même viande ressort filandreuse quelle que soit la cuisson ; épongée, elle colore au lieu de bouillir dans son eau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Saisir les lanières en deux ou trois fois dans une poêle très chaude avec un peu d''huile, une minute par face, et les réserver dès qu''elles sont colorées mais encore rosées à cœur. Toutes ensemble, elles font tomber la température de la poêle et rendent leur jus : elles bouillent, grisent, et durcissent. C''est l''erreur qui ruine ce plat, et elle est irréversible.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Dans la même poêle, faire sauter les champignons émincés à feu vif dans le beurre, sans sel, jusqu''à ce que l''eau rendue se soit évaporée et qu''ils commencent à dorer. Le sel les ferait dégorger tout de suite et ils cuiraient dans leur jus au lieu de rôtir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ajouter l''oignon émincé et le laisser fondre cinq minutes, puis singer avec la farine, remuer une minute, et déglacer au vin blanc en grattant tout ce qui est attaché au fond. Les sucs bruns collés sous la viande et les champignons sont l''essentiel du goût de la sauce ; les laisser là revient à jeter la moitié du plat.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser le bouillon et le concentré de tomate, porter à petits bouillons et laisser réduire cinq à sept minutes jusqu''à ce que la sauce nappe la cuillère. Elle doit être un peu plus épaisse que ce que l''on veut à l''arrivée : la crème et le jus rendu par la viande vont la détendre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Baisser le feu au minimum, incorporer la crème puis la moutarde et le paprika hors ébullition. La moutarde ne doit jamais bouillir : elle perd son piquant en quelques secondes et laisse un goût plat et légèrement amer. C''est la raison pour laquelle elle entre en dernier et pas avec le bouillon.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Remettre la viande et son jus, réchauffer une minute à peine sans laisser frémir, saler, poivrer et parsemer de persil. Servir aussitôt : la viande a été saisie pour rester rosée, et cinq minutes de plus dans la sauce chaude suffisent à la cuire une seconde fois.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-027', 'recipe_family', 'Bœuf Stroganoff',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-027', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['À la crème aigre, 80 à 125 ml, ou à la crème additionnée de jus de citron (chefsimon)','Au gingembre frais râpé, avec du fond de veau à la place du bouillon (marmiton)','De luxe : viande à fondue, six oignons blancs, 500 g de champignons, trois cuillerées à soupe de moutarde et un demi-litre de crème (marmiton)','Sans farine, liaison à la fécule de maïs pour une version sans gluten (chefsimon)','Avec une pincée de sucre pour corriger l''acidité de la moutarde et du vin (marmiton)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-027","variants":["À la crème aigre, 80 à 125 ml, ou à la crème additionnée de jus de citron (chefsimon)","Au gingembre frais râpé, avec du fond de veau à la place du bouillon (marmiton)","De luxe : viande à fondue, six oignons blancs, 500 g de champignons, trois cuillerées à soupe de moutarde et un demi-litre de crème (marmiton)","Sans farine, liaison à la fécule de maïs pour une version sans gluten (chefsimon)","Avec une pincée de sucre pour corriger l''acidité de la moutarde et du vin (marmiton)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-027', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('a0adc1210872aa16fcc0fe955c852188'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":2,"salty":3,"acidic":3,"bitter":0,"umami":4,"heat":1,"pungency":3,"richness":4,"freshness":1,"intensity":4},"dominant_flavors":["moutarde","crème","champignon","bœuf saisi"],"aroma_families":["moutarde","champignon_terreux","lactée","paprika"],"target_textures":["sauce_nappante","tendre","champignon_fondant"],"signature_ingredients":["Bœuf à griller cru, en fines lamelles","Moutarde de Dijon","Crème fraîche épaisse"],"identity_guardrails":["Le bœuf se taille en lanières et se saisit en plusieurs fois : entassé, il bout et durcit sans retour","La moutarde entre hors ébullition et en dernier — bouillie, elle perd tout son piquant","Ce n''est jamais un plat de viande hachée ni de bœuf à mijoter : la cuisson totale de la viande est de deux minutes","Les champignons se sautent à sec et sans sel avant la sauce, sinon ils rendent leur eau dedans"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Blinis', 'blinis', 'Russie', 'Russie',
     'meal', 'blinis à la levure', 'named_traditional_dish', 'creamy_delicate',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Blinis', 'Petites crêpes épaisses à la levure de boulanger, cuites à la poêle', ds.id, 'VAR-028',
    'Myko', 'editorial', 6, 15, 15, 'facile',
    NULL, NULL,
    'B', 'candidate', 'a1c1f17cba6317a8217e11fa19d073ea',
    '{"sweet":2,"salty":2,"acidic":2,"bitter":0,"umami":1,"heat":0,"pungency":0,"richness":3,"freshness":0,"intensity":2}'::jsonb, ARRAY['lait','beurre','levure']::text[],
    ARRAY['lacté','beurre','pain grillé']::text[], ARRAY['moelleux','alvéolé','dessus_doré']::text[],
    ARRAY['Farine de blé T55','Lait entier','Levure boulangère fraîche']::text[], ARRAY['Une heure de pousse à la levure de boulanger : sans elle, c''est une crêpe épaisse et non un blini','Les blancs montés s''incorporent au dernier moment — ils retombent en un quart d''heure','On retourne quand la surface est criblée de trous ouverts, pas avant','Les blinis cuits s''empilent sous un linge : à l''air, ils croûtent en dix minutes']::text[],
    ARRAY['fermentation','blancs en neige','cuisson à la poêle']::text[], ARRAY['Au sarrasin : 150 g de farine de blé et 100 g de farine de sarrasin, forme absente du catalogue et donc non écrite ici (chefsimon)','À la levure chimique : 8 g pour six, sans temps de pousse (marmiton, chefsimon)','Au yaourt : 200 g de yaourt épais à la place d''une partie du lait, avec de l''huile d''olive plutôt que du beurre (chefsimon, marmiton)','Garnis de gruyère râpé et de jambon blanc, ou de bacon, cuits dans la pâte (750g)','En version apéritive : louches de la taille d''une cuillère à café, une douzaine de plus par fournée (chefsimon)']::text[], ARRAY['gluten','lait','œuf']::text[],
    'Se gardent 3 jours au réfrigérateur en boîte fermée et se réchauffent trente secondes par face à la poêle sèche ou dix secondes au grille-pain. Se congèlent 2 mois, empilés avec du papier cuisson entre chaque, et se réchauffent sans décongélation — c''est la forme la plus utile, une poignée sortie à la demande. La pâte crue ne se garde pas au-delà de deux heures après la pousse : elle retombe et le blini devient plat.', '{"fridge_hours":72,"eat_immediately":false,"freezable":true,"freezer_months":2,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'lait entier' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
