  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Tiédir le lait à trente-cinq degrés — la température du doigt, ni chaude ni froide — et y émietter la levure avec le sucre. Attendre dix minutes qu''une mousse se forme. Au-dessus de quarante-cinq degrés la levure meurt sans qu''on le voie, et la pâte ne lèvera jamais.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Verser le lait levuré sur la farine et le sel en fouettant, jusqu''à obtenir une pâte lisse et assez épaisse, de la consistance d''une crème fraîche fluide. Trop liquide, elle s''étale en crêpe ; trop épaisse, le blini reste cru au centre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Séparer les œufs, incorporer les jaunes à la pâte, couvrir et laisser pousser une heure à température ambiante, jusqu''à ce que la surface se couvre de bulles. C''est cette pousse qui fait le blini plutôt que la crêpe : elle acidifie légèrement la pâte et lui donne le goût lacté et un peu aigre qu''aucune levure chimique ne reproduit.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Juste avant de cuire, monter les blancs en neige ferme et les incorporer à la spatule en soulevant la masse, sans jamais tourner. Cette dernière opération se fait au dernier moment : les blancs retombent en un quart d''heure, et avec eux la légèreté qu''ils apportaient.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Chauffer une poêle à feu moyen, la beurrer légèrement, et déposer des louches de la taille d''une cuillère à soupe en les espaçant. Cuire deux minutes, jusqu''à ce que la surface soit criblée de trous ouverts, puis retourner et compter une minute. Les trous sont le signal : retourné avant qu''ils ne s''ouvrent, le blini s''affaisse ; après, il sèche.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Empiler les blinis cuits sur une assiette sous un linge propre, ce qui les garde souples pendant qu''on termine la fournée. À l''air libre, ils croûtent en dix minutes et cassent quand on les plie. Beurrer la poêle entre chaque fournée, pas davantage : un excès de beurre les fait frire et tacher.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-028', 'recipe_family', 'Blinis',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-028', 'missing_required_count', v_missing), 'open');
  END IF;

