     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 6, 'g', 'required',
     'assaisonnement', false, 11);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 2, 'g', 'required',
     'assaisonnement', false, 12);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Cuire le riz à l''eau salée, l''égoutter et l''étaler sur une plaque pour qu''il refroidisse complètement. Un riz tiède dégage de la vapeur sous la pâte et c''est ce qui donne un fond détrempé : tout ce qui entre dans une tourte doit être froid, sans exception.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire tomber les épinards à la poêle dans un peu de beurre, puis les presser fortement entre les mains ou dans un linge jusqu''à ce qu''il n''en sorte plus une goutte. Trois cents grammes d''épinards rendent près d''un verre d''eau ; enfermée dans le feuilletage, cette eau ressort en cuisant et décolle le fond.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Faire sauter les champignons émincés à feu vif dans le reste de beurre, sans les saler, jusqu''à évaporation complète de leur eau. Les saler maintenant leur ferait rendre leur jus dans la poêle sans jamais qu''ils dorent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Tailler le saumon en pavés réguliers, l''arroser du jus de citron, saler, poivrer et mêler l''aneth ciselé aux épinards refroidis. Le citron sur le saumon reste dix minutes au plus : au-delà, l''acide commence à cuire la chair et la tourte contiendra un poisson déjà blanc.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Étaler la première pâte, y monter les couches en laissant quatre centimètres de bord libre : riz d''abord, puis la moitié des épinards, le saumon, les œufs durs coupés en deux rangés bout à bout au milieu, les champignons, et le reste des épinards. L''ordre compte — le riz en dessous absorbe le peu de jus que le saumon rendra, et les œufs au centre donnent la tranche qui fait reconnaître un koulibiac.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Poser la seconde pâte, souder les bords à l''eau en pinçant, badigeonner de jaune d''œuf battu et pratiquer une cheminée au centre en y glissant un petit rouleau de papier. La cheminée n''est pas décorative : sans elle, la vapeur soulève le couvercle et le fait éclater sur un côté.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Enfourner à 200 °C pour vingt minutes, puis baisser à 180 °C et poursuivre quarante minutes, jusqu''à ce que le dessus soit brun doré et que la pointe d''un couteau ressorte brûlante. Laisser reposer un quart d''heure avant de trancher, sur une grille pour que le dessous ne cuise pas dans sa propre vapeur. Découper au couteau-scie, sans appuyer.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-029', 'recipe_family', 'Koulibiac de saumon',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-029', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Sauce d''accompagnement : 40 cl de crème liquide réduite avec le jus d''un citron, servie à part (chefsimon, 750g)','Aux épinards seuls, sans riz : 1 kg d''épinards frais et 800 g de saumon pour quatre, avec des graines de sésame sur la dorure (marmiton)','Au fenouil : 400 g de fenouil émincé à la place des champignons (chefsimon)','Au comté : 150 g râpés répartis sur le riz (750g)','Aux œufs de caille, douze pièces à la place des trois œufs durs (chefsimon)','Saumon poché au court-bouillon et au vin blanc avant montage, avec cerfeuil et ciboulette (marmiton)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-029","variants":["Sauce d''accompagnement : 40 cl de crème liquide réduite avec le jus d''un citron, servie à part (chefsimon, 750g)","Aux épinards seuls, sans riz : 1 kg d''épinards frais et 800 g de saumon pour quatre, avec des graines de sésame sur la dorure (marmiton)","Au fenouil : 400 g de fenouil émincé à la place des champignons (chefsimon)","Au comté : 150 g râpés répartis sur le riz (750g)","Aux œufs de caille, douze pièces à la place des trois œufs durs (chefsimon)","Saumon poché au court-bouillon et au vin blanc avant montage, avec cerfeuil et ciboulette (marmiton)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-029', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('a000f199a6d248f64c1069e8201a644a'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_delicate","scores":{"sweet":1,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":0,"richness":4,"freshness":2,"intensity":3},"dominant_flavors":["saumon","aneth","beurre","champignon"],"aroma_families":["marin","herbacé","beurre","champignon"],"target_textures":["feuilletage croustillant","chair_moelleuse","contraste_léger"],"signature_ingredients":["Pavé de saumon cru, sans peau","Pâte feuilletée crue","Aneth frais"],"identity_guardrails":["Tout ce qui entre dans la tourte doit être froid et sec : un riz tiède ou des épinards mal pressés détrempent le fond","Les œufs durs se rangent en file au centre — c''est la tranche qui fait reconnaître un koulibiac","Une cheminée dans le couvercle, sinon la vapeur fait éclater la pâte sur le côté","Un quart d''heure de repos sur grille avant la découpe, sans quoi la tranche s''effondre"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Salade russe', 'salade russe', 'Russie', 'Russie',
     'meal', 'salade composée', 'named_traditional_dish', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Salade russe', 'Dés de pommes de terre, carottes et petits pois liés à la mayonnaise, garnis de thon', ds.id, 'VAR-030',
    'Myko', 'editorial', 6, 20, 25, 'facile',
    NULL, NULL,
    'B', 'candidate', '2f8d29b9c909854d065a3f3af413fc3b',
    '{"sweet":2,"salty":3,"acidic":3,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":2,"intensity":2}'::jsonb, ARRAY['mayonnaise','pomme de terre','œuf dur','thon']::text[],
    ARRAY['moutarde','lactée','marin','végétal cuit']::text[], ARRAY['dés fermes','crémeux','contraste_léger']::text[],
    ARRAY['Pomme de terre cuite','Mayonnaise','Œuf dur']::text[], ARRAY['Pommes de terre cuites entières et en robe, taillées après : coupées avant, elles se gorgent d''eau','Tout doit être froid avant la mayonnaise, qui se dissocie sur des légumes tièdes','Dés réguliers d''un centimètre — c''est la seule tenue de ce plat','On mélange en soulevant, jamais en tournant, sous peine de purée']::text[],
    ARRAY['cuisson en robe des champs','blanchiment','refroidissement','taille en dés','assemblage','repos au froid']::text[], ARRAY['Salade Olivier : 250 g de blancs de poulet et six cornichons taillés en dés, aneth ou persil (chefsimon)','Stolichny : un filet de poulet, 100 g de haricots verts et un demi-concombre, aneth (chefsimon)','À la macédoine et au maïs en boîte, avec des pommes de terre grenaille (750g)','Aux crevettes, 50 g ajoutées avec le thon, et six tomates cerises (750g)','Aux olives vertes seules, sans thon ni poulet, six cuillerées de mayonnaise pour six (marmiton)']::text[], ARRAY['œuf','poisson','moutarde']::text[],
    'Se garde 2 jours au réfrigérateur, couverte, et pas davantage : la mayonnaise et les œufs durs limitent la conservation. Elle est meilleure le lendemain de sa confection. Ne se congèle pas — la mayonnaise tranche et la pomme de terre devient farineuse. Les légumes cuits et taillés se gardent en revanche 3 jours nature, sans mayonnaise, ce qui permet d''assembler la salade en cinq minutes le jour venu.', '{"fridge_hours":48,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":true,"source":"manual"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
