      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 2, 'g', 'required',
     'assaisonnement', false, 9);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Cuire les pommes de terre entières et non épluchées dans une grande eau salée, vingt à vingt-cinq minutes selon leur taille : la lame d''un couteau doit les traverser sans effort. Cuites entières et en robe, elles ne boivent pas l''eau de cuisson : coupées avant, elles ressortent gorgées et la mayonnaise glisse dessus au lieu d''adhérer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Cuire les carottes en morceaux dans la même eau les dix dernières minutes, et les œufs dix minutes à part. Les carottes doivent rester fermes sous la dent : trop cuites, elles s''écrasent au moment du mélange et colorent toute la salade en orange.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Jeter les petits pois encore surgelés dans l''eau bouillante trois minutes, puis les rafraîchir aussitôt dans l''eau glacée. Ce refroidissement brutal fixe leur vert et arrête la cuisson net ; sans lui, ils continuent de cuire dans leur propre chaleur et virent au kaki.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Peler les pommes de terre tièdes et les tailler, avec les carottes, en dés d''un centimètre bien réguliers. La régularité est le seul point de style de ce plat : des morceaux inégaux le font ressembler à un reste de pot-au-feu écrasé.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Laisser tous les éléments refroidir complètement avant d''ajouter la mayonnaise. Sur des légumes tièdes, elle se dissocie et rend de l''huile : la salade paraît alors grasse et brillante au lieu d''être liée et mate.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Mélanger délicatement les dés, les petits pois, le thon égoutté et émietté, deux œufs durs coupés en dés et la mayonnaise, saler et poivrer. Remuer à la spatule en soulevant plutôt qu''en tournant, sinon la pomme de terre se délite et la salade tourne à la purée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Tasser dans un plat, lisser la surface et décorer du troisième œuf en rondelles et des olives. Réserver au moins deux heures au réfrigérateur avant de servir : la salade a besoin de ce temps pour que les goûts se lient, et elle se coupe alors à la cuillère sans s''affaisser.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-030', 'recipe_family', 'Salade russe',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-030', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Salade Olivier : 250 g de blancs de poulet et six cornichons taillés en dés, aneth ou persil (chefsimon)','Stolichny : un filet de poulet, 100 g de haricots verts et un demi-concombre, aneth (chefsimon)','À la macédoine et au maïs en boîte, avec des pommes de terre grenaille (750g)','Aux crevettes, 50 g ajoutées avec le thon, et six tomates cerises (750g)','Aux olives vertes seules, sans thon ni poulet, six cuillerées de mayonnaise pour six (marmiton)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-030","variants":["Salade Olivier : 250 g de blancs de poulet et six cornichons taillés en dés, aneth ou persil (chefsimon)","Stolichny : un filet de poulet, 100 g de haricots verts et un demi-concombre, aneth (chefsimon)","À la macédoine et au maïs en boîte, avec des pommes de terre grenaille (750g)","Aux crevettes, 50 g ajoutées avec le thon, et six tomates cerises (750g)","Aux olives vertes seules, sans thon ni poulet, six cuillerées de mayonnaise pour six (marmiton)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-030', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('2f8d29b9c909854d065a3f3af413fc3b'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":2,"salty":3,"acidic":3,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":2,"intensity":2},"dominant_flavors":["mayonnaise","pomme de terre","œuf dur","thon"],"aroma_families":["moutarde","lactée","marin","végétal cuit"],"target_textures":["dés fermes","crémeux","contraste_léger"],"signature_ingredients":["Pomme de terre cuite","Mayonnaise","Œuf dur"],"identity_guardrails":["Pommes de terre cuites entières et en robe, taillées après : coupées avant, elles se gorgent d''eau","Tout doit être froid avant la mayonnaise, qui se dissocie sur des légumes tièdes","Dés réguliers d''un centimètre — c''est la seule tenue de ce plat","On mélange en soulevant, jamais en tournant, sous peine de purée"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Porc au caramel', 'porc au caramel', 'Vietnam', 'Vietnam',
     'meal', 'plat mijoté', 'named_traditional_dish', 'smoky_sweet',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Porc au caramel', 'Échine de porc mijotée dans un caramel salé à la sauce poisson et à la sauce soja', ds.id, 'VAR-031',
    'Myko', 'editorial', 4, 15, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', '5b145493afeb53e3d9ab465b979c0db4',
    '{"sweet":4,"salty":5,"acidic":1,"bitter":2,"umami":5,"heat":0,"pungency":2,"richness":4,"freshness":0,"intensity":5}'::jsonb, ARRAY['caramel','nuoc-mâm','porc','gingembre']::text[],
    ARRAY['caramel','soja_fermenté','porc','gingembre']::text[], ARRAY['viande fondante','sauce laquée','jus court et nappant']::text[],
    ARRAY['Échine de porc crue','Sucre semoule','Sauce poisson']::text[], ARRAY['Caramel à sec poussé jusqu''à l''ambre foncé : blond, il ne donne que du sucre, et c''est son amertume qui équilibre le nuoc-mâm','On garde le gras de l''échine — sans lui la viande est cordée au bout de quarante-cinq minutes','La sauce poisson est indispensable : sans elle, c''est un porc au sucre','La réduction se surveille à l''œil sur la fin : une minute sépare la sauce laquée du fond brûlé']::text[],
    ARRAY['caramel à sec','saisie','réduction','mijotage','laquage']::text[], ARRAY['À l''eau de coco : un litre à la place du bouillon, avec citron vert, coriandre et piment oiseau (chefsimon)','Au quatre-épices, une cuillerée à soupe avec le gingembre (marmiton, deux pages)','Poitrine de porc et œufs durs : 600 g de poitrine mijotés deux heures avec quatre œufs durs (750g)','Moitié échine, moitié poitrine fraîche, avec six grosses échalotes (chefsimon)','En wok, quinze minutes : filet de porc, brocolis, germes de soja, champignons et poivron rouge, trois cuillerées à café de sucre seulement (chefsimon)']::text[], ARRAY['poisson','soja','gluten']::text[],
    'Se garde 4 jours au réfrigérateur et gagne nettement à être réchauffé : la sauce continue de pénétrer la viande. Réchauffer à couvert et à feu doux avec deux cuillerées d''eau, la sauce s''étant figée au froid. Se congèle 3 mois sans dommage — c''est l''un des plats du lot qui supporte le mieux le congélateur, la sauce sucrée-salée protégeant la viande. C''est aussi un bon candidat au double : la moitié se sert avec du riz, l''autre effilochée dans un bouillon ou un sandwich.', '{"fridge_hours":96,"eat_immediately":false,"freezable":true,"freezer_months":3,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

