  CROSS JOIN unnest(ARRAY['À l''eau de coco : un litre à la place du bouillon, avec citron vert, coriandre et piment oiseau (chefsimon)','Au quatre-épices, une cuillerée à soupe avec le gingembre (marmiton, deux pages)','Poitrine de porc et œufs durs : 600 g de poitrine mijotés deux heures avec quatre œufs durs (750g)','Moitié échine, moitié poitrine fraîche, avec six grosses échalotes (chefsimon)','En wok, quinze minutes : filet de porc, brocolis, germes de soja, champignons et poivron rouge, trois cuillerées à café de sucre seulement (chefsimon)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
