  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Foncer un moule de la pâte feuilletée, piquer le fond et le cuire à blanc douze minutes à 200 °C, lesté. Une pâte feuilletée non précuite sous un appareil liquide ne feuillette pas : elle se compacte et forme une semelle grise, ce qui est exactement ce qu''on lui demande de ne pas faire.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Tailler le saumon en cubes de deux centimètres, en retirant les arêtes à la pince en passant le doigt à contresens de la chair. Des cubes plutôt que des lamelles : ils restent nacrés au cœur pendant que l''appareil prend, là où des lamelles fines seraient cuites bien avant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Battre les œufs à la fourchette avec la crème et le lait, saler modérément, poivrer, et ajouter l''aneth ciselé. Saler modérément parce que le fromage viendra ensuite ; et l''aneth cru dans l''appareil plutôt qu''en garniture, parce que c''est là qu''il diffuse au lieu de brûler en surface.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Répartir les cubes de saumon sur le fond précuit, en les espaçant régulièrement, parsemer la moitié du gruyère, verser l''appareil et finir du reste de fromage. Les cubes espacés donnent du saumon dans chaque part ; entassés au centre, ils rendent leur jus au même endroit et détrempent une seule zone.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Enfourner à 180 °C pour trente-cinq minutes, jusqu''à ce que la surface soit dorée et que le centre ne soit plus liquide. Le saumon doit rester juste ferme : c''est un poisson gras qui passe du moelleux au sec en quelques minutes, et c''est le repère de cuisson de cette quiche, davantage que la couleur du dessus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Laisser reposer dix minutes avant de découper. L''appareil finit de prendre hors du four et la part se tient alors à la spatule ; découpée brûlante, elle s''effondre et rend du liquide dans l''assiette.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-036', 'recipe_family', 'Quiche au saumon',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-036', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Au saumon fumé : de 100 à 250 g pour six, forme absente du catalogue et donc non écrite ici (marmiton, chefsimon, 750g)','Aux deux saumons : 200 g de saumon frais et 150 g de fumé, avec de la ciboulette (750g)','Aux épinards : 200 g d''épinards hachés surgelés et bien pressés, avec du parmesan et du basilic (marmiton)','Aux brocolis : 180 g après découpe, avec un quart d''oignon et de l''emmental (chefsimon)','Aux courgettes : trois courgettes râpées et dégorgées (marmiton)','Sans pâte : quatre œufs, un demi-litre de lait et 100 g de farine, cuits directement au plat (chefsimon)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-036","variants":["Au saumon fumé : de 100 à 250 g pour six, forme absente du catalogue et donc non écrite ici (marmiton, chefsimon, 750g)","Aux deux saumons : 200 g de saumon frais et 150 g de fumé, avec de la ciboulette (750g)","Aux épinards : 200 g d''épinards hachés surgelés et bien pressés, avec du parmesan et du basilic (marmiton)","Aux brocolis : 180 g après découpe, avec un quart d''oignon et de l''emmental (chefsimon)","Aux courgettes : trois courgettes râpées et dégorgées (marmiton)","Sans pâte : quatre œufs, un demi-litre de lait et 100 g de farine, cuits directement au plat (chefsimon)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-036', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('b603e2d70167bcf9a4c62a02f20a6af0'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_delicate","scores":{"sweet":1,"salty":3,"acidic":1,"bitter":0,"umami":3,"heat":0,"pungency":0,"richness":4,"freshness":2,"intensity":2},"dominant_flavors":["saumon","crème","aneth","gruyère"],"aroma_families":["marin","lactée","herbacé","beurre"],"target_textures":["feuilletage croustillant","intérieur_fondant_ou_crémeux","chair_moelleuse"],"signature_ingredients":["Pavé de saumon cru, sans peau","Crème fraîche liquide entière","Aneth frais"],"identity_guardrails":["Le saumon se taille en cubes et non en lamelles : les cubes restent nacrés quand l''appareil est pris","Fond feuilleté cuit à blanc, sans quoi il se compacte en semelle sous l''appareil","L''aneth entre dans l''appareil et non en surface, où il brûlerait","On sort la quiche quand le saumon est juste ferme — c''est lui, et non la couleur du dessus, qui donne le point"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Quiche aux courgettes', 'quiche aux courgettes', 'France', 'France',
     'meal', 'tarte salée', 'domestic_standard', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Quiche aux courgettes', 'Tarte salée aux courgettes revenues à l''ail dans un appareil œufs-crème', ds.id, 'VAR-037',
    'Myko', 'editorial', 6, 20, 35, 'facile',
    NULL, NULL,
    'B', 'candidate', 'ba32e29b72479e4b923eaa8bd8ce6d1b',
    '{"sweet":3,"salty":3,"acidic":0,"bitter":0,"umami":2,"heat":0,"pungency":2,"richness":3,"freshness":2,"intensity":2}'::jsonb, ARRAY['courgette','crème','ail','huile d''olive']::text[],
    ARRAY['végétal cuit','lactée','ail','huile_olive']::text[], ARRAY['pâte sablée','intérieur_fondant_ou_crémeux','rondelles fermes']::text[],
    ARRAY['Courgette fraîche','Crème fraîche liquide entière','Œuf cru']::text[], ARRAY['Les courgettes se dégorgent puis se sautent à feu vif : sans les deux, la quiche rend de l''eau au four','Aucun fromage n''est écrit ici et c''est le dossier qui le dicte — cinq pages, cinq fromages, aucun sur deux sites','Fond cuit à blanc : 650 g de légumes sur une pâte crue donnent une semelle molle','L''appareil se verse en deux fois, le temps qu''il s''infiltre entre les rondelles']::text[],
    ARRAY['dégorgement','sauté à feu vif','cuisson à blanc','appareil','cuisson au four']::text[], ARRAY['Au chèvre frais : 150 g répartis sur les courgettes (marmiton)','Au parmesan, 60 à 100 g râpés dans l''appareil (chefsimon, deux pages)','À la feta émiettée et à la menthe, sur une pâte au sarrasin et un appareil au yaourt entier (chefsimon)','Aux lardons : 100 à 250 g rissolés et égouttés, ajoutés avec les courgettes (marmiton, 750g)','Au pistou : basilic, ail, parmesan et huile d''olive mixés et étalés sur le fond avant les courgettes (chefsimon)','Aux amandes effilées et aux herbes fraîches, menthe et coriandre (chefsimon)']::text[], ARRAY['gluten','lait','œuf']::text[],
    'Se garde 3 jours au réfrigérateur et se réchauffe 12 minutes à 180 °C. Elle se mange froide sans rien perdre. Se congèle 2 mois cuite, en parts filmées séparément — la courgette y perd un peu de tenue mais la quiche reste bonne. Les courgettes sautées se préparent 3 jours à l''avance et se congèlent 3 mois, ce qui ramène le montage à dix minutes.', '{"fridge_hours":72,"eat_immediately":false,"freezable":true,"freezer_months":2,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
