      WHERE ff.canonical_name_normalized = 'courgette fraiche' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Courgette fraîche', 650, 'g', 'required',
     'légume', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
