  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Rincer les lentilles à l''eau froide et les trier, en écartant les petits cailloux que les paquets contiennent encore. Ne pas les faire tremper : une lentille verte cuit en trois quarts d''heure sans trempage, et trempée elle se défait en purée avant d''avoir pris le goût du bouillon.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire fondre l''oignon émincé et la carotte en petits dés dans l''huile d''olive, à feu doux, dix minutes, avec l''ail haché en fin de course. Cette garniture est tout ce que la soupe a pour se donner du fond, puisqu''elle ne porte ni lard ni chorizo : il faut la laisser vraiment fondre et non simplement chauffer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Ajouter les lentilles, remuer une minute pour les enrober du gras, puis verser le bouillon. Ne pas saler maintenant : le sel en début de cuisson durcit la peau des légumineuses et elles refusent de s''attendrir, quel que soit le temps qu''on leur laisse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Porter à frémissement et laisser cuire quarante-cinq minutes à couvert, à petits bouillons. La soupe est prête quand les lentilles s''écrasent entre deux doigts tout en gardant leur forme dans la cuillère — c''est la texture d''une soupe rustique, à l''opposé du velouté lisse que donnerait une lentille corail.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Saler alors, poivrer et goûter. Si la soupe paraît épaisse, allonger d''un verre d''eau chaude ; si elle est trop liquide, écraser une louche de lentilles contre la paroi et la remettre, ce qui lie sans mixer et garde les grains entiers.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Laisser reposer dix minutes hors du feu avant de servir, avec un filet d''huile d''olive crue dans chaque assiette. L''huile ajoutée à froid garde son parfum, celle qui a cuit quarante-cinq minutes ne l''a plus.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-040', 'recipe_family', 'Soupe de lentilles',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-040', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Soupe de lentilles corail : 120 à 250 g de corail, deux carottes, un oignon, du cumin, du curry ou du lait de coco, mixée en velouté — attestée sur un seul site (marmiton, trois pages)','Au lard demi-sel fumé : une grosse tranche taillée en lardons avec la garniture, et une quenelle de crème fraîche par assiette (chefsimon)','Au chorizo : une pièce en rondelles avec une courgette, un demi-poivron et une pomme de terre (chefsimon)','Au bacon et à l''œuf poché : six tranches grillées et un œuf poché par assiette, avec du thym (750g)','Aux tomates et au parmesan, avec des feuilles de lasagne cassées cuites dedans (chefsimon)','Avec un blanc de poireau émincé ajouté à la carotte (chefsimon)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
