  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-040', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('9a1a79f9dd3e2c99d2e2dd767b48bb8a'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"earthy_herbal","scores":{"sweet":2,"salty":3,"acidic":0,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":2,"freshness":1,"intensity":2},"dominant_flavors":["lentille","oignon fondu","carotte","huile d''olive"],"aroma_families":["légumineuse","oignon_compoté","végétal cuit","huile_olive"],"target_textures":["lentilles fondantes mais entières","bouillon lié par l''amidon"],"signature_ingredients":["Lentille verte sèche, crue","Carotte crue","Oignon jaune cru"],"identity_guardrails":["Lentille verte et non corail : la corail se défait en velouté, et c''est une autre soupe que ce dossier n''atteste que sur un site","On ne sale qu''à la fin — le sel en début de cuisson durcit la peau des légumineuses","Pas de trempage : une lentille verte cuit en trois quarts d''heure et trempée elle part en purée","La soupe reste non mixée, les grains entiers dans la cuillère"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Tarte à la tomate', 'tarte a la tomate', 'France', 'France',
     'meal', 'tarte salée', 'domestic_standard', 'tomato_herbal',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Tarte à la tomate', 'Tarte salée aux tomates sur un fond moutardé, gratinée au gruyère', ds.id, 'VAR-041',
    'Myko', 'editorial', 6, 20, 40, 'facile',
    NULL, NULL,
    'B', 'candidate', 'fe8d729950c7701976bd6aeabb105b11',
    '{"sweet":3,"salty":3,"acidic":3,"bitter":0,"umami":3,"heat":0,"pungency":3,"richness":2,"freshness":2,"intensity":3}'::jsonb, ARRAY['tomate rôtie','moutarde','herbes de Provence','oignon fondu']::text[],
    ARRAY['tomate_cuite','moutarde','herbacé','oignon_compoté']::text[], ARRAY['pâte sablée','tomate confite','contraste_léger']::text[],
    ARRAY['Tomate fraîche mûre','Moutarde de Dijon','Pâte brisée crue']::text[], ARRAY['Aucun appareil aux œufs : une tarte à la tomate liée à la crème est une quiche, et les deux pages qui portent ce titre exact n''en mettent pas','Les tomates se dégorgent une demi-heure — sans appareil pour absorber leur eau, rien d''autre ne protège la pâte','La moutarde s''étale sur le fond précuit encore chaud, où elle sèche en film','On cuit jusqu''à ce que les bords des rondelles brunissent : c''est là que la tomate se concentre']::text[],
    ARRAY['dégorgement','fondue d''oignons','cuisson à blanc','cuisson au four']::text[], ARRAY['À la moutarde et au thon : deux boîtes égouttées sous les tomates, avec deux œufs et 20 cl de crème (marmiton, deux pages)','Au chèvre : une bûche en rondelles sur les tomates, avec un appareil de deux œufs, un décilitre de crème et un de lait, et du thym sec (chefsimon)','Au parmesan et à la chapelure : deux cuillerées de chapelure fine étalées sur la moutarde pour absorber le jus, deux de parmesan sur les tomates, et une burrata déchirée au service (chefsimon)','Au pesto, cent grammes étalés à la place de la moutarde (chefsimon)']::text[], ARRAY['gluten','lait','moutarde']::text[],
    'Se garde 2 jours au réfrigérateur et se réchauffe 10 minutes à 190 °C pour rendre à la pâte son croustillant ; froide, elle est correcte mais la pâte a ramolli. Ne se congèle pas cuite — la tomate rend toute son eau à la décongélation et le fond se défait. Le fond cuit à blanc se garde en revanche 3 jours dans une boîte et se congèle 2 mois, ce qui ramène la tarte à un quart d''heure de montage.', '{"fridge_hours":48,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

