     'assaisonnement', false, 9);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Trancher les tomates en rondelles de cinq millimètres, les ranger à plat sur une grille ou du papier absorbant, les saler légèrement et les laisser rendre leur eau une demi-heure. Sans appareil aux œufs pour absorber ce jus, cette demi-heure est la seule protection de la pâte, et c''est elle qui décide entre une tarte croustillante et une tarte molle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Émincer l''oignon en lamelles fines et le faire fondre dix minutes dans la moitié de l''huile d''olive, sans coloration. Cru sous les tomates, il reste croquant et piquant sous une tarte par ailleurs douce, et c''est un décalage qu''on remarque à chaque bouchée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Foncer un moule de la pâte brisée, piquer le fond à la fourchette et le cuire à blanc quinze minutes à 180 °C, lesté. Une tarte à la tomate sans appareil n''a rien pour tenir sa pâte au sec : la cuisson à blanc n''est pas ici une commodité, c''est la structure du plat.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Étaler la moutarde en couche mince sur le fond précuit et encore chaud, puis répartir l''oignon fondu par-dessus. La moutarde sur une pâte chaude sèche instantanément et forme un film ; posée sur une pâte froide, elle reste humide sous les tomates.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ranger les rondelles de tomate épongées en rosace, en les faisant se chevaucher légèrement, poivrer et parsemer des herbes de Provence puis du gruyère râpé. Un chevauchement léger et non un empilement : deux épaisseurs de tomate ne cuisent pas, elles s''affaissent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Arroser du reste d''huile d''olive et enfourner à 180 °C pour quarante minutes, jusqu''à ce que les bords des rondelles soient bruns et légèrement ridés. C''est cette caramélisation des bords qui concentre le goût de la tomate ; une tarte sortie trop tôt est aqueuse et fade quelle que soit la qualité des fruits. Laisser tiédir dix minutes avant de couper.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-041', 'recipe_family', 'Tarte à la tomate',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-041', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['À la moutarde et au thon : deux boîtes égouttées sous les tomates, avec deux œufs et 20 cl de crème (marmiton, deux pages)','Au chèvre : une bûche en rondelles sur les tomates, avec un appareil de deux œufs, un décilitre de crème et un de lait, et du thym sec (chefsimon)','Au parmesan et à la chapelure : deux cuillerées de chapelure fine étalées sur la moutarde pour absorber le jus, deux de parmesan sur les tomates, et une burrata déchirée au service (chefsimon)','Au pesto, cent grammes étalés à la place de la moutarde (chefsimon)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-041","variants":["À la moutarde et au thon : deux boîtes égouttées sous les tomates, avec deux œufs et 20 cl de crème (marmiton, deux pages)","Au chèvre : une bûche en rondelles sur les tomates, avec un appareil de deux œufs, un décilitre de crème et un de lait, et du thym sec (chefsimon)","Au parmesan et à la chapelure : deux cuillerées de chapelure fine étalées sur la moutarde pour absorber le jus, deux de parmesan sur les tomates, et une burrata déchirée au service (chefsimon)","Au pesto, cent grammes étalés à la place de la moutarde (chefsimon)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-041', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('fe8d729950c7701976bd6aeabb105b11'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"tomato_herbal","scores":{"sweet":3,"salty":3,"acidic":3,"bitter":0,"umami":3,"heat":0,"pungency":3,"richness":2,"freshness":2,"intensity":3},"dominant_flavors":["tomate rôtie","moutarde","herbes de Provence","oignon fondu"],"aroma_families":["tomate_cuite","moutarde","herbacé","oignon_compoté"],"target_textures":["pâte sablée","tomate confite","contraste_léger"],"signature_ingredients":["Tomate fraîche mûre","Moutarde de Dijon","Pâte brisée crue"],"identity_guardrails":["Aucun appareil aux œufs : une tarte à la tomate liée à la crème est une quiche, et les deux pages qui portent ce titre exact n''en mettent pas","Les tomates se dégorgent une demi-heure — sans appareil pour absorber leur eau, rien d''autre ne protège la pâte","La moutarde s''étale sur le fond précuit encore chaud, où elle sèche en film","On cuit jusqu''à ce que les bords des rondelles brunissent : c''est là que la tomate se concentre"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Bolognaise végétarienne', 'bolognaise vegetarienne', 'Italie', 'Italie',
     'meal', 'sauce', 'domestic_standard', 'tomato_herbal',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Bolognaise végétarienne', 'Sauce tomate mijotée avec courgette, aubergine et carotte finement taillées, sans viande', ds.id, 'VAR-044',
    'Myko', 'editorial', 6, 20, 35, 'facile',
    NULL, NULL,
    'B', 'candidate', '9a56e978860c2c94ef8f89224924e83f',
    '{"sweet":3,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":2,"freshness":2,"intensity":3}'::jsonb, ARRAY['tomate mijotée','légumes fondus','basilic','ail']::text[],
    ARRAY['tomate_cuite','oignon_compoté','basilic','huile_olive']::text[], ARRAY['sauce_épaisse','légumes fondants','nappant']::text[],
    ARRAY['Tomate concassée en conserve','Aubergine fraîche','Carotte crue']::text[], ARRAY['Les légumes se taillent en dés de trois à quatre millimètres : c''est la découpe, et non la cuisson, qui donne la texture d''un ragù','Le concentré de tomate se torréfie deux minutes avant d''être mouillé, sinon il garde son goût de boîte','Trente-cinq minutes de réduction à découvert : une sauce de légumes non réduite reste une soupe','Le basilic entre hors du feu — cuit, il noircit en cinq minutes']::text[],
    ARRAY['taille en brunoise','suer','torréfaction du concentré','mijotage','réduction']::text[], ARRAY['Aux protéines de soja texturées ou au haché végétal, 50 à 240 g réhydratés, formes absentes du catalogue (marmiton, chefsimon, 750g)','Au poivron rouge, au céleri branche et à un verre de vin rouge (750g, deux pages)','Aux champignons de Paris, trois pièces émincées avec les légumes (marmiton)','Au beurre de cacahuète, deux cuillerées à soupe, avec paprika et curcuma (chefsimon)','Au romarin, au thym et au laurier, une cuillerée à café de chaque (chefsimon)']::text[], ARRAY[]::text[],
    'Se garde 5 jours au réfrigérateur en bocal fermé sous un film d''huile d''olive, et se congèle 4 mois en portions — c''est la préparation à faire en double ou en triple. Elle sert de sauce à pâtes, de couche de lasagnes, de base de gratin de courgettes ou de fond sous une purée. Réchauffer à feu doux avec une cuillerée d''eau. Le basilic se rajoute frais à chaque usage plutôt que congelé avec la sauce.', '{"fridge_hours":120,"eat_immediately":false,"freezable":true,"freezer_months":4,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

