  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Émincer les oignons, tailler le poivron en lanières fines, hacher l''ail et râper le gingembre. Monder les tomates si l''on veut une sauce lisse — une croix sous chacune, trente secondes dans l''eau bouillante, puis l''eau glacée — sinon les concasser peau comprise, ce que font la plupart des sources.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire suer les oignons dans l''huile à feu moyen pendant six à huit minutes, sans les colorer. On cherche leur sucre, pas leur grillé : un oignon doré donnerait au lait de coco une note torréfiée qui écraserait le gingembre. Ajouter le poivron et poursuivre cinq minutes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Ajouter l''ail et le gingembre, remuer trente secondes, puis verser les tomates concassées. Laisser compoter à feu vif cinq minutes, jusqu''à ce que l''eau de végétation soit partie et que le fond de la poêle grésille au lieu de bouillonner.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser le lait de coco, saler, poivrer, ajouter le piment d''Espelette et laisser réduire dix minutes à feu doux et à découvert, sans jamais faire bouillir franchement : au gros bouillon le lait de coco se dissocie et rend une sauce grainée où l''huile surnage. La sauce est prête quand elle nappe le dos d''une cuillère.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Plonger les crevettes dans la sauce frémissante et compter trois minutes, pas plus, en les retournant à mi-parcours. Elles finissent de cuire dans la chaleur de la sauce pendant qu''on porte le plat à table. Goûter et rectifier le sel : le lait de coco en absorbe beaucoup plus qu''on ne croit.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'DEN-002', 'recipe_family', 'Crevettes au lait de coco',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'DEN-002', 'missing_required_count', v_missing), 'open');
  END IF;

