  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:DEN-002', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('fd604829637d16251174cce62357515d'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":2,"acidic":2,"bitter":0,"umami":3,"heat":1,"pungency":2,"richness":4,"freshness":2,"intensity":3},"dominant_flavors":["lait de coco","crevette","tomate cuite","gingembre"],"aroma_families":["coco","marin","tomate_cuite","gingembre"],"target_textures":["sauce nappante","chair nacrée et moelleuse"],"signature_ingredients":["Crevette crue décortiquée","Lait de coco","Tomate fraîche mûre"],"identity_guardrails":["Pas de curry : c''est ce qui sépare ce plat de « Crevettes au curry » déjà au corpus","Le lait de coco ne bout jamais — il tranche et rend une sauce grainée","La crevette entre en dernier et cuit trois minutes : au-delà elle se rétracte et durcit","La tomate est cuite jusqu''à évaporation avant le lait de coco, sinon la sauce reste aqueuse"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
