  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Poêlée de fruits de mer', 'Un sachet de fruits de mer surgelés réchauffé sur une échalote fondue, tomate concassée et une pointe de crème', ds.id, 'DEN-003',
    'Myko', 'editorial', 4, 10, 20, 'facile',
    NULL, NULL,
    'B', 'candidate', '301d5dff600a4b2bbb3b845fcc4a3635',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":1,"pungency":2,"richness":3,"freshness":2,"intensity":3}'::jsonb, ARRAY['fruits de mer','tomate cuite','échalote fondue','crème']::text[],
    ARRAY['fruits_de_mer','tomate_cuite','échalote','crème']::text[], ARRAY['chair nacrée et moelleuse','jus court et nappant']::text[],
    ARRAY['Fruits de mer cuits surgelés','Tomate fraîche mûre','Échalote crue']::text[], ARRAY['Les fruits de mer sont vendus cuits : trois minutes de réchauffage, pas une cuisson','La tomate réduit avant l''arrivée des fruits de mer, sinon le plat rend de l''eau à l''assiette','La crème entre hors du feu et reste une pointe : au-delà, ce n''est plus une poêlée mais une blanquette','Ne jamais décongeler le sachet à l''avance dans un saladier — l''eau rendue emporte le goût']::text[],
    ARRAY['égouttage','suer','réduction','sauté','liaison à la crème']::text[], ARRAY['Poivron vert taillé en dés, ajouté avec la tomate (marmiton)','Deux cuillerées de curry à la place du piment, avec des poireaux émincés à la place de l''échalote (marmiton)','Basilic et origan frais ciselés hors du feu, et un copeau de parmesan à l''assiette (chefsimon)','Piment de Cayenne et paprika à la place du piment d''Espelette, pour une poêlée nettement plus relevée (marmiton)']::text[], ARRAY['crustacés','mollusques','lait']::text[],
    'Se garde 24 heures au réfrigérateur entre 0 et 4 °C, dans une boîte fermée. Ne se congèle PAS : les fruits de mer ont déjà subi une congélation et une seconde ruinerait leur texture autant que leur sécurité. Se réchauffe à feu doux deux minutes, jamais au micro-ondes à pleine puissance.', '{"fridge_hours":24,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
