  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Équeuter les haricots verts et les plonger huit minutes dans un grand volume d''eau bouillante fortement salée, puis les égoutter et les rafraîchir aussitôt dans l''eau glacée. Ce choc thermique fixe la chlorophylle : sans lui, les haricots continuent de cuire sur leur chaleur et virent au vert olive.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Couper les blancs de poulet en gros cubes de trois centimètres, les saler et les poivrer. Émincer l''oignon en demi-lunes assez épaisses pour qu''il tienne à la cuisson sans se défaire en purée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chauffer l''huile à feu vif dans une sauteuse et faire dorer les cubes de poulet sur toutes leurs faces, cinq à six minutes, sans les remuer trop souvent. La croûte dorée est le goût du plat : elle ne se forme que si la viande reste immobile assez longtemps pour que sa surface sèche.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Baisser le feu, ajouter l''oignon, le thym et les feuilles de laurier, et laisser fondre huit minutes à couvert. L''oignon rend son eau et déglace naturellement les sucs collés au fond, ce qui donne le jus du plat sans qu''on ait besoin d''ajouter de liquide.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter les haricots égouttés, mélanger et poursuivre à découvert cinq minutes à feu moyen, le temps qu''ils se réchauffent et prennent le jus. Retirer le laurier, goûter et rectifier l''assaisonnement avant de servir bien chaud.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'DEN-012', 'recipe_family', 'Poulet aux haricots verts',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'DEN-012', 'missing_required_count', v_missing), 'open');
  END IF;

