  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:DEN-012', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('dbf0322fd1c9e0def18cecba25f3ac2d'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"earthy_herbal","scores":{"sweet":1,"salty":2,"acidic":0,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":2,"freshness":3,"intensity":2},"dominant_flavors":["poulet doré","haricot vert","oignon fondu","thym"],"aroma_families":["poulet","haricot","oignon_compoté","thym"],"target_textures":["tendre","haricot fondant à peau intacte","jus court et nappant"],"signature_ingredients":["Blanc de poulet cru, sans peau","Haricot vert cru","Thym frais"],"identity_guardrails":["Les haricots sont blanchis puis glacés à part : cuits avec la viande, ils grisent","Le poulet dore avant tout le reste, la croûte est le goût du plat","Aucun liquide ajouté : le jus vient de l''eau rendue par l''oignon","Pas de crème — c''est une poêlée, la version crémée est une variante déclarée"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
