  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:DEN-013', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('bda5ff5eff2abcf49c7d3a5a543170a5'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":2,"acidic":1,"bitter":0,"umami":4,"heat":0,"pungency":3,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["poulet doré","champignon","crème","moutarde"],"aroma_families":["poulet","champignon_terreux","crème","moutarde"],"target_textures":["tendre","lamelles de champignon tendres","sauce nappante"],"signature_ingredients":["Blanc de poulet cru, sans peau","Champignon de Paris frais","Crème fraîche liquide entière"],"identity_guardrails":["Les champignons sont poêlés à sec jusqu''à évaporation complète avant toute matière grasse","La moutarde entre hors du feu, sinon elle tourne amère et perd son piquant","Le poulet est émincé et saisi vif : c''est un sauté de vingt-cinq minutes, pas un mijoté","Ne pas laver les champignons à l''eau — ils la boivent et la rendent dans la poêle"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Bœuf aux brocolis', 'boeuf aux brocolis', 'Chine / cuisine domestique adaptée', 'Chine / cuisine domestique adaptée',
     'meal', 'bœuf sauté', 'domestic_standard', 'spicy_umami',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Bœuf aux brocolis', 'Lamelles de bœuf saisies au wok et brocolis croquants, glacés d''une sauce soja au gingembre et à l''ail', ds.id, 'DEN-014',
    'Myko', 'editorial', 4, 20, 15, 'facile',
    NULL, NULL,
    'B', 'candidate', '8c693a2ef2b425d50b4ca85aaca3799d',
    '{"sweet":2,"salty":4,"acidic":0,"bitter":1,"umami":5,"heat":0,"pungency":3,"richness":3,"freshness":2,"intensity":4}'::jsonb, ARRAY['bœuf saisi','sauce soja','gingembre','brocoli']::text[],
    ARRAY['bœuf_saisi','soja','gingembre','sésame_toasté']::text[], ARRAY['tendre','bouquets fondants','sauce nappante']::text[],
    ARRAY['Bœuf à griller cru, en fines lamelles','Brocoli cru','Sauce soja']::text[], ARRAY['Le bœuf est tranché en travers des fibres et saisi une minute : au-delà il devient coriace','Le brocoli est blanchi avant le wok, sinon il n''est pas cuit quand la viande l''est déjà trop','L''huile de sésame arrive hors du feu — chauffée, elle devient amère et perd son parfum','Le sucre est une pointe qui fait laquer, pas un assaisonnement sucré']::text[],
    ARRAY['taillage','marinade','blanchiment','saisie vive','sauté']::text[], ARRAY['Deux cuillerées de sauce d''huître et une de nuoc mam dans la marinade (marmiton)','Nouilles chinoises sautées dans le wok à la fin, avec du poivron rouge et des champignons noirs (chefsimon)','Deux cuillerées de saté en poudre dans la sauce, servi sur du riz basmati (chefsimon)','Riz sauté dans le même wok après la viande, façon plat unique (marmiton)']::text[], ARRAY['soja','gluten','sésame']::text[],
    'Se garde 2 jours au réfrigérateur entre 0 et 4 °C, mais le bœuf continue de durcir : le manger froid émincé en salade vaut mieux qu''un réchauffage. Se congèle 2 mois, la viande ressortant nettement plus ferme. Ne pas réchauffer au micro-ondes.', '{"fridge_hours":48,"eat_immediately":false,"freezable":true,"freezer_months":2,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    NULL, '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
