  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Placer le morceau de bœuf vingt minutes au congélateur avant de le trancher : raffermi, il se coupe en lamelles de deux millimètres qu''aucun couteau n''obtiendrait sur une viande souple. Trancher en travers des fibres, sans quoi les lamelles resteront coriaces quelle que soit la cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Mélanger la sauce soja, le sucre, l''ail haché et le gingembre râpé dans un bol, et y faire mariner les lamelles pendant qu''on prépare les légumes — quinze minutes suffisent. Détacher les bouquets de brocoli, éplucher et trancher le tronc, émincer l''oignon.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Blanchir les bouquets de brocoli trois minutes dans l''eau bouillante salée, les égoutter et les passer sous l''eau froide. Au wok seul, un brocoli met huit minutes à cuire et le bœuf serait alors trop cuit depuis longtemps : le blanchiment préalable est ce qui permet aux deux d''arriver ensemble.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Chauffer l''huile d''arachide dans un wok jusqu''à ce qu''elle fume, égoutter les lamelles de leur marinade en gardant celle-ci, et les saisir en deux fournées, une minute chacune, sans les remuer plus de deux fois. Les débarrasser dès qu''elles sont colorées : elles sont encore rosées à cœur, et c''est ce qui les gardera tendres.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Faire sauter l''oignon deux minutes dans le wok, ajouter le brocoli égoutté puis la marinade réservée, et laisser bouillonner une minute pour qu''elle réduise en un glaçage brillant. Remettre le bœuf, mélanger dix secondes, couper le feu, verser l''huile de sésame et poivrer. Servir immédiatement.');

  INSERT INTO quality.review_tasks
