  CROSS JOIN unnest(ARRAY['Deux cuillerées de sauce d''huître et une de nuoc mam dans la marinade (marmiton)','Nouilles chinoises sautées dans le wok à la fin, avec du poivron rouge et des champignons noirs (chefsimon)','Deux cuillerées de saté en poudre dans la sauce, servi sur du riz basmati (chefsimon)','Riz sauté dans le même wok après la viande, façon plat unique (marmiton)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
