  SELECT
    v_family, 3, 'Wok de poulet aux légumes', 'Escalopes de poulet et légumes taillés fin, sautés à feu vif dans le soja, le gingembre et le sésame', ds.id, 'DEN-015',
    'Myko', 'editorial', 4, 20, 15, 'facile',
