  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Égoutter les pois chiches et les rincer longuement à l''eau froide jusqu''à ce que l''eau cesse de mousser. Le jus de conserve a un goût métallique tenace qui ressort dans un plat mijoté, et trente secondes de rinçage le règlent définitivement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Couper le poulet en gros morceaux, saler et poivrer. Les faire dorer dans l''huile chaude à feu vif, cinq à six minutes, puis les réserver hors de la cocotte. Émincer l''oignon, tailler le poivron en lamelles, hacher l''ail.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Faire fondre l''oignon et le poivron dans la cocotte à feu moyen pendant huit minutes, en grattant les sucs. Ajouter l''ail et la cannelle et remuer une minute à sec : une épice moulue jetée dans un liquide reste poudreuse, alors qu''un passage dans le gras chaud libère ses arômes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser le bouillon, ajouter les pois chiches rincés et laisser mijoter vingt minutes à couvert et à petit feu. Les pois chiches sont déjà cuits : ce temps n''est pas là pour les attendrir mais pour qu''ils prennent le goût du fond.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Remettre le poulet avec son jus, découvrir et poursuivre huit minutes pour que le bouillon réduise et nappe les pois chiches. Goûter, rectifier le sel et le poivre, et laisser reposer cinq minutes hors du feu avant de servir.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'DEN-017', 'recipe_family', 'Poulet aux pois chiches',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'DEN-017', 'missing_required_count', v_missing), 'open');
  END IF;

