  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Laver les épinards dans un grand volume d''eau et les sécher en essoreuse à salade. Retirer les côtes des grandes feuilles, qui restent fibreuses quand le limbe est déjà fondu ; les jeunes pousses se gardent entières.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire fondre l''oignon émincé dans l''huile à feu moyen pendant six minutes, puis ajouter les épinards par grosses poignées, en attendant que chacune retombe avant d''enfourner la suivante. Quatre cents grammes de feuilles crues tiennent dans une poêle en trois fois et donnent à peine 150 g une fois tombés.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Monter le feu et laisser l''eau des épinards s''évaporer complètement, deux à trois minutes, jusqu''à ce que la poêle chuinte au lieu de bouillonner. Des épinards humides feraient une omelette qui rend son eau à l''assiette, et c''est le défaut classique de ce plat. Saler, poivrer et débarrasser.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Battre les œufs avec le lait à la fourchette, une quinzaine de secondes seulement : trop battus, ils s''allègent en mousse et l''omelette prend une texture de flan soufflé qui retombe. Incorporer les épinards et la moitié du gruyère.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
