  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Chauffer la moitié de l''huile à feu vif dans la poêle et saisir les crevettes une minute par face, juste le temps qu''elles rosissent et se referment en virgule. Les débarrasser aussitôt : elles repasseront trente secondes dans l''omelette et une cuisson complète maintenant les rendrait caoutchouteuses.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
