    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'required',
     'assaisonnement', false, 6);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Retirer le gras périphérique des tranches de jambon et les couper en lanières d''un demi-centimètre plutôt qu''en dés : les lanières se répartissent dans l''œuf sans tomber toutes au fond, ce que font les dés.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Casser les œufs dans un bol, poivrer et saler avec retenue — le jambon apporte déjà l''essentiel du sel — puis battre à la fourchette une quinzaine de secondes, jusqu''à ce que blancs et jaunes soient tout juste homogènes et que la surface porte encore quelques bulles.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chauffer l''huile et le beurre ensemble dans une poêle de vingt-huit centimètres à feu moyen. L''huile empêche le beurre de noircir : seul, il brunirait avant que la poêle ne soit à température, et cette amertume-là traverse l''œuf.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Quand la mousse du beurre retombe, verser les œufs d''un coup et attendre dix secondes sans y toucher. Puis, à la spatule, ramener les bords pris vers le centre en inclinant la poêle pour que l''œuf liquide prenne leur place. Répéter quatre ou cinq fois.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Répartir les lanières de jambon sur la moitié de l''omelette pendant que le dessus est encore brillant, plier et laisser vingt secondes de plus. Le jambon est déjà cuit : il ne demande qu''à être chaud, et prolonger la cuisson le rendrait sec et salé.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'DEN-021', 'recipe_family', 'Omelette au jambon',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
