  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Décongeler les épinards à la poêle à couvert et à feu doux, une dizaine de minutes, puis les verser dans une passoire et les PRESSER de toutes ses forces contre la paroi, à la louche ou à la main. Il en sort une quantité d''eau qui surprend toujours, et c''est elle qui déciderait sinon du sort de la frittata : un appareil dilué ne prend pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Préchauffer le four à 180 °C. Faire fondre l''oignon émincé dans l''huile à feu doux pendant huit minutes dans une poêle de vingt-quatre centimètres allant au four, puis ajouter les épinards pressés et remuer deux minutes pour les dessécher encore un peu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Battre les œufs avec le lait, le parmesan râpé, le sel et le poivre, sans excès d''énergie. Goûter l''appareil du bout du doigt : le parmesan est déjà salé, et une frittata trop salée ne se rattrape pas une fois prise.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser l''appareil sur les épinards, mélanger d''un geste pour les répartir, et laisser prendre sur le feu le plus doux pendant huit à dix minutes sans y toucher. Les bords doivent être fermes et le centre encore liquide : c''est cette prise lente par le dessous qui donne à la frittata sa texture serrée et sans bulles.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Enfourner la poêle vingt minutes à 180 °C, jusqu''à ce que le centre soit tout juste pris et légèrement bombé. Sortir, laisser tiédir dix minutes dans la poêle puis démouler sur une planche : à chaud elle se casse, tiède elle se coupe net en parts.');

