  FROM axis
  CROSS JOIN unnest(ARRAY['Épinards frais lavés et tombés à la poêle à la place des surgelés (marmiton, chefsimon, 750g)','200 g de lardons rissolés et 100 g de feta émiettée, l''appareil monté à la crème (marmiton)','Burrata déchirée sur la frittata à la sortie du four, avec pignons de pin et menthe (chefsimon)','Pommes de terre en rondelles précuites et petits pois, avec du Grana Padano et de la ciboulette (750g)','Champignons et poivron rouge revenus avec l''oignon, emmental râpé et origan séché (chefsimon)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
