  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:DEN-022', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('657884488aa77c2a8873895e94f372c2'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"nutty_savory","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3},"dominant_flavors":["œuf","épinard","parmesan","oignon fondu"],"aroma_families":["œuf cuit","épinard","parmesan","oignon_compoté"],"target_textures":["appareil pris","moelleux","feuilles fondantes"],"signature_ingredients":["Œuf cru","Épinard surgelé","Parmesan affiné"],"identity_guardrails":["Les épinards sont pressés jusqu''à ce qu''ils ne rendent plus rien : c''est le geste qui fait ou défait la frittata","Prise lente à feu doux d''abord, four ensuite — une frittata saisie fort gonfle puis retombe","Elle se démoule tiède, jamais brûlante, sinon elle se casse","Épaisse et coupée en parts : une frittata ne se plie pas, c''est ce qui la sépare d''une omelette"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
