    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-001'), '{"variant_label":"Avec chou vert blanchi à part","rationale":"Le chou se cuit à part et non dans la marmite : plongé dans le bouillon, il l''emporterait sur tout le reste et le troublerait. Blanchi séparément puis fini dans une louche de bouillon, il garde sa tenue et le bouillon sa clarté.","operations":[{"op":"add","form":"Chou vert frais","quantity":800,"unit":"g","role":"légume"}],"steps":[{"op":"insert","after":6,"instruction":"Pendant ce temps, ôter les grosses côtes du chou vert et le tailler en larges lanières. Le plonger cinq minutes dans une grande casserole d''eau bouillante salée, l''égoutter, puis le laisser fondre vingt minutes dans deux louches de bouillon prélevées à la marmite."}]}'::jsonb, NULL
