    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-004-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-004-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('ff9d2eebf0a15f2ecf1fc9ecfe7d2bcb'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":2,"acidic":0,"bitter":0,"umami":0,"heat":3,"pungency":0,"richness":3,"freshness":5,"intensity":2},"dominant_flavors":["pomme_fondante","cidre","crème_normande"],"aroma_families":["pomme_cuite","beurre_noisette","champignon"],"target_textures":["sauce_nappante","pomme_fondante","chair_moelleuse"],"signature_ingredients":["Cidre brut","Calvados","Pomme fraîche"],"identity_guardrails":["Le cidre est brut, jamais doux : le sucre résiduel déséquilibrerait la sauce.","Les pommes sont un fruit et la signature du plat — les retirer en fait une simple fricassée à la crème."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
