  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Détailler la dinde en cubes d''environ 4 cm. Émincer l''oignon, couper les carottes en rondelles épaisses, fendre le poireau dans la longueur, le rincer et le tronçonner. Dégermer et hacher l''ail. Brosser les champignons et les partager en quartiers.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire chauffer l''huile d''olive avec la moitié du beurre dans une cocotte à fond épais. Y déposer les cubes de dinde et les remuer sur feu moyen : ils doivent seulement blanchir et raidir, sans jamais prendre de couleur. Assaisonner de sel et de poivre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Ajouter l''oignon et l''ail, poursuivre deux à trois minutes toujours sans coloration, puis poudrer de farine. Remuer une minute pleine pour que la farine perde son goût cru et enrobe la viande.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser le vin blanc en grattant le fond à la spatule, laisser l''alcool s''évaporer une minute. Mouiller avec le bouillon et l''eau, ajouter le thym, les carottes et les poireaux, puis amener doucement au frémissement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Préchauffer le four à 150 °C. Couvrir la cocotte et l''enfourner à mi-hauteur une heure trente, sans y toucher. La dinde doit se défaire sous la fourchette et le jus avoir à peine réduit.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Vingt minutes avant la fin, saisir les champignons dans le beurre restant à feu vif jusqu''à ce que leur eau se soit évaporée et qu''ils brillent, puis les glisser dans la cocotte et refermer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Couper le feu, attendre que le bouillonnement cesse puis incorporer la crème. Si la sauce reste trop fluide, délayer la fécule dans deux cuillères de jus refroidi, l''ajouter et laisser épaissir deux minutes sans jamais faire bouillir. Rectifier l''assaisonnement et parsemer de persil ciselé au moment de servir.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-008-D4', 'recipe_family', 'Blanquette de dinde au four',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-008-D4', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-008-D4', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-008-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('258e6d714ead168cb9059d839160adfc'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":2,"salty":3,"acidic":1,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["volaille","crème","champignon"],"aroma_families":["lacté","herbacé","aillé"],"target_textures":["sauce nappante","viande fondante","légumes tendres"],"signature_ingredients":["Escalope de dinde crue","Crème fraîche liquide entière","Champignon de Paris frais"],"identity_guardrails":["La viande ne doit pas colorer : une dinde saisie brune donne un sauté en sauce brune, plus une blanquette.","Sans liaison crémée blanche (crème et farine), il ne reste qu''un bouillon de volaille aux légumes.","Pas de tomate ni de concentré de tomates : la sauce doit rester ivoire.","La crème s''incorpore hors ébullition, sinon elle tranche et la texture nappante est perdue."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Croque-madame au four', 'croque madame au four', 'France', 'France',
     'meal', 'sandwich chaud', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Croque-madame au four', 'Pain de mie au jambon et emmental gratiné au four, surmonté d''un œuf', ds.id, 'SRC-011-D1',
    'Myko', 'editorial', 4, 15, 18, 'facile',
    NULL, NULL,
    'B', 'candidate', '80d29e01a7a4044b8c328f0806319f30',
    '{"sweet":1,"salty":4,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":0,"intensity":3}'::jsonb, ARRAY['fromage fondu','jambon sale','beurre dore']::text[],
    ARRAY['lactee','grillee','beurree']::text[], ARRAY['pain grille croustillant','coeur fondant','jaune coulant']::text[],
    ARRAY['Pain de mie','Œuf cru','Jambon blanc cuit','Emmental râpé']::text[], ARRAY['Sans l''oeuf pose sur le dessus, le plat redevient un croque-monsieur et perd son nom.','Le pain de mie est la seule enveloppe admise : remplace par une baguette ou un pain de campagne, ce n''est plus un croque.','Le couple jambon blanc cuit et fromage fondu forme le coeur du plat ; retirer l''un des deux le denature.']::text[],
    ARRAY['saisie','gratinage']::text[], ARRAY[]::text[], ARRAY['gluten','lait','œuf']::text[],
    'Se mange immediatement, le jaune coulant ne supportant pas l''attente. Un croque deja garni se garde au maximum 24 heures a 4 degres au refrigerateur et se rechauffe dix minutes a 180 degres, l''oeuf devenant alors ferme. La congelation ne convient qu''au croque monte cru et non garni d''oeuf, jusqu''a un mois a -18 degres, a cuire sans decongelation prealable.', '{"fridge_hours":24,"eat_immediately":true,"freezable":false,"freezer_months":null,"serve_cold":false,"source":"manual"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-011'), '{"variant_label":"Version integralement au four : monter les croques beurres, enfourner a 210 degres pendant quinze minutes, puis coiffer chacun d''un oeuf au plat cuit a part.","rationale":"Le four cuit les quatre croques d''un coup et sans les presser : la mie reste plus aérée qu''à la poêle, la croûte plus sèche. L''œuf ne peut plus profiter du beurre de la poêle, il se cuit à part.","operations":[],"steps":[{"op":"replace","n":4,"instruction":"Préchauffer le four à 210 °C. Déposer les croques sur une plaque garnie de papier cuisson et les enfourner à mi-hauteur douze minutes, en les retournant à mi-parcours pour que les deux faces dorent également."},{"op":"replace","n":5,"instruction":"Sortir la plaque, couvrir les croques de gruyère râpé et les remettre trois minutes sous le gril, juste le temps que la surface prenne une croûte dorée sans que le pain ne noircisse."},{"op":"replace","n":6,"instruction":"Pendant ce temps, faire fondre le beurre restant dans une poêle à feu doux, y casser les quatre œufs, assaisonner de sel fin et de poivre noir moulu, puis couvrir une minute pour que le blanc se fige alors que le jaune reste liquide."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
