      WHERE ff.canonical_name_normalized = 'jambon blanc cuit' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Jambon blanc cuit', 160, 'g', 'required',
     'proteine', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
