  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Gratin de brocolis végétarien', 'Brocolis blanchis gratinés dans une sauce béchamel crémeuse, sans protéine animale', ds.id, 'SRC-012-D1',
    'Myko', 'editorial', 4, 25, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', '9b9ca5546ef84e45faa9c5ed306b22f1',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":2,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['lacté','fromagé','végétal vert']::text[],
    ARRAY['lacté','alliacé','épicé doux']::text[], ARRAY['fondant','croûte gratinée croustillante','appareil pris']::text[],
    ARRAY['Brocoli cru','Lait entier','Gruyère râpé']::text[], ARRAY['Sans brocoli, le plat n''existe plus : c''est lui qui donne le nom, la couleur et la légère amertume végétale du gratin.','Sans liaison lactée à base de lait entier et de farine, on obtient des bouquets gratinés et non un gratin : la béchamel est ce qui lie le légume.','Sans couverture de gruyère râpé et de chapelure, il manque la croûte dorée qui définit le gratinage.','Le brocoli doit rester ferme et bien égoutté : trop cuit ou détrempé, il délave la sauce et fait rendre de l''eau au plat.']::text[],
    ARRAY['blanchiment','gratinage','réduction']::text[], ARRAY[]::text[], ARRAY['gluten','lait','œuf']::text[],
    'Se conserve 3 jours au réfrigérateur entre 0 et 4 °C, dans le plat filmé ou en boîte hermétique une fois refroidi à cœur. Réchauffer 15 à 20 minutes à 160 °C plutôt qu''au micro-ondes, pour retrouver la croûte. La congélation est déconseillée : l''appareil aux œufs et à la crème se dissocie en rendant de l''eau à la décongélation et le brocoli devient filandreux ; si on y tient, congeler avant cuisson au four, jusqu''à 1 mois à -18 °C, et enfourner sans décongeler en ajoutant 20 minutes.', '{"fridge_hours":72,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-012'), '{"variant_label":"Version végétarienne : retirer le jambon blanc cuit et compenser en portant le gruyère râpé à 120 g pour garder du corps à l''appareil.","rationale":"Sans jambon, l''appareil perd son sel et sa mâche. Le gruyère majoré rend l''un et l''autre : le gratin reste un plat, il ne devient pas un accompagnement.","operations":[{"op":"remove","form":"Jambon blanc cuit"},{"op":"set","form":"Gruyère râpé","quantity":120}],"steps":[{"op":"replace","n":5,"instruction":"Battre les œufs à la fourchette dans un saladier. Y verser d''abord une louche de sauce tiédie en fouettant pour les tempérer, puis reverser le tout dans la casserole et mélanger. Incorporer la moitié du gruyère râpé ; goûter et rectifier l''assaisonnement à ce stade, la cuisson ne le corrigera plus."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
