  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Rincer les lentilles sous l''eau froide dans une passoire fine jusqu''à ce que l''eau ressorte claire. Peler la carotte et la tailler en rondelles de 3 mm, fendre le poireau et le débiter en fines demi-rondelles après l''avoir bien lavé. Peler l''oignon et le couper en deux : une moitié partira entière à la cuisson, l''autre sera émincée crue au dernier moment.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Réunir dans une casserole les lentilles, la carotte, le poireau, la demi-moitié d''oignon entière, le laurier et le thym. Recouvrir de deux fois leur volume d''eau froide, sans sel : une eau salée dès le départ durcit la peau de la légumineuse et l''empêche de s''attendrir régulièrement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Monter doucement jusqu''au frémissement, puis baisser le feu au minimum et laisser cuire à découvert 12 à 15 minutes. La lentille corail se défait beaucoup plus vite que la verte : goûter dès la dixième minute et couper le feu à l''instant où le grain cède sous la dent tout en restant entier.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Saler seulement à ce moment-là, puis égoutter immédiatement et sans rincer pour stopper la cuisson. Retirer la moitié d''oignon et la feuille de laurier, garder carotte et poireau. Étaler le tout dans un saladier large : la chaleur retombe vite et les grains cessent de se coller entre eux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Pendant que les lentilles cuisent, plonger les œufs dans une casserole d''eau à petits bouillons et compter exactement 6 minutes pour un jaune encore coulant. Les basculer dans un bol d''eau glacée, attendre deux minutes, puis les écaler délicatement en commençant par le côté le plus large.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Dans un bol, écraser l''ail au presse-ail, ajouter le vinaigre de cidre, le poivre et une pincée de sel, puis verser l''huile d''olive en mince filet en fouettant sans arrêt jusqu''à ce que la sauce épaississe et cesse de se séparer. Verser sur les lentilles encore tièdes, mélanger à la spatule souple et laisser reposer 5 minutes : c''est en refroidissant qu''elles boivent la vinaigrette.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Ciseler le persil et la ciboulette, concasser grossièrement les noix au couteau. Les ajouter au saladier avec l''oignon cru émincé très finement, mélanger une dernière fois, répartir dans les assiettes puis poser sur chacune un œuf ouvert en deux. Rectifier en poivre et servir sans attendre, à peine tiède.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-014-D2', 'recipe_family', 'Lentilles tièdes au vinaigre de cidre',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-014-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-014-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-014-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('5f993a2bc747cf6e4cf88d57ffadbe22'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":2,"acidic":3,"bitter":1,"umami":2,"heat":0,"pungency":3,"richness":3,"freshness":3,"intensity":3},"dominant_flavors":["terreux","acidulé","herbacé","alliacé"],"aroma_families":["herbacé","aromates séchés","alliacé"],"target_textures":["lentilles fondantes mais entières","jaune d''œuf coulant","éclats de noix croquants","oignon cru croquant"],"signature_ingredients":["Lentille corail sèche, crue","Huile d''olive vierge extra","Vinaigre de cidre","Persil frais"],"identity_guardrails":["Les lentilles doivent être assaisonnées encore tièdes : une fois froides elles n''absorbent plus la vinaigrette et le plat bascule en salade froide banale.","L''eau de cuisson reste non salée jusqu''à la fin, sinon la peau durcit et le grain ne s''attendrit plus uniformément.","La garniture aromatique carotte-poireau-oignon cuite avec la légumineuse et le duo thym-laurier constituent la base commune à toutes les sources : les retirer viderait le plat de son fond de goût.","La vinaigrette doit rester une émulsion huile d''olive et vinaigre franchement acide ; adoucie ou crémée, le contraste avec la lentille disparaît."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Lentilles tièdes à la patate douce et à la betterave', 'lentilles tiedes a la patate douce et a la betterave', 'France', 'France',
     'meal', 'salade tiède', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Lentilles tièdes à la patate douce et à la betterave', 'Lentilles corail tièdes avec œuf poché et légumes de saison en vinaigrette', ds.id, 'SRC-014-D3',
    'Myko', 'editorial', 4, 30, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', '4e150b6e05625728c92b212598a91245',
    '{"sweet":1,"salty":2,"acidic":3,"bitter":1,"umami":2,"heat":0,"pungency":3,"richness":3,"freshness":3,"intensity":3}'::jsonb, ARRAY['terreux','acidulé','herbacé','alliacé']::text[],
    ARRAY['herbacé','aromates séchés','alliacé']::text[], ARRAY['lentilles fondantes mais entières','jaune d''œuf coulant','éclats de noix croquants','oignon cru croquant']::text[],
    ARRAY['Lentille corail sèche, crue','Huile d''olive vierge extra','Vinaigre de vin rouge','Persil frais']::text[], ARRAY['Les lentilles doivent être assaisonnées encore tièdes : une fois froides elles n''absorbent plus la vinaigrette et le plat bascule en salade froide banale.','L''eau de cuisson reste non salée jusqu''à la fin, sinon la peau durcit et le grain ne s''attendrit plus uniformément.','La garniture aromatique carotte-poireau-oignon cuite avec la légumineuse et le duo thym-laurier constituent la base commune à toutes les sources : les retirer viderait le plat de son fond de goût.','La vinaigrette doit rester une émulsion huile d''olive et vinaigre franchement acide ; adoucie ou crémée, le contraste avec la lentille disparaît.']::text[],
    ARRAY['mijotage','pochage','émulsion']::text[], ARRAY[]::text[], ARRAY['œuf','fruits à coque','sulfites']::text[],
    'Se garde 3 jours au réfrigérateur entre 0 et 4 °C en boîte hermétique, vinaigrette déjà incorporée. Sortir 30 minutes avant le service ou réchauffer 1 minute à la poêle à feu doux pour retrouver la tiédeur. Les œufs mollets ne se conservent pas plus de 24 h et se posent au dernier moment. Congélation à proscrire : la lentille corail se délite en purée à la décongélation et les herbes fraîches noircissent.', '{"fridge_hours":72,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":false,"source":"manual"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-014'), '{"variant_label":"Ajouter des dés de patate douce rôtis au four et des dés de betterave cuite pour une salade plus sucrée et plus colorée.","rationale":"La patate douce rôtie et la betterave apportent un sucre que la lentille n''a pas, et une couleur qui change complètement l''assiette. C''est une salade plus nourrissante, où la légumineuse cesse d''être seule au centre.","operations":[{"op":"add","form":"Patate douce crue","quantity":300,"unit":"g","role":"légume"},{"op":"add","form":"Betterave crue","quantity":200,"unit":"g","role":"légume"}],"steps":[{"op":"insert","after":1,"instruction":"Préchauffer le four à 200 °C. Peler la patate douce, la tailler en dés de deux centimètres, les mêler à une cuillerée d''huile d''olive prélevée sur la dose et les rôtir vingt-cinq minutes sur une plaque, en les retournant à mi-cuisson. Cuire la betterave à l''eau bouillante jusqu''à ce qu''un couteau la traverse, la peler tiède et la couper en dés de même taille."},{"op":"replace","n":7,"instruction":"Ciseler le persil et la ciboulette, concasser grossièrement les noix au couteau. Les ajouter au saladier avec l''oignon cru émincé très finement, les dés de patate douce rôtis et ceux de betterave, mélanger d''une main légère pour que la betterave ne teigne pas tout, répartir dans les assiettes puis poser sur chacune un œuf ouvert en deux. Rectifier en poivre et servir sans attendre, à peine tiède."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
