  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Ranger les œufs dans une casserole, les couvrir d''eau froide salée et porter sur feu vif ; dès les premiers bouillons, baisser à frémissement et compter dix minutes, en faisant rouler les œufs à la cuillère pendant la première minute pour que les jaunes restent au centre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Sortir les œufs à l''écumoire et les plonger sans attendre dans un saladier d''eau très froide, le temps qu''ils refroidissent à cœur ; les écaler ensuite sous un mince filet d''eau, la coquille se détachant alors sans arracher le blanc.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Fendre chaque œuf en deux dans la longueur, lame essuyée entre chaque coupe, puis faire glisser le jaune hors de son logement en préservant l''intégrité du blanc ; aligner les demi-blancs creux vers le haut sur le plat de service.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Pour une liaison maison, travailler le jaune d''œuf cru avec la moutarde de Dijon, verser l''huile d''olive vierge extra en filet très mince sans cesser de fouetter jusqu''à ce que la sauce se tienne, puis détendre au jus de citron frais au dernier moment ; sinon, partir directement de la mayonnaise.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Passer les deux tiers des jaunes durs au travers d''un tamis fin, les écraser à la fourchette avec la mayonnaise, le thon soigneusement égoutté et émietté, le sel fin, le poivre noir moulu et le persil frais finement ciselé, jusqu''à une farce lisse, souple et sans grumeaux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Remplir chaque demi-blanc de cette farce, à la petite cuillère en bombant la surface ou à la poche à douille pour un dressage plus net, sans faire déborder sur les bords du blanc.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Tamiser le dernier tiers des jaunes réservés directement au-dessus des œufs garnis pour obtenir la neige jaune caractéristique, ajouter quelques pluches de persil frais, filmer sans écraser et laisser raffermir trente minutes au réfrigérateur avant de servir bien frais.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-015-D1', 'recipe_family', 'Œufs mimosa au thon',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-015-D1', 'missing_required_count', v_missing), 'open');
  END IF;

