     'assaisonnement', true, 8);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Dégermer l''ail puis l''écraser. Ouvrir la conserve de thon, la laisser s''égoutter quelques minutes dans une passoire et défaire la chair en miettes grossières à la fourchette.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire tiédir les trois quarts de l''huile d''olive dans une sauteuse large et y jeter l''ail écrasé. Le laisser à peine blondir une minute sur feu doux, sans le laisser brunir : passé la couleur noisette, il devient amer et la sauce entière avec lui.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Verser la tomate concassée avec tout son jus, saler légèrement, donner un tour de poivre, poser le couvercle en biais et laisser réduire à petit feu une quinzaine de minutes, jusqu''à ce que la sauce se resserre et nappe le dos d''une cuillère.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Pendant la réduction, porter un grand volume d''eau salée à pleine ébullition et y cuire les pâtes une minute de moins que le temps indiqué sur le paquet. Réserver une petite louche d''eau de cuisson avant d''égoutter.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Baisser le feu sous la sauce, y disperser les miettes de thon et les herbes de Provence, puis laisser confire cinq minutes sans remuer trop fort : le poisson doit se réchauffer et prendre le goût de la tomate en restant en morceaux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Réunir les pâtes égouttées et la sauce dans la sauteuse, verser le reste d''huile d''olive et un filet d''eau de cuisson si l''ensemble paraît sec, mélanger hors du feu pour enrober chaque pâte, rectifier sel et poivre et servir sans attendre.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-018-D1', 'recipe_family', 'Pâtes au thon tout à l''ail',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-018-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-018-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-018-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('2dc49186e01f348772b1543cfee54e61'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":1,"salty":3,"acidic":3,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":3,"freshness":1,"intensity":3},"dominant_flavors":["tomate cuite","iodé","aillé"],"aroma_families":["herbacé","aillé","fruité vert"],"target_textures":["pâtes al dente","sauce nappante","miettes de poisson fondantes"],"signature_ingredients":["Thon au naturel en conserve, égoutté","Tomate concassée en conserve","Petites pâtes sèches"],"identity_guardrails":["Le thon doit être ajouté en fin de cuisson et rester en miettes visibles : émietté trop tôt ou remué jusqu''à disparaître, le plat devient une simple sauce tomate.","La tomate concassée doit réduire avant l''arrivée du poisson : une sauce non réduite délave le plat et le rapproche d''un plat de pâtes à la sauce industrielle.","L''huile d''olive vierge extra est la seule matière grasse : remplacée par du beurre ou de la crème, le plat quitte son registre provençal."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Pâtes au thon longuement mijotées', 'pates au thon longuement mijotees', 'France', 'France',
     'meal', 'plat de pâtes', 'documented_variation', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Pâtes au thon longuement mijotées', 'Petites pâtes avec thon dans une sauce tomate réduite longuement avec oignon et ail', ds.id, 'SRC-018-D2',
    'Myko', 'editorial', 4, 10, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', 'b267d07ead09a774753f5cae2aa488b2',
    '{"sweet":1,"salty":3,"acidic":3,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":3,"freshness":1,"intensity":3}'::jsonb, ARRAY['tomate cuite','iodé','aillé']::text[],
    ARRAY['herbacé','aillé','fruité vert']::text[], ARRAY['pâtes al dente','sauce nappante','miettes de poisson fondantes']::text[],
    ARRAY['Thon au naturel en conserve, égoutté','Tomate concassée en conserve','Petites pâtes sèches']::text[], ARRAY['Le thon doit être ajouté en fin de cuisson et rester en miettes visibles : émietté trop tôt ou remué jusqu''à disparaître, le plat devient une simple sauce tomate.','La tomate concassée doit réduire avant l''arrivée du poisson : une sauce non réduite délave le plat et le rapproche d''un plat de pâtes à la sauce industrielle.','L''huile d''olive vierge extra est la seule matière grasse : remplacée par du beurre ou de la crème, le plat quitte son registre provençal.']::text[],
    ARRAY['mijotage','réduction']::text[], ARRAY[]::text[], ARRAY['gluten','poisson']::text[],
    'Se garde 2 jours au réfrigérateur entre 0 et 4 °C dans une boîte hermétique ; réchauffer à la poêle avec une cuillère d''eau, jamais à ébullition sous peine de dessécher le thon. La congélation est déconseillée pour le plat assemblé (les pâtes deviennent farineuses), mais la sauce tomate au thon seule se congèle jusqu''à 2 mois.', '{"fridge_hours":48,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-018'), '{"variant_label":"Version longuement mijotée : doubler le temps de réduction de la tomate à couvert et à feu très doux, en ajoutant un peu d''eau de cuisson des pâtes si la sauce attache, pour un goût plus rond et moins acide.","rationale":"Une demi-heure à couvert casse l''acidité de la conserve, que quinze minutes laissent entière. La sauce devient plus ronde et plus sombre ; en contrepartie le plat n''est plus un plat rapide.","operations":[],"steps":[{"op":"replace","n":3,"instruction":"Verser la tomate concassée avec tout son jus, saler légèrement, donner un tour de poivre, couvrir entièrement et laisser réduire à feu très doux une demi-heure, en remuant de loin en loin et en ajoutant une cuillerée d''eau chaude si la sauce accroche au fond. Elle doit foncer et perdre son acidité de conserve."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
