  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Peler l''oignon et le hacher menu, dégermer l''ail puis l''écraser. Ouvrir la conserve de thon, la laisser s''égoutter quelques minutes dans une passoire et défaire la chair en miettes grossières à la fourchette.');

