DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Bœuf mode en gelée', 'boeuf mode en gelee', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Bœuf mode en gelée', 'Bœuf braisé aux carottes, refroidi et servi en gelée naturelle formée par le bouillon', ds.id, 'SRC-002-D1',
    'Myko', 'editorial', 6, 45, 195, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '490a5837776ba16585b59fa1c5c57c20',
    '{"sweet":1,"salty":2,"acidic":0,"bitter":0,"umami":1,"heat":3,"pungency":0,"richness":2,"freshness":4,"intensity":1}'::jsonb, ARRAY['bœuf_braisé','carotte_fondante','vin_blanc']::text[],
    ARRAY['viande_braisée','oignon_compoté','bouillon_corsé']::text[], ARRAY['viande_effilochable','sauce_nappante','carotte_fondante']::text[],
    ARRAY['Bœuf à braiser cru','Carotte crue','Vin blanc sec']::text[], ARRAY['Les carottes cuisent avec la viande et deviennent fondantes : les ajouter tard en ferait une garniture, pas un bœuf mode.','La quantité de carottes égale au moins la moitié du poids de viande.']::text[],
    ARRAY['saisie','mijotage','réduction','gelée de bouillon','prise au froid']::text[], ARRAY[]::text[], ARRAY['gluten']::text[],
    'Se garde 3 jours au froid et gagne à être réchauffé le lendemain. Se congèle 3 mois.', '{"fridge_hours":72,"eat_immediately":false,"freezable":true,"freezer_months":3,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-002'), '{"variant_label":"Servi froid en gelée","rationale":"Le plat ne change pas de cuisson mais change d''état : le jus de braisage est filtré, dégraissé, réduit et gélifié, puis la viande prend au froid une nuit entière. La farine disparaît, car un jus singé se fige en pâte au réfrigérateur au lieu de trancher net sous le couteau. Ce que la version chaude donnait en velouté, celle-ci le rend en fraîcheur et en franchise, au prix d''une nuit d''attente et d''un assaisonnement à relever davantage, le froid éteignant le sel.","operations":[{"op":"remove","form":"Farine de blé T55"},{"op":"add","form":"Gélatine feuille","quantity":12,"unit":"g","role":"gélifiant","optional":false}],"steps":[{"op":"replace","n":4,"instruction":"Déglacer au vin blanc et gratter les sucs jusqu''à ce qu''ils se détachent du fond, puis laisser réduire de moitié. On ne singe pas cette version : un jus épaissi se prend en pâte trouble au froid, là où un jus nu se coupe net."},{"op":"replace","n":7,"instruction":"Retirer le thym et le laurier, puis sortir la viande et les carottes à l''écumoire. Filtrer le jus au chinois, le laisser reposer quelques minutes et le dégraisser à la louche, avant de le réduire à environ six cents millilitres. Rectifier l''assaisonnement franchement, plus haut que pour un plat chaud, puis dissoudre hors du feu la gélatine ramollie dix minutes à l''eau très froide et essorée entre les doigts."},{"op":"insert","after":7,"instruction":"Ranger la viande et les carottes en couches serrées dans une terrine, en parsemant de persil ciselé entre chacune, puis verser le jus tiède jusqu''à les recouvrir. Laisser prendre au réfrigérateur une nuit entière : quelques heures suffisent à figer la surface mais pas le cœur. Démouler en trempant trois secondes le moule dans l''eau chaude, et trancher au couteau à lame fine."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

