  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Verser le bouillon de volaille dans une casserole, le porter à frémissement et le garder au chaud. Il entre directement dans la sauce sans avoir rien cuit : c''est là toute l''économie de temps de cette version, et c''est aussi pourquoi il vaut la peine de le choisir bon.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Détacher le poulet cuit effiloché en filaments courts et le saisir deux minutes à feu vif dans une noisette du beurre doux, jusqu''à ce que les bords accrochent et blondissent. Cette coloration remplace, en partie seulement, le goût qu''un pochage aurait déposé dans le bouillon. Réserver, et garder la poêle telle quelle pour les champignons.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Nettoyer les champignons de Paris frais en grattant le chapeau et en coupant le bout terreux du pied, puis les émincer en lamelles épaisses. Les faire sauter à feu vif dans une noisette du beurre doux jusqu''à ce que l''eau rendue se soit entièrement évaporée et que les lamelles commencent à dorer. Réserver hors du feu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Dans une casserole à fond épais, fondre le reste du beurre doux à feu doux, pluvioriser la farine de blé T55 d''un coup et remuer au fouet pendant 3 minutes : le mélange doit mousser sans jamais prendre couleur, on veut un roux blanc.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Retirer la casserole du feu et verser le bouillon chaud en filet, fouet en main, pour éviter tout grumeau. Ajouter le vin blanc sec puis le lait entier, remettre sur feu moyen et laisser réduire 15 minutes en fouettant régulièrement, jusqu''à ce que le velouté nappe le dos d''une cuillère. Assaisonner de poivre noir moulu et de muscade moulue.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Verser le poulet réservé et les champignons dans le velouté, baisser au minimum et laisser les saveurs se lier 5 minutes sans que la sauce reprenne l''ébullition. Une viande déjà cuite ne demande rien de plus que d''être réchauffée : la faire mijoter la dessécherait en filaments secs.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Battre les jaunes d''œuf cru avec la crème fraîche liquide entière dans un bol, détendre cet appareil avec une louche de sauce brûlante, puis le reverser dans la casserole hors du feu en mélangeant. Réchauffer 2 à 3 minutes à feu très doux : la sauce épaissit et prend du brillant, mais un seul bouillon ferait grainer les jaunes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Servir sans attendre, la garniture bien chaude répartie dans des croûtes feuilletées passées quelques minutes au four, ou nappée sur du riz, des nouilles ou des spätzle. Le surplus de sauce se présente à part en saucière.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-009-D3', 'recipe_family', 'Bouchées à la reine express au poulet',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-009-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-009-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-009-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('0cf2c652c394453901eb9cf24f9ae1a9'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":3,"acidic":1,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":3},"dominant_flavors":["volaille","champignon","crème","vin blanc"],"aroma_families":["beurré","lacté","épicé doux","champignon"],"target_textures":["sauce nappante","viande fondante","lamelles de champignon tendres"],"signature_ingredients":["Champignon de Paris frais","Bouillon de volaille","Jaune d''œuf cru"],"identity_guardrails":["Sans la liaison finale au Jaune d''œuf cru et à la Crème fraîche liquide entière, le velouté retombe au rang de simple béchamel et le plat perd son caractère de sauce à la reine.","Retirer le Champignon de Paris frais ou la volaille pochée vide la garniture de sa substance : ce sont les deux éléments présents dans presque toutes les sources du dossier.","Le bouillon de volaille doit être celui du pochage des viandes, pas de l''eau salée : c''est lui qui porte tout l''umami de la sauce.","La sauce ne doit jamais bouillir après l''ajout des jaunes, sous peine de grainer irrémédiablement."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Courgettes farcies au brochet', 'courgettes farcies au brochet', 'France', 'France',
     'meal', 'plat au four', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Courgettes farcies au brochet', 'Courgettes évidées farcies de chair de brochet et oignons, cuites au four dans la tomate', ds.id, 'SRC-010-D1',
    'Myko', 'editorial', 4, 25, 50, 'facile',
    NULL, NULL,
    'B', 'candidate', 'f874a97a985c76b5daecbc948d1d22d5',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":3,"freshness":2,"intensity":3}'::jsonb, ARRAY['viande rôtie','tomate','ail']::text[],
    ARRAY['alliacé','herbacé','épicé doux']::text[], ARRAY['légume fondant','farce moelleuse','dessus doré']::text[],
    ARRAY['Courgette fraîche','Chair de brochet crue']::text[], ARRAY['La courgette évidée doit rester le contenant du plat : farce servie à part ou légume coupé en dés, ce ne sont plus des courgettes farcies.','La farce est à base de viande hachée liée à la pulpe de courgette récupérée ; sans cette pulpe réincorporée, le plat perd le lien végétal qui le caractérise.','La cuisson se fait au four dans un plat, garniture apparente : cuire à couvert en cocotte comme un mijoté change la nature du plat.']::text[],
    ARRAY['saisie','rôtissage']::text[], ARRAY[]::text[], ARRAY[]::text[],
    'Se garde 3 jours au réfrigérateur à 4 °C dans un plat couvert, et se réchauffe 15 minutes à 160 °C plutôt qu''au micro-ondes pour que la barquette ne s''affaisse pas. La congélation de la farce seule tient 2 mois à -18 °C ; en revanche les courgettes garnies supportent mal le gel, elles rendent leur eau et deviennent flasques à la décongélation.', '{"fridge_hours":72,"eat_immediately":false,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-010'), '{"variant_label":"Version au poisson relevée dans le dossier : remplacer les viandes par de la chair de brochet crue, avec une pointe de jus de citron frais.","rationale":"La farce perd le gras du porc et le liant du bœuf : elle devient légère, presque maigre, et c''est le citron qui la tient debout à la place de la viande. Le brochet est haché cru et n''est pas passé à la poêle, sans quoi il cuirait deux fois et deviendrait cotonneux — le four s''en charge seul. Le temps de cuisson ne bouge pas pour autant : c''est la paroi de la courgette qui le fixe, et le brochet, cuit bien avant elle, demande seulement d''être couvert tôt pour ne pas sécher.","operations":[{"op":"substitute","form":"Porc haché cru","with":"Chair de brochet crue","quantity":600,"unit":"g","role":"protéine"},{"op":"remove","form":"Bœuf haché cru 15 % MG"},{"op":"add","form":"Jus de citron frais","quantity":20,"unit":"g","role":"acidité","optional":false}],"steps":[{"op":"replace","n":5,"instruction":"Retirer la poêle du feu et laisser tiédir la fondue de courgette. Hacher la chair de brochet crue au couteau, en grain un peu grossier, et la mêler à la fondue sans la remettre sur le feu : un poisson maigre saisi puis enfourné cuit deux fois et sort filandreux. Assaisonner de sel, de poivre et, si l''on y tient, d''une pincée de cumin."},{"op":"replace","n":6,"instruction":"Incorporer le persil et le basilic finement ciselés, puis le jus de citron frais, qui resserre la chair du brochet et réveille une farce que le gras de la viande ne soutient plus. Rectifier l''assaisonnement en poêlant à blanc une noisette de farce pour la goûter : une farce de poisson crue ne se juge pas à la cuillère, et une fois les barquettes au four il est trop tard pour la reprendre."},{"op":"replace","n":9,"instruction":"Enfourner cinquante minutes environ et poser une feuille d''aluminium dès la vingtième : c''est la paroi de la courgette qui commande l''horloge, non le poisson, et le brochet serait desséché bien avant qu''un centimètre de chair ne cède. La cuisson est juste quand la pointe d''un couteau traverse la peau sans effort. Laisser reposer cinq minutes avant de porter à table."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
