  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Chauffer le four à 200 °C. Rincer les courgettes sans retirer la peau, ôter les deux bouts, puis les fendre en deux sur toute leur longueur de façon à obtenir des barquettes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Racler l''intérieur de chaque moitié avec une petite cuillère en laissant une paroi d''un centimètre environ, pour que la courgette tienne debout à la cuisson. Hacher grossièrement la pulpe recueillie et la mettre de côté.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Tailler l''oignon et l''échalote en petits dés, écraser puis hacher les gousses d''ail. Les faire suer à feu moyen dans la moitié de l''huile d''olive, sans coloration, jusqu''à ce qu''ils deviennent translucides.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser la pulpe de courgette hachée dans la poêle et poursuivre cinq à six minutes à feu vif, le temps que l''eau de végétation s''évapore : une farce trop humide détremperait les barquettes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Incorporer les deux viandes hachées et les écraser à la fourchette au fur et à mesure pour qu''aucun paquet ne subsiste. Assaisonner de sel, de poivre et de cumin, puis cuire une dizaine de minutes jusqu''à disparition complète du rosé.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Retirer la poêle du feu et mélanger à la farce encore chaude le persil, le basilic et la moitié de la coriandre fraîche, tous finement ciselés, afin qu''ils gardent leur parfum. Goûter à ce moment-là : le cumin, plus que doublé, mène désormais la farce et réclame un peu plus de sel pour ne pas y régner seul.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Aligner les barquettes côte à côte dans un plat à four et les remplir de farce en tassant légèrement, avec un dôme qui dépasse le bord : la garniture se rétracte pendant la cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Écraser les tomates pelées à la fourchette et les répartir avec leur jus dans le fond du plat, autour des courgettes et non dessus. Arroser les dômes du reste d''huile d''olive.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Enfourner cinquante minutes environ. Poser une feuille d''aluminium si le dessus brunit trop tôt : la cuisson est juste quand la pointe d''un couteau traverse la peau sans effort. Laisser reposer cinq minutes avant de porter à table.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 10, 'Au sortir du four, parsemer les barquettes du reste de coriandre fraîche et les asperger du jus de citron frais. Ni l''herbe crue ni l''acidité ne supportent la cuisson : ajoutées à table, elles éclaircissent le cumin au lieu de s''y dissoudre.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-010-D2', 'recipe_family', 'Courgettes farcies à l''orientale',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-010-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-010-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-010-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('7204bef95ed20615530578854431a2fc'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":3,"freshness":2,"intensity":3},"dominant_flavors":["viande rôtie","tomate","ail"],"aroma_families":["alliacé","herbacé","épicé doux"],"target_textures":["légume fondant","farce moelleuse","dessus doré"],"signature_ingredients":["Courgette fraîche","Porc haché cru","Bœuf haché cru 15 % MG"],"identity_guardrails":["La courgette évidée doit rester le contenant du plat : farce servie à part ou légume coupé en dés, ce ne sont plus des courgettes farcies.","La farce est à base de viande hachée liée à la pulpe de courgette récupérée ; sans cette pulpe réincorporée, le plat perd le lien végétal qui le caractérise.","La cuisson se fait au four dans un plat, garniture apparente : cuire à couvert en cocotte comme un mijoté change la nature du plat."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Courgettes rondes farcies', 'courgettes rondes farcies', 'France', 'France',
     'meal', 'plat au four', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Courgettes rondes farcies', 'Courgettes rondes blanchies puis farcies de viande hachée à la tomate', ds.id, 'SRC-010-D3',
    'Myko', 'editorial', 4, 30, 50, 'facile',
    NULL, NULL,
    'B', 'candidate', 'e671e951e0a3ae9c136c51ab0f8bb94c',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":3,"freshness":2,"intensity":3}'::jsonb, ARRAY['viande rôtie','tomate','ail']::text[],
    ARRAY['alliacé','herbacé','épicé doux']::text[], ARRAY['légume fondant','farce moelleuse','dessus doré']::text[],
    ARRAY['Courgette fraîche','Porc haché cru','Bœuf haché cru 15 % MG']::text[], ARRAY['La courgette évidée doit rester le contenant du plat : farce servie à part ou légume coupé en dés, ce ne sont plus des courgettes farcies.','La farce est à base de viande hachée liée à la pulpe de courgette récupérée ; sans cette pulpe réincorporée, le plat perd le lien végétal qui le caractérise.','La cuisson se fait au four dans un plat, garniture apparente : cuire à couvert en cocotte comme un mijoté change la nature du plat.']::text[],
    ARRAY['saisie','blanchiment','rôtissage']::text[], ARRAY[]::text[], ARRAY[]::text[],
    'Se garde 3 jours au réfrigérateur à 4 °C dans un plat couvert, et se réchauffe 15 minutes à 160 °C plutôt qu''au micro-ondes pour que la barquette ne s''affaisse pas. La congélation de la farce seule tient 2 mois à -18 °C ; en revanche les courgettes garnies supportent mal le gel, elles rendent leur eau et deviennent flasques à la décongélation.', '{"fridge_hours":72,"eat_immediately":false,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-010'), '{"variant_label":"Avec des courgettes rondes : décalotter, évider, blanchir dix minutes à l''eau bouillante avant de garnir, puis remettre le chapeau pour la cuisson au four.","rationale":"Le contenant change et toute la méthode suit : une coque ronde a bien plus de chair à traverser qu''une barquette fendue, d''où le blanchiment préalable sans lequel elle sortirait crue au cœur. Le chapeau remis retient la vapeur et garde la farce moelleuse, mais interdit le dôme et la croûte dorée de la version en barquettes. On y gagne en tenue et en présentation, on y perd le gratiné du dessus et dix minutes de préparation.","operations":[],"steps":[{"op":"replace","n":1,"instruction":"Chauffer le four à 200 °C. Rincer les courgettes rondes sans retirer la peau, puis les décalotter au tiers supérieur d''un coup de couteau franc. Garder les chapeaux de côté, ils reviendront sur les coques à l''enfournement."},{"op":"replace","n":2,"instruction":"Évider chaque courgette à la petite cuillère en laissant une paroi d''un centimètre et sans percer le fond : une coque ronde ne tient que par son épaisseur, et une paroi trouée laisserait fuir le jus de la farce. Hacher grossièrement la pulpe recueillie et la mettre de côté."},{"op":"replace","n":4,"instruction":"Verser la pulpe de courgette hachée dans la poêle et poursuivre cinq à six minutes à feu vif, le temps que l''eau de végétation s''évapore : une farce trop humide détremperait des coques que le blanchiment a déjà gorgées d''eau."},{"op":"replace","n":7,"instruction":"Ranger les coques égouttées côte à côte dans un plat à four et les remplir de farce en tassant légèrement, jusqu''à ras bord et sans dôme : le chapeau doit pouvoir se reposer à plat dessus."},{"op":"replace","n":8,"instruction":"Écraser les tomates pelées à la fourchette et les répartir avec leur jus dans le fond du plat, autour des courgettes et non dessus. Arroser d''un filet du reste d''huile d''olive la farce encore à découvert, avant de recoiffer."},{"op":"replace","n":9,"instruction":"Poser sur chaque courgette son propre chapeau et enfourner quarante minutes environ. Le couvercle retient la vapeur et empêche la farce de sécher, mais il interdit aussi tout gratiné : inutile de guetter le brunissement, la cuisson est juste quand la pointe d''un couteau traverse la paroi sans effort. Laisser reposer cinq minutes avant de porter à table."},{"op":"insert","after":2,"instruction":"Plonger les coques et leurs chapeaux dix minutes dans une grande casserole d''eau bouillante salée, puis les égoutter tête en bas sur un linge. Une courgette ronde offre au four une paroi bien plus épaisse qu''une barquette : sans ce blanchiment, la farce serait cuite quand le légume ne le serait pas encore."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'courgette fraiche' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Courgette fraîche', 1200, 'g', 'required',
     'légume', false, 1);

