  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Anchoïade camarguaise', 'Anchoïade d''anchois et ail à l''huile d''olive épaissie avec du pain de mie mixé', ds.id, 'SRC-007-D1',
    'Myko', 'editorial', 4, 10, 0, 'facile',
    NULL, NULL,
    'B', 'candidate', '9c49dfaa545f34eac56781587df89ff3',
    '{"sweet":0,"salty":4,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":4,"richness":5,"freshness":1,"intensity":4}'::jsonb, ARRAY['aillé','salin','acidulé']::text[],
    ARRAY['allium','fruité vert','vinaigré']::text[], ARRAY['pommade lisse','onctueux']::text[],
    ARRAY['Anchois à l''huile, égoutté','Ail cru','Huile d''olive vierge extra']::text[], ARRAY['Sans filets d''anchois pilés, ce n''est pas une anchoïade mais une pâte d''ail à l''huile.','L''ail reste cru et réduit en pâte : le confire efface le mordant qui fait le plat.','L''huile s''incorpore en filet pour que la préparation prenne ; versée d''un coup, elle rejette son gras.','Le plat se sert froid ou à température ambiante — servi chaud, il bascule vers une bagna cauda.']::text[],
    ARRAY['émulsion','mixage']::text[], ARRAY[]::text[], ARRAY['poisson','gluten','sulfites']::text[],
    'Se garde 3 à 4 jours au réfrigérateur entre 0 et 4 °C, dans un bocal hermétique, la surface recouverte d''une fine couche d''huile d''olive qui protège de l''oxydation. Sortir 20 minutes avant de servir, l''huile figeant au froid. La congélation est déconseillée : l''émulsion se casse au dégel et l''ail cru y développe une amertume marquée.', '{"fridge_hours":72,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":true,"source":"manual"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-007'), '{"variant_label":"Version camarguaise liée à la mie de pain de mie, mixée jusqu''à une pommade très ferme qui prend comme une mayonnaise","rationale":"La mie cesse d''être un correctif facultatif pour devenir la charpente : quatre-vingts grammes de pain absorbent l''huile et donnent une pâte qui tient au bout de la spatule. Le mixeur remplace le mortier, ce qui gagne du temps mais rend la texture plus lisse et plus anonyme — on perd le grain de l''ail pilé. La tomate sort de la recette, son eau ferait retomber l''émulsion. Au total, une anchoïade plus douce, plus nourrissante et plus féculente que la provençale.","operations":[{"op":"set","form":"Pain de mie","quantity":80,"role":"liant","optional":false},{"op":"remove","form":"Tomate râpée"}],"steps":[{"op":"replace","n":1,"instruction":"Égoutter les filets d''anchois de leur huile et les éponger. Peler les gousses d''ail, ôter le germe, puis réunir ail et anchois dans le bol d''un mixeur avec une pincée de sel. Donner quelques impulsions brèves, en raclant les parois entre deux, jusqu''à ce qu''il ne subsiste aucun morceau reconnaissable."},{"op":"replace","n":2,"instruction":"Émietter toute la mie du pain de mie dans un bol, l''imbiber du vinaigre de vin rouge allongé de deux cuillerées d''eau, laisser gonfler deux minutes, puis la presser entre les doigts avant de la joindre aux anchois dans le bol. C''est cette panade qui donnera son corps à la pommade : sans elle, l''huile n''aurait rien à quoi s''accrocher."},{"op":"replace","n":3,"instruction":"Mixer en continu et verser l''huile d''olive vierge extra en filet très mince par la cheminée, exactement comme on monte une mayonnaise. La préparation pâlit, se resserre et finit par former une pommade très ferme. Si le bol chauffe sous la lame, arrêter trente secondes : une émulsion tiédie se rompt et ne se rattrape qu''en repartant d''un fond neuf."},{"op":"replace","n":4,"instruction":"Rectifier au jus de citron frais et au poivre noir moulu, puis goûter. La pommade doit tenir en dôme sur la cuillère sans s''affaisser ; si elle s''est tendue au point de graisser, quelques gouttes d''eau glacée mixées une seconde la rendent à sa souplesse."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
