  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Égoutter les filets d''anchois de leur huile et les éponger. Peler les gousses d''ail, ôter le germe, puis réunir ail et anchois dans le bol d''un mixeur avec une pincée de sel. Donner quelques impulsions brèves, en raclant les parois entre deux, jusqu''à ce qu''il ne subsiste aucun morceau reconnaissable.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Émietter toute la mie du pain de mie dans un bol, l''imbiber du vinaigre de vin rouge allongé de deux cuillerées d''eau, laisser gonfler deux minutes, puis la presser entre les doigts avant de la joindre aux anchois dans le bol. C''est cette panade qui donnera son corps à la pommade : sans elle, l''huile n''aurait rien à quoi s''accrocher.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Mixer en continu et verser l''huile d''olive vierge extra en filet très mince par la cheminée, exactement comme on monte une mayonnaise. La préparation pâlit, se resserre et finit par former une pommade très ferme. Si le bol chauffe sous la lame, arrêter trente secondes : une émulsion tiédie se rompt et ne se rattrape qu''en repartant d''un fond neuf.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Rectifier au jus de citron frais et au poivre noir moulu, puis goûter. La pommade doit tenir en dôme sur la cuillère sans s''affaisser ; si elle s''est tendue au point de graisser, quelques gouttes d''eau glacée mixées une seconde la rendent à sa souplesse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Couvrir et laisser reposer trente minutes au frais avant le service : le mordant de l''ail s''arrondit et les arômes se fondent. Servir à température ambiante, tartiné sur du pain grillé ou en trempette avec des crudités.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-007-D1', 'recipe_family', 'Anchoïade camarguaise',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-007-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-007-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-007-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('9c49dfaa545f34eac56781587df89ff3'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"spicy_umami","scores":{"sweet":0,"salty":4,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":4,"richness":5,"freshness":1,"intensity":4},"dominant_flavors":["aillé","salin","acidulé"],"aroma_families":["allium","fruité vert","vinaigré"],"target_textures":["pommade lisse","onctueux"],"signature_ingredients":["Anchois à l''huile, égoutté","Ail cru","Huile d''olive vierge extra"],"identity_guardrails":["Sans filets d''anchois pilés, ce n''est pas une anchoïade mais une pâte d''ail à l''huile.","L''ail reste cru et réduit en pâte : le confire efface le mordant qui fait le plat.","L''huile s''incorpore en filet pour que la préparation prenne ; versée d''un coup, elle rejette son gras.","Le plat se sert froid ou à température ambiante — servi chaud, il bascule vers une bagna cauda."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
