     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 2, 'g', 'optional',
     'assaisonnement', true, 8);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'optional',
     'assaisonnement', true, 9);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Égoutter les filets d''anchois de leur huile et les éponger. Peler les gousses d''ail, ôter le germe, puis piler ail et anchois au mortier avec une pincée de sel jusqu''à obtenir une pâte lisse — le sel sert d''abrasif et évite les morceaux qui piquent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Émietter la mie du pain de mie dans un bol, l''imbiber du vinaigre de vin rouge, laisser gonfler deux minutes, puis l''incorporer à la pâte d''ail en écrasant à la fourchette jusqu''à une masse homogène et sans grumeau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Verser l''huile d''olive vierge extra en filet très mince, sans jamais cesser de travailler la préparation : elle doit épaissir et rester liée comme une pommade ferme. Si de l''huile perle en surface, arrêter le versement et resserrer au fouet avant de reprendre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Râper la tomate à la grosse grille, la laisser s''égoutter dix minutes dans une passoire en pressant du dos de la cuillère, puis l''incorporer à la pommade par tiers, en travaillant vite. Ajoutée d''un coup, son eau délierait l''émulsion ; fractionnée, elle se laisse absorber. Rectifier au jus de citron frais et au poivre noir moulu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Couvrir et laisser reposer une heure au réfrigérateur : l''ail y perd son feu et les arômes se fondent. Retirer à la cuillère le peu d''eau remontée en surface, mélanger une dernière fois et servir frais, dans la journée — cette version tourne bien plus vite que l''anchoïade sèche.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-007-D3', 'recipe_family', 'Anchoïade à la tomate',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-007-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-007-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-007-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('64318afc77649680ec69e4a25d638d08'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"spicy_umami","scores":{"sweet":0,"salty":4,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":4,"richness":5,"freshness":1,"intensity":4},"dominant_flavors":["aillé","salin","acidulé"],"aroma_families":["allium","fruité vert","vinaigré"],"target_textures":["pommade lisse","onctueux"],"signature_ingredients":["Anchois à l''huile, égoutté","Ail cru","Huile d''olive vierge extra"],"identity_guardrails":["Sans filets d''anchois pilés, ce n''est pas une anchoïade mais une pâte d''ail à l''huile.","L''ail reste cru et réduit en pâte : le confire efface le mordant qui fait le plat.","L''huile s''incorpore en filet pour que la préparation prenne ; versée d''un coup, elle rejette son gras.","Le plat se sert froid ou à température ambiante — servi chaud, il bascule vers une bagna cauda."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Langue de bœuf sauce piquante au vinaigre de vin rouge', 'langue de boeuf sauce piquante au vinaigre de vin rouge', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'bright_acidic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Langue de bœuf sauce piquante au vinaigre de vin rouge', 'Langue de bœuf pochée puis servie avec une sauce piquante au vinaigre de vin rouge et cornichons', ds.id, 'SRC-013-D1',
    'Myko', 'editorial', 6, 35, 165, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '951fdfa25e143dc9d4f0cbdf18904dbf',
    '{"sweet":1,"salty":3,"acidic":4,"bitter":1,"umami":4,"heat":0,"pungency":3,"richness":3,"freshness":2,"intensity":4}'::jsonb, ARRAY['acidité vinaigrée','umami de bouillon de bœuf','cornichon saumuré','aromates de court-bouillon']::text[],
    ARRAY['vinaigré','épices chaudes','herbacé']::text[], ARRAY['viande fondante','sauce nappante','éclats croquants de cornichon']::text[],
    ARRAY['Langue de bœuf crue','Cornichon au vinaigre','Vinaigre blanc']::text[], ARRAY['Sans langue de bœuf pochée puis pelée, le plat n''existe plus : aucune autre pièce de bœuf ne peut s''y substituer.','Sans l''acidité conjointe du vinaigre réduit et des cornichons, la sauce n''est plus piquante mais une simple sauce brune.','La sauce doit être liée au roux avec le bouillon de cuisson de la langue, et non avec un fond étranger : c''est ce recyclage qui fait sa profondeur.']::text[],
    ARRAY['blanchiment','pochage','réduction','déglaçage','mijotage']::text[], ARRAY[]::text[], ARRAY['gluten','lait','sulfites']::text[],
    'Se garde 3 jours au réfrigérateur entre 0 et 4 °C, tranches immergées dans la sauce ou dans un peu de bouillon filtré pour éviter le dessèchement. Réchauffer à feu doux sans ébullition. La congélation est possible 2 mois pour la viande et sa sauce ensemble, mais la sauce liée à la farine peut se déphaser : la relier au fouet à la remise en température, et ne jamais congeler les cornichons, à ajouter au dernier moment.', '{"fridge_hours":72,"eat_immediately":false,"freezable":true,"freezer_months":2,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-013'), '{"variant_label":"Remplacer le vinaigre blanc de la sauce par du vinaigre de vin rouge, pour une acidité plus ronde et une couleur plus soutenue.","rationale":"Seul le vinaigre de la sauce change : celui du dégorgeage reste blanc, sa neutralité convenant mieux au trempage. Le vin rouge mord moins sec, laisse une acidité plus large et fonce la réduction d''un brun profond que le concentré de tomate ne suffisait pas à donner. Le mordant net qui répondait aux cornichons s''estompe d''autant : la sauce est plus ample, moins tranchante.","operations":[{"op":"set","form":"Vinaigre blanc","quantity":30,"unit":"ml","role":"dégorgeage"},{"op":"add","form":"Vinaigre de vin rouge","quantity":60,"unit":"ml","role":"acidité de sauce"}],"steps":[{"op":"replace","n":1,"instruction":"La veille, installer la langue dans un grand récipient, la noyer sous l''eau froide additionnée de tout le vinaigre blanc, puis la laisser dégorger au réfrigérateur une nuit entière en renouvelant l''eau une ou deux fois. Le blanc reste ici à sa place : il dégorge sans rien colorer, là où un vinaigre teinté marquerait la chair pour rien."},{"op":"replace","n":6,"instruction":"Pour la sauce, fondre le beurre doux dans une casserole à fond épais, y faire suer les échalotes ciselées sans qu''elles prennent couleur, puis mouiller avec le vin blanc et le vinaigre de vin rouge. Laisser réduire jusqu''à ce qu''il ne subsiste qu''un fond sirupeux, presque brun : c''est en s''évaporant que l''acide perd son agressivité et ne garde que sa profondeur."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
