      WHERE ff.canonical_name_normalized = 'cornichon au vinaigre' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Cornichon au vinaigre', 140, 'g', 'required',
     'condiment acide', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
