  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'La veille, installer la langue dans un grand récipient, la noyer sous l''eau froide additionnée d''un tiers du vinaigre blanc, puis la laisser dégorger au réfrigérateur une nuit entière en renouvelant l''eau une ou deux fois.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Le lendemain, jeter l''eau de trempage, rincer la pièce et la remettre dans une cocotte sous une hauteur d''eau froide propre. Porter à frémissement et compter un quart d''heure, en retirant l''écume grise qui remonte, puis égoutter et rincer de nouveau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Piquer l''oignon jaune épluché des clous de girofle. Déposer la langue dans la cuve de l''autocuiseur avec cet oignon, la carotte pelée coupée en gros tronçons, le laurier, le thym, les grains de poivre et le bouillon de bœuf émietté. Couvrir d''eau chaude sans dépasser les deux tiers de la cuve — au-delà, la soupape crache et la montée en pression ne se fait plus proprement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Fermer, porter à pression sur feu vif, puis compter quarante-cinq minutes dès que la soupape chuchote, feu réduit au minimum pour qu''elle ne siffle qu''à peine. Laisser ensuite la pression retomber seule, sans forcer la purge : une détente brutale contracte les fibres et rend la langue sèche. Ouvrir, vérifier qu''une lame traverse la partie la plus épaisse sans résistance, et laisser tiédir la pièce dans son bouillon.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Sortir la langue encore chaude, la poser côté bombé contre la planche et retirer la membrane épaisse, qui se décolle alors sans effort. Parer la base, réserver au chaud. Filtrer un litre et demi de bouillon et le faire réduire à découvert jusqu''à un litre avant de le garder frémissant : la cuve fermée n''a rien laissé s''évaporer, et ce bouillon-là est trop étendu pour porter la sauce tel quel.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Pour la sauce, fondre le beurre doux dans une casserole à fond épais, y faire suer les échalotes ciselées sans qu''elles prennent couleur, puis mouiller avec le vin blanc et le reste du vinaigre blanc. Laisser réduire jusqu''à ce qu''il ne subsiste qu''un fond sirupeux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Pluvioriser la farine sur les échalotes, remuer deux minutes à feu doux pour cuire le roux, incorporer le concentré de tomate, puis verser le bouillon filtré louche après louche en fouettant. Laisser épaissir vingt minutes à petit feu, en remuant régulièrement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Hors du bouillonnement, ajouter les cornichons taillés en fines rondelles pour qu''ils gardent leur mordant, rectifier en sel fin et poivre noir moulu, puis parsemer de persil haché.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Détailler la langue en tranches d''un demi-centimètre, les ranger en éventail dans un plat chaud et les napper généreusement de sauce piquante ; servir le reste de sauce à part en saucière.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-013-D3', 'recipe_family', 'Langue de bœuf sauce piquante à l''autocuiseur',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-013-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-013-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-013-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('8ec65dac1087e0fecb1adf717b8c4e6d'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"bright_acidic","scores":{"sweet":1,"salty":3,"acidic":4,"bitter":1,"umami":4,"heat":0,"pungency":3,"richness":3,"freshness":2,"intensity":4},"dominant_flavors":["acidité vinaigrée","umami de bouillon de bœuf","cornichon saumuré","aromates de court-bouillon"],"aroma_families":["vinaigré","épices chaudes","herbacé"],"target_textures":["viande fondante","sauce nappante","éclats croquants de cornichon"],"signature_ingredients":["Langue de bœuf crue","Cornichon au vinaigre","Vinaigre blanc"],"identity_guardrails":["Sans langue de bœuf pochée puis pelée, le plat n''existe plus : aucune autre pièce de bœuf ne peut s''y substituer.","Sans l''acidité conjointe du vinaigre réduit et des cornichons, la sauce n''est plus piquante mais une simple sauce brune.","La sauce doit être liée au roux avec le bouillon de cuisson de la langue, et non avec un fond étranger : c''est ce recyclage qui fait sa profondeur."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Verrines mimosa au thon', 'verrines mimosa au thon', 'France', 'France',
     'meal', 'entrée froide', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Verrines mimosa au thon', 'Verrine de crème de thon et jaunes d''œufs à la mayonnaise, garnie d''œuf mimosa', ds.id, 'SRC-015-D3',
    'Myko', 'editorial', 4, 20, 10, 'facile',
    NULL, NULL,
    'B', 'candidate', 'f4bbd2a97c5e722bf5285e0ff3f55b90',
    '{"sweet":0,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":2,"richness":4,"freshness":2,"intensity":2}'::jsonb, ARRAY['jaune d''œuf cuit','mayonnaise','moutarde']::text[],
    ARRAY['œuf cuit','moutardé','herbacé']::text[], ARRAY['blanc ferme et lisse','farce crémeuse','poudre sèche de jaune tamisé']::text[],
    ARRAY['Œuf cru','Mayonnaise','Moutarde de Dijon']::text[], ARRAY['La finition en jaune dur tamisé saupoudré sur le dessus est ce qui fait le mimosa : sans elle, le plat n''est qu''un œuf dur garni.','Les demi-blancs doivent rester entiers et servir de contenant ; hachés ou mixés, on bascule sur une salade d''œufs.','La liaison est une mayonnaise froide montée à l''huile, jamais une sauce cuite ni une crème chaude.','Le plat se sert froid, après passage au réfrigérateur ; tiède, la farce se délite et l''identité se perd.']::text[],
    ARRAY['pochage','émulsion','tamisage','mixage']::text[], ARRAY[]::text[], ARRAY['œuf','moutarde','poisson']::text[],
    'Se garde 24 heures au réfrigérateur entre 0 et 4 °C, à plat, filmé sans contact avec la farce ; les œufs durs entiers non écalés tiennent jusqu''à trois jours. La congélation est à exclure : le blanc cuit devient caoutchouteux et la mayonnaise tranche à la décongélation. La variante au thon se consomme dans les 12 heures.', '{"fridge_hours":12,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":true,"source":"manual"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-015'), '{"variant_label":"Montage en verrine : n''utiliser que les jaunes, les mixer avec la mayonnaise et le thon jusqu''à une crème lisse, dresser en verrines et saupoudrer de jaunes tamisés.","rationale":"Le blanc quitte l''assiette : il ne sert plus de coquille et doit être recyclé ailleurs, ce qui fait de cette version la plus dispendieuse des trois. En échange, la farce n''a plus à tenir toute seule et peut être mixée plus souple, avec un tiers de mayonnaise en plus, jusqu''à une crème qu''on mange à la cuillère. Le thon devient obligatoire et porte le plat ; le contraste de texture entre blanc ferme et farce lisse, lui, disparaît.","operations":[{"op":"set","form":"Thon au naturel en conserve, égoutté","quantity":160,"role":"protéine de la crème","optional":false},{"op":"set","form":"Mayonnaise","quantity":55,"role":"liaison","optional":false}],"steps":[{"op":"replace","n":3,"instruction":"Fendre chaque œuf en deux dans la longueur, lame essuyée entre chaque coupe, et faire glisser les jaunes dans un bol. Réserver les blancs à couvert : ils ne servent pas ici et se gardent deux jours au frais pour une salade ou une farce. Mettre à part deux jaunes entiers, qui feront la neige de finition."},{"op":"replace","n":5,"instruction":"Réunir dans le bol du mixeur les jaunes restants, la mayonnaise, le thon soigneusement égoutté et émietté, le sel fin, le poivre noir moulu et le persil frais ciselé. Mixer par impulsions courtes, racler les parois, puis mixer en continu jusqu''à une crème parfaitement lisse : elle doit tomber du ruban sans se casser ni couler."},{"op":"replace","n":6,"instruction":"Répartir la crème dans quatre verrines à la poche à douille, en descendant la douille au fond du verre pour ne pas emprisonner de bulle d''air, puis lisser la surface à la petite spatule. Ne pas remplir à ras bord : il faut garder la place de la neige de jaunes."},{"op":"replace","n":7,"instruction":"Tamiser les deux jaunes réservés directement au-dessus des verrines pour obtenir la neige jaune caractéristique, ajouter quelques pluches de persil frais, puis laisser raffermir trente minutes au réfrigérateur avant de servir bien frais, à la petite cuillère."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'oeuf cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Œuf cru', 270, 'g', 'required',
     'protéine principale', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'mayonnaise' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Mayonnaise', 55, 'g', 'required',
     'liaison', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'moutarde de dijon' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Moutarde de Dijon', 5, 'g', 'required',
     'condiment', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'persil frais' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Persil frais', 15, 'g', 'required',
     'herbe de finition', false, 4);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
