  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Tailler le pain rassis en dés d''un bon centimètre, croûte comprise, émincer l''oignon et dégermer l''ail avant de l''écraser au plat du couteau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire rendre leur gras aux lardons dans une poêle, à feu moyen, puis ajouter l''oignon et le laisser blondir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Jeter les dés de pain dans la poêle avec le beurre et les faire dorer à feu moyen en les remuant souvent, jusqu''à ce qu''ils croustillent dehors en restant tendres au centre. Ne pas pousser le feu pour aller plus vite : l''oignon blondi à l''étape précédente est déjà au bord de brunir et emporterait toute la poêlée dans son amertume. Ajouter l''ail écrasé dans la dernière minute seulement : plus tôt il noircirait dans la graisse chaude et donnerait son amertume à son tour.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Battre les œufs à la fourchette avec la crème fraîche liquide entière, saler légèrement — les lardons salent déjà — et poivrer, puis incorporer la ciboulette ciselée. La crème allonge l''appareil et le retient de serrer trop vite au contact de la poêle brûlante.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser les œufs sur la garniture bien chaude et baisser le feu. Ramener les bords vers le centre à la spatule pendant les premières secondes, puis laisser prendre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Retirer du feu quand le dessus reste encore crémeux : la chaleur de la poêle finit la cuisson pendant le service.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-016-D1', 'recipe_family', 'Omelette aux croûtons et aux lardons',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-016-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-016-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-016-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('beede0d786e026e7737cc2314a88fb58'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":0,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":2,"richness":4,"freshness":2,"intensity":3},"dominant_flavors":["œuf","lardon fumé","ail","ciboulette"],"aroma_families":["œuf cuit","pain doré","alliacé grillé"],"target_textures":["moelleux","croûtons croustillants","baveux à cœur"],"signature_ingredients":["Pain rassis","Lardon fumé cru","Œuf cru"],"identity_guardrails":["Les croûtons sont dorés dans la graisse des lardons avant l''arrivée de l''œuf ; ajoutés crus à l''appareil, ils s''y détrempent au lieu de croustiller.","L''ail entre en toute fin de coloration, jamais au début : brûlé, il domine et amertume tout le plat.","L''omelette quitte le feu encore crémeuse au centre et se sert aussitôt, sans quoi les croûtons ramollissent."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
