DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Omelette de pommes de terre râpées', 'omelette de pommes de terre rapees', 'France', 'France',
     'meal', 'omelette', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Omelette de pommes de terre râpées', 'Omelette plate aux pommes de terre fraîchement râpées et lardons', ds.id, 'SRC-016-D2',
    'Myko', 'editorial', 4, 20, 20, 'facile',
    NULL, NULL,
    'B', 'candidate', '9ddd19230f75e550acbd5b23fb410900',
    '{"sweet":1,"salty":2,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":2}'::jsonb, ARRAY['pomme de terre','œuf','ciboulette']::text[],
    ARRAY['œuf cuit','alliacé frais','beurre noisette']::text[], ARRAY['galette dense','filaments fondants','surface dorée']::text[],
    ARRAY['Pomme de terre crue, épluchée','Lardon fumé cru','Œuf cru']::text[], ARRAY['La râpure doit être essorée au linge : gorgée d''eau, elle empêche l''œuf de prendre et la galette se défait.','Tout est mêlé à l''œuf avant cuisson ; rien n''est coloré à part, c''est ce qui distingue cette version de l''omelette paysanne.','La cuisson reste douce et couverte jusqu''au cœur, la pomme de terre crue ne s''attendrit pas autrement.']::text[],
    ARRAY['blanchiment','cuisson à couvert']::text[], ARRAY[]::text[], ARRAY['œuf','lait']::text[],
    'Se garde 3 jours au réfrigérateur entre 0 et 4 °C en boîte hermétique : cuite de part en part, cette galette n''a pas le cœur crémeux qui interdit à l''omelette paysanne d''attendre. Se mange froide en parts ou retiédie deux minutes par face à la poêle couverte sur feu doux, jamais au micro-ondes qui la rend spongieuse. Congélation à proscrire : la pomme de terre râpée rend son eau à la décongélation et la galette se délite.', '{"fridge_hours":72,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-016'), '{"variant_label":"Version 750g.com : blanchir brièvement du lard, râper finement des pommes de terre bien séchées dans un linge et émincer un oignon en rondelles, le tout mélangé aux œufs battus avant cuisson.","rationale":"La pomme de terre passe de cuite à crue et de rondelles à râpure, ce qui change tout l''ordre du travail : plus rien n''est coloré à part, tout est mélangé à l''œuf et cuit d''un seul bloc. Il faut compter quatre cent cinquante grammes de tubercule cru pour retrouver le poids de quatre cents grammes de pomme de terre déjà cuite, un essorage sérieux au linge et une dizaine de minutes de cuisson douce en plus pour que la râpure s''attendrisse. On y gagne une galette dense et liée, on y perd la croûte des rondelles rissolées et le cœur baveux de l''omelette paysanne.","operations":[{"op":"substitute","form":"Pomme de terre cuite","with":"Pomme de terre crue, épluchée","quantity":450,"unit":"g","role":"féculent"}],"steps":[{"op":"replace","n":1,"instruction":"Râper les pommes de terre épluchées à la grille moyenne, les enfermer dans un linge propre et tordre fermement pour en chasser l''eau. Émincer l''oignon en fines rondelles. Une râpure mal essorée rendrait son eau dans la poêle et l''appareil ne prendrait jamais."},{"op":"replace","n":2,"instruction":"Plonger les lardons une demi-minute dans une petite casserole d''eau bouillante, les égoutter et les éponger. Ce blanchiment leur retire l''excès de sel et de fumé, qui domineraient tout dans un appareil aussi nu."},{"op":"remove","n":3},{"op":"replace","n":4,"instruction":"Battre les œufs à la fourchette, saler franchement — le blanchiment a emporté une bonne part du sel des lardons et la râpure de pomme de terre en boit beaucoup — et poivrer, puis incorporer la ciboulette ciselée, la râpure essorée, les rondelles d''oignon et les lardons. Mélanger jusqu''à ce que chaque filament soit enrobé d''œuf, sans laisser reposer : la râpure noircirait à l''air."},{"op":"replace","n":5,"instruction":"Faire fondre le beurre dans une poêle à feu moyen, y verser l''appareil d''un coup et l''étaler à la spatule sur toute la surface. Baisser aussitôt le feu au minimum : le tubercule cru demande une douzaine de minutes pour s''attendrir, et un feu vif brûlerait le dessous bien avant."},{"op":"replace","n":6,"instruction":"Couvrir et laisser cuire à petit feu jusqu''à ce que le dessus soit pris, puis retourner la galette à l''aide d''une assiette et la laisser colorer deux minutes de l''autre côté. Vérifier d''une pointe de couteau : elle doit traverser sans résistance, faute de quoi la râpure reste croquante et crayeuse."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
