  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Râper les pommes de terre épluchées à la grille moyenne, les enfermer dans un linge propre et tordre fermement pour en chasser l''eau. Émincer l''oignon en fines rondelles. Une râpure mal essorée rendrait son eau dans la poêle et l''appareil ne prendrait jamais.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Plonger les lardons une demi-minute dans une petite casserole d''eau bouillante, les égoutter et les éponger. Ce blanchiment leur retire l''excès de sel et de fumé, qui domineraient tout dans un appareil aussi nu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Battre les œufs à la fourchette, saler franchement — le blanchiment a emporté une bonne part du sel des lardons et la râpure de pomme de terre en boit beaucoup — et poivrer, puis incorporer la ciboulette ciselée, la râpure essorée, les rondelles d''oignon et les lardons. Mélanger jusqu''à ce que chaque filament soit enrobé d''œuf, sans laisser reposer : la râpure noircirait à l''air.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Faire fondre le beurre dans une poêle à feu moyen, y verser l''appareil d''un coup et l''étaler à la spatule sur toute la surface. Baisser aussitôt le feu au minimum : le tubercule cru demande une douzaine de minutes pour s''attendrir, et un feu vif brûlerait le dessous bien avant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Couvrir et laisser cuire à petit feu jusqu''à ce que le dessus soit pris, puis retourner la galette à l''aide d''une assiette et la laisser colorer deux minutes de l''autre côté. Vérifier d''une pointe de couteau : elle doit traverser sans résistance, faute de quoi la râpure reste croquante et crayeuse.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-016-D2', 'recipe_family', 'Omelette de pommes de terre râpées',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-016-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-016-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-016-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('9ddd19230f75e550acbd5b23fb410900'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":2,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":2},"dominant_flavors":["pomme de terre","œuf","ciboulette"],"aroma_families":["œuf cuit","alliacé frais","beurre noisette"],"target_textures":["galette dense","filaments fondants","surface dorée"],"signature_ingredients":["Pomme de terre crue, épluchée","Lardon fumé cru","Œuf cru"],"identity_guardrails":["La râpure doit être essorée au linge : gorgée d''eau, elle empêche l''œuf de prendre et la galette se défait.","Tout est mêlé à l''œuf avant cuisson ; rien n''est coloré à part, c''est ce qui distingue cette version de l''omelette paysanne.","La cuisson reste douce et couverte jusqu''au cœur, la pomme de terre crue ne s''attendrit pas autrement."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
