  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-016-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('fac0b2e1832635358cf946bcd534e0fb'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":0,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":2,"freshness":2,"intensity":2},"dominant_flavors":["œuf","lardon fumé","ciboulette"],"aroma_families":["œuf cuit","alliacé frais","poivré"],"target_textures":["lanières fermes","cœur pris","croûte sèche"],"signature_ingredients":["Pomme de terre cuite","Lardon fumé cru","Œuf cru"],"identity_guardrails":["Sans pomme de terre ni lardons, c''est une omelette nature : la garniture est ce qui fait la paysanne.","Aucune matière grasse laitière : la graisse des lardons est la seule à colorer les rondelles.","L''omelette cuit jusqu''au cœur ferme et refroidit entière avant d''être détaillée ; découpée tiède, elle s''effondre."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
