DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Pan bagnat aux tomates en rondelles', 'pan bagnat aux tomates en rondelles', 'France', 'France',
     'meal', 'sandwich', 'documented_variation', 'bright_acidic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Pan bagnat aux tomates en rondelles', 'Sandwich provençal pressé avec tomates fraîches en rondelles, œuf dur et olives', ds.id, 'SRC-017-D2',
    'Myko', 'editorial', 4, 20, 10, 'facile',
    NULL, NULL,
    'B', 'candidate', '69d8723d8b621c866dd139b030b14280',
    '{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":4,"intensity":3}'::jsonb, ARRAY['tomate mûre','huile d''olive fruitée','olive noire','acidité vinaigrée']::text[],
    ARRAY['fruité olive','végétal frais','acidulé vinaigré']::text[], ARRAY['mie imbibée et moelleuse','croûte souple','jaune d''œuf crémeux']::text[],
    ARRAY['Pain de campagne','Huile d''olive vierge extra','Tomate fraîche mûre','Olive noire']::text[], ARRAY['La mie doit être imbibée d''huile d''olive et du jus de tomate : un pan bagnat sec n''est plus un pan bagnat.','Tout est assemblé à froid et rien n''est cuit dans le sandwich ; le pain ne passe jamais au grill ni au four.','Aucun beurre ni sauce émulsionnée type mayonnaise : l''huile d''olive vierge extra est l''unique corps gras.','Le repos sous pression fait partie de la recette, il ne s''agit pas d''un sandwich servi à la minute.']::text[],
    ARRAY['marinade','pochage','pressage']::text[], ARRAY[]::text[], ARRAY['gluten','œuf','sulfites']::text[],
    'Se garde 24 heures au réfrigérateur entre 0 et 4 °C, emballé bien serré dans un film ou un papier ; il gagne à reposer quelques heures mais se délite au-delà d''une journée. Congélation exclue : le pain imbibé et l''œuf dur deviennent spongieux et caoutchouteux à la décongélation.', '{"fridge_hours":24,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":true,"source":"manual"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-017'), '{"variant_label":"Remplacer la tomate râpée par de fines rondelles de tomate laissées à dégorger dans l''huile et le vinaigre.","rationale":"La pulpe râpée cède la place à des rondelles entières : la tomate se mange en tranches franches au lieu de fondre dans la mie, et la mâche du sandwich s''en trouve plus nette. Le revers est liquide — une tomate en rondelles ne rend qu''une fraction du jus d''une tomate râpée, et c''est ce jus qui imbibe le pain. Il faut donc verser la marinade lentement, en plusieurs fois, sous peine d''un pain sec par endroits et noyé ailleurs.","operations":[{"op":"substitute","form":"Tomate râpée","with":"Tomate fraîche mûre","quantity":480,"unit":"g","role":"légume"}],"steps":[{"op":"replace","n":2,"instruction":"Couper les tomates en rondelles de trois millimètres et les ranger à plat dans un saladier avec le vinaigre de vin rouge, les deux tiers de l''huile d''olive, le sel fin et le poivre noir moulu ; laisser dégorger un quart d''heure, le temps que le sel tire l''eau de la chair et que la marinade se colore."},{"op":"replace","n":4,"instruction":"Badigeonner les deux faces internes avec l''huile d''olive restante, puis les arroser de la marinade recueillie au fond du saladier. Elle est bien moins abondante que le jus d''une pulpe râpée : verser en trois fois, en laissant la mie boire entre chaque passage, sinon le pain reste sec d''un côté et détrempé de l''autre."},{"op":"replace","n":5,"instruction":"Ranger les rondelles de tomate égouttées sur la base en les faisant se chevaucher comme des tuiles, sur deux couches régulières si nécessaire : quatre cent quatre-vingts grammes de tomate ne tiennent pas à plat sur une demi-miche, et une garniture d''épaisseur constante vaut mieux qu''un tas au centre. Répartir dessus les rondelles d''œuf dur et parsemer d''olives noires dénoyautées et grossièrement concassées."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

