  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Immerger les œufs dans une casserole d''eau frémissante et compter dix minutes à petits bouillons, puis les refroidir sous l''eau courante, les écaler et les couper en rondelles régulières.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Couper les tomates en rondelles de trois millimètres et les ranger à plat dans un saladier avec le vinaigre de vin rouge, les deux tiers de l''huile d''olive, le sel fin et le poivre noir moulu ; laisser dégorger un quart d''heure, le temps que le sel tire l''eau de la chair et que la marinade se colore.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Fendre le pain de campagne en deux dans l''épaisseur et creuser légèrement la mie de la partie supérieure pour ménager de la place à la garniture et à l''huile.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Badigeonner les deux faces internes avec l''huile d''olive restante, puis les arroser de la marinade recueillie au fond du saladier. Elle est bien moins abondante que le jus d''une pulpe râpée : verser en trois fois, en laissant la mie boire entre chaque passage, sinon le pain reste sec d''un côté et détrempé de l''autre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ranger les rondelles de tomate égouttées sur la base en les faisant se chevaucher comme des tuiles, sur deux couches régulières si nécessaire : quatre cent quatre-vingts grammes de tomate ne tiennent pas à plat sur une demi-miche, et une garniture d''épaisseur constante vaut mieux qu''un tas au centre. Répartir dessus les rondelles d''œuf dur et parsemer d''olives noires dénoyautées et grossièrement concassées.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Recoiffer avec la partie supérieure, presser fermement de la paume, envelopper serré dans un papier et laisser reposer trente à soixante minutes au frais avant de découper en quatre parts.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-017-D2', 'recipe_family', 'Pan bagnat aux tomates en rondelles',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-017-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-017-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-017-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('69d8723d8b621c866dd139b030b14280'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"bright_acidic","scores":{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":4,"intensity":3},"dominant_flavors":["tomate mûre","huile d''olive fruitée","olive noire","acidité vinaigrée"],"aroma_families":["fruité olive","végétal frais","acidulé vinaigré"],"target_textures":["mie imbibée et moelleuse","croûte souple","jaune d''œuf crémeux"],"signature_ingredients":["Pain de campagne","Huile d''olive vierge extra","Tomate fraîche mûre","Olive noire"],"identity_guardrails":["La mie doit être imbibée d''huile d''olive et du jus de tomate : un pan bagnat sec n''est plus un pan bagnat.","Tout est assemblé à froid et rien n''est cuit dans le sandwich ; le pain ne passe jamais au grill ni au four.","Aucun beurre ni sauce émulsionnée type mayonnaise : l''huile d''olive vierge extra est l''unique corps gras.","Le repos sous pression fait partie de la recette, il ne s''agit pas d''un sandwich servi à la minute."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Pan bagnat pressé de la veille', 'pan bagnat presse de la veille', 'France', 'France',
     'meal', 'sandwich', 'documented_variation', 'bright_acidic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Pan bagnat pressé de la veille', 'Pan bagnat classique préparé la veille pour une meilleure imprégnation des ingrédients', ds.id, 'SRC-017-D3',
    'Myko', 'editorial', 4, 20, 10, 'facile',
    NULL, NULL,
    'B', 'candidate', '5357097d601dbf5a7a442c6c65ddef9c',
    '{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":4,"intensity":3}'::jsonb, ARRAY['tomate mûre','huile d''olive fruitée','olive noire','acidité vinaigrée']::text[],
    ARRAY['fruité olive','végétal frais','acidulé vinaigré']::text[], ARRAY['mie imbibée et moelleuse','croûte souple','jaune d''œuf crémeux']::text[],
    ARRAY['Pain de campagne','Huile d''olive vierge extra','Tomate râpée','Olive noire']::text[], ARRAY['La mie doit être imbibée d''huile d''olive et du jus de tomate : un pan bagnat sec n''est plus un pan bagnat.','Tout est assemblé à froid et rien n''est cuit dans le sandwich ; le pain ne passe jamais au grill ni au four.','Aucun beurre ni sauce émulsionnée type mayonnaise : l''huile d''olive vierge extra est l''unique corps gras.','Le repos sous pression fait partie de la recette, il ne s''agit pas d''un sandwich servi à la minute.']::text[],
    ARRAY['marinade','pochage','pressage']::text[], ARRAY[]::text[], ARRAY['gluten','œuf','sulfites']::text[],
    'Se mange le jour de la découpe : la nuit de pressage compte déjà dans la vie du sandwich et une seconde journée délite la mie. Garder entre 0 et 4 °C sous son papier et son poids jusqu''au service, puis sortir 30 minutes avant de découper pour que l''huile d''olive se refluidifie. Congélation exclue : le pain imbibé et l''œuf dur deviennent spongieux et caoutchouteux à la décongélation.', '{"fridge_hours":24,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":true,"source":"manual"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-017'), '{"variant_label":"Préparer la veille et laisser presser toute la nuit sous un poids léger pour une mie totalement imprégnée.","rationale":"Le repos passe d''une demi-heure sous la paume à douze heures sous un poids : la mie finit par boire tout le jus et l''huile jusqu''au cœur, et le sandwich se tient d''un bloc à la découpe. La contrepartie est que le pain perd le peu de mâche qui lui restait et que la tomate, longuement pressée, rend son eau au point de fatiguer. Le froid fige aussi l''huile d''olive, il faut sortir le pan bagnat une bonne demi-heure avant de le servir pour qu''il retrouve son parfum.","operations":[],"steps":[{"op":"replace","n":6,"instruction":"Recoiffer avec la partie supérieure, presser fermement de la paume, envelopper serré dans un papier puis dans un film bien tendu. Poser le paquet sur une assiette, coiffer d''une petite planche et lester d''une boîte de conserve, sans excès : un poids trop lourd chasse l''huile au lieu de la faire pénétrer. Laisser au réfrigérateur toute la nuit, puis sortir le sandwich une demi-heure avant de le découper en quatre parts."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
