  SELECT
    v_family, 3, 'Pichade mentonnaise', 'Tarte sur pâte levée garnie d''oignons confits, anchois et olives, proche de la pissaladière', ds.id, 'SRC-019-D1',
    'Myko', 'editorial', 4, 30, 115, 'facile',
