  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Réunir dans un saladier la farine, la levure chimique et le sel fin, creuser un creux au centre, y verser l''eau tiède et 15 g d''huile d''olive, puis travailler à la main jusqu''à obtenir une boule souple et lisse qui se décolle des doigts ; couvrir d''un linge et réserver le temps de cuire la garniture.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Peler les oignons et les tailler en lamelles fines et régulières. Parer les bulbes de fenouil, ôter la base dure et les côtes extérieures les plus filandreuses, puis les émincer à la même finesse pour que les deux légumes fondent au même rythme. Chauffer le reste de l''huile d''olive dans une grande sauteuse, y verser ensemble oignons et fenouil avec le sucre semoule, le thym séché, les herbes de Provence et le poivre noir moulu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Couvrir et laisser compoter sur feu très doux une quarantaine de minutes en remuant toutes les cinq minutes ; ajouter l''ail écrasé à mi-cuisson. Le fenouil met plus longtemps que l''oignon à céder : la compotée n''est prête que lorsque ses lamelles s''écrasent sans résistance entre deux doigts, translucides et à peine blondes, sans jamais colorer ni accrocher — une cuillère d''eau suffit à rattraper le fond si besoin. Ne pas saler à cette étape.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Hors du feu, écraser les deux tiers des anchois égouttés dans les oignons encore chauds jusqu''à ce qu''ils se délitent entièrement dans la compotée ; réserver le tiers restant en filets entiers pour le dessus, puis laisser tiédir la garniture.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Préchauffer le four à 220 °C. Étaler la pâte au rouleau en un rectangle d''environ 40 × 25 cm sur une plaque tapissée de papier cuisson, en laissant un léger bourrelet tout autour pour retenir la garniture.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Répartir la compotée d''oignons et de fenouil en couche régulière jusqu''au bourrelet, croiser dessus les filets d''anchois réservés de façon à dessiner des losanges, et déposer une olive noire au creux de chaque losange.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Enfourner environ 20 minutes, jusqu''à ce que le pourtour soit doré et le dessous de la pâte sec et ferme au toucher. Sortir la plaque, laisser reposer une dizaine de minutes et servir tiède ou à température ambiante, jamais brûlante.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-019-D3', 'recipe_family', 'Pissaladière au fenouil',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-019-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-019-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-019-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('aa87a317c73a2fdae926dce90cfca15a'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":3,"salty":4,"acidic":1,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":4},"dominant_flavors":["oignon confit sucré","anchois salé","olive noire","huile d''olive"],"aroma_families":["allium","herbacé","marin"],"target_textures":["oignon fondant","croûte croustillante","filet d''anchois moelleux"],"signature_ingredients":["Oignon jaune cru","Anchois à l''huile, égoutté","Olive noire"],"identity_guardrails":["Sans anchois, ce n''est plus une pissaladière mais une simple tarte à l''oignon.","Les oignons doivent compoter longuement à feu doux jusqu''à fondre : simplement sautés, ils perdent la douceur qui fait le plat.","Ni tomate ni fromage : la version tomatée est une pichade mentonnaise, un autre plat.","La base est une pâte à pain fine, pas une pâte feuilletée ni une pâte brisée."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Pissaladière à l''aubergine rôtie', 'pissaladiere a l aubergine rotie', 'France', 'France',
     'meal', 'tarte salée', 'documented_variation', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Pissaladière à l''aubergine rôtie', 'Tarte niçoise levée aux oignons confits, anchois, olives et tranches d''aubergine rôtie', ds.id, 'SRC-019-D4',
    'Myko', 'editorial', 4, 35, 60, 'facile',
    NULL, NULL,
    'B', 'candidate', 'a313a487b84408531a0e7505e08cd785',
    '{"sweet":3,"salty":4,"acidic":1,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":4}'::jsonb, ARRAY['oignon confit sucré','anchois salé','olive noire','huile d''olive']::text[],
    ARRAY['allium','herbacé','marin']::text[], ARRAY['oignon fondant','croûte croustillante','filet d''anchois moelleux']::text[],
    ARRAY['Oignon jaune cru','Anchois à l''huile, égoutté','Olive noire']::text[], ARRAY['Sans anchois, ce n''est plus une pissaladière mais une simple tarte à l''oignon.','Les oignons doivent compoter longuement à feu doux jusqu''à fondre : simplement sautés, ils perdent la douceur qui fait le plat.','Ni tomate ni fromage : la version tomatée est une pichade mentonnaise, un autre plat.','La base est une pâte à pain fine, pas une pâte feuilletée ni une pâte brisée.']::text[],
    ARRAY['mijotage','rôtissage','pétrissage']::text[], ARRAY[]::text[], ARRAY['gluten','poisson']::text[],
    'Se conserve 48 h au réfrigérateur entre 0 et 4 °C, couverte d''un film ou en boîte hermétique ; se déguste tiède ou froide, et se retend en 8 minutes à 180 °C. La compotée d''oignons seule se congèle très bien 3 mois, mais la tarte montée supporte mal la congélation : la pâte ressort détrempée.', '{"fridge_hours":48,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-019'), '{"variant_label":"Base à l''aubergine rôtie écrasée mêlée aux oignons, pour une garniture plus fondante.","rationale":"Six cent cinquante grammes d''aubergine rôtie au four viennent s''écraser dans une compotée d''oignons réduite d''un tiers. La garniture passe de la lamelle fondante à la purée grumeleuse : elle couvre mieux la pâte, tient à la découpe et porte un goût de fumé léger que l''oignon seul ne donne pas. Le prix à payer est un four occupé quarante minutes en amont et une garniture plus lourde en eau, qu''il faut vraiment laisser sécher avant de l''étaler.","operations":[{"op":"scale","form":"Oignon jaune cru","factor":0.65},{"op":"add","form":"Aubergine fraîche","quantity":650,"unit":"g","role":"légume","optional":false}],"steps":[{"op":"replace","n":5,"instruction":"Monter le four à 220 °C. Étaler la pâte au rouleau en un rectangle d''environ 40 × 25 cm sur une plaque tapissée de papier cuisson, en laissant un léger bourrelet tout autour pour retenir la garniture."},{"op":"replace","n":6,"instruction":"Répartir la garniture d''oignons et d''aubergine en couche régulière jusqu''au bourrelet, croiser dessus les filets d''anchois réservés de façon à dessiner des losanges, et déposer une olive noire au creux de chaque losange."},{"op":"insert","after":3,"instruction":"Prélever à la cuillère la chair des aubergines rôties en laissant la peau et le jus brun qui s''est amassé sous elles, l''écraser grossièrement à la fourchette et la mêler hors du feu aux oignons compotés. Garder du grain : une chair mixée trop lisse coulerait sur la pâte au lieu d''y tenir en couche."},{"op":"insert","after":1,"instruction":"Chauffer le four à 200 °C. Fendre les aubergines en deux dans la longueur, quadriller la chair à la pointe du couteau sans entamer la peau, puis les coucher face tranchée contre une plaque tapissée de papier cuisson. Les rôtir quarante minutes pendant que les oignons compotent : la peau doit se rider et se creuser, et la chair s''enfoncer sans la moindre résistance."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

