  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Réunir dans un saladier la farine, la levure chimique et le sel fin, creuser un creux au centre, y verser l''eau tiède et 15 g d''huile d''olive, puis travailler à la main jusqu''à obtenir une boule souple et lisse qui se décolle des doigts ; couvrir d''un linge et réserver le temps de cuire la garniture.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Chauffer le four à 200 °C. Fendre les aubergines en deux dans la longueur, quadriller la chair à la pointe du couteau sans entamer la peau, puis les coucher face tranchée contre une plaque tapissée de papier cuisson. Les rôtir quarante minutes pendant que les oignons compotent : la peau doit se rider et se creuser, et la chair s''enfoncer sans la moindre résistance.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Peler les oignons et les tailler en lamelles fines et régulières. Chauffer le reste de l''huile d''olive dans une grande sauteuse, y verser les oignons avec le sucre semoule, le thym séché, les herbes de Provence et le poivre noir moulu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Couvrir et laisser compoter sur feu très doux environ 35 minutes en remuant toutes les cinq minutes ; ajouter l''ail écrasé à mi-cuisson. Les oignons doivent devenir translucides et fondants, à peine blonds, sans jamais colorer ni accrocher — une cuillère d''eau suffit à rattraper le fond si besoin. Ne pas saler à cette étape.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Prélever à la cuillère la chair des aubergines rôties en laissant la peau et le jus brun qui s''est amassé sous elles, l''écraser grossièrement à la fourchette et la mêler hors du feu aux oignons compotés. Garder du grain : une chair mixée trop lisse coulerait sur la pâte au lieu d''y tenir en couche.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Hors du feu, écraser les deux tiers des anchois égouttés dans les oignons encore chauds jusqu''à ce qu''ils se délitent entièrement dans la compotée ; réserver le tiers restant en filets entiers pour le dessus, puis laisser tiédir la garniture.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Monter le four à 220 °C. Étaler la pâte au rouleau en un rectangle d''environ 40 × 25 cm sur une plaque tapissée de papier cuisson, en laissant un léger bourrelet tout autour pour retenir la garniture.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Répartir la garniture d''oignons et d''aubergine en couche régulière jusqu''au bourrelet, croiser dessus les filets d''anchois réservés de façon à dessiner des losanges, et déposer une olive noire au creux de chaque losange.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Enfourner environ 20 minutes, jusqu''à ce que le pourtour soit doré et le dessous de la pâte sec et ferme au toucher. Sortir la plaque, laisser reposer une dizaine de minutes et servir tiède ou à température ambiante, jamais brûlante.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-019-D4', 'recipe_family', 'Pissaladière à l''aubergine rôtie',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-019-D4', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-019-D4', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-019-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('a313a487b84408531a0e7505e08cd785'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":3,"salty":4,"acidic":1,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":4},"dominant_flavors":["oignon confit sucré","anchois salé","olive noire","huile d''olive"],"aroma_families":["allium","herbacé","marin"],"target_textures":["oignon fondant","croûte croustillante","filet d''anchois moelleux"],"signature_ingredients":["Oignon jaune cru","Anchois à l''huile, égoutté","Olive noire"],"identity_guardrails":["Sans anchois, ce n''est plus une pissaladière mais une simple tarte à l''oignon.","Les oignons doivent compoter longuement à feu doux jusqu''à fondre : simplement sautés, ils perdent la douceur qui fait le plat.","Ni tomate ni fromage : la version tomatée est une pichade mentonnaise, un autre plat.","La base est une pâte à pain fine, pas une pâte feuilletée ni une pâte brisée."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Gratin de poireaux à la béchamel muscadée', 'gratin de poireaux a la bechamel muscadee', 'France', 'France',
     'meal', 'gratin', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Gratin de poireaux à la béchamel muscadée', 'Poireaux blanchis nappés d''une béchamel à la muscade, gratinés au gruyère', ds.id, 'SRC-020-D1',
    'Myko', 'editorial', 4, 30, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', '05eb1c6623bb6a94e9af76d5ed83696a',
    '{"sweet":2,"salty":3,"acidic":0,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['poireau doux','crème lactée','fromage gratiné']::text[],
    ARRAY['lactée','alliacée','grillée']::text[], ARRAY['fondant','croûte gratinée','nappage crémeux']::text[],
    ARRAY['Poireau cru','Gruyère râpé','Lait demi-écrémé']::text[], ARRAY['Le poireau doit être précuit puis pressé : sans cet égouttage, le plat rend son eau et devient une soupe gratinée.','Sans gruyère râpé sur le dessus, il n''y a plus de croûte dorée et le plat cesse d''être un gratin.','Le liant blanc et onctueux est obligatoire : privé de crème, l''appareil n''est plus qu''un plat de poireaux rôtis.']::text[],
    ARRAY['blanchiment','roux','gratinage']::text[], ARRAY[]::text[], ARRAY['lait']::text[],
    'Se conserve 3 jours au réfrigérateur entre 0 et 4 °C, couvert une fois complètement refroidi, et se réchauffe 15 minutes à 180 °C pour retrouver la croûte. La congélation est déconseillée : le poireau relâche son eau à la décongélation et la crème risque de trancher.', '{"fridge_hours":72,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-020'), '{"variant_label":"Version béchamel classique : remplacer la crème par une sauce blanche montée au roux beurre-farine-lait, muscadée, dès que ces formes sont disponibles au catalogue.","rationale":"La crème laisse la place à une vraie béchamel : quarante grammes de beurre et autant de farine en roux blanc, mouillés d''un demi-litre de lait demi-écrémé et relevés d''une pointe de muscade. La sauce enrobe davantage et tient mieux à la cuisson qu''une crème, qui peut trancher sous le gril ; le gratin devient plus nourrissant et franchement plus farineux en bouche. Le coût est du travail en plus — un roux à surveiller, un fouet à tenir — et une dizaine de minutes ajoutées à la cuisson.","operations":[{"op":"substitute","form":"Crème fraîche liquide entière","with":"Lait demi-écrémé","quantity":500,"unit":"ml","role":"béchamel"},{"op":"add","form":"Beurre doux","quantity":40,"unit":"g","role":"béchamel","optional":false},{"op":"add","form":"Farine de blé T55","quantity":40,"unit":"g","role":"béchamel","optional":false},{"op":"add","form":"Muscade moulue","quantity":0.5,"unit":"g","role":"épice","optional":false}],"steps":[{"op":"replace","n":5,"instruction":"Retirer la sauteuse du feu. Dans une casserole à part, faire fondre le beurre doux à feu doux, y pleuvoir la farine de blé T55 en une seule fois et remuer deux minutes sans laisser blondir : un roux blanc doit sentir le biscuit, jamais le grillé. Verser le lait demi-écrémé froid en trois fois, en fouettant jusqu''au lisse à chaque ajout, amener à petits frémissements et laisser épaissir cinq minutes, le temps que la sauce nappe le dos de la cuillère. Assaisonner d''une pointe de muscade moulue, saler, poivrer, puis en napper les poireaux et mélanger doucement pour que chaque tronçon soit enrobé."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
