DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Gratin de poireaux à la tomate', 'gratin de poireaux a la tomate', 'France', 'France',
     'meal', 'gratin', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Gratin de poireaux à la tomate', 'Poireaux blanchis dans une sauce tomate fraîche à l''ail, gratinés au gruyère', ds.id, 'SRC-020-D2',
    'Myko', 'editorial', 4, 40, 55, 'facile',
    NULL, NULL,
    'B', 'candidate', 'cec17a52c93deee4ae44ccb6b6be1ecb',
    '{"sweet":2,"salty":3,"acidic":0,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['poireau doux','crème lactée','fromage gratiné']::text[],
    ARRAY['lactée','alliacée','grillée']::text[], ARRAY['fondant','croûte gratinée','nappage crémeux']::text[],
    ARRAY['Poireau cru','Gruyère râpé','Crème fraîche liquide entière']::text[], ARRAY['Le poireau doit être précuit puis pressé : sans cet égouttage, le plat rend son eau et devient une soupe gratinée.','Sans gruyère râpé sur le dessus, il n''y a plus de croûte dorée et le plat cesse d''être un gratin.','Le liant blanc et onctueux est obligatoire : privé de crème, l''appareil n''est plus qu''un plat de poireaux rôtis.']::text[],
    ARRAY['blanchiment','réduction','gratinage']::text[], ARRAY[]::text[], ARRAY['lait']::text[],
    'Se conserve 3 jours au réfrigérateur entre 0 et 4 °C, couvert une fois complètement refroidi, et se réchauffe 15 minutes à 180 °C pour retrouver la croûte. La congélation est déconseillée : le poireau relâche son eau à la décongélation et la crème risque de trancher.', '{"fridge_hours":72,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-020'), '{"variant_label":"Montage à la tomate façon marmiton.org : alterner des couches de tomates pelées et épépinées mijotées à l''oignon et à l''ail avec les poireaux et le fromage.","rationale":"Sept cents grammes de tomates pelées, épépinées et mijotées à l''oignon et à l''ail s''intercalent en couches entre les poireaux et le fromage. L''acidité et le sucre de la tomate coupent le gras du gruyère et donnent au gratin une lecture méridionale que la version crémée n''a pas. La crème tombe donc à soixante grammes — la sauce apporte désormais l''humidité, et en garder cent seize noierait le plat. Il faut compter vingt minutes de mijotage et un montage en trois temps là où la base se contentait d''une couche unique.","operations":[{"op":"add","form":"Tomate fraîche mûre","quantity":700,"unit":"g","role":"sauce","optional":false},{"op":"add","form":"Oignon jaune cru","quantity":150,"unit":"g","role":"aromate","optional":false},{"op":"add","form":"Ail cru","quantity":8,"unit":"g","role":"aromate","optional":false},{"op":"set","form":"Huile d''olive vierge extra","quantity":40,"role":"matière grasse","optional":false},{"op":"set","form":"Crème fraîche liquide entière","quantity":60,"role":"liant","optional":false}],"steps":[{"op":"replace","n":4,"instruction":"Faire chauffer le reste de l''huile d''olive vierge extra dans une sauteuse large et y remuer les poireaux égouttés trois à quatre minutes sur feu vif, le temps que l''humidité restante s''évapore et que les tronçons prennent une légère coloration. Saler et poivrer à ce moment-là."},{"op":"replace","n":5,"instruction":"Retirer la sauteuse du feu, arroser des soixante grammes de crème fraîche liquide entière et mélanger doucement. Il n''en faut plus qu''un voile : la sauce apporte désormais l''essentiel du moelleux, et une double dose ferait un gratin qui rend du jus dans l''assiette. Goûter et rectifier le sel et le poivre."},{"op":"replace","n":6,"instruction":"Monter le gratin par couches dans le plat : un tiers des poireaux, un tiers de la sauce tomate étalée à la cuillère, une poignée de gruyère râpé, et recommencer deux fois. Terminer par le fromage réparti jusqu''aux bords, qui doit couvrir toute la surface — une couche de tomate laissée à l''air brunit et sèche au lieu de gratiner."},{"op":"insert","after":3,"instruction":"Inciser les tomates en croix à la base, les plonger trente secondes dans l''eau bouillante puis aussitôt dans l''eau glacée : la peau se retire alors d''un seul geste. Les couper en deux, les épépiner au-dessus d''une passoire, puis les concasser. Faire suer l''oignon émincé et l''ail écrasé dans une cuillerée d''huile d''olive prélevée sur la dose, ajouter la pulpe et laisser mijoter vingt minutes à découvert, jusqu''à une sauce courte qui ne rend plus d''eau au fond de la casserole."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poireau cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poireau cru', 1000, 'g', 'required',
     'légume principal', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
