  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Ôter des poireaux les feuilles vertes les plus coriaces et l''extrémité racinaire, fendre les blancs sur toute leur longueur, puis les passer sous un filet d''eau froide en écartant les épaisseurs pour déloger la terre. Détailler ensuite en tronçons d''environ trois centimètres.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Porter un grand volume d''eau salée à frémissement, y plonger les tronçons et compter une quinzaine de minutes de cuisson : la lame d''un couteau doit s''enfoncer sans buter dans le cœur du poireau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Verser le contenu de la casserole dans une passoire et appuyer franchement sur les poireaux avec le dos d''une louche pour en chasser le plus d''eau possible. C''est ce pressage qui évite au gratin de rendre du jus en cuisant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Inciser les tomates en croix à la base, les plonger trente secondes dans l''eau bouillante puis aussitôt dans l''eau glacée : la peau se retire alors d''un seul geste. Les couper en deux, les épépiner au-dessus d''une passoire, puis les concasser. Faire suer l''oignon émincé et l''ail écrasé dans une cuillerée d''huile d''olive prélevée sur la dose, ajouter la pulpe et laisser mijoter vingt minutes à découvert, jusqu''à une sauce courte qui ne rend plus d''eau au fond de la casserole.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Faire chauffer le reste de l''huile d''olive vierge extra dans une sauteuse large et y remuer les poireaux égouttés trois à quatre minutes sur feu vif, le temps que l''humidité restante s''évapore et que les tronçons prennent une légère coloration. Saler et poivrer à ce moment-là.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Retirer la sauteuse du feu, arroser des soixante grammes de crème fraîche liquide entière et mélanger doucement. Il n''en faut plus qu''un voile : la sauce apporte désormais l''essentiel du moelleux, et une double dose ferait un gratin qui rend du jus dans l''assiette. Goûter et rectifier le sel et le poivre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Monter le gratin par couches dans le plat : un tiers des poireaux, un tiers de la sauce tomate étalée à la cuillère, une poignée de gruyère râpé, et recommencer deux fois. Terminer par le fromage réparti jusqu''aux bords, qui doit couvrir toute la surface — une couche de tomate laissée à l''air brunit et sèche au lieu de gratiner.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Enfourner à 210 °C sur la grille haute pendant quinze à vingt minutes, jusqu''à obtenir une surface dorée et boursouflée. Rester à proximité sur la fin : le fromage bascule très vite du doré au brûlé. Laisser reposer cinq minutes hors du four avant de servir à même le plat de cuisson.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-020-D2', 'recipe_family', 'Gratin de poireaux à la tomate',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-020-D2', 'missing_required_count', v_missing), 'open');
  END IF;

