  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Peler les pommes de terre, les rincer sous l''eau claire puis les débiter en cubes réguliers d''environ deux centimètres ; les maintenir dans un saladier d''eau froide le temps de préparer le reste.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Fendre les poireaux en deux sur la longueur, les laver feuille à feuille pour chasser la terre, puis les détailler en fines demi-rondelles en gardant surtout le blanc et le vert tendre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Faire mousser le beurre — avec l''huile d''olive si l''on veut une matière grasse plus stable — dans une cocotte à fond épais, y verser les poireaux et les laisser suer huit minutes à feu doux, sans jamais les laisser prendre couleur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Égoutter les cubes de pomme de terre, les mêler aux poireaux fondus, mouiller avec le bouillon de volaille bien chaud jusqu''à recouvrir les légumes, saler modérément et amener au frémissement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Couvrir et laisser cuire à petits bouillons vingt-cinq à trente minutes : la pointe d''un couteau doit traverser un cube de pomme de terre sans la moindre résistance.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Mixer le potage encore chaud jusqu''à une texture parfaitement lisse, puis le passer au chinois en foulant à la louche — servi froid, le moindre grain se sent, alors qu''il passerait inaperçu dans une soupe fumante. Incorporer la crème hors du feu, puis rectifier le sel et le poivre plus franchement qu''à chaud : le froid endort l''assaisonnement, ce qui semble juste à la casserole paraîtra fade au bol.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Filmer au contact, laisser tiédir puis réserver au moins quatre heures au réfrigérateur, une nuit si l''on peut. Fouetter vivement le velouté glacé juste avant de le verser en assiette creuse ou en bol rafraîchi : il se resserre en reposant et demande à être remis en mouvement pour retrouver sa coulée.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-022-D1', 'recipe_family', 'Vichyssoise',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-022-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-022-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-022-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('aed53eee88a4ae01f40f439983ba2ca0'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":2,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":2},"dominant_flavors":["poireau fondu","pomme de terre douce","crème lactée","bouillon de volaille"],"aroma_families":["allium doux","lacté","bouillon de volaille","beurre noisette"],"target_textures":["velouté lisse","nappant","sans fibre"],"signature_ingredients":["Poireau cru","Pomme de terre cuite","Crème fraîche liquide entière"],"identity_guardrails":["Le couple poireau + pomme de terre est le plat lui-même : sans l''un des deux, ce n''est plus un potage parmentier.","Les poireaux doivent suer sans coloration ; toute caraméliisation ou saisie brune fait basculer le potage vers une soupe rustique étrangère à l''identité du plat.","La texture doit rester un velouté entièrement mixé : laisser des morceaux entiers en ferait une soupe paysanne, pas un potage.","La crème s''ajoute hors du feu en fin de cuisson, jamais en début de mijotage."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Potage Parmentier aux croûtons et cerfeuil', 'potage parmentier aux croutons et cerfeuil', 'France', 'France',
     'meal', 'soupe', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Potage Parmentier aux croûtons et cerfeuil', 'Soupe de poireau et pomme de terre dans le bouillon, garnie de croûtons frits et de cerfeuil frais', ds.id, 'SRC-022-D2',
    'Myko', 'editorial', 4, 20, 35, 'facile',
    NULL, NULL,
    'B', 'candidate', '39c5b0b0e1b69b9f5b92b416b2a8469e',
    '{"sweet":2,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":2}'::jsonb, ARRAY['poireau fondu','pomme de terre douce','crème lactée','bouillon de volaille']::text[],
    ARRAY['allium doux','lacté','bouillon de volaille','beurre noisette']::text[], ARRAY['velouté lisse','nappant','sans fibre']::text[],
    ARRAY['Poireau cru','Pomme de terre cuite','Crème fraîche liquide entière']::text[], ARRAY['Le couple poireau + pomme de terre est le plat lui-même : sans l''un des deux, ce n''est plus un potage parmentier.','Les poireaux doivent suer sans coloration ; toute caraméliisation ou saisie brune fait basculer le potage vers une soupe rustique étrangère à l''identité du plat.','La texture doit rester un velouté entièrement mixé : laisser des morceaux entiers en ferait une soupe paysanne, pas un potage.','La crème s''ajoute hors du feu en fin de cuisson, jamais en début de mijotage.']::text[],
    ARRAY['suage','mijotage','mixage','friture']::text[], ARRAY[]::text[], ARRAY['lait']::text[],
    'Se garde trois jours au réfrigérateur entre 0 et 4 °C dans un contenant fermé ; réchauffer doucement sans faire bouillir pour éviter que la crème ne tranche. Pour la congélation, congeler la base mixée sans crème jusqu''à trois mois et n''incorporer la crème qu''au réchauffage : congelée crémée, elle se déphase et rend le velouté granuleux.', '{"fridge_hours":72,"eat_immediately":false,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-022'), '{"variant_label":"Couronner chaque assiette de croûtons frits égouttés sur papier absorbant et de quelques pluches de cerfeuil.","rationale":"Cent vingt grammes de pain de campagne frits et huit grammes de cerfeuil s''ajoutent au moment du service, et l''huile d''olive cesse d''être facultative pour devenir la friture, à quarante-cinq grammes. Le potage y gagne ce qui lui manquait — du croquant et une note anisée fraîche contre le velouté lisse — et de quoi tenir plus longtemps au corps. Le coût est net : le pain frit alourdit sensiblement la part, et la fenêtre de service se réduit à quelques minutes, les croûtons buvant le potage et retombant dès qu''ils y séjournent.","operations":[{"op":"add","form":"Pain de campagne","quantity":120,"unit":"g","role":"croûtons","optional":false},{"op":"add","form":"Cerfeuil frais","quantity":8,"unit":"g","role":"herbe de finition","optional":false},{"op":"set","form":"Huile d''olive vierge extra","quantity":45,"role":"friture","optional":false}],"steps":[{"op":"replace","n":3,"instruction":"Faire mousser le beurre doux seul dans une cocotte à fond épais — l''huile d''olive est ici réservée à la friture des croûtons —, y verser les poireaux et les laisser suer huit minutes à feu doux, sans jamais les laisser prendre couleur."},{"op":"replace","n":6,"instruction":"Mixer le potage encore chaud jusqu''à une texture veloutée, le passer au chinois pour une finesse parfaite, puis incorporer la crème hors du feu et rectifier en sel et poivre. Verser en assiette creuse, semer les croûtons au tout dernier moment et couronner de pluches de cerfeuil frais : posés d''avance, les croûtons boivent le potage et retombent, et le cerfeuil, s''il cuit, perd en quelques secondes son parfum d''anis."},{"op":"insert","after":5,"instruction":"Tailler le pain de campagne, rassis de préférence, en cubes d''un centimètre. Chauffer l''huile d''olive vierge extra dans une petite poêle jusqu''à ce qu''un cube y grésille aussitôt, puis frire les croûtons par poignées en les remuant sans arrêt deux à trois minutes, jusqu''à ce qu''ils dorent sur toutes leurs faces. Les débarrasser sur un papier absorbant et les saler tout de suite : le sel n''accroche que sur le gras encore chaud."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
