  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Passer le riz sous l''eau claire en le brassant à la main jusqu''à ce que l''eau ressorte limpide, puis le mettre dans une casserole avec une fois et demie son volume d''eau salée. Porter à frémissement, couvrir, baisser au minimum et laisser boire tout le liquide sans jamais soulever le couvercle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Laisser gonfler dix minutes hors du feu, toujours couvert, puis étaler le riz en couche mince sur un grand plat pour qu''il tiédisse et que les grains cessent de coller entre eux. Un riz refroidi tient le sauté ; un riz brûlant se transforme en purée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pendant ce temps, ébouillanter les petits pois deux minutes puis les égoutter et les rafraîchir sous l''eau froide. Tailler l''oignon en petits dés, hacher l''ail au couteau et débiter la carotte en brunoise fine. Éponger les crevettes décortiquées une à une dans un linge propre : mouillées, elles bouillent au lieu de saisir et ne prennent aucune couleur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Fouetter les œufs avec une pincée de sel et un tour de moulin. Les verser dans une poêle chaude où le beurre a juste fondu, incliner le manche pour étaler une galette très mince, la décoller dès qu''elle est prise, la faire glisser sur une planche, la rouler sur elle-même et la trancher en fines lanières.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Faire fumer l''huile d''olive dans un wok ou une grande sauteuse et y jeter les crevettes en une seule couche. Les laisser trente secondes sans y toucher, le temps qu''elles rosissent et se rétractent, les retourner d''un coup de spatule puis les débarrasser aussitôt dans une assiette : leur cuisson s''achèvera à la chaleur du riz.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Remettre le wok sur le feu vif et jeter dans l''huile restée au fond l''oignon, l''ail et la carotte. Les remuer sans arrêt deux à trois minutes : ils doivent s''assouplir en gardant leur teinte claire, sans jamais roussir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Ajouter les petits pois et sauter une minute pour les enrober de matière grasse, puis verser le riz refroidi en l''écrasant du dos de la spatule pour séparer les paquets de grains. Étaler le tout contre les parois chaudes et laisser accrocher quelques secondes entre deux mouvements.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Remettre les crevettes et le jus qu''elles ont rendu dans l''assiette, disperser les lanières d''omelette, arroser de sauce soja versée en pluie sur le bord brûlant du wok, ajouter l''huile de sésame hors du feu, goûter puis rectifier en sel et en poivre. Sauter une dernière minute, le temps de réchauffer les crevettes sans les recuire, et envoyer immédiatement.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-023-D1', 'recipe_family', 'Riz cantonais aux crevettes',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-023-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-023-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-023-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('fab856a5f30b4ac441e4b7872def092f'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":2,"freshness":1,"intensity":2},"dominant_flavors":["salé","umami","douceur végétale"],"aroma_families":["alliacé","grillé","céréalier"],"target_textures":["grains détachés","moelleux","lanières fondantes"],"signature_ingredients":["Riz cru","Œuf cru","Crevette crue décortiquée","Petit pois surgelé"],"identity_guardrails":["L''œuf doit être cuit à part en omelette fine puis retaillé en lanières : des œufs brouillés directement dans le riz donnent un autre plat.","Le riz doit être cuit à l''avance et refroidi avant d''être sauté ; un riz encore chaud colle et fait perdre la texture en grains détachés qui définit le plat.","Le trio riz, œuf et petit pois est présent dans les sept sources du dossier : retirer l''un des trois fait sortir de l''identité du riz cantonais.","Le sauté se fait sur feu vif et court, jamais en mijotage : le plat n''est pas un riz cuisiné en sauce."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Riz cantonais végétarien', 'riz cantonais vegetarien', 'France', 'France',
     'meal', 'plat sauté', 'documented_variation', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Riz cantonais végétarien', 'Riz sauté avec œufs brouillés, carottes, petits pois et sauce soja, sans protéine animale', ds.id, 'SRC-023-D2',
    'Myko', 'editorial', 4, 15, 20, 'facile',
    NULL, NULL,
    'B', 'candidate', '5a9124f8a64fbf60a4e469e74bb5433a',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":2,"freshness":1,"intensity":2}'::jsonb, ARRAY['salé','umami','douceur végétale']::text[],
    ARRAY['alliacé','grillé','céréalier']::text[], ARRAY['grains détachés','moelleux','lanières fondantes']::text[],
    ARRAY['Riz cru','Œuf cru','Petit pois surgelé']::text[], ARRAY['L''œuf doit être cuit à part en omelette fine puis retaillé en lanières : des œufs brouillés directement dans le riz donnent un autre plat.','Le riz doit être cuit à l''avance et refroidi avant d''être sauté ; un riz encore chaud colle et fait perdre la texture en grains détachés qui définit le plat.','Le trio riz, œuf et petit pois est présent dans les sept sources du dossier : retirer l''un des trois fait sortir de l''identité du riz cantonais.','Le sauté se fait sur feu vif et court, jamais en mijotage : le plat n''est pas un riz cuisiné en sauce.']::text[],
    ARRAY['saisie','blanchiment']::text[], ARRAY[]::text[], ARRAY['œuf','lait','gluten','soja','sésame']::text[],
    'Se garde 2 jours au réfrigérateur entre 0 et 4 °C dans une boîte hermétique, à refroidir rapidement après cuisson car le riz cuit tiède est un terrain favorable à Bacillus cereus. Réchauffer à la poêle bien chaude, jamais tiède. La congélation est possible 1 mois mais dégrade nettement la texture : les petits pois rendent de l''eau et l''omelette devient caoutchouteuse — décongeler au réfrigérateur puis sauter à feu vif.', '{"fridge_hours":48,"eat_immediately":false,"freezable":true,"freezer_months":1,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-023'), '{"variant_label":"Version végétarienne : supprimer le jambon, doubler la dose de petit pois et de carotte, et relever d''un trait supplémentaire de sauce soja.","rationale":"Sans jambon, le plat perd sa principale source de sel et une bonne part de son umami ; les petits pois et la carotte doublés compensent en volume, la sauce soja plus généreuse en goût. Le riz devient plus sucré et plus végétal, et un peu moins protéiné puisque l''œuf reste seul à ce poste. La carotte cesse d''être facultative : c''est elle qui porte désormais la mâche, et la sauce soja aussi devient indispensable.","operations":[{"op":"remove","form":"Jambon blanc cuit"},{"op":"scale","form":"Petit pois surgelé","factor":2},{"op":"set","form":"Carotte crue","quantity":160,"role":"légume","optional":false},{"op":"set","form":"Sauce soja","quantity":75,"role":"assaisonnement","optional":false}],"steps":[{"op":"replace","n":3,"instruction":"Pendant ce temps, ébouillanter les petits pois deux minutes puis les égoutter et les rafraîchir sous l''eau froide : ils sont ici deux fois plus nombreux, il faut les étaler pour qu''ils refroidissent vite. Tailler l''oignon en petits dés, hacher l''ail au couteau et débiter la carotte en brunoise fine, menue malgré sa quantité doublée, sans quoi elle resterait crue quand le reste sera prêt."},{"op":"replace","n":6,"instruction":"Ajouter les petits pois et sauter une minute pour les enrober de matière grasse, puis verser le riz refroidi en l''écrasant du dos de la spatule pour séparer les paquets de grains. Étaler le tout contre les parois chaudes et laisser accrocher franchement entre deux mouvements : privé de garniture de viande, c''est de cette accroche que le plat tire son goût de grillé."},{"op":"replace","n":7,"instruction":"Disperser les lanières d''omelette, arroser de sauce soja versée en pluie sur le bord brûlant du wok — la dose est plus large qu''à l''ordinaire, elle apporte le sel et le fond salé que la charcuterie donnait —, ajouter l''huile de sésame hors du feu, goûter puis rectifier en sel et en poivre. Sauter une dernière minute et envoyer immédiatement, tant que la vapeur monte."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
