  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Passer le riz sous l''eau claire en le brassant à la main jusqu''à ce que l''eau ressorte limpide, puis le mettre dans une casserole avec une fois et demie son volume d''eau salée. Porter à frémissement, couvrir, baisser au minimum et laisser boire tout le liquide sans jamais soulever le couvercle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Laisser gonfler dix minutes hors du feu, toujours couvert, puis étaler le riz en couche mince sur un grand plat pour qu''il tiédisse et que les grains cessent de coller entre eux. Un riz refroidi tient le sauté ; un riz brûlant se transforme en purée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pendant ce temps, ébouillanter les petits pois deux minutes puis les égoutter et les rafraîchir sous l''eau froide. Tailler l''oignon en petits dés, hacher l''ail au couteau et débiter la carotte en brunoise fine.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Fouetter les œufs avec une pincée de sel et un tour de moulin. Les verser dans une poêle chaude où le beurre a juste fondu, incliner le manche pour étaler une galette très mince, la décoller dès qu''elle est prise, la faire glisser sur une planche, la rouler sur elle-même et la trancher en fines lanières.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Jeter les lardons fumés dans le wok encore froid et les faire fondre à feu moyen quatre à cinq bonnes minutes, jusqu''à ce qu''ils blondissent et que leur gras coule au fond : démarrés à froid, ils le rendent au lieu de le garder, mais il faut leur laisser ce temps-là. Verser alors le filet d''huile d''olive, monter le feu, ajouter l''oignon, l''ail et la carotte et les remuer sans arrêt deux à trois minutes, sans jamais les laisser roussir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Ajouter les petits pois et sauter une minute pour les enrober du gras fumé, puis verser le riz refroidi en l''écrasant du dos de la spatule pour séparer les paquets de grains. Étaler le tout contre les parois chaudes et laisser accrocher quelques secondes entre deux mouvements.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Disperser les lanières d''omelette, arroser de sauce soja versée en pluie sur le bord brûlant du wok, mais d''une main plus retenue qu''à l''ordinaire : le lard a déjà salé le riz. Ajouter l''huile de sésame hors du feu, goûter puis rectifier en poivre et en sel seulement si c''est nécessaire. Sauter une dernière minute et envoyer immédiatement, tant que la vapeur monte.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-023-D3', 'recipe_family', 'Riz cantonais aux lardons fumés',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-023-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-023-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-023-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('ecd2abdf0886a40516fd1c2baee910cc'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3},"dominant_flavors":["salé","umami","fumé"],"aroma_families":["fumé","alliacé","grillé","céréalier"],"target_textures":["grains détachés","lardons dorés","lanières fondantes"],"signature_ingredients":["Riz cru","Œuf cru","Lardon fumé cru","Petit pois surgelé"],"identity_guardrails":["L''œuf doit être cuit à part en omelette fine puis retaillé en lanières : des œufs brouillés directement dans le riz donnent un autre plat.","Le riz doit être cuit à l''avance et refroidi avant d''être sauté ; un riz encore chaud colle et fait perdre la texture en grains détachés qui définit le plat.","Les lardons partent dans un wok froid et fondent avant l''huile : jetés dans une matière grasse déjà brûlante, ils saisissent sans rien rendre et le riz n''est jamais fumé.","Le sauté se fait sur feu vif et court, jamais en mijotage : le plat n''est pas un riz cuisiné en sauce."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Riz sauté beurré aux œufs brouillés', 'riz saute beurre aux oeufs brouilles', 'France', 'France',
     'meal', 'plat sauté', 'documented_variation', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Riz sauté beurré aux œufs brouillés', 'Riz sauté au beurre avec œufs brouillés et jambon blanc, sans sauce soja', ds.id, 'SRC-023-D4',
    'Myko', 'editorial', 4, 15, 20, 'facile',
    NULL, NULL,
    'B', 'candidate', '5de6b1b156d9f6c9447c7c2accef3b3f',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":2}'::jsonb, ARRAY['salé','umami','beurre frais']::text[],
    ARRAY['alliacé','grillé','lacté','céréalier']::text[], ARRAY['grains détachés','œufs en caillots crémeux','moelleux']::text[],
    ARRAY['Riz cru','Œuf cru','Jambon blanc cuit','Petit pois surgelé']::text[], ARRAY['Les œufs sont brouillés au beurre à part et réincorporés en fin de sauté : versés crus sur le riz, ils l''enroberaient d''une pellicule caillée au lieu de rester en caillots.','Le riz doit être cuit à l''avance et refroidi avant d''être sauté ; un riz encore chaud colle et fait perdre la texture en grains détachés qui définit le plat.','Le trio riz, œuf et petit pois reste intouchable : retirer l''un des trois fait sortir de l''identité du riz sauté cantonais.','Le sauté se fait sur feu vif et court, jamais en mijotage : le beurre arrondit le plat, il ne le transforme pas en riz crémeux.']::text[],
    ARRAY['saisie','blanchiment','brouillage rapide']::text[], ARRAY[]::text[], ARRAY['œuf','lait','gluten','soja','sésame']::text[],
    'Se garde 2 jours au réfrigérateur entre 0 et 4 °C dans une boîte hermétique, à refroidir rapidement après cuisson car le riz cuit tiède est un terrain favorable à Bacillus cereus. Réchauffer à la poêle bien chaude, jamais tiède. La congélation est possible 1 mois mais dégrade nettement la texture : les petits pois rendent de l''eau et l''omelette devient caoutchouteuse — décongeler au réfrigérateur puis sauter à feu vif.', '{"fridge_hours":48,"eat_immediately":false,"freezable":true,"freezer_months":1,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-023'), '{"variant_label":"Riz sauté beurré à la façon de chefsimon.com : brouiller les œufs à la spatule dans le beurre au lieu de dresser une omelette, et les réincorporer en fin de sauté.","rationale":"Brouillés au beurre plutôt que dressés en omelette, les œufs cessent d''être des lanières identifiables pour devenir des caillots crémeux répartis dans tout le riz. Le beurre passe de secours facultatif à matière grasse assumée : le sauté s''arrondit et s''éloigne du wok pour se rapprocher de la poêle. La texture ne pardonne pas l''attente — des œufs trop cuits ou réincorporés trop tôt se dessèchent en granules et le riz redevient sec.","operations":[{"op":"set","form":"Beurre doux","quantity":30,"role":"matière grasse","optional":false}],"steps":[{"op":"replace","n":4,"instruction":"Fouetter les œufs avec une pincée de sel et un tour de moulin. Faire mousser le beurre dans une poêle à feu doux sans le laisser colorer, y verser les œufs et les travailler sans arrêt à la spatule en ramenant les bords vers le centre : ils doivent prendre en petits caillots brillants. Les débarrasser dans un bol dès qu''ils cessent de couler, la chaleur du riz finira le travail."},{"op":"replace","n":7,"instruction":"Verser les œufs brouillés sur le riz brûlant et les défaire en gros morceaux d''un geste bref, sans les écraser. Arroser de sauce soja versée en pluie sur le bord du wok, ajouter l''huile de sésame hors du feu, goûter puis rectifier en sel et en poivre. Sauter trente secondes à peine et envoyer immédiatement : au-delà, les œufs rendent leur eau et se raidissent."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
