     jsonb_build_object('recipe_code', 'SRC-023-D4', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-023-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('5de6b1b156d9f6c9447c7c2accef3b3f'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":2},"dominant_flavors":["salé","umami","beurre frais"],"aroma_families":["alliacé","grillé","lacté","céréalier"],"target_textures":["grains détachés","œufs en caillots crémeux","moelleux"],"signature_ingredients":["Riz cru","Œuf cru","Jambon blanc cuit","Petit pois surgelé"],"identity_guardrails":["Les œufs sont brouillés au beurre à part et réincorporés en fin de sauté : versés crus sur le riz, ils l''enroberaient d''une pellicule caillée au lieu de rester en caillots.","Le riz doit être cuit à l''avance et refroidi avant d''être sauté ; un riz encore chaud colle et fait perdre la texture en grains détachés qui définit le plat.","Le trio riz, œuf et petit pois reste intouchable : retirer l''un des trois fait sortir de l''identité du riz sauté cantonais.","Le sauté se fait sur feu vif et court, jamais en mijotage : le beurre arrondit le plat, il ne le transforme pas en riz crémeux."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
