  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Déposer les pommes de terre entières et non pelées dans un grand volume d''eau salée, porter à petits bouillons et laisser cuire 20 à 25 minutes selon le calibre : la lame d''un couteau doit entrer sans résistance mais la chair rester ferme. Égoutter, passer sous l''eau froide, peler dès que possible et détailler en dés d''environ un centimètre et demi.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'En parallèle, plonger les œufs dans une casserole d''eau frémissante et compter 10 minutes pour obtenir des jaunes bien pris. Les transvaser aussitôt dans un bol d''eau glacée : le choc thermique décolle la coquille et facilite l''écalage. Écaler, puis couper chaque œuf en quartiers ou en gros morceaux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Rincer les tomates, retirer le pédoncule, les ouvrir en deux et évacuer graines et jus avec une petite cuillère pour éviter que la salade ne rende de l''eau. Tailler la chair en cubes réguliers. Débiter le jambon en dés de même taille, émincer les cornichons en fines rondelles et ciseler finement le persil.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Sortir le jaune d''œuf cru et l''huile un quart d''heure à l''avance : une émulsion ne prend qu''avec des éléments à la même température. Dans un bol, délayer la moutarde de Dijon avec une pincée de sel, ajouter le jaune et fouetter quelques secondes, puis verser l''huile d''olive vierge extra goutte à goutte pour commencer, en filet mince ensuite, sans jamais cesser de battre : la sauce blanchit, épaissit et finit par tenir au fouet. La détendre alors avec le vinaigre de vin rouge et la crème fraîche, poivrer et goûter — elle doit paraître franchement relevée, car les pommes de terre en absorberont une bonne part.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Réunir dans un saladier les dés de pommes de terre, de tomate et de jambon, les rondelles de cornichon et le persil. Verser la sauce, puis remuer à la spatule en soulevant la masse par en dessous, sans écraser, jusqu''à ce que chaque élément soit enrobé. Ajouter les œufs durs en dernier et les mêler d''un geste léger pour garder les morceaux entiers.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Filmer le saladier et le placer au réfrigérateur au moins une heure, idéalement deux : ce repos permet à la pomme de terre de s''imprégner de la sauce et de lier l''ensemble. Rectifier le sel, le poivre et l''acidité juste avant de servir, bien frais.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-025-D1', 'recipe_family', 'Salade piémontaise à la mayonnaise maison',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-025-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-025-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-025-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('f3cf2d173ec732b12468b302edbe3771'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":3,"acidic":3,"bitter":0,"umami":2,"heat":0,"pungency":2,"richness":4,"freshness":3,"intensity":3},"dominant_flavors":["acidulé","salé","moutardé","huile d''olive"],"aroma_families":["vinaigré","herbacé","végétal frais"],"target_textures":["fondant","croquant","crémeux"],"signature_ingredients":["Pomme de terre cuite","Cornichon au vinaigre","Œuf dur"],"identity_guardrails":["Sans dés de pomme de terre cuite refroidis, ce n''est plus une salade piémontaise mais une simple salade de crudités.","La sauce doit rester une émulsion épaisse montée à l''huile : réduite à une vinaigrette moutardée, le plat perd son onctuosité caractéristique.","L''acidité vive apportée par les cornichons et le vinaigre est constitutive du plat ; sans elle, l''ensemble devient plat et gras.","Le plat se sert froid après repos au réfrigérateur, et le jour même : la sauce au jaune cru ne se garde pas comme celle du commerce."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Salade piémontaise à la crème moutardée', 'salade piemontaise a la creme moutardee', 'France', 'France',
     'meal', 'salade composée', 'documented_variation', 'tangy_creamy',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Salade piémontaise à la crème moutardée', 'Pommes de terre, jambon blanc, œufs durs et cornichons liés à une mayonnaise allégée à la crème', ds.id, 'SRC-025-D2',
    'Myko', 'editorial', 4, 25, 25, 'facile',
    NULL, NULL,
    'B', 'candidate', '2e6b5659411504b1ca92ec4d3827c930',
    '{"sweet":1,"salty":3,"acidic":3,"bitter":0,"umami":2,"heat":0,"pungency":3,"richness":3,"freshness":3,"intensity":3}'::jsonb, ARRAY['acidulé','moutardé','lacté','salé']::text[],
    ARRAY['vinaigré','herbacé','lacté']::text[], ARRAY['fondant','croquant','sauce fluide']::text[],
    ARRAY['Pomme de terre cuite','Mayonnaise','Cornichon au vinaigre','Œuf dur']::text[], ARRAY['Sans dés de pomme de terre cuite refroidis, ce n''est plus une salade piémontaise mais une simple salade de crudités.','La sauce s''allège mais reste une sauce blanche liée : tombée en vinaigrette, elle glisserait au fond du saladier et laisserait la pomme de terre nue.','L''acidité vive apportée par les cornichons et le vinaigre est constitutive du plat ; sans elle, l''ensemble devient plat et gras.','Le plat se sert froid après repos au réfrigérateur : servi tiède, il n''est pas reconnaissable.']::text[],
    ARRAY['pochage','émulsion']::text[], ARRAY[]::text[], ARRAY['œuf','moutarde','lait','sulfites']::text[],
    'Se conserve 48 heures maximum au réfrigérateur entre 0 et 4 °C, dans un contenant hermétique, en raison de la mayonnaise et de l''œuf dur. Sortir 10 minutes avant de servir. Ne se congèle pas : la mayonnaise se déphase et la pomme de terre devient farineuse et granuleuse à la décongélation.', '{"fridge_hours":48,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":true,"source":"manual"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-025'), '{"variant_label":"Version allégée : remplacer une partie de la mayonnaise par de la crème fraîche liquide entière relevée de moutarde, pour une sauce plus fluide et moins riche.","rationale":"La crème liquide relevée de moutarde prend la moitié du travail de la mayonnaise, dont la dose est plus que divisée par deux et qui n''est plus là que pour donner du corps. La sauce devient fluide, plus acidulée et sensiblement moins grasse, mais elle nappe moins bien : elle glisse sur les dés au lieu de les enrober et la salade rend un peu plus d''eau au repos. La moutarde, presque doublée, passe au premier plan du goût.","operations":[{"op":"set","form":"Mayonnaise","quantity":60,"role":"sauce"},{"op":"substitute","form":"Crème fraîche épaisse","with":"Crème fraîche liquide entière","quantity":100,"unit":"g","role":"liant","optional":false},{"op":"set","form":"Moutarde de Dijon","quantity":20,"role":"condiment"}],"steps":[{"op":"replace","n":4,"instruction":"Dans un bol, délayer la moutarde de Dijon avec le vinaigre, puis fouetter la crème fraîche liquide avec elle jusqu''à ce qu''elle épaississe légèrement — la moutarde suffit à lui donner du corps si l''on bat vivement. Incorporer la mayonnaise en dernier : elle ne sert plus qu''à tenir la sauce. Saler, poivrer, goûter : elle doit paraître franchement relevée et rester assez fluide pour couler entre les dés, car les pommes de terre en absorberont une bonne part."},{"op":"replace","n":6,"instruction":"Filmer le saladier et le placer au réfrigérateur au moins une heure, idéalement deux : ce repos permet à la pomme de terre de boire la sauce, qui est ici plus liquide et se laisse absorber plus vite. Remuer une fois à mi-repos pour reprendre ce qui a coulé au fond, puis rectifier le sel, le poivre et l''acidité juste avant de servir, bien frais."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

