  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Détailler l''épaule de porc en lanières de la largeur d''un doigt, en tranchant en travers de la fibre : coupée dans le sens des fibres, une viande saisie vite reste filandreuse. Peler et émincer l''oignon jaune en fines lamelles, tailler la carotte en bâtonnets courts.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire fumer l''huile d''olive dans un wok ou une grande sauteuse et y jeter la moitié des lanières de porc en une seule couche, sans les tasser. Les laisser une minute sans y toucher, puis les retourner jusqu''à ce qu''elles soient dorées de partout, et les débarrasser dans une assiette avant de recommencer avec le reste : une poêlée surchargée rend son eau et bout au lieu de colorer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Remettre le wok vide sur le feu vif, y verser l''oignon et la carotte et les remuer deux à trois minutes seulement : ils doivent s''assouplir et prendre quelques taches dorées en gardant du mordant, loin de la fondue lente que demandait le braisé.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ajouter les lardons fumés et les laisser crépiter deux minutes en remuant, le temps qu''ils libèrent leur gras et en parfument les légumes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser l''eau et gratter aussitôt le fond à la cuillère en bois pour décoller les sucs caramélisés. Poivrer, puis laisser bouillir vivement deux à trois minutes jusqu''à ce qu''il ne reste qu''un fond de jus sirupeux : le mouillement est ici trois fois plus faible, il sert à déglacer et non à mijoter.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Remettre le porc et le jus qu''il a rendu dans l''assiette, et le rouler une minute dans ce fond de sauce pour l''enrober et le réchauffer. La viande est déjà cuite : prolongée, elle se contracte et sèche, là où l''épaule braisée gagnait à s''attendrir une heure.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Jeter les pruneaux dénoyautés à la toute fin et les remuer trente secondes, le temps qu''ils tiédissent et lâchent un peu de leur sucre dans le jus. Ils restent fermes et entiers, sans le moelleux gonflé que seule donne la cuisson longue.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Rectifier le poivre et servir aussitôt, tant que les légumes croquent et que la sauce brille. Ce sauté n''attend pas : gardé au chaud, il rend son eau et perd précisément ce qui le distingue du braisé.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-026-D1', 'recipe_family', 'Sauté minute de porc aux pruneaux',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-026-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-026-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-026-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('ba269a57c6fea5f15121af10768d73f0'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":3,"salty":3,"acidic":1,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":3},"dominant_flavors":["sucré du fruit sec","porc saisi","fumé du lard"],"aroma_families":["fruit sec","fumé","viande grillée"],"target_textures":["lanières de porc juste saisies","pruneau ferme et tiède","légumes croquants","jus court et sirupeux"],"signature_ingredients":["Épaule de porc crue","Pruneau dénoyauté","Lardon fumé cru"],"identity_guardrails":["Sans pruneau dénoyauté, il ne reste qu''un sauté de porc ordinaire : c''est le fruit sec qui porte le contraste sucré-salé du plat.","La viande est saisie en deux fournées et jamais entassée : c''est la seule coloration que cette version courte obtiendra, faute de cuisson longue.","La cuisson reste vive et à découvert : dix minutes sous un couvercle raidissent la lanière sans jamais la rendre fondante, et le plat n''est alors ni un sauté ni un braisé.","Le mouillement se limite à un fond d''eau destiné au déglaçage : noyée, la poêlée redevient un ragoût manqué."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Porc aux pruneaux à la cocotte', 'porc aux pruneaux a la cocotte', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Porc aux pruneaux à la cocotte', 'Épaule de porc mijotée en cocotte avec des pruneaux', ds.id, 'SRC-026-D2',
    'Myko', 'editorial', 4, 20, 90, 'facile',
    NULL, NULL,
    'B', 'candidate', '2fa9ce3063dc4538cc55dc9444c5d33a',
    '{"sweet":3,"salty":2,"acidic":1,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":2}'::jsonb, ARRAY['sucré du fruit sec','porc caramélisé','oignon confit']::text[],
    ARRAY['fruit sec','viande rôtie','légume fondu']::text[], ARRAY['viande fondante à la fourchette','pruneau moelleux et gonflé','sauce nappante']::text[],
    ARRAY['Épaule de porc crue','Pruneau dénoyauté']::text[], ARRAY['Sans pruneau dénoyauté, il ne reste qu''un sauté de porc ordinaire : c''est le fruit sec qui porte le contraste sucré-salé du plat.','La viande doit être saisie en deux fournées et poussée jusqu''au brun : c''est elle seule qui donne au jus la profondeur que la garniture fumée apportait.','La cuisson reste longue et à couvert : un passage rapide à la poêle ne rend pas l''épaule fondante et ne laisse pas les pruneaux parfumer le jus.','Le mouillement se limite à un fond d''eau, pas à un bain : la sauce doit finir réduite et nappante, jamais aqueuse.']::text[],
    ARRAY['saisie','déglaçage','mijotage','réduction']::text[], ARRAY[]::text[], ARRAY['sulfites']::text[],
    'Se conserve 3 jours au réfrigérateur entre 0 et 4 °C dans un récipient fermé, et gagne même en goût réchauffé le lendemain à feu doux avec une cuillère d''eau. Le plat se congèle très bien 3 mois : la viande et la sauce supportent la décongélation, les pruneaux ressortent seulement un peu plus fondus.', '{"fridge_hours":72,"eat_immediately":false,"freezable":true,"freezer_months":3,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-026'), '{"variant_label":"Sans lardons : doubler la saisie de la viande pour compenser la profondeur fumée manquante.","rationale":"Retirer les lardons ôte au plat sa colonne fumée et l''essentiel de son sel : la saisie menée en deux fournées et poussée jusqu''au brun redonne du fond au jus, mais ne remplace pas le fumé, qui disparaît vraiment. Il faut désormais saler la cocotte, ce que la recette d''origine n''avait pas à faire, et juger l''assaisonnement une fois le jus réduit. Le résultat est plus maigre, plus franchement porc et pruneau, moins complexe aussi.","operations":[{"op":"remove","form":"Lardon fumé cru"},{"op":"add","form":"Sel fin","quantity":4,"unit":"g","role":"assaisonnement","optional":false}],"steps":[{"op":"replace","n":3,"instruction":"Débarrasser l''oignon et la carotte dans une assiette : la saisie se mène ici en deux fournées, et des légumes laissés sur les bords d''une cocotte brûlante noirciraient pendant que la seconde colore, donnant au jus une amertume dont il ne se relève pas. Monter le feu et déposer la moitié des cubes de porc à plat, sans qu''ils se touchent. Les laisser dorer sans les bouger, les retourner face par face jusqu''à ce qu''ils soient colorés partout et presque bruns, les réserver, puis recommencer avec le reste : privée de garniture fumée, la cocotte n''a plus que cette croûte caramélisée pour donner du fond à son jus, et une viande entassée bout au lieu de saisir. Remettre alors dans la cocotte l''oignon, la carotte, toute la viande et les sucs qu''elle a rendus."},{"op":"remove","n":4},{"op":"replace","n":5,"instruction":"Verser l''eau et gratter aussitôt le fond à la cuillère en bois pour décoller les sucs caramélisés. Ajouter le sel fin et poivrer — il n''y a plus de charcuterie pour saler le jus à la place du cuisinier —, porter à petits bouillons puis couvrir et baisser au minimum."},{"op":"replace","n":8,"instruction":"Retirer le couvercle pour les dix dernières minutes et laisser le liquide réduire jusqu''à une sauce brillante qui nappe la cuillère. Mélanger avec précaution, goûter et rectifier en sel et en poivre seulement à ce moment : la réduction concentre l''assaisonnement, et un jus salé trop tôt devient immangeable une fois réduit."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
