  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Portez une petite casserole d''eau à frémissement, immergez-y les olives vertes et noires une quinzaine de secondes pour adoucir la saumure, égouttez-les et gardez-les de côté.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chauffez l''huile d''olive dans une cocotte à fond épais et colorez les cubes de veau par petites poignées, sans jamais surcharger le fond, jusqu''à une croûte ambrée sur toutes les faces ; débarrassez la viande et faites rendre leur gras aux lardons au même endroit.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Baissez le feu, jetez l''oignon finement émincé et la carotte en rondelles dans la graisse de cuisson, laissez-les fondre sans brunir, ajoutez l''ail écrasé puis le concentré de tomate et tournez deux minutes pour qu''il perde son mordant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Mouillez avec le vin blanc en raclant les sucs collés au fond à la spatule, laissez-le réduire de moitié, remettez la viande et les lardons, versez l''eau à hauteur, parsemez de thym et de romarin, salez et poivrez.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Couvrez et maintenez un frémissement à peine perceptible pendant deux heures pleines, en remuant délicatement de loin en loin pour que rien n''attache. C''est ce long tirage qui fait descendre le fumé de la poitrine dans la sauce au lieu de le laisser flotter en surface, et qui amène la viande au point où elle se défait à la cuillère.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Ajoutez les olives égouttées, retirez le couvercle et prolongez trente minutes : la viande doit céder sous la fourchette et la sauce napper le dos d''une cuillère. Goûtez et rectifiez le sel en tenant compte des olives avant d''envoyer à table.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-027-D1', 'recipe_family', 'Sauté de veau à la corse',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-027-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-027-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-027-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('89b7034ac48a419d2a95ab7bc0b03b8f'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":3,"acidic":2,"bitter":2,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3},"dominant_flavors":["olive saumurée","veau braisé","ail fondu","vin blanc réduit"],"aroma_families":["herbacé méditerranéen","oignon compoté","tomate concentrée"],"target_textures":["viande fondante","sauce nappante","olive charnue"],"signature_ingredients":["Épaule de veau crue","Olive verte dénoyautée","Olive noire"],"identity_guardrails":["Les olives sont ajoutées en fin de mijotage et jamais dès le départ : cuites trop longtemps elles rendent le plat amer et perdent leur mâche.","Sans veau en gros cubes saisis puis braisés dans leur propre jus, ce n''est plus un sauté de veau mais un simple ragoût.","La sauce reste courte et liée par la farine de singeage, sans crème ni liaison finale."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Sauté de veau aux olives et au citron', 'saute de veau aux olives et au citron', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Sauté de veau aux olives et au citron', 'Veau braisé aux olives vertes et noires avec un zeste de citron en finition', ds.id, 'SRC-027-D2',
    'Myko', 'editorial', 4, 25, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', 'c4ad29eb85d26029c93078e89be691ce',
    '{"sweet":1,"salty":3,"acidic":2,"bitter":2,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3}'::jsonb, ARRAY['olive saumurée','veau braisé','ail fondu','vin blanc réduit']::text[],
    ARRAY['herbacé méditerranéen','oignon compoté','tomate concentrée']::text[], ARRAY['viande fondante','sauce nappante','olive charnue']::text[],
    ARRAY['Épaule de veau crue','Olive verte dénoyautée','Olive noire']::text[], ARRAY['Les olives sont ajoutées en fin de mijotage et jamais dès le départ : cuites trop longtemps elles rendent le plat amer et perdent leur mâche.','Sans veau en gros cubes saisis puis braisés dans leur propre jus, ce n''est plus un sauté de veau mais un simple ragoût.','La sauce reste courte et liée par la farine de singeage, sans crème ni liaison finale.']::text[],
    ARRAY['blanchiment','saisie','déglaçage','mijotage','réduction']::text[], ARRAY[]::text[], ARRAY['gluten','sulfites']::text[],
    'Se garde deux jours au réfrigérateur entre 0 et 4 °C dans un récipient hermétique, mais à la différence du sauté en cubes il ne gagne rien à attendre : les tranches minces se resserrent au réchauffage et l''écorce du citron, laissée dans la sauce, y pousse son amertume d''un jour sur l''autre. Retirer les rondelles avant de mettre au froid. La congélation est déconseillée pour les mêmes raisons.', '{"fridge_hours":48,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-027'), '{"variant_label":"Version au citron : ajouter des rondelles de citron avec les olives et réduire la cuisson à trente minutes en utilisant des tranches fines de veau plutôt que des cubes.","rationale":"Taillé en tranches fines, le veau cuit en une demi-heure au lieu de deux : la fibre n''a pas le temps de se défaire, la viande reste ferme et la sauce, moins longuement tirée, nappe moins. Les rondelles de citron cuites avec leur écorce apportent une amertume et une acidité franches qui recouvrent en partie le fond de tomate. Le plat gagne en vivacité ce qu''il perd en fondant, et supporte mal d''être réchauffé.","operations":[{"op":"add","form":"Citron jaune frais","quantity":120,"unit":"g","role":"acidifiant","optional":false}],"steps":[{"op":"replace","n":1,"instruction":"Parez l''épaule de veau et détaillez-la en tranches fines de moins d''un centimètre, la lame en travers de la fibre pour qu''elles ne se rétractent pas à la chaleur, puis farinez-les d''une face et de l''autre et secouez-les pour ne garder qu''un voile mince."},{"op":"replace","n":3,"instruction":"Chauffez l''huile d''olive dans une cocotte à fond épais et saisissez les tranches de veau à plat, trois ou quatre à la fois, une minute par face à peine : plus minces que des cubes, elles se dessèchent dès qu''on cherche la croûte ambrée ; débarrassez la viande et faites rendre leur gras aux lardons au même endroit."},{"op":"replace","n":6,"instruction":"Couvrez et maintenez un frémissement à peine perceptible vingt minutes seulement, le temps que les tranches s''attendrissent sans se défiler en filaments."},{"op":"replace","n":7,"instruction":"Ajoutez les olives égouttées et le citron débité en rondelles très fines, écorce comprise, retirez le couvercle et prolongez dix minutes, pas davantage : au-delà, la peau du citron vire à l''amer et ne revient plus. Goûtez et rectifiez le sel en tenant compte des olives et de l''acidité apportée par les rondelles avant d''envoyer à table."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
