DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Socca au poivre du moulin', 'socca au poivre du moulin', 'France', 'France',
     'meal', 'galette', 'documented_variation', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Socca au poivre du moulin', 'Galette de pois chiche à l''huile d''olive, assaisonnée généreusement au poivre noir du moulin', ds.id, 'SRC-028-D1',
    'Myko', 'editorial', 4, 15, 15, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '718a89f5906f2b41113185f85c52137d',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":2,"heat":0,"pungency":3,"richness":3,"freshness":1,"intensity":3}'::jsonb, ARRAY['pois chiche torréfié','huile d''olive','poivre']::text[],
    ARRAY['légumineuse grillée','fruité olive','notes fumées de croûte']::text[], ARRAY['croûte dorée et craquante','cœur souple et fondant','bords fins presque brûlés']::text[],
    ARRAY['Farine de pois chiche','Huile d''olive vierge extra']::text[], ARRAY['Sans farine de pois chiche, ce n''est plus une socca : aucune autre farine ne peut s''y substituer sans détruire le plat.','Sans cuisson à chaleur maximale finie sous le gril, le contraste entre croûte tachée de brun et intérieur moelleux disparaît et la galette devient une simple crêpe pâle.','Sans huile d''olive généreuse dans la pâte et sur la plaque brûlante, la socca perd son parfum et sa surface craquante.','Sans étalement très fin, de deux à trois millimètres, la galette cuit en épaisseur et perd sa texture caractéristique.']::text[],
    ARRAY['rôtissage','gratinage']::text[], ARRAY[]::text[], ARRAY[]::text[],
    'La socca se mange dans les minutes qui suivent la sortie du four, quand la croûte est encore craquante. À défaut, la garder quelques heures à température ambiante sous un linge, ou deux jours au réfrigérateur entre 0 et 4 °C en boîte hermétique, puis la repasser deux à trois minutes sous le gril pour lui rendre du croustillant. La congélation est déconseillée : la décongélation détrempe la croûte et rend le cœur caoutchouteux.', '{"fridge_hours":48,"eat_immediately":true,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-028'), '{"variant_label":"Finition très poivrée au moulin juste avant de servir, jusqu''à couvrir visiblement la surface.","rationale":"Quatre grammes de poivre fraîchement moulu au lieu d''une pincée : le poivre cesse d''être un assaisonnement pour devenir la seconde saveur de la galette, à côté du pois chiche. Sa pointe piquante et résineuse recouvre en partie le goût de farine grillée, et la socca ne convient plus aux palais sensibles. L''assaisonnement passe donc du rang de facultatif à celui d''obligatoire.","operations":[{"op":"set","form":"Poivre noir moulu","quantity":4,"optional":false}],"steps":[{"op":"replace","n":7,"instruction":"Décoller la galette à la spatule et la débiter en morceaux irréguliers, puis passer le moulin sur toute la surface en allées serrées, jusqu''à ce que le poivre noir moulu se voie franchement sur le doré de la pâte. Servir brûlant, à la main : moulu au dernier moment et posé sur un support gras et chaud, le poivre libère ses arômes volatils au lieu de rester une poussière sèche."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
