  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-031-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('b958e7dca1c55a54de88329d40a58ef4'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":3,"freshness":2,"intensity":3},"dominant_flavors":["tomate cuite","fromage gratiné","ail"],"aroma_families":["herbacé","alliacé","fromager"],"target_textures":["chair fondante","farce moelleuse","surface gratinée"],"signature_ingredients":["Aubergine fraîche","Riz long blanc cru","Tomate râpée"],"identity_guardrails":["La coque d''aubergine rôtie doit rester le contenant : servie en gratin dans un plat, la préparation redevient un simple riz à la tomate.","La chair prélevée retourne obligatoirement dans la farce ; la jeter fait perdre au plat son goût d''aubergine et son moelleux.","Le riz entre dans la farce ferme au cœur : cuit à point avant l''assemblage, il se délite au four et la garniture devient pâteuse."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
