  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Préchauffer le panier de la friteuse à air trois minutes à 180 °C. Prendre deux aubergines d''environ 280 g pièce, soit à peu près 560 g sur la balance du primeur, qui donnent les 500 g nets une fois les pédoncules coupés. Les rincer, les fendre en deux dans la longueur et vérifier qu''elles tiennent à plat dans le panier : entassées, elles cuisent à la vapeur au lieu de rôtir, quitte à les faire en deux fournées.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Quadriller la chair à la pointe du couteau sans traverser la peau, saler du bout des doigts et badigeonner avec la moitié de l''huile d''olive — l''air brassé dessèche vite, et une chair nue se racornit avant de fondre. Ranger les moitiés chair vers le haut et compter 30 minutes à 180 °C : elles doivent s''affaisser et céder sous la cuillère.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pendant ce temps, hacher menu l''oignon et l''ail. Les faire suer 5 minutes à feu moyen dans le reste d''huile, en visant la transparence plutôt que la coloration.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Monter le feu, verser le bœuf haché, l''émietter à la cuillère de bois et le laisser accrocher 5 minutes, le temps que des sucs bruns se forment au fond de la poêle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Sortir les aubergines, les laisser tiédir 5 minutes, puis les évider à la petite cuillère en gardant une paroi d''environ 5 mm. Hacher grossièrement la chair prélevée et la reverser dans la poêle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Ajouter la tomate râpée, le sucre, les herbes de Provence et un tour de poivre. Laisser réduire à découvert une quinzaine de minutes : la farce est au point quand la cuillère y laisse un sillon net.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Retirer du feu, incorporer le persil et le basilic ciselés, patienter deux minutes puis lier avec les deux œufs battus en remuant sans arrêt, pour qu''ils épaississent la farce au lieu de coaguler en filaments.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Garnir les coques en tassant légèrement, couvrir de gruyère râpé et remettre 8 minutes à 180 °C dans le panier. Surveiller la dernière minute : le souffle chaud brunit le fromage bien plus tôt qu''un four et le brûlerait avant que la farce ne soit chaude à cœur. Laisser reposer 5 minutes avant de servir.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-031-D3', 'recipe_family', 'Aubergines farcies à la friteuse à air',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-031-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-031-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-031-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('3cb476935fb665c5ce3bc6b65346750d'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":3,"freshness":2,"intensity":3},"dominant_flavors":["tomate cuite","viande rôtie","ail"],"aroma_families":["herbacé","alliacé","fromager"],"target_textures":["chair fondante","farce moelleuse","surface gratinée"],"signature_ingredients":["Aubergine fraîche","Bœuf haché cru 15 % MG","Tomate râpée"],"identity_guardrails":["La coque d''aubergine rôtie doit rester le contenant : servie en gratin dans un plat, la préparation redevient une simple sauce à la viande.","La chair prélevée retourne obligatoirement dans la farce ; la jeter fait perdre au plat son goût d''aubergine et son moelleux.","La farce se lie à la tomate réduite et à l''œuf, jamais à une béchamel, qui la ferait basculer vers la moussaka."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Aubergines farcies sans œuf', 'aubergines farcies sans oeuf', 'France', 'France',
     'meal', 'plat au four', 'documented_variation', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Aubergines farcies sans œuf', 'Aubergines farcies de bœuf haché à la tomate et gruyère, sans liant à l''œuf', ds.id, 'SRC-031-D4',
    'Myko', 'editorial', 4, 25, 55, 'facile',
    NULL, NULL,
    'B', 'candidate', '75ab9a30b5fad50216fd8975ffb4920b',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":3,"freshness":2,"intensity":3}'::jsonb, ARRAY['tomate cuite','viande rôtie','ail']::text[],
    ARRAY['herbacé','alliacé','fromager']::text[], ARRAY['chair fondante','farce serrée','surface gratinée']::text[],
    ARRAY['Aubergine fraîche','Bœuf haché cru 15 % MG','Tomate râpée']::text[], ARRAY['La coque d''aubergine rôtie doit rester le contenant : servie en gratin dans un plat, la préparation redevient une simple sauce à la viande.','La chair prélevée retourne obligatoirement dans la farce ; la jeter fait perdre au plat son goût d''aubergine et son moelleux.','La tenue vient de la seule tomate longuement réduite : une farce encore humide au garnissage s''affaisse dans la coque et rend son eau au four. Aucune béchamel ne vient la remplacer, qui ferait basculer le plat vers la moussaka.']::text[],
    ARRAY['rôtissage','saisie','réduction','gratinage']::text[], ARRAY[]::text[], ARRAY['lait']::text[],
    'Trois jours au réfrigérateur à 4 °C dans une boîte fermée ; réchauffer 15 minutes à 160 °C plutôt qu''au micro-ondes, qui détrempe la croûte. Congélation possible deux mois avant gratinage, mais la coque rend beaucoup d''eau à la décongélation et perd sa tenue.', '{"fridge_hours":72,"eat_immediately":false,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-031'), '{"variant_label":"Sans œuf : supprimer le liant et prolonger la réduction de 5 minutes, la tomate assurant seule la tenue de la farce.","rationale":"Privée d''œuf, la farce n''a plus de liant : c''est la tomate, réduite cinq minutes de plus, qui doit tenir seule la garniture. Elle y parvient à condition d''être franchement sèche au moment du garnissage, faute de quoi la farce rend son eau dans la coque et le fond du plat se remplit. Le plat sort de l''allergène œuf sans s''alléger vraiment, mais la texture change : plus friable, moins moelleuse, et la part se tranche mal.","operations":[{"op":"remove","form":"Œuf cru"}],"steps":[{"op":"replace","n":6,"instruction":"Ajouter la tomate râpée, le sucre, les herbes de Provence et un tour de poivre. Laisser réduire à découvert une vingtaine de minutes, cinq de plus que d''ordinaire : rien ne viendra lier la farce à la fin, c''est donc l''évaporation seule qui doit la resserrer. Le sillon laissé par la cuillère doit tenir sans se refermer."},{"op":"replace","n":7,"instruction":"Retirer du feu et incorporer hors flamme le persil et le basilic ciselés, qui garderont ainsi leur vert. Laisser la farce reposer dix minutes avant de garnir : en refroidissant, la tomate longuement réduite prend d''elle-même et tient la garniture aussi bien qu''un liant."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

