  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Chauffer le four à 220 °C. Prendre deux aubergines d''environ 280 g pièce, soit à peu près 560 g sur la balance du primeur, qui donnent les 500 g nets une fois les pédoncules coupés. Les rincer et les fendre en deux dans la longueur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Quadriller la chair à la pointe du couteau sans traverser la peau, saler du bout des doigts, badigeonner avec la moitié de l''huile d''olive, puis enfourner les moitiés chair vers le haut 25 minutes : elles doivent s''affaisser et céder sous la cuillère.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pendant ce temps, hacher menu l''oignon et l''ail. Les faire suer 5 minutes à feu moyen dans le reste d''huile, en visant la transparence plutôt que la coloration.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Monter le feu, verser le bœuf haché, l''émietter à la cuillère de bois et le laisser accrocher 5 minutes, le temps que des sucs bruns se forment au fond de la poêle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Sortir les aubergines, les laisser tiédir 5 minutes, puis les évider à la petite cuillère en gardant une paroi d''environ 5 mm. Hacher grossièrement la chair prélevée et la reverser dans la poêle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Ajouter la tomate râpée, le sucre, les herbes de Provence et un tour de poivre. Laisser réduire à découvert une vingtaine de minutes, cinq de plus que d''ordinaire : rien ne viendra lier la farce à la fin, c''est donc l''évaporation seule qui doit la resserrer. Le sillon laissé par la cuillère doit tenir sans se refermer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Retirer du feu et incorporer hors flamme le persil et le basilic ciselés, qui garderont ainsi leur vert. Laisser la farce reposer dix minutes avant de garnir : en refroidissant, la tomate longuement réduite prend d''elle-même et tient la garniture aussi bien qu''un liant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Garnir les coques en tassant légèrement, couvrir de gruyère râpé et remettre au four 20 minutes à 200 °C, jusqu''à une surface dorée et boursouflée. Laisser reposer 5 minutes avant de servir.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-031-D4', 'recipe_family', 'Aubergines farcies sans œuf',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-031-D4', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-031-D4', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-031-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('75ab9a30b5fad50216fd8975ffb4920b'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":3,"freshness":2,"intensity":3},"dominant_flavors":["tomate cuite","viande rôtie","ail"],"aroma_families":["herbacé","alliacé","fromager"],"target_textures":["chair fondante","farce serrée","surface gratinée"],"signature_ingredients":["Aubergine fraîche","Bœuf haché cru 15 % MG","Tomate râpée"],"identity_guardrails":["La coque d''aubergine rôtie doit rester le contenant : servie en gratin dans un plat, la préparation redevient une simple sauce à la viande.","La chair prélevée retourne obligatoirement dans la farce ; la jeter fait perdre au plat son goût d''aubergine et son moelleux.","La tenue vient de la seule tomate longuement réduite : une farce encore humide au garnissage s''affaisse dans la coque et rend son eau au four. Aucune béchamel ne vient la remplacer, qui ferait basculer le plat vers la moussaka."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Tourte au boudin noir et aux poireaux', 'tourte au boudin noir et aux poireaux', 'France', 'France',
     'meal', 'tourte sucrée-salée', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Tourte au boudin noir et aux poireaux', 'Tourte feuilletée garnie de boudin noir, pommes caramélisées et fondue de poireaux', ds.id, 'SRC-032-D1',
    'Myko', 'editorial', 4, 40, 60, 'facile',
    NULL, NULL,
    'B', 'candidate', '0790f72f403b3089ba9d6d7eed5ebb22',
    '{"sweet":3,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":4}'::jsonb, ARRAY['pomme compotée','sucré','profond','beurré']::text[],
    ARRAY['beurre','oignon_compoté','porc']::text[], ARRAY['protéine_fondante','tendre','feuilletage_croustillant']::text[],
    ARRAY['Boudin noir à cuire','Pomme fraîche']::text[], ARRAY['Sans boudin noir, le plat n''existe plus : la chair de sang en est l''axe et aucune autre charcuterie ne la remplace.','En tourte, la pomme passe en compote : elle doit rester granuleuse et peu sucrée, une purée lisse détrempant le fond et empêchant la pâte de cuire.','Le boyau se retire entièrement : conservé sous la pâte, il se rétracte sans jamais dorer et reste élastique.','Le poivre reste un assaisonnement de finition : la médiane du dossier est faussée par des pesées de boudin et ne doit jamais être appliquée telle quelle.']::text[],
    ARRAY['compotage','suer','fonçage','cuisson au four']::text[], ARRAY[]::text[], ARRAY['lait','gluten','œuf']::text[],
    'Se garde 48 h à 4 °C en boîte fermée, boudin et pommes séparés, et se réchauffe à la poêle sur feu doux ou au four à 140 °C. Congélation déconseillée : le boudin cuit relargue son gras et devient granuleux, les pommes s''affaissent en rendant leur eau.', '{"fridge_hours":48,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":false,"source":"manual"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-032'), '{"variant_label":"Tourte feuilletée : compote de pomme, tronçons de blanc de poireau et rondelles de boudin sans peau entre deux abaisses, dorées à l''œuf, 35 min à 210 °C (750g.com).","rationale":"La poêlée devient une tourte : compote de pomme, fondue de poireau et d''oignon, rondelles de boudin dépouillées de leur boyau, le tout pris entre deux abaisses. Le boudin cuit à l''étouffée sous la pâte au lieu d''être saisi — il reste fondant mais ne développe aucune croûte, et son gras imbibe le feuilletage au lieu de rester dans la poêle. Passée en compote, la pomme perd les morceaux caramélisés dont vivait l''accord sucré-salé de la base ; en échange la tourte se transporte, se réchauffe et se coupe en parts. Le feuilletage pèse en calories presque autant que la charcuterie et fait quasiment doubler la part.","operations":[{"op":"add","form":"Pâte feuilletée crue","quantity":450,"unit":"g","role":"pâte","optional":false},{"op":"add","form":"Poireau cru","quantity":300,"unit":"g","role":"légume","optional":false},{"op":"add","form":"Œuf cru","quantity":50,"unit":"g","role":"dorure","optional":false}],"steps":[{"op":"replace","n":1,"instruction":"Pelez et évidez quatre pommes à chair ferme, soit environ 450 g de fruits entiers pour 320 g de chair nette, et détaillez-les en dés. Arrosez-les du jus de citron, poudrez-les du sucre et faites-les fondre à couvert une dizaine de minutes sur feu doux, puis écrasez-les grossièrement à la fourchette : la compote doit rester granuleuse et un peu sèche, une purée lisse détremperait le fond de la tourte."},{"op":"replace","n":2,"instruction":"Épluchez 280 g d''oignons pour en obtenir 250 g nets et émincez-les finement. Fendez les blancs de poireau en quatre dans la longueur, lavez-les à grande eau entre les feuilles et débitez-les en tronçons courts. Faites fondre le tout à couvert dans la totalité du beurre, sur feu très doux, une quinzaine de minutes, jusqu''à ce que le poireau cède sous le doigt sans avoir pris couleur — c''est le seul gras de la tourte, le feuilletage apportant le reste. Égouttez cette fondue et laissez-la refroidir : posée chaude, elle ferait fondre le feuilletage avant qu''il n''entre au four."},{"op":"remove","n":3},{"op":"replace","n":4,"instruction":"Le boudin se vend en boyau : prévoyez quatre tronçons d''environ 150 g, soit près de 600 g sur la balance du charcutier, qui donnent les 560 g de chair annoncés une fois les extrémités parées. Fendez le boyau d''un coup de lame et retirez-le entièrement — sous la pâte il resterait élastique sous la dent — puis coupez la chair en rondelles d''un bon centimètre, en la manipulant le moins possible, car elle se défait vite une fois nue."},{"op":"replace","n":5,"instruction":"Étalez la moitié de la pâte feuilletée sur une plaque garnie de papier cuisson, piquez-la à la fourchette et laissez deux centimètres de bord libre tout autour. Étalez la compote de pomme au centre, couvrez-la de la fondue de poireau et d''oignon bien égouttée, puis rangez les rondelles de boudin en une seule couche sans les faire chevaucher. Salez, poivrez, et humectez le bord au pinceau."},{"op":"replace","n":6,"instruction":"Posez la seconde abaisse par-dessus, soudez les bords en les pinçant fermement, dorez toute la surface à l''œuf battu et percez une cheminée au centre : sans elle, la vapeur soulève la pâte puis la fait retomber détrempée. Enfournez 35 minutes à 210 °C, jusqu''à ce que le dessus soit brun et le dessous sec au toucher, et attendez dix minutes avant de couper, sinon la garniture glisse hors des parts."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
