  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'optional',
     'assaisonnement', true, 16);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'rouget grondin cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Rouget grondin cru', 500, 'g', 'required',
     'protéine', false, 17);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Compter 625 g de moules en coquille chez le poissonnier, moitié moins que dans la version toute marine : c''est le poids d''achat qui donne les 188 g de chair annoncés. Les gratter, tirer le byssus, les rincer à grande eau froide et jeter sans hésiter toute coquille fêlée ou qui refuse de se refermer lorsqu''on la tapote. Demander au même moment de lever en filets 1,3 kg de rougets grondins entiers : la tête cuirassée et l''arête de ce poisson de roche emportent près des deux tiers du poids, et il n''en reste que les 500 g de chair annoncés.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Verser le vin blanc dans un faitout, y jeter les moules, couvrir et monter à feu vif trois à quatre minutes en secouant une fois la casserole — moitié moins de coquillages s''ouvrent d''autant plus vite, et les oublier une minute de trop les racornit. Les retirer dès qu''elles bâillent, décoquiller les trois quarts et garder le reste en coquille pour le service. Filtrer le jus rendu à travers une passoire doublée d''un linge : c''est lui qui apportera le sel et l''iode, le sable doit rester dedans.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Éplucher environ 780 g de pommes de terre à chair ferme achetées en robe pour obtenir les 625 g de chair utile, puis les tailler en gros quartiers d''environ trois centimètres qui tiendront au mijotage sans se déliter.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Chauffer l''huile d''olive dans une cocotte large, y laisser fondre l''oignon émincé finement et les brins de fenouil ciselés pendant huit minutes à feu doux, sans jamais chercher la coloration, puis ajouter l''ail écrasé et prolonger une minute le temps qu''il libère son parfum.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Incorporer la tomate râpée et le concentré, remonter un peu le feu et laisser compoter cinq minutes en remuant, jusqu''à ce que le jus épaississe et que le mordant acide de la tomate s''arrondisse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Mouiller avec les 800 ml de fond de poisson et le jus de moules filtré, ajouter le laurier, le thym, le zeste de citron et le poivre, puis amener doucement à frémissement — un bouillon marin qui bout à gros bouillons devient trouble et amer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Délayer le safran dans une petite louche de bouillon chaud pour qu''il diffuse sa couleur, le reverser dans la cocotte, ajouter les quartiers de pomme de terre et laisser cuire vingt à vingt-cinq minutes à tout petits frémissements, jusqu''à ce que la pointe d''un couteau traverse un morceau sans résistance.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Couper le feu et déposer les filets de rouget grondin à plat sur le bouillon, sans les enfoncer. Couvrir et laisser pocher cinq minutes hors du feu : la chaleur retenue suffit à raffermir la chair, alors qu''un frémissement la déferait en lambeaux. Remettre alors la chair de moule et les coquilles réservées, goûter seulement à cet instant avant de saler — avec moitié moins de jus de coquillage, la base est nettement moins salée qu''à l''ordinaire — puis servir en assiette creuse en répartissant bouillon, pommes de terre, filets et coquillages.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-033-D1', 'recipe_family', 'Bouillabaisse du pêcheur',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-033-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-033-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-033-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('96ee546589465c32345508c3703337f6'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":4,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":2,"freshness":2,"intensity":4},"dominant_flavors":["iodé","safran","tomate cuite","ail"],"aroma_families":["marine","épice safranée","anisée","agrume"],"target_textures":["bouillon fluide et soyeux","pomme de terre fondante","chair de moule tendre"],"signature_ingredients":["Sauce poisson","Moule commune crue","Safran"],"identity_guardrails":["Sans safran, le bouillon perd sa robe orangée et son parfum : ce n''est plus une bouillabaisse mais une soupe de pommes de terre à la tomate.","Sans base marine — fond de poisson et coquillages — il ne reste qu''un ragoût de légumes ; l''iode est la colonne vertébrale du plat.","La garniture reste strictement marine et provençale : ni viande, ni condiment asiatique, quoi qu''en disent les relevés d''ingrédients aberrants.","Le bouillon ne doit jamais bouillir franchement, sous peine de troubler et de durcir les coquillages."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Bouillabaisse en deux services', 'bouillabaisse en deux services', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Bouillabaisse en deux services', 'Bouillabaisse servie d''abord en soupe filtrée, puis avec les fruits de mer en assiette', ds.id, 'SRC-033-D2',
    'Myko', 'editorial', 4, 40, 45, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '3e84f9fe47aba61f3979fac8c012be98',
    '{"sweet":1,"salty":4,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":2,"freshness":2,"intensity":4}'::jsonb, ARRAY['iodé','safran','tomate cuite','ail']::text[],
    ARRAY['marine','épice safranée','anisée','agrume']::text[], ARRAY['bouillon fluide et soyeux','pomme de terre fondante','chair de moule tendre']::text[],
    ARRAY['Sauce poisson','Moule commune crue','Safran']::text[], ARRAY['Sans safran, le bouillon perd sa robe orangée et son parfum : ce n''est plus une bouillabaisse mais une soupe de pommes de terre à la tomate.','Sans base marine — fond de poisson et coquillages — il ne reste qu''un ragoût de légumes ; l''iode est la colonne vertébrale du plat.','La garniture reste strictement marine et provençale : ni viande, ni condiment asiatique, quoi qu''en disent les relevés d''ingrédients aberrants.','Le bouillon ne doit jamais bouillir franchement, sous peine de troubler et de durcir les coquillages.']::text[],
    ARRAY['mijotage','pochage','réduction','infusion','filtration','grillade du pain']::text[], ARRAY[]::text[], ARRAY['poisson','mollusques','sulfites','gluten']::text[],
    'Se garde 24 heures au réfrigérateur entre 0 et 4 °C dans un récipient couvert, coquillages et bouillon ensemble ; ne réchauffer qu''une seule fois, à frémissement doux et sans ébullition. La congélation est déconseillée : le bouillon safrané la supporte, mais les moules deviennent caoutchouteuses et les pommes de terre farineuses à la décongélation.', '{"fridge_hours":24,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-033'), '{"variant_label":"Service à la marseillaise : passer le bouillon et le servir à part, brûlant, avec des croûtons frottés d''ail, la garniture étant présentée à côté sur un plat creux.","rationale":"Le bouillon est passé au chinois et part seul à table, brûlant, avec des croûtons de pain de campagne frottés d''ail ; la garniture suit sur un plat creux. La cuisson ne bouge pas, le repas change : le bouillon se boit clair et concentré au lieu d''être bu dilué autour des pommes de terre, et le pain grillé lui rend le corps que la filtration lui retire. Il faut deux gousses d''ail de plus pour frotter les cent soixante grammes de pain, et deux services au lieu d''un — la garniture attend, et refroidit si le plat n''est pas tenu au chaud.","operations":[{"op":"add","form":"Pain de campagne","quantity":160,"unit":"g","role":"accompagnement","optional":false},{"op":"scale","form":"Ail cru","factor":1.5}],"steps":[{"op":"replace","n":8,"instruction":"Couper le feu, remettre la chair de moule et les coquilles réservées, couvrir deux minutes pour les réchauffer sans les raidir. Prélever ensuite à l''écumoire les pommes de terre et les coquillages et les dresser sur un plat creux tenu au chaud, puis passer le bouillon au chinois au-dessus d''une casserole et le remettre à frémir : c''est lui qui part le premier à table, brûlant, en assiette creuse."},{"op":"insert","after":8,"instruction":"Griller les tranches de pain de campagne des deux côtés et les frotter énergiquement d''ail cru tant qu''elles sont chaudes, en changeant de gousse dès que la première s''use — froides, elles ne râpent plus rien et l''ail reste dessus au lieu de fondre. Les servir avec le bouillon, la garniture suivant dans un second temps sur son plat creux, chacun se resservant de bouillon par-dessus."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

