  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Compter 1,25 kg de moules en coquille chez le poissonnier : c''est le poids d''achat qui donne les 375 g de chair annoncés. Les gratter, tirer le byssus, les rincer à grande eau froide et jeter sans hésiter toute coquille fêlée ou qui refuse de se refermer lorsqu''on la tapote.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Verser le vin blanc dans un faitout, y jeter les moules, couvrir et monter à feu vif quatre à cinq minutes en secouant une fois la casserole. Les retirer dès qu''elles bâillent, décoquiller les trois quarts et garder le reste en coquille pour le service. Filtrer le jus rendu à travers une passoire doublée d''un linge : c''est lui qui apportera le sel et l''iode, le sable doit rester dedans.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Éplucher environ 780 g de pommes de terre à chair ferme achetées en robe pour obtenir les 625 g de chair utile, puis les tailler en gros quartiers d''environ trois centimètres qui tiendront au mijotage sans se déliter.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Chauffer l''huile d''olive dans une cocotte large, y laisser fondre l''oignon émincé finement et les brins de fenouil ciselés pendant huit minutes à feu doux, sans jamais chercher la coloration, puis ajouter l''ail écrasé et prolonger une minute le temps qu''il libère son parfum.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Incorporer la tomate râpée et le concentré, remonter un peu le feu et laisser compoter cinq minutes en remuant, jusqu''à ce que le jus épaississe et que le mordant acide de la tomate s''arrondisse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Mouiller avec les 800 ml de fond de poisson et le jus de moules filtré, ajouter le laurier, le thym, le zeste de citron et le poivre, puis amener doucement à frémissement — un bouillon marin qui bout à gros bouillons devient trouble et amer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Délayer le safran dans une petite louche de bouillon chaud pour qu''il diffuse sa couleur, le reverser dans la cocotte, ajouter les quartiers de pomme de terre et laisser cuire vingt à vingt-cinq minutes à tout petits frémissements, jusqu''à ce que la pointe d''un couteau traverse un morceau sans résistance.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Couper le feu, remettre la chair de moule et les coquilles réservées, couvrir deux minutes pour les réchauffer sans les raidir. Prélever ensuite à l''écumoire les pommes de terre et les coquillages et les dresser sur un plat creux tenu au chaud, puis passer le bouillon au chinois au-dessus d''une casserole et le remettre à frémir : c''est lui qui part le premier à table, brûlant, en assiette creuse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Griller les tranches de pain de campagne des deux côtés et les frotter énergiquement d''ail cru tant qu''elles sont chaudes, en changeant de gousse dès que la première s''use — froides, elles ne râpent plus rien et l''ail reste dessus au lieu de fondre. Les servir avec le bouillon, la garniture suivant dans un second temps sur son plat creux, chacun se resservant de bouillon par-dessus.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-033-D2', 'recipe_family', 'Bouillabaisse en deux services',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-033-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-033-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-033-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('3e84f9fe47aba61f3979fac8c012be98'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":4,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":2,"freshness":2,"intensity":4},"dominant_flavors":["iodé","safran","tomate cuite","ail"],"aroma_families":["marine","épice safranée","anisée","agrume"],"target_textures":["bouillon fluide et soyeux","pomme de terre fondante","chair de moule tendre"],"signature_ingredients":["Sauce poisson","Moule commune crue","Safran"],"identity_guardrails":["Sans safran, le bouillon perd sa robe orangée et son parfum : ce n''est plus une bouillabaisse mais une soupe de pommes de terre à la tomate.","Sans base marine — fond de poisson et coquillages — il ne reste qu''un ragoût de légumes ; l''iode est la colonne vertébrale du plat.","La garniture reste strictement marine et provençale : ni viande, ni condiment asiatique, quoi qu''en disent les relevés d''ingrédients aberrants.","Le bouillon ne doit jamais bouillir franchement, sous peine de troubler et de durcir les coquillages."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Bouillabaisse sans alcool', 'bouillabaisse sans alcool', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Bouillabaisse sans alcool', 'Soupe de moules dans un bouillon de poisson et tomates avec concentré, sans vin blanc', ds.id, 'SRC-033-D3',
    'Myko', 'editorial', 4, 35, 40, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '9ad77502461b458861184493dbc2b8c6',
    '{"sweet":1,"salty":4,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":2,"freshness":2,"intensity":4}'::jsonb, ARRAY['iodé','safran','tomate cuite','ail']::text[],
    ARRAY['marine','épice safranée','anisée','agrume']::text[], ARRAY['bouillon fluide et soyeux','pomme de terre fondante','chair de moule tendre']::text[],
    ARRAY['Sauce poisson','Moule commune crue','Safran']::text[], ARRAY['Sans safran, le bouillon perd sa robe orangée et son parfum : ce n''est plus une bouillabaisse mais une soupe de pommes de terre à la tomate.','Sans base marine — fond de poisson et coquillages — il ne reste qu''un ragoût de légumes ; l''iode est la colonne vertébrale du plat.','La garniture reste strictement marine et provençale : ni viande, ni condiment asiatique, quoi qu''en disent les relevés d''ingrédients aberrants.','Le bouillon ne doit jamais bouillir franchement, sous peine de troubler et de durcir les coquillages.']::text[],
    ARRAY['mijotage','pochage','réduction','infusion']::text[], ARRAY[]::text[], ARRAY['poisson','mollusques']::text[],
    'Se garde 24 heures au réfrigérateur entre 0 et 4 °C dans un récipient couvert, coquillages et bouillon ensemble ; ne réchauffer qu''une seule fois, à frémissement doux et sans ébullition. La congélation est déconseillée : le bouillon safrané la supporte, mais les moules deviennent caoutchouteuses et les pommes de terre farineuses à la décongélation.', '{"fridge_hours":24,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-033'), '{"variant_label":"Sans alcool : supprimer le vin blanc, ouvrir les moules dans un fond d''eau et rattraper la vivacité par un trait de jus de citron au moment de servir.","rationale":"Les moules s''ouvrent dans un fond d''eau et le jus de citron, ajouté hors du feu, rend au bouillon le tranchant que l''acidité de l''alcool lui donnait. L''ouverture à l''eau produit un jus plus court et plus franchement iodé, mais moins parfumé : le bouillon y perd sa longueur et son fond légèrement vineux. Le plat sort des sulfites et convient à qui ne boit pas d''alcool, à condition d''ajouter le citron au tout dernier moment — chauffé, il vire à l''amer et ne se rattrape plus.","operations":[{"op":"remove","form":"Vin blanc sec"},{"op":"add","form":"Eau","quantity":150,"unit":"ml","role":"liquide","optional":false},{"op":"add","form":"Jus de citron frais","quantity":15,"unit":"ml","role":"acidité","optional":false}],"steps":[{"op":"replace","n":2,"instruction":"Verser l''eau dans un faitout, y jeter les moules, couvrir et monter à feu vif quatre à cinq minutes en secouant une fois la casserole. Les retirer dès qu''elles bâillent, décoquiller les trois quarts et garder le reste en coquille pour le service. Filtrer le jus rendu à travers une passoire doublée d''un linge : privé de tout apport aromatique à l''ouverture, ce jus est la seule chose qui apporte le sel et l''iode, et le sable doit rester dans le linge."},{"op":"replace","n":8,"instruction":"Couper le feu, remettre la chair de moule et les coquilles réservées, couvrir deux minutes pour les réchauffer sans les raidir. Ajouter le jus de citron hors du feu et goûter seulement à cet instant avant de saler : c''est lui qui redonne au bouillon le tranchant que l''acidité de l''alcool lui apportait, et il s''évanouit dès qu''on le fait chauffer. Servir aussitôt en assiette creuse en répartissant bouillon, pommes de terre et coquillages."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
