  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir environ 500 g de carottes entières, ou une botte d''à peu près 700 g si elles sont vendues avec leurs fanes, pour arriver aux 400 g de chair nette de la recette : ôter le feuillage, gratter la peau à l''économe et retirer les deux extrémités.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Râper les carottes sur la grille à gros trous, à la main ou au robot, et les laisser tomber sans les tasser dans un grand saladier afin que les filaments restent aérés.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Presser l''orange et faire tiédir son jus dans une petite casserole sans jamais le laisser bouillir, sous peine de lui donner un goût cuit. Y jeter les raisins secs hors du feu et les laisser gonfler dix minutes : ils boivent l''agrume au lieu de l''eau et en gardent le parfum. Les égoutter au-dessus du bol en réservant tout le jus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Délayer la moutarde à la fourchette dans le jus d''orange encore tiède jusqu''à disparition des grumeaux, ajouter le vinaigre, puis verser l''huile en mince filet en fouettant, jusqu''à ce que la sauce épaississe et cesse de se séparer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Saler, poivrer et incorporer les quatre grammes de cumin en deux fois, en goûtant entre les deux : doublée, l''épice doit se sentir franchement dès le bol, sans pour autant couvrir l''orange qui la porte.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Verser la sauce sur les carottes, ajouter les raisins égouttés et mélanger longuement à deux fourchettes en soulevant la masse, de façon à enrober chaque filament plutôt que d''écraser le tas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Couvrir et laisser reposer un quart d''heure à température ambiante seulement, jamais au réfrigérateur : le froid figerait l''huile et refermerait le cumin, qui ne s''ouvre qu''à la chaleur. Remuer une dernière fois, rectifier le sel et servir tiède, les raisins encore chauds au milieu des carottes.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-035-D1', 'recipe_family', 'Carottes râpées à la marocaine',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-035-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-035-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-035-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('bd3c0f21f2d2ec62abbc7e8542503f66'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"bright_acidic","scores":{"sweet":3,"salty":2,"acidic":4,"bitter":0,"umami":1,"heat":0,"pungency":2,"richness":2,"freshness":5,"intensity":2},"dominant_flavors":["sucré végétal de la carotte crue","acidité vinaigrée","jus d''agrume"],"aroma_families":["agrume","épices chaudes","végétal frais"],"target_textures":["croquant filamenteux","juteux","moelleux des raisins regonflés"],"signature_ingredients":["Carotte crue","Orange fraîche","Moutarde de Dijon"],"identity_guardrails":["La carotte reste crue et râpée : dès qu''elle est cuite, le plat cesse d''être des carottes râpées","L''assaisonnement est une vinaigrette acidulée montée à la moutarde, jamais une sauce crémeuse ou mayonnaise","Le jus d''agrume frais vient épauler le vinaigre, il ne le remplace pas par un sirop sucré","La râpe à gros trous fait la texture : une carotte réduite en purée ou en fins cheveux d''ange n''a plus le croquant attendu"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Carottes râpées douces à l''orange', 'carottes rapees douces a l orange', 'France', 'France',
     'meal', 'salade', 'documented_variation', 'bright_acidic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Carottes râpées douces à l''orange', 'Carottes râpées assaisonnées d''une vinaigrette douce à l''orange sans vinaigre', ds.id, 'SRC-035-D2',
    'Myko', 'editorial', 4, 15, 0, 'facile',
    NULL, NULL,
    'B', 'candidate', '542f2077d074a433e6b29cce8765c2b8',
    '{"sweet":3,"salty":2,"acidic":4,"bitter":0,"umami":1,"heat":0,"pungency":2,"richness":2,"freshness":5,"intensity":2}'::jsonb, ARRAY['sucré végétal de la carotte crue','acidité vinaigrée','jus d''agrume']::text[],
    ARRAY['agrume','épices chaudes','végétal frais']::text[], ARRAY['croquant filamenteux','juteux','moelleux des raisins regonflés']::text[],
    ARRAY['Carotte crue','Orange fraîche','Moutarde de Dijon']::text[], ARRAY['La carotte reste crue et râpée : dès qu''elle est cuite, le plat cesse d''être des carottes râpées','L''assaisonnement est une vinaigrette acidulée montée à la moutarde, jamais une sauce crémeuse ou mayonnaise','Le jus d''agrume frais vient épauler le vinaigre, il ne le remplace pas par un sirop sucré','La râpe à gros trous fait la texture : une carotte réduite en purée ou en fins cheveux d''ange n''a plus le croquant attendu']::text[],
    ARRAY['émulsion','marinade']::text[], ARRAY[]::text[], ARRAY['moutarde','sulfites']::text[],
    'Se garde 48 heures au réfrigérateur entre 0 et 4 °C dans une boîte hermétique ; dès le deuxième jour la carotte rend son eau et s''assouplit, il faut alors l''égoutter et rectifier sel et acidité avant de servir. Ne se congèle pas : la décongélation ruine définitivement le croquant.', '{"fridge_hours":48,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":true,"source":"manual"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-035'), '{"variant_label":"Version douce sans vinaigre : monter la vinaigrette au seul jus d''orange et à la moutarde, pour des convives sensibles à l''acidité","rationale":"Sans acidité vive, la sauce devient franchement douce et l''orange cesse d''être un accent pour devenir la base du goût. Il faut plus de fruit — 250 g au lieu de 180 — pour retrouver le liquide perdu et garder une sauce qui coule. Ce qu''on y gagne en confort de bouche se paie en tenue : rien ne relance plus le palais d''une bouchée à l''autre, et l''assaisonnement monte à 4 g de sel et 1,5 g de poivre au lieu de 3 et 1, faute de quoi la salade paraîtrait plate.","operations":[{"op":"remove","form":"Vinaigre de vin rouge"},{"op":"set","form":"Orange fraîche","quantity":250},{"op":"set","form":"Sel fin","quantity":4},{"op":"set","form":"Poivre noir moulu","quantity":1.5}],"steps":[{"op":"replace","n":4,"instruction":"Presser l''orange au-dessus d''un bol — il en faut nettement plus qu''à l''ordinaire, son jus tenant désormais seul le rôle de l''acidité — y délayer la moutarde à la fourchette jusqu''à disparition des grumeaux, puis verser l''huile en mince filet en fouettant, jusqu''à ce que la sauce épaississe et cesse de se séparer."},{"op":"replace","n":5,"instruction":"Saler, poivrer et incorporer le cumin à la sauce, puis goûter : privée de mordant, elle paraîtra fade si on la sale timidement. Forcer un peu le sel et le poivre, qui prennent ici le relais et donnent seuls le contraste."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
