  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir environ 500 g de carottes entières, ou une botte d''à peu près 700 g si elles sont vendues avec leurs fanes, pour arriver aux 400 g de chair nette de la recette : ôter le feuillage, gratter la peau à l''économe et retirer les deux extrémités.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Râper les carottes sur la grille à gros trous, à la main ou au robot, et les laisser tomber sans les tasser dans un grand saladier afin que les filaments restent aérés.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Faire gonfler les raisins secs une dizaine de minutes dans un fond d''eau tiède, puis les égoutter et les presser doucement entre les doigts.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
