  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Saler, poivrer et incorporer le cumin à la vinaigrette, puis goûter : elle doit sembler un cran trop franche dans le bol, car l''eau des carottes va l''adoucir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
