  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir environ 3 kg de coquilles entières pour quatre, soit une bonne douzaine de pièces lourdes et bien closes : une fois décoquillées et parées, elles rendent les 500 g de chair de la liste, le reste étant coquille, manteau et viscères. Les brosser sous un filet d''eau froide sans jamais les laisser tremper.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Ouvrir chaque coquille en engageant une lame rigide contre la face plate, au niveau de la charnière, puis en rasant l''intérieur du couvercle pour trancher le muscle. Détacher la chair, ôter la frange grise et le petit nerf latéral, rincer très vite et éponger à fond. Les valves n''ont pas d''emploi ici : le montage se fait dans quatre petits poêlons de fonte ou de terre, beurrés de 10 g prélevés sur le beurre puis mis à tiédir près du four, dont le fond plus large donnera une croûte plus étendue.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chauffer une poêle jusqu''à ce qu''elle fume légèrement, y verser l''huile d''olive et saisir la chair bien sèche 45 secondes par face, en deux fois pour ne pas encombrer la poêle. Elle doit rester nacrée à cœur. La débarrasser aussitôt sur une assiette froide et garder le jus rendu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ciseler les échalotes menu et les faire suer deux minutes dans 10 g de beurre sans les colorer. Mouiller avec le vin blanc, ajouter le jus rendu par la chair et laisser réduire à feu moyen jusqu''à ce qu''il ne reste qu''un fond sirupeux, environ la moitié du volume.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Dans une casserole à part, fondre 25 g de beurre, pluie de farine, remuer une minute à feu doux : le mélange doit mousser sans blondir. Verser la réduction passée au tamis puis le lait tiédi en trois fois, en fouettant à chaque ajout. Laisser épaissir 6 à 7 minutes à petits bouillons — privée du gras qui la portait, la sauce demande un roux un peu plus fourni et une minute de plus pour napper le dos d''une cuillère.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Retirer du feu, attendre une minute, puis incorporer les jaunes d''œufs un par un au fouet — la sauce ne doit plus jamais bouillir, sous peine de grainer. Jeter le gruyère râpé en trois fois dans la chaleur restante en fouettant jusqu''à ce qu''il file sans se séparer, râper la muscade par-dessus, poivrer et ciseler le persil dedans. Goûter et n''ajuster le sel qu''après : la réduction et le fromage en apportent déjà beaucoup à eux deux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Trancher les grosses pièces de chair en deux dans l''épaisseur, les répartir dans les poêlons tièdes sans les serrer, napper de sauce sans noyer, saupoudrer de chapelure et parsemer des 5 g de beurre restants en tout petits éclats.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Enfourner dans le haut d''un four préchauffé à 210 °C pour 8 à 10 minutes, le temps que la chapelure prenne couleur et que la surface boursoufle. S''arrêter dès que la croûte est dorée : au-delà, la chair se rétracte et devient élastique. Servir les poêlons brûlants, posés chacun sur une assiette doublée d''un rond de papier pour qu''ils ne glissent pas.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-039-D2', 'recipe_family', 'Coquilles Saint-Jacques sauce Mornay',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-039-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-039-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-039-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('51eb5c324dd2cee505e5db0dd71e6d72'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":2,"salty":2,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["iodé","crémeux beurré","vin blanc réduit","échalote fondue"],"aroma_families":["marin","lacté","alliacé","grillé"],"target_textures":["chair nacrée et moelleuse","sauce nappante","croûte de chapelure croustillante"],"signature_ingredients":["Noix de Saint-Jacques crue","Lait entier","Vin blanc sec","Chapelure de blé"],"identity_guardrails":["Sans noix de Saint-Jacques, ce n''est pas le plat : un autre poisson blanc en fait une simple coquille de poisson à la crème.","Les noix se saisissent très vite, une minute par face au plus : au-delà elles se rétractent et deviennent caoutchouteuses.","Le poids déclaré est celui des noix décoquillées — une coquille entière n''en donne qu''une trentaine de grammes."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Fenouil blanchi puis braisé', 'fenouil blanchi puis braise', 'France', 'France',
     'meal', 'légume braisé', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Fenouil blanchi puis braisé', 'Fenouil d''abord blanchi puis saisi et braisé au vin blanc avec jus de citron', ds.id, 'SRC-040-D1',
    'Myko', 'editorial', 4, 15, 40, 'facile',
    NULL, NULL,
    'B', 'candidate', '514d49c54182ed8a05f1f7f73a2776a2',
    '{"sweet":3,"salty":2,"acidic":2,"bitter":1,"umami":1,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":2}'::jsonb, ARRAY['anisé','citronné','sucré végétal']::text[],
    ARRAY['anisée','agrume','herbacée']::text[], ARRAY['fondant','légèrement confit','jus sirupeux']::text[],
    ARRAY['Fenouil frais','Vin blanc sec','Jus de citron frais']::text[], ARRAY['Le fenouil doit être braisé en quartiers gardant leur cœur : émincé finement, il devient une fondue de fenouil et perd l''identité du plat.','La cuisson se fait à couvert dans un liquide court puis réduit ; rôti à sec au four, le résultat n''est plus un braisé.','L''acidité du vin blanc et du citron est structurante : sans elle le plat vire au légume sucré et l''amertume du bulbe ressort.']::text[],
    ARRAY['saisie','déglaçage','mijotage','réduction']::text[], ARRAY[]::text[], ARRAY['lait','sulfites']::text[],
    'Se conserve 3 jours au réfrigérateur à 4 °C, dans une boîte hermétique et baigné de son jus de braisage ; réchauffer doucement à couvert avec une cuillère d''eau. La congélation est déconseillée : les fibres du fenouil éclatent au dégel et le légume rend son eau, donnant une texture filandreuse et un jus délavé.', '{"fridge_hours":72,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-040'), '{"variant_label":"Départ blanchi, façon 750g.com : plonger les demi-bulbes cinq minutes dans une eau bouillante salée et les égoutter avant de les colorer, pour un cœur encore plus fondant.","rationale":"Le passage à l''eau bouillante attendrit le cœur du bulbe avant qu''il ne rencontre la matière grasse, si bien que le braisage tombe à vingt minutes. Le prix est triple : une casserole d''eau de plus à porter à ébullition, une part de l''anis et des sucres du fenouil qui s''en va dans cette eau sans jamais revenir dans le jus, et une marge de cuisson qui se resserre — une chair déjà attendrie passe du fondant à la charpie en quelques minutes et demande d''être goûtée tôt. La coloration devient aussi plus ingrate, une chair humide dorant moins franchement qu''une chair crue. Au total le temps de feu bouge à peine : les dix minutes de braisage gagnées repartent dans l''eau à porter à ébullition.","operations":[],"steps":[{"op":"replace","n":2,"instruction":"Raccourcir la base terreuse au couteau sans creuser le cœur : c''est lui qui empêchera les morceaux de se défaire pendant la cuisson. Fendre chaque bulbe en deux dans la hauteur et s''en tenir là pour l''instant, la découpe fine venant après le passage à l''eau. Citronner aussitôt les faces tranchées pour qu''elles ne noircissent pas."},{"op":"replace","n":4,"instruction":"Coucher les quartiers de fenouil sur leur face tranchée, bien à plat contre le fond, et les laisser dorer trois à quatre minutes seulement : une chair déjà attendrie prend couleur bien plus vite qu''une chair crue et brûlerait au temps de la version directe. Les retourner pour marquer l''autre face, puis glisser l''ail écrasé entre les morceaux au tout dernier moment afin qu''il parfume sans amertume."},{"op":"replace","n":6,"instruction":"Poser le couvercle et maintenir un frémissement paresseux une vingtaine de minutes, en retournant les quartiers une fois à mi-cuisson pour qu''ils s''imprègnent des deux côtés. Le blanchiment a pris de l''avance sur le braisage : goûter dès dix-huit minutes, car un fenouil déjà attendri passe du fondant à la charpie en quelques minutes."},{"op":"insert","after":2,"instruction":"Porter une grande casserole d''eau salée à pleine ébullition et y plonger les demi-bulbes cinq minutes, pas davantage : il s''agit d''attendrir le cœur, pas de le cuire. Les sortir à l''écumoire, les laisser s''égoutter retournés sur un linge, puis les recouper en quartiers de deux à trois centimètres d''épaisseur. Les éponger à fond avant la poêle, sans quoi ils bouilliront dans leur propre eau au lieu de dorer."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
