  VALUES (v_version, 3, 'Chauffer l''huile d''olive seule dans une cocotte assez large pour recevoir tous les quartiers sur une seule couche : la portion est montée à 40 g, faute de quoi le fond manquerait de corps une fois le braisage lancé et le légume se contenterait de bouillir. Y jeter l''oignon finement émincé et le laisser s''attendrir cinq minutes à feu modéré, jusqu''à ce qu''il perde son opacité, sans lui laisser prendre de couleur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Coucher les quartiers de fenouil sur leur face tranchée, bien à plat contre le fond, et les laisser dorer sans y toucher cinq à six minutes. Les retourner pour colorer l''autre face, puis glisser l''ail écrasé entre les morceaux au tout dernier moment afin qu''il parfume sans amertume.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser le vin blanc sur le fond brûlant et gratter les sucs à la spatule ; laisser bouillonner une minute pour chasser l''alcool. Mouiller ensuite avec l''eau, qui doit monter à mi-hauteur des quartiers, éparpiller le thym et le sucre, puis assaisonner de sel et de poivre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Poser le couvercle et maintenir un frémissement paresseux pendant une trentaine de minutes, en retournant les quartiers une fois à mi-cuisson pour qu''ils s''imprègnent des deux côtés. Le fenouil est prêt quand la pointe d''un couteau traverse le cœur sans résistance.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Retirer le couvercle et pousser le feu quelques minutes : le jus doit se resserrer jusqu''à napper les quartiers d''un sirop léger et brillant. Rectifier l''assaisonnement, disperser les plumets réservés et servir sans attendre, la sauce cuillérée par-dessus.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-040-D3', 'recipe_family', 'Fenouil braisé à l''huile d''olive',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-040-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-040-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-040-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('3f29c893361faff9808ff5e500401e4f'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":3,"salty":2,"acidic":2,"bitter":1,"umami":1,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":2},"dominant_flavors":["anisé","citronné","sucré végétal"],"aroma_families":["anisée","agrume","herbacée"],"target_textures":["fondant","légèrement confit","jus sirupeux"],"signature_ingredients":["Fenouil frais","Vin blanc sec","Jus de citron frais"],"identity_guardrails":["Le fenouil doit être braisé en quartiers gardant leur cœur : émincé finement, il devient une fondue de fenouil et perd l''identité du plat.","La cuisson se fait à couvert dans un liquide court puis réduit ; rôti à sec au four, le résultat n''est plus un braisé.","L''acidité du vin blanc et du citron est structurante : sans elle le plat vire au légume sucré et l''amertume du bulbe ressort."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Gratin de chou-fleur au bouillon de volaille', 'gratin de chou fleur au bouillon de volaille', 'France', 'France',
     'meal', 'gratin', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Gratin de chou-fleur au bouillon de volaille', 'Chou-fleur blanchi gratiné dans une sauce au bouillon de volaille liée au gruyère', ds.id, 'SRC-041-D1',
    'Myko', 'editorial', 4, 20, 40, 'facile',
    NULL, NULL,
    'B', 'candidate', '9775a573edb4fe909b28e9811d143d9e',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3}'::jsonb, ARRAY['bouillon de volaille','fromage affiné','légume crucifère doux']::text[],
    ARRAY['bouillon','beurré','épices douces']::text[], ARRAY['bouquets fondants','sauce fluide et nappante','croûte gratinée']::text[],
    ARRAY['Chou-fleur frais','Gruyère râpé','Bouillon de volaille']::text[], ARRAY['Les bouquets de chou-fleur doivent rester entiers et identifiables sous la sauce : réduits en purée, le plat devient un flan de légume et non un gratin.','C''est le roux beurre-farine qui fait la sauce, pas le liquide qu''on y verse : remplacer le lait par du bouillon reste un gratin, verser un jus de cuisson non lié n''en est plus un.','La couche de fromage gratinée en surface est obligatoire : sans croûte dorée, il ne reste qu''un chou-fleur au velouté.']::text[],
    ARRAY['blanchiment','gratinage']::text[], ARRAY[]::text[], ARRAY['gluten','lait']::text[],
    'Se conserve trois jours au réfrigérateur entre 0 et 4 °C, plat couvert d''un film une fois refroidi. Réchauffer vingt minutes à 160 °C plutôt qu''au micro-ondes, pour retrouver la croûte. La congélation est déconseillée : le chou-fleur relâche son eau et la béchamel tranche à la décongélation.', '{"fridge_hours":72,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-041'), '{"variant_label":"Version au bouillon, comme sur marmiton : remplacer le lait entier par du bouillon de volaille bien chaud pour une sauce plus légère, et ne garder la crème qu''en filet final.","rationale":"Le velouté au bouillon allège franchement le plat et laisse le chou-fleur au premier plan, là où la béchamel le couvrait ; en contrepartie la sauce est plus fluide, moins couvrante, et se sépare plus vite à l''attente. Le bouillon monte à 600 ml pour reprendre aussi les cent millilitres de crème qui détendaient la béchamel : à 500 ml, le même roux donnerait une sauce plus serrée que celle de la base, et il en manquerait pour recouvrir les bouquets. Le sel demande de la prudence, le bouillon en apportant déjà. Les quarante millilitres de crème versés en filet ne servent qu''à rendre un peu de rondeur en surface, pas à lier : mélangés dans la sauce, ils ne se verraient plus.","operations":[{"op":"substitute","form":"Lait entier","with":"Bouillon de volaille","quantity":600,"unit":"ml","role":"liquide de sauce"},{"op":"set","form":"Crème fraîche liquide entière","quantity":40,"role":"finition"}],"steps":[{"op":"replace","n":4,"instruction":"Faire fondre le reste du beurre à feu doux dans une casserole, verser la farine d''un coup et remuer une bonne minute jusqu''à ce que le mélange mousse sans colorer. Retirer du feu quelques secondes, puis incorporer le bouillon de volaille très chaud en trois fois, en fouettant à chaque ajout : un liquide bouillant sur un roux tiédi se lie sans grumeau, l''inverse demande dix minutes de patience."},{"op":"replace","n":5,"instruction":"Remettre sur feu doux et laisser épaissir cinq à six minutes en fouettant sans arrêt, jusqu''à ce que la sauce voile la spatule. Elle nappera moins franchement qu''une béchamel et c''est normal : le bouillon n''a ni gras ni protéines laitières pour épauler la farine, et il ne faut surtout pas chercher à rattraper cette légèreté en poussant la réduction, sous peine de manquer de sauce au montage. Saler avec prudence — le bouillon a déjà sa part de sel —, poivrer, râper la muscade, puis fouetter hors du feu un tiers du gruyère pour qu''il fonde dans la sauce encore chaude."},{"op":"replace","n":6,"instruction":"Étaler une louche de sauce au fond du plat beurré, ranger les bouquets serrés et tête vers le bas afin que la sauce s''infiltre entre les fleurettes, puis napper du reste jusqu''à recouvrir les sommets. Verser enfin la crème en filet sur toute la surface, sans chercher à la mélanger : c''est elle qui rendra au gratin le peu de rondeur que le bouillon lui a retiré."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'chou fleur frais' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Chou-fleur frais', 650, 'g', 'required',
     'légume principal', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'bouillon de volaille' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Bouillon de volaille', 600, 'ml', 'required',
     'liquide de sauce', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'gruyere rape' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Gruyère râpé', 175, 'g', 'required',
     'fromage', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'beurre doux' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Beurre doux', 40, 'g', 'required',
     'matière grasse', false, 4);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'farine de ble t55' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Farine de blé T55', 35, 'g', 'required',
     'liant', false, 5);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'creme fraiche liquide entiere' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Crème fraîche liquide entière', 40, 'ml', 'required',
     'finition', false, 6);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 6, 'g', 'optional',
     'assaisonnement', true, 7);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'optional',
     'assaisonnement', true, 8);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'muscade moulue' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Muscade moulue', 0.5, 'g', 'optional',
     'épice', true, 9);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir un chou-fleur entier d''environ 1,2 kg chez le primeur : une fois les grosses feuilles retirées et le trognon éliminé, il reste à peu près les 650 g de bouquets utiles. Détacher ces bouquets à la main en gardant une taille régulière, de la grosseur d''une grosse noix, puis les rincer à l''eau froide et les laisser s''égoutter.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Plonger les bouquets dans un grand volume d''eau salée en pleine ébullition et les laisser huit à dix minutes. La pointe d''un couteau doit traverser la tige sans résistance mais le bouquet doit rester ferme : trop cuit, il s''affaissera au four. Égoutter aussitôt et laisser reposer dans la passoire, bouquets retournés, le temps que l''eau s''écoule complètement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Allumer le four à 200 °C en chaleur tournante. Prélever une noisette sur le beurre pour graisser généreusement le fond et les bords d''un plat à gratin.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Faire fondre le reste du beurre à feu doux dans une casserole, verser la farine d''un coup et remuer une bonne minute jusqu''à ce que le mélange mousse sans colorer. Retirer du feu quelques secondes, puis incorporer le bouillon de volaille très chaud en trois fois, en fouettant à chaque ajout : un liquide bouillant sur un roux tiédi se lie sans grumeau, l''inverse demande dix minutes de patience.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Remettre sur feu doux et laisser épaissir cinq à six minutes en fouettant sans arrêt, jusqu''à ce que la sauce voile la spatule. Elle nappera moins franchement qu''une béchamel et c''est normal : le bouillon n''a ni gras ni protéines laitières pour épauler la farine, et il ne faut surtout pas chercher à rattraper cette légèreté en poussant la réduction, sous peine de manquer de sauce au montage. Saler avec prudence — le bouillon a déjà sa part de sel —, poivrer, râper la muscade, puis fouetter hors du feu un tiers du gruyère pour qu''il fonde dans la sauce encore chaude.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Étaler une louche de sauce au fond du plat beurré, ranger les bouquets serrés et tête vers le bas afin que la sauce s''infiltre entre les fleurettes, puis napper du reste jusqu''à recouvrir les sommets. Verser enfin la crème en filet sur toute la surface, sans chercher à la mélanger : c''est elle qui rendra au gratin le peu de rondeur que le bouillon lui a retiré.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Répartir le gruyère restant sur toute la surface et enfourner trente minutes à mi-hauteur. Si le dessus manque de couleur, terminer cinq minutes sous le gril en surveillant. Laisser reposer le plat cinq minutes avant de servir, le temps que la sauce se raffermisse.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-041-D1', 'recipe_family', 'Gratin de chou-fleur au bouillon de volaille',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
