    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Gratin de chou-fleur au curry', 'Chou-fleur blanchi dans une béchamel parfumée au curry, gratinée au gruyère', ds.id, 'SRC-041-D2',
    'Myko', 'editorial', 4, 20, 40, 'facile',
    NULL, NULL,
    'B', 'candidate', '6306dbeb7d202305fad4f44c0ed33359',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":3,"heat":1,"pungency":2,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['lacté crémeux','curry doux','légume crucifère doux']::text[],
    ARRAY['lacté','épices douces','curcuma et coriandre']::text[], ARRAY['bouquets fondants','sauce nappante','croûte gratinée']::text[],
    ARRAY['Chou-fleur frais','Gruyère râpé','Lait entier','Curry en poudre']::text[], ARRAY['Les bouquets de chou-fleur doivent rester entiers et identifiables sous la sauce : réduits en purée, le plat devient un flan de légume et non un gratin.','Le curry se fouette hors du feu et au dernier moment : cuit avec la sauce il devient amer et la sauce grise.','La couche de fromage gratinée en surface est obligatoire : sans croûte dorée, il ne reste qu''un chou-fleur à la béchamel.']::text[],
    ARRAY['blanchiment','gratinage']::text[], ARRAY[]::text[], ARRAY['gluten','lait']::text[],
    'Se conserve trois jours au réfrigérateur entre 0 et 4 °C, plat couvert d''un film une fois refroidi. Réchauffer vingt minutes à 160 °C plutôt qu''au micro-ondes, pour retrouver la croûte. La congélation est déconseillée : le chou-fleur relâche son eau et la béchamel tranche à la décongélation.', '{"fridge_hours":72,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-041'), '{"variant_label":"Version au curry de chefsimon : fouetter une petite cuillerée de curry en poudre dans la béchamel juste avant de napper, en rallongeant d''un peu de lait si la sauce s''épaissit trop.","rationale":"Quatre grammes de curry suffisent à colorer la sauce et à poser une chaleur douce derrière le lacté, sans que le chou-fleur disparaisse dessous. Le mélange contient de l''amidon et de la fécule : il resserre la béchamel, d''où les cinquante millilitres de lait tenus en réserve. Ajouté trop tôt ou cuit longuement, il vire à l''amer et grise la sauce — c''est le seul vrai risque de la variante.","operations":[{"op":"add","form":"Curry en poudre","quantity":4,"unit":"g","role":"épice","optional":false},{"op":"set","form":"Lait entier","quantity":550,"role":"liquide de sauce"}],"steps":[{"op":"replace","n":4,"instruction":"Faire fondre le reste du beurre à feu doux dans une casserole, verser la farine d''un coup et remuer une bonne minute jusqu''à ce que le mélange mousse sans colorer. Retirer du feu quelques secondes, puis incorporer 500 ml de lait tiédi en trois fois, en fouettant à chaque ajout pour éviter les grumeaux. Garder les 50 ml restants de côté : ils serviront peut-être en fin de sauce."},{"op":"replace","n":5,"instruction":"Remettre sur feu doux et laisser épaissir cinq à six minutes en fouettant sans arrêt, jusqu''à ce que la sauce nappe la spatule. La détendre avec la crème, puis avec le lait réservé si elle s''est trop resserrée. Saler, poivrer, râper la muscade, fouetter hors du feu un tiers du gruyère, et n''incorporer le curry en poudre qu''en tout dernier, juste avant de napper : longuement cuit il tourne à l''amer et grise, jeté au dernier moment il garde son parfum entier."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
