    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Gratin de chou-fleur à l''oignon', 'Chou-fleur blanchi dans une béchamel enrichie d''oignons fondus, gratiné au gruyère', ds.id, 'SRC-041-D3',
    'Myko', 'editorial', 4, 25, 48, 'facile',
    NULL, NULL,
    'B', 'candidate', '0dbdf2c43df563dea4c2b23369365ae7',
    '{"sweet":2,"salty":3,"acidic":0,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['lacté crémeux','oignon fondu','fromage affiné']::text[],
    ARRAY['lacté','alliacé','épices douces']::text[], ARRAY['bouquets fondants','sauce nappante piquée d''oignon','croûte gratinée']::text[],
    ARRAY['Chou-fleur frais','Gruyère râpé','Lait entier']::text[], ARRAY['Les bouquets de chou-fleur doivent rester entiers et identifiables sous la sauce : réduits en purée, le plat devient un flan de légume et non un gratin.','L''oignon doit blondir et non brunir : coloré trop loin, il emporte toute la sauce vers l''amer et annule le bénéfice de la variante.','La couche de fromage gratinée en surface est obligatoire : sans croûte dorée, il ne reste qu''un chou-fleur à la béchamel.']::text[],
    ARRAY['blanchiment','gratinage']::text[], ARRAY[]::text[], ARRAY['gluten','lait']::text[],
    'Se conserve trois jours au réfrigérateur entre 0 et 4 °C, plat couvert d''un film une fois refroidi. Réchauffer vingt minutes à 160 °C plutôt qu''au micro-ondes, pour retrouver la croûte. La congélation est déconseillée : le chou-fleur relâche son eau et la béchamel tranche à la décongélation.', '{"fridge_hours":72,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-041'), '{"variant_label":"Version à l''oignon : faire blondir un oignon jaune finement émincé dans le beurre avant d''ajouter la farine, ce qui donne une sauce plus douce et plus sucrée.","rationale":"L''oignon fondu dans le beurre avant le roux sucre la sauce et lui donne une profondeur que le lait seul n''a pas, ce qui adoucit l''amertume propre au chou-fleur. Il coûte huit à dix minutes de feu doux et une vigilance : passé la teinte de miel, il brunit et emmène toute la sauce vers l''amer. Sa présence en morceaux change aussi la texture, qui n''est plus tout à fait lisse sous la fourchette.","operations":[{"op":"add","form":"Oignon jaune cru","quantity":130,"unit":"g","role":"aromate","optional":false}],"steps":[{"op":"replace","n":4,"instruction":"Faire fondre le reste du beurre à feu doux dans une casserole et y laisser blondir l''oignon jaune finement émincé huit à dix minutes, en remuant : il doit devenir translucide puis prendre juste une teinte de miel, sans jamais brunir, faute de quoi la sauce entière tirerait sur l''amer. Verser alors la farine d''un coup et remuer une bonne minute jusqu''à ce que le mélange mousse. Retirer du feu quelques secondes, puis incorporer le lait tiédi en trois fois, en fouettant à chaque ajout pour éviter les grumeaux."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

