     jsonb_build_object('recipe_code', 'SRC-041-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-041-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('0dbdf2c43df563dea4c2b23369365ae7'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":2,"salty":3,"acidic":0,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["lacté crémeux","oignon fondu","fromage affiné"],"aroma_families":["lacté","alliacé","épices douces"],"target_textures":["bouquets fondants","sauce nappante piquée d''oignon","croûte gratinée"],"signature_ingredients":["Chou-fleur frais","Gruyère râpé","Lait entier"],"identity_guardrails":["Les bouquets de chou-fleur doivent rester entiers et identifiables sous la sauce : réduits en purée, le plat devient un flan de légume et non un gratin.","L''oignon doit blondir et non brunir : coloré trop loin, il emporte toute la sauce vers l''amer et annule le bénéfice de la variante.","La couche de fromage gratinée en surface est obligatoire : sans croûte dorée, il ne reste qu''un chou-fleur à la béchamel."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
