  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Gratin de chou-fleur aux noix', 'gratin de chou fleur aux noix', 'France', 'France',
     'meal', 'gratin', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Gratin de chou-fleur aux noix', 'Chou-fleur blanchi dans une béchamel crémeuse avec des noix concassées, gratiné', ds.id, 'SRC-041-D4',
    'Myko', 'editorial', 4, 20, 40, 'facile',
    NULL, NULL,
    'B', 'candidate', '87bcf1aa99d697b4350dc43d4f35c998',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":2,"umami":3,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":3}'::jsonb, ARRAY['lacté crémeux','fromage affiné','noix grillée']::text[],
    ARRAY['lacté','beurré','fruit à coque torréfié']::text[], ARRAY['bouquets fondants','sauce nappante','éclats de noix craquants']::text[],
    ARRAY['Chou-fleur frais','Gruyère râpé','Lait entier']::text[], ARRAY['Les bouquets de chou-fleur doivent rester entiers et identifiables sous la sauce : réduits en purée, le plat devient un flan de légume et non un gratin.','Les noix n''entrent au four que pour les cinq dernières minutes : enfournées d''emblée, leur huile brûle et l''amertume gagne tout le plat.','La couche de fromage gratinée en surface est obligatoire : sans croûte dorée, il ne reste qu''un chou-fleur à la béchamel.']::text[],
    ARRAY['blanchiment','gratinage']::text[], ARRAY[]::text[], ARRAY['gluten','lait','fruits à coque']::text[],
    'Se conserve trois jours au réfrigérateur entre 0 et 4 °C, plat couvert d''un film une fois refroidi. Réchauffer vingt minutes à 160 °C plutôt qu''au micro-ondes ; les noix, elles, ne retrouveront pas leur croquant et auront ramolli dans la sauce — mieux vaut en garder une part à concasser au moment de la seconde table. La congélation est déconseillée : le chou-fleur relâche son eau, la béchamel tranche à la décongélation et les noix deviennent pâteuses.', '{"fridge_hours":72,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-041'), '{"variant_label":"Version croquante : parsemer une poignée de noix grossièrement concassées avec le fromage du dessus, à ajouter en fin de cuisson pour qu''elles ne brûlent pas.","rationale":"Les noix donnent au gratin le contraste de texture qui lui manque, tout en fondu et en croûte molle, et leur amertume légère répond bien au gruyère. Elles ajoutent en revanche cinquante grammes d''un aliment à près de sept cents kilocalories aux cent grammes, ce qui pèse davantage que la poignée ne le laisse croire. Elles imposent aussi de fractionner la cuisson au four et interdisent le réchauffage prolongé, qui les ramollit sans retour.","operations":[{"op":"add","form":"Noix","quantity":50,"unit":"g","role":"garniture croquante","optional":false}],"steps":[{"op":"replace","n":7,"instruction":"Répartir le gruyère restant sur toute la surface et enfourner vingt-cinq minutes à mi-hauteur. Concasser pendant ce temps les noix grossièrement au couteau, en gros éclats plutôt qu''en poudre, les parsemer sur le gratin et remettre au four cinq minutes seulement : au-delà leur huile chauffe et elles tournent à l''amer. Si le dessus manque de couleur, terminer deux minutes sous le gril en surveillant, puis laisser reposer cinq minutes avant de servir."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
