  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir un chou-fleur entier d''environ 1,2 kg chez le primeur : une fois les grosses feuilles retirées et le trognon éliminé, il reste à peu près les 650 g de bouquets utiles. Détacher ces bouquets à la main en gardant une taille régulière, de la grosseur d''une grosse noix, puis les rincer à l''eau froide et les laisser s''égoutter.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Plonger les bouquets dans un grand volume d''eau salée en pleine ébullition et les laisser huit à dix minutes. La pointe d''un couteau doit traverser la tige sans résistance mais le bouquet doit rester ferme : trop cuit, il s''affaissera au four. Égoutter aussitôt et laisser reposer dans la passoire, bouquets retournés, le temps que l''eau s''écoule complètement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Allumer le four à 200 °C en chaleur tournante. Prélever une noisette sur le beurre pour graisser généreusement le fond et les bords d''un plat à gratin.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Faire fondre le reste du beurre à feu doux dans une casserole, verser la farine d''un coup et remuer une bonne minute jusqu''à ce que le mélange mousse sans colorer. Retirer du feu quelques secondes, puis incorporer le lait tiédi en trois fois, en fouettant à chaque ajout pour éviter les grumeaux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Remettre sur feu doux et laisser épaissir cinq à six minutes en fouettant sans arrêt, jusqu''à ce que la sauce nappe la spatule. Détendre avec la crème, saler, poivrer, râper la muscade, puis fouetter hors du feu un tiers du gruyère pour qu''il fonde dans la sauce encore chaude.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Étaler une louche de sauce au fond du plat beurré, ranger les bouquets serrés et tête vers le bas afin que la sauce s''infiltre entre les fleurettes, puis napper du reste de sauce jusqu''à recouvrir les sommets.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Répartir le gruyère restant sur toute la surface et enfourner vingt-cinq minutes à mi-hauteur. Concasser pendant ce temps les noix grossièrement au couteau, en gros éclats plutôt qu''en poudre, les parsemer sur le gratin et remettre au four cinq minutes seulement : au-delà leur huile chauffe et elles tournent à l''amer. Si le dessus manque de couleur, terminer deux minutes sous le gril en surveillant, puis laisser reposer cinq minutes avant de servir.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-041-D4', 'recipe_family', 'Gratin de chou-fleur aux noix',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-041-D4', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-041-D4', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-041-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('87bcf1aa99d697b4350dc43d4f35c998'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":2,"umami":3,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":3},"dominant_flavors":["lacté crémeux","fromage affiné","noix grillée"],"aroma_families":["lacté","beurré","fruit à coque torréfié"],"target_textures":["bouquets fondants","sauce nappante","éclats de noix craquants"],"signature_ingredients":["Chou-fleur frais","Gruyère râpé","Lait entier"],"identity_guardrails":["Les bouquets de chou-fleur doivent rester entiers et identifiables sous la sauce : réduits en purée, le plat devient un flan de légume et non un gratin.","Les noix n''entrent au four que pour les cinq dernières minutes : enfournées d''emblée, leur huile brûle et l''amertume gagne tout le plat.","La couche de fromage gratinée en surface est obligatoire : sans croûte dorée, il ne reste qu''un chou-fleur à la béchamel."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Velouté de lentilles au lard', 'veloute de lentilles au lard', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Velouté de lentilles au lard', 'Lentilles vertes et lardons mixés en velouté crémeux avec carottes et thym', ds.id, 'SRC-042-D1',
    'Myko', 'editorial', 4, 20, 40, 'facile',
    NULL, NULL,
    'B', 'candidate', 'd4b6680ab8d5315a97feae6e5552c0bf',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":3}'::jsonb, ARRAY['fumé','terreux','crème cuite']::text[],
    ARRAY['fumé','herbacé sec','lacté']::text[], ARRAY['moitié veloutée et moitié restée grainée','lardon doré posé entier en surface','liaison crémeuse']::text[],
    ARRAY['Lentille verte sèche, crue','Lardon fumé cru','Thym séché']::text[], ARRAY['Sans lardon fumé, il ne reste que des lentilles mijotées : le fumé du porc est la moitié du nom du plat','Seule la moitié de la casserole passe au mixeur ; tout mixer effacerait la lentille entière et ferait basculer le plat en soupe','Les lardons ne descendent jamais dans le mixeur : ils se posent entiers au dernier moment, faute de quoi leur fumé se dilue et la surface perd son contraste']::text[],
    ARRAY['saisie','mijotage','réduction','mixage']::text[], ARRAY[]::text[], ARRAY['lait']::text[],
    'Trois jours au réfrigérateur à 4 °C dans une boîte fermée, lardons rangés à part pour qu''ils ne s''amollissent pas dans le velouté. La partie mixée épaissit beaucoup en refroidissant : rallonger d''un fond d''eau à la réchauffe douce et fouetter pour la relisser. La congélation est ici déconseillée, la crème n''étant plus facultative et tranchant au dégel — mieux vaut congeler le velouté avant liaison et le remonter au moment de servir.', '{"fridge_hours":72,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-042'), '{"variant_label":"Version veloutée du dossier : mixer la moitié de la casserole, remonter à la crème et remettre les lardons entiers par-dessus","rationale":"Mixer la moitié seulement donne un jus épais qui porte les grains restés entiers, au lieu de la soupe uniforme qu''un mixage complet produirait. La crème cesse d''être facultative et passe de cent cinquante à deux cents grammes : c''est elle qui tient la liaison. Le supplément ne pèse qu''une quarantaine de kilocalories par part, mais la rendre obligatoire en coûte cent dix de plus à qui faisait la version sans. Les lardons ne descendent plus dans le bouillon à mi-cuisson mais se posent entiers en surface, ce qui préserve leur croustillant à condition de les repasser à la poêle avant de servir, et retire au jus une partie du fumé qu''il tirait d''eux.","operations":[{"op":"set","form":"Crème fraîche liquide entière","quantity":200,"role":"liaison","optional":false}],"steps":[{"op":"replace","n":6,"instruction":"Glisser le thym, le laurier et les clous de girofle, porter à petits bouillons puis baisser jusqu''au frémissement. Couvrir aux trois quarts et laisser aller trente-cinq à quarante minutes. Les lardons restent de côté cette fois, à couvert et hors du feu : passés au mixeur avec le reste, leur fumé se dissoudrait dans le velouté au lieu de le couronner. Les garder au chaud trois quarts d''heure les rendrait coriaces — mieux vaut les laisser attendre à température ambiante et les réveiller trente secondes à la poêle au moment de dresser. Ne rien saler à ce stade."},{"op":"replace","n":7,"instruction":"Retirer le laurier et les clous de girofle, prélever la moitié de la casserole et la passer au mixeur plongeant jusqu''à obtenir une purée lisse, sans grain sous la langue. La reverser sur l''autre moitié restée entière et remonter avec la crème, en laissant frémir trois minutes de plus pour qu''elle se lie au jus. Saler enfin, poivrer, répartir les lardons entiers par-dessus sans les enfouir, et parsemer de persil ciselé au moment de porter à table."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
