  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Verser les lentilles dans une passoire, les rincer sous l''eau froide et les étaler un instant sur la main pour écarter un éventuel gravillon. Aucun trempage : il ramollirait la peau et ferait éclater les grains pendant le mijotage.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Éplucher les légumes et les tailler en dés de la taille d''un grain de lentille. Compter environ 210 g de carottes et 170 g d''oignon tels qu''ils sortent du cabas pour obtenir les poids nets indiqués une fois les épluchures parties ; l''ail se pèse gousses nues, soit trois à quatre gousses.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chez le charcutier, demander un morceau de poitrine fumée d''environ 190 g : la couenne ôtée, il reste les 160 g de lardons qui entrent dans le plat. Les détailler en bâtonnets courts, puis les colorer à sec dans une cocotte à fond épais jusqu''à ce que la graisse ait rendu et que les arêtes soient dorées. Les débarrasser et jeter l''excédent de gras fondu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Remettre la cocotte sur feu moyen avec l''huile d''olive, y faire fondre carotte, oignon et échalote sans les brunir, une bonne poignée de minutes, jusqu''à ce qu''ils deviennent translucides. Ajouter l''ail haché et poursuivre trente secondes, le temps qu''il embaume.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter les lentilles égouttées et les remuer une minute dans les légumes gras : elles doivent se laquer et prendre le parfum du fond de cocotte avant tout liquide. Mouiller avec un litre d''eau froide, en ajoutant de quoi couvrir de deux doigts si besoin.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Glisser le thym, le laurier et les clous de girofle, porter à petits bouillons puis baisser jusqu''au frémissement. Couvrir aux trois quarts et laisser aller trente-cinq à quarante minutes. Les lardons restent de côté cette fois, à couvert et hors du feu : passés au mixeur avec le reste, leur fumé se dissoudrait dans le velouté au lieu de le couronner. Les garder au chaud trois quarts d''heure les rendrait coriaces — mieux vaut les laisser attendre à température ambiante et les réveiller trente secondes à la poêle au moment de dresser. Ne rien saler à ce stade.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Retirer le laurier et les clous de girofle, prélever la moitié de la casserole et la passer au mixeur plongeant jusqu''à obtenir une purée lisse, sans grain sous la langue. La reverser sur l''autre moitié restée entière et remonter avec la crème, en laissant frémir trois minutes de plus pour qu''elle se lie au jus. Saler enfin, poivrer, répartir les lardons entiers par-dessus sans les enfouir, et parsemer de persil ciselé au moment de porter à table.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-042-D1', 'recipe_family', 'Velouté de lentilles au lard',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-042-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-042-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-042-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('d4b6680ab8d5315a97feae6e5552c0bf'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":3},"dominant_flavors":["fumé","terreux","crème cuite"],"aroma_families":["fumé","herbacé sec","lacté"],"target_textures":["moitié veloutée et moitié restée grainée","lardon doré posé entier en surface","liaison crémeuse"],"signature_ingredients":["Lentille verte sèche, crue","Lardon fumé cru","Thym séché"],"identity_guardrails":["Sans lardon fumé, il ne reste que des lentilles mijotées : le fumé du porc est la moitié du nom du plat","Seule la moitié de la casserole passe au mixeur ; tout mixer effacerait la lentille entière et ferait basculer le plat en soupe","Les lardons ne descendent jamais dans le mixeur : ils se posent entiers au dernier moment, faute de quoi leur fumé se dilue et la surface perd son contraste"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Lentilles corail au lard', 'lentilles corail au lard', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Lentilles corail au lard', 'Lentilles corail mijotées avec lardons fumés, carottes et oignons au thym', ds.id, 'SRC-042-D2',
    'Myko', 'editorial', 4, 20, 25, 'facile',
    NULL, NULL,
    'B', 'candidate', 'b0b09f1d343ca05380b0bd11ddf5a252',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['fumé','terreux']::text[],
    ARRAY['fumé','herbacé sec','végétal cuit']::text[], ARRAY['lentille délitée en purée','lardon doré aux arêtes croustillantes','jus épais lié par l''amidon du grain']::text[],
    ARRAY['Lentille corail sèche, crue','Lardon fumé cru','Thym séché']::text[], ARRAY['Sans lardon fumé, il ne reste que des lentilles mijotées : le fumé du porc est la moitié du nom du plat','La corail se défait par nature et c''est tout le propos de la variante, mais elle interdit de dépasser vingt-cinq minutes, au-delà desquelles il ne reste qu''une bouillie sans relief','Le sel ne s''ajoute qu''en fin de cuisson et à petite dose, le lard ayant déjà salé le bouillon']::text[],
    ARRAY['saisie','mijotage','réduction']::text[], ARRAY[]::text[], ARRAY['lait']::text[],
    'Trois jours au réfrigérateur à 4 °C dans une boîte fermée ; les lentilles boivent leur jus en refroidissant, rallonger d''un fond d''eau à la réchauffe douce. Congélation possible deux mois à condition de n''avoir pas mis la crème, celle-ci tranchant à la décongélation : la verser plutôt après réchauffage.', '{"fridge_hours":72,"eat_immediately":false,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed+manual"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-042'), '{"variant_label":"Avec de la lentille corail, qui se délite en purée en une vingtaine de minutes et donne un plat plus fondant que grainé","rationale":"La corail est décortiquée : elle n''a plus de peau pour tenir le grain et se défait en purée, ce qui lie le jus toute seule et raccourcit la cuisson de quarante à vingt-cinq minutes. Le plat y perd sa mâche et le contraste entre la lentille ferme et le lardon fondant, qui faisait une partie de son intérêt. Il faut aussi mouiller moins — huit cents millilitres au lieu d''un litre — et remuer, la corail accrochant au fond dès qu''elle commence à se déliter.","operations":[{"op":"substitute","form":"Lentille verte sèche, crue","with":"Lentille corail sèche, crue","quantity":320,"unit":"g","role":"légumineuse"}],"steps":[{"op":"replace","n":1,"instruction":"Verser les lentilles dans une passoire et les rincer sous l''eau froide jusqu''à ce que l''eau cesse de blanchir : décortiquées, elles rendent beaucoup d''amidon en surface, et l''emporter dans la cocotte ferait mousser le bouillon. Aucun trempage — elles n''en ont pas besoin et se déferaient avant même d''avoir cuit."},{"op":"replace","n":5,"instruction":"Ajouter les lentilles égouttées et les remuer une minute dans les légumes gras : elles doivent se laquer et prendre le parfum du fond de cocotte avant tout liquide. Mouiller avec 800 ml d''eau froide seulement, un doigt au-dessus du niveau des grains : la corail boit moins longtemps que la verte et un litre donnerait une soupe."},{"op":"replace","n":6,"instruction":"Glisser le thym, le laurier et les clous de girofle, porter à petits bouillons puis baisser jusqu''au frémissement. Couvrir aux trois quarts et compter vingt minutes seulement, en remettant les lardons au bout de dix pour qu''ils parfument sans se dessécher. Passer la spatule plate sur le fond de temps à autre : la corail y accroche dès qu''elle commence à se défaire. Ne rien saler à ce stade."},{"op":"replace","n":7,"instruction":"Goûter : les grains ont perdu leur forme et s''écrasent en purée sous la langue, le jus s''étant épaissi de lui-même sans qu''on ait rien lié. Retirer le laurier et les clous de girofle, saler enfin, poivrer, et verser la crème pour arrondir encore si on le souhaite, en laissant frémir trois minutes de plus. Parsemer de persil ciselé au moment de porter à table."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
