  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Verser les lentilles dans une passoire et les rincer sous l''eau froide jusqu''à ce que l''eau cesse de blanchir : décortiquées, elles rendent beaucoup d''amidon en surface, et l''emporter dans la cocotte ferait mousser le bouillon. Aucun trempage — elles n''en ont pas besoin et se déferaient avant même d''avoir cuit.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Éplucher les légumes et les tailler en dés de la taille d''un grain de lentille. Compter environ 210 g de carottes et 170 g d''oignon tels qu''ils sortent du cabas pour obtenir les poids nets indiqués une fois les épluchures parties ; l''ail se pèse gousses nues, soit trois à quatre gousses.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chez le charcutier, demander un morceau de poitrine fumée d''environ 190 g : la couenne ôtée, il reste les 160 g de lardons qui entrent dans le plat. Les détailler en bâtonnets courts, puis les colorer à sec dans une cocotte à fond épais jusqu''à ce que la graisse ait rendu et que les arêtes soient dorées. Les débarrasser et jeter l''excédent de gras fondu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Remettre la cocotte sur feu moyen avec l''huile d''olive, y faire fondre carotte, oignon et échalote sans les brunir, une bonne poignée de minutes, jusqu''à ce qu''ils deviennent translucides. Ajouter l''ail haché et poursuivre trente secondes, le temps qu''il embaume.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter les lentilles égouttées et les remuer une minute dans les légumes gras : elles doivent se laquer et prendre le parfum du fond de cocotte avant tout liquide. Mouiller avec 800 ml d''eau froide seulement, un doigt au-dessus du niveau des grains : la corail boit moins longtemps que la verte et un litre donnerait une soupe.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Glisser le thym, le laurier et les clous de girofle, porter à petits bouillons puis baisser jusqu''au frémissement. Couvrir aux trois quarts et compter vingt minutes seulement, en remettant les lardons au bout de dix pour qu''ils parfument sans se dessécher. Passer la spatule plate sur le fond de temps à autre : la corail y accroche dès qu''elle commence à se défaire. Ne rien saler à ce stade.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Goûter : les grains ont perdu leur forme et s''écrasent en purée sous la langue, le jus s''étant épaissi de lui-même sans qu''on ait rien lié. Retirer le laurier et les clous de girofle, saler enfin, poivrer, et verser la crème pour arrondir encore si on le souhaite, en laissant frémir trois minutes de plus. Parsemer de persil ciselé au moment de porter à table.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-042-D2', 'recipe_family', 'Lentilles corail au lard',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-042-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-042-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-042-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('b0b09f1d343ca05380b0bd11ddf5a252'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["fumé","terreux"],"aroma_families":["fumé","herbacé sec","végétal cuit"],"target_textures":["lentille délitée en purée","lardon doré aux arêtes croustillantes","jus épais lié par l''amidon du grain"],"signature_ingredients":["Lentille corail sèche, crue","Lardon fumé cru","Thym séché"],"identity_guardrails":["Sans lardon fumé, il ne reste que des lentilles mijotées : le fumé du porc est la moitié du nom du plat","La corail se défait par nature et c''est tout le propos de la variante, mais elle interdit de dépasser vingt-cinq minutes, au-delà desquelles il ne reste qu''une bouillie sans relief","Le sel ne s''ajoute qu''en fin de cuisson et à petite dose, le lard ayant déjà salé le bouillon"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Lentilles au lard à l''huile d''olive', 'lentilles au lard a l huile d olive', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Lentilles au lard à l''huile d''olive', 'Lentilles vertes et lardons cuits à l''huile d''olive, assaisonnés au poivre noir en finition', ds.id, 'SRC-042-D3',
    'Myko', 'editorial', 4, 20, 40, 'facile',
    NULL, NULL,
    'B', 'candidate', '65e6e1dd2ea39ee50709b09f9431c680',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":3,"freshness":2,"intensity":3}'::jsonb, ARRAY['fumé','terreux','huile d''olive fruitée']::text[],
    ARRAY['fumé','herbacé sec','végétal cuit']::text[], ARRAY['lentille fondante restée entière','lardon doré aux arêtes croustillantes','jus court et lustré']::text[],
    ARRAY['Lentille verte sèche, crue','Lardon fumé cru','Thym séché']::text[], ARRAY['Sans lardon fumé, il ne reste que des lentilles mijotées : le fumé du porc est la moitié du nom du plat','Les grains doivent tenir entiers ; passés au mixeur, le plat bascule en velouté et change d''identité','L''huile de finition se verse hors du feu et à cru : chauffée, elle ne lustre plus rien et le plat perd le seul relief qui remplace la crème']::text[],
    ARRAY['saisie','mijotage','réduction']::text[], ARRAY[]::text[], ARRAY[]::text[],
    'Trois jours au réfrigérateur à 4 °C dans une boîte fermée ; les lentilles boivent leur jus en refroidissant, rallonger d''un fond d''eau à la réchauffe douce. Refaire le filet d''huile crue et le persil à l''assiette : ceux de la veille ont perdu leur parfum dans le froid. Sans crème, la congélation ne pose aucun problème — deux mois sans que rien ne tranche au dégel.', '{"fridge_hours":72,"eat_immediately":false,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-042'), '{"variant_label":"Sans crème, simplement lustrée d''un filet d''huile d''olive crue et relevée de persil et d''un tour de moulin","rationale":"Sans crème, le jus reste court et franc : le fumé du lard et le terreux de la lentille passent devant, sans le voile lacté qui les arrondissait. Les douze grammes d''huile crue versés hors du feu lustrent les grains et portent les arômes, mais ne lient rien — le plat est plus liquide, et il faut le servir dans une assiette creuse. Le persil cesse d''être facultatif : c''est lui, avec le poivre, qui apporte la fraîcheur que la crème donnait autrement.","operations":[{"op":"remove","form":"Crème fraîche liquide entière"},{"op":"set","form":"Huile d''olive vierge extra","quantity":40,"role":"matière grasse"},{"op":"set","form":"Persil frais","quantity":15,"role":"herbe","optional":false},{"op":"set","form":"Poivre noir moulu","quantity":2,"role":"assaisonnement","optional":false}],"steps":[{"op":"replace","n":4,"instruction":"Remettre la cocotte sur feu moyen avec 28 g de l''huile d''olive, les 12 g restants étant tenus de côté pour la fin, et y faire fondre carotte, oignon et échalote sans les brunir, une bonne poignée de minutes, jusqu''à ce qu''ils deviennent translucides. Ajouter l''ail haché et poursuivre trente secondes, le temps qu''il embaume."},{"op":"replace","n":7,"instruction":"Goûter un grain : il doit céder sous la dent tout en gardant sa forme. Retirer alors le laurier et les clous de girofle, saler enfin et donner un tour de moulin franc. Verser hors du feu l''huile d''olive réservée, à cru, en remuant une seule fois : chauffée, elle perdrait le fruité qui fait tout l''intérêt du geste. Parsemer largement de persil ciselé au moment de porter à table."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'lentille verte seche crue' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
