  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Verser les lentilles dans une passoire, les rincer sous l''eau froide et les étaler un instant sur la main pour écarter un éventuel gravillon. Aucun trempage : il ramollirait la peau et ferait éclater les grains pendant le mijotage.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Éplucher les légumes et les tailler en dés de la taille d''un grain de lentille. Compter environ 210 g de carottes et 170 g d''oignon tels qu''ils sortent du cabas pour obtenir les poids nets indiqués une fois les épluchures parties ; l''ail se pèse gousses nues, soit trois à quatre gousses.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chez le charcutier, demander un morceau de poitrine fumée d''environ 190 g : la couenne ôtée, il reste les 160 g de lardons qui entrent dans le plat. Les détailler en bâtonnets courts, puis les colorer à sec dans une cocotte à fond épais jusqu''à ce que la graisse ait rendu et que les arêtes soient dorées. Les débarrasser et jeter l''excédent de gras fondu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Remettre la cocotte sur feu moyen avec 28 g de l''huile d''olive, les 12 g restants étant tenus de côté pour la fin, et y faire fondre carotte, oignon et échalote sans les brunir, une bonne poignée de minutes, jusqu''à ce qu''ils deviennent translucides. Ajouter l''ail haché et poursuivre trente secondes, le temps qu''il embaume.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter les lentilles égouttées et les remuer une minute dans les légumes gras : elles doivent se laquer et prendre le parfum du fond de cocotte avant tout liquide. Mouiller avec un litre d''eau froide, en ajoutant de quoi couvrir de deux doigts si besoin.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Glisser le thym, le laurier et les clous de girofle, porter à petits bouillons puis baisser jusqu''au frémissement. Couvrir aux trois quarts et laisser aller trente-cinq à quarante minutes, en remettant les lardons à mi-parcours pour qu''ils parfument le bouillon sans se dessécher. Ne rien saler à ce stade.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Goûter un grain : il doit céder sous la dent tout en gardant sa forme. Retirer alors le laurier et les clous de girofle, saler enfin et donner un tour de moulin franc. Verser hors du feu l''huile d''olive réservée, à cru, en remuant une seule fois : chauffée, elle perdrait le fruité qui fait tout l''intérêt du geste. Parsemer largement de persil ciselé au moment de porter à table.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-042-D3', 'recipe_family', 'Lentilles au lard à l''huile d''olive',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-042-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-042-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-042-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('65e6e1dd2ea39ee50709b09f9431c680'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":3,"freshness":2,"intensity":3},"dominant_flavors":["fumé","terreux","huile d''olive fruitée"],"aroma_families":["fumé","herbacé sec","végétal cuit"],"target_textures":["lentille fondante restée entière","lardon doré aux arêtes croustillantes","jus court et lustré"],"signature_ingredients":["Lentille verte sèche, crue","Lardon fumé cru","Thym séché"],"identity_guardrails":["Sans lardon fumé, il ne reste que des lentilles mijotées : le fumé du porc est la moitié du nom du plat","Les grains doivent tenir entiers ; passés au mixeur, le plat bascule en velouté et change d''identité","L''huile de finition se verse hors du feu et à cru : chauffée, elle ne lustre plus rien et le plat perd le seul relief qui remplace la crème"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Morue à la Brás', 'morue a la bras', 'Portugal', 'Portugal',
     'meal', 'plat au four', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Morue à la Brás', 'Morue effeuillée saisie avec des pommes de terre frites en fins bâtonnets et liée aux œufs brouillés', ds.id, 'SRC-043-D1',
    'Myko', 'editorial', 4, 40, 35, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '5867febc72431d6395a179926de05656',
    '{"sweet":1,"salty":3,"acidic":1,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['salin marin','oignon doux fondu','œuf crémeux','huile d''olive fruitée']::text[],
    ARRAY['marin','alliacé','herbacé','laurier']::text[], ARRAY['morue effeuillée en pétales','allumettes de pomme de terre dorées et encore fermes','liaison d''œuf à peine prise']::text[],
    ARRAY['Morue salée sèche','Pomme de terre crue, épluchée','Huile d''olive vierge extra']::text[], ARRAY['La morue salée sèche doit être dessalée vingt-quatre heures puis pochée avant d''être effeuillée à la main : sans ce dessalage, le plat est immangeable, et sans effeuillage il perd sa texture en pétales.','Les pommes de terre se taillent en allumettes et se frient crues : cuites d''abord puis sautées, elles s''écrasent dans la liaison et le plat devient une purée à l''œuf.','L''œuf est ajouté cru, hors ébullition et au dernier instant : dès qu''il prend en morceaux fermes, ce n''est plus une Brás mais une brouillade de morue.','L''huile d''olive vierge extra est le seul corps gras du plat : introduire du beurre ou de la crème ferait sortir la recette de son répertoire.']::text[],
    ARRAY['pochage','effeuillage','friture peu profonde','liaison aux œufs']::text[], ARRAY[]::text[], ARRAY['poisson','œuf']::text[],
    'Se mange à la sortie de la poêle : la liaison d''œuf continue de prendre tant que le plat est chaud et tourne sèche et granuleuse en quelques minutes. Un reste se garde 24 heures au réfrigérateur à 4 °C en boîte fermée, mais il se réchauffe très doucement à la poêle avec une cuillerée d''eau, jamais au micro-ondes qui achèverait de coaguler l''œuf. La congélation est à écarter : les allumettes frites ramollissent et l''œuf pris rend son eau à la décongélation.', '{"fridge_hours":24,"eat_immediately":true,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-043'), '{"variant_label":"Version à la Brás : la morue effeuillée est sautée avec des pommes de terre taillées en allumettes puis liée aux œufs battus à feu très doux, sans passage au four.","rationale":"Le plat change entièrement de structure : il ne se monte plus en étages au four, il se lie à la poêle. Les pommes de terre passent de rondelles pochées à des allumettes frites, ce qui impose de partir de tubercules crus et fait presque doubler l''huile ; les œufs, durs et tranchés dans la base, deviennent crus et battus pour napper le mélange. On gagne une texture crémeuse et une fin de cuisson qui tient en dix minutes à la poêle — le dessalage de la veille, lui, reste dû —, on perd la croûte gratinée et toute possibilité de le préparer à l''avance : une Brás qui attend se dessèche.","operations":[{"op":"substitute","form":"Pomme de terre cuite","with":"Pomme de terre crue, épluchée","quantity":600,"unit":"g","role":"féculent"},{"op":"set","form":"Huile d''olive vierge extra","quantity":90},{"op":"set","form":"Œuf cru","quantity":250,"role":"liaison"}],"steps":[{"op":"replace","n":4,"instruction":"Peler environ 700 g de pommes de terre crues, dont il reste à peu près 600 g de chair épluchée, et les tailler en bâtonnets de la taille d''une allumette. Les rincer à grande eau froide pour emporter l''amidon de surface, puis les sécher longuement dans un torchon : une allumette humide ne dore pas, elle bout dans sa propre vapeur et retombe molle."},{"op":"replace","n":5,"instruction":"Casser les œufs dans un bol et les battre à la fourchette juste le temps de mêler blancs et jaunes, sans chercher à les faire mousser. Trop d''air et la liaison prendrait comme une omelette au lieu d''enrober la morue."},{"op":"replace","n":7,"instruction":"Verser le reste de l''huile dans une grande poêle, la chauffer jusqu''à ce qu''un bâtonnet grésille aussitôt, et frire les allumettes par petites poignées deux à trois minutes, jusqu''à ce qu''elles dorent et raidissent ; les égoutter au fur et à mesure sur du papier absorbant. Faire glisser l''oignon à l''ail de la sauteuse dans cette poêle, y ajouter les pétales de morue et les réchauffer une minute sans les défaire, puis rendre les allumettes au mélange au tout dernier instant, pour qu''elles n''aient pas le temps de ramollir."},{"op":"replace","n":8,"instruction":"Baisser au plus faible et verser les œufs battus d''un seul geste, en remuant sans arrêt à la spatule : ils doivent napper la morue et les allumettes d''une crème à peine prise, jamais se rassembler en morceaux fermes. Poivrer, goûter avant de saler, puis parsemer de persil ciselé et d''olives noires et servir immédiatement, la poêle continuant de cuire tant qu''elle est chaude."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'morue salee seche' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Morue salée sèche', 380, 'g', 'required',
     'protéine', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
