  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'La veille, immerger les 500 g de dos de morue salée sèche achetés chez le poissonnier dans un grand volume d''eau froide, peau vers le haut, et réserver vingt-quatre heures au réfrigérateur en renouvelant l''eau quatre fois : sans ce dessalage, le plat reste beaucoup trop salin pour être mangé.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Le jour même, égoutter les morceaux, les déposer dans une casserole d''eau froide non salée avec les feuilles de laurier, monter jusqu''au premier frémissement, couper la source de chaleur et laisser la chair finir de raffermir dix minutes dans l''eau chaude.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Sortir la morue, la laisser tiédir sur une planche, ôter la peau puis palper la chair pour extraire toutes les arêtes, et l''effeuiller à la main en larges pétales : les 500 g pesés à l''achat donnent environ 380 g de chair nette.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Cuire environ 600 g de pommes de terre entières et non pelées vingt minutes dans le bouillon de pochage réservé, les peler encore tièdes et les détailler en rondelles d''un demi-centimètre ; il en reste à peu près 480 g de chair prête à monter.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Plonger quatre gros œufs (environ 240 g en coquille) dix minutes dans une eau frémissante, les rafraîchir aussitôt, les écaler et les trancher en rondelles régulières.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Chauffer un tiers de l''huile d''olive dans une sauteuse et y laisser fondre ensemble l''oignon émincé et le poivron rouge épépiné puis taillé en lanières, une douzaine de minutes à feu moyen : le poivron doit s''assouplir sans se défaire, car il lui reste une heure de four à traverser. Ajouter l''ail haché et prolonger deux minutes le temps que le parfum monte.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Huiler un plat à four et monter deux étages successifs : rondelles de pomme de terre, pétales de morue, oignon au poivron, rondelles de tomate débarrassées de leurs graines, rondelles d''œuf et olives, en filant un peu d''huile d''olive sur chaque étage. Épépiner la tomate n''est pas un raffinement : ses graines rendent une eau acide qui délave le plat sur une cuisson aussi longue. Poivrer, et ne saler qu''après avoir goûté un pétale de morue.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Enfourner une heure à 220 °C, sans couvrir : le légume rend son eau puis la reprend en concentrant, et le dessus prend une croûte franchement colorée, presque noircie sur les crêtes — c''est la marque de cette version rustique, qu''une cuisson prudente manquerait. Parsemer de persil ciselé et porter à table sans attendre.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-043-D2', 'recipe_family', 'Morue au four à la tomate et au poivron',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-043-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-043-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-043-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('7e72aa7d1f8075c4ff94fd50d78d386e'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":3,"acidic":1,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":3,"freshness":1,"intensity":3},"dominant_flavors":["salin marin","oignon doux fondu","huile d''olive fruitée"],"aroma_families":["marin","alliacé","herbacé","laurier"],"target_textures":["morue effeuillée en pétales","pomme de terre fondante","surface légèrement dorée"],"signature_ingredients":["Morue salée sèche","Pomme de terre cuite","Huile d''olive vierge extra"],"identity_guardrails":["La morue salée sèche doit être dessalée vingt-quatre heures puis pochée avant d''être effeuillée à la main : sans ce dessalage, le plat est immangeable, et sans effeuillage il perd sa texture en pétales.","Les rondelles de pomme de terre cuite forment la structure en couches du plat ; réduites en purée ou remplacées par du riz, ce n''est plus une morue à la portugaise.","L''huile d''olive vierge extra est le seul corps gras du montage : introduire du beurre ou de la crème ferait sortir la recette de son répertoire."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Moules marinières au jus lié', 'moules marinieres au jus lie', 'France', 'France',
     'meal', 'plat de fruits de mer', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Moules marinières au jus lié', 'Moules cuites dans le vin blanc et beurre, dont le jus est lié à une farine pour une sauce courte', ds.id, 'SRC-044-D1',
    'Myko', 'editorial', 4, 20, 15, 'facile',
    NULL, NULL,
    'B', 'candidate', '7d1d921f306425372d59f54442f0a7d0',
    '{"sweet":1,"salty":4,"acidic":3,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":3,"freshness":3,"intensity":3}'::jsonb, ARRAY['iodé','vineux','aillé','beurré']::text[],
    ARRAY['marin','alliacé','herbacé','vineux']::text[], ARRAY['chair tendre et charnue','jus court et fluide']::text[],
    ARRAY['Moule commune crue','Vin blanc sec','Persil frais']::text[], ARRAY['Sans moules fraîches cuites dans leur coquille, le plat n''existe plus : la chair préparée à part ou décoquillée à l''avance perd le jus qui fait la marinière','Le mouillement doit rester un vin blanc sec : le remplacer par de la crème, du curry ou un fond fait basculer la recette vers les moules à la crème','Le jus ne se sale pas d''avance : l''eau de mer relâchée par les coquillages est l''assaisonnement principal','Le persil s''ajoute cru en fin de cuisson, jamais cuit avec les aromates']::text[],
    ARRAY['singer','liaison au roux','réduction','pochage','cuisson à couvert']::text[], ARRAY[]::text[], ARRAY['mollusques','lait','gluten','sulfites','céleri']::text[],
    'Se mange dans la foulée. Les restes se gardent 24 heures maximum au réfrigérateur à 4 °C, décoquillés et immergés dans leur jus filtré, puis se réchauffent très brièvement à feu doux sans jamais bouillir. La congélation des moules cuites en coquille est déconseillée : la chair devient caoutchouteuse à la décongélation. Seul le jus de cuisson filtré se congèle bien, jusqu''à trois mois, et sert de base à une sauce ou à un risotto.', '{"fridge_hours":24,"eat_immediately":true,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-044'), '{"variant_label":"Marinière liée : saupoudrer une cuillerée de farine sur les aromates fondus avant de mouiller au vin, pour un jus plus nappant","rationale":"Quinze grammes de farine cuite dans le beurre suffisent à faire tenir le jus sur la cuillère au lieu de le laisser courir au fond de l''assiette. La contrepartie est double : le jus perd un peu de sa franchise marine, que l''amidon adoucit, et le plat cesse d''être sans gluten. La farine doit cuire une minute pleine et le vin entrer en trois fois, faute de quoi le bouillon garde un goût de cru et des grumeaux qu''aucune cuisson ultérieure ne rattrape.","operations":[{"op":"add","form":"Farine de blé T55","quantity":15,"unit":"g","role":"liaison","optional":false}],"steps":[{"op":"replace","n":4,"instruction":"Faire fondre le beurre à feu doux dans une grande marmite. Y laisser fondre l''oignon, l''ail et le céleri pendant 4 à 5 minutes en remuant, sans jamais leur laisser prendre de couleur. Saupoudrer alors la farine en pluie et remuer une minute pleine : elle doit boire tout le beurre et perdre son goût de cru avant le moindre mouillement."},{"op":"replace","n":5,"instruction":"Mouiller au vin blanc en trois fois, en fouettant à chaque ajout jusqu''à ce que le liquide redevienne lisse : versé d''un coup sur la farine chaude, il ferait des grumeaux que rien ne défera ensuite. Pousser le feu et laisser bouillonner deux minutes à découvert pour évaporer l''alcool ; le bouillon épaissit déjà légèrement."},{"op":"replace","n":9,"instruction":"Servir sans attendre, directement dans la marmite ou réparti en assiettes creuses, en nappant chaque part d''un jus qui tient maintenant aux coquilles au lieu de glisser dessus. Prévoir du pain : lié, ce jus se ramasse à la mie plus qu''il ne se boit."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
