  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Demander au boucher quatre tranches de jarret de veau d''environ 280 g pièce, coupées épais et gardées sur l''os : cela représente à peu près 1,1 kg sur la balance, pour environ 800 g de viande une fois l''os central déduit. Éponger les tranches, puis entailler en trois ou quatre endroits la membrane qui les ceinture, sans quoi elles se recroquevillent à la chaleur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Saler et poivrer les deux faces, puis éponger les tranches une dernière fois jusqu''à ce qu''elles soient sèches au toucher : rien n''enrobe plus la viande, et une surface humide se contente de blanchir au lieu de colorer. Chauffer l''huile d''olive seule dans une cocotte à fond épais jusqu''à ce qu''elle ondule, et y coucher les tranches à plat, sans qu''elles se touchent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Colorer à feu moyen trois à quatre minutes par face, un peu plus longtemps qu''à l''ordinaire puisque la viande est nue, jusqu''à une croûte franchement dorée. Débarrasser ensuite sur une assiette en posant les morceaux os vers le haut pour que la moelle reste en place.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Détailler en petits dés réguliers les trois légumes aromatiques — carotte, céleri, puis oignon — et les verser dans la cocotte encore grasse avec l''ail écrasé. Les laisser fondre huit minutes à feu doux en raclant le fond pour décoller les sucs, sans chercher à les colorer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser le vin blanc, remonter le feu et laisser bouillonner jusqu''à ce que l''odeur d''alcool ait disparu et que le liquide ait diminué de moitié.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Écraser les tomates pelées à la fourchette et les ajouter avec leur jus, puis le concentré, le bouillon, le thym et les feuilles de laurier. Remettre les tranches à plat dans la cocotte, os vers le haut, et les arroser : le liquide doit affleurer la viande sans la noyer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Couvrir, régler sur un frémissement à peine visible et compter une heure et demie. Retourner les tranches à mi-parcours et ajouter un fond d''eau chaude si la sauce attache. La viande est prête lorsqu''une fourchette la sépare de l''os sans effort.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Pendant ce temps, hacher très finement le persil avec une gousse d''ail réservée et le zeste de citron, puis garder ce mélange cru et à couvert jusqu''au service.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Retirer les tranches et les tenir au chaud, ôter le laurier et les branches de thym, puis pousser le feu et réduire la sauce à découvert dix à quinze minutes, jusqu''à ce qu''elle nappe le dos d''une cuillère. C''est la seule liaison dont dispose cette version : l''écourter laisse un jus qui se sépare dans l''assiette. Goûter, rectifier le sel, napper la viande et parsemer la gremolata au tout dernier moment, hors du feu.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-045-D2', 'recipe_family', 'Osso buco à l''huile d''olive',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-045-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-045-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-045-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('96a9aba8ed6f3e60226f7d6ae375455c'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":1,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":2,"intensity":3},"dominant_flavors":["veau braisé","tomate cuite longuement","vin blanc réduit","zeste de citron"],"aroma_families":["agrume","aromates séchés","légumes racines fondus"],"target_textures":["viande fondante se détachant de l''os","sauce nappante","moelle onctueuse"],"signature_ingredients":["Jarret de veau cru, en tranches avec os","Vin blanc sec","Tomate entière pelée en conserve","Zeste de citron"],"identity_guardrails":["Le veau doit rester en tranches épaisses avec l''os et sa moelle : désossé, ou remplacé par un autre morceau, ce n''est plus un osso buco.","Le mouillement se fait au vin blanc sec et jamais au vin rouge, sinon la sauce vire au ragoût et perd son acidité claire.","La gremolata, persil et ail et zeste de citron hachés, s''ajoute crue au moment de servir : cuite, elle disparaît et le plat perd son relief.","La cuisson est longue, à couvert et à frémissement : un feu vif raccourcit le temps mais laisse la viande ferme et attachée à l''os."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Osso buco aux agrumes et aux anchois', 'osso buco aux agrumes et aux anchois', 'Italie', 'Italie',
     'meal', 'plat mijoté', 'documented_variation', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Osso buco aux agrumes et aux anchois', 'Jarret de veau braisé avec une gremolata d''agrumes et d''anchois en finition', ds.id, 'SRC-045-D3',
    'Myko', 'editorial', 4, 30, 90, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '153d1c766523f1720db094cd8e117f34',
    '{"sweet":1,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":2,"intensity":3}'::jsonb, ARRAY['veau braisé','tomate cuite longuement','vin blanc réduit','zeste de citron']::text[],
    ARRAY['agrume','aromates séchés','légumes racines fondus']::text[], ARRAY['viande fondante se détachant de l''os','sauce nappante','moelle onctueuse']::text[],
    ARRAY['Jarret de veau cru, en tranches avec os','Vin blanc sec','Tomate entière pelée en conserve','Zeste de citron']::text[], ARRAY['Le veau doit rester en tranches épaisses avec l''os et sa moelle : désossé, ou remplacé par un autre morceau, ce n''est plus un osso buco.','Le mouillement se fait au vin blanc sec et jamais au vin rouge, sinon la sauce vire au ragoût et perd son acidité claire.','La gremolata, persil et ail et zeste de citron hachés, s''ajoute crue au moment de servir : cuite, elle disparaît et le plat perd son relief.','La cuisson est longue, à couvert et à frémissement : un feu vif raccourcit le temps mais laisse la viande ferme et attachée à l''os.']::text[],
    ARRAY['saisie','déglaçage','mijotage','réduction']::text[], ARRAY[]::text[], ARRAY['gluten','lait','poisson','sulfites','céleri']::text[],
    'Se garde trois jours au réfrigérateur à 4 °C, viande immergée dans sa sauce en boîte hermétique, et gagne à être réchauffée doucement le lendemain. La viande et la sauce se congèlent ensemble jusqu''à trois mois ; la gremolata, elle, ne supporte ni le froid négatif ni l''attente et se refait au moment de servir.', '{"fridge_hours":72,"eat_immediately":false,"freezable":true,"freezer_months":3,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-045'), '{"variant_label":"Version agrumes et anchois, relevée par une page du dossier : ajouter des quartiers de citron et d''orange lavés et quelques filets d''anchois en cours de mijotage.","rationale":"Les anchois fondent entièrement dans la sauce et n''y laissent aucun goût de poisson : ils y déposent du sel et de l''umami, ce qui oblige à diviser par deux le sel prévu. Les quartiers d''agrumes cuits avec leur écorce donnent un parfum plus large et plus amer que le zeste cru de la gremolata, à condition de les retirer au bout d''une heure — au-delà, l''écorce cède son amertume au jus et ne la reprend pas. Le plat devient nettement plus tranchant, et il faut accepter qu''il porte désormais un allergène de plus.","operations":[{"op":"add","form":"Citron jaune frais","quantity":120,"unit":"g","role":"agrume","optional":false},{"op":"add","form":"Orange fraîche","quantity":200,"unit":"g","role":"agrume","optional":false},{"op":"add","form":"Anchois à l''huile, égoutté","quantity":30,"unit":"g","role":"condiment","optional":false},{"op":"set","form":"Sel fin","quantity":4}],"steps":[{"op":"insert","after":6,"instruction":"Brosser le citron et l''orange sous l''eau chaude pour ôter la cire de leur peau, puisqu''ils vont cuire écorce comprise, et couper chaque fruit en quartiers dans le sens de la hauteur. Écraser les anchois à la pointe du couteau jusqu''à les réduire en pâte, les délayer dans une louche de sauce chaude prélevée dans la cocotte, puis reverser le tout et glisser les quartiers entre les tranches de viande."},{"op":"replace","n":7,"instruction":"Couvrir, régler sur un frémissement à peine visible et compter une heure et demie. Retourner les tranches à mi-parcours et ajouter un fond d''eau chaude si la sauce attache. Retirer les quartiers d''agrumes au bout de la première heure, avant que leur écorce ne verse son amertume dans le jus. La viande est prête lorsqu''une fourchette la sépare de l''os sans effort."},{"op":"replace","n":9,"instruction":"Retirer les tranches et les tenir au chaud, ôter le laurier et les branches de thym, puis faire réduire la sauce à découvert quelques minutes si elle reste trop fluide. Goûter longuement avant de saler : les anchois ont disparu dans le jus mais y ont laissé tout leur sel, et la moitié de la dose prévue suffit presque toujours. Napper la viande et parsemer la gremolata au tout dernier moment, hors du feu."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
