  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoyez environ 850 g d''aubergines entières chez le primeur, soit deux belles pièces : une fois le pédoncule coupé et les extrémités parées, il reste à peu près les 750 g de chair utile de la liste. Lavez-les, essuyez-les et détaillez-les dans la longueur en tranches d''environ 8 mm, peau comprise.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Empilez les tranches en couches dans une passoire en salant légèrement chaque couche au gros sel, posez dessus une assiette lestée d''un poids et laissez la chair rendre son eau 45 minutes au-dessus de l''évier. Rincez ensuite à l''eau froide et épongez chaque tranche jusqu''à ce qu''elle soit sèche au toucher : ce sel-là s''en va avec l''amertume et ne compte pas dans l''assaisonnement du plat.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pendant ce temps, comptez à peu près 750 g de tomates mûres entières pour arriver aux 633 g de pulpe annoncés. Entaillez-les en croix, plongez-les 30 secondes dans l''eau frémissante puis dans l''eau glacée, retirez peau, pédoncule et graines, et concassez grossièrement la chair.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Dans une sauteuse, faites tomber l''oignon haché et l''ail dégermé finement émincé dans un tiers de l''huile d''olive, à feu doux et sans coloration. Ajoutez la pulpe de tomate et la feuille de laurier, puis laissez réduire à découvert 25 à 30 minutes, en remuant de temps en temps, jusqu''à ce que la sauce tienne sur la cuillère. Retirez le laurier, rectifiez avec une partie du sel et du poivre, puis incorporez la moitié du basilic ciselé hors du feu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Réservez un œuf pour la panure et battez-le à la fourchette dans une assiette creuse ; versez la chapelure dans une seconde assiette, en en réservant environ 15 g pour la finition. Passez chaque tranche d''aubergine dans l''œuf battu, laissez l''excédent s''égoutter, puis pressez-la des deux côtés dans la chapelure pour obtenir une couche fine et régulière.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Plongez les trois œufs restants dix minutes dans une eau frémissante, rafraîchissez-les aussitôt sous l''eau froide pour arrêter net la cuisson et éviter le cerne verdâtre autour du jaune, écalez-les et coupez-les en rondelles régulières. Détaillez le jambon en lanières très fines, presque en fils : coupé épais, il ferait une semelle entre les couches au lieu de s''y fondre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Chauffez une large poêle avec un fond d''huile d''olive et saisissez les tranches panées par petites fournées, deux à trois minutes par face, jusqu''à une couleur noisette franche. Débarrassez-les au fur et à mesure sur du papier absorbant et ajoutez un filet d''huile entre chaque tournée plutôt que tout d''un coup.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Préchauffez le four à 190 °C. Nappez le fond d''un plat à gratin d''une louche de sauce, couchez une première rangée de tranches côte à côte, répartissez dessus quelques rondelles d''œuf dur et une poignée de fils de jambon, parsemez de mozzarella coupée en dés et d''un peu de parmesan râpé, puis recouvrez de sauce. Répétez en croisant le sens des tranches à chaque étage, jusqu''à épuisement, et comptez vos rondelles dès le premier niveau pour qu''il en reste à tous les autres.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Terminez par une couche de sauce, le reste du parmesan et la chapelure réservée, puis enfournez 35 à 40 minutes : le plat doit frémir sur les bords et la surface prendre une croûte dorée. Si elle colore trop vite, posez une feuille d''aluminium pendant les dix dernières minutes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 10, 'Sortez le plat et laissez-le reposer au moins 15 minutes avant de le découper, le temps que les couches se tiennent. Répartissez le basilic restant en feuilles entières juste avant de servir, pour garder son parfum.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-046-D3', 'recipe_family', 'Parmigiana napolitaine à l''œuf dur',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-046-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-046-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-046-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('bb878a3c38266f0819bbb1066c6a095f'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":2,"intensity":3},"dominant_flavors":["tomate cuite","fromage affiné","aubergine dorée"],"aroma_families":["herbacé","lacté","végétal grillé"],"target_textures":["fondant","filant","croûte gratinée"],"signature_ingredients":["Aubergine fraîche","Tomate fraîche mûre","Mozzarella","Parmesan affiné","Basilic frais"],"identity_guardrails":["Les aubergines doivent être dégorgées puis dorées avant montage : montées crues, le plat rend de l''eau et cesse d''être une parmigiana.","Le duo mozzarella fondante et parmesan affiné est obligatoire ; un seul fromage, ou un fromage à gratin neutre, casse l''identité du plat.","Ni béchamel ni pâtes : ce n''est pas un gratin de lasagnes, la structure repose uniquement sur les tranches d''aubergine et la sauce tomate."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Petits pois à l''anglaise, laitue étuvée et oignons glacés', 'petits pois a l anglaise laitue etuvee et oignons glaces', 'France', 'France',
     'meal', 'légume mijoté', 'documented_variation', 'fresh_herbal',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Petits pois à l''anglaise, laitue étuvée et oignons glacés', 'Petits pois mijotés avec laitue, oignons blancs et oignons grelots glacés', ds.id, 'SRC-047-D1',
    'Myko', 'editorial', 4, 30, 35, 'facile',
    NULL, NULL,
    'B', 'candidate', '822b4aecdeea9567f76c109d746413f5',
    '{"sweet":3,"salty":2,"acidic":0,"bitter":1,"umami":2,"heat":0,"pungency":1,"richness":3,"freshness":5,"intensity":2}'::jsonb, ARRAY['douceur végétale du petit pois','beurre frais','oignon glacé']::text[],
    ARRAY['végétal frais','lacté beurré','herbacé anisé']::text[], ARRAY['petit pois ferme à la peau intacte','laitue tombée et soyeuse','oignon grelot fondant sous un sirop clair']::text[],
    ARRAY['Petit pois surgelé','Laitue fraîche','Beurre doux']::text[], ARRAY['Pois et laitue cuisent séparément mais se servent ensemble : servir la laitue à part, en légume distinct, ferait sortir le plat de sa famille.','Le refroidissement à l''eau glacée n''est pas une commodité mais la raison d''être de cette version : sans lui les pois continuent de cuire et rejoignent le fondant terne de la cuisson à l''étouffée.','Les oignons grelots sont glacés à blanc, jamais à brun : une caramélisation, même légère, apporterait une amertume grillée que ce plat ne porte pas.','Ni crème ni farine : la liaison vient uniquement du beurre froid incorporé hors du feu.']::text[],
    ARRAY['mijotage','réduction','émulsion']::text[], ARRAY[]::text[], ARRAY['lait']::text[],
    'Se garde 2 à 3 jours au réfrigérateur à 4 °C dans une boîte hermétique, et se réchauffe à couvert sur feu très doux avec une cuillère d''eau. La congélation est déconseillée : la laitue rend son eau et se défait, et les pois, déjà congelés une fois, s''écrasent à la décongélation.', '{"fridge_hours":48,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-047'), '{"variant_label":"Version Chef Simon : pois cuits à l''anglaise puis rafraîchis à l''eau glacée, laitue étuvée séparément au beurre, les deux réunis au dernier moment et complétés de petits oignons glacés à blanc.","rationale":"Cuits à l''anglaise puis saisis dans l''eau glacée, les pois gardent un vert franc et une peau qui résiste sous la dent, là où la cuisson à l''étouffée de la base les mène au fondant et au vert éteint. Le prix est double : une part du sucre du pois s''en va dans l''eau de cuisson et n''entre jamais dans le jus, et le plat perd son unité — trois casseroles au lieu d''une, trois surveillances, et une réunion de dernière minute qui ne pardonne pas l''attente. Les oignons grelots glacés à blanc apportent une douceur ronde et une masse végétale supplémentaire, mais réclament vingt minutes de conduite à part et une épluchure fastidieuse.","operations":[{"op":"add","form":"Oignon grelot cru","quantity":200,"unit":"g","role":"garniture","optional":false},{"op":"set","form":"Beurre doux","quantity":70,"role":"matière grasse","optional":false},{"op":"set","form":"Sucre semoule","quantity":10,"role":"assaisonnement"}],"steps":[{"op":"replace","n":3,"instruction":"Pelez l''oignon blanc et débitez-le en lamelles très fines. Dégermez la gousse d''ail et hachez-la menu. Pelez ensuite les oignons grelots sans entamer leur base : c''est elle qui les tient entiers pendant le glaçage, et un bulbe entamé se défait en pétales. Trente secondes dans l''eau bouillante décollent la première peau et vous épargnent dix minutes de lutte. Ciselez le cerfeuil et réservez-le à couvert, il n''interviendra qu''à la toute fin."},{"op":"replace","n":4,"instruction":"Rangez les oignons grelots en une seule couche dans une petite sauteuse, ajoutez 20 g de beurre, 5 g de sucre et de l''eau à mi-hauteur, puis couvrez d''un rond de papier cuisson percé au centre. Laissez frémir une vingtaine de minutes : l''eau part peu à peu, le beurre et le sucre restent et enrobent les bulbes d''un sirop clair. Surveillez la fin — le glaçage à blanc ne doit prendre aucune couleur, et il passe au blond en trente secondes d''inattention. Réservez-les tièdes."},{"op":"replace","n":5,"instruction":"Portez une grande casserole d''eau salée à gros bouillons et jetez-y les petits pois encore glacés. Comptez cinq à sept minutes à découvert dès la reprise de l''ébullition, puis égouttez-les et plongez-les aussitôt dans un saladier d''eau additionnée de glaçons : le froid brutal fixe la couleur et arrête net une cuisson qui, sans lui, se poursuivrait dans la chaleur des grains. Égouttez de nouveau dès qu''ils sont froids, sans les laisser tremper."},{"op":"replace","n":6,"instruction":"Dans la cocotte, faites tiédir 20 g de beurre à feu très doux et jetez-y les lardons cinq minutes sans qu''ils prennent couleur, puis l''oignon blanc et l''ail pour cinq minutes de plus. Ajoutez les rubans de laitue, le sel, le poivre blanc et le sucre restant, couvrez et laissez étuver douze à quinze minutes sans une goutte d''eau : la salade rend la sienne et tombe en compote souple. Découvrez et laissez filer ce jus jusqu''à un fond sirupeux."},{"op":"replace","n":7,"instruction":"Réunissez tout au tout dernier moment, sur la laitue étuvée bien chaude : les pois froids d''abord, les oignons glacés ensuite, une minute à feu vif en secouant la cocotte, le temps de les remettre à température et pas davantage. Coupez le feu et incorporez les 30 g de beurre restants, très froids et coupés en dés, en imprimant à la cocotte un mouvement circulaire jusqu''à ce que le jus nappe. Réunir tard est tout le principe de cette version : les pois n''ont pas le temps de ternir dans le fond de cuisson."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

