  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Les 400 g indiqués sont du grain net, prêt à cuire. Avec des pois surgelés, sortez simplement le sachet du congélateur : nul besoin de les décongeler. Si vous partez de pois frais, prévoyez environ 1,1 kg de cosses à l''achat, le rendement en grains tournant autour de 35 %, et écossez-les juste avant de cuisiner.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Débarrassez deux petites laitues d''environ 300 g pièce de leurs feuilles extérieures flétries et de leur pied dur : il doit vous rester à peu près 200 g de feuilles nettes. Rincez-les à l''eau froide, essorez-les soigneusement puis taillez-les en larges rubans.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pelez l''oignon blanc et débitez-le en lamelles très fines. Dégermez la gousse d''ail et hachez-la menu. Ciselez le cerfeuil et réservez-le à couvert, il n''interviendra qu''à la toute fin.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Sortez le beurre une bonne heure à l''avance et travaillez-le à la fourchette jusqu''à la consistance d''une pommade souple, qui s''étale sans couler. Un beurre encore ferme roulerait sur les légumes en copeaux au lieu de les enrober, et c''est cet enrobage qui fait toute la version. Réservez-en un quart pour la fin et mettez le reste dans un grand saladier.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Jetez dans ce saladier les petits pois encore glacés, les rubans de laitue, l''oignon en lamelles, l''ail haché et les lardons, puis le sucre et le sel. Roulez le tout à pleines mains jusqu''à ce que chaque grain soit luisant de gras. Couvrez et laissez reposer une demi-heure au réfrigérateur : le sel tire l''eau des légumes, et c''est elle seule qui fournira la vapeur — n''ajoutez rien d''autre, surtout pas d''eau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Versez la préparation dans la cocotte, tassez sans écraser et fermez non pas avec le couvercle mais avec une assiette creuse remplie d''eau froide, bien calée sur le bord. Menez à feu très doux vingt-cinq à trente minutes : la vapeur monte, rencontre le fond froid de l''assiette, s''y condense et retombe en pluie sur les légumes. Tendez l''oreille plutôt que de soulever — un chuintement régulier signale que tout va bien, un grésillement sec que le feu est trop vif.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Retirez l''assiette avec précaution, en la tenant par les bords : son dessous est brûlant quand son creux est encore tiède, et l''eau qu''elle porte se renverse pour un rien. Jugez du jus au fond de la cocotte : s''il en reste trop, montez le feu une minute à découvert. Coupez le feu et incorporez en trois fois le beurre pommade réservé, en secouant la cocotte par son anse ; il fond dans la chaleur restante et lie le fond de cuisson en un jus court.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Rectifiez le sel, parsemez le cerfeuil ciselé au dernier moment pour qu''il garde son parfum, et servez aussitôt dans un plat creux en versant tout le jus par-dessus.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-047-D2', 'recipe_family', 'Petits pois au beurre pommade',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-047-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-047-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-047-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('d9831628067d9aa38f20a75ab7b0a82e'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"fresh_herbal","scores":{"sweet":3,"salty":2,"acidic":0,"bitter":1,"umami":2,"heat":0,"pungency":1,"richness":3,"freshness":4,"intensity":2},"dominant_flavors":["douceur végétale du petit pois","beurre frais","oignon fondu"],"aroma_families":["végétal frais","lacté beurré","herbacé anisé"],"target_textures":["petit pois fondant qui garde sa peau","laitue tombée et soyeuse","jus court et nappant"],"signature_ingredients":["Petit pois surgelé","Laitue fraîche","Beurre doux"],"identity_guardrails":["Sans la laitue braisée avec les pois, ce ne sont plus des petits pois à la française mais de simples petits pois au beurre.","Le mouillement doit rester un fond d''eau réduit en jus court et monté au beurre : noyer les légumes dans du bouillon fait perdre au plat sa concentration sucrée.","Ni crème ni farine : la liaison vient uniquement du beurre froid incorporé hors du feu."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Petits pois à la laitue au beurre', 'petits pois a la laitue au beurre', 'France', 'France',
     'meal', 'légume mijoté', 'documented_variation', 'fresh_herbal',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Petits pois à la laitue au beurre', 'Petits pois avec laitue effilée dans un beurre monté, sans oignons grelots', ds.id, 'SRC-047-D3',
    'Myko', 'editorial', 4, 20, 25, 'facile',
    NULL, NULL,
    'B', 'candidate', '2ecfc9f21748ac6e958536b9532caac1',
    '{"sweet":3,"salty":2,"acidic":0,"bitter":1,"umami":2,"heat":0,"pungency":1,"richness":3,"freshness":4,"intensity":2}'::jsonb, ARRAY['douceur végétale du petit pois','beurre frais','oignon fondu']::text[],
    ARRAY['végétal frais','lacté beurré','herbacé anisé']::text[], ARRAY['petit pois fondant qui garde sa peau','laitue tombée et soyeuse','jus court et nappant']::text[],
    ARRAY['Petit pois surgelé','Laitue fraîche','Beurre doux']::text[], ARRAY['Sans la laitue braisée avec les pois, ce ne sont plus des petits pois à la française mais de simples petits pois au beurre.','Le mouillement doit rester un fond d''eau réduit en jus court et monté au beurre : noyer les légumes dans du bouillon fait perdre au plat sa concentration sucrée.','Ni crème ni farine : la liaison vient uniquement du beurre froid incorporé hors du feu.']::text[],
    ARRAY['mijotage','réduction','émulsion']::text[], ARRAY[]::text[], ARRAY['lait']::text[],
    'Se garde 2 à 3 jours au réfrigérateur à 4 °C dans une boîte hermétique, et se réchauffe à couvert sur feu très doux avec une cuillère d''eau. La congélation est déconseillée : la laitue rend son eau et se défait, et les pois, déjà congelés une fois, s''écrasent à la décongélation.', '{"fridge_hours":48,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-047'), '{"variant_label":"Sans lardons pour une garniture entièrement maigre, en compensant par une noisette de beurre supplémentaire à la fin.","rationale":"Le plat devient entièrement végétarien et perd d''un coup le sel fumé et la graisse de porc qui donnaient au fond de cuisson sa profondeur : ce qui reste est plus net, plus vert, franchement plus court en bouche. Les quinze grammes de beurre ajoutés rattrapent la texture du jus, qui nappe toujours, mais rien ne rattrape le fumé — il faut l''accepter plutôt qu''essayer de le remplacer. La garniture aromatique doit compenser par le temps ce qu''elle a perdu en gras, d''où un fondu d''oignon mené plus longuement.","operations":[{"op":"remove","form":"Lardon fumé cru"},{"op":"set","form":"Beurre doux","quantity":65,"role":"matière grasse","optional":false}],"steps":[{"op":"replace","n":4,"instruction":"Faites tiédir un tiers du beurre dans une cocotte à fond épais, à feu très doux, et jetez-y directement l''oignon et l''ail. Laissez-les fondre huit à dix minutes en remuant de temps en temps : privée de la graisse fumée qui parfumait le fond, la garniture aromatique doit donner seule tout ce qu''elle a, et cela demande du temps plus que du feu. L''oignon doit devenir translucide et sucré, jamais doré."},{"op":"replace","n":7,"instruction":"Découvrez et montez le feu une minute ou deux pour faire partir l''excédent de liquide, jusqu''à ce qu''il ne reste qu''un fond sirupeux au niveau des légumes. Coupez alors le feu et incorporez le beurre restant, très froid et coupé en dés, en imprimant à la cocotte un mouvement circulaire. Il y en a un tiers de plus que dans la recette d''origine et c''est voulu : il porte désormais seul le gras du plat, et c''est lui qui décide si le jus nappe ou reste de l''eau."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
