      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 4, 'g', 'optional',
     'assaisonnement', true, 8);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre blanc moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre blanc moulu', 1, 'g', 'optional',
     'assaisonnement', true, 9);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Les 400 g indiqués sont du grain net, prêt à cuire. Avec des pois surgelés, sortez simplement le sachet du congélateur : nul besoin de les décongeler. Si vous partez de pois frais, prévoyez environ 1,1 kg de cosses à l''achat, le rendement en grains tournant autour de 35 %, et écossez-les juste avant de cuisiner.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Débarrassez deux petites laitues d''environ 300 g pièce de leurs feuilles extérieures flétries et de leur pied dur : il doit vous rester à peu près 200 g de feuilles nettes. Rincez-les à l''eau froide, essorez-les soigneusement puis taillez-les en larges rubans.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pelez l''oignon blanc et débitez-le en lamelles très fines. Dégermez la gousse d''ail et hachez-la menu. Ciselez le cerfeuil et réservez-le à couvert, il n''interviendra qu''à la toute fin.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Faites tiédir un tiers du beurre dans une cocotte à fond épais, à feu très doux, et jetez-y directement l''oignon et l''ail. Laissez-les fondre huit à dix minutes en remuant de temps en temps : privée de la graisse fumée qui parfumait le fond, la garniture aromatique doit donner seule tout ce qu''elle a, et cela demande du temps plus que du feu. L''oignon doit devenir translucide et sucré, jamais doré.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Versez les petits pois encore glacés par-dessus, puis les rubans de laitue, le sucre, le sel et le poivre blanc. Mouillez de 10 cl d''eau seulement : le légume doit cuire dans sa propre vapeur et dans l''eau que rend la salade, pas nager dans un bouillon.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Couvrez, ramenez à léger frémissement et laissez aller de 20 à 25 minutes à petit feu, en secouant la cocotte par son anse toutes les cinq minutes plutôt qu''en remuant à la cuillère, ce qui écraserait les grains. Les pois doivent céder sans résistance sous la pression du doigt.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Découvrez et montez le feu une minute ou deux pour faire partir l''excédent de liquide, jusqu''à ce qu''il ne reste qu''un fond sirupeux au niveau des légumes. Coupez alors le feu et incorporez le beurre restant, très froid et coupé en dés, en imprimant à la cocotte un mouvement circulaire. Il y en a un tiers de plus que dans la recette d''origine et c''est voulu : il porte désormais seul le gras du plat, et c''est lui qui décide si le jus nappe ou reste de l''eau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Rectifiez le sel, parsemez le cerfeuil ciselé au dernier moment pour qu''il garde son parfum, et servez aussitôt dans un plat creux en versant tout le jus par-dessus.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-047-D3', 'recipe_family', 'Petits pois à la laitue au beurre',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-047-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-047-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-047-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('2ecfc9f21748ac6e958536b9532caac1'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"fresh_herbal","scores":{"sweet":3,"salty":2,"acidic":0,"bitter":1,"umami":2,"heat":0,"pungency":1,"richness":3,"freshness":4,"intensity":2},"dominant_flavors":["douceur végétale du petit pois","beurre frais","oignon fondu"],"aroma_families":["végétal frais","lacté beurré","herbacé anisé"],"target_textures":["petit pois fondant qui garde sa peau","laitue tombée et soyeuse","jus court et nappant"],"signature_ingredients":["Petit pois surgelé","Laitue fraîche","Beurre doux"],"identity_guardrails":["Sans la laitue braisée avec les pois, ce ne sont plus des petits pois à la française mais de simples petits pois au beurre.","Le mouillement doit rester un fond d''eau réduit en jus court et monté au beurre : noyer les légumes dans du bouillon fait perdre au plat sa concentration sucrée.","Ni crème ni farine : la liaison vient uniquement du beurre froid incorporé hors du feu."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Poulet aux petits pois à la française', 'poulet aux petits pois a la francaise', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'fresh_herbal',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Poulet aux petits pois à la française', 'Cuisses de poulet ajoutées aux petits pois à la française avec laitue et oignons', ds.id, 'SRC-047-D4',
    'Myko', 'editorial', 4, 25, 55, 'facile',
    NULL, NULL,
    'B', 'candidate', '3fd2f4c2e4462926f063b5ef47254778',
    '{"sweet":3,"salty":2,"acidic":0,"bitter":1,"umami":2,"heat":0,"pungency":1,"richness":3,"freshness":4,"intensity":2}'::jsonb, ARRAY['douceur végétale du petit pois','beurre frais','oignon fondu']::text[],
    ARRAY['végétal frais','lacté beurré','herbacé anisé']::text[], ARRAY['petit pois fondant qui garde sa peau','laitue tombée et soyeuse','jus court et nappant']::text[],
    ARRAY['Petit pois surgelé','Laitue fraîche','Beurre doux']::text[], ARRAY['Sans la laitue braisée avec les pois, ce ne sont plus des petits pois à la française mais de simples petits pois au beurre.','Le mouillement doit rester un fond d''eau réduit en jus court et monté au beurre : noyer les légumes dans du bouillon fait perdre au plat sa concentration sucrée.','Ni crème ni farine : la liaison vient uniquement du beurre froid incorporé hors du feu.']::text[],
    ARRAY['mijotage','réduction','émulsion']::text[], ARRAY[]::text[], ARRAY['lait']::text[],
    'Se garde 2 jours au réfrigérateur à 4 °C, volaille et légumes conservés ensemble dans leur jus pour que la chair ne sèche pas, et se réchauffe à couvert sur feu très doux avec une cuillère d''eau. La peau ne redeviendra pas croustillante, autant la retirer avant de réchauffer. Congélation déconseillée : la laitue rend son eau et se défait, et les pois, déjà congelés une fois, s''écrasent à la décongélation.', '{"fridge_hours":48,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-047'), '{"variant_label":"En plat unique : poser une cuisse de poulet avec os et peau sur le lit de légumes en début de cuisson et prolonger à couvert jusqu''à ce que la chair se détache.","rationale":"La garniture devient un plat entier : la volaille cuit sur les légumes, leur donne son jus et sa gélatine, et le fond de cocotte y gagne une longueur que le beurre seul n''atteignait pas. Ce que cela coûte se voit à l''œil — cinquante minutes à couvert, et les pois ont dépassé le fondant, perdu leur vert vif et une partie de leur douceur au profit de la sauce. La peau, elle, ne croustillera jamais sous un couvercle : il faut la colorer d''abord à la poêle, et accepter qu''elle se ramollisse tout de même en partie.","operations":[{"op":"add","form":"Cuisse de poulet crue, avec os, avec peau","quantity":900,"unit":"g","role":"protéine","optional":false}],"steps":[{"op":"replace","n":5,"instruction":"Versez les petits pois encore glacés par-dessus, puis les rubans de laitue, le sucre, le sel et le poivre blanc. Couchez les morceaux de volaille sur ce lit, peau vers le haut, en les enfonçant à peine — s''ils s''immergent, la peau que vous venez de colorer se détrempe. Mouillez de 15 cl d''eau, à peine plus que dans la version en légume seul : la cuisson est deux fois plus longue, mais la viande rendra son propre jus."},{"op":"replace","n":6,"instruction":"Couvrez, ramenez à léger frémissement et laissez aller cinquante minutes à petit feu, en secouant la cocotte par son anse toutes les dix minutes plutôt qu''en remuant. La chair doit se détacher de l''os sans résistance quand on la pousse du dos d''une cuillère. Les pois auront alors largement dépassé le fondant : c''est le prix du plat unique, et il ne sert à rien de raccourcir, une volaille à l''os ne se négocie pas."},{"op":"replace","n":7,"instruction":"Sortez les morceaux de volaille et tenez-les au chaud sous une feuille d''aluminium. Découvrez et montez le feu deux à trois minutes pour faire partir l''excédent de liquide, plus abondant qu''à l''ordinaire, jusqu''à ce qu''il ne reste qu''un fond sirupeux au niveau des légumes. Coupez le feu et incorporez le beurre restant, très froid et coupé en dés, en imprimant à la cocotte un mouvement circulaire : le jus s''épaissit et se met à napper."},{"op":"replace","n":8,"instruction":"Rectifiez le sel — le jus de volaille en a concentré une partie, goûtez avant d''en remettre —, reposez la viande sur les légumes, parsemez le cerfeuil ciselé au dernier moment et servez aussitôt dans un plat creux, une part de volaille par assiette avec sa portion de légumes et tout le jus par-dessus."},{"op":"insert","after":3,"instruction":"Épongez les cuisses de poulet avec un papier absorbant et salez la peau. Posez-les côté peau dans une poêle bien chaude, sans matière grasse ajoutée : elles en portent assez pour se suffire. Laissez-les six à sept minutes sans y toucher, jusqu''à ce que la peau soit dorée et se détache seule du fond. Réservez-les et versez la graisse rendue dans la cocotte, où elle remplacera une part du beurre du départ."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
