  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sucre semoule' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sucre semoule', 10, 'g', 'optional',
     'correcteur d''acidité', true, 12);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'jambon de bayonne' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Jambon de Bayonne', 160, 'g', 'required',
     'charcuterie', false, 13);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoyez environ 600 g de poivrons rouges entiers à l''étal pour arriver aux 500 g de chair utile de la liste. Débarrassez chacun de sa queue, de ses pépins et des membranes claires qui tapissent l''intérieur, puis débitez la chair en lanières d''un bon centimètre de large.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Comptez à l''achat deux gros oignons, soit près de 290 g bruts, pour 250 g une fois pelés. Détaillez-les en demi-lunes fines. Écrasez trois à quatre gousses d''ail sous le plat de la lame, retirez la peau et hachez la pulpe : vous obtenez les 12 g attendus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pour les 500 g de pulpe, partez de 700 g environ de tomates bien mûres. Coupez-les en deux à l''équateur et frottez la face ouverte sur une râpe à gros trous, la peau restant entière dans votre main : la chair tombe râpée dans le bol et vous évitez l''ébouillantage.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Versez l''huile d''olive dans une sauteuse large et posez sur feu doux. Jetez-y les oignons et laissez-les s''attendrir sept à huit minutes en remuant : ils doivent devenir translucides et souples, sans jamais prendre de couleur blonde.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajoutez les lanières de poivron, mélangez pour les enrober de gras, couvrez et poursuivez à feu modéré une dizaine de minutes. Remuez deux ou trois fois pendant ce temps : les lanières perdent leur raideur et commencent à se coucher au fond.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Incorporez la pulpe de tomate râpée, l''ail haché, le thym, les feuilles de laurier et le piment d''Espelette. Salez d''une main très légère — la moitié de ce que réclamerait la fondue seule, car la charcuterie qui la rejoindra tout à l''heure en apporte largement pour deux — et donnez un tour de poivre. Découvrez et laissez réduire vingt minutes à petits bouillons, en raclant régulièrement le fond à la spatule.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'La préparation est prête quand elle a perdu son eau et qu''un sillon tracé à la spatule tient quelques secondes avant de se refermer. Goûtez : si la tomate mord trop, corrigez avec le sucre semoule, par petites pincées seulement. Retirez les feuilles de laurier.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Chauffez une poêle sèche à feu vif et saisissez-y les tranches de jambon de Bayonne trente secondes par face, le temps qu''elles se raidissent et lâchent un peu de leur gras. N''allez pas plus loin : une seconde de trop et elles durcissent en copeaux cassants. Débitez-les en lanières d''un bon centimètre, jetez-les dans la fondue avec le gras resté au fond de la poêle et mélangez.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Cassez quatre œufs de calibre moyen, ce qui donne les 200 g de contenu attendus une fois les coquilles écartées, et battez-les à la fourchette avec une pointe de sel. Baissez le feu au minimum sous la sauteuse avant de continuer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 10, 'Versez les œufs battus sur la fondue de légumes et remuez sans interruption avec une spatule souple. Coupez le feu dès que l''ensemble prend une consistance crémeuse et encore souple, la chaleur résiduelle finissant le travail. Servez immédiatement, avec du pain de campagne.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-048-D1', 'recipe_family', 'Piperade au jambon de Bayonne',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-048-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-048-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-048-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('c7292bb13a97b48411c3ed068da269ca'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":3,"salty":2,"acidic":2,"bitter":0,"umami":3,"heat":1,"pungency":2,"richness":3,"freshness":1,"intensity":3},"dominant_flavors":["poivron doux confit","tomate mûre","ail","piment doux"],"aroma_families":["végétal cuit","fruité","épicé doux"],"target_textures":["fondant","nappant","moelleux"],"signature_ingredients":["Poivron rouge frais","Tomate râpée","Piment d''Espelette moulu"],"identity_guardrails":["Le poivron rouge fondu longuement à l''huile d''olive est la base du plat : sans lui il ne reste qu''une sauce tomate aux œufs.","Le piment d''Espelette signe l''origine basque ; le remplacer par un piment fort ou par du paprika déplace le plat hors de son identité.","Les légumes doivent être menés jusqu''à la fondue, ni laissés croquants ni réduits en purée mixée.","Les œufs sont brouillés dans les légumes et restent crémeux : cuits en omelette prise à part, ce n''est plus une piperade."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Piperade en fondue, sans œufs', 'piperade en fondue sans oeufs', 'France', 'France',
     'meal', 'accompagnement', 'documented_variation', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Piperade en fondue, sans œufs', 'Fondue de poivrons et tomates au piment d''Espelette sans œufs, servie en accompagnement', ds.id, 'SRC-048-D2',
    'Myko', 'editorial', 4, 18, 28, 'facile',
    NULL, NULL,
    'B', 'candidate', 'd20d5c99b276d37018837e239a29e2fa',
    '{"sweet":3,"salty":2,"acidic":3,"bitter":0,"umami":3,"heat":2,"pungency":2,"richness":2,"freshness":1,"intensity":3}'::jsonb, ARRAY['poivron doux confit','tomate mûre','ail','piment doux']::text[],
    ARRAY['végétal cuit','fruité','épicé doux']::text[], ARRAY['fondant','nappant','compoté']::text[],
    ARRAY['Poivron rouge frais','Tomate râpée','Piment d''Espelette moulu']::text[], ARRAY['Le poivron rouge fondu longuement à l''huile d''olive est la base de la préparation : sans lui il ne reste qu''une sauce tomate.','Le piment d''Espelette signe l''origine basque ; le remplacer par un piment fort ou par du paprika déplace la préparation hors de son identité.','Les légumes doivent être menés jusqu''à la fondue, ni laissés croquants ni réduits en purée mixée.','La réduction va plus loin que dans la version complète, puisque plus rien ne viendra ensuite absorber le liquide : une fondue restée humide détremperait l''assiette qu''elle accompagne.']::text[],
    ARRAY['mijotage','réduction']::text[], ARRAY[]::text[], ARRAY[]::text[],
    'Se garde 4 jours au réfrigérateur à 4 °C dans un contenant fermé, et se congèle très bien 3 mois : la fondue de légumes réduite ne souffre pas de la décongélation, contrairement à la version liée aux œufs qui, elle, ne se garde qu''une journée. Réchauffez à feu doux en remuant, ou servez tiède. Si elle a rendu de l''eau au réfrigérateur, laissez-la repasser deux minutes à découvert avant de servir.', '{"fridge_hours":96,"eat_immediately":false,"freezable":true,"freezer_months":3,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-048'), '{"variant_label":"Fondue de piperade sans œuf : arrêter la recette à la fin de la réduction et servir la préparation en accompagnement d''un poulet basquaise, d''une morue ou d''un thon grillé.","rationale":"Arrêtée à la réduction, la préparation cesse d''être un plat pour devenir une garniture : elle perd la protéine et l''onctuosité qui la tenaient en assiette, et gagne en netteté ce qu''elle abandonne en rondeur. Le poivron et la tomate ne sont plus adoucis par rien, si bien que l''acidité et le piment ressortent nettement et demandent d''être goûtés à nouveau en fin de course. En échange, elle se garde quatre jours au lieu de vingt-quatre heures, se congèle sans dommage et sort de la liste des allergènes.","operations":[{"op":"remove","form":"Œuf cru"}],"steps":[{"op":"remove","n":8},{"op":"replace","n":9,"instruction":"Goûtez une dernière fois et rectifiez avant de servir : la fondue se juge désormais toute seule, sans rien qui vienne en arrondir l''acidité ni le piquant, et supporte volontiers une pincée de sel et un tour de moulin de plus qu''à l''ordinaire. Servez-la brûlante à côté d''un poulet basquaise, d''une morue ou d''un thon grillé — ou tiède le lendemain, ce qui lui va tout aussi bien, sa saveur s''étant rassemblée pendant la nuit."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
