      WHERE ff.canonical_name_normalized = 'chou blanc frais' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Chou blanc frais', 800, 'g', 'required',
     'légume', false, 1);

