  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Parer le chou : d''une pomme achetée entière d''environ 1,1 kg, jeter les feuilles extérieures fatiguées et creuser le trognon à la pointe du couteau, ce qui laisse à peu près 800 g de feuilles utilisables. Fendre en quartiers, dégager la côte centrale trop dure et rincer à grande eau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Immerger les quartiers de chou dans un grand volume d''eau bouillante non salée, compter deux à trois minutes dès que l''ébullition repart, puis les cueillir à l''écumoire et les rafraîchir sous le robinet froid. Les laisser s''égoutter, côte vers le bas : ce passage arrondit l''amertume et rend le plat plus digeste.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Gratter les légumes-racines. Prévoir environ 600 g de carottes et 500 g de navets à l''achat pour obtenir respectivement 500 g et 400 g nets une fois épluchés et les bouts retirés. Débiter les carottes en gros tronçons de quatre centimètres, les navets en quartiers, de façon que tout cuise au même rythme.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Peler les oignons. En piquer un de tous les clous de girofle, en enfonçant chaque tête dans la chair jusqu''à ce qu''elle tienne seule ; couper l''autre en deux. Écraser les gousses d''ail d''un coup de paume, sans chercher à les peler complètement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Coucher les saucisses de Morteau et de Montbéliard entières au fond d''une grande cocotte, sans jamais les piquer, et les recouvrir de trois bons doigts d''eau froide. Ajouter l''oignon clouté, l''oignon fendu et l''ail, puis monter tout doucement en température.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Dès que la surface frissonne, cueillir la mousse grise à la louche jusqu''à ce que le bouillon redevienne net. Maintenir ensuite un frémissement paresseux, couvercle posé de biais, pendant quarante-cinq minutes : une ébullition franche ferait éclater la peau des saucisses et troublerait le liquide. Ne rien saler à ce stade, la charcuterie fumée s''en charge.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Rincer les lentilles vertes à l''eau froide, sans les faire tremper. Les faire glisser dans le bouillon en même temps que les carottes et les navets, remuer une fois pour qu''elles ne s''agglutinent pas au fond, et laisser aller vingt-cinq minutes. Surveiller le niveau du liquide, qui descend beaucoup plus vite qu''à l''ordinaire, et compléter à l''eau bouillante dès que les légumes se découvrent. Ajouter alors les quartiers de chou blanchis et les pommes de terre pelées — compter à peu près 750 g de tubercules achetés pour les 600 g de chair attendus — et poursuivre trente minutes, jusqu''à ce que la lame d''un couteau traverse une pomme de terre sans buter.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Goûter le bouillon avant toute correction : selon la salaison des saucisses, les 10 g de sel fin prévus seront de trop ou tout juste nécessaires, alors les incorporer par petites pincées successives. Donner un tour de moulin de poivre noir moulu et couper le feu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Sortir les saucisses, les trancher en rondelles épaisses et les disposer au centre d''un plat creux bien chaud. Ranger les légumes autour par familles, puis verser les lentilles à la louche dans le creux du plat, où elles retiendront le bouillon qu''elles n''ont pas déjà bu. Servir aussitôt : le liquide restant est trop épais pour la soupière et se sert directement sur l''assiette, une louche par convive.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-050-D2', 'recipe_family', 'Potée auvergnate aux lentilles vertes',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-050-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-050-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-050-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('d8050162fcb8e5b8e0625219fedb9320'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":4,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3},"dominant_flavors":["porc fumé","chou braisé","bouillon salé","légume-racine sucré"],"aroma_families":["fumé","épices chaudes","végétal cuit"],"target_textures":["légumes fondants","pomme de terre farineuse","saucisse ferme et juteuse","bouillon clair"],"signature_ingredients":["Chou vert frais","Saucisse de Morteau","Saucisse de Montbéliard","Pomme de terre cuite"],"identity_guardrails":["Sans chou, ce n''est plus une potée : c''est lui qui structure le plat et parfume le bouillon en retour.","La charcuterie doit être fumée et pochée entière ; remplacer Morteau et Montbéliard par une viande fraîche non fumée efface le goût de cochonnaille qui fait le plat.","Les légumes cuisent dans le bouillon des viandes, jamais dans une eau neuve : c''est cet échange qui distingue la potée d''un simple pot-au-feu de légumes.","Pas de liaison ni de crème : le bouillon reste clair et se sert tel quel."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
