  VALUES
    ('Ratatouille confite au four', 'ratatouille confite au four', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Ratatouille confite au four', 'Légumes méditerranéens confits séparément puis réunis et confits au four à basse température', ds.id, 'SRC-051-D1',
    'Myko', 'editorial', 4, 30, 60, 'facile',
    NULL, NULL,
    'B', 'candidate', '550f93e7d2947e8358d0cb39d27d3658',
    '{"sweet":3,"salty":2,"acidic":2,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":3}'::jsonb, ARRAY['tomate cuite','poivron confit','ail','huile d''olive']::text[],
    ARRAY['herbacé méditerranéen','végétal grillé','aillé']::text[], ARRAY['dés fondants gardant leur forme','sauce courte et nappante']::text[],
    ARRAY['Aubergine fraîche','Courgette fraîche','Poivron rouge frais','Tomate fraîche mûre','Huile d''olive vierge extra']::text[], ARRAY['Les quatre légumes d''été — aubergine, courgette, poivron, tomate — sont indissociables : en retirer un fait sortir du plat.','L''huile d''olive est le seul corps gras admis ; beurre ou crème déplacent la recette vers une autre famille.','Aucun bouillon ni liquide ajouté : la liaison vient de l''eau et des sucs rendus par les légumes eux-mêmes.','Ni viande ni féculent dans la cocotte, sous peine de basculer vers un ragoût ou une poêlée composée.']::text[],
    ARRAY['saisie','mijotage','réduction']::text[], ARRAY[]::text[], ARRAY[]::text[],
    'Trois à quatre jours au réfrigérateur à 4 °C dans un contenant hermétique ; le goût se raffermit après une nuit de repos. Se congèle jusqu''à trois mois, mais les courgettes relâchent beaucoup d''eau à la décongélation : réchauffer à découvert pour faire évaporer le surplus avant de servir.', '{"fridge_hours":72,"eat_immediately":false,"freezable":true,"freezer_months":3,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-051'), '{"variant_label":"Version confite au four : les légumes sont empilés crus en couches dans une cocotte en fonte, salés et parfumés entre chaque étage, puis cuits couvercle fermé une heure à four moyen, sans une goutte d''eau ajoutée.","rationale":"La cuisson change entièrement de nature : plus aucune saisie, les légumes entrent crus et confisent dans la vapeur qu''ils libèrent eux-mêmes sous le couvercle. On y gagne une heure sans surveillance et des dés uniformément fondants jusqu''au cœur ; on y perd la coloration de la sauteuse, ce goût de légume grillé que le confit ne produit jamais, et la possibilité de garder chaque légume distinct. L''huile descend de 80 à 60 g, faute des trois passages successifs qui en absorbaient à chaque tour.","operations":[{"op":"set","form":"Huile d''olive vierge extra","quantity":60}],"steps":[{"op":"replace","n":6,"instruction":"Chauffer le four à 160 °C. Frotter d''huile le fond et les parois d''une cocotte en fonte, puis y étaler la moitié des oignons émincés et la moitié de l''ail haché : placés dessous, ils fondent les premiers et parfument par en bas tout ce qui les surplombe."},{"op":"remove","n":7},{"op":"replace","n":8,"instruction":"Empiler les légumes crus par étages successifs — aubergine, courgette, poivron rouge, puis le poivron vert s''il entre dans la version choisie — en salant, poivrant et semant un peu de thym entre chaque couche, et en glissant le reste d''oignon et d''ail à mi-hauteur. Coiffer du concassé de tomate, compléter de la tomate râpée si les tomates manquent de maturité, poser les feuilles de laurier et arroser du reste d''huile. Ne rien mouiller : les légumes rendront à eux seuls tout le liquide dont la cocotte a besoin."},{"op":"replace","n":9,"instruction":"Fermer le couvercle et enfourner une heure pleine sans jamais soulever. La vapeur retenue sous la fonte fait tout le travail : les dés s''affaissent lentement dans leur propre jus au lieu de rissoler, et chaque étage se parfume de celui qui le surmonte."},{"op":"replace","n":10,"instruction":"Sortir la cocotte, ôter le couvercle et les feuilles de laurier, puis remettre dix à quinze minutes à découvert si le fond baigne encore. Mélanger d''un geste large en soulevant par-dessous plutôt qu''en remuant, pour ne pas réduire les étages en purée, rectifier le sel et laisser tiédir : la ratatouille confite se sert à peine chaude, ou réchauffée le lendemain, jamais brûlante."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

