  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Éplucher un oignon jaune d''environ 150 g pour en obtenir 120 g de chair nette, le tailler en dés fins. Fendre les gousses d''ail, retirer le germe central et les hacher menu. Mettre le bouillon à chauffer dans une petite casserole à côté : il devra être fumant au moment du mouillement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Dans une sauteuse large à fond épais, faire tiédir l''huile d''olive avec la moitié du beurre. Y laisser fondre l''oignon et l''ail à feu doux pendant 5 à 6 minutes, en remuant, jusqu''à ce qu''ils rendent leur eau et blondissent tout juste aux bords. Verser alors le curry en poudre et le remuer une minute pleine dans le corps gras chaud : c''est la graisse et non le bouillon qui ouvre ses arômes, et une poudre jetée crue dans le liquide garderait jusqu''au bout un goût de farine d''épice.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Retirer la sauteuse du feu et y verser le riz sec d''un seul coup. Mélanger une minute à la spatule pour que chaque grain se couvre de matière grasse : le riz passe du mat au brillant puis se voile de blanc laiteux. C''est le nacrage, l''étape qui empêchera les grains de coller.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Remettre sur le feu, verser le bouillon chaud d''un seul trait, saler et poivrer. Compter en volume un et demi de liquide pour un de céréale. Porter au premier frémissement en mélangeant une fois pour répartir l''oignon, puis ne plus toucher.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Poser à même le riz un disque de papier cuisson percé d''un trou au centre, coiffer du couvercle et laisser cuire 18 à 20 minutes sur la plus petite flamme, sans remuer ni soulever. Variante au four : enfourner la cocotte couverte à 200 °C pour la même durée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Hors du feu, laisser reposer 5 minutes à couvert pour que l''humidité résiduelle finisse d''être bue. Ôter le papier, déposer le reste du beurre en parcelles et égrainer délicatement à la fourchette, dents à plat. Goûter un grain, rectifier en sel et servir aussitôt.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-052-D1', 'recipe_family', 'Riz pilaf au curry',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-052-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-052-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-052-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('5533d8d77a91adc9b35ba981ad4c32a3'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":2},"dominant_flavors":["bouillon de volaille","oignon fondu","beurre"],"aroma_families":["alliacé","lacté","céréalier"],"target_textures":["grains égrenés et détachés","riz fondant sans être collant"],"signature_ingredients":["Riz cru","Bouillon de volaille","Oignon jaune cru"],"identity_guardrails":["Le riz doit être nacré dans le corps gras avant tout mouillement : sans cette étape d''enrobage, on obtient du riz bouillonné, plus un pilaf.","Le liquide est versé chaud et en une seule fois, à environ une fois et demie le volume du riz, puis le plat cuit à couvert sans être remué : remuer libère l''amidon et fait glisser le plat vers le risotto.","Le mouillement se fait au bouillon et non à l''eau nue : c''est lui qui porte tout l''assaisonnement du grain."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
