  VALUES (v_version, 4, 'Remettre sur le feu, verser le bouillon chaud d''un seul trait, saler et poivrer. Compter en volume un et demi de liquide pour un de céréale. Porter au premier frémissement en mélangeant une fois pour répartir l''oignon, puis ne plus toucher.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Poser à même le riz un disque de papier cuisson percé d''un trou au centre, coiffer du couvercle et laisser cuire 18 à 20 minutes sur la plus petite flamme, sans remuer ni soulever. Variante au four : enfourner la cocotte couverte à 200 °C pour la même durée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Hors du feu, laisser reposer 5 minutes à couvert pour que l''humidité résiduelle finisse d''être bue. Ôter le papier, déposer le reste du beurre en parcelles et égrainer délicatement à la fourchette, dents à plat. Goûter un grain, rectifier en sel et servir aussitôt.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-052-D4', 'recipe_family', 'Riz pilaf végétarien aux poivrons',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-052-D4', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-052-D4', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-052-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('be769f2ef5d629a2b4b0c40f242f07d5'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":2},"dominant_flavors":["bouillon de volaille","oignon fondu","beurre"],"aroma_families":["alliacé","lacté","céréalier"],"target_textures":["grains égrenés et détachés","riz fondant sans être collant"],"signature_ingredients":["Riz cru","Bouillon de légumes","Oignon jaune cru"],"identity_guardrails":["Le riz doit être nacré dans le corps gras avant tout mouillement : sans cette étape d''enrobage, on obtient du riz bouillonné, plus un pilaf.","Le liquide est versé chaud et en une seule fois, à environ une fois et demie le volume du riz, puis le plat cuit à couvert sans être remué : remuer libère l''amidon et fait glisser le plat vers le risotto.","Le mouillement se fait au bouillon et non à l''eau nue : c''est lui qui porte tout l''assaisonnement du grain."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Salade de chèvre pané', 'salade de chevre pane', 'France', 'France',
     'meal', 'salade composée', 'documented_variation', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Salade de chèvre pané', 'Salade verte avec du fromage de chèvre pané et frit, vinaigrette au miel', ds.id, 'SRC-053-D1',
    'Myko', 'editorial', 4, 25, 15, 'facile',
    NULL, NULL,
    'B', 'candidate', '68d1d97f52d9ea609da62b5aa75ab017',
    '{"sweet":2,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":4,"freshness":3,"intensity":3}'::jsonb, ARRAY['chèvre lactique','acidité vinaigrée','miel','fumé']::text[],
    ARRAY['lactée','herbacée','toastée']::text[], ARRAY['fromage fondant','pain croustillant','feuilles croquantes','éclats de noix']::text[],
    ARRAY['Fromage de chèvre bûche','Pain de campagne','Miel']::text[], ARRAY['Le chèvre doit arriver chaud et coulant sur l''assiette : servi froid ou émietté à cru, le plat perd son nom','Le pain de campagne grillé sous le fromage est le socle du plat, pas une garniture — sans lui il ne reste qu''une salade au fromage','La vinaigrette reste franchement acidulée pour trancher la richesse du fromage et du gras des lardons']::text[],
    ARRAY['panure','saisie','émulsion','grillade du pain']::text[], ARRAY[]::text[], ARRAY['gluten','lait','fruits à coque','moutarde','sulfites','œuf']::text[],
    'La vinaigrette se garde cinq jours en bocal fermé à 4 °C et les lardons cuits deux jours au réfrigérateur. Les toasts gratinés se mangent dans la minute : réchauffés, le fromage se dessèche et le pain devient cassant. La salade assaisonnée ne se conserve pas, les feuilles tombent en une heure. Rien dans ce plat ne supporte la congélation, ni le chèvre frais qui rend son eau à la décongélation, ni la laitue.', '{"fridge_hours":48,"eat_immediately":true,"freezable":false,"freezer_months":null,"serve_cold":false,"source":"manual"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-053'), '{"variant_label":"Chèvre pané : tremper les rondelles dans l''œuf cru puis dans la chapelure de blé et les dorer à la poêle au lieu de les gratiner sur le pain","rationale":"Le fromage change de contenant : au lieu de fondre à découvert sur son toast, il est enfermé dans une croûte de chapelure qui le retient et le laisse à peine s''amollir. Le contraste se déplace — croustillant sec contre cœur crémeux, là où la version gratinée opposait un dessus doré à un pain croustillant. Cela coûte une manipulation de plus, une double panure sans laquelle le chèvre s''échappe dans la poêle, et un allergène supplémentaire avec l''œuf ; le pain, désormais grillé à part, n''est plus qu''un socle et ne recueille plus le fromage coulé.","operations":[{"op":"add","form":"Œuf cru","quantity":1,"unit":"u","role":"panure","optional":false},{"op":"add","form":"Chapelure de blé","quantity":60,"unit":"g","role":"panure","optional":false}],"steps":[{"op":"replace","n":1,"instruction":"Monter la vinaigrette en premier pour qu''elle attende au frais : délayer la moutarde de Dijon dans le vinaigre de vin rouge avec le sel fin, puis incorporer 90 g d''huile d''olive en mince filet au fouet jusqu''à ce que le mélange épaississe et cesse de se séparer. Poivrer et réserver ; les 30 g d''huile restants iront pour moitié au pain, pour moitié à la poêle où doreront les rondelles panées."},{"op":"replace","n":4,"instruction":"Mettre le gril du four en chauffe à 220 °C avec une plaque garnie de papier cuisson. Trancher le pain de campagne en quatre larges tranches d''environ 50 g et un doigt d''épaisseur, les badigeonner de la moitié de l''huile réservée et les passer sous le gril deux à trois minutes par face, juste le temps qu''elles raidissent. Elles serviront de socle croustillant et ne recevront plus le fromage à gratiner."},{"op":"replace","n":5,"instruction":"Ôter les deux extrémités croûtées de la bûche de chèvre et la débiter en quatre rondelles d''environ 25 g. Battre l''œuf cru à la fourchette dans une assiette creuse, verser la chapelure de blé dans une seconde et y mêler les herbes de Provence pincées entre les doigts. Passer chaque rondelle dans l''œuf puis dans la chapelure, presser du plat de la main pour faire tenir la couche, et recommencer une seconde fois : une seule passe laisse toujours une brèche par où le fromage s''échappe dès qu''il chauffe."},{"op":"replace","n":6,"instruction":"Chauffer le reste de l''huile dans une petite poêle antiadhésive à feu moyen et y coucher les rondelles panées. Deux minutes par face suffisent : la croûte doit prendre une couleur de pain grillé pendant que le cœur s''amollit à peine. Les retourner une seule fois, à la spatule et non à la pince, puis les débarrasser aussitôt sur une grille — posées dans une assiette, elles ramolliraient par-dessous dans leur propre vapeur."},{"op":"replace","n":7,"instruction":"Pendant la cuisson, laver et essorer la laitue, la répartir en dômes dans quatre assiettes, semer la tomate râpée, les lardons égouttés et les éclats de noix. Napper de vinaigrette au dernier moment, poser une rondelle panée et une tranche de pain grillé sur chaque assiette, puis filer le miel sur le fromage brûlant : versé à ce moment-là seulement, il coule sans cuire ni brunir, et il ne détrempe pas la panure."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
