  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Glisser la plaque sous le gril à mi-hauteur et surveiller sans s''éloigner : cinq à huit minutes suffisent pour que le chèvre s''affaisse, blondisse par endroits et laisse apparaître de petites bulles en surface. Le pain doit rester ferme dessous, jamais desséché.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Pendant le gratinage, laver et essorer la laitue, la répartir en dômes dans quatre assiettes, semer la tomate râpée, les lardons égouttés et les éclats de noix. Napper de vinaigrette au dernier moment, poser un toast brûlant sur chaque assiette, puis déchirer les feuilles de basilic frais à la main juste au-dessus : coupées au couteau, leurs nervures noircissent et l''essentiel du parfum reste sur la planche. Servir sans attendre pour garder le contraste chaud-froid.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
