    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Salade landaise à la frisée', 'Frisée avec confit de canard chaud et tomates en vinaigrette moutardée', ds.id, 'SRC-054-D1',
    'Myko', 'editorial', 4, 20, 10, 'facile',
    NULL, NULL,
    'B', 'candidate', '538f3305b27d79f464effe173451b931',
    '{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":4,"freshness":3,"intensity":3}'::jsonb, ARRAY['gras de canard confit','acidité vinaigrée','moutarde']::text[],
    ARRAY['rôti','végétal frais','acidulé']::text[], ARRAY['peau de canard croustillante','chair effilochée fondante','pulpe de tomate fraîche']::text[],
    ARRAY['Confit de canard cuit','Moutarde de Dijon','Huile d''olive vierge extra']::text[], ARRAY['Sans canard confit, ce n''est plus une salade landaise : le gras de canard tiédi est le cœur du plat, aucune autre viande ne le remplace.','La sauce doit rester une vinaigrette moutardée et franchement acide, seule capable de trancher le gras ; une sauce crémée efface l''identité gasconne.','Le canard se pose tiède sur une base froide et non assaisonnée à l''avance : tout réchauffer ou tout laisser refroidir transforme le plat en autre chose.']::text[],
    ARRAY['saisie','émulsion']::text[], ARRAY[]::text[], ARRAY['moutarde','sulfites']::text[],
    'À manger dans la foulée du dressage. Les éléments se gardent séparément : chair de canard désossée trois jours à 4 °C recouverte de sa graisse, vinaigrette une semaine au réfrigérateur en bocal fermé, pulpe de tomate le jour même. Une fois assaisonnée, la salade s''affaisse en moins d''une heure. Ne se congèle pas : la tomate râpée rend toute son eau à la décongélation et la peau croustillante devient molle ; seul le confit non désossé supporte le congélateur, trois mois sous graisse.', '{"fridge_hours":72,"eat_immediately":true,"freezable":false,"freezer_months":null,"serve_cold":false,"source":"manual"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-054'), '{"variant_label":"Monter l''assiette sur un lit de frisée ou de jeunes pousses assaisonnées, comme le fait la majorité des pages du dossier.","rationale":"Deux cents grammes de frisée transforment un dressage de pulpe de tomate en vraie salade composée : l''amertume des feuilles coupe le gras du confit et donne à l''assiette un volume que la base n''avait pas. La vinaigrette doit suivre — de 28 à 45 g d''huile, de 15 à 24 g de vinaigre — puisqu''elle n''assaisonne plus une seule pulpe mais un lit de feuilles. En contrepartie, la fenêtre de service se resserre encore : la frisée s''affaisse sous le canard tiède plus vite qu''une tomate râpée ne se délave.","operations":[{"op":"add","form":"Frisée fraîche","quantity":200,"unit":"g","role":"salade","optional":false},{"op":"set","form":"Huile d''olive vierge extra","quantity":45},{"op":"set","form":"Vinaigre de vin rouge","quantity":24},{"op":"set","form":"Moutarde de Dijon","quantity":8}],"steps":[{"op":"insert","after":5,"instruction":"Trier la frisée en ne gardant que le cœur blond et les feuilles tendres, écarter les grandes côtes vertes trop amères, laver à grande eau froide et essorer sans ménagement. Une feuille encore humide repousse la vinaigrette au lieu de la retenir, et le lit se retrouve à la fois fade et détrempé."},{"op":"replace","n":7,"instruction":"Assaisonner la frisée d''un tiers de la vinaigrette et la retourner à la main, sans la brasser, puis en dresser un lit souple au centre de chaque assiette. Répartir la pulpe de tomate égouttée autour, poser dessus la chair de canard encore tiède et les éclats de peau, napper du reste de vinaigrette au tout dernier moment et porter à table aussitôt : la frisée s''affaisse en quelques minutes sous le gras tiède, et le contraste tiède contre frais s''efface avec elle."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
