  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Sortir le confit du froid une demi-heure à l''avance, le temps que la graisse figée se détende. On part de deux cuisses confites telles qu''on les achète, environ 180 g pièce avec l''os et leur couche de graisse : elles rendront les 200 g de chair comestible portés dans la liste.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Racler la graisse de couverture et la garder de côté pour un autre usage. Coucher les cuisses peau vers le bas dans une poêle encore froide, sans rien ajouter, puis monter à feu moyen : la graisse résiduelle fond seule et sert de bain de friture.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Laisser la peau grésiller six à huit minutes sans y toucher, jusqu''à ce qu''elle brunisse et durcisse, retourner deux minutes, puis débarrasser sur une grille pour que le dessous ne ramollisse pas dans son jus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Dès que les cuisses se manipulent, ôter l''os et les cartilages, séparer la peau croustillante et la briser en éclats, puis défaire la chair en filaments à la fourchette. Garder l''ensemble au tiède, pas au chaud.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser les pignons de pin dans une petite poêle froide, sans matière grasse, et les faire blondir à feu moyen environ trois minutes en les remuant sans cesse. Les débarrasser dans une assiette froide dès qu''ils sentent la résine : leur propre huile les fait passer du doré à l''amer en quelques secondes de trop, et la poêle chaude continue de les cuire hors du feu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Râper les tomates sur la grille moyenne au-dessus d''un bol, saler d''une pincée prise sur les 3 g et laisser rendre l''eau cinq minutes, puis évacuer ce jus clair qui délaverait la sauce.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Éplucher l''échalote et la ciseler le plus finement possible, puis la laisser dégorger cinq minutes dans le vinaigre avec une pincée de sel prise sur les 3 g : l''acide mange son mordant et elle ne remontera plus en bouche longtemps après le repas. Délayer ensuite la moutarde dans ce vinaigre parfumé, donner un tour de moulin à poivre, puis incorporer l''huile en mince filet sans cesser de fouetter, jusqu''à obtenir une sauce lisse qui nappe le dos d''une cuillère.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Étaler la pulpe de tomate au fond de chaque assiette, répartir dessus la chair de canard encore tiède et les éclats de peau, parsemer des pignons torréfiés, napper d''un filet de vinaigrette au tout dernier moment et porter à table aussitôt : les pignons perdent leur croquant dès qu''ils trempent dans la sauce, et le contraste tiède contre frais s''efface en quelques minutes.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-054-D2', 'recipe_family', 'Salade landaise aux pignons et à l''échalote',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-054-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-054-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-054-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('a383452a2dcb1eed177e2715289375f1'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":4,"freshness":3,"intensity":3},"dominant_flavors":["gras de canard confit","acidité vinaigrée","moutarde"],"aroma_families":["rôti","végétal frais","acidulé"],"target_textures":["peau de canard croustillante","chair effilochée fondante","pulpe de tomate fraîche"],"signature_ingredients":["Confit de canard cuit","Moutarde de Dijon","Huile d''olive vierge extra"],"identity_guardrails":["Sans canard confit, ce n''est plus une salade landaise : le gras de canard tiédi est le cœur du plat, aucune autre viande ne le remplace.","La sauce doit rester une vinaigrette moutardée et franchement acide, seule capable de trancher le gras ; une sauce crémée efface l''identité gasconne.","Le canard se pose tiède sur une base froide et non assaisonnée à l''avance : tout réchauffer ou tout laisser refroidir transforme le plat en autre chose."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
