DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Tarte à l''oignon au chèvre', 'tarte a l oignon au chevre', 'France', 'France',
     'meal', 'tarte salée', 'documented_variation', 'tangy_creamy',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Tarte à l''oignon au chèvre', 'Tarte à l''oignon sur fond feuilleté avec lardons et fromage de chèvre en garniture', ds.id, 'SRC-057-D2',
    'Myko', 'editorial', 6, 20, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', '514b0492f5e73a62483ce9d992bc8620',
    '{"sweet":3,"salty":4,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":4}'::jsonb, ARRAY['oignon compoté sucré','chèvre acidulé','lard fumé']::text[],
    ARRAY['allium doux','caprine','fumé','lacté']::text[], ARRAY['feuilletage croustillant','poches de chèvre fondu','oignons fondants']::text[],
    ARRAY['Oignon jaune cru','Fromage de chèvre bûche','Pâte feuilletée crue']::text[], ARRAY['Sans oignon jaune longuement compoté à feu doux jusqu''au blond, ce n''est plus une tarte à l''oignon mais une quiche quelconque.','L''appareil œuf-crème doit rester salé et prendre au four : le remplacer par du fromage fondu ou une sauce blanche change de plat.','La garniture doit reposer sur un fond de pâte cuit dans un moule, jamais sur une base de pain ou de pizza.','Le chèvre se pose en rondelles sur la compotée et affleure l''appareil : émietté ou fondu dedans, il se dissout en un fond lactique et le contraste qui justifie cette version disparaît.']::text[],
    ARRAY['mijotage','réduction','cuisson au four']::text[], ARRAY[]::text[], ARRAY['gluten','lait','œuf']::text[],
    'Se garde trois jours au réfrigérateur entre 0 et 4 °C, filmée une fois complètement refroidie, et se réchauffe dix minutes à 160 °C pour que le feuilletage retrouve son croustillant. La congélation est possible sur la tarte cuite et refroidie, deux mois maximum, mais l''appareil œuf-crème relâche un peu d''eau à la décongélation et la pâte ramollit : la réchauffer alors directement à 180 °C sans décongélation préalable.', '{"fridge_hours":72,"eat_immediately":false,"freezable":true,"freezer_months":2,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-057'), '{"variant_label":"Tarte à l''oignon au chèvre : disposer des rondelles de Fromage de chèvre bûche sur la compotée avant de verser l''appareil.","rationale":"Les rondelles de chèvre posées en surface fondent en poches crémeuses et acidulées qui tranchent le sucre de la compotée : la tarte cesse d''être uniformément douce et se lit par bouchées contrastées. Elle devient en revanche sensiblement plus grasse et plus salée, et le lard fumé se dispute désormais le premier plan avec le chèvre au lieu de s''effacer derrière l''oignon. Il faut enfin accepter une surface irrégulière : un chèvre noyé dans l''appareil ne dore pas, et les rondelles doivent affleurer.","operations":[{"op":"add","form":"Fromage de chèvre bûche","quantity":150,"unit":"g","role":"fromage","optional":false}],"steps":[{"op":"replace","n":6,"instruction":"Répartir la compotée tiède sur le fond de pâte en couche égale, puis disposer par-dessus le fromage de chèvre en bûche détaillé en rondelles d''un demi-centimètre, régulièrement espacées pour que chaque part en reçoive deux ou trois. Verser l''appareil autour et entre les rondelles sans jamais les recouvrir : elles doivent affleurer, c''est à cette condition qu''elles dorent et rendent leur gras en surface au lieu de se dissoudre. Enfourner trente minutes, jusqu''à ce que la crème soit prise au centre, que les rondelles soient blondes et boursouflées et que le pourtour du feuilletage soit bien doré."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

