  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir environ 270 g d''oignons entiers, c''est-à-dire trois beaux oignons tels qu''on les achète : une fois pelés et parés, il en reste les 240 g de chair nette utilisés ici. Les couper en deux dans la hauteur puis les émincer en demi-lunes fines et régulières.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire chauffer l''huile d''olive dans une large sauteuse, y jeter les oignons avec le miel et une petite pincée de sel, couvrir et laisser suer huit minutes à feu doux, le temps qu''ils rendent leur eau et s''affaissent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Retirer le couvercle, ajouter les lardons et poursuivre douze minutes à feu moyen en remuant régulièrement, jusqu''à ce que l''humidité se soit évaporée et que les oignons soient blonds et translucides, sans jamais brunir. Débarrasser dans un plat et laisser tiédir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Porter le four à 200 °C. Étaler la pâte avec son papier au fond d''un moule de vingt-six centimètres, piquer le fond à la fourchette et plaquer les bords contre la paroi.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Casser deux gros œufs, soit environ cent dix grammes coquille comprise pour les cent grammes d''œuf de la liste, et les fouetter avec la crème jusqu''à obtenir un appareil homogène. Saler, poivrer, goûter.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Répartir la compotée tiède sur le fond de pâte en couche égale, puis disposer par-dessus le fromage de chèvre en bûche détaillé en rondelles d''un demi-centimètre, régulièrement espacées pour que chaque part en reçoive deux ou trois. Verser l''appareil autour et entre les rondelles sans jamais les recouvrir : elles doivent affleurer, c''est à cette condition qu''elles dorent et rendent leur gras en surface au lieu de se dissoudre. Enfourner trente minutes, jusqu''à ce que la crème soit prise au centre, que les rondelles soient blondes et boursouflées et que le pourtour du feuilletage soit bien doré.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Sortir la tarte et la laisser reposer une dizaine de minutes sur une grille avant de la découper, le temps que la garniture se raffermisse et que le dessous du feuilletage sèche.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-057-D2', 'recipe_family', 'Tarte à l''oignon au chèvre',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-057-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-057-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-057-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('514b0492f5e73a62483ce9d992bc8620'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"tangy_creamy","scores":{"sweet":3,"salty":4,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":4},"dominant_flavors":["oignon compoté sucré","chèvre acidulé","lard fumé"],"aroma_families":["allium doux","caprine","fumé","lacté"],"target_textures":["feuilletage croustillant","poches de chèvre fondu","oignons fondants"],"signature_ingredients":["Oignon jaune cru","Fromage de chèvre bûche","Pâte feuilletée crue"],"identity_guardrails":["Sans oignon jaune longuement compoté à feu doux jusqu''au blond, ce n''est plus une tarte à l''oignon mais une quiche quelconque.","L''appareil œuf-crème doit rester salé et prendre au four : le remplacer par du fromage fondu ou une sauce blanche change de plat.","La garniture doit reposer sur un fond de pâte cuit dans un moule, jamais sur une base de pain ou de pizza.","Le chèvre se pose en rondelles sur la compotée et affleure l''appareil : émietté ou fondu dedans, il se dissout en un fond lactique et le contraste qui justifie cette version disparaît."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Tarte à l''oignon aux herbes de Provence', 'tarte a l oignon aux herbes de provence', 'France', 'France',
     'meal', 'tarte salée', 'documented_variation', 'earthy_herbal',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Tarte à l''oignon aux herbes de Provence', 'Tarte à l''oignon avec lardons, relevée d''herbes de Provence séchées', ds.id, 'SRC-057-D3',
    'Myko', 'editorial', 6, 20, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', 'bd892b3398c3d75faf7a0f7b7ce9ac52',
    '{"sweet":3,"salty":3,"acidic":1,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":2,"intensity":4}'::jsonb, ARRAY['oignon compoté sucré','herbes sèches résineuses','lard fumé']::text[],
    ARRAY['allium doux','herbacé résineux','fumé','lacté']::text[], ARRAY['feuilletage croustillant','appareil crémeux tout juste pris','oignons fondants']::text[],
    ARRAY['Oignon jaune cru','Crème fraîche liquide entière','Pâte feuilletée crue']::text[], ARRAY['Sans oignon jaune longuement compoté à feu doux jusqu''au blond, ce n''est plus une tarte à l''oignon mais une quiche quelconque.','L''appareil œuf-crème doit rester salé et prendre au four : le remplacer par du fromage fondu ou une sauce blanche change de plat.','La garniture doit reposer sur un fond de pâte cuit dans un moule, jamais sur une base de pain ou de pizza.','Les herbes s''ajoutent hors du feu en toute fin de compotée : mises à cuire, elles virent à l''amer et couvrent l''oignon, qui doit rester le sujet de la tarte.']::text[],
    ARRAY['mijotage','réduction','cuisson au four']::text[], ARRAY[]::text[], ARRAY['gluten','lait','œuf']::text[],
    'Se garde trois jours au réfrigérateur entre 0 et 4 °C, filmée une fois complètement refroidie, et se réchauffe dix minutes à 160 °C pour que le feuilletage retrouve son croustillant. La congélation est possible sur la tarte cuite et refroidie, deux mois maximum, mais l''appareil œuf-crème relâche un peu d''eau à la décongélation et la pâte ramollit : la réchauffer alors directement à 180 °C sans décongélation préalable.', '{"fridge_hours":72,"eat_immediately":false,"freezable":true,"freezer_months":2,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-057'), '{"variant_label":"Version méridionale : parfumer la compotée d''Herbes de Provence séderisées — ici, une cuillère d''Herbes de Provence séchées ajoutée en fin de compotée.","rationale":"Deux grammes d''herbes sèches jetées hors du feu suffisent à déplacer la tarte vers le sud : le thym et la sarriette du mélange rencontrent le sucre de l''oignon et donnent un ensemble plus résineux, moins strictement lacté. C''est peu de matière pour beaucoup d''effet, et c''est là le risque — une cuillère bombée au lieu d''une rase, ou des herbes mises à cuire dès le départ, et l''amertume sèche du romarin couvre l''oignon pour de bon. Le fumé du lard, lui, ne s''accorde qu''à moitié à ce registre et se retrouve un peu en travers.","operations":[{"op":"add","form":"Herbes de Provence séchées","quantity":2,"unit":"g","role":"aromate","optional":false}],"steps":[{"op":"replace","n":3,"instruction":"Retirer le couvercle, ajouter les lardons et poursuivre douze minutes à feu moyen en remuant régulièrement, jusqu''à ce que l''humidité se soit évaporée et que les oignons soient blonds et translucides, sans jamais brunir. Couper le feu, verser les herbes de Provence séchées sur la compotée brûlante et mélanger : la chaleur résiduelle suffit à les ouvrir, alors qu''ajoutées en début de cuisson elles auraient bouilli vingt minutes et rendu une amertume de tisane. Débarrasser dans un plat et laisser tiédir."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

