      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'optional',
     'assaisonnement', true, 11);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir environ 260 g de poivrons rouges entiers et 520 g de verts, soit un rouge et deux verts de belle taille, pour obtenir les 200 g de chair rouge et les 400 g de chair verte utiles. Les fendre, arracher le pédoncule, secouer les graines, raser les cloisons blanches puis débiter la chair en lanières larges comme un doigt, en gardant les deux couleurs séparées jusqu''à la sauteuse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Peler 230 g d''oignons pour en garder 200 g nets et les trancher en fines demi-lunes. Écraser puis hacher les gousses d''ail. Râper environ 450 g de tomates mûres, face coupée contre la grille moyenne, jusqu''à ce que la peau reste vide dans la paume : on récupère à peu près 350 g de pulpe.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Tiédir l''huile d''olive dans une sauteuse large, y verser les oignons et laisser fondre à feu modéré une bonne huitaine de minutes sans coloration, en raclant le fond de temps à autre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser d''abord les lanières vertes, remonter légèrement la flamme et les laisser quatre minutes seules, puis ajouter les rouges et poursuivre douze minutes à découvert : les bords doivent s''assouplir et prendre quelques marques dorées. Le vert étant deux fois plus abondant que le rouge, l''étaler franchement et remuer plus souvent, sans quoi il s''entasse au fond et cuit à l''étouffée au lieu de rissoler.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Incorporer l''ail haché, attendre une minute que le parfum monte, puis ajouter la pulpe de tomate, les herbes de Provence et le piment d''Espelette. Laisser réduire quinze minutes à petit frémissement, sans couvercle, jusqu''à ce que le jus nappe les légumes au lieu de baigner la sauteuse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Pendant ce temps, ouvrir trois boîtes de thon au naturel de 185 g net, renverser leur contenu dans une passoire et presser du dos d''une cuillère : il reste environ 390 g de chair une fois le jus de conserve évacué. La séparer en gros pétales sans la réduire en miettes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Couper le feu, glisser les pétales de thon dans la piperade et les enrober par mouvements amples de la spatule. Remettre trente secondes sur la plaque éteinte encore chaude, juste le temps de réchauffer, sans jamais laisser bouillir sous peine de dessécher les fibres.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Goûter à ce moment seulement et rectifier avec le sel fin et le poivre noir, en se souvenant que la saumure du thon a déjà salé le plat. Laisser reposer cinq minutes hors du feu avant de servir avec un riz blanc.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-059-D1', 'recipe_family', 'Thon à la basquaise aux deux poivrons',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-059-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-059-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-059-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('12fcbb7e47d5318080310aa1b7d30c89'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":1,"pungency":2,"richness":2,"freshness":2,"intensity":3},"dominant_flavors":["tomate cuite","poivron confit","thon salé"],"aroma_families":["végétal cuit","fruité olive","piment doux"],"target_textures":["légumes fondants","pétales de thon effeuillés","sauce nappante"],"signature_ingredients":["Thon au naturel en conserve, égoutté","Poivron rouge frais","Piment d''Espelette moulu"],"identity_guardrails":["Sans le duo de poivrons rouge et vert fondus dans la tomate, il ne reste qu''un thon à la sauce tomate et le caractère basquaise disparaît.","Le thon doit rester en pétales entiers ajoutés hors du feu : mijoté avec les légumes, il se délite en rillettes et le plat change de nature.","Le piment d''Espelette est l''épice d''ancrage régional ; le poivre seul ou le piment fort le remplacent mal."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Thon sur piperade liée à l''œuf', 'thon sur piperade liee a l oeuf', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Thon sur piperade liée à l''œuf', 'Thon mijoté dans une piperade de poivrons et tomates liée aux œufs en fin de cuisson', ds.id, 'SRC-059-D2',
    'Myko', 'editorial', 4, 25, 37, 'facile',
    NULL, NULL,
    'B', 'candidate', 'e0b5f90a9dbe987bde004ef2fff574aa',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":1,"pungency":2,"richness":3,"freshness":2,"intensity":3}'::jsonb, ARRAY['tomate cuite','poivron confit','œuf lié']::text[],
    ARRAY['végétal cuit','fruité olive','piment doux']::text[], ARRAY['légumes fondants','liaison crémeuse à l''œuf','pétales de thon effeuillés']::text[],
    ARRAY['Thon au naturel en conserve, égoutté','Poivron rouge frais','Piment d''Espelette moulu']::text[], ARRAY['L''œuf entre hors ébullition et se retire dès qu''il nappe la spatule : poussé plus loin il grumelle, et la piperade liée n''est plus qu''une brouillade aux légumes.','Le thon se couche sur la piperade et ne s''y mélange jamais : incorporé, il se délite dans la masse et le plat perd la lecture en deux couches qui le définit.','Le piment d''Espelette est l''épice d''ancrage régional ; le poivre seul ou le piment fort le remplacent mal.']::text[],
    ARRAY['mijotage','réduction','liaison aux œufs']::text[], ARRAY[]::text[], ARRAY['poisson','œuf']::text[],
    'Se garde deux jours au réfrigérateur entre 0 et 4 °C dans une boîte fermée, mais la liaison à l''œuf ne supporte pas un vrai réchauffage : la reprendre à feu très doux en remuant, ou la manger tiède, faute de quoi elle graine. La congélation est exclue : l''œuf tranche au dégel et la chair de thon en conserve devient cotonneuse.', '{"fridge_hours":48,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-059'), '{"variant_label":"Ajouter un œuf battu en fin de réduction pour glisser vers la piperade liée, et servir le thon dessus.","rationale":"Les œufs battus versés en fin de réduction lient la piperade : le jus de tomate cesse de napper les légumes pour devenir une masse crémeuse qui les tient. La phrase parle d''un œuf, la base sert quatre personnes — il en faut deux pour que la liaison se sente sans virer à la brouillade. Le thon n''est plus enrobé mais couché dessus, ce qui le garde en pétales lisibles et le prive de l''échange de saveurs que le mélange produisait. Le prix réel est la fenêtre de service : liée à l''œuf, la piperade se raffermit en refroidissant et ne se réchauffe plus sans grainer.","operations":[{"op":"add","form":"Œuf cru","quantity":2,"unit":"u","role":"liant","optional":false}],"steps":[{"op":"insert","after":6,"instruction":"Casser les deux œufs dans un bol et les battre à la fourchette juste assez pour mêler jaunes et blancs, sans les faire mousser. Baisser la flamme sous la piperade, verser les œufs en filet et remuer sans arrêt à la spatule en raclant le fond. Retirer du feu dès que le mélange épaissit et nappe la spatule, au bout d''une minute à peine : poussé plus loin, l''œuf coagule en grumeaux et la liaison tourne en brouillade."},{"op":"replace","n":7,"instruction":"Étaler la piperade liée dans un plat creux ou la répartir directement dans quatre assiettes, puis coucher les pétales de thon par-dessus sans les enfouir. Le poisson reste ainsi identifiable sous la fourchette et ne subit pas une seconde chauffe dans une masse brûlante, où ses fibres se dessécheraient."},{"op":"replace","n":8,"instruction":"Goûter la piperade seule avant de rectifier avec le sel fin et le poivre noir : la saumure du thon a déjà salé le plat, mais l''œuf, lui, réclame son sel. Servir sans attendre, tant que la liaison est encore souple — elle se raffermit en quelques minutes et ne revient pas en arrière."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
