  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 6, 'g', 'optional',
     'assaisonnement', true, 7);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 2, 'g', 'optional',
     'assaisonnement', true, 8);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir quatre truites entières d''environ 250 g, soit un kilo au comptoir du poissonnier : demandez-lui de les écailler, de les vider et d''ôter l''arête centrale. Une fois la tête et les nageoires retirées, il reste environ 520 g de chair, ce qui correspond à la quantité utile de la recette. Rincer à l''eau froide et sécher soigneusement avec du papier absorbant : une chair humide ne dore pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Saler et poivrer les deux faces des poissons, puis les passer dans la farine T55 étalée sur une assiette. Tapoter franchement pour ne garder qu''un voile : le surplus brûlerait dans la poêle et masquerait le goût de l''amande.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Faire chauffer l''huile d''olive avec les deux tiers du beurre dans une grande poêle sur feu moyen-vif, en gardant le dernier tiers de côté pour la sauce. Déposer les truites côté peau et les laisser prendre couleur environ cinq minutes sans y toucher, puis les retourner deux à trois minutes côté chair. La chair doit se détacher en lamelles opaques sous la pointe d''un couteau. Réserver au chaud sur le plat de service.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser les amandes effilées dans une petite poêle parfaitement sèche, sans une trace de gras, et les blondir sur feu moyen quatre à cinq minutes en secouant sans arrêt. Elles colorent plus lentement qu''au beurre et plus régulièrement, mais rien ne les protège : dès que l''odeur de noisette monte, les faire glisser sur une assiette froide, car la fonte continue de les cuire longtemps après le feu coupé.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Essuyer la poêle des truites avec du papier absorbant, la remettre sur feu doux et y faire fondre le reste du beurre, puis retirer du feu et verser le jus de citron en faisant tourner la poêle. Napper les poissons de ce jus à peine lié, puis semer les amandes par-dessus au tout dernier moment : posées sur une sauce courte au lieu d''y baigner, elles gardent un croquant net et cassant jusqu''à l''assiette.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-060-D1', 'recipe_family', 'Truite aux amandes grillées à sec',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-060-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-060-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-060-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('1a1c87ec18b07b9d46a700385b06620d'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":2,"heat":0,"pungency":0,"richness":3,"freshness":3,"intensity":3},"dominant_flavors":["amande torréfiée","citron","beurre fondu"],"aroma_families":["fruit à coque torréfié","agrume","lacté"],"target_textures":["chair floconneuse","amandes sèches et cassantes","surface farinée dorée"],"signature_ingredients":["Truite crue","Amande effilée","Beurre doux"],"identity_guardrails":["Les amandes sont grillées à sec et semées au dernier moment : versées dans la sauce, elles s''imbibent en quelques secondes et le croquant sec que vise cette version disparaît.","Le beurre reste la matière grasse de la sauce, même réduit à dix grammes : sans lui le jus de citron ne se lie pas et le plat n''est plus qu''un poisson fariné arrosé d''acide.","La truite est farinée puis saisie à la poêle, peau comprise ; pochée, fumée ou gratinée, elle sort de l''identité du plat."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Truite flambée au cognac et aux amandes', 'truite flambee au cognac et aux amandes', 'France', 'France',
     'meal', 'plat de poisson', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Truite flambée au cognac et aux amandes', 'Truite poêlée puis flambée au cognac, servie avec des amandes effilées', ds.id, 'SRC-060-D2',
    'Myko', 'editorial', 4, 20, 17, 'facile',
    NULL, NULL,
    'B', 'candidate', 'c22b41fc2465bd303d54221868514f10',
    '{"sweet":1,"salty":3,"acidic":2,"bitter":1,"umami":2,"heat":0,"pungency":0,"richness":4,"freshness":2,"intensity":4}'::jsonb, ARRAY['beurre noisette','amande grillée','eau-de-vie boisée']::text[],
    ARRAY['lacté','fruit à coque torréfié','spiritueux vieilli']::text[], ARRAY['chair floconneuse','amandes croquantes','sauce ambrée aux sucs']::text[],
    ARRAY['Truite crue','Amande effilée','Beurre doux']::text[], ARRAY['L''alcool s''enflamme tiède et brûle jusqu''à extinction naturelle : étouffé trop tôt, il laisse dans la sauce une amertume d''alcool cru que rien ne rattrape ensuite.','La poêle ne s''essuie pas après le flambage : les sucs au cognac sont la sauce, les retirer ramène le plat à sa version d''origine sans rien lui avoir apporté.','L''amande doit être effilée et blondie juste avant le service : réduite en poudre, mixée en crème ou laissée crue, le plat perd le croquant qui le nomme.']::text[],
    ARRAY['saisie','flambage','déglaçage','torréfaction']::text[], ARRAY[]::text[], ARRAY['poisson','fruits à coque','lait','gluten']::text[],
    'Se mange immédiatement, la sauce et les amandes perdant leur croquant en quelques minutes. Les restes se gardent 24 h à 4 °C dans une boîte hermétique, amandes séparées du poisson si possible, et se réchauffent doucement à la poêle ou se mangent froids. La truite cuite supporte mal la congélation (chair qui rend son eau) et les amandes blondies ramollissent au dégel : ne pas congeler le plat monté.', '{"fridge_hours":24,"eat_immediately":true,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-060'), '{"variant_label":"Version flambée : arroser les truites saisies d''un alcool ambré chauffé puis enflammé avant d''ajouter les amandes.","rationale":"Quarante millilitres de cognac tiédi puis enflammé sur les truites encore en poêle ajoutent une couche boisée et vanillée que le beurre seul ne donne pas, et laissent au fond des sucs caramélisés dont la sauce hérite. L''alcool brûle presque entièrement : il en reste le parfum et une vingtaine de calories par part. Le geste coûte de l''attention plus que du temps — hotte coupée, visage écarté, manche tenu à distance — et il accélère la coloration des amandes, que le fond sucré fait virer plus vite. La phrase de la base dit « un alcool ambré » sans le nommer ; le cognac est ici la lecture retenue, non une indication de la source.","operations":[{"op":"add","form":"Cognac","quantity":40,"unit":"ml","role":"alcool","optional":false}],"steps":[{"op":"replace","n":3,"instruction":"Faire chauffer l''huile d''olive avec le tiers du beurre dans une grande poêle sur feu moyen-vif. Déposer les truites côté peau et les laisser prendre couleur environ cinq minutes sans y toucher, puis les retourner deux à trois minutes côté chair. La chair doit se détacher en lamelles opaques sous la pointe d''un couteau. Les laisser dans la poêle cette fois : c''est là qu''elles vont être flambées."},{"op":"insert","after":3,"instruction":"Tiédir le cognac quelques secondes dans une petite casserole — un alcool froid ne s''enflamme pas —, couper la hotte, le verser sur les truites et l''enflammer aussitôt en tenant le manche à bout de bras et le visage écarté. Laisser la flamme s''éteindre d''elle-même, une demi-minute environ : elle brûle l''alcool et ne laisse que le parfum de fût accroché à la peau dorée. Réserver ensuite les poissons au chaud sur le plat de service."},{"op":"replace","n":4,"instruction":"Ne pas essuyer la poêle cette fois : le fond porte le cognac réduit avec les sucs, et c''est lui qui fera la sauce. Y faire fondre le reste du beurre sur feu doux et verser les amandes effilées. Remuer sans arrêt trois à quatre minutes jusqu''au blond noisette, en surveillant de près — le sucre laissé par l''alcool les colore plus vite que dans un beurre propre."},{"op":"replace","n":5,"instruction":"Retirer la poêle du feu, verser le jus de citron sur les amandes et faire tourner la poêle pour lier le beurre, les sucs et l''acidité en une sauce ambrée. En napper aussitôt les truites et servir sans attendre, tant que les amandes croquent encore."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'truite crue' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Truite crue', 520, 'g', 'required',
     'protéine', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'amande effilee' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Amande effilée', 65, 'g', 'required',
     'garniture', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
