  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Verser les haricots flageolets appertisés dans une passoire et les rincer à l''eau froide pour ôter le jus de conserve, qui est salé et un peu farineux, puis les laisser s''égoutter le temps du rôtissage. Peler l''oignon et le garder entier ; réserver à côté de lui le laurier et la petite part de thym destinée aux haricots, le reste du thym partant sur le gigot. La conserve étant déjà cuite, ces aromates n''auront que le réchauffage final pour se faire entendre, et il ne sert à rien de les mettre à l''eau maintenant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Peler l''ail et le tailler en éclats. Inciser le gigot à intervalles réguliers et glisser un éclat dans chaque fente.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Badigeonner le gigot d''huile d''olive, saler, poivrer, parsemer de thym, puis l''installer sur une grille au-dessus du plat de cuisson, la face la plus charnue tournée vers le fond.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Enfourner à 220 °C et saisir vingt minutes, puis baisser à 180 °C, retourner le gigot, verser un demi-verre d''eau dans le plat et poursuivre trente à quarante minutes en arrosant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Sortir le gigot et le laisser reposer dix minutes sous une feuille d''aluminium : la chair se détend et le jus se redistribue.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Pendant que le gigot repose, réchauffer les flageolets égouttés dix minutes à couvert et à feu doux avec l''oignon entier, le thym et le laurier, sans ajouter d''eau et sans remuer plus que nécessaire : le grain est déjà cuit, une ébullition le réduirait en purée. Les deux dix minutes se recouvrent exactement, et c''est voulu : un gigot qui attendrait en plus le réchauffage du lit se trancherait froid. Retirer les aromates, goûter avant de saler — la conserve en apporte déjà —, puis lier au beurre et au jus de rôtissage dégraissé et servir le gigot tranché sur ce lit.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-003-D2', 'recipe_family', 'Gigot d''agneau aux flageolets en conserve',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-003-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-003-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-003-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('6201111c9f4e673bfa959dc2efa470a1'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":2,"acidic":0,"bitter":0,"umami":0,"heat":3,"pungency":0,"richness":3,"freshness":4,"intensity":1},"dominant_flavors":["agneau_rôti","ail_confit","haricot_fondant"],"aroma_families":["viande_rôtie","ail","thym"],"target_textures":["croûte_dorée","chair_rosée","haricot_fondant"],"signature_ingredients":["Gigot d''agneau cru","Haricot flageolet appertisé, égoutté","Ail cru"],"identity_guardrails":["Le gigot repose avant d''être tranché, sinon le jus part sur la planche.","Les flageolets ne sont pas un accompagnement rapporté : ils finissent dans le jus de rôtissage.","La conserve ne se recuit pas : dix minutes à couvert suffisent à la parfumer, au-delà la peau éclate et le lit tourne en purée."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Bouchées à la reine alsaciennes aux quenelles', 'bouchees a la reine alsaciennes aux quenelles', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Bouchées à la reine alsaciennes aux quenelles', 'Bouchées feuilletées avec fricassée de poulet et veau dans la tradition alsacienne aux quenelles', ds.id, 'SRC-009-D4',
    'Myko', 'editorial', 6, 40, 100, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '9374ec34bbfe4c209c2a906f735149be',
    '{"sweet":1,"salty":3,"acidic":1,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":3}'::jsonb, ARRAY['volaille','champignon','crème','vin blanc','quenelle']::text[],
    ARRAY['beurré','lacté','épicé doux','champignon']::text[], ARRAY['sauce nappante','viande fondante','lamelles de champignon tendres','tronçons de quenelle gonflés et moelleux']::text[],
    ARRAY['Champignon de Paris frais','Escalope de veau crue fine','Bouillon de volaille','Jaune d''œuf cru','Quenelle nature crue']::text[], ARRAY['Sans la liaison finale au Jaune d''œuf cru et à la Crème fraîche liquide entière, le velouté retombe au rang de simple béchamel et le plat perd son caractère de sauce à la reine.','Retirer le Champignon de Paris frais ou la volaille pochée vide la garniture de sa substance : ce sont les deux éléments présents dans presque toutes les sources du dossier.','Le bouillon de volaille doit être celui du pochage des viandes, pas de l''eau salée : c''est lui qui porte tout l''umami de la sauce.','La sauce ne doit jamais bouillir après l''ajout des jaunes, sous peine de grainer irrémédiablement.','Les quenelles sont pochées à part et coupées en tronçons : jetées crues dans le velouté, elles y lâchent leur farine et le troublent.']::text[],
    ARRAY['pochage','mijotage','réduction','liaison']::text[], ARRAY[]::text[], ARRAY['gluten','lait','œuf','sulfites']::text[],
    'Se garde 2 jours au réfrigérateur à 4 °C dans une boîte hermétique, la garniture bien refroidie avant fermeture. Les quenelles continuent d''absorber la sauce au froid : compter une bonne louche de bouillon au réchauffage, à feu très doux ou au bain-marie, sans jamais laisser frémir. La congélation est à proscrire deux fois : la liaison jaune d''œuf et crème tranche au dégel, et la quenelle en ressort spongieuse.', '{"fridge_hours":48,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-009'), '{"variant_label":"Version alsacienne de fête : augmenter la part de viandes, ajouter des quenelles coupées en tronçons au moment de réunir la garniture, et servir avec des spätzle.","rationale":"La part de viandes passe de 925 à 1200 g et les quenelles ajoutent 360 g de garniture, sans que le velouté grossisse d''un gramme : la sauce devient courte, et la quenelle, qui continue de boire une fois dans la casserole, la resserre encore. C''est pourquoi le bouillon monte de 750 à 950 g — les 600 g de la sauce ne changent pas, le supplément sert à détendre la garniture louche par louche. Les quenelles se pochent à l''eau salée et non dans le bouillon, qu''elles absorberaient au détriment de la sauce : cela coûte une casserole de plus et une douzaine de minutes. Les spätzle se servent à côté, dans leur plat : ils recueillent le surplus de sauce mais ne sont pas dans l''assiette pesée, et ne comptent donc pas dans les ingrédients.","operations":[{"op":"set","form":"Poulet entier cru","quantity":900},{"op":"set","form":"Escalope de veau crue fine","quantity":300},{"op":"set","form":"Bouillon de volaille","quantity":950},{"op":"add","form":"Quenelle nature crue","quantity":360,"unit":"g","role":"garniture","optional":false}],"steps":[{"op":"replace","n":1,"instruction":"Peler la carotte et l''oignon jaune, les couper en gros tronçons. Détailler le poulet en quatre morceaux et l''installer avec les légumes dans une cocotte assez large pour que le bouillon recouvre tout : la part de viande est ici plus lourde d''un tiers qu''au plat de base, et un morceau qui affleure cuit d''un côté seulement. Verser le bouillon de volaille, amener à frémissement puis couvrir et laisser cuire 45 minutes à tout petits bouillons, en retournant les morceaux à mi-parcours."},{"op":"insert","after":4,"instruction":"Pocher les quenelles nature crues dans une large casserole d''eau salée à peine frémissante, dix à douze minutes selon leur grosseur : elles gonflent de moitié, remontent en surface et se raffermissent sous le doigt. À l''eau et non dans le bouillon, qu''elles boiraient au détriment de la sauce, et sans jamais laisser bouillir, sous peine de les voir éclater. Les égoutter sur un linge, les laisser tiédir pour qu''elles se tiennent au couteau, puis les couper en tronçons de deux centimètres."},{"op":"replace","n":7,"instruction":"Verser les cubes de viande, les champignons et les tronçons de quenelle dans le velouté, baisser au minimum et laisser les saveurs se lier 5 minutes sans que la sauce reprenne l''ébullition. La quenelle continue de boire : la sauce épaissit à vue d''œil, et c''est là que sert le bouillon gardé au chaud, une louche à la fois, jusqu''à retrouver un velouté qui nappe."},{"op":"replace","n":9,"instruction":"Servir sans attendre, la garniture bien chaude répartie dans des croûtes feuilletées passées quelques minutes au four, et présenter à côté un plat de spätzle beurrés, comme le veut l''usage alsacien : ils recueillent le surplus de sauce mieux qu''une croûte déjà pleine. Le reste de sauce se présente à part en saucière."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

