  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Rincer les lentilles sous l''eau froide dans une passoire fine jusqu''à ce que l''eau ressorte claire. Peler la carotte et la tailler en rondelles de 3 mm, fendre le poireau et le débiter en fines demi-rondelles après l''avoir bien lavé. Peler l''oignon et le couper en deux : une moitié partira entière à la cuisson, l''autre sera émincée crue au dernier moment.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Réunir dans une casserole les lentilles, la carotte, le poireau, la demi-moitié d''oignon entière, le laurier et le thym. Recouvrir de deux fois leur volume d''eau froide, sans sel : une eau salée dès le départ durcit la peau de la légumineuse et l''empêche de s''attendrir régulièrement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Monter doucement jusqu''au frémissement, puis baisser le feu au minimum et laisser cuire à découvert 12 à 15 minutes. La lentille corail se défait beaucoup plus vite que la verte : goûter dès la dixième minute et couper le feu à l''instant où le grain cède sous la dent tout en restant entier.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Saler seulement à ce moment-là, puis égoutter immédiatement et sans rincer pour stopper la cuisson. Retirer la moitié d''oignon et la feuille de laurier, garder carotte et poireau. Étaler le tout dans un saladier large : la chaleur retombe vite et les grains cessent de se coller entre eux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Pendant que les lentilles cuisent, plonger les œufs dans une casserole d''eau à petits bouillons et compter exactement 6 minutes pour un jaune encore coulant. Les basculer dans un bol d''eau glacée, attendre deux minutes, puis les écaler délicatement en commençant par le côté le plus large.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Torréfier les noisettes à sec dans une petite poêle sur feu moyen, trois à quatre minutes en la secouant sans arrêt, jusqu''à ce qu''elles embaument et que la peau se craquèle. Les verser aussitôt dans un linge et les frotter pour ôter les pellicules, qui sont amères, puis les laisser refroidir à l''air libre : versées chaudes sur des lentilles tièdes, elles ramolliraient et ne croqueraient plus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Dans un bol, écraser l''ail au presse-ail, ajouter le vinaigre, le poivre et une pincée de sel, puis verser l''huile d''olive en mince filet en fouettant sans arrêt jusqu''à ce que la sauce épaississe et cesse de se séparer. Verser sur les lentilles encore tièdes, mélanger à la spatule souple et laisser reposer 5 minutes : c''est en refroidissant qu''elles boivent la vinaigrette.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Ciseler le persil et la ciboulette, concasser grossièrement les noisettes refroidies au couteau — en éclats et non en poudre, sinon il ne reste rien à croquer. Les ajouter au saladier avec l''oignon cru émincé très finement, mélanger une dernière fois, répartir dans les assiettes puis poser sur chacune un œuf ouvert en deux. Rectifier en poivre et servir sans attendre, à peine tiède.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-014-D6', 'recipe_family', 'Lentilles tièdes aux noisettes torréfiées',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-014-D6', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-014-D6', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-014-D6', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('a2eab266c0f4d071a38f090c07729978'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":2,"acidic":3,"bitter":0,"umami":2,"heat":0,"pungency":3,"richness":3,"freshness":3,"intensity":3},"dominant_flavors":["terreux","noisette torréfiée","acidulé","herbacé","alliacé"],"aroma_families":["herbacé","fruit à coque grillé","aromates séchés","alliacé"],"target_textures":["lentilles fondantes mais entières","jaune d''œuf coulant","éclats de noisette croquants","oignon cru croquant"],"signature_ingredients":["Lentille corail sèche, crue","Noisette grillée","Huile d''olive vierge extra","Vinaigre de vin rouge","Persil frais"],"identity_guardrails":["Les lentilles doivent être assaisonnées encore tièdes : une fois froides elles n''absorbent plus la vinaigrette et le plat bascule en salade froide banale.","L''eau de cuisson reste non salée jusqu''à la fin, sinon la peau durcit et le grain ne s''attendrit plus uniformément.","La garniture aromatique carotte-poireau-oignon cuite avec la légumineuse et le duo thym-laurier constituent la base commune à toutes les sources : les retirer viderait le plat de son fond de goût.","La vinaigrette doit rester une émulsion huile d''olive et vinaigre franchement acide ; adoucie ou crémée, le contraste avec la lentille disparaît.","Les noisettes se torréfient à sec et se concassent au couteau : achetées en poudre ou en éclats déjà broyés, elles se noient dans la vinaigrette et le croquant annoncé disparaît."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Pan bagnat niçois de printemps', 'pan bagnat nicois de printemps', 'France', 'France',
     'meal', 'sandwich', 'documented_variation', 'bright_acidic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Pan bagnat niçois de printemps', 'Pan bagnat provençal pressé avec fèves fraîches et oignon nouveau en saison', ds.id, 'SRC-017-D4',
    'Myko', 'editorial', 4, 35, 10, 'facile',
    NULL, NULL,
    'B', 'candidate', 'd38777502be9c1addc203b1786fe04a7',
    '{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":4,"intensity":3}'::jsonb, ARRAY['tomate mûre','huile d''olive fruitée','olive noire','acidité vinaigrée']::text[],
    ARRAY['fruité olive','végétal frais','acidulé vinaigré']::text[], ARRAY['mie imbibée et moelleuse','croûte souple','jaune d''œuf crémeux']::text[],
    ARRAY['Pain de campagne','Huile d''olive vierge extra','Tomate râpée','Olive noire']::text[], ARRAY['La mie doit être imbibée d''huile d''olive et du jus de tomate : un pan bagnat sec n''est plus un pan bagnat.','Tout est assemblé à froid et rien n''est cuit dans le sandwich ; le pain ne passe jamais au grill ni au four.','Aucun beurre ni sauce émulsionnée type mayonnaise : l''huile d''olive vierge extra est l''unique corps gras.','Le repos sous pression fait partie de la recette, il ne s''agit pas d''un sandwich servi à la minute.']::text[],
    ARRAY['marinade','pochage','pressage']::text[], ARRAY[]::text[], ARRAY['gluten','œuf','sulfites']::text[],
    'Se garde 24 heures au réfrigérateur entre 0 et 4 °C, emballé bien serré dans un film ou un papier ; il gagne à reposer quelques heures mais se délite au-delà d''une journée. Congélation exclue : le pain imbibé et l''œuf dur deviennent spongieux et caoutchouteux à la décongélation.', '{"fridge_hours":24,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":true,"source":"manual"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-017'), '{"variant_label":"Ajouter au printemps quelques lamelles d''oignon nouveau cru et des févettes écossées, comme dans la version niçoise de saison.","rationale":"Deux crudités de saison entrent sans que rien ne sorte : cent vingt grammes de fèves écossées apportent une mâche ferme et une amertume verte que le pan bagnat n''a pas autrement, l''oignon nouveau une pointe piquante à la place de l''ail de la version frottée. Le coût est d''abord une saison, car passé le début de l''été la fève devient farineuse sous sa robe et la variante n''a plus d''objet, puis un quart d''heure de travail pour l''écossage : il faut quatre cents grammes de gousses pour cent vingt grammes de grains. Le sandwich s''alourdit aussi de cent quatre-vingts grammes de garniture sur le même pain, ce qui demande de presser plus fermement et rend la découpe moins nette. Enfin l''heure de repos, qui profite à la tomate et à la mie, n''améliore ni la fève ni l''oignon crus, dont le mordant s''émousse à mesure.","operations":[{"op":"add","form":"Fève à écosser fraîche","quantity":120,"unit":"g","role":"légume","optional":false},{"op":"add","form":"Oignon nouveau frais","quantity":60,"unit":"g","role":"aromate","optional":false}],"steps":[{"op":"insert","after":2,"instruction":"Profiter du quart d''heure de macération pour écosser les fèves : compter environ quatre cents grammes de gousses pour obtenir les cent vingt grammes de grains utiles. Goûter un grain cru — sur une févette de printemps, la fine robe qui l''enveloppe est encore tendre et se mange telle quelle ; si elle accroche déjà sous la dent, l''entamer de l''ongle au sommet du grain et la faire glisser, sans passer par l''eau bouillante qui cuirait ce qui doit rester cru. Émincer l''oignon nouveau en lamelles très fines, le vert de la tige compris, puis le laisser tremper cinq minutes à l''eau froide avant de l''égoutter et de l''éponger : ainsi rincé de son jus le plus agressif, il ne prendra pas le dessus pendant l''heure de repos."},{"op":"replace","n":5,"instruction":"Étaler la tomate râpée égouttée sur la base, répartir dessus les rondelles d''œuf dur, puis semer les fèves écossées et les lamelles d''oignon nouveau en les glissant entre les rondelles plutôt qu''en surface : posées sur le dessus, elles roulent hors du pain dès la première pression. Parsemer enfin d''olives noires dénoyautées et grossièrement concassées."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'pain de campagne' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Pain de campagne', 600, 'g', 'required',
     'féculent', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'tomate rapee' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Tomate râpée', 480, 'g', 'required',
     'légume', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
