  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Immerger les œufs dans une casserole d''eau frémissante et compter dix minutes à petits bouillons, puis les refroidir sous l''eau courante, les écaler et les couper en rondelles régulières.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Réunir la tomate râpée dans un saladier avec le vinaigre de vin rouge, les deux tiers de l''huile d''olive, le sel fin et le poivre noir moulu ; laisser macérer un quart d''heure le temps que le jus se colore et se parfume.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Profiter du quart d''heure de macération pour écosser les fèves : compter environ quatre cents grammes de gousses pour obtenir les cent vingt grammes de grains utiles. Goûter un grain cru — sur une févette de printemps, la fine robe qui l''enveloppe est encore tendre et se mange telle quelle ; si elle accroche déjà sous la dent, l''entamer de l''ongle au sommet du grain et la faire glisser, sans passer par l''eau bouillante qui cuirait ce qui doit rester cru. Émincer l''oignon nouveau en lamelles très fines, le vert de la tige compris, puis le laisser tremper cinq minutes à l''eau froide avant de l''égoutter et de l''éponger : ainsi rincé de son jus le plus agressif, il ne prendra pas le dessus pendant l''heure de repos.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Fendre le pain de campagne en deux dans l''épaisseur et creuser légèrement la mie de la partie supérieure pour ménager de la place à la garniture et à l''huile.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Badigeonner les deux faces internes avec l''huile d''olive restante, puis les arroser du jus rendu par la tomate jusqu''à ce que la mie soit franchement humide sans être détrempée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Étaler la tomate râpée égouttée sur la base, répartir dessus les rondelles d''œuf dur, puis semer les fèves écossées et les lamelles d''oignon nouveau en les glissant entre les rondelles plutôt qu''en surface : posées sur le dessus, elles roulent hors du pain dès la première pression. Parsemer enfin d''olives noires dénoyautées et grossièrement concassées.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Recoiffer avec la partie supérieure, presser fermement de la paume, envelopper serré dans un papier et laisser reposer trente à soixante minutes au frais avant de découper en quatre parts.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-017-D4', 'recipe_family', 'Pan bagnat niçois de printemps',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-017-D4', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-017-D4', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-017-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('d38777502be9c1addc203b1786fe04a7'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"bright_acidic","scores":{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":4,"intensity":3},"dominant_flavors":["tomate mûre","huile d''olive fruitée","olive noire","acidité vinaigrée"],"aroma_families":["fruité olive","végétal frais","acidulé vinaigré"],"target_textures":["mie imbibée et moelleuse","croûte souple","jaune d''œuf crémeux"],"signature_ingredients":["Pain de campagne","Huile d''olive vierge extra","Tomate râpée","Olive noire"],"identity_guardrails":["La mie doit être imbibée d''huile d''olive et du jus de tomate : un pan bagnat sec n''est plus un pan bagnat.","Tout est assemblé à froid et rien n''est cuit dans le sandwich ; le pain ne passe jamais au grill ni au four.","Aucun beurre ni sauce émulsionnée type mayonnaise : l''huile d''olive vierge extra est l''unique corps gras.","Le repos sous pression fait partie de la recette, il ne s''agit pas d''un sandwich servi à la minute."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Salade de riz niçoise au riz complet', 'salade de riz nicoise au riz complet', 'France', 'France',
     'meal', 'salade composée', 'documented_variation', 'bright_acidic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Salade de riz niçoise au riz complet', 'Riz complet froid avec thon, œufs, tomates et poivron vert en vinaigrette', ds.id, 'SRC-024-D2',
    'Myko', 'editorial', 4, 20, 22, 'facile',
    NULL, NULL,
    'B', 'candidate', '501241298f9f7646d23383541d1f271e',
    '{"sweet":1,"salty":2,"acidic":3,"bitter":1,"umami":2,"heat":0,"pungency":1,"richness":3,"freshness":4,"intensity":2}'::jsonb, ARRAY['tomate','huile d''olive','poivron vert']::text[],
    ARRAY['végétal','fruité']::text[], ARRAY['grains de riz détachés','dés de poivron croquants','enrobage huileux léger']::text[],
    ARRAY['Thon au naturel en conserve, égoutté','Riz cru','Huile d''olive vierge extra']::text[], ARRAY['Sans thon ni œuf dur, ce n''est plus une salade niçoise mais une salade de riz aux crudités.','Le riz est refroidi avant d''être assaisonné : tiède, il boit l''huile et devient pâteux.','Les légumes restent crus et taillés à la main ; cuits, la salade perd son mordant.']::text[],
    ARRAY['pochage','marinade','émulsion']::text[], ARRAY[]::text[], ARRAY['poisson','œuf']::text[],
    'Se conserve 24 à 48 heures au réfrigérateur entre 0 et 4 °C dans un contenant hermétique ; sortir le saladier un quart d''heure avant le service pour réveiller le fruité de l''huile, qui fige au froid. Ne supporte pas la congélation : le riz devient farineux et les légumes crus rendent toute leur eau à la décongélation.', '{"fridge_hours":24,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":true,"source":"manual"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-024'), '{"variant_label":"Remplacer un tiers du riz blanc par du riz complet pour un grain plus mordant, en allongeant la cuisson de cinq à sept minutes.","rationale":"Un tiers du riz blanc passe au complet, quarante-cinq grammes sur cent trente : le grain garde son son, donc du mordant et un fond de noisette que le riz blanc n''a pas. Le prix est une organisation en deux temps — un trempage d''une nuit à lancer la veille, puis le riz complet jeté seul sept minutes avant le blanc, de sorte que la casserole totalise vingt-deux minutes sans que le blanc dépasse les quinze qui lui conviennent. La texture n''est plus homogène et ne cherche pas à l''être : deux grains cohabitent, l''un tendre, l''autre ferme sous la dent. Il faut aussi porter le repos au froid à une heure, le son freinant l''absorption de l''assaisonnement à la tomate.","operations":[{"op":"set","form":"Riz cru","quantity":85,"role":"féculent","optional":false},{"op":"add","form":"Riz complet cru","quantity":45,"unit":"g","role":"féculent","optional":false}],"steps":[{"op":"replace","n":1,"instruction":"Rincer le riz complet cru à l''eau froide et le laisser tremper une nuit entière, ou quatre heures au minimum : le son qui enveloppe le grain freine l''eau, et sans trempage il demanderait trois quarts d''heure de casserole là où le riz blanc en réclame quinze minutes. Une heure ne lui ferait gagner qu''une dizaine de minutes ; pour qu''il cède en vingt-deux, il doit entrer dans la casserole déjà gorgé d''eau. L''égoutter, porter un grand volume d''eau salée à ébullition et y jeter en pluie le riz complet seul. Le laisser sept minutes à découvert et à frémissement, puis ajouter le riz blanc en pluie et poursuivre quinze minutes : le complet cuit ainsi vingt-deux minutes en tout et le blanc ses quinze, chacun cédant sous la dent en gardant un cœur ferme, au lieu que l''un se défasse pendant que l''autre reste dur."},{"op":"replace","n":3,"instruction":"Verser les deux riz ensemble dans une passoire, les rincer sous un filet d''eau froide en remuant à la main jusqu''à ce qu''ils ne soient plus tièdes du tout, puis les laisser s''égoutter un bon quart d''heure : le son du grain complet retient l''eau plus longtemps que l''amidon nu du blanc, et un riz mal égoutté délaye l''assaisonnement à la tomate."},{"op":"replace","n":7,"instruction":"Goûter, rectifier en sel et en poivre, couvrir puis réserver une heure au réfrigérateur plutôt qu''une demi-heure : protégé par son son, le grain complet boit l''assaisonnement à la tomate bien plus lentement que le blanc, et une salade goûtée trop tôt paraît sèche sur un tiers de ses grains. Remuer une dernière fois juste avant de servir bien frais."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
