  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 4, 'g', 'optional',
     'assaisonnement', true, 7);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'optional',
     'assaisonnement', true, 8);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'riz complet cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Riz complet cru', 45, 'g', 'required',
     'féculent', false, 9);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Rincer le riz complet cru à l''eau froide et le laisser tremper une nuit entière, ou quatre heures au minimum : le son qui enveloppe le grain freine l''eau, et sans trempage il demanderait trois quarts d''heure de casserole là où le riz blanc en réclame quinze minutes. Une heure ne lui ferait gagner qu''une dizaine de minutes ; pour qu''il cède en vingt-deux, il doit entrer dans la casserole déjà gorgé d''eau. L''égoutter, porter un grand volume d''eau salée à ébullition et y jeter en pluie le riz complet seul. Le laisser sept minutes à découvert et à frémissement, puis ajouter le riz blanc en pluie et poursuivre quinze minutes : le complet cuit ainsi vingt-deux minutes en tout et le blanc ses quinze, chacun cédant sous la dent en gardant un cœur ferme, au lieu que l''un se défasse pendant que l''autre reste dur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Cuire les œufs dix minutes à l''eau frémissante, les rafraîchir, les écaler et les couper en quartiers.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Verser les deux riz ensemble dans une passoire, les rincer sous un filet d''eau froide en remuant à la main jusqu''à ce qu''ils ne soient plus tièdes du tout, puis les laisser s''égoutter un bon quart d''heure : le son du grain complet retient l''eau plus longtemps que l''amidon nu du blanc, et un riz mal égoutté délaye l''assaisonnement à la tomate.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Pendant la cuisson, fendre le poivron vert frais, en ôter le pédoncule, les graines et les cloisons blanches, puis le détailler en petits dés réguliers de la taille d''un grain de maïs, sans le cuire.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Réunir la tomate râpée et son jus dans un bol, la saler, patienter cinq minutes le temps qu''elle rende son eau, puis verser l''huile d''olive vierge extra en filet en fouettant pour obtenir un assaisonnement lié et brillant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Rassembler dans un saladier le riz bien refroidi et les dés de poivron, napper de l''assaisonnement à la tomate, donner un tour de poivre noir moulu et mélanger à la fourchette en soulevant la masse pour détacher les grains sans les écraser.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Goûter, rectifier en sel et en poivre, couvrir puis réserver une heure au réfrigérateur plutôt qu''une demi-heure : protégé par son son, le grain complet boit l''assaisonnement à la tomate bien plus lentement que le blanc, et une salade goûtée trop tôt paraît sèche sur un tiers de ses grains. Remuer une dernière fois juste avant de servir bien frais.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-024-D2', 'recipe_family', 'Salade de riz niçoise au riz complet',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-024-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-024-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-024-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('501241298f9f7646d23383541d1f271e'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"bright_acidic","scores":{"sweet":1,"salty":2,"acidic":3,"bitter":1,"umami":2,"heat":0,"pungency":1,"richness":3,"freshness":4,"intensity":2},"dominant_flavors":["tomate","huile d''olive","poivron vert"],"aroma_families":["végétal","fruité"],"target_textures":["grains de riz détachés","dés de poivron croquants","enrobage huileux léger"],"signature_ingredients":["Thon au naturel en conserve, égoutté","Riz cru","Huile d''olive vierge extra"],"identity_guardrails":["Sans thon ni œuf dur, ce n''est plus une salade niçoise mais une salade de riz aux crudités.","Le riz est refroidi avant d''être assaisonné : tiède, il boit l''huile et devient pâteux.","Les légumes restent crus et taillés à la main ; cuits, la salade perd son mordant."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Sauté de porc aux pruneaux et chou rouge', 'saute de porc aux pruneaux et chou rouge', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Sauté de porc aux pruneaux et chou rouge', 'Épaule de porc mijotée avec pruneaux, lardons et chou rouge', ds.id, 'SRC-026-D3',
    'Myko', 'editorial', 4, 25, 90, 'facile',
    NULL, NULL,
    'B', 'candidate', '0f8370e2cc390eba7f7880cd116bc7e6',
    '{"sweet":3,"salty":3,"acidic":1,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['sucré du fruit sec','porc caramélisé','fumé du lard','oignon confit']::text[],
    ARRAY['fruit sec','fumé','viande rôtie','légume fondu']::text[], ARRAY['viande fondante à la fourchette','pruneau moelleux et gonflé','sauce nappante']::text[],
    ARRAY['Épaule de porc crue','Pruneau dénoyauté','Lardon fumé cru']::text[], ARRAY['Sans pruneau dénoyauté, il ne reste qu''un sauté de porc ordinaire : c''est le fruit sec qui porte le contraste sucré-salé du plat.','La viande doit être saisie et colorée avant le mouillement ; un porc simplement poché dans l''eau donne un plat pâle et sans sucs.','La cuisson reste longue et à couvert : un passage rapide à la poêle ne rend pas l''épaule fondante et ne laisse pas les pruneaux parfumer le jus.','Le mouillement se limite à un fond d''eau, pas à un bain : la sauce doit finir réduite et nappante, jamais aqueuse.']::text[],
    ARRAY['saisie','déglaçage','mijotage','réduction']::text[], ARRAY[]::text[], ARRAY['sulfites']::text[],
    'Se conserve 3 jours au réfrigérateur entre 0 et 4 °C dans un récipient fermé, et gagne même en goût réchauffé le lendemain à feu doux avec une cuillère d''eau. Le plat se congèle très bien 3 mois : la viande et la sauce supportent la décongélation, les pruneaux ressortent seulement un peu plus fondus.', '{"fridge_hours":72,"eat_immediately":false,"freezable":true,"freezer_months":3,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-026'), '{"variant_label":"Version au chou rouge : ajouter du chou rouge cru émincé au moment du mouillement, il cuit avec la viande et colore le jus.","rationale":"Quatre cents grammes de chou rouge émincé entrent au mouillement et cuisent l''heure et demie restante avec la viande : ils fondent à l''étouffée, se chargent du gras des lardons et donnent enfin un légume de plein droit au plat, là où la carotte facultative ne servait que de garniture aromatique avec l''oignon. Le mouillement descend de trois cent trente à deux cent vingt millilitres, mais le tiers retiré ne compense qu''une partie de l''eau que le chou rendra : on n''en ôte pas plus pour garder de quoi déglacer et couvrir le fond le temps qu''il s''affaisse, et le surplus s''en va à découvert en fin de cuisson, sans quoi la sauce ne napperait pas. Le chou coûte cinq minutes de taille et une part du premier plan : son amertume légère et son sucré terreux s''installent entre le porc et le pruneau, dont le contraste se lit moins net. Sa couleur, enfin, ne tient pas — sans acidité pour la fixer, le pourpre du cru tourne au violet brun en une heure de cocotte, et c''est de cette teinte-là qu''il colore le jus.","operations":[{"op":"add","form":"Chou rouge cru","quantity":400,"unit":"g","role":"légume","optional":false},{"op":"set","form":"Eau","quantity":220,"role":"mouillement","optional":false}],"steps":[{"op":"replace","n":1,"instruction":"Détailler l''épaule de porc en cubes réguliers d''environ quatre centimètres, assez gros pour rester moelleux après une cuisson longue. Peler et émincer finement l''oignon jaune, tailler la carotte en petits dés. Fendre le chou rouge en quartiers, retirer le trognon central qui ne s''attendrit jamais, puis émincer les feuilles en lanières de la largeur d''un doigt : taillées plus fin, elles se défont en marmelade au bout d''une heure de cocotte."},{"op":"replace","n":5,"instruction":"Jeter le chou rouge émincé dans la cocotte et le retourner deux minutes dans le gras rendu par les lardons, le temps qu''il commence à s''affaisser et qu''il prenne le goût du fond. Verser l''eau et gratter aussitôt à la cuillère en bois pour décoller les sucs caramélisés : le mouillement est ici plus court d''un tiers, parce que quatre cents grammes de chou lâchent bien plus que cela pendant la cuisson et qu''un jus trop abondant ne se rattrape pas. Ne pas en retirer davantage pour autant : il faut de quoi déglacer et de quoi couvrir le fond le temps que le chou s''affaisse et prenne le relais. Poivrer, porter à petits bouillons puis couvrir et baisser au minimum."},{"op":"replace","n":6,"instruction":"Laisser mijoter environ une heure à frémissement à peine perceptible, en remuant de loin en loin pour faire descendre dans le jus le chou resté en surface. Il perd les deux tiers de son volume et lâche son pigment, qui teinte la sauce et jusqu''aux cubes de porc. Piquer la viande : elle doit céder sans résistance sous la pointe du couteau."},{"op":"replace","n":8,"instruction":"Retirer le couvercle pour les dix dernières minutes et laisser le liquide réduire jusqu''à une sauce brillante qui nappe la cuillère ; le chou ayant rendu davantage d''eau que les cent dix millilitres retirés au mouillement, prolonger de quelques minutes à feu plus vif si le jus reste fluide. Mélanger avec précaution et rectifier le poivre avant de servir. La couleur, à ce stade, a viré : faute d''acidité pour fixer son pigment, le chou longuement cuit abandonne le pourpre du cru pour un violet sombre qui tire sur le brun, et la sauce le suit."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
