  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Détailler l''épaule de porc en cubes réguliers d''environ quatre centimètres, assez gros pour rester moelleux après une cuisson longue. Peler et émincer finement l''oignon jaune, tailler la carotte en petits dés. Fendre le chou rouge en quartiers, retirer le trognon central qui ne s''attendrit jamais, puis émincer les feuilles en lanières de la largeur d''un doigt : taillées plus fin, elles se défont en marmelade au bout d''une heure de cocotte.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Chauffer l''huile d''olive dans une cocotte à fond épais, y faire suer l''oignon et la carotte à feu moyen une dizaine de minutes, jusqu''à ce qu''ils deviennent translucides et souples sans prendre de couleur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pousser la garniture sur les bords, monter le feu et déposer les cubes de porc à plat. Les laisser dorer sans les bouger, puis les retourner face par face jusqu''à ce qu''ils soient colorés partout.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ajouter les lardons fumés et les laisser fondre deux à trois minutes en remuant, le temps qu''ils libèrent leur gras et parfument l''ensemble de la cocotte.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Jeter le chou rouge émincé dans la cocotte et le retourner deux minutes dans le gras rendu par les lardons, le temps qu''il commence à s''affaisser et qu''il prenne le goût du fond. Verser l''eau et gratter aussitôt à la cuillère en bois pour décoller les sucs caramélisés : le mouillement est ici plus court d''un tiers, parce que quatre cents grammes de chou lâchent bien plus que cela pendant la cuisson et qu''un jus trop abondant ne se rattrape pas. Ne pas en retirer davantage pour autant : il faut de quoi déglacer et de quoi couvrir le fond le temps que le chou s''affaisse et prenne le relais. Poivrer, porter à petits bouillons puis couvrir et baisser au minimum.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Laisser mijoter environ une heure à frémissement à peine perceptible, en remuant de loin en loin pour faire descendre dans le jus le chou resté en surface. Il perd les deux tiers de son volume et lâche son pigment, qui teinte la sauce et jusqu''aux cubes de porc. Piquer la viande : elle doit céder sans résistance sous la pointe du couteau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Incorporer les pruneaux dénoyautés et poursuivre vingt minutes à couvert, juste assez pour qu''ils gonflent et parfument le jus sans se défaire en purée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Retirer le couvercle pour les dix dernières minutes et laisser le liquide réduire jusqu''à une sauce brillante qui nappe la cuillère ; le chou ayant rendu davantage d''eau que les cent dix millilitres retirés au mouillement, prolonger de quelques minutes à feu plus vif si le jus reste fluide. Mélanger avec précaution et rectifier le poivre avant de servir. La couleur, à ce stade, a viré : faute d''acidité pour fixer son pigment, le chou longuement cuit abandonne le pourpre du cru pour un violet sombre qui tire sur le brun, et la sauce le suit.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-026-D3', 'recipe_family', 'Sauté de porc aux pruneaux et chou rouge',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-026-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-026-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-026-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('0f8370e2cc390eba7f7880cd116bc7e6'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":3,"salty":3,"acidic":1,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["sucré du fruit sec","porc caramélisé","fumé du lard","oignon confit"],"aroma_families":["fruit sec","fumé","viande rôtie","légume fondu"],"target_textures":["viande fondante à la fourchette","pruneau moelleux et gonflé","sauce nappante"],"signature_ingredients":["Épaule de porc crue","Pruneau dénoyauté","Lardon fumé cru"],"identity_guardrails":["Sans pruneau dénoyauté, il ne reste qu''un sauté de porc ordinaire : c''est le fruit sec qui porte le contraste sucré-salé du plat.","La viande doit être saisie et colorée avant le mouillement ; un porc simplement poché dans l''eau donne un plat pâle et sans sucs.","La cuisson reste longue et à couvert : un passage rapide à la poêle ne rend pas l''épaule fondante et ne laisse pas les pruneaux parfumer le jus.","Le mouillement se limite à un fond d''eau, pas à un bain : la sauce doit finir réduite et nappante, jamais aqueuse."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Calamars à l''armoricaine au whisky', 'calamars a l armoricaine au whisky', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Calamars à l''armoricaine au whisky', 'Calamars flambés au whisky, mijotés dans une sauce tomate au vin blanc', ds.id, 'SRC-034-D2',
    'Myko', 'editorial', 4, 25, 55, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '966e77a064d622678d115d1c3c4e15a7',
    '{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":4,"heat":2,"pungency":2,"richness":3,"freshness":1,"intensity":4}'::jsonb, ARRAY['tomate concentrée','iodé','whisky flambé','vin blanc']::text[],
    ARRAY['marin','céréalier fumé','vineux','alliacé']::text[], ARRAY['anneaux tendres sous la dent','sauce nappante','oignons fondus']::text[],
    ARRAY['Calamar cru nettoyé','Whisky','Concentré de tomate','Vin blanc sec']::text[], ARRAY['Sans calamar, il n''y a plus de plat : c''est le mollusque, et non un poisson ou une autre chair, qui porte l''identité.','C''est le flambage qui est constitutif de l''armoricaine, pas l''eau-de-vie employée : l''alcool doit brûler dans la cocotte, versé cru il ne laisserait que son alcool.','La base doit rester tomate et vin blanc : une liaison crémeuse dominante bascule vers une autre recette.','Le whisky se choisit non tourbé : la fumée de tourbe recouvre l''iode du mollusque et donne à la sauce un goût médicinal que rien ne rattrape.']::text[],
    ARRAY['saisie','flambage','déglaçage','mijotage','réduction']::text[], ARRAY[]::text[], ARRAY['mollusques','sulfites','lait']::text[],
    'Se garde deux à trois jours au réfrigérateur à 4 °C dans un contenant hermétique, et gagne même à être préparé la veille. Réchauffer à feu très doux, sans ébullition, sous peine de raidir les calamars. La congélation est possible un mois mais dégrade nettement la texture du mollusque : mieux vaut congeler la sauce seule et cuire les calamars au moment.', '{"fridge_hours":48,"eat_immediately":false,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-034'), '{"variant_label":"Remplacer le Cognac par un whisky, variante explicitement proposée par une source, pour une note plus fumée que fruitée.","rationale":"Le whisky prend la place du Cognac à volume égal : le flambage reste le même geste, mais le fond de sauce perd les notes de fruit confit de l''eau-de-vie de vin pour une amertume céréalière et fumée qui tient plus longtemps en bouche. Le coût est un risque de dosage plutôt qu''un coût calorique — les deux alcools pèsent presque le même poids d''éthanol, et l''apport par part ne bouge pas d''une dizaine de kilocalories. Ce qui change vraiment, c''est l''équilibre : un whisky tourbé recouvre l''iode du calamar et rend la sauce médicinale, si bien que la variante ne tient qu''avec un grain léger, non tourbé.","operations":[{"op":"substitute","form":"Cognac","with":"Whisky","quantity":32,"unit":"g","role":"alcool de flambage"}],"steps":[{"op":"replace","n":4,"instruction":"Remettre les calamars et leur jus dans la cocotte, monter le feu, verser le whisky et l''enflammer en écartant le visage et en éteignant la hotte. Attendre que la flamme retombe d''elle-même et la laisser aller jusqu''au bout : un alcool de grain brûle plus court qu''une eau-de-vie de vin et laisse au fond une amertume qu''il faut lui laisser perdre dans la flamme. Racler ensuite le fond à la cuillère en bois pour décoller ce qui a caramélisé."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

