      LIMIT 1),
     'Herbes de Provence séchées', 2, 'g', 'optional',
     'aromate', true, 11);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 4, 'g', 'optional',
     'assaisonnement', true, 12);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'optional',
     'assaisonnement', true, 13);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poire fraiche' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poire fraîche', 260, 'g', 'required',
     'fruit', false, 14);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Monter la vinaigrette en premier pour qu''elle attende au frais : délayer la moutarde de Dijon dans le vinaigre de vin rouge avec le sel fin, puis incorporer 90 g d''huile d''olive en mince filet au fouet jusqu''à ce que le mélange épaississe et cesse de se séparer. Poivrer et réserver ; les 30 g d''huile restants serviront au pain.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Poser les lardons fumés dans une poêle froide sans aucune matière grasse, monter à feu moyen et les laisser rendre leur gras puis colorer une petite dizaine de minutes en remuant de temps en temps. Les débarrasser sur du papier absorbant et jeter la graisse de la poêle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Compter environ 130 g de noix en coquille chez le primeur pour obtenir les 55 g de cerneaux utiles ici — la coque part à la poubelle et représente plus de la moitié du poids acheté. Casser, trier, puis concasser les cerneaux au couteau en gros éclats irréguliers.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Peler deux belles poires mûres mais encore fermes, les couper en quartiers, ôter le cœur et les pépins, puis les tailler en lamelles de deux à trois millimètres — assez fines pour plier sous la fourchette, assez épaisses pour ne pas tourner en compote au contact du toast. Les arroser aussitôt d''une cuillerée de vinaigrette prise sur la réserve : sans cet acide, la chair coupée brunit en un quart d''heure et le fruit arrive gris sur la table.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Mettre le gril du four en chauffe à 220 °C avec une plaque garnie de papier cuisson. Trancher le pain de campagne en quatre larges tranches d''environ 50 g et un doigt d''épaisseur, puis les badigeonner d''huile d''olive sur la face qui recevra le fromage.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Ôter les deux extrémités croûtées de la bûche de chèvre et la débiter en quatre rondelles d''environ 25 g. En coiffer chaque tranche de pain, déposer un filet de miel sur le fromage et pincer les herbes de Provence entre les doigts au-dessus des toasts pour les réveiller.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Glisser la plaque sous le gril à mi-hauteur et surveiller sans s''éloigner : cinq à huit minutes suffisent pour que le chèvre s''affaisse, blondisse par endroits et laisse apparaître de petites bulles en surface. Le pain doit rester ferme dessous, jamais desséché.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Pendant le gratinage, laver et essorer la laitue, la répartir en dômes dans quatre assiettes, semer la tomate râpée, les lardons égouttés et les éclats de noix, puis coucher les lamelles de poire en éventail d''un côté de l''assiette, à l''écart du toast. Napper de vinaigrette au dernier moment, poser le toast brûlant et servir sans attendre : glissée dessous, la poire chauffe, rend son eau et devient molle en deux minutes.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-053-D5', 'recipe_family', 'Salade de chèvre chaud à la poire',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-053-D5', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-053-D5', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-053-D5', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('e550f34ef3017f8108f8441b1367e08d'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":4,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":4,"freshness":3,"intensity":3},"dominant_flavors":["chèvre lactique","poire sucrée","acidité vinaigrée","miel","fumé"],"aroma_families":["lactée","fruitée","toastée"],"target_textures":["fromage fondant","pain croustillant","feuilles croquantes","lamelles de poire fondantes","éclats de noix"],"signature_ingredients":["Fromage de chèvre bûche","Pain de campagne","Miel"],"identity_guardrails":["Le chèvre doit arriver chaud et coulant sur l''assiette : servi froid ou émietté à cru, le plat perd son nom","Le pain de campagne grillé sous le fromage est le socle du plat, pas une garniture — sans lui il ne reste qu''une salade au fromage","La poire se pose crue, en lamelles et à l''écart du toast : cuite ou réchauffée elle rend son eau et délave la vinaigrette","La vinaigrette reste franchement acidulée : avec le miel et la poire, deux sources de sucre pèsent désormais sur l''assiette"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Salade landaise aux gésiers et au magret fumé', 'salade landaise aux gesiers et au magret fume', 'France', 'France',
     'meal', 'salade composée', 'documented_variation', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Salade landaise aux gésiers et au magret fumé', 'Salade avec confit de canard, gésiers confits et magret de canard fumé en vinaigrette', ds.id, 'SRC-054-D3',
    'Myko', 'editorial', 4, 20, 15, 'facile',
    NULL, NULL,
    'B', 'candidate', 'a65e67931ecb295f555814ac7b74c96d',
    '{"sweet":1,"salty":4,"acidic":3,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":4,"freshness":2,"intensity":4}'::jsonb, ARRAY['gras de canard confit','fumé du magret','abat ferme','acidité vinaigrée','moutarde']::text[],
    ARRAY['rôti','fumée','acidulé']::text[], ARRAY['peau de canard croustillante','chair effilochée fondante','gésier ferme sous la dent','tranche de magret souple','pulpe de tomate fraîche']::text[],
    ARRAY['Confit de canard cuit','Magret de canard fumé','Moutarde de Dijon','Huile d''olive vierge extra']::text[], ARRAY['Sans canard confit, ce n''est plus une salade landaise : le gras de canard tiédi est le cœur du plat, et les gésiers comme le magret s''ajoutent à lui sans le remplacer.','La sauce doit rester une vinaigrette moutardée et franchement acide, seule capable de trancher le gras du confit et celui du magret fumé, qui portent à eux deux presque tout le gras de l''assiette ; une sauce crémée efface l''identité gasconne.','Le magret fumé se pose froid et cru sur le bord de l''assiette, jamais sur la viande chaude : passé à la poêle ou seulement tiédi, il rend son gras et perd le fumé qui le justifie.','Les gésiers se servent chauds et en gros morceaux : froids ou coupés en dés, ils deviennent caoutchouteux et disparaissent dans la salade.']::text[],
    ARRAY['saisie','émulsion']::text[], ARRAY[]::text[], ARRAY['moutarde','sulfites']::text[],
    'À manger dans la foulée du dressage. Les éléments se gardent séparément : chair de canard désossée trois jours à 4 °C recouverte de sa graisse, gésiers poêlés deux jours au réfrigérateur, vinaigrette une semaine en bocal fermé, pulpe de tomate le jour même. Le magret fumé entamé tient cinq jours serré dans son film, mais tranché il sèche en quelques heures : il se coupe au dernier moment. Ne se congèle pas monté : la tomate râpée rend toute son eau à la décongélation, la peau croustillante devient molle et le magret fumé perd son gras ; seuls le confit non désossé et les gésiers sous graisse supportent le congélateur, trois mois.', '{"fridge_hours":48,"eat_immediately":true,"freezable":false,"freezer_months":null,"serve_cold":false,"source":"manual"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-054'), '{"variant_label":"Ajouter des gésiers confits réchauffés à la poêle, taillés en morceaux, et deux tranches de magret fumé par personne.","rationale":"Deux abats et une charcuterie de plus, et la salade change de catégorie : de garniture de tomate au canard effiloché, elle devient l''assiette de charcuterie gasconne complète. Les gésiers apportent une mâche ferme et un goût d''abat franc que la chair effilochée n''a pas — débarrassés de leur graisse comme les veut la poêle, ils sont la pièce la plus maigre de l''assiette, deux grammes de lipides aux cent grammes contre dix-neuf pour le confit ; le magret fumé arrive en tranche froide, salée et fumée qui répond au gras tiède du confit, et c''est lui, à trente-deux grammes aux cent, qui apporte presque tout le gras ajouté. Le coût est d''abord de poids : trois cent vingt grammes de canard s''ajoutent aux deux cents de la base, soit cent trente grammes de viande par personne, et la vinaigrette de la base suffit tout juste à trancher autant de gras. Le coût le moins visible est le sel : gésiers et magret sont deux salaisons, l''assiette passe d''environ un gramme et demi de sel par part à plus de trois, et la pincée prise sur les 3 g pour la vinaigrette est désormais tout ce qu''on peut ajouter. Le coût est enfin de température : le magret fumé ne doit pas tiédir, son gras fond à rien et perd son parfum, alors que les gésiers doivent être chauds — deux exigences contraires dans la même assiette.","operations":[{"op":"add","form":"Gésier de canard confit","quantity":200,"unit":"g","role":"protéine","optional":false},{"op":"add","form":"Magret de canard fumé","quantity":120,"unit":"g","role":"charcuterie","optional":false}],"steps":[{"op":"insert","after":6,"instruction":"Remettre la poêle du confit sur feu moyen sans la laver, une fois la vinaigrette montée et non avant : les gésiers doivent arriver chauds dans l''assiette et n''attendent pas. Y coucher les gésiers de canard confits, débarrassés à la main du gras figé qui les enrobe, et les laisser raffermir et grésiller trois à quatre minutes en les retournant une fois, jusqu''à ce que les arêtes brunissent — réchauffés trop doucement ils restent caoutchouteux, poussés trop loin ils durcissent d''un coup. Les tailler chacun en deux ou trois morceaux dans l''épaisseur, jamais en dés, et les garder dans la poêle hors du feu le temps de dresser : un gésier se mange en bouchées qui résistent."},{"op":"replace","n":7,"instruction":"Détailler le magret de canard fumé en tranches très fines, deux par personne et une trentaine de grammes par assiette : plus épaisses, elles mâchent au lieu de fondre. Étaler la pulpe de tomate au fond de chaque assiette, répartir dessus la chair de canard encore tiède, les éclats de peau et les morceaux de gésier chauds, puis poser les tranches de magret en éventail sur le bord de l''assiette, là où rien ne les réchauffera. Napper d''un filet de vinaigrette au tout dernier moment et porter à table aussitôt : le gras du magret fumé fond dès qu''il tiédit et emporte son parfum avec lui."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
