  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'magret de canard fume' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Magret de canard fumé', 120, 'g', 'required',
     'charcuterie', false, 9);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Sortir le confit du froid une demi-heure à l''avance, le temps que la graisse figée se détende. On part de deux cuisses confites telles qu''on les achète, environ 180 g pièce avec l''os et leur couche de graisse : elles rendront les 200 g de chair comestible portés dans la liste.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Racler la graisse de couverture et la garder de côté pour un autre usage. Coucher les cuisses peau vers le bas dans une poêle encore froide, sans rien ajouter, puis monter à feu moyen : la graisse résiduelle fond seule et sert de bain de friture.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Laisser la peau grésiller six à huit minutes sans y toucher, jusqu''à ce qu''elle brunisse et durcisse, retourner deux minutes, puis débarrasser sur une grille pour que le dessous ne ramollisse pas dans son jus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Dès que les cuisses se manipulent, ôter l''os et les cartilages, séparer la peau croustillante et la briser en éclats, puis défaire la chair en filaments à la fourchette. Garder l''ensemble au tiède, pas au chaud.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Râper les tomates sur la grille moyenne au-dessus d''un bol, saler d''une pincée prise sur les 3 g et laisser rendre l''eau cinq minutes, puis évacuer ce jus clair qui délaverait la sauce.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Dans un autre bol, délayer la moutarde avec le vinaigre, une pincée de sel et un tour de moulin à poivre, puis incorporer l''huile en mince filet sans cesser de fouetter, jusqu''à obtenir une sauce lisse qui nappe le dos d''une cuillère.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Remettre la poêle du confit sur feu moyen sans la laver, une fois la vinaigrette montée et non avant : les gésiers doivent arriver chauds dans l''assiette et n''attendent pas. Y coucher les gésiers de canard confits, débarrassés à la main du gras figé qui les enrobe, et les laisser raffermir et grésiller trois à quatre minutes en les retournant une fois, jusqu''à ce que les arêtes brunissent — réchauffés trop doucement ils restent caoutchouteux, poussés trop loin ils durcissent d''un coup. Les tailler chacun en deux ou trois morceaux dans l''épaisseur, jamais en dés, et les garder dans la poêle hors du feu le temps de dresser : un gésier se mange en bouchées qui résistent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Détailler le magret de canard fumé en tranches très fines, deux par personne et une trentaine de grammes par assiette : plus épaisses, elles mâchent au lieu de fondre. Étaler la pulpe de tomate au fond de chaque assiette, répartir dessus la chair de canard encore tiède, les éclats de peau et les morceaux de gésier chauds, puis poser les tranches de magret en éventail sur le bord de l''assiette, là où rien ne les réchauffera. Napper d''un filet de vinaigrette au tout dernier moment et porter à table aussitôt : le gras du magret fumé fond dès qu''il tiédit et emporte son parfum avec lui.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-054-D3', 'recipe_family', 'Salade landaise aux gésiers et au magret fumé',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-054-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-054-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-054-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('a65e67931ecb295f555814ac7b74c96d'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":4,"acidic":3,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":4,"freshness":2,"intensity":4},"dominant_flavors":["gras de canard confit","fumé du magret","abat ferme","acidité vinaigrée","moutarde"],"aroma_families":["rôti","fumée","acidulé"],"target_textures":["peau de canard croustillante","chair effilochée fondante","gésier ferme sous la dent","tranche de magret souple","pulpe de tomate fraîche"],"signature_ingredients":["Confit de canard cuit","Magret de canard fumé","Moutarde de Dijon","Huile d''olive vierge extra"],"identity_guardrails":["Sans canard confit, ce n''est plus une salade landaise : le gras de canard tiédi est le cœur du plat, et les gésiers comme le magret s''ajoutent à lui sans le remplacer.","La sauce doit rester une vinaigrette moutardée et franchement acide, seule capable de trancher le gras du confit et celui du magret fumé, qui portent à eux deux presque tout le gras de l''assiette ; une sauce crémée efface l''identité gasconne.","Le magret fumé se pose froid et cru sur le bord de l''assiette, jamais sur la viande chaude : passé à la poêle ou seulement tiédi, il rend son gras et perd le fumé qui le justifie.","Les gésiers se servent chauds et en gros morceaux : froids ou coupés en dés, ils deviennent caoutchouteux et disparaissent dans la salade."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Salade landaise au foie gras', 'salade landaise au foie gras', 'France', 'France',
     'meal', 'salade composée', 'documented_variation', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Salade landaise au foie gras', 'Salade landaise avec tranche de foie gras de canard en plus du confit', ds.id, 'SRC-054-D4',
    'Myko', 'editorial', 4, 20, 12, 'facile',
    NULL, NULL,
    'B', 'candidate', 'a100c92919a8ac81585985687a1c3cc5',
    '{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":5,"freshness":2,"intensity":4}'::jsonb, ARRAY['foie gras poêlé','gras de canard confit','acidité vinaigrée','moutarde']::text[],
    ARRAY['rôti','abats','acidulé']::text[], ARRAY['foie gras crémeux et tiède','peau de canard croustillante','chair effilochée fondante','pulpe de tomate fraîche']::text[],
    ARRAY['Confit de canard cuit','Foie gras de canard cru','Moutarde de Dijon','Huile d''olive vierge extra']::text[], ARRAY['Sans canard confit, ce n''est plus une salade landaise : le foie gras se pose sur le confit, il ne le remplace pas.','La sauce doit rester une vinaigrette moutardée et franchement acide, seule capable de trancher le gras du confit et celui du foie gras ; une sauce crémée efface l''identité gasconne.','L''escalope se saisit à sec, poêle très chaude et moins d''une minute par face : cuite plus longtemps ou lancée dans une matière grasse ajoutée, elle fond et il ne reste rien à poser au centre.','Le foie gras arrive brûlant sur une base froide et se sert dans la minute : refroidi, il fige et graisse le fond de l''assiette.']::text[],
    ARRAY['saisie','émulsion']::text[], ARRAY[]::text[], ARRAY['moutarde','sulfites']::text[],
    'À manger dans la foulée du dressage, et plus strictement encore que la base : une escalope de foie gras poêlée ne se réchauffe pas, elle refond et se vide de son gras. Le foie gras cru se garde deux jours au plus à 4 °C, serré dans un linge, et se tranche au dernier moment. Les autres éléments tiennent séparément : chair de canard désossée trois jours sous sa graisse, vinaigrette une semaine en bocal fermé, pulpe de tomate le jour même. Rien ne se congèle une fois l''assiette montée ; le foie gras cru entier supporte trois mois au congélateur, jamais tranché.', '{"fridge_hours":72,"eat_immediately":true,"freezable":false,"freezer_months":null,"serve_cold":false,"source":"manual"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-054'), '{"variant_label":"Version festive : une tranche de foie gras de canard posée au centre juste avant de servir.","rationale":"Une escalope de cinquante grammes par assiette, saisie à sec et posée au centre au tout dernier geste : la salade cesse d''être une entrée de tous les jours et devient un plat de fête. Le foie gras n''ajoute pas un goût neuf — on reste dans le canard — mais une texture que rien d''autre ne donne, crémeuse et tiède au milieu de la chair effilochée. Le catalogue ne porte que le foie gras cru : la tranche est donc poêlée plutôt que découpée dans une terrine, ce qui est le choix de l''arbitrage et non un contournement, l''entrée cuite comptant déjà la graisse rendue à la cuisson. Ce que la variante coûte est franc : cinquante grammes de foie gras cru pèsent trois cents kilocalories, davantage à eux seuls que tout le reste de l''assiette réuni, la fenêtre de cuisson tient dans trente secondes de part et d''autre, et l''assiette ne se rattrape pas — refroidi, le foie gras fige et graisse le fond.","operations":[{"op":"add","form":"Foie gras de canard cru","quantity":200,"unit":"g","role":"protéine","optional":false}],"steps":[{"op":"insert","after":6,"instruction":"Sortir le foie gras du froid au dernier moment et le trancher en quatre escalopes d''un bon centimètre, la lame passée sous l''eau chaude et essuyée entre chaque coupe pour qu''elle glisse au lieu d''écraser. Chauffer une poêle à sec jusqu''à ce qu''elle commence à peine à fumer, assaisonner les escalopes des deux côtés d''une pincée prise sur le sel restant et d''un tour de moulin, puis les saisir trente à quarante secondes par face : le dessus doit être coloré et le centre encore crémeux. Les débarrasser aussitôt sur du papier absorbant — laissées dans la poêle, elles continuent de fondre et il ne reste qu''une flaque de graisse."},{"op":"replace","n":7,"instruction":"Étaler la pulpe de tomate au fond de chaque assiette, disposer la chair de canard tiède et les éclats de peau en couronne autour d''un creux laissé libre, napper d''un filet de vinaigrette, puis poser l''escalope de foie gras brûlante dans ce creux au tout dernier geste. Porter à table sans attendre : le foie gras poêlé continue de rendre son gras dans l''assiette et fige dès qu''il refroidit, et c''est la seule pièce du plat qu''on ne peut pas servir tiède."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'confit de canard cuit' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Confit de canard cuit', 200, 'g', 'required',
     'protéine', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'tomate rapee' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Tomate râpée', 200, 'g', 'required',
     'légume', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'huile d olive vierge extra' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Huile d''olive vierge extra', 28, 'g', 'required',
     'matière grasse', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
