  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Sortir le confit du froid une demi-heure à l''avance, le temps que la graisse figée se détende. On part de deux cuisses confites telles qu''on les achète, environ 180 g pièce avec l''os et leur couche de graisse : elles rendront les 200 g de chair comestible portés dans la liste.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Racler la graisse de couverture et la garder de côté pour un autre usage. Coucher les cuisses peau vers le bas dans une poêle encore froide, sans rien ajouter, puis monter à feu moyen : la graisse résiduelle fond seule et sert de bain de friture.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Laisser la peau grésiller six à huit minutes sans y toucher, jusqu''à ce qu''elle brunisse et durcisse, retourner deux minutes, puis débarrasser sur une grille pour que le dessous ne ramollisse pas dans son jus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Dès que les cuisses se manipulent, ôter l''os et les cartilages, séparer la peau croustillante et la briser en éclats, puis défaire la chair en filaments à la fourchette. Garder l''ensemble au tiède, pas au chaud.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Râper les tomates sur la grille moyenne au-dessus d''un bol, saler d''une pincée prise sur les 3 g et laisser rendre l''eau cinq minutes, puis évacuer ce jus clair qui délaverait la sauce.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Dans un autre bol, délayer la moutarde avec le vinaigre, une pincée de sel et un tour de moulin à poivre, puis incorporer l''huile en mince filet sans cesser de fouetter, jusqu''à obtenir une sauce lisse qui nappe le dos d''une cuillère.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Sortir le foie gras du froid au dernier moment et le trancher en quatre escalopes d''un bon centimètre, la lame passée sous l''eau chaude et essuyée entre chaque coupe pour qu''elle glisse au lieu d''écraser. Chauffer une poêle à sec jusqu''à ce qu''elle commence à peine à fumer, assaisonner les escalopes des deux côtés d''une pincée prise sur le sel restant et d''un tour de moulin, puis les saisir trente à quarante secondes par face : le dessus doit être coloré et le centre encore crémeux. Les débarrasser aussitôt sur du papier absorbant — laissées dans la poêle, elles continuent de fondre et il ne reste qu''une flaque de graisse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Étaler la pulpe de tomate au fond de chaque assiette, disposer la chair de canard tiède et les éclats de peau en couronne autour d''un creux laissé libre, napper d''un filet de vinaigrette, puis poser l''escalope de foie gras brûlante dans ce creux au tout dernier geste. Porter à table sans attendre : le foie gras poêlé continue de rendre son gras dans l''assiette et fige dès qu''il refroidit, et c''est la seule pièce du plat qu''on ne peut pas servir tiède.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-054-D4', 'recipe_family', 'Salade landaise au foie gras',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-054-D4', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-054-D4', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-054-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('a100c92919a8ac81585985687a1c3cc5'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":5,"freshness":2,"intensity":4},"dominant_flavors":["foie gras poêlé","gras de canard confit","acidité vinaigrée","moutarde"],"aroma_families":["rôti","abats","acidulé"],"target_textures":["foie gras crémeux et tiède","peau de canard croustillante","chair effilochée fondante","pulpe de tomate fraîche"],"signature_ingredients":["Confit de canard cuit","Foie gras de canard cru","Moutarde de Dijon","Huile d''olive vierge extra"],"identity_guardrails":["Sans canard confit, ce n''est plus une salade landaise : le foie gras se pose sur le confit, il ne le remplace pas.","La sauce doit rester une vinaigrette moutardée et franchement acide, seule capable de trancher le gras du confit et celui du foie gras ; une sauce crémée efface l''identité gasconne.","L''escalope se saisit à sec, poêle très chaude et moins d''une minute par face : cuite plus longtemps ou lancée dans une matière grasse ajoutée, elle fond et il ne reste rien à poser au centre.","Le foie gras arrive brûlant sur une base froide et se sert dans la minute : refroidi, il fige et graisse le fond de l''assiette."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Salade landaise à la truite fumée', 'salade landaise a la truite fumee', 'France', 'France',
     'meal', 'salade composée', 'documented_variation', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Salade landaise à la truite fumée', 'Salade avec confit de canard et filet de truite fumée en vinaigrette moutardée', ds.id, 'SRC-054-D5',
    'Myko', 'editorial', 4, 20, 10, 'facile',
    NULL, NULL,
    'B', 'candidate', 'e03523eec7cb4dcba1de7317bcb5f698',
    '{"sweet":1,"salty":4,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":3,"freshness":3,"intensity":3}'::jsonb, ARRAY['gras de canard confit','truite fumée','acidité vinaigrée','moutarde']::text[],
    ARRAY['rôti','fumée','marine']::text[], ARRAY['peau de canard croustillante','chair effilochée fondante','lanières de truite souples et froides','pulpe de tomate fraîche']::text[],
    ARRAY['Confit de canard cuit','Truite fumée','Moutarde de Dijon','Huile d''olive vierge extra']::text[], ARRAY['Le canard confit reste dans l''assiette, en quantité réduite mais présent : la truite en remplace une partie, jamais la totalité, sans quoi le plat n''a plus rien de landais.','La sauce doit rester une vinaigrette moutardée et franchement acide, seule capable de tenir ensemble un gras tiède et un poisson fumé ; une sauce crémée efface l''identité gasconne.','La truite se sert froide et telle quelle, en lanières taillées au dernier moment : passée à la poêle ou seulement tiédie, elle s''effrite et perd le fumé qui la justifie.','Le canard se pose tiède, la truite froide, sur une base non assaisonnée à l''avance : tout mettre à la même température transforme le plat en autre chose.']::text[],
    ARRAY['saisie','émulsion']::text[], ARRAY[]::text[], ARRAY['moutarde','sulfites','poisson']::text[],
    'À manger dans la foulée du dressage. La truite fumée sous vide se garde jusqu''à sa date, mais deux jours seulement une fois le sachet ouvert, et elle se détaille au dernier moment : les lanières coupées à l''avance sèchent et se collent entre elles. Les autres éléments se gardent séparément : chair de canard désossée trois jours à 4 °C sous sa graisse, vinaigrette une semaine en bocal fermé, pulpe de tomate le jour même. Ne se congèle pas : la tomate râpée rend son eau, la peau de canard ramollit, et une truite déjà fumée devient farineuse à la décongélation.', '{"fridge_hours":72,"eat_immediately":true,"freezable":false,"freezer_months":null,"serve_cold":false,"source":"manual"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-054'), '{"variant_label":"Variante landaise à la truite fumée, détaillée en lanières, en remplacement d''une partie du canard.","rationale":"Le confit descend de deux cuisses à une seule, cent vingt grammes de chair au lieu de deux cents, et cent cinquante grammes de truite fumée viennent occuper la place — plus large, en vérité, que celle qui vient d''être libérée : l''assiette passe de deux cents à deux cent soixante-dix grammes de protéine, soit soixante-sept grammes par personne, et bascule de l''entrée vers la salade de repas. Elle garde son ossature gasconne — la peau croustillante, le gras tiède, la vinaigrette moutardée — mais l''oppose désormais à un poisson froid, salé et fumé au lieu de la doubler. Ce qui recule est la sensation de graisse fondue, non la graisse elle-même : la truite fumée porte moins de la moitié des lipides d''une chair de confit aux cent grammes, mais comme il en entre presque deux fois plus qu''il n''est sorti de canard, le gras de l''assiette perd moins d''un dixième et l''énergie ne recule pas du tout — elle monte même de quelques kilocalories par part. Le vrai coût est ailleurs : un allergène de plus, le poisson, dans une recette qui n''en portait aucun ; un sel qui passe d''environ un gramme et demi à près de deux grammes et demi par part, la truite fumée en portant trois aux cent grammes ; et une contrainte de dressage — la truite doit rester froide et se détailler au dernier moment, sans quoi ses lanières sèchent et se collent entre elles.","operations":[{"op":"set","form":"Confit de canard cuit","quantity":120,"role":"protéine"},{"op":"add","form":"Truite fumée","quantity":150,"unit":"g","role":"protéine","optional":false}],"steps":[{"op":"replace","n":1,"instruction":"Sortir le confit du froid une demi-heure à l''avance, le temps que la graisse figée se détende. Ici une seule cuisse suffit, la plus grosse du bocal, environ 220 g avec l''os et sa couche de graisse : elle rendra les 120 g de chair comestible portés dans la liste, la truite fumée tenant le reste de l''assiette."},{"op":"replace","n":2,"instruction":"Racler la graisse de couverture et la garder de côté pour un autre usage. Coucher la cuisse peau vers le bas dans une poêle encore froide, sans rien ajouter, puis monter à feu moyen : la graisse résiduelle fond seule et sert de bain de friture. Une seule pièce dans une grande poêle colore mieux qu''un fond encombré, il n''y a donc pas lieu de prendre plus petit."},{"op":"replace","n":4,"instruction":"Dès que la cuisse se manipule, ôter l''os et les cartilages, séparer la peau croustillante et la briser en éclats, puis défaire la chair en filaments à la fourchette. Garder l''ensemble au tiède, pas au chaud."},{"op":"insert","after":4,"instruction":"Détailler la truite fumée en lanières d''un bon centimètre, en suivant le sens des feuillets plutôt qu''en travers : coupée à contresens, elle se casse en miettes qui disparaîtront dans la salade. La garder au réfrigérateur jusqu''au dressage et à l''écart de la poêle — un poisson fumé posé dans la chaleur perd son gras et sa fermeté en quelques minutes."},{"op":"replace","n":7,"instruction":"Étaler la pulpe de tomate au fond de chaque assiette, répartir dessus la chair de canard encore tiède et les éclats de peau, puis entrelacer les lanières de truite fumée sorties du froid, sans les poser sur la viande chaude. Napper d''un filet de vinaigrette au tout dernier moment et porter à table aussitôt : le contraste s''efface en quelques minutes, et il joue ici entre le gras tiède du canard et le fumé froid du poisson."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'confit de canard cuit' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Confit de canard cuit', 120, 'g', 'required',
     'protéine', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'tomate rapee' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Tomate râpée', 200, 'g', 'required',
     'légume', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'huile d olive vierge extra' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Huile d''olive vierge extra', 28, 'g', 'required',
     'matière grasse', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'vinaigre de vin rouge' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Vinaigre de vin rouge', 15, 'g', 'required',
     'acide', false, 4);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'moutarde de dijon' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Moutarde de Dijon', 5, 'g', 'required',
     'condiment émulsifiant', false, 5);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 3, 'g', 'optional',
     'assaisonnement', true, 6);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'optional',
     'assaisonnement', true, 7);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'truite fumee' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Truite fumée', 150, 'g', 'required',
     'protéine', false, 8);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Sortir le confit du froid une demi-heure à l''avance, le temps que la graisse figée se détende. Ici une seule cuisse suffit, la plus grosse du bocal, environ 220 g avec l''os et sa couche de graisse : elle rendra les 120 g de chair comestible portés dans la liste, la truite fumée tenant le reste de l''assiette.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Racler la graisse de couverture et la garder de côté pour un autre usage. Coucher la cuisse peau vers le bas dans une poêle encore froide, sans rien ajouter, puis monter à feu moyen : la graisse résiduelle fond seule et sert de bain de friture. Une seule pièce dans une grande poêle colore mieux qu''un fond encombré, il n''y a donc pas lieu de prendre plus petit.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Laisser la peau grésiller six à huit minutes sans y toucher, jusqu''à ce qu''elle brunisse et durcisse, retourner deux minutes, puis débarrasser sur une grille pour que le dessous ne ramollisse pas dans son jus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Dès que la cuisse se manipule, ôter l''os et les cartilages, séparer la peau croustillante et la briser en éclats, puis défaire la chair en filaments à la fourchette. Garder l''ensemble au tiède, pas au chaud.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Détailler la truite fumée en lanières d''un bon centimètre, en suivant le sens des feuillets plutôt qu''en travers : coupée à contresens, elle se casse en miettes qui disparaîtront dans la salade. La garder au réfrigérateur jusqu''au dressage et à l''écart de la poêle — un poisson fumé posé dans la chaleur perd son gras et sa fermeté en quelques minutes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Râper les tomates sur la grille moyenne au-dessus d''un bol, saler d''une pincée prise sur les 3 g et laisser rendre l''eau cinq minutes, puis évacuer ce jus clair qui délaverait la sauce.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Dans un autre bol, délayer la moutarde avec le vinaigre, une pincée de sel et un tour de moulin à poivre, puis incorporer l''huile en mince filet sans cesser de fouetter, jusqu''à obtenir une sauce lisse qui nappe le dos d''une cuillère.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Étaler la pulpe de tomate au fond de chaque assiette, répartir dessus la chair de canard encore tiède et les éclats de peau, puis entrelacer les lanières de truite fumée sorties du froid, sans les poser sur la viande chaude. Napper d''un filet de vinaigrette au tout dernier moment et porter à table aussitôt : le contraste s''efface en quelques minutes, et il joue ici entre le gras tiède du canard et le fumé froid du poisson.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-054-D5', 'recipe_family', 'Salade landaise à la truite fumée',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-054-D5', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-054-D5', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-054-D5', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('e03523eec7cb4dcba1de7317bcb5f698'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":4,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":3,"freshness":3,"intensity":3},"dominant_flavors":["gras de canard confit","truite fumée","acidité vinaigrée","moutarde"],"aroma_families":["rôti","fumée","marine"],"target_textures":["peau de canard croustillante","chair effilochée fondante","lanières de truite souples et froides","pulpe de tomate fraîche"],"signature_ingredients":["Confit de canard cuit","Truite fumée","Moutarde de Dijon","Huile d''olive vierge extra"],"identity_guardrails":["Le canard confit reste dans l''assiette, en quantité réduite mais présent : la truite en remplace une partie, jamais la totalité, sans quoi le plat n''a plus rien de landais.","La sauce doit rester une vinaigrette moutardée et franchement acide, seule capable de tenir ensemble un gras tiède et un poisson fumé ; une sauce crémée efface l''identité gasconne.","La truite se sert froide et telle quelle, en lanières taillées au dernier moment : passée à la poêle ou seulement tiédie, elle s''effrite et perd le fumé qui la justifie.","Le canard se pose tiède, la truite froide, sur une base non assaisonnée à l''avance : tout mettre à la même température transforme le plat en autre chose."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Saumon à l''oseille au vermouth', 'saumon a l oseille au vermouth', 'France', 'France',
     'meal', 'plat de poisson', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Saumon à l''oseille au vermouth', 'Saumon saisi puis nappé d''une sauce crème-oseille déglacée au vermouth sec', ds.id, 'SRC-055-D1',
    'Myko', 'editorial', 4, 20, 20, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '3d98e5ab0aa1499200d1cc25b7f8f0f1',
    '{"sweet":2,"salty":3,"acidic":3,"bitter":2,"umami":3,"heat":0,"pungency":1,"richness":5,"freshness":3,"intensity":4}'::jsonb, ARRAY['acidulé végétal','amertume aromatique du vermouth','lacté beurré','gras iodé du saumon']::text[],
    ARRAY['lactée','végétale acidulée','aromatique amère','marine']::text[], ARRAY['chair nacrée qui se détache en feuillets','sauce nappante','oseille fondue']::text[],
    ARRAY['Pavé de saumon cru, sans peau','Oseille crue','Crème fraîche liquide entière']::text[], ARRAY['Sans oseille fondue dans la crème, ce n''est plus un saumon à l''oseille : c''est son acidité citronnée qui coupe le gras du poisson et de la crème, aucun jus de citron ne la remplace.','Le saumon est saisi à part et nappé au dernier moment, jamais cuit dans la sauce : pochée dedans, la chair grise, se dessèche et perd le nacré qui fait le plat.','Le vermouth se réduit jusqu''au sirop comme le ferait un vin : versé et laissé tel quel, il garde un goût d''apéritif et de sucre qui domine l''oseille.','La liaison se fait à la crème réduite, sans farine ni roux — une sauce épaissie à la farine transforme le plat en gratin de poisson.']::text[],
    ARRAY['saisie','réduction','déglaçage','émulsion']::text[], ARRAY[]::text[], ARRAY['poisson','lait','sulfites']::text[],
    'La sauce à l''oseille se garde 48 h à 4 °C dans un bocal fermé et se réchauffe à feu très doux sans jamais bouillir ; le saumon cuit se conserve 24 h au réfrigérateur et se mange plutôt froid ou tiède, un réchauffage le dessèche. Ni la sauce ni le poisson ne supportent la congélation : la crème tranche à la décongélation, l''oseille rend son eau et devient filandreuse, et la chair du saumon se délite. Congeler éventuellement l''oseille crue ciselée en portions, à jeter telle quelle dans la crème chaude.', '{"fridge_hours":24,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-055'), '{"variant_label":"Remplacer le vin blanc sec par la même quantité de vermouth sec, comme le fait l''une des sources du dossier.","rationale":"Cinquante grammes de vermouth pour cinquante millilitres de vin blanc, soit la même quantité au gramme près, et ce n''est pas un simple changement de bouteille : le vermouth apporte l''absinthe, le quinquina et les écorces de son infusion, qui survivent à la réduction là où un vin blanc ne laisse que son acidité. La sauce y gagne une amertume aromatique qui répond à l''acidité de l''oseille au lieu de la doubler. Ce qu''elle y perd est de la franchise : un vermouth reste plus sucré et moins acide qu''un vin sec, il faut donc goûter avant de saler et accepter une sauce plus ronde. Réserve de mesure, à dire puisqu''elle est connue : la forme retenue au catalogue est un aliment moyen d''apéritifs à base de vin, plus sucré qu''un vermouth réellement sec, mais sur cinquante grammes de déglaçage l''écart ne dépasse pas trois kilocalories par part.","operations":[{"op":"substitute","form":"Vin blanc sec","with":"Vermouth sec","quantity":50,"unit":"g","role":"déglaçage"}],"steps":[{"op":"replace","n":4,"instruction":"Mouiller au vermouth sec, remonter le feu et conduire la réduction jusqu''au sirop, presque à sec. Compter une minute de plus qu''avec un blanc ordinaire : un vermouth est muté, seize à dix-huit degrés contre douze, et son alcool demande d''autant plus de temps pour s''évacuer. Son sucre, lui, épaissit la réduction avant qu''elle ne s''assèche : ne pas quitter la sauteuse et gratter le fond au fouet, les plantes amères s''y attachent et brûleraient là où elles doivent revenir dans le liquide."},{"op":"replace","n":5,"instruction":"Ajouter la crème, ramener à petits frémissements et laisser épaissir quelques minutes, jusqu''à ce qu''un trait tracé au doigt tienne au dos de la cuillère. Goûter avant de saler : le vermouth a laissé une amertume douce que le sel amplifie, et c''est le dernier moment pour rectifier, la sauce ne se resalera plus une fois l''oseille dedans."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'pave de saumon cru sans peau' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Pavé de saumon cru, sans peau', 600, 'g', 'required',
     'protéine', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'oseille crue' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Oseille crue', 200, 'g', 'required',
     'légume signature', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'creme fraiche liquide entiere' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Crème fraîche liquide entière', 150, 'ml', 'required',
     'liaison', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'echalote crue' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Échalote crue', 60, 'g', 'required',
     'aromate', false, 4);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'beurre doux' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Beurre doux', 30, 'g', 'required',
     'matière grasse', false, 5);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'vermouth sec' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Vermouth sec', 50, 'g', 'required',
     'déglaçage', false, 6);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'huile d olive vierge extra' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Huile d''olive vierge extra', 30, 'ml', 'required',
     'matière grasse de cuisson', false, 7);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 4, 'g', 'optional',
     'assaisonnement', true, 8);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'optional',
     'assaisonnement', true, 9);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir chez le poissonnier un tronçon de saumon d''environ 800 g avec sa peau : une fois la peau détachée au couteau souple et les arêtes retirées à la pince, il reste les 600 g de chair nette de la liste, à recouper en quatre pavés réguliers de 150 g. Les garder au frais, à plat sur une assiette.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Compter à peu près 300 g d''oseille en bottes pour obtenir les 200 g de feuilles nettes : effeuiller, ôter la côte centrale en tirant la nervure de la base vers la pointe, laver à grande eau, essorer sans écraser puis tailler grossièrement en larges lanières.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Peler et hacher menu les échalotes. Les laisser suer dans le beurre à feu doux, en sauteuse large, jusqu''à ce qu''elles perdent leur mordant et deviennent translucides sans prendre la moindre couleur, environ trois minutes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Mouiller au vermouth sec, remonter le feu et conduire la réduction jusqu''au sirop, presque à sec. Compter une minute de plus qu''avec un blanc ordinaire : un vermouth est muté, seize à dix-huit degrés contre douze, et son alcool demande d''autant plus de temps pour s''évacuer. Son sucre, lui, épaissit la réduction avant qu''elle ne s''assèche : ne pas quitter la sauteuse et gratter le fond au fouet, les plantes amères s''y attachent et brûleraient là où elles doivent revenir dans le liquide.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter la crème, ramener à petits frémissements et laisser épaissir quelques minutes, jusqu''à ce qu''un trait tracé au doigt tienne au dos de la cuillère. Goûter avant de saler : le vermouth a laissé une amertume douce que le sel amplifie, et c''est le dernier moment pour rectifier, la sauce ne se resalera plus une fois l''oseille dedans.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Jeter les lanières d''oseille dans la crème chaude, feu coupé ou très doux : elles s''affaissent et virent au vert olive en moins d''une minute. Arrêter là et réserver à couvert sans bouillir — une cuisson prolongée brunit l''oseille et efface l''acidité qui fait tout le plat.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Chauffer l''huile d''olive dans une poêle jusqu''à ce qu''elle ondule. Assaisonner les pavés sur les deux faces, les poser sans les serrer et les saisir environ trois minutes sur la première face, deux sur la seconde : le cœur doit rester légèrement translucide et se détacher en larges feuillets.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Dresser les pavés dans des assiettes chaudes, les napper de sauce à l''oseille au tout dernier moment et servir aussitôt, avec des pommes de terre vapeur ou de larges pâtes fraîches.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-055-D1', 'recipe_family', 'Saumon à l''oseille au vermouth',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-055-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-055-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-055-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('3d98e5ab0aa1499200d1cc25b7f8f0f1'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":2,"salty":3,"acidic":3,"bitter":2,"umami":3,"heat":0,"pungency":1,"richness":5,"freshness":3,"intensity":4},"dominant_flavors":["acidulé végétal","amertume aromatique du vermouth","lacté beurré","gras iodé du saumon"],"aroma_families":["lactée","végétale acidulée","aromatique amère","marine"],"target_textures":["chair nacrée qui se détache en feuillets","sauce nappante","oseille fondue"],"signature_ingredients":["Pavé de saumon cru, sans peau","Oseille crue","Crème fraîche liquide entière"],"identity_guardrails":["Sans oseille fondue dans la crème, ce n''est plus un saumon à l''oseille : c''est son acidité citronnée qui coupe le gras du poisson et de la crème, aucun jus de citron ne la remplace.","Le saumon est saisi à part et nappé au dernier moment, jamais cuit dans la sauce : pochée dedans, la chair grise, se dessèche et perd le nacré qui fait le plat.","Le vermouth se réduit jusqu''au sirop comme le ferait un vin : versé et laissé tel quel, il garde un goût d''apéritif et de sucre qui domine l''oseille.","La liaison se fait à la crème réduite, sans farine ni roux — une sauce épaissie à la farine transforme le plat en gratin de poisson."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Saumon à l''oseille sur pâtes fraîches', 'saumon a l oseille sur pates fraiches', 'France', 'France',
     'meal', 'plat de poisson', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Saumon à l''oseille sur pâtes fraîches', 'Saumon en sauce crème-oseille au vin blanc, servi sur des pâtes fraîches aux œufs', ds.id, 'SRC-055-D2',
    'Myko', 'editorial', 4, 25, 25, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'e89caf32de24453ac33833d7e7a87a14',
    '{"sweet":1,"salty":3,"acidic":4,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":3,"intensity":3}'::jsonb, ARRAY['acidulé végétal','lacté beurré','gras iodé du saumon']::text[],
    ARRAY['lactée','végétale acidulée','marine']::text[], ARRAY['pâtes fraîches souples','chair nacrée effeuillée','sauce nappante','oseille fondue','lanières d''oseille crue']::text[],
    ARRAY['Pavé de saumon cru, sans peau','Oseille crue','Crème fraîche liquide entière']::text[], ARRAY['Sans oseille fondue dans la crème, ce n''est plus un saumon à l''oseille : c''est son acidité citronnée qui coupe le gras du poisson et de la crème, aucun jus de citron ne la remplace.','Le saumon est saisi à part et effeuillé au dressage, jamais cuit ni réchauffé dans la sauce : mêlé aux pâtes brûlantes puis attendu, il grise et se dessèche.','La poignée d''oseille crue du dressage n''est pas une décoration : elle rend l''acidité que la sauce perd en s''étendant sur un féculent, et elle se sème hors du feu.','La liaison se fait à la crème réduite, sans farine ni roux — une sauce épaissie à la farine transforme le plat en gratin de pâtes.']::text[],
    ARRAY['saisie','réduction','déglaçage','émulsion']::text[], ARRAY[]::text[], ARRAY['poisson','lait','sulfites','gluten','œuf']::text[],
    'Rien ne se garde une fois monté : les pâtes fraîches boivent la sauce en un quart d''heure et l''assiette devient pâteuse. La sauce à l''oseille se garde 48 h à 4 °C en bocal fermé et se réchauffe à feu très doux sans jamais bouillir ; le saumon cuit tient 24 h au réfrigérateur et se mange plutôt froid ou tiède. Les pâtes fraîches crues se gardent deux jours au frais dans leur farine et cuisent alors une trentaine de secondes de plus. Ni la sauce ni le poisson ne supportent la congélation : la crème tranche, l''oseille rend son eau et devient filandreuse, la chair du saumon se délite et les pâtes cuites tournent en bouillie. Congeler éventuellement l''oseille crue ciselée en portions, à jeter telle quelle dans la crème chaude.', '{"fridge_hours":24,"eat_immediately":true,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-055'), '{"variant_label":"Servir la sauce et le saumon effeuillé sur de larges pâtes fraîches, en parsemant au dressage quelques lanières d''oseille crue pour relancer l''acidité.","rationale":"Ce n''est pas un accompagnement posé à côté : les quatre cents grammes de pâtes fraîches sont mêlés à la sauce, le pavé y est effeuillé, et le plat devient une assiette unique où le poisson n''est plus une pièce mais une garniture. L''oseille se dédouble pour tenir le coup — deux cent cinquante grammes au lieu de deux cents, dont cinquante réservés crus et semés au dressage, parce qu''une sauce étendue sur un féculent perd l''acidité qui la définit. Le volume, lui, se rattrape à l''eau de cuisson des pâtes et non à la crème : les cent cinquante millilitres de la base ont été calculés pour napper quatre pavés, ils doivent maintenant enrober quatre cents grammes de pâtes en plus, et une louche d''eau farineuse les allonge là où une crème supplémentaire ne ferait qu''alourdir. Le prix est celui du féculent : cent grammes de pâtes fraîches par personne ajoutent l''œuf et le gluten à une recette qui n''en portait pas, et une part passe de poisson en sauce à plat complet. Le prix est aussi celui de la minute : des pâtes fraîches cuisent en deux ou trois minutes et boivent la sauce en un quart d''heure, si bien que le dressage ne souffre aucun retard.","operations":[{"op":"add","form":"Pâtes fraîches aux œufs crues","quantity":400,"unit":"g","role":"féculent","optional":false},{"op":"set","form":"Oseille crue","quantity":250,"role":"légume signature"}],"steps":[{"op":"replace","n":2,"instruction":"Compter à peu près 375 g d''oseille en bottes pour obtenir les 250 g de feuilles nettes : effeuiller, ôter la côte centrale en tirant la nervure de la base vers la pointe, laver à grande eau, essorer sans écraser puis tailler grossièrement en larges lanières. Mettre à part une poignée d''une cinquantaine de grammes, choisie parmi les feuilles les plus jeunes : elle ne verra pas la casserole et ira crue sur les assiettes au dressage."},{"op":"replace","n":6,"instruction":"Jeter dans la crème chaude les seules lanières destinées à la sauce, feu coupé ou très doux, en laissant la poignée réservée de côté : elles s''affaissent et virent au vert olive en moins d''une minute. Arrêter là et réserver à couvert sans bouillir — une cuisson prolongée brunit l''oseille et efface l''acidité qui fait tout le plat, et c''est justement pour la rendre que l''on a gardé des feuilles crues."},{"op":"insert","after":6,"instruction":"Mettre à chauffer une grande casserole d''eau salée avant de toucher au poisson. Des pâtes fraîches cuisent en deux ou trois minutes et doivent trouver leur eau à gros bouillons au moment où le saumon sort de la poêle, jamais l''inverse : c''est l''eau qui attend le poisson, pas le poisson qui attend l''eau."},{"op":"replace","n":8,"instruction":"Plonger les pâtes fraîches aux œufs dans l''eau bouillante et les égoutter dès qu''elles remontent et cèdent sous la dent, deux à trois minutes, sans les rincer — la farine qu''elles gardent en surface aide la sauce à tenir. Prélever une petite louche de cette eau blanchie avant d''égoutter : la sauce a été montée pour napper quatre pavés et doit maintenant enrober les pâtes avec eux. Les mêler délicatement à la sauce à l''oseille hors du feu, en rendant l''eau réservée cuillerée par cuillerée jusqu''à ce que la sauce enrobe sans couler, et les répartir dans des assiettes chaudes. Effeuiller les pavés à la fourchette en larges lamelles, en suivant les feuillets de la chair, les coucher sur les pâtes, puis semer les lanières d''oseille crue réservées et servir aussitôt : crue, l''oseille garde un mordant acide et un vert franc que la cuisson dans la crème efface en moins d''une minute."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'pave de saumon cru sans peau' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Pavé de saumon cru, sans peau', 600, 'g', 'required',
     'protéine', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'oseille crue' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Oseille crue', 250, 'g', 'required',
     'légume signature', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'creme fraiche liquide entiere' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Crème fraîche liquide entière', 150, 'ml', 'required',
     'liaison', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
