DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Spaghetti bolognaise au vin rouge', 'spaghetti bolognaise au vin rouge', 'France / cuisine domestique internationale', 'France / cuisine domestique internationale',
     'meal', 'pâtes en sauce', 'documented_variation', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Spaghetti bolognaise au vin rouge', 'Spaghetti nappés d''un ragù de bœuf haché au soffritto, déglacé au vin rouge avant la tomate', ds.id, 'IT-004-D1',
    'Myko', 'editorial', 6, 20, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', '6735090e53e257aa2f3f0925b9d178d5',
    '{"sweet":2,"salty":3,"acidic":3,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":4}'::jsonb, ARRAY['tomate cuite','viande rissolée','légume compoté']::text[],
    ARRAY['tomate_cuite','oignon_compoté','viande_rissolée','thym']::text[], ARRAY['sauce_nappante','pâtes_fermes','haché_fondant']::text[],
    ARRAY['Spaghetti secs','Bœuf haché cru 15 % MG','Tomate concassée en conserve','Carotte crue','Céleri branche cru']::text[], ARRAY['Sans le trio oignon-carotte-céleri fondu au départ, il reste une sauce tomate à la viande : c''est le soffritto qui donne au plat son sucre et son corps, et cinq à six sources sur huit le portent.','La viande hachée doit rissoler avant d''être mouillée ; pochée directement dans la tomate, elle ne développe rien et la sauce reste plate quelle que soit la durée du mijotage.','La tomate doit être une base longuement réduite, pas un concentré délayé : deux sources font l''inverse et produisent une autre sauce, épaisse et sucrée, qui ne mijote pas.','Les pâtes se terminent dans la sauce avec un peu de leur eau de cuisson ; servies nues avec la sauce posée dessus, le plat se dissocie dans l''assiette.']::text[],
    ARRAY['soffritto','saisie du haché','cuisson du concentré','mijotage','cuisson al dente','enrobage à l''eau de cuisson']::text[], ARRAY[]::text[], ARRAY['gluten','céleri','lait']::text[],
    'La sauce se garde quatre jours au réfrigérateur dans un récipient fermé et gagne à être faite la veille : la tomate finit de perdre son acidité au froid. Elle se congèle trois mois, sans les pâtes. Réchauffer à feu doux avec une cuillerée d''eau. Les pâtes déjà enrobées ne se conservent pas plus de vingt-quatre heures et ne se congèlent pas : elles rendent leur eau et deviennent farineuses.', '{"fridge_hours":24,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'IT-004'), '{"variant_label":"Déglaçage au vin rouge avant la tomate (deux sources sur huit)","rationale":"Le vin rouge déglace les sucs de la viande avant la tomate : il ramasse ce que la viande a laissé au fond, l''acidité s''évapore à la chaleur et il reste une profondeur que la tomate seule ne donnerait pas. C''est la méthode de deux sources sur huit — minoritaire mais documentée.","operations":[{"op":"add","form":"Vin rouge sec","quantity":150,"unit":"ml","role":"déglaçage"}],"steps":[{"op":"insert","after":3,"instruction":"Verser le vin rouge dans la sauteuse et gratter immédiatement les sucs caramélisés du fond à la cuillère de bois. Laisser réduire à feu vif jusqu''à presque complète évaporation — une à deux minutes suffit, et l''alcool part avant la fumée."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

