     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'champignon de paris frais' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Champignon de Paris frais', 250, 'g', 'required',
     'soffritto', false, 15);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Éplucher oignon, carotte et céleri, puis les tailler en dés de deux à trois millimètres. Émincer finement les champignons de Paris — pas trop petits, ils fondent à la cuisson et disparaîtraient s''ils étaient hachés fin. Le soffritto n''a pas à se retrouver sous la dent : son travail est de fondre dans la sauce et d''en faire le fond sucré et umami.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire chauffer l''huile d''olive dans une sauteuse large, y verser les légumes du soffritto et les champignons émincés, et les laisser suer douze à quinze minutes à feu moyen, en remuant. Les saler d''une pincée dès le début : le sel tire l''eau des légumes et des champignons et les fait fondre au lieu de les colorer. Ils doivent devenir translucides, l''oignon à peine blond, sans jamais roussir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pousser le feu, ajouter le bœuf haché en deux fois et l''écraser à la cuillère de bois pour le détacher. Une viande versée d''un seul coup rend son eau, bouillit dans son jus et ressort grise — c''est cet écueil qu''on évite en procédant en deux fois : c''est la coloration brune, pas grise, qui fait toute la profondeur de la sauce. Attendre que le fond de la sauteuse crépite avant de remuer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ajouter le concentré de tomate et le remuer une bonne minute au contact du fond chaud, le temps qu''il perde son goût métallique de crudité et qu''il fonce. Puis verser la tomate concassée, l''ail écrasé, le thym et le laurier. Rincer la boîte avec un fond d''eau et le verser aussi — c''est de la sauce qui resterait collée au métal.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Laisser mijoter quarante-cinq minutes à découvert, à petits bouillons, en raclant le fond toutes les dix minutes. La sauce est prête quand elle ne coule plus de la cuillère et que la graisse remonte en brillant à la surface. Goûter alors : si l''acidité de la tomate reste piquante, une pincée de sucre l''arrondit mieux qu''un ajout de gras.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Porter à ébullition un grand volume d''eau — comptez un litre et dix grammes de sel pour cent grammes de pâtes — et y cuire les spaghetti. Les égoutter une minute avant le temps du paquet, en réservant une louche d''eau de cuisson. Ne jamais les rincer ni les huiler : l''amidon de surface est ce qui fera tenir la sauce.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Retirer thym et laurier, verser les pâtes dans la sauteuse avec une petite louche d''eau de cuisson et remuer une minute sur le feu. L''amidon lie la sauce aux pâtes et l''enrobe au lieu de la laisser au fond de l''assiette. Servir aussitôt, le parmesan râpé à part pour ceux qui en veulent.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'IT-004-D2', 'recipe_family', 'Spaghetti bolognaise aux champignons',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'IT-004-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'IT-004-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:IT-004-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('595f38cf24f7373f2c32d00fec5c834b'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":2,"salty":3,"acidic":3,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":4},"dominant_flavors":["tomate cuite","viande rissolée","légume compoté"],"aroma_families":["tomate_cuite","oignon_compoté","viande_rissolée","thym"],"target_textures":["sauce_nappante","pâtes_fermes","haché_fondant"],"signature_ingredients":["Spaghetti secs","Bœuf haché cru 15 % MG","Tomate concassée en conserve","Carotte crue","Céleri branche cru"],"identity_guardrails":["Sans le trio oignon-carotte-céleri fondu au départ, il reste une sauce tomate à la viande : c''est le soffritto qui donne au plat son sucre et son corps, et cinq à six sources sur huit le portent.","La viande hachée doit rissoler avant d''être mouillée ; pochée directement dans la tomate, elle ne développe rien et la sauce reste plate quelle que soit la durée du mijotage.","La tomate doit être une base longuement réduite, pas un concentré délayé : deux sources font l''inverse et produisent une autre sauce, épaisse et sucrée, qui ne mijote pas.","Les pâtes se terminent dans la sauce avec un peu de leur eau de cuisson ; servies nues avec la sauce posée dessus, le plat se dissocie dans l''assiette."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Minestrone aux tomates pelées en conserve', 'minestrone aux tomates pelees en conserve', 'Italie', 'Italie',
     'meal', 'soupe complète', 'documented_variation', 'brothy_umami',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Minestrone aux tomates pelées en conserve', 'Soupe épaisse de légumes de saison, légumineuses et petites pâtes au bouillon, avec tomates entières pelées en conserve à la place des fraîches', ds.id, 'IT-008-D1',
    'Myko', 'editorial', 8, 30, 55, 'facile',
    NULL, NULL,
    'B', 'candidate', '05f2c242735a608b76e2cfa7057715d1',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":2,"freshness":3,"intensity":3}'::jsonb, ARRAY['bouillon de légumes','tomate','basilic']::text[],
    ARRAY['bouillon','tomate_cuite','oignon_compoté','basilic','céleri']::text[], ARRAY['légumes_tendres_distincts','bouillon_lié','pâtes_fermes']::text[],
    ARRAY['Haricot blanc cuit, égoutté','Petites pâtes sèches','Tomate entière pelée en conserve','Courgette fraîche','Basilic frais']::text[], ARRAY['Un minestrone porte à la fois une légumineuse et un féculent en grain — haricot blanc et petites pâtes ici : sans eux, il reste une soupe de légumes, et six sources sur huit portent l''un ou l''autre.','Les légumes restent en dés distincts sous la cuillère : mixé, le plat devient un velouté et perd la définition qui fait son nom.','Les légumes entrent par ordre de tenue, les durs d''abord et les tendres dix minutes avant la fin ; tous ensemble, la courgette disparaît et la carotte reste crue.','Les pâtes cuisent dans le bouillon et non à part : leur amidon est le seul liant de la soupe, et cuites séparément elles laissent un bouillon clair.']::text[],
    ARRAY['suer','cuisson séquencée par tenue des légumes','cuisson des pâtes dans le bouillon','finition à l''huile crue']::text[], ARRAY[]::text[], ARRAY['gluten','céleri','lait']::text[],
    'Quatre jours au réfrigérateur, et la soupe gagne du goût la deuxième journée. Réserve faite des pâtes : elles continuent d''absorber le bouillon au froid et la soupe se resserre en plat épais — allonger d''un demi-litre de bouillon au réchauffage, ou cuire les pâtes le jour même dans la portion qu''on va servir et garder le reste sans elles. Se congèle trois mois, sans les pâtes ni la pomme de terre, qui se délitent à la décongélation. Réchauffer à frémissement et ajouter le basilic seulement au moment de servir.', '{"fridge_hours":96,"eat_immediately":false,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'IT-008'), '{"variant_label":"Grosse boîte de tomates pelées à la place des tomates fraîches, hors saison (une source sur huit)","rationale":"Hors saison, la tomate fraîche ne rend qu''une eau pâle et acide. La conserve de tomates entières pelées, récoltée mûre, donne une base plus colorée et plus douce, au prix d''une texture légèrement plus fondue. On l''égoutte partiellement pour ne pas noyer le bouillon.","operations":[{"op":"substitute","form":"Tomate fraîche mûre","with":"Tomate entière pelée en conserve","quantity":400,"unit":"g","role":"base"}],"steps":[{"op":"replace","n":4,"instruction":"Ajouter les pommes de terre en dés et les tomates entières pelées égouttées sommairement, en les écrasant grossièrement à la cuillère directement dans la cocotte pour les défaire sans les mixer. Laisser cinq minutes à découvert à feu moyen pour réduire l''acidité avant de mouiller."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
