      WHERE ff.canonical_name_normalized = 'boeuf hache cru 15 mg' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
