      WHERE ff.canonical_name_normalized = 'haricot rouge cuit egoutte' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Haricot rouge cuit, égoutté', 530, 'g', 'required',
     'légumineuse', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
