     'meal', 'légumineuses', 'documented_variation', 'rich_winey',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Lentilles vertes mijotées avec œuf mollet', 'Lentilles vertes mijotées aux légumes en vinaigrette, accompagnées d''un œuf mollet à blanc pris et jaune coulant', ds.id, 'VEG-001-D2',
    'Myko', 'editorial', 6, 20, 40, 'facile',
    NULL, NULL,
    'B', 'candidate', 'a1c6b7bf31d97bc9e26dd840c2c87f40',
    '{"sweet":1,"salty":3,"acidic":2,"bitter":1,"umami":5,"heat":0,"pungency":2,"richness":5,"freshness":1,"intensity":5}'::jsonb, ARRAY['umami','rôti','vinique']::text[],
    ARRAY['ail','oignon_compoté','vin_rouge_réduit','thym','laurier']::text[], ARRAY['protéine_fondante','sauce_nappante']::text[],
    ARRAY['Lentille verte sèche, crue','Carotte crue','Oignon jaune cru','Céleri branche cru']::text[], ARRAY['conserver_les_ingrédients_signatures','conserver_la_technique_centrale','ne_pas_remplacer_par_un_simple_équivalent_nutritionnel']::text[],
    ARRAY['suer','mijotage','assaisonnement tardif','acidification']::text[], ARRAY[]::text[], ARRAY['céleri']::text[],
    '4 jours au réfrigérateur ; congélation 3 mois.', '{"fridge_hours":96,"eat_immediately":false,"freezable":true,"freezer_months":3,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'VEG-001'), '{"variant_label":"œuf mollet","rationale":"Un œuf mollet par assiette complète les lentilles en protéines sans alourdir le plat : le blanc pris et le jaune coulant se mêlent à la vinaigrette et lient le tout. Il se cuit à part pendant que les lentilles terminent leur cuisson.","operations":[{"op":"add","form":"Œuf cru","quantity":4,"unit":"u","role":"protéine"}],"steps":[{"op":"insert","after":3,"instruction":"Porter à ébullition une casserole d''eau et y plonger les œufs délicatement pendant quatre minutes exactement. Les plonger aussitôt dans un bain d''eau froide et les écaler dès qu''ils ont tiédi : le blanc doit être juste pris et le jaune encore coulant."}]}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
