  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Éplucher la patate douce et les carottes, les couper en morceaux de deux centimètres, et la courgette en demi-rondelles épaisses en gardant sa peau. Les tailles diffèrent volontairement : la courgette cuit deux fois plus vite que la racine, et des morceaux plus gros compensent en partie cet écart.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Chauffer l''huile dans une cocotte à feu moyen et y faire fondre l''oignon émincé cinq minutes, sans le colorer. Ajouter l''ail haché et le curry en poudre et remuer TRENTE SECONDES dans l''huile chaude avant tout liquide : c''est le geste qui décide du parfum, les arômes du curry étant solubles dans le gras et non dans l''eau. Une poudre jetée dans la sauce reste poudreuse et rêche.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Ajouter les carottes et la patate douce, remuer pour les enrober du mélange épicé, puis verser le lait de coco. Saler et porter à frémissement. Le liquide ne couvre pas les légumes et c''est normal : ils vont rendre de l''eau et le niveau montera.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Couvrir et laisser mijoter vingt minutes à feu doux, en remuant deux ou trois fois pour que le fond n''attache pas — le lait de coco brûle vite. Les racines doivent alors être presque tendres, une lame entrant avec une légère résistance.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter la courgette et poursuivre quinze minutes à découvert. Le découvert de cette seconde phase fait deux choses : il laisse la courgette cuire sans se déliter et il réduit la sauce, qui doit napper et non baigner.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Goûter et rectifier le sel plus généreusement qu''on ne le ferait d''habitude : la recette est écrite au curry en poudre là où les sources emploient une pâte, qui est salée. Poivrer et laisser reposer cinq minutes hors du feu avant de servir — la sauce épaissit encore en tiédissant.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'RAP-032', 'recipe_family', 'Curry de légumes',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'RAP-032', 'missing_required_count', v_missing), 'open');
  END IF;

