  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Trancher les aubergines en rondelles d''un centimètre, les saler généreusement et les laisser dégorger trente minutes dans une passoire, puis les éponger. L''eau salée qui s''écoule emporte une partie de l''amertume et surtout ferme les cellules : une aubergine dégorgée boit deux fois moins d''huile qu''une aubergine crue, et c''est ce qui décide si le plat sera gras ou non.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Ranger les rondelles d''aubergine et de courgette sur des plaques, les badigeonner d''huile d''olive au pinceau et les rôtir vingt minutes à 200 °C en les retournant à mi-cuisson. Au four plutôt qu''à la poêle : la poêle exige trois fois plus d''huile pour le même résultat, et une moussaka végétarienne dont les légumes ont bu un demi-litre d''huile est immangeable.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pendant ce temps, faire fondre l''oignon émincé et le poivron en dés dans le reste d''huile, quinze minutes, ajouter l''ail et l''origan, puis les tomates concassées. Laisser réduire vingt minutes jusqu''à une sauce très épaisse. Sans viande pour absorber l''eau, la sauce doit être réduite bien plus qu''une sauce à la bolognaise, sinon le gratin rendra du jus et la béchamel flottera dessus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Monter la béchamel : roux au beurre et à la farine, lait froid versé d''un coup en fouettant, cuisson jusqu''à ce qu''elle nappe la cuillère, puis muscade, sel et poivre. La faire épaisse — elle doit tenir en couche sur les légumes et non couler entre eux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Monter le plat en couches : la moitié des aubergines, toute la sauce aux légumes, les courgettes, le reste des aubergines, en salant légèrement entre chaque couche. Terminer par la béchamel étalée à la spatule et l''emmental râpé sur toute la surface.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Enfourner à 180 °C pour quarante minutes, jusqu''à ce que le dessus soit brun doré et que les bords bouillonnent. Laisser reposer vingt minutes avant de servir : une moussaka coupée à la sortie du four s''affaisse, celle qui a reposé se tient à la spatule. C''est vrai des moussakas à la viande, ce l''est deux fois plus d''une moussaka de légumes, qui n''a rien d''autre pour se tenir.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-015', 'recipe_family', 'Moussaka végétarienne',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-015', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['À la feta : 800 g émiettés entre les couches et 500 g de yaourt grec dans la béchamel, mozzarella pour gratiner (marmiton)','Mozzarella et parmesan à la place de l''emmental, 125 g et 100 g pour quatre (marmiton)','Aux haricots rouges : 200 g égouttés dans la sauce, avec persil et menthe fraîche, chapelure sur le dessus (750g)','Montée entre des feuilles de lasagne, avec olives vertes, câpres et piment d''Espelette (marmiton)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-015","variants":["À la feta : 800 g émiettés entre les couches et 500 g de yaourt grec dans la béchamel, mozzarella pour gratiner (marmiton)","Mozzarella et parmesan à la place de l''emmental, 125 g et 100 g pour quatre (marmiton)","Aux haricots rouges : 200 g égouttés dans la sauce, avec persil et menthe fraîche, chapelure sur le dessus (750g)","Montée entre des feuilles de lasagne, avec olives vertes, câpres et piment d''Espelette (marmiton)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-015', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('4895222327e13392879f5576177f0e8b'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":3,"salty":3,"acidic":2,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["aubergine rôtie","béchamel","tomate mijotée","fromage gratiné"],"aroma_families":["végétal grillé","lacté","tomate_cuite","origan"],"target_textures":["légumes fondants","croûte gratinée","sauce_épaisse"],"signature_ingredients":["Aubergine fraîche","Emmental râpé","Lait entier"],"identity_guardrails":["Les aubergines se dégorgent et se rôtissent au four : à la poêle elles boivent trois fois plus d''huile","La sauce aux légumes doit être franchement réduite — sans viande, rien n''absorbe l''eau et le gratin rend du jus","La béchamel se fait épaisse : c''est la seule chose qui tienne les couches d''un plat sans viande","Vingt minutes de repos avant de servir, sinon la part s''affaisse dans l''assiette"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Couscous végétarien', 'couscous vegetarien', 'Maroc', 'Maroc',
     'meal', 'plat complet', 'named_traditional_dish', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Couscous végétarien', 'Semoule servie avec des courgettes, navets et oignons mijotés au bouillon, sans viande', ds.id, 'VAR-025',
    'Myko', 'editorial', 6, 25, 40, 'facile',
    NULL, NULL,
    'B', 'candidate', 'b1fb09c0995c471598e9a004a9976c0b',
    '{"sweet":3,"salty":3,"acidic":2,"bitter":0,"umami":2,"heat":0,"pungency":2,"richness":3,"freshness":2,"intensity":3}'::jsonb, ARRAY['curcuma','légumes du bouillon','oignon fondu','beurre']::text[],
    ARRAY['épices chaudes','végétal cuit','oignon_compoté','beurre']::text[], ARRAY['semoule égrenée','légumes fondants','bouillon_clair']::text[],
    ARRAY['Semoule de blé dur moyenne sèche','Pois chiche cuit, égoutté','Navet cru']::text[], ARRAY['La semoule gonfle dans le bouillon et non dans l''eau : c''est sa seule occasion d''être parfumée','Les pois chiches sont ici la protéine du plat, pas une garniture — 250 g pour six, ajoutés en fin de cuisson','Racines d''abord, courgettes ensuite : ensemble, l''un est cru quand l''autre est en bouillie','Le bouillon se sert à part : versé sur la semoule en cuisine, il la noie et interdit tout reste']::text[],
    ARRAY['suer','réduction','cuisson séquencée','gonflage de la semoule','égrenage']::text[], ARRAY['Aux raisins secs, de 50 à 250 g gonflés dans le bouillon, avec un bâton de cannelle (chefsimon, 750g)','Aux haricots verts et petits pois : 500 g et 300 g ajoutés avec les courgettes, plus un fenouil et deux pommes de terre (marmiton)','Au ras el-hanout ou aux épices à couscous, deux pincées à une cuillerée à soupe, formes absentes ou bloquées au catalogue (chefsimon, 750g)','Aux champignons : deux boîtes émincées ajoutées au bouillon (chefsimon)','Version sautée : champignons, carottes et céleri au gingembre râpé et à la sauce soja, servis sur semoule sans bouillon (marmiton)','Au gingembre moulu, une demi-cuillerée à café avec le curcuma (750g)']::text[], ARRAY['gluten','lait']::text[],
    'Les légumes et leur bouillon se gardent 4 jours au réfrigérateur et se congèlent 3 mois, sans les courgettes qui s''affaissent. La semoule se garde 3 jours à part, en boîte fermée, et se réchauffe à la vapeur ou au micro-ondes avec une cuillerée d''eau — jamais mélangée au bouillon, sous peine de bouillie. C''est un plat qui gagne à être fait en double : le bouillon de légumes ressert en soupe, et la semoule froide devient une salade avec des herbes et du citron.', '{"fridge_hours":72,"eat_immediately":false,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'MAG-001'), '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'courgette fraiche' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Courgette fraîche', 450, 'g', 'required',
     'légume', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'tomate fraiche mure' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Tomate fraîche mûre', 480, 'g', 'required',
     'légume', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
