  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Émincer les oignons et les faire fondre quinze minutes dans l''huile d''olive au fond d''une grande marmite, avec l''ail haché et le curcuma. Quatre cents grammes d''oignon pour six ne sont pas un aromate d''appoint : sans viande, c''est cette masse fondue qui donnera du corps au bouillon, et il faut la laisser aller jusqu''au blond.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Ajouter les tomates concassées et laisser réduire dix minutes, puis verser le bouillon de légumes, saler et poivrer, et porter à frémissement. Le bouillon doit être franchement assaisonné dès maintenant : la semoule qu''il arrosera est fade par nature et n''a rien pour se rattraper ensuite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Ajouter les carottes et les navets en gros morceaux et cuire vingt-cinq minutes à couvert, puis les courgettes en tronçons et le poivron en lanières et cuire quinze minutes de plus. Les racines et les cucurbitacées n''ont pas le même temps : mises ensemble, on obtient soit des navets crus, soit des courgettes en bouillie.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ajouter les pois chiches égouttés dans les dix dernières minutes, le temps qu''ils se réchauffent et prennent le goût du bouillon. Cuits depuis le début, ils se défont et troublent le liquide.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Pendant ce temps, verser la semoule dans un grand plat creux, l''arroser d''un volume égal de bouillon prélevé à la louche, couvrir et laisser gonfler dix minutes. Le bouillon plutôt que l''eau, c''est ce qui distingue une semoule de couscous d''une semoule nature — et c''est la seule occasion de la parfumer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Égrener la semoule à la main ou à la fourchette en y incorporant le beurre en parcelles, jusqu''à ce qu''elle soit lisse et sans grumeaux. Ce travail se fait pendant qu''elle est chaude : refroidie, elle se prend en blocs que rien ne défait. Le beurre enrobe chaque grain et les empêche de se ressouder.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Dresser la semoule en couronne, disposer les légumes égouttés au centre et servir le bouillon à part, en saucière. Le bouillon versé sur la semoule en cuisine la noie : chacun l''ajoute à son assiette, et c''est aussi ce qui permet de garder la semoule sèche pour le lendemain.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-025', 'recipe_family', 'Couscous végétarien',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-025', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Aux raisins secs, de 50 à 250 g gonflés dans le bouillon, avec un bâton de cannelle (chefsimon, 750g)','Aux haricots verts et petits pois : 500 g et 300 g ajoutés avec les courgettes, plus un fenouil et deux pommes de terre (marmiton)','Au ras el-hanout ou aux épices à couscous, deux pincées à une cuillerée à soupe, formes absentes ou bloquées au catalogue (chefsimon, 750g)','Aux champignons : deux boîtes émincées ajoutées au bouillon (chefsimon)','Version sautée : champignons, carottes et céleri au gingembre râpé et à la sauce soja, servis sur semoule sans bouillon (marmiton)','Au gingembre moulu, une demi-cuillerée à café avec le curcuma (750g)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-025","variants":["Aux raisins secs, de 50 à 250 g gonflés dans le bouillon, avec un bâton de cannelle (chefsimon, 750g)","Aux haricots verts et petits pois : 500 g et 300 g ajoutés avec les courgettes, plus un fenouil et deux pommes de terre (marmiton)","Au ras el-hanout ou aux épices à couscous, deux pincées à une cuillerée à soupe, formes absentes ou bloquées au catalogue (chefsimon, 750g)","Aux champignons : deux boîtes émincées ajoutées au bouillon (chefsimon)","Version sautée : champignons, carottes et céleri au gingembre râpé et à la sauce soja, servis sur semoule sans bouillon (marmiton)","Au gingembre moulu, une demi-cuillerée à café avec le curcuma (750g)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-025', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('b1fb09c0995c471598e9a004a9976c0b'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":3,"salty":3,"acidic":2,"bitter":0,"umami":2,"heat":0,"pungency":2,"richness":3,"freshness":2,"intensity":3},"dominant_flavors":["curcuma","légumes du bouillon","oignon fondu","beurre"],"aroma_families":["épices chaudes","végétal cuit","oignon_compoté","beurre"],"target_textures":["semoule égrenée","légumes fondants","bouillon_clair"],"signature_ingredients":["Semoule de blé dur moyenne sèche","Pois chiche cuit, égoutté","Navet cru"],"identity_guardrails":["La semoule gonfle dans le bouillon et non dans l''eau : c''est sa seule occasion d''être parfumée","Les pois chiches sont ici la protéine du plat, pas une garniture — 250 g pour six, ajoutés en fin de cuisson","Racines d''abord, courgettes ensuite : ensemble, l''un est cru quand l''autre est en bouillie","Le bouillon se sert à part : versé sur la semoule en cuisine, il la noie et interdit tout reste"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Chili sin carne', 'chili sin carne', 'Tex-Mex, adapté en cuisine domestique française', 'Tex-Mex, adapté en cuisine domestique française',
     'meal', 'légumineuses', 'named_traditional_dish', 'spicy_umami',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Chili sin carne', 'Haricots rouges mijotés à la tomate avec poivrons et carottes, sans viande', ds.id, 'VAR-042',
    'Myko', 'editorial', 6, 20, 50, 'facile',
    NULL, NULL,
    'B', 'candidate', '3915aa67cbae7b6804f6d70c36b0c8d0',
    '{"sweet":2,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":3,"pungency":4,"richness":2,"freshness":2,"intensity":4}'::jsonb, ARRAY['cumin','paprika fumé','tomate mijotée','haricot rouge']::text[],
    ARRAY['cumin','fumé','tomate_cuite','piment']::text[], ARRAY['sauce_épaisse','haricots fondants mais entiers','légumes fondants']::text[],
    ARRAY['Haricot rouge cuit, égoutté','Cumin moulu','Paprika fumé']::text[], ARRAY['Les épices s''ouvrent dans l''huile avant la tomate, sinon le plat garde un goût poudreux','On écrase une louche de haricots pour lier : c''est ce qui remplace la viande et évite toute farine','Le sel n''entre qu''après la cuisson des haricots, qu''il durcirait','Ni soja texturé ni haché végétal ici : trois pages sur six s''en passent entièrement, et le plat tient sur la légumineuse']::text[],
    ARRAY['suer','épices ouvertes dans le gras','mijotage','liaison par écrasement','repos']::text[], ARRAY['Aux protéines de soja texturées, 60 à 150 g réhydratées, ou à un haché végétal — formes absentes du catalogue (marmiton, chefsimon, 750g)','Au maïs doux, 140 g égouttés ajoutés avec les haricots (chefsimon, 750g)','Aux haricots noirs, 180 g crus en plus des rouges, avec du céleri et des champignons (chefsimon)','Servi avec un avocat en dés, un quart de citron jaune et une demi-échalote crue (chefsimon)','Relevé au tabasco, une demi à une cuillerée à café, ou au piment d''Espelette (marmiton, chefsimon, 750g)','Aux lentilles vertes : 350 g cuites avec les haricots (750g)']::text[], ARRAY[]::text[],
    'Se garde 5 jours au réfrigérateur et gagne beaucoup au deuxième jour, les épices ayant fini de se répartir. Se congèle 3 mois sans rien perdre : c''est l''un des meilleurs candidats du corpus au travail d''avance, et doubler les quantités ne coûte presque rien. Réchauffer à couvert et à feu doux avec deux cuillerées d''eau. Les restes servent aussi de garniture — sur une pomme de terre au four, dans une tortilla, sous un œuf au plat.', '{"fridge_hours":120,"eat_immediately":false,"freezable":true,"freezer_months":3,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'MX-001'), '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'tomate concassee en conserve' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Tomate concassée en conserve', 800, 'g', 'required',
     'sauce', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'bouillon de legumes' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Bouillon de légumes', 500, 'ml', 'required',
