  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Trancher les aubergines et les courgettes en rondelles d''un demi-centimètre, les ranger sur des plaques, les badigeonner d''huile d''olive et les rôtir vingt minutes à 200 °C en les retournant à mi-cuisson. Un kilo de légumes d''été contient près de neuf cents grammes d''eau : rôtis, ils en perdent le tiers et concentrent leur goût ; crus dans le plat, ils la rendent tous entre les feuilles de pâte.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Pendant ce temps, faire fondre l''oignon émincé dans le reste d''huile avec l''ail et les herbes de Provence, puis verser les tomates concassées et laisser réduire vingt minutes jusqu''à une sauce épaisse qui ne coule plus de la cuillère. Sans viande pour absorber l''eau, cette sauce doit être nettement plus réduite qu''un ragù.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Monter la béchamel : faire un roux blond avec le beurre et la farine, verser le lait froid d''un coup en fouettant, et cuire jusqu''à ce qu''elle nappe. La faire un peu plus fluide qu''une béchamel de gratin — elle doit pouvoir s''insinuer entre les feuilles, qui vont s''en servir pour cuire.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Monter le plat en quatre couches : une louche de béchamel au fond, des feuilles de lasagne, la sauce tomate, les légumes rôtis, la mozzarella en dés, un peu de béchamel, et recommencer en terminant par béchamel et parmesan. Les feuilles sèches ne doivent jamais toucher le fond nu du plat ni rester à l''air en surface : partout où elles ne sont pas mouillées, elles restent dures.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Presser légèrement la surface à la spatule pour chasser les poches d''air et vérifier que la dernière couche de pâte est entièrement couverte. Une lasagne montée trop lâche s''affaisse à la cuisson et laisse des zones sèches.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Enfourner à 180 °C pour trente-cinq minutes, jusqu''à ce que le dessus soit doré et que la pointe d''un couteau traverse toutes les couches sans résistance. Parsemer le basilic déchiré au sortir du four et non avant : cuit trente-cinq minutes, il noircit et ne sert plus à rien.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Laisser reposer un quart d''heure avant de découper. Une lasagne coupée brûlante coule dans l''assiette ; celle qui a reposé se tient en parts nettes, et c''est encore plus vrai d''une lasagne de légumes, qui n''a pas de viande pour la structurer.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-043', 'recipe_family', 'Lasagnes végétariennes',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-043', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Au gruyère râpé, jusqu''à 400 g pour quatre, à la place du parmesan (marmiton)','Au chèvre : 100 g de fromage de chèvre frais entre les couches, ou une crème de chèvre au pesto (marmiton, deux pages)','À la ricotta et aux épinards : 300 g de ricotta, 450 g d''épinards frais et deux œufs (750g)','Aux carottes râpées, une à deux, ajoutées à la sauce tomate (750g)','Au provolone, 100 g en plus de la mozzarella, avec de l''origan frais et des tomates cerises rôties (chefsimon)','Sans béchamel : quatre cuillerées de crème liquide réparties entre les couches (chefsimon)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-043","variants":["Au gruyère râpé, jusqu''à 400 g pour quatre, à la place du parmesan (marmiton)","Au chèvre : 100 g de fromage de chèvre frais entre les couches, ou une crème de chèvre au pesto (marmiton, deux pages)","À la ricotta et aux épinards : 300 g de ricotta, 450 g d''épinards frais et deux œufs (750g)","Aux carottes râpées, une à deux, ajoutées à la sauce tomate (750g)","Au provolone, 100 g en plus de la mozzarella, avec de l''origan frais et des tomates cerises rôties (chefsimon)","Sans béchamel : quatre cuillerées de crème liquide réparties entre les couches (chefsimon)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-043', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('02ad78a013909da281eeff81836c92cf'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":3,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["aubergine rôtie","tomate mijotée","mozzarella fondue","basilic"],"aroma_families":["tomate_cuite","végétal grillé","lacté","basilic"],"target_textures":["croûte gratinée","pâtes_fermes","légumes fondants"],"signature_ingredients":["Feuille de lasagne sèche","Aubergine fraîche","Mozzarella"],"identity_guardrails":["Les légumes se rôtissent avant : crus entre les feuilles, ils rendent près d''un litre d''eau","La sauce tomate doit être franchement réduite — sans viande, rien n''absorbe l''excès","Aucune feuille ne doit rester sèche : partout où elle n''est pas mouillée, elle reste dure","Quinze minutes de repos avant la découpe, faute de quoi la part coule dans l''assiette"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Hachis parmentier végétarien', 'hachis parmentier vegetarien', 'France', 'France',
     'meal', 'hachis parmentier de légumes', 'domestic_standard', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Hachis parmentier végétarien', 'Légumes hachés recouverts d''une purée de pommes de terre, gratinés au four', ds.id, 'VAR-045',
    'Myko', 'editorial', 6, 30, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', 'ed7c8304734951a6242ea7ce6d01eb5f',
    '{"sweet":3,"salty":3,"acidic":1,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":2}'::jsonb, ARRAY['purée au beurre','champignon','légumes racines','thym']::text[],
    ARRAY['beurre','champignon_terreux','végétal cuit','thym']::text[], ARRAY['croûte gratinée','purée lisse','légumes fondants']::text[],
    ARRAY['Pomme de terre crue, épluchée','Champignon de Paris frais','Carotte crue']::text[], ARRAY['Les légumes se taillent en dés de cinq millimètres : c''est ce qui fait un hachis et non un ragoût sous purée','Ils se colorent à feu vif — sans viande, la coloration est la seule source de goût brun du plat','La garniture doit être sèche avant d''être couverte, sinon la purée remonte et ne gratine pas','Purée au presse-purée et jamais au robot, qui la rend élastique']::text[],
    ARRAY['cuisson départ eau froide','taille en dés','sauté à feu vif','déglaçage','purée au presse-purée','gratinage']::text[], ARRAY['Aux haricots rouges : 800 g égouttés dans la garniture, avec 125 g de mozzarella et du concentré de tomate (marmiton)','Aux lentilles et à la patate douce : 200 g de lentilles, 400 g de tomates concassées et une purée de quatre patates douces (chefsimon)','Au boulgour : 85 g avec un kilo de carottes et 250 g de macédoine surgelée, sous un bouquet garni (marmiton)','Purée liée d''un jaune d''œuf avant gratinage (chefsimon)','Une cuillerée à café de sauce soja dans la garniture, avec deux branches de céleri et une tranche de pain de mie émiettée (marmiton)']::text[], ARRAY['lait']::text[],
    'Se garde 4 jours au réfrigérateur et se réchauffe 20 minutes à 180 °C, couvert d''aluminium les dix premières minutes. Se congèle 3 mois, cru et monté ou déjà cuit : cru, il s''enfourne sans décongélation en ajoutant trente minutes. La garniture de légumes se prépare seule 3 jours à l''avance et se congèle 3 mois ; elle sert aussi de fond de tourte ou de garniture de crêpes salées, ce qui en fait une base à doubler.', '{"fridge_hours":96,"eat_immediately":false,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'FR-004'), '{}'::jsonb, NULL
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'pomme de terre crue epluchee' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Pomme de terre crue, épluchée', 1200, 'g', 'required',
     'féculent', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
