  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Éplucher les pommes de terre, les couper en morceaux réguliers et les cuire départ eau froide salée, vingt-cinq minutes, jusqu''à ce qu''elles s''écrasent sans résistance. Départ eau froide et non eau bouillante : jetées dans l''eau chaude, elles cuisent en surface avant le cœur et la purée reste grumeleuse quoi qu''on fasse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Tailler la carotte, le navet, l''oignon, le poireau et les champignons en dés de cinq millimètres. C''est ce qui remplace le hachis de viande : le plat s''appelle hachis, et sans cette découpe menue la couche du dessous reste un ragoût de légumes sous une purée, ce qui n''est pas la même chose en bouche.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Faire revenir les légumes dans l''huile d''olive à feu vif, sept à huit minutes, en les laissant colorer sans les remuer en permanence, puis ajouter le thym. La coloration est la seule source de goût brun d''un plat sans viande : à feu doux, les légumes suent et le hachis reste pâle et fade.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Déglacer au vin blanc, gratter le fond, et laisser réduire à découvert une quinzaine de minutes jusqu''à ce qu''il ne reste plus de liquide libre. Une garniture humide fait remonter la purée et l''empêche de gratiner : le dessous doit être moelleux mais non mouillé.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Écraser les pommes de terre au presse-purée — jamais au robot, qui rend l''amidon élastique et donne une colle — puis incorporer le beurre en parcelles et la crème chaude, saler, poivrer. La crème froide sur une purée chaude la fait figer par plaques ; chaude, elle s''incorpore d''un coup.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Étaler la garniture dans un plat, parsemer le persil ciselé, couvrir de la purée en lissant à la fourchette pour former des sillons, et parsemer d''emmental râpé. Les sillons ne sont pas décoratifs : ils multiplient la surface exposée et c''est là que se forme la croûte.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Enfourner à 200 °C pour vingt-cinq à trente minutes, jusqu''à ce que le dessus soit doré et que les bords bouillonnent. Laisser reposer dix minutes avant de servir, le temps que la garniture se raffermisse et que la part se tienne à la cuillère.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'VAR-045', 'recipe_family', 'Hachis parmentier végétarien',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'VAR-045', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Aux haricots rouges : 800 g égouttés dans la garniture, avec 125 g de mozzarella et du concentré de tomate (marmiton)','Aux lentilles et à la patate douce : 200 g de lentilles, 400 g de tomates concassées et une purée de quatre patates douces (chefsimon)','Au boulgour : 85 g avec un kilo de carottes et 250 g de macédoine surgelée, sous un bouquet garni (marmiton)','Purée liée d''un jaune d''œuf avant gratinage (chefsimon)','Une cuillerée à café de sauce soja dans la garniture, avec deux branches de céleri et une tranche de pain de mie émiettée (marmiton)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"VAR-045","variants":["Aux haricots rouges : 800 g égouttés dans la garniture, avec 125 g de mozzarella et du concentré de tomate (marmiton)","Aux lentilles et à la patate douce : 200 g de lentilles, 400 g de tomates concassées et une purée de quatre patates douces (chefsimon)","Au boulgour : 85 g avec un kilo de carottes et 250 g de macédoine surgelée, sous un bouquet garni (marmiton)","Purée liée d''un jaune d''œuf avant gratinage (chefsimon)","Une cuillerée à café de sauce soja dans la garniture, avec deux branches de céleri et une tranche de pain de mie émiettée (marmiton)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:VAR-045', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('ed7c8304734951a6242ea7ce6d01eb5f'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":3,"salty":3,"acidic":1,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":2},"dominant_flavors":["purée au beurre","champignon","légumes racines","thym"],"aroma_families":["beurre","champignon_terreux","végétal cuit","thym"],"target_textures":["croûte gratinée","purée lisse","légumes fondants"],"signature_ingredients":["Pomme de terre crue, épluchée","Champignon de Paris frais","Carotte crue"],"identity_guardrails":["Les légumes se taillent en dés de cinq millimètres : c''est ce qui fait un hachis et non un ragoût sous purée","Ils se colorent à feu vif — sans viande, la coloration est la seule source de goût brun du plat","La garniture doit être sèche avant d''être couverte, sinon la purée remonte et ne gratine pas","Purée au presse-purée et jamais au robot, qui la rend élastique"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Spaghetti à la bolognaise de lentilles', 'spaghetti a la bolognaise de lentilles', 'France / cuisine domestique internationale', 'France / cuisine domestique internationale',
     'meal', 'pâtes en sauce', 'domestic_standard', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Spaghetti à la bolognaise de lentilles', 'Spaghettis enrobés d''une sauce tomate au soffritto où des lentilles vertes tiennent la place du bœuf haché — le jumeau végétarien de la bolognaise', ds.id, 'JUM-001',
    'Myko', 'editorial', 6, 20, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', '783ca730352980d94dd06ad0703051a8',
    '{"sweet":2,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":2,"freshness":1,"intensity":3}'::jsonb, ARRAY['tomate cuite','lentille','légume compoté']::text[],
    ARRAY['tomate_cuite','oignon_compoté','lentille','thym']::text[], ARRAY['sauce_nappante','pâtes_fermes','lentilles fondantes mais entières']::text[],
    ARRAY['Spaghetti secs','Lentille verte sèche, crue','Tomate concassée en conserve','Carotte crue','Céleri branche cru']::text[], ARRAY['Le soffritto oignon-carotte-céleri fondu au départ est ce qui reste de la bolognaise quand la viande s''en va : sans lui c''est une sauce tomate aux lentilles','Les lentilles cuisent à part, à l''eau non salée, et n''entrent qu''une fois la tomate réduite : versées crues dans l''acide elles restent dures','Une louche de lentilles écrasée lie la sauce : c''est ce qui remplace le gras et le collagène du haché, et pourquoi le plat ne prend ni farine ni crème','Les pâtes finissent dans la sauce avec un peu de leur eau, comme dans le parent ; servies nues sous la sauce, le plat se dissocie']::text[],
    ARRAY['cuissons séparées','soffritto','cuisson du concentré','mijotage','liaison par écrasement','cuisson al dente','enrobage à l''eau de cuisson']::text[], ARRAY['Aux lentilles corail, 30 g par personne cuites directement dans la tomate un quart d''heure, pour une sauce plus fondue (marmiton, chefsimon)','Aux champignons de Paris émincés et revenus avec l''oignon, 120 à 300 g pour quatre (chefsimon)','Déglacée au vin rouge, 7 cl pour quatre, avant la tomate (750g), ou mouillée d''un verre de vin blanc avec les tomates (marmiton)','Au poireau émincé avec l''oignon, à la place du céleri, et aux herbes de Provence (marmiton)','Aux tomates séchées, noix de Grenoble concassées et paprika (chefsimon)','Une cuillerée à café de miel dans la sauce pour arrondir l''acidité (marmiton)','Servie avec du parmesan râpé — ou, pour un végétarien strict, un fromage à pâte dure sans présure animale (chefsimon, 750g)']::text[], ARRAY['gluten','céleri','lait']::text[],
    'La sauce se garde quatre jours au réfrigérateur dans un récipient fermé et gagne à être faite la veille : les lentilles finissent d''absorber la tomate et la sauce s''arrondit. Elle se congèle trois mois, sans les pâtes — les lentilles supportent la congélation sans s''écraser davantage. Réchauffer à feu doux avec deux cuillerées d''eau, la sauce ayant épaissi au froid. Les pâtes déjà enrobées ne se gardent pas plus de vingt-quatre heures et ne se congèlent pas : elles rendent leur eau et deviennent farineuses. C''est ce que dit le parent, et c''est ce que fait physiquement une sauce de légumineuse.', '{"fridge_hours":24,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'IT-004'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

