  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Couper le tofu ferme en cubes de trois centimètres et les poser entre deux linges sous une planche lestée pendant un quart d''heure. Le tofu est gorgé d''eau : pressé, il devient plus dense, tient à la cuisson et se laisse imprégner par la sauce au lieu de la diluer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Éplucher les carottes et les couper en tronçons épais, fendre le poireau, le laver et le tronçonner, émincer l''oignon, brosser les champignons et les partager en quartiers. Des morceaux gros, parce qu''ils cuisent longtemps dans un liquide et doivent arriver entiers dans l''assiette.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Réunir carottes, poireau et oignon dans une cocotte, verser le bouillon de légumes froid, ajouter le thym et le laurier, porter à frémissement et cuire vingt minutes à couvert. Une blanquette ne colore rien : les légumes cuisent dans le bouillon dès le départ, et c''est ce bouillon, enrichi par eux, qui fera la sauce.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ajouter les cubes de tofu et les champignons, poursuivre dix minutes à petit frémissement, puis passer le contenu de la cocotte au tamis en gardant le bouillon d''un côté et la garniture de l''autre. Le tofu n''a rien à raidir comme une viande : il prend le goût du bouillon en y pochant, et dix minutes y suffisent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Dans la cocotte essuyée, fondre le beurre, ajouter la farine d''un coup et cuire ce roux deux minutes à feu doux en fouettant, sans le laisser blondir. Verser le bouillon chaud par louches en fouettant à chaque fois, puis laisser épaissir dix minutes à feu doux : la sauce doit napper la cuillère sans coller. Le roux cuit d''abord à sec pour perdre son goût de farine crue ; mouillé trop vite, il fait des grumeaux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Hors du feu, incorporer la crème, saler, poivrer, puis remettre la garniture et le tofu dans la sauce et réchauffer deux ou trois minutes sans jamais atteindre l''ébullition. Une crème qui bout dans une sauce déjà liée tranche et perd son velouté ; le tofu, lui, n''a besoin que d''être réchauffé.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Parsemer de persil ciselé et servir avec du riz ou des pommes de terre vapeur, comme le parent : la sauce en demande.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
