  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Liée au jaune d''œuf battu dans la crème, avec le jus d''un demi-citron, hors du feu (recette-painperdu)','Aux pommes de terre en gros cubes cuites dans le bouillon avec les carottes, ce qui en fait un plat complet (750g, supertoinette)','Tofu mariné dix minutes à la moutarde puis saisi à l''huile avant d''entrer dans la sauce, et crème de soja à la place de la crème (supertoinette)','Au céleri branche avec les poireaux, liée à la fécule de maïs, avec deux clous de girofle (ptitchef)','Aux pruneaux trempés, ajoutés au mijotage, et nappée d''une cuillerée de crème de soja (750g)','Finie à la ciboulette plutôt qu''au persil (supertoinette)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-002","variants":["Liée au jaune d''œuf battu dans la crème, avec le jus d''un demi-citron, hors du feu (recette-painperdu)","Aux pommes de terre en gros cubes cuites dans le bouillon avec les carottes, ce qui en fait un plat complet (750g, supertoinette)","Tofu mariné dix minutes à la moutarde puis saisi à l''huile avant d''entrer dans la sauce, et crème de soja à la place de la crème (supertoinette)","Au céleri branche avec les poireaux, liée à la fécule de maïs, avec deux clous de girofle (ptitchef)","Aux pruneaux trempés, ajoutés au mijotage, et nappée d''une cuillerée de crème de soja (750g)","Finie à la ciboulette plutôt qu''au persil (supertoinette)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-002', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('43b48d5000251076ce4e931e6fb0fca7'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":2,"salty":3,"acidic":1,"bitter":0,"umami":2,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":2},"dominant_flavors":["crème","champignon","légumes racines fondus"],"aroma_families":["lacté","champignon_terreux","thym","poireau"],"target_textures":["sauce nappante","tofu","légumes tendres"],"signature_ingredients":["Tofu ferme","Crème fraîche liquide entière","Champignon de Paris frais"],"identity_guardrails":["Rien ne colore : légumes et tofu cuisent dans le bouillon, et la sauce reste ivoire — une saisie brune donnerait un sauté en sauce, plus une blanquette","Le tofu se presse avant d''entrer dans le bouillon, sinon il rend son eau dans la sauce et la détend","La liaison est un roux mouillé au bouillon de cuisson et monté à la crème hors du feu : sans elle, il reste un bouillon de légumes au tofu","Bouillon de légumes, jamais de volaille : c''est ce qui fait de ce plat le jumeau végétarien de la blanquette de dinde"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Paneer tikka et dal palak', 'paneer tikka et dal palak', 'Inde du Nord', 'Inde du Nord',
     'meal', 'plat complet', 'named_traditional_dish', 'spicy_umami',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Paneer tikka et dal palak', 'Cubes de paneer marinés au yaourt et aux épices, grillés en brochettes avec poivron et oignon rouge, servis sur le dal d''épinards aux lentilles corail du parent', ds.id, 'JUM-003',
    'Myko', 'editorial', 4, 25, 40, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '76805c4039cabb688afe0656c855d68f',
    '{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":2,"pungency":4,"richness":3,"freshness":3,"intensity":4}'::jsonb, ARRAY['épices grillées','yaourt acidulé','paneer','lentille terreuse']::text[],
    ARRAY['cumin','coriandre','gingembre','ail','paprika','paneer','epinard']::text[], ARRAY['paneer_doré','bords_grillés','dal_crémeux','épinard_fondant','poivron tendre']::text[],
    ARRAY['Paneer','Yaourt à la grecque','Lentille corail sèche, crue']::text[], ARRAY['La marinade est au yaourt épais et aux épices, comme celle du poulet du parent : c''est elle qui fait le tikka, un paneer simplement poêlé n''en est pas un','Cuisson vive et courte sous le gril ou au barbecue, jusqu''aux bords noircis ; prolongée, elle durcit le paneer — il n''a pas de température à cœur à atteindre','Le dal palak est celui du parent, sans crème ; c''est lui qui fait l''assiette complète','Le paneer et le yaourt sont les seules origines animales du plat : lait, jamais viande ni volaille — c''est ce qui en fait le jumeau végétarien du murgh tandoori']::text[],
    ARRAY['marinade lactique','grillade','brochette','mijotage','tempérage des épices']::text[], ARRAY['Au garam masala, une cuillerée à café dans la marinade — forme bloquée au catalogue, proxy de confiance C (196flavors, air-fryer-ninja, cookwithmanali, vegrecipesofindia)','Au chaat masala saupoudré à la sortie du gril, et au kasuri methi, fenugrec séché écrasé, dans la marinade — formes absentes du catalogue (196flavors, cookwithmanali, vegrecipesofindia)','À l''huile de moutarde plutôt qu''à l''huile neutre — forme bloquée au catalogue (196flavors, cookwithmanali, vegrecipesofindia)','Coriandre et menthe ciselées dans la marinade, et chutney de coriandre-menthe au service (196flavors, cookwithmanali)','Paneer seul sur les brochettes, sans poivron ni oignon, au barbecue (grainedepices)','Cuisson en friteuse à air, 200 °C, sept minutes puis cinq à huit après retournement (air-fryer-ninja)','Marinade de six heures au réfrigérateur, puis passage au four à 230 °C suivi de deux minutes sur le grille-viande pour noircir les bords (196flavors)']::text[], ARRAY['lait']::text[],
    'Le dal se garde 3 jours au réfrigérateur et se congèle 2 mois, comme celui du parent. Le paneer tikka se garde 2 jours au réfrigérateur dans une boîte fermée — c''est ce que dit l''une des pages — et se réchauffe doucement à la poêle ou au four, jamais au micro-ondes à pleine puissance, qui le rend caoutchouteux. Il ne se congèle pas : le paneer congelé perd son moelleux et devient granuleux, et le yaourt de la marinade grène. C''est ce que fait un fromage frais pressé, et c''est ce qu''on choisit ici.', '{"fridge_hours":48,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'PROT-005'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

