  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Fouetter le yaourt jusqu''à ce qu''il soit lisse, puis y mélanger dix grammes d''ail et dix grammes de gingembre râpés, le paprika, le piment, trois grammes de coriandre moulue, la moitié du cumin, un tiers du curcuma, l''huile, la moitié du jus de citron et une cuillerée à café de sel. Couper le paneer en cubes de trois centimètres, tailler poivron et oignon rouge en carrés du même calibre, enrober le tout de marinade et laisser au frais une heure au moins, deux si possible. La marinade doit rester épaisse : un yaourt fluide glisse du paneer, qui n''absorbe pas comme une chair, et brûle sur la plaque au lieu d''y rester.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Rincer les lentilles corail, les couvrir de trois fois leur volume d''eau avec le reste du curcuma et les laisser frémir un quart d''heure à découvert, en écumant, jusqu''à ce qu''elles se défassent en purée souple. Sans sel à ce stade : il ralentirait leur cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Dans une cocotte bien chaude et à sec, blondir l''oignon jaune émincé en remuant, ajouter le reste d''ail et de gingembre, le reste de cumin et de coriandre moulue, remuer une minute pour ouvrir les épices, puis la tomate en dés et laisser compoter cinq minutes. C''est la base du dal palak du parent, inchangée : le paneer ne demande aucun aménagement au dal.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser les lentilles dans la cocotte, ajouter les épinards par poignées et les laisser tomber cinq minutes, saler. Le dal doit rester coulant — l''allonger d''un peu d''eau chaude s''il épaissit — parce que c''est lui qui tient le rôle du féculent et qui recevra les brochettes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Préchauffer le four en position gril, à 230 °C, un bon quart d''heure. Enfiler paneer, poivron et oignon en alternance sur des brochettes, les poser sur une plaque chemisée et les passer au pinceau huilé. Cuire dix minutes sous le gril, retourner, puis deux à cinq minutes de plus, jusqu''à ce que les arêtes du paneer noircissent par endroits. Ne pas prolonger : un paneer trop cuit durcit et devient caoutchouteux, là où le poulet du parent devait atteindre sa température à cœur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Poser les brochettes sur le dal, arroser du reste de jus de citron, parsemer de coriandre fraîche et servir aussitôt, le paneer perdant son moelleux en refroidissant.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-003', 'recipe_family', 'Paneer tikka et dal palak',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-003', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
