  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Au garam masala, une cuillerée à café dans la marinade — forme bloquée au catalogue, proxy de confiance C (196flavors, air-fryer-ninja, cookwithmanali, vegrecipesofindia)','Au chaat masala saupoudré à la sortie du gril, et au kasuri methi, fenugrec séché écrasé, dans la marinade — formes absentes du catalogue (196flavors, cookwithmanali, vegrecipesofindia)','À l''huile de moutarde plutôt qu''à l''huile neutre — forme bloquée au catalogue (196flavors, cookwithmanali, vegrecipesofindia)','Coriandre et menthe ciselées dans la marinade, et chutney de coriandre-menthe au service (196flavors, cookwithmanali)','Paneer seul sur les brochettes, sans poivron ni oignon, au barbecue (grainedepices)','Cuisson en friteuse à air, 200 °C, sept minutes puis cinq à huit après retournement (air-fryer-ninja)','Marinade de six heures au réfrigérateur, puis passage au four à 230 °C suivi de deux minutes sur le grille-viande pour noircir les bords (196flavors)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-003","variants":["Au garam masala, une cuillerée à café dans la marinade — forme bloquée au catalogue, proxy de confiance C (196flavors, air-fryer-ninja, cookwithmanali, vegrecipesofindia)","Au chaat masala saupoudré à la sortie du gril, et au kasuri methi, fenugrec séché écrasé, dans la marinade — formes absentes du catalogue (196flavors, cookwithmanali, vegrecipesofindia)","À l''huile de moutarde plutôt qu''à l''huile neutre — forme bloquée au catalogue (196flavors, cookwithmanali, vegrecipesofindia)","Coriandre et menthe ciselées dans la marinade, et chutney de coriandre-menthe au service (196flavors, cookwithmanali)","Paneer seul sur les brochettes, sans poivron ni oignon, au barbecue (grainedepices)","Cuisson en friteuse à air, 200 °C, sept minutes puis cinq à huit après retournement (air-fryer-ninja)","Marinade de six heures au réfrigérateur, puis passage au four à 230 °C suivi de deux minutes sur le grille-viande pour noircir les bords (196flavors)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-003', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('76805c4039cabb688afe0656c855d68f'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"spicy_umami","scores":{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":2,"pungency":4,"richness":3,"freshness":3,"intensity":4},"dominant_flavors":["épices grillées","yaourt acidulé","paneer","lentille terreuse"],"aroma_families":["cumin","coriandre","gingembre","ail","paprika","paneer","epinard"],"target_textures":["paneer_doré","bords_grillés","dal_crémeux","épinard_fondant","poivron tendre"],"signature_ingredients":["Paneer","Yaourt à la grecque","Lentille corail sèche, crue"],"identity_guardrails":["La marinade est au yaourt épais et aux épices, comme celle du poulet du parent : c''est elle qui fait le tikka, un paneer simplement poêlé n''en est pas un","Cuisson vive et courte sous le gril ou au barbecue, jusqu''aux bords noircis ; prolongée, elle durcit le paneer — il n''a pas de température à cœur à atteindre","Le dal palak est celui du parent, sans crème ; c''est lui qui fait l''assiette complète","Le paneer et le yaourt sont les seules origines animales du plat : lait, jamais viande ni volaille — c''est ce qui en fait le jumeau végétarien du murgh tandoori"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Chou farci végétarien', 'chou farci vegetarien', 'France', 'France',
     'meal', 'plat mijoté', 'domestic_standard', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Chou farci végétarien', 'Feuilles de chou vert blanchies, farcies de lentilles vertes, de riz et de champignons, braisées à couvert dans la tomate et le bouillon — le jumeau végétarien du chou farci', ds.id, 'JUM-004',
    'Myko', 'editorial', 6, 30, 60, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'a5f9daf1c201073e365527ce8bbeec20',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":2,"freshness":1,"intensity":3}'::jsonb, ARRAY['chou fondant','lentille','champignon','tomate cuite']::text[],
    ARRAY['végétal cuit','champignon_terreux','tomate_cuite','aromates verts']::text[], ARRAY['feuilles fondantes','farce moelleuse et serrée','jus court et nappant']::text[],
    ARRAY['Chou vert frais','Lentille verte sèche, crue','Champignon de Paris frais']::text[], ARRAY['Les feuilles de chou vert entières enveloppent la farce, en paquets fermés : émincé et mélangé aux lentilles, ce n''est plus un chou farci mais une potée','La farce tient sur les lentilles vertes et les champignons liés au riz et à l''œuf, sans haché végétal du commerce — les quatre pages s''en passent','Les champignons sont cuits à sec avant d''entrer dans la farce, sinon ils la détrempent et les paquets s''ouvrent','La cuisson est un braisage long à couvert dans un mouillement court de tomate et de bouillon, comme le parent, pas un rôtissage à sec']::text[],
    ARRAY['cuissons séparées','blanchiment','suer','farcissage','mijotage','repos']::text[], ARRAY['Au quinoa rouge et aux lentilles corail cuits ensemble dans un bouillon au concentré de tomate, relevés de piment d''Espelette, paquets cuits au four arrosés du jus de cuisson (lacerisesurlemaillot)','Farce aux champignons, aubergine frite, pignons, chapelure et ricotta, montée en moules chemisés de feuilles et cuite une heure au four (marmiton)','Rouleaux au millet, aux noix et à la sauce soja, gratinés à l''emmental vingt minutes au four (menu-vegetarien)','Champignons de Paris en conserve plutôt que frais (ffcuisine)','Cuisson au four à sec plutôt qu''en cocotte : vingt à soixante minutes selon la taille des paquets (marmiton, menu-vegetarien)']::text[], ARRAY['œuf']::text[],
    'Se garde 3 jours au réfrigérateur entre 0 et 4 °C, les paquets immergés dans leur jus dans un récipient fermé ; réchauffer à couvert et à feu doux, jamais à gros bouillons. Se congèle 3 mois en parts, mais les feuilles rendent de l''eau à la décongélation et perdent de leur tenue : congeler le jus à part et le réduire au réchauffage. C''est ce que dit le parent, et une farce de lentilles se comporte comme lui — mieux, même : sans gras animal, le jus ne fige pas et les lentilles ne se dessèchent pas au deuxième jour.', '{"fridge_hours":72,"eat_immediately":false,"freezable":true,"freezer_months":3,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-038'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

