  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-004', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('a5f9daf1c201073e365527ce8bbeec20'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":2,"freshness":1,"intensity":3},"dominant_flavors":["chou fondant","lentille","champignon","tomate cuite"],"aroma_families":["végétal cuit","champignon_terreux","tomate_cuite","aromates verts"],"target_textures":["feuilles fondantes","farce moelleuse et serrée","jus court et nappant"],"signature_ingredients":["Chou vert frais","Lentille verte sèche, crue","Champignon de Paris frais"],"identity_guardrails":["Les feuilles de chou vert entières enveloppent la farce, en paquets fermés : émincé et mélangé aux lentilles, ce n''est plus un chou farci mais une potée","La farce tient sur les lentilles vertes et les champignons liés au riz et à l''œuf, sans haché végétal du commerce — les quatre pages s''en passent","Les champignons sont cuits à sec avant d''entrer dans la farce, sinon ils la détrempent et les paquets s''ouvrent","La cuisson est un braisage long à couvert dans un mouillement court de tomate et de bouillon, comme le parent, pas un rôtissage à sec"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Mafé végétarien', 'mafe vegetarien', 'Mali/Sénégal', 'Mali/Sénégal',
     'meal', 'ragoût à l arachide', 'domestic_standard', 'nutty_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Mafé végétarien', 'Patate douce, carottes, chou et pois chiches mijotés dans la sauce d''arachide et de tomate concentrée du mafé, servis sur du riz — le jumeau végétarien du mafé de bœuf', ds.id, 'JUM-005',
    'Myko', 'editorial', 8, 25, 35, 'facile',
    NULL, NULL,
    'B', 'candidate', 'b5ca93062bb6cf974c3e2c9c358f788f',
    '{"sweet":3,"salty":3,"acidic":2,"bitter":1,"umami":3,"heat":2,"pungency":2,"richness":4,"freshness":1,"intensity":4}'::jsonb, ARRAY['arachide','patate douce','tomate concentrée','pois chiche']::text[],
    ARRAY['arachide','oignon_compoté','tomate_cuite','piment']::text[], ARRAY['sauce_onctueuse','légumes_entiers','pois chiches fondants']::text[],
    ARRAY['Pâte d’arachide pure','Patate douce crue, épluchée','Pois chiche cuit, égoutté','Tomate concentrée']::text[], ARRAY['La pâte d''arachide est pure et non sucrée, délayée dans le bouillon chaud et jamais versée telle quelle : un beurre de cacahuète sucré fait un autre plat','La sauce réduit jusqu''à napper et à laisser perler l''huile d''arachide, comme le parent — un mafé clair est une soupe','Les légumes entrent selon leur temps de cuisson, carotte et chou avant la patate douce, et restent entiers','Les pois chiches remplacent le bœuf et entrent en dernier, déjà cuits : versés au départ ils s''écraseraient et lieraient la sauce en purée']::text[],
    ARRAY['suer','friture de concentré','mijotage','légumes séquencés','réduction']::text[], ARRAY['Mafé de légumes sans légumineuse, la patate douce en tenant la place — la lecture de cinq pages sur six (bonduelle, lescommis, sabnpepper, marmiton, menu-vegetarien)','Avec de la chair de tomate en plus du concentré : 400 g de pulpe pour quatre, deux tomates fraîches ou une boîte (lescommis, sabnpepper, marmiton)','Au gingembre frais râpé avec l''ail, 20 g pour quatre (lescommis, recettesetcabas)','Avec des pommes de terre en plus de la patate douce, quatre pour six (bonduelle, sabnpepper)','À l''aubergine en gros morceaux avec les autres légumes, cuite en cocotte-minute (marmiton)','Aux feuilles de blettes ajoutées en fin de cuisson, relevé de cumin et de flocons de piment (menu-vegetarien)','Arrosé d''un filet de jus de citron vert au service, sur du riz avec des carottes seules (recettesetcabas)','Servi sur de la semoule plutôt que sur du riz, parsemé de persil (lescommis)','Une feuille de laurier dans le bouillon (bonduelle)']::text[], ARRAY['arachide']::text[],
    'Se garde 3 jours au réfrigérateur dans un récipient fermé, la durée du parent, et gagne au deuxième jour, la sauce d''arachide finissant d''imprégner les légumes. Aucune des six pages du dossier ne dit un mot de la conservation : la durée vient du parent et de rien d''autre, et on ne l''allonge pas sur une déduction. Se congèle 3 mois sans dommage : pois chiches et sauce d''arachide supportent le froid. La patate douce ramollit un peu à la décongélation, ce qui ne gêne pas un plat en sauce. Réchauffer à couvert et à feu doux avec un fond d''eau : la sauce a épaissi en refroidissant et attacherait. Cuire le riz au moment du service.', '{"fridge_hours":72,"eat_immediately":false,"freezable":true,"freezer_months":3,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'REAL-155'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

