  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Éplucher la patate douce et la tailler en cubes de trois centimètres, les carottes en tronçons épais, le chou en larges lanières ; émincer l''oignon, hacher l''ail. Les morceaux sont gros à dessein : ils doivent tenir trente-cinq minutes dans une sauce qu''on remue, et la patate douce taillée petite se défait en purée avant que la sauce ait pris.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire suer l''oignon dans l''huile d''arachide cinq minutes à feu moyen, ajouter la tomate concentrée et la remuer une bonne minute au contact du fond, jusqu''à ce qu''elle fonce et sente le cuit. Cette friture du concentré est le geste du parent : elle lui ôte son goût de fer et donne à la sauce sa couleur, ce que la viande colorée apportait aussi. Ajouter l''ail et le laisser parfumer trente secondes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Verser le bouillon de légumes, ajouter les carottes, le chou et le piment entier, porter à frémissement et cuire dix minutes à couvert. Les carottes et le chou entrent en premier parce qu''ils sont les plus longs à attendrir ; la patate douce, mise en même temps, serait défaite avant eux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ajouter les cubes de patate douce et poursuivre quinze minutes à petits frémissements, à couvert, jusqu''à ce qu''ils cèdent sous la pointe du couteau sans s''écraser.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Délayer la pâte d''arachide au fouet dans une louche de bouillon chaud puisée dans la cocotte, jusqu''à obtenir une crème lisse, puis la reverser dans le ragoût avec les pois chiches rincés et égouttés. Versée telle quelle, la pâte fait des grumeaux et attache au fond en brûlant ; délayée à part, elle se disperse. Les pois chiches, déjà cuits, n''ont besoin que de s''imprégner.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Cuire dix minutes à découvert en remuant souvent, jusqu''à ce que la sauce épaississe, nappe les légumes et que l''huile de l''arachide perle en surface — c''est le signe que le mafé est prêt, comme dans le parent. Retirer le piment, saler, poivrer, goûter. Servir sur du riz blanc.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-005', 'recipe_family', 'Mafé végétarien',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
