    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-005', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('b5ca93062bb6cf974c3e2c9c358f788f'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"nutty_savory","scores":{"sweet":3,"salty":3,"acidic":2,"bitter":1,"umami":3,"heat":2,"pungency":2,"richness":4,"freshness":1,"intensity":4},"dominant_flavors":["arachide","patate douce","tomate concentrée","pois chiche"],"aroma_families":["arachide","oignon_compoté","tomate_cuite","piment"],"target_textures":["sauce_onctueuse","légumes_entiers","pois chiches fondants"],"signature_ingredients":["Pâte d’arachide pure","Patate douce crue, épluchée","Pois chiche cuit, égoutté","Tomate concentrée"],"identity_guardrails":["La pâte d''arachide est pure et non sucrée, délayée dans le bouillon chaud et jamais versée telle quelle : un beurre de cacahuète sucré fait un autre plat","La sauce réduit jusqu''à napper et à laisser perler l''huile d''arachide, comme le parent — un mafé clair est une soupe","Les légumes entrent selon leur temps de cuisson, carotte et chou avant la patate douce, et restent entiers","Les pois chiches remplacent le bœuf et entrent en dernier, déjà cuits : versés au départ ils s''écraseraient et lieraient la sauce en purée"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Seitan alla cacciatora', 'seitan alla cacciatora', 'Italie', 'Italie',
     'meal', 'plat mijoté', 'named_traditional_dish', 'tomato_herbal',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Seitan alla cacciatora', 'Morceaux de seitan farinés et dorés, mijotés dans une sauce chasseur au vin rouge, à la tomate, aux olives et au romarin — le jumeau végétarien du pollo alla cacciatora', ds.id, 'JUM-006',
    'Myko', 'editorial', 6, 25, 40, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '747b6a7c8caeb78206414230b1a7d6cb',
    '{"sweet":2,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":2,"freshness":2,"intensity":4}'::jsonb, ARRAY['tomate','vin rouge réduit','olive','romarin']::text[],
    ARRAY['tomate_cuite','vin_rouge_réduit','romarin','oignon_compoté','ail']::text[], ARRAY['sauce_rustique','seitan ferme à croûte fondue','légumes fondants']::text[],
    ARRAY['Seitan','Tomate concassée en conserve','Vin rouge sec','Olive noire dénoyautée','Romarin frais']::text[], ARRAY['Le seitan est fariné et doré avant d''entrer dans la sauce : nu, il reste lisse, gris et glissant','Le vin rouge réduit avant la tomate, comme dans le parent — versé avec elle il reste aigre','Cuisson mijotée à couvert puis découverte, sans crème : la sauce nappe, elle ne baigne pas','Les olives sont obligatoires ici : les trois pages en portent, et c''est ce qui reste de la cacciatora quand le poulet s''en va']::text[],
    ARRAY['enrobage à la farine','saisie','soffritto','déglaçage','mijotage','réduction']::text[], ARRAY['Aux champignons de Paris, 350 g revenus avec l''oignon — la garniture du parent, qu''aucune page de seitan ne reprend','Seitan mariné une heure dans le vin rouge avec clous de girofle, baies de genièvre, thym, origan et poivre en grains, puis épongé et fariné ; concentré de tomate dans le bouillon plutôt que tomate concassée, câpres dessalées et olives vertes (petitchef)','En blanc, sans tomate : déglacé au vin blanc, aux olives taggiasche, à la sauge et au romarin, réduit à sec en fin de cuisson (academia)','Seitan fait maison à la farine de gluten et aux pommes de terre, poché une heure et demie dans un bouillon de légumes au kombu (academia)','Servi avec des tranches de pain pour saucer (vegolosi)']::text[], ARRAY['gluten']::text[],
    'Se garde 3 jours au réfrigérateur dans un récipient fermé — c''est ce que dit le parent, et aucune des trois pages de seitan ne parle de conservation : la durée vient du parent, pas du dossier — et gagne au deuxième jour, le seitan finissant de boire la sauce. Se congèle 3 mois : le seitan, contrairement au tofu, garde sa texture au froid, et une sauce tomate au vin sans crème ne tranche pas. Réchauffer à couvert et à feu doux avec un fond d''eau, la sauce ayant épaissi. C''est ce que fait physiquement un ragoût de gluten en sauce tomate, et c''est ce qu''on écrit.', '{"fridge_hours":72,"eat_immediately":false,"freezable":true,"freezer_months":3,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'REAL-095'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

