  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Couper le seitan en morceaux de trois centimètres, les éponger et les rouler dans la farine en secouant l''excédent. Faire chauffer la moitié de l''huile dans une sauteuse large et dorer les morceaux deux à trois minutes par face, sans les entasser, jusqu''à ce que la croûte de farine soit brune ; réserver. Le seitan nu est lisse et ne prend pas de couleur : c''est cette croûte qui accroche la sauce, comme la peau dorée le fait pour le poulet du parent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Tailler l''oignon, la carotte et le céleri en petits dés et les faire suer dans le reste de l''huile, dix minutes à feu moyen, avec le romarin, le thym et le laurier. Ajouter l''ail haché la dernière minute, le temps qu''il parfume sans brûler. Ce soffritto compte plus ici que dans le parent : sans le gras et le collagène de la cuisse, c''est lui qui donne du corps à la sauce.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Verser le vin rouge, gratter le fond et laisser réduire de moitié à feu vif, deux ou trois minutes, jusqu''à ce que l''odeur d''alcool ait disparu. Réduit avant la tomate, le vin garde son fruit et perd son âcreté ; versé avec elle, il resterait aigre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ajouter la tomate concassée, le bouillon de légumes et les olives, porter à frémissement, puis remettre les morceaux de seitan avec le jus qu''ils ont rendu. Couvrir et mijoter trente minutes à feu doux. Le seitan n''a pas de température à atteindre, contrairement au poulet ; ce temps sert à ce qu''il boive la sauce, et c''est pourquoi on ne l''écourte pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Découvrir et poursuivre dix minutes à petits bouillons, en remuant de temps en temps, jusqu''à ce que la sauce nappe les morceaux au lieu de baigner autour ; la farine de l''enrobage la lie au passage. Saler avec retenue — les olives et le seitan sont déjà salés —, poivrer, retirer le laurier. Laisser reposer cinq minutes et servir avec de la polenta, du pain ou des pommes de terre.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
