  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Tailler l''oignon en petits dés, les carottes en rondelles épaisses, le poivron en lanières, les tomates en dés, les pommes de terre en gros quartiers ; hacher l''ail ; rincer et égoutter les haricots. Les quartiers de pommes de terre sont gros pour la même raison que dans le parent : petits, ils se délitent et rendent le bouillon farineux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire fondre l''oignon dans l''huile, à feu doux et à couvert, quinze minutes, jusqu''à ce qu''il soit translucide et sucré sans couleur. Cette fondue est ce qui lie un goulash, et le jumeau en a autant besoin que le parent : sans viande ni farine, c''est elle et l''amidon des haricots qui donneront du corps au bouillon.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Retirer la marmite du feu, attendre une minute, puis jeter le paprika doux, le paprika fumé, le cumin et l''ail dans le gras tiède et remuer vivement pour les enrober. Le paprika brûle très bas et son amertume ne se rattrape pas : hors du feu, il s''ouvre dans la graisse et donne au plat sa couleur rouge profonde. Le fumé tient ici la place de la fumée que la viande apportait.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Remettre sur feu moyen, ajouter le poivron et les tomates, laisser rendre leur eau deux ou trois minutes, puis verser le bouillon de légumes, ajouter les carottes et le laurier. Porter à frémissement et cuire quinze minutes à couvert ; les carottes partent en premier parce qu''elles sont les plus longues.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter les pommes de terre et cuire vingt minutes, à petits frémissements, jusqu''à ce qu''un quartier cède sous la lame. Ajouter alors les haricots égouttés pour les dix dernières minutes seulement : déjà cuits, ils n''ont qu''à se réchauffer et à prendre le paprika, et versés au départ ils s''écraseraient. Écraser une louche de haricots contre la paroi et la remuer dans le bouillon : leur amidon le lie, et c''est ce qui remplace ici la longue réduction du parent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Saler — les haricots n''ont pas été salés en boîte comme la viande l''aurait été —, poivrer, retirer le laurier, et laisser reposer dix minutes hors du feu, le temps que les pommes de terre finissent de s''imbiber. Servir à la louche en assiette creuse, avec, pour qui le veut, une cuillerée de crème fraîche déposée dans l''assiette et non dans la marmite.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-007', 'recipe_family', 'Goulash végétarien aux haricots (babgulyás)',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-007', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Au tofu fumé, 200 g en dés revenus avec les légumes, avec de la patate douce et du thym — forme absente du catalogue (bonduelle)','Aux dés de soja déshydratés, 50 g trempés la veille, cuits avec les haricots secs, à l''huile de coco, avec racine de persil, chou-rave et céleri-rave — forme absente du catalogue (cookpad)','Aux haricots secs trempés la veille et cuits dans leur eau, qui sert ensuite de bouillon (mindenmentes, cookpad)','Avec des pâtes à potage — csipetke, galuska ou lebbencs — pochées dedans en fin de cuisson (urban-eve)','Relevé de pâte de piment hongroise, deux cuillerées pour dix, et servi avec une crème végétale (mindenmentes)','Aux haricots pinto plutôt que blancs, avec racine de persil et vert de céleri, parsemé de persil frais (mindenmentes)','Au poivron vert plutôt que rouge (mindenmentes)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-007","variants":["Au tofu fumé, 200 g en dés revenus avec les légumes, avec de la patate douce et du thym — forme absente du catalogue (bonduelle)","Aux dés de soja déshydratés, 50 g trempés la veille, cuits avec les haricots secs, à l''huile de coco, avec racine de persil, chou-rave et céleri-rave — forme absente du catalogue (cookpad)","Aux haricots secs trempés la veille et cuits dans leur eau, qui sert ensuite de bouillon (mindenmentes, cookpad)","Avec des pâtes à potage — csipetke, galuska ou lebbencs — pochées dedans en fin de cuisson (urban-eve)","Relevé de pâte de piment hongroise, deux cuillerées pour dix, et servi avec une crème végétale (mindenmentes)","Aux haricots pinto plutôt que blancs, avec racine de persil et vert de céleri, parsemé de persil frais (mindenmentes)","Au poivron vert plutôt que rouge (mindenmentes)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-007', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('ad471562b644f25fa1edf038da4660e1'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":3,"heat":1,"pungency":2,"richness":2,"freshness":1,"intensity":3},"dominant_flavors":["paprika doux","oignon fondu","haricot blanc","tomate cuite"],"aroma_families":["paprika","oignon compoté","fumé","tomate cuite"],"target_textures":["haricots fondants mais entiers","pomme de terre juste tenue","bouillon rouge lié"],"signature_ingredients":["Haricot blanc cuit, égoutté","Paprika doux","Oignon jaune cru","Pomme de terre crue, épluchée"],"identity_guardrails":["Sans paprika doux en quantité — 15 g pour huit, jetés hors du feu — ce n''est qu''une soupe de haricots : la couleur et le parfum ne viennent de rien d''autre","L''oignon fondu et une louche de haricots écrasés lient le bouillon : ni farine ni crème dans la marmite, qui en feraient un paprikás","Les haricots entrent en dernier, déjà cuits, et restent entiers ; cuits une heure dans le paprika ils font une purée","Le bouillon reste franchement liquide et se sert à la louche : c''est une soupe-ragoût, pas une sauce"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Boulettes de lentilles sauce tomate', 'boulettes de lentilles sauce tomate', 'France / cuisine domestique internationale', 'France / cuisine domestique internationale',
     'meal', 'boulettes', 'domestic_standard', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Boulettes de lentilles sauce tomate', 'Des boulettes de lentilles vertes liées à l''œuf, à la chapelure et au parmesan, dorées puis finies dans une sauce tomate à l''oignon — le jumeau végétarien des boulettes de bœuf', ds.id, 'JUM-031',
    'Myko', 'editorial', 6, 30, 50, 'facile',
    NULL, NULL,
    'B', 'candidate', '8b5c187e030f7c2410515ce00b2946ea',
    '{"sweet":2,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":2,"freshness":2,"intensity":3}'::jsonb, ARRAY['tomate cuite','lentille','parmesan','persil']::text[],
    ARRAY['tomate_cuite','oignon_compoté','lentille','fromage affiné']::text[], ARRAY['boulette moelleuse à cœur, croûte fine','grain de lentille sous la dent','sauce_nappante']::text[],
    ARRAY['Lentille verte sèche, crue','Tomate concassée en conserve','Chapelure de blé','Œuf cru']::text[], ARRAY['Les lentilles sont cuites à fond puis écrasées à moitié seulement : trop fermes elles ne lient pas, mixées elles font une pâte compacte','La farce repose vingt minutes avant façonnage — c''est la chapelure gonflée, plus que l''œuf, qui tient une boulette sans viande','Les boulettes finissent dix minutes dans la sauce, pas vingt : la lentille ne se raffermit pas comme la viande, elle ramollit','Même sauce tomate à l''oignon et à l''ail que le parent, l''allium dans la sauce et non dans la farce']::text[],
    ARRAY['cuisson des lentilles à l''eau non salée','écrasement partiel','farce liée','repos','façonnage','panure sèche','saisie','finition en sauce']::text[], ARRAY['Aux lentilles corail, cuites en purée puis liées à la chapelure, plus fondantes et plus fragiles (marmiton, chefsimon, 750g)','Liées à la farine plutôt qu''à la chapelure, 50 g pour 250 g de lentilles (chefsimon), ou huit cuillerées à soupe travaillées dans la farce avant façonnage (marmiton)','Avec du concentré de tomate dans la farce, deux cuillerées pour quatre, qui colore et resserre la boulette (chefsimon, 750g)','Aux carottes râpées, 200 g pour cinq, et au son d''avoine à la place d''une partie de la chapelure (chefsimon)','Épicées au cumin, au curry ou au massalé et au curcuma, une cuillerée à café pour quatre (chefsimon, 750g)','Une échalote ou un oignon ciselé dans la farce, ce que sept pages font et que le parent ne fait pas (marmiton, chefsimon, 750g)','Cuites au four à 180 °C vingt minutes sur une plaque huilée plutôt qu''à la poêle, ou dix minutes au four puis passées à la poêle pour croustiller (marmiton, 750g)','En mercimek köftesi turques : lentilles corail et boulgour pétris à cru avec oignon, concentré et menthe, servis froids — un autre plat sous le même mot (marmiton, 750g)','Sans parmesan — neuf pages sur dix n''en mettent pas — ou avec une pâte dure sans présure animale, pour un végétarien strict']::text[], ARRAY['gluten','œuf','lait']::text[],
    'Dans leur sauce, les boulettes se gardent 3 jours au réfrigérateur dans un récipient fermé, et elles gagnent au deuxième jour, la sauce ayant fini de les imprégner. Elles se congèlent 2 mois dans leur sauce — la lentille liée à l''œuf supporte le froid sans s''écraser davantage, et c''est la sauce qui la protège du dessèchement. La seule page du dossier qui parle de congélation est une köfte crue de lentilles corail et de boulgour, préparation trop éloignée pour valoir attestation ici : on ne s''en réclame pas. Réchauffer à couvert et à feu doux sans remuer, les boulettes réchauffées étant plus fragiles qu''à la sortie de la poêle. Les boulettes façonnées crues se gardent 24 heures au frais sur un plateau filmé, pas plus : l''œuf et la chapelure continuent de boire et la farce se dessèche. Le parent FR-019 ne dit de la conservation que « 4 jours au réfrigérateur ; congélation 3 mois » : les durées ci-dessus sont plus courtes que les siennes et ne viennent ni de lui ni du dossier, qui n''en porte aucune, mais de ce qu''une farce de légumineuse fait physiquement.', '{"fridge_hours":72,"eat_immediately":false,"freezable":true,"freezer_months":2,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'FR-019'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
