  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Rincer les lentilles vertes, les couvrir de trois fois leur volume d''eau froide sans sel et les cuire vingt-cinq minutes à petit frémissement, jusqu''à ce qu''elles s''écrasent sous le doigt. Elles doivent être plus cuites que pour une salade : c''est leur amidon libéré qui tiendra la boulette, et une lentille encore ferme ne lie rien. Les égoutter à fond et les laisser tiédir dans la passoire, car une farce mouillée réclame le double de chapelure.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Écraser les lentilles tièdes à la fourchette ou au presse-purée, en s''arrêtant quand la moitié est en purée et l''autre moitié encore en grains. Ce grain est ce qui remplace le haché du parent sous la dent ; passées au mixeur, elles donneraient une pâte lisse qui fait une boulette compacte et triste.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Ajouter les œufs battus, 60 g de chapelure, le parmesan râpé, le persil ciselé, la moitié du sel et le poivre, et mélanger du bout des doigts jusqu''à ce que la masse se tienne quand on la presse. Laisser reposer vingt minutes au frais : la chapelure boit l''humidité des lentilles pendant ce temps, et c''est ce repos, plus que l''œuf, qui empêche les boulettes de s''ouvrir à la poêle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Pendant le repos, lancer la sauce : faire fondre l''oignon émincé six à huit minutes dans 25 ml d''huile à feu moyen sans le colorer, ajouter l''ail haché une minute, puis les tomates concassées et le reste du sel. Laisser mijoter quinze minutes à découvert, à petits bouillons, jusqu''à ce que la sauce épaississe un peu — elle doit pouvoir porter les boulettes sans les noyer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Former à mains humides des boulettes de la taille d''une noix, 35 g environ, et les rouler dans les 30 g de chapelure restants. Compter une trentaine de boulettes pour six. L''enrobage n''est pas décoratif : une farce de lentilles ne rend aucun gras et ne croûte pas seule, et c''est cette chapelure qui, dans l''huile, lui donne la surface dorée qu''une boulette de viande fabrique d''elle-même.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Chauffer les 20 ml d''huile restants dans une grande poêle à feu moyen-vif et y dorer les boulettes en deux fournées, deux minutes par face, en les retournant à la cuillère plutôt qu''à la pince. Ne pas chercher à les rouler sur toutes leurs faces comme des boulettes de viande : deux faces dorées suffisent, et chaque manipulation de plus est une boulette qui se fend.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Déposer les boulettes dans la sauce, sans les remuer, et poursuivre dix minutes à couvert et à feu doux — pas les vingt du parent. La viande se raffermit dans la sauce en cuisant ; la lentille, elle, ne fait que ramollir, et dix minutes suffisent à ce que la sauce l''imprègne sans la défaire. Servir avec des pâtes, du riz ou du pain, la sauce nappée à la cuillère.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-031', 'recipe_family', 'Boulettes de lentilles sauce tomate',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-031', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Aux lentilles corail, cuites en purée puis liées à la chapelure, plus fondantes et plus fragiles (marmiton, chefsimon, 750g)','Liées à la farine plutôt qu''à la chapelure, 50 g pour 250 g de lentilles (chefsimon), ou huit cuillerées à soupe travaillées dans la farce avant façonnage (marmiton)','Avec du concentré de tomate dans la farce, deux cuillerées pour quatre, qui colore et resserre la boulette (chefsimon, 750g)','Aux carottes râpées, 200 g pour cinq, et au son d''avoine à la place d''une partie de la chapelure (chefsimon)','Épicées au cumin, au curry ou au massalé et au curcuma, une cuillerée à café pour quatre (chefsimon, 750g)','Une échalote ou un oignon ciselé dans la farce, ce que sept pages font et que le parent ne fait pas (marmiton, chefsimon, 750g)','Cuites au four à 180 °C vingt minutes sur une plaque huilée plutôt qu''à la poêle, ou dix minutes au four puis passées à la poêle pour croustiller (marmiton, 750g)','En mercimek köftesi turques : lentilles corail et boulgour pétris à cru avec oignon, concentré et menthe, servis froids — un autre plat sous le même mot (marmiton, 750g)','Sans parmesan — neuf pages sur dix n''en mettent pas — ou avec une pâte dure sans présure animale, pour un végétarien strict']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-031","variants":["Aux lentilles corail, cuites en purée puis liées à la chapelure, plus fondantes et plus fragiles (marmiton, chefsimon, 750g)","Liées à la farine plutôt qu''à la chapelure, 50 g pour 250 g de lentilles (chefsimon), ou huit cuillerées à soupe travaillées dans la farce avant façonnage (marmiton)","Avec du concentré de tomate dans la farce, deux cuillerées pour quatre, qui colore et resserre la boulette (chefsimon, 750g)","Aux carottes râpées, 200 g pour cinq, et au son d''avoine à la place d''une partie de la chapelure (chefsimon)","Épicées au cumin, au curry ou au massalé et au curcuma, une cuillerée à café pour quatre (chefsimon, 750g)","Une échalote ou un oignon ciselé dans la farce, ce que sept pages font et que le parent ne fait pas (marmiton, chefsimon, 750g)","Cuites au four à 180 °C vingt minutes sur une plaque huilée plutôt qu''à la poêle, ou dix minutes au four puis passées à la poêle pour croustiller (marmiton, 750g)","En mercimek köftesi turques : lentilles corail et boulgour pétris à cru avec oignon, concentré et menthe, servis froids — un autre plat sous le même mot (marmiton, 750g)","Sans parmesan — neuf pages sur dix n''en mettent pas — ou avec une pâte dure sans présure animale, pour un végétarien strict"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-031', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('8b5c187e030f7c2410515ce00b2946ea'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":2,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":2,"freshness":2,"intensity":3},"dominant_flavors":["tomate cuite","lentille","parmesan","persil"],"aroma_families":["tomate_cuite","oignon_compoté","lentille","fromage affiné"],"target_textures":["boulette moelleuse à cœur, croûte fine","grain de lentille sous la dent","sauce_nappante"],"signature_ingredients":["Lentille verte sèche, crue","Tomate concassée en conserve","Chapelure de blé","Œuf cru"],"identity_guardrails":["Les lentilles sont cuites à fond puis écrasées à moitié seulement : trop fermes elles ne lient pas, mixées elles font une pâte compacte","La farce repose vingt minutes avant façonnage — c''est la chapelure gonflée, plus que l''œuf, qui tient une boulette sans viande","Les boulettes finissent dix minutes dans la sauce, pas vingt : la lentille ne se raffermit pas comme la viande, elle ramollit","Même sauce tomate à l''oignon et à l''ail que le parent, l''allium dans la sauce et non dans la farce"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Boulettes de haricots rouges', 'boulettes de haricots rouges', 'France / cuisine domestique internationale', 'France / cuisine domestique internationale',
     'meal', 'boulettes', 'domestic_standard', 'smoky_sweet',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Boulettes de haricots rouges', 'Haricots rouges écrasés, oignon, cumin et paprika, liés à l''œuf et à la chapelure, roulés en boulettes et dorés à la poêle — le jumeau végétarien des boulettes de viande', ds.id, 'JUM-032',
    'Myko', 'editorial', 4, 15, 20, 'facile',
    NULL, NULL,
    'B', 'candidate', 'c4c21d42642aa67cbda56d11810d9b1c',
    '{"sweet":2,"salty":3,"acidic":1,"bitter":1,"umami":3,"heat":1,"pungency":2,"richness":2,"freshness":1,"intensity":3}'::jsonb, ARRAY['haricot rouge','cumin','paprika','oignon']::text[],
    ARRAY['cumin','paprika','oignon','haricot cuit']::text[], ARRAY['croûte fine et sèche','cœur moelleux avec des morceaux de haricots','boulette qui tient à la fourchette']::text[],
    ARRAY['Haricot rouge cuit, égoutté','Cumin moulu','Paprika doux','Chapelure de blé']::text[], ARRAY['Les haricots sont épongés avant d''être écrasés : une farce mouillée ne se façonne pas','Écrasement partiel, jamais mixé lisse — un tiers de haricots entiers fait la mâche','La farce repose avant façonnage et les boulettes ne sont retournées qu''une fois : c''est la fragilité du plat','Cumin et paprika sont indispensables ici et absents du parent : le haricot écrasé n''a pas le goût de la viande','Servies avec une sauce à côté, jamais mijotées dedans']::text[],
    ARRAY['égouttage et séchage','écrasement partiel','farce liée','repos','façonnage','saisie à feu moyen','cuisson à couvert']::text[], ARRAY['Liées aux flocons d''avoine plutôt qu''à l''œuf et à la chapelure, 30 g pour 250 g de haricots, pour une version végétalienne — forme absente du catalogue (deliacious.com, sainplementhealthy.com)','Sans liant, simplement roulées dans la farine avant de passer à la poêle à feu vif dans de l''huile de tournesol (blogdechataigne.fr)','Cuites au four vingt minutes à 180 ou 190 °C sur une plaque, retournées à mi-cuisson, puis éventuellement dorées à la poêle (deliacious.com, sainplementhealthy.com)','Au paprika fumé et à la coriandre moulue (deliacious.com)','Avec une cuillerée à café de moutarde dans la farce (blogdechataigne.fr)','Avec 10 ml de sauce soja dans la farce à la place du sel (sainplementhealthy.com)','Dorées puis mijotées dans un bouillon de légumes lié à la fécule, servies sur un riz aux poivrons (coeuretavc.ca)']::text[], ARRAY['gluten','œuf']::text[],
    'Cuites, les boulettes se gardent 3 jours au réfrigérateur dans une boîte fermée, et se réchauffent à la poêle à feu doux ou au four plutôt qu''au micro-ondes, qui les ramollit. Elles se congèlent 2 mois, séparées d''abord sur une plaque puis rassemblées en sachet, et se réchauffent sans décongélation au four à 180 °C ; congelées crues, elles rendent leur eau et s''écrasent — on congèle cuites, contrairement au parent. Le dossier ne dit rien de la conservation, sinon qu''une page déconseille de laisser ces boulettes dans une sauce ; ce qui est écrit ici est ce qu''une purée de légumineuse liée à l''œuf fait physiquement.', '{"fridge_hours":72,"eat_immediately":false,"freezable":true,"freezer_months":2,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'RAP-017'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

