  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Rincer les haricots rouges à l''eau froide, les égoutter longuement puis les éponger dans un torchon. C''est le geste qui décide de tout le reste : un haricot de boîte est gorgé de son jus, et une farce mouillée ne se façonne pas, quelle que soit la chapelure qu''on y ajoute.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Râper l''oignon à la grosse grille et presser son jus entre les doigts, comme pour le parent, puis l''écraser avec les haricots à la fourchette ou au presse-purée. S''arrêter quand la purée garde encore un tiers de haricots entiers : c''est cette mâche qui fait la boulette, et un mixeur poussé jusqu''au lisse donne une pâte qui colle et se tasse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Ajouter l''œuf battu, la chapelure, le concentré de tomate, l''ail en purée, le persil ciselé, le cumin, le paprika, le sel et le poivre, et mélanger à la main jusqu''à ce que la masse se tienne quand on la serre. Goûter la farce crue — elle est faite de haricots cuits, on le peut — et corriger le sel : un haricot écrasé est fade là où le bœuf ne l''est pas, c''est la raison des épices.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Laisser reposer la farce quinze minutes au frais, le temps que la chapelure boive l''humidité restante. Ce repos est plus nécessaire qu''avec la viande : sans lui la boulette s''ouvre au premier retournement, et c''est la première cause d''échec de ce plat.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Former à paumes humides des billes d''environ 35 g, une vingtaine pour 400 g de haricots, et les poser sur une assiette sans qu''elles se touchent. Les serrer un peu plus fermement qu''une boulette de viande, qui se soude en cuisant quand celle-ci ne fait que sécher.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Chauffer l''huile à feu moyen — pas vif — dans une grande poêle antiadhésive et y déposer les boulettes en une seule couche. Les laisser trois minutes sans y toucher, jusqu''à ce que la face au contact ait pris une croûte brune, puis les retourner d''un seul geste à la cuillère et donner trois minutes à l''autre face. Une boulette de haricots ne se roule pas sur toutes ses faces comme celle du parent : deux faces suffisent, et chaque manipulation de plus la fend.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Baisser le feu et laisser quatre à cinq minutes de plus en secouant la poêle de temps en temps, pour que le cœur soit chaud et que l''œuf ait pris. Servir aussitôt, nature, avec un riz ou une sauce tomate fluide versée à côté plutôt que dessus : laissées à mijoter dans une sauce, ces boulettes se délitent, et une page du dossier le dit expressément.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-032', 'recipe_family', 'Boulettes de haricots rouges',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-032', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Liées aux flocons d''avoine plutôt qu''à l''œuf et à la chapelure, 30 g pour 250 g de haricots, pour une version végétalienne — forme absente du catalogue (deliacious.com, sainplementhealthy.com)','Sans liant, simplement roulées dans la farine avant de passer à la poêle à feu vif dans de l''huile de tournesol (blogdechataigne.fr)','Cuites au four vingt minutes à 180 ou 190 °C sur une plaque, retournées à mi-cuisson, puis éventuellement dorées à la poêle (deliacious.com, sainplementhealthy.com)','Au paprika fumé et à la coriandre moulue (deliacious.com)','Avec une cuillerée à café de moutarde dans la farce (blogdechataigne.fr)','Avec 10 ml de sauce soja dans la farce à la place du sel (sainplementhealthy.com)','Dorées puis mijotées dans un bouillon de légumes lié à la fécule, servies sur un riz aux poivrons (coeuretavc.ca)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-032","variants":["Liées aux flocons d''avoine plutôt qu''à l''œuf et à la chapelure, 30 g pour 250 g de haricots, pour une version végétalienne — forme absente du catalogue (deliacious.com, sainplementhealthy.com)","Sans liant, simplement roulées dans la farine avant de passer à la poêle à feu vif dans de l''huile de tournesol (blogdechataigne.fr)","Cuites au four vingt minutes à 180 ou 190 °C sur une plaque, retournées à mi-cuisson, puis éventuellement dorées à la poêle (deliacious.com, sainplementhealthy.com)","Au paprika fumé et à la coriandre moulue (deliacious.com)","Avec une cuillerée à café de moutarde dans la farce (blogdechataigne.fr)","Avec 10 ml de sauce soja dans la farce à la place du sel (sainplementhealthy.com)","Dorées puis mijotées dans un bouillon de légumes lié à la fécule, servies sur un riz aux poivrons (coeuretavc.ca)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-032', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('c4c21d42642aa67cbda56d11810d9b1c'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"smoky_sweet","scores":{"sweet":2,"salty":3,"acidic":1,"bitter":1,"umami":3,"heat":1,"pungency":2,"richness":2,"freshness":1,"intensity":3},"dominant_flavors":["haricot rouge","cumin","paprika","oignon"],"aroma_families":["cumin","paprika","oignon","haricot cuit"],"target_textures":["croûte fine et sèche","cœur moelleux avec des morceaux de haricots","boulette qui tient à la fourchette"],"signature_ingredients":["Haricot rouge cuit, égoutté","Cumin moulu","Paprika doux","Chapelure de blé"],"identity_guardrails":["Les haricots sont épongés avant d''être écrasés : une farce mouillée ne se façonne pas","Écrasement partiel, jamais mixé lisse — un tiers de haricots entiers fait la mâche","La farce repose avant façonnage et les boulettes ne sont retournées qu''une fois : c''est la fragilité du plat","Cumin et paprika sont indispensables ici et absents du parent : le haricot écrasé n''a pas le goût de la viande","Servies avec une sauce à côté, jamais mijotées dedans"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Stroganoff de champignons', 'stroganoff de champignons', 'Russie', 'Russie',
     'meal', 'plat sauté', 'named_traditional_dish', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Stroganoff de champignons', 'Champignons de Paris sautés à feu vif puis liés dans une sauce à l''oignon, au vin blanc, à la moutarde, au paprika et à la crème — le jumeau végétarien du bœuf Stroganoff', ds.id, 'JUM-033',
    'Myko', 'editorial', 4, 15, 25, 'facile',
    NULL, NULL,
    'B', 'candidate', 'ee907de06c347f04552fe7cc83757567',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":1,"pungency":3,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['champignon rôti','crème','moutarde','oignon fondu']::text[],
    ARRAY['champignon','oignon_compoté','moutarde','paprika','crème']::text[], ARRAY['champignons dorés et fermes','sauce_nappante','oignon fondu']::text[],
    ARRAY['Champignon de Paris frais','Crème fraîche épaisse','Moutarde de Dijon','Paprika doux']::text[], ARRAY['Les champignons se sautent à feu vif, sans sel, en deux fournées, jusqu''à évaporation de leur eau : c''est la saisie du bœuf transposée, et un champignon bouilli fait une soupe','La moutarde entre en dernier et ne bout jamais, comme dans le parent','Bouillon de légumes et non de bœuf : c''est la seule autre forme animale du parent, et elle part avec la viande','Crème fraîche épaisse, pas lait de coco : le coco fait une autre sauce et un autre plat']::text[],
    ARRAY['sauté à feu vif en deux fournées','fondre l''oignon','singer','déglaçage','réduction','liaison à la crème']::text[], ARRAY['Au lait de coco à la place de la crème et du bouillon, 800 ml pour quatre, réduit vingt minutes à feu vif, pour une version végétalienne (marciatack.fr, sharkninja.fr)','À la crème de cajou : 140 g de noix de cajou trempées mixées avec le bouillon, du tamari et du vinaigre balsamique, sur des fettuccine (menu-vegetarien.com)','À la crème de soja ou d''avoine, avec du sirop d''érable, de la sauce soja, du thym et du laurier, servi sur des linguine (larecetteparfaite.com)','Avec 200 g de tofu fumé sauté avec les champignons, pour retrouver une protéine, servi sur une purée à l''huile d''olive (lescommis.com)','Un jus de citron incorporé avec la crème, pour l''acidité de la crème aigre du plat russe (marciatack.fr, menu-vegetarien.com, sharkninja.fr)','Au paprika fumé en plus du doux (larecetteparfaite.com)','Lié à la fécule de maïs plutôt qu''à la farine, pour une version sans gluten (sharkninja.fr)']::text[], ARRAY['lait','gluten','moutarde']::text[],
    'Se garde 2 jours au réfrigérateur dans un récipient fermé, et se réchauffe à feu très doux sans bouillir, la crème et la moutarde ne le supportant pas ; les champignons rendent un peu d''eau au froid et la sauce se détend, ce qui se rattrape en la laissant frémir une minute avant d''ajouter une cuillerée de crème. Ne se congèle pas : la sauce à la crème tranche et les champignons décongelés deviennent spongieux. C''est ce que dit le parent pour sa sauce, et ce que fait un champignon sauté au congélateur ; aucune des six pages ne parle de conservation.', '{"fridge_hours":48,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'VAR-027'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

