  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Chauffer le four à 180 °C. Tapisser un moule à cake de vingt-quatre centimètres de papier cuisson, ou en passer les parois au pinceau avec un peu de l''huile pesée. La feta relâche une eau salée pendant la cuisson et la mie s''accroche partout où elle touche le métal nu ; sans protection, la tranche se déchire au démoulage.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Sortir la feta de sa saumure, l''essuyer et la couper en cubes d''un centimètre — surtout pas l''émietter. En miettes elle se dissout dans l''appareil et le cake perd la garniture visible que faisaient, chez le parent, les dés de jambon ; en cubes elle reste blanche à la coupe et fond en poches crémeuses. Égoutter les olives, les sécher dans un linge, les fendre en deux dans la longueur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Réunir la farine et la levure dans un saladier et les fouetter à sec, en mettant une cuillerée à soupe de farine de côté pour plus tard. Ouvrir un puits, y casser les quatre œufs et les incorporer un par un, puis faire couler le lait et l''huile en tournant sans s''arrêter jusqu''à ce que la pâte soit lisse et coulante. Ne pas insister au-delà : plus longtemps on la bat, plus le gluten se développe et plus la mie sort élastique.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Faire rouler les cubes de feta et les demi-olives dans la cuillerée de farine réservée, puis les verser dans l''appareil avec le gruyère râpé. Ce voile de farine fait deux choses : il tient la garniture en suspension au lieu de la laisser couler au fond pendant la levée, et il boit la saumure qui suinte des deux éléments les plus mouillés du cake, laquelle laisserait sinon des zones grises et détrempées dans la mie. Poivrer, et ne saler que de trois grammes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser dans le moule, lisser le dessus à la spatule et enfourner pour quarante-cinq minutes. Garder la porte fermée jusqu''à la trentième minute au moins : cet appareil porte 420 g de garniture pour 200 g de farine, il ne monte que par une chaleur constante et retombe au centre au premier courant d''air.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Planter la pointe d''un couteau au cœur : la lame doit ressortir sèche, sans trace de pâte crue. Laisser reposer dix minutes, démouler sur une grille et attendre le refroidissement complet avant de trancher. Chaude, la feta est molle et la tranche s''effrite ; froide, elle s''est resserrée et le couteau passe net. Le lendemain, la coupe est encore plus propre.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-041', 'recipe_family', 'Cake aux olives et à la feta',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-041', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Aux olives noires, six pages du dossier sur neuf, de 60 à 100 g déclarés selon les pages, soit 7,5 à 20 g par personne — la mie en sort plus sombre et plus amère (marmiton.org, chefsimon.com, 750g.com)','Aux tomates séchées ou confites, de 50 g pour quatre à 130 g pour six, ajoutées à la garniture (marmiton.org, chefsimon.com, 750g.com)','Au basilic frais ou à l''origan séché dans l''appareil, une cuillerée à soupe pour six (marmiton.org, chefsimon.com, 750g.com)','Moitié huile d''olive, moitié beurre clarifié, 100 g de chacun pour six : mie plus courte et plus riche (marmiton.org)','Avec une courgette et un oignon revenus à la poêle avant d''être incorporés, ou 500 g de haricots verts, ou les fanes d''une botte de radis (chefsimon.com, 750g.com)','Monté au yaourt et au bicarbonate plutôt qu''au lait et à la levure chimique (chefsimon.com)','Relevé d''une pointe de curry ou de tandoori à la place du poivre (marmiton.org, 750g.com)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-041","variants":["Aux olives noires, six pages du dossier sur neuf, de 60 à 100 g déclarés selon les pages, soit 7,5 à 20 g par personne — la mie en sort plus sombre et plus amère (marmiton.org, chefsimon.com, 750g.com)","Aux tomates séchées ou confites, de 50 g pour quatre à 130 g pour six, ajoutées à la garniture (marmiton.org, chefsimon.com, 750g.com)","Au basilic frais ou à l''origan séché dans l''appareil, une cuillerée à soupe pour six (marmiton.org, chefsimon.com, 750g.com)","Moitié huile d''olive, moitié beurre clarifié, 100 g de chacun pour six : mie plus courte et plus riche (marmiton.org)","Avec une courgette et un oignon revenus à la poêle avant d''être incorporés, ou 500 g de haricots verts, ou les fanes d''une botte de radis (chefsimon.com, 750g.com)","Monté au yaourt et au bicarbonate plutôt qu''au lait et à la levure chimique (chefsimon.com)","Relevé d''une pointe de curry ou de tandoori à la place du poivre (marmiton.org, 750g.com)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-041', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('2b8492dc4569bd75883f90e1508defe2'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":4,"acidic":2,"bitter":2,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3},"dominant_flavors":["olive_saumurée","feta_lactique","fromage_fondu"],"aroma_families":["olive_verte","feta","mie_dorée"],"target_textures":["mie_moelleuse","garniture_en_dés","croûte_dorée"],"signature_ingredients":["Feta","Olive verte dénoyautée","Gruyère râpé"],"identity_guardrails":["Sans olives il ne reste qu''un cake à la feta : c''est leur sel et leur amertume qui donnent au plat son nom, et deux pages du dossier les prennent vertes comme la lignée le fait.","La feta se taille en cubes d''un centimètre et ne s''émiette jamais : émiettée elle disparaît dans la mie, et le cake perd la garniture visible que les dés de jambon donnaient au parent.","La levure chimique n''est pas négociable : cinq pages sur neuf mettent un sachet entier et un appareil aussi chargé de garniture sort compact sans elle.","Aucune viande, aucun poisson : les deux pages au saumon et au jambon que la recherche a ramenées ont été écartées avant relevé, et c''est ce qui fait de ce cake le jumeau végétarien de FR-028."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Tartiflette végétarienne', 'tartiflette vegetarienne', 'France', 'France',
     'meal', 'tartiflette', 'domestic_standard', 'creamy_delicate',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Tartiflette végétarienne', 'La tartiflette de la lignée REAL-075 sans lardons : des cubes de tofu fumé dorés à la poêle prennent leur place sous les mêmes pommes de terre, le même oignon au vin blanc et le même reblochon fendu.', ds.id, 'JUM-042',
    'Myko', 'editorial', 6, 25, 55, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '65b610f3fcd3064fdc1f2a8e693653e8',
    '{"sweet":1,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['reblochon fondu','tofu fumé','oignon compoté','vin blanc réduit']::text[],
    ARRAY['reblochon','fumé','oignon_compoté','vin_blanc_réduit']::text[], ARRAY['pommes_de_terre_fondantes','fromage_coulant','cubes de tofu dorés','dessus_doré']::text[],
    ARRAY['Reblochon au lait cru','Pomme de terre crue, avec peau','Tofu fumé']::text[], ARRAY['Le reblochon est fendu en deux dans l''épaisseur et posé croûte vers le haut, jamais râpé ni coupé en dés : c''est la croûte qui fait couvercle et qui dore.','Le tofu est FUMÉ et non nature : ce que le lardon apportait à ce gratin est d''abord la fumée, et la page qui emploie un tofu nature doit la rattraper à la sauce soja, ce qu''on n''écrit pas.','Les pommes de terre sont précuites tout juste tendres puis tranchées : cuites à cœur, elles se délitent en purée sous le fromage.','Aucun lardon et aucun bouillon animal : le seul mouillement est le vin blanc, et le plat est végétarien par ses formes autant que par son nom.']::text[],
    ARRAY['précuisson','égouttage','fondue d''oignons','saisie','déglaçage','montage en couches','gratinage']::text[], ARRAY['Au tofu nature à la place du tofu fumé, un bloc de 400 g pour quatre, relevé à la sauce soja et à un verre de bouillon de légumes (marmiton.org)','Aux champignons parfumés séchés plutôt qu''au tofu, trois par personne, réhydratés puis taillés en morceaux (750g.com)','Aux tomates séchées, 320 g pour quatre, avec des oignons rouges caramélisés à 20 g de sucre de canne (marmiton.org)','À la courge butternut à la place des pommes de terre, avec une cuillerée à café de muscade — un autre plat sous le même nom (chefsimon.com)','Avec beaucoup plus de crème, jusqu''à 125 g par personne, pour un gratin franchement liquide (marmiton.org)','Montée en couches alternées comme des lasagnes plutôt qu''en deux étages, tout le mélange étant réparti entre les épaisseurs de pommes de terre (marmiton.org)','Les pommes de terre rissolées à la poêle au beurre et à l''huile au lieu d''être cuites à l''eau, puis terminées à couvert (750g.com)']::text[], ARRAY['lait','soja']::text[],
    'Trois jours au réfrigérateur, couvert, et se réchauffe vingt-cinq minutes à 170 °C plutôt qu''au micro-ondes, qui rend la pomme de terre spongieuse et fait suinter le fromage. Congélation déconseillée, et la raison est physique : la pomme de terre cuite se cristallise et rend son eau au dégel, le reblochon fondu se sépare en gras et en petit-lait, et le tofu fumé, déjà pressé, devient franchement caoutchouteux — trois textures perdues d''un coup pour un plat dont tout l''intérêt est la texture. Aucune des cinq pages du dossier ne parle de conservation ; ces durées sont celles que ce gratin tient réellement, et on le dit plutôt que de les attribuer aux sources.', '{"fridge_hours":72,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'REAL-075'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'pomme de terre crue avec peau' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Pomme de terre crue, avec peau', 1200, 'g', 'required',
     'base', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'reblochon au lait cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Reblochon au lait cru', 500, 'g', 'required',
     'fromage', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'tofu fume' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Tofu fumé', 300, 'g', 'required',
     'protéine', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'oignon jaune cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Oignon jaune cru', 250, 'g', 'required',
