  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 2, 'g', 'required',
     'assaisonnement', false, 9);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Cuire les pommes de terre entières et non pelées à l''eau salée, une vingtaine de minutes après la reprise de l''ébullition pour des tubercules moyens. Elles doivent être tout juste tendres sous la lame et pas davantage : elles finiront au four, et une pomme de terre déjà cuite à cœur se défait en purée sous le fromage. Les laisser tiédir, les peler et les couper en rondelles d''un demi-centimètre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Pendant ce temps, égoutter le tofu fumé, le presser une minute entre deux feuilles de papier absorbant et le tailler en cubes d''un centimètre. Le séchage n''est pas un détail : un tofu gorgé d''eau ne colore pas, il bout dans son propre jus et ressort gris et mou, alors que c''est justement sa surface dorée qui doit tenir le rôle du lardon croustillant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Faire fondre le beurre dans une grande poêle à feu moyen et y jeter l''oignon émincé avec une pincée du sel. Le laisser blondir une dizaine de minutes sans le brûler. Chez le parent, c''est le lardon qui fournissait à la fois la graisse et le sel de cette étape ; ici le beurre s''en charge, et la pincée de sel tire l''eau de l''oignon pour qu''il compote au lieu de frire.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Pousser l''oignon sur un côté de la poêle, monter le feu et faire sauter les cubes de tofu cinq à six minutes, en ne les retournant que lorsque la face posée a pris couleur. Verser alors le vin blanc sur l''ensemble et laisser réduire jusqu''à ce qu''il n''en reste qu''un fond sirupeux. Le vin fait ici le travail que faisait le gras fumé : il donne l''acidité et la longueur sans lesquelles la pomme de terre et le reblochon n''auraient qu''un goût de crème.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Frotter un plat à gratin d''un peu de beurre et monter deux étages : la moitié des rondelles, la moitié du mélange oignon-tofu, le reste des rondelles, le reste du mélange. Saler et poivrer entre les couches plutôt que sur le dessus seulement — le fond resterait fade, et le tofu fumé apporte trois fois et demie moins de sel au poids que les lardons qu''il remplace.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Répartir la crème sur le dessus si l''on en met, puis fendre le reblochon en deux dans l''épaisseur et poser les deux moitiés croûte vers le haut, sans les débiter en morceaux. La croûte sert de couvercle : elle retient la pâte qui coule dessous et se colore elle-même, ce qu''un fromage retourné ou râpé ne fera jamais.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Enfourner à 180 °C pour une trentaine de minutes, jusqu''à ce que la surface soit brune par plaques et que le gratin bouillonne sur les bords. Laisser reposer dix minutes hors du four avant de servir : à la sortie, le fromage est encore liquide et la part s''étale dans l''assiette au lieu de se tenir.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-042', 'recipe_family', 'Tartiflette végétarienne',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-042', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Au tofu nature à la place du tofu fumé, un bloc de 400 g pour quatre, relevé à la sauce soja et à un verre de bouillon de légumes (marmiton.org)','Aux champignons parfumés séchés plutôt qu''au tofu, trois par personne, réhydratés puis taillés en morceaux (750g.com)','Aux tomates séchées, 320 g pour quatre, avec des oignons rouges caramélisés à 20 g de sucre de canne (marmiton.org)','À la courge butternut à la place des pommes de terre, avec une cuillerée à café de muscade — un autre plat sous le même nom (chefsimon.com)','Avec beaucoup plus de crème, jusqu''à 125 g par personne, pour un gratin franchement liquide (marmiton.org)','Montée en couches alternées comme des lasagnes plutôt qu''en deux étages, tout le mélange étant réparti entre les épaisseurs de pommes de terre (marmiton.org)','Les pommes de terre rissolées à la poêle au beurre et à l''huile au lieu d''être cuites à l''eau, puis terminées à couvert (750g.com)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-042","variants":["Au tofu nature à la place du tofu fumé, un bloc de 400 g pour quatre, relevé à la sauce soja et à un verre de bouillon de légumes (marmiton.org)","Aux champignons parfumés séchés plutôt qu''au tofu, trois par personne, réhydratés puis taillés en morceaux (750g.com)","Aux tomates séchées, 320 g pour quatre, avec des oignons rouges caramélisés à 20 g de sucre de canne (marmiton.org)","À la courge butternut à la place des pommes de terre, avec une cuillerée à café de muscade — un autre plat sous le même nom (chefsimon.com)","Avec beaucoup plus de crème, jusqu''à 125 g par personne, pour un gratin franchement liquide (marmiton.org)","Montée en couches alternées comme des lasagnes plutôt qu''en deux étages, tout le mélange étant réparti entre les épaisseurs de pommes de terre (marmiton.org)","Les pommes de terre rissolées à la poêle au beurre et à l''huile au lieu d''être cuites à l''eau, puis terminées à couvert (750g.com)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-042', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('65b610f3fcd3064fdc1f2a8e693653e8'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_delicate","scores":{"sweet":1,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["reblochon fondu","tofu fumé","oignon compoté","vin blanc réduit"],"aroma_families":["reblochon","fumé","oignon_compoté","vin_blanc_réduit"],"target_textures":["pommes_de_terre_fondantes","fromage_coulant","cubes de tofu dorés","dessus_doré"],"signature_ingredients":["Reblochon au lait cru","Pomme de terre crue, avec peau","Tofu fumé"],"identity_guardrails":["Le reblochon est fendu en deux dans l''épaisseur et posé croûte vers le haut, jamais râpé ni coupé en dés : c''est la croûte qui fait couvercle et qui dore.","Le tofu est FUMÉ et non nature : ce que le lardon apportait à ce gratin est d''abord la fumée, et la page qui emploie un tofu nature doit la rattraper à la sauce soja, ce qu''on n''écrit pas.","Les pommes de terre sont précuites tout juste tendres puis tranchées : cuites à cœur, elles se délitent en purée sous le fromage.","Aucun lardon et aucun bouillon animal : le seul mouillement est le vin blanc, et le plat est végétarien par ses formes autant que par son nom."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Parmentier de lentilles', 'parmentier de lentilles', 'France (Sud-Ouest)', 'France (Sud-Ouest)',
     'meal', 'gratin parmentier', 'domestic_standard', 'rich_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Parmentier de lentilles', 'Le parmentier de la lignée FR-037 où la lentille verte remplace le confit : même purée de pommes de terre au lait et au beurre, même oignon fondu, même croûte de comté.', ds.id, 'JUM-043',
    'Myko', 'editorial', 6, 30, 60, 'facile',
    NULL, NULL,
    'B', 'candidate', '98de1ea4be6d362f32aa83d4ee575896',
    '{"sweet":2,"salty":3,"acidic":0,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['lentille','oignon fondu','comté gratiné','beurre']::text[],
    ARRAY['lentille','oignon compoté','croûte grillée','muscade']::text[], ARRAY['lentilles fondantes mais entières','purée souple','croûte croustillante']::text[],
    ARRAY['Lentille verte sèche, crue','Pomme de terre crue, épluchée','Comté']::text[], ARRAY['Deux couches distinctes, lentilles dessous et purée dessus : mélangées, c''est une autre préparation.','Un tiers des lentilles est écrasé dans la sauteuse — c''est ce qui lie la couche du bas, là où la graisse du confit tenait toute seule.','La lentille est verte et cuite entière : la corail se défait d''elle-même et donnerait deux purées superposées.','Une croûte de comté franchement brune : un parmentier servi sans gratiner n''est pas fini.','Le féculent est la pomme de terre : les pages du dossier qui montent une patate douce ou un chou-fleur portent le nom sans être le plat.']::text[],
    ARRAY['cuisson des lentilles à l''eau non salée','fondue d''oignons','écrasement','purée au presse-purée','montage en couches','gratinage']::text[], ARRAY['Aux lentilles corail plutôt qu''aux vertes, 120 g pour trois, plus fondantes et qui se défont en purée (chefsimon.com)','Avec deux carottes fondues dans l''oignon, ce que font deux des trois pages structurelles — toutes deux de chefsimon — et que le parent ne fait pas (chefsimon.com)','En ragù de lentilles : tomates concassées, concentré, poireau, céleri, laurier et cumin sous la purée (chefsimon.com)','Purée enrichie de crème fraîche ou de fromage à tartiner en plus du lait, une cuillerée pour quatre (marmiton.org)','À la patate douce, entière ou pour moitié, à la place de la pomme de terre — un autre plat sous le même nom (chefsimon.com)','À la courge butternut mêlée à la purée, 800 g pour trois (chefsimon.com)','Un brin de romarin dans les lentilles pendant leur cuisson (chefsimon.com)','Aux lardons fumés revenus avec les échalotes avant les lentilles — c''est la version carnée du même montage, et c''est précisément ce que ce jumeau retire (marmiton.org)']::text[], ARRAY['lait']::text[],
    'Trois jours au réfrigérateur, couvert, et se réchauffe vingt-cinq minutes à 170 °C plutôt qu''au micro-ondes, qui détrempe la croûte de comté. Se congèle 2 mois, cru ou cuit, dans son plat filmé : décongeler une nuit au réfrigérateur avant de cuire ou de réchauffer. La lentille supporte le froid mieux que le confit du parent — elle a déjà rendu son eau à la cuisson et ne se dessèche pas au dégel —, et la purée montée au beurre et au lait se reprend à la fourchette. Le dossier ne dit rien de la conservation ; ces durées sont celles que le plat tient physiquement, et on le dit plutôt que de les attribuer aux sources.', '{"fridge_hours":72,"eat_immediately":false,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'FR-037'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
