  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Si le seitan vient d''un bocal, l''égoutter en gardant son jus de côté, puis l''éponger. Le détailler en morceaux de trois à quatre centimètres, de la taille des cubes de bœuf du plat d''origine : plus petits, ils se déferaient en filaments dans une heure de sauce.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire mousser le beurre dans une cocotte en fonte et colorer les morceaux par deux fournées, sur toutes leurs faces, trois ou quatre minutes chacune. Ne pas chercher davantage : le seitan n''a ni collagène à fondre ni jus à rendre, il ne gagne rien à rester dans la poêle et il y durcirait. Réserver dans un plat creux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Émincer les oignons et les laisser fondre vingt bonnes minutes dans la graisse de saisie, à feu modéré, jusqu''à ce qu''ils prennent une couleur blonde et se défassent. C''est le geste qui décide de tout, et davantage encore ici que chez le parent : la carbonade au bœuf tire son corps du gras et des sucs de la viande, celle-ci n''a que ses oignons pour lui en donner. Écourter cette étape donne une sauce maigre que rien ne rattrape ensuite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser la cassonade et le vinaigre sur les oignons, laisser caraméliser une poignée de secondes, puis mouiller avec la bière en raclant le fond à la spatule pour décoller tout ce qui a accroché. Aucune farine n''entre ici : ce sont le pain d''épices et la réduction qui lieront la sauce, et les quatre pages du dossier procèdent ainsi.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Remettre le seitan et le jus qu''il a rendu, saler, poivrer, glisser le thym et le laurier. Tartiner généreusement les tranches de pain d''épices de moutarde et les poser côté moutarde à la surface du liquide, sans les enfoncer : elles vont s''imbiber, se déliter d''elles-mêmes et épaissir la sauce en cours de cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Couvrir et tenir un frémissement paresseux quarante-cinq minutes à une heure, à très petit feu ou au four à 150 °C. C''est la seule vraie différence de conduite avec le plat de Julien, qui mijote deux heures trente : il n''y a ici aucune fibre à attendrir, et le seitan poussé au-delà d''une heure devient spongieux et rebondit sous la dent. La durée n''est plus au service de la viande, seulement de la sauce.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Découvrir, remuer pour faire disparaître complètement les morceaux de pain d''épices, et laisser réduire dix minutes si la sauce reste liquide. Goûter et rééquilibrer alors : une pointe de vinaigre si le sucre domine, une pointe de cassonade si l''amertume de la bière ressort trop. Cette sauce se règle en fin de cuisson, jamais au début.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Retirer le thym et le laurier et laisser reposer la cocotte hors du feu un quart d''heure avant de servir, avec des frites ou une purée. Comme la carbonade au bœuf, celle-ci est meilleure réchauffée le lendemain, quand la sauce a fini de prendre et que le seitan s''est imprégné de bière jusqu''au cœur.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-052', 'recipe_family', 'Carbonade flamande végétarienne',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-052', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['À la bière brune plutôt que blonde : trois pages sur quatre l''emploient (bokbier, bruin bier), la forme n''est pas au catalogue','Aux champignons de Paris, 250 g pour quatre, en quartiers ajoutés avec les oignons (dagelijksekost)','Carotte en petits dés et céleri branche revenus avec les oignons (dagelijksekost, duurzamekeuzes, cookpad)','Ail écrasé dans la compotée d''oignons (jumbo, dagelijksekost, duurzamekeuzes, et cookpad qui l''emploie sans le lister)','Liaison à la biscotte émiettée avec une cuillerée de ketchup et du sirop de sucre candi à la place de la cassonade (jumbo)','Tranche de pain bis tartinée de moutarde à la place du pain d''épices, posée face moutardée vers le bas (dagelijksekost, duurzamekeuzes)','Cannelle avec le sucre et réduction de quarante minutes seulement (cookpad)','Concentré de tomate revenu avec les aromates et mouillement au bouillon de légumes en complément de la bière (duurzamekeuzes)','Version aux pois chiches et aux champignons, sans seitan, relevée à la muscade et au clou de girofle : rédaction unique publiée sur deux sites, écartée du dossier à ce titre']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-052","variants":["À la bière brune plutôt que blonde : trois pages sur quatre l''emploient (bokbier, bruin bier), la forme n''est pas au catalogue","Aux champignons de Paris, 250 g pour quatre, en quartiers ajoutés avec les oignons (dagelijksekost)","Carotte en petits dés et céleri branche revenus avec les oignons (dagelijksekost, duurzamekeuzes, cookpad)","Ail écrasé dans la compotée d''oignons (jumbo, dagelijksekost, duurzamekeuzes, et cookpad qui l''emploie sans le lister)","Liaison à la biscotte émiettée avec une cuillerée de ketchup et du sirop de sucre candi à la place de la cassonade (jumbo)","Tranche de pain bis tartinée de moutarde à la place du pain d''épices, posée face moutardée vers le bas (dagelijksekost, duurzamekeuzes)","Cannelle avec le sucre et réduction de quarante minutes seulement (cookpad)","Concentré de tomate revenu avec les aromates et mouillement au bouillon de légumes en complément de la bière (duurzamekeuzes)","Version aux pois chiches et aux champignons, sans seitan, relevée à la muscade et au clou de girofle : rédaction unique publiée sur deux sites, écartée du dossier à ce titre"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-052', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('24e71744ad5ead73d11a1f54c5b2bc5a'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"rich_winey","scores":{"sweet":3,"salty":3,"acidic":2,"bitter":2,"umami":3,"heat":0,"pungency":2,"richness":3,"freshness":0,"intensity":4},"dominant_flavors":["bière réduite","oignon compoté","pain d''épices","moutarde"],"aroma_families":["oignon_compoté","épices chaudes","moutarde","caramel"],"target_textures":["morceaux fermes et élastiques","sauce nappante","oignons fondus"],"signature_ingredients":["Seitan","Bière blonde","Pain d''épices"],"identity_guardrails":["La compotée d''oignons est longue et blonde : c''est elle qui fait le corps de la sauce, davantage encore que dans la version au bœuf","Le pain d''épices moutardé se pose à plat sur le liquide et se délite tout seul — mélangé dès le départ, il fait un fond farineux au lieu de lier","La cuisson s''arrête à une heure : le seitan n''a rien à attendrir et devient spongieux si on le pousse comme on pousse le bœuf","Sucre et acidité se règlent à la fin, une fois la bière réduite, sinon on assaisonne un liquide qui n''a pas encore son goût"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Cassoulet végétarien', 'cassoulet vegetarien', 'France', 'France',
     'meal', 'plat mijoté', 'domestic_standard', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Cassoulet végétarien', 'Des haricots blancs mijotés à la tomate avec des saucisses végétales rissolées et des dés de tofu fumé, gratinés sous une croûte de chapelure — le jumeau végétarien du cassoulet.', ds.id, 'JUM-053',
    'Myko', 'editorial', 8, 30, 140, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'f6338405d59b2fb89f7483634ba4e92c',
    '{"sweet":1,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":0,"intensity":3}'::jsonb, ARRAY['haricot blanc','tomate cuite','fumé','ail']::text[],
    ARRAY['haricot','tomate_cuite','fumé','ail']::text[], ARRAY['haricot fondant à peau intacte','croûte de chapelure cassante','jus lié par l''amidon']::text[],
    ARRAY['Haricot blanc sec','Saucisse végétale au tofu','Tofu fumé']::text[], ARRAY['Les haricots sont secs, trempés la veille et cuits à part dans une eau non salée : en conserve, ils ne donnent pas le bouillon amidonné qui lie le plat','La croûte se forme et se crève plusieurs fois pendant la cuisson au four, puis se refait une dernière fois à la chapelure — c''est le geste qui fait un cassoulet et non un plat de haricots','La protéine est remplacée, pas retirée : sans saucisse végétale ni tofu fumé, c''est un plat de haricots aux légumes, ce que deux pages du dossier proposent et que ce jumeau écarte','Le fumé du tofu tient le rôle de la poitrine et du confit : sans lui, le plat perd la profondeur qui distingue un cassoulet d''un ragoût de haricots']::text[],
    ARRAY['trempage','mijotage','saisie','compotage','cuisson au four','gratinage','repos']::text[], ARRAY['Cassoulet aux légumes variés, sans protéine de remplacement : poireau, navet, pomme de terre, champignons de Paris et olives noires cuits avec les haricots (marmiton) ; aubergine, courgette, poivron et céleri branche (lacuisinedemamere) — deux des trois pages solides du dossier, écartées ici parce qu''elles retirent la protéine au lieu de la remplacer','Aux saucisses végétales au blé ou seitan plutôt qu''au tofu : le dossier ne dit jamais de quoi ses saucisses sont faites, et le classeur Ciqual mesure les deux séparément','Haricots blancs en conserve, égouttés et rincés, qui ramènent le plat à quarante minutes mais le privent de son bouillon de cuisson (Télé-Québec, vegourmet)','Croûte de panko mélangé à l''huile, finie sous le gril (Télé-Québec), ou chapelure relevée de paprika fumé (vegourmet)','Émincé végétal, 200 g pour quatre, ajouté aux saucisses (vegan-pratique)','Bouillon lié à la farine et déglacé au vin blanc, avec céleri branche et sarriette (Télé-Québec)','Cuisson en deux jours, comme le parent : une heure de four la veille, refroidissement complet, puis la croûte de chapelure au moment de servir']::text[], ARRAY['gluten','soja']::text[],
    'Se conserve 4 jours au réfrigérateur entre 0 et 4 °C, dans son plat couvert d''un film une fois refroidi, et il gagne au réchauffage lent à 150 °C avec une louche de bouillon chaud. Se congèle 3 mois, haricots et saucisses ensemble, mais la croûte de chapelure ne supporte pas le gel : la refaire au four après décongélation complète au réfrigérateur. Ce sont les durées du parent, aucune page du dossier ne parlant de conservation ; elles tiennent ici pour la même raison physique — un plat de légumineuses cuit longuement, salé et acidulé par la tomate, se garde bien, et le tofu fumé, salé lui aussi, ne raccourcit pas ce délai.', '{"fridge_hours":96,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-036'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'bouillon de legumes' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Bouillon de légumes', 1000, 'ml', 'required',
     'mouillement', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'haricot blanc sec' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Haricot blanc sec', 800, 'g', 'required',
     'légumineuse', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'saucisse vegetale au tofu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
