  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'La veille, noyer les haricots blancs secs sous trois fois leur volume d''eau froide et les laisser gonfler douze heures au frais. Le lendemain, jeter cette eau et les rincer : elle emporte une partie des sucres que l''intestin ne digère pas, et c''est la seule raison de la jeter.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Mettre les haricots égouttés dans une grande cocotte avec la carotte en tronçons, la moitié de l''oignon piquée des clous de girofle, le thym et le laurier. Couvrir d''eau froide sans saler, écumer aux premiers bouillons, puis tenir un frémissement paresseux cinquante minutes. On ne sale pas maintenant : le sel raffermit la peau et le grain met deux fois plus de temps à céder. Les haricots doivent rester entiers sous la dent, ils finiront de cuire au four.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pendant ce temps, chauffer la moitié de l''huile d''olive dans une large sauteuse et y rissoler les saucisses végétales entières, trois à quatre minutes en les roulant, jusqu''à ce qu''elles prennent couleur sur toute leur surface. Elles ne rendent pas de graisse comme la saucisse de Toulouse du plat de Julien : c''est l''huile qui fait le travail, et sans cette coloration elles resteraient pâles et molles au milieu des haricots. Les réserver et les couper en tronçons épais.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Dans la même sauteuse, faire tomber le reste de l''oignon émincé et les deux tiers de l''ail écrasé. Quand l''oignon devient translucide, ajouter le concentré et la tomate concassée, laisser compoter dix minutes en grattant les sucs, puis mouiller de deux louches de bouillon de légumes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Égoutter les haricots en gardant tout leur bouillon de cuisson, retirer l''oignon clouté, la carotte et le laurier. Les mélanger à la fondue de tomate avec les dés de tofu fumé, et saler seulement ici : les saucisses et le tofu fumé apportent déjà beaucoup de sel, et douze grammes pour huit parts suffisent. Poivrer généreusement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Frotter d''ail cru l''intérieur d''une cocotte en terre ou d''un plat creux allant au four, puis monter en couches : haricots, tronçons de saucisse, haricots encore, en terminant par une couche de haricots qui portera la croûte. Verser le bouillon de légumes et le bouillon de haricots jusqu''à effleurer la surface, sans noyer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Enfourner à 150 °C pour une heure, à découvert. Toutes les vingt minutes, crever du dos d''une cuillère la peau qui se forme en surface et rajouter une louche de bouillon chaud si le dessus s''assèche. Ce geste répété est ce qui donne au plat son liant : chaque croûte enfoncée relâche de l''amidon dans le jus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Poudrer toute la surface de chapelure, arroser du reste d''huile d''olive et monter le four à 170 °C pour trente minutes de plus, jusqu''à une croûte dorée et cassante. Sortir le plat et le laisser se détendre vingt minutes avant de servir à la louche, dans des assiettes chaudes : sorti brûlant, le cassoulet coule au lieu de se tenir.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-053', 'recipe_family', 'Cassoulet végétarien',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-053', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Cassoulet aux légumes variés, sans protéine de remplacement : poireau, navet, pomme de terre, champignons de Paris et olives noires cuits avec les haricots (marmiton) ; aubergine, courgette, poivron et céleri branche (lacuisinedemamere) — deux des trois pages solides du dossier, écartées ici parce qu''elles retirent la protéine au lieu de la remplacer','Aux saucisses végétales au blé ou seitan plutôt qu''au tofu : le dossier ne dit jamais de quoi ses saucisses sont faites, et le classeur Ciqual mesure les deux séparément','Haricots blancs en conserve, égouttés et rincés, qui ramènent le plat à quarante minutes mais le privent de son bouillon de cuisson (Télé-Québec, vegourmet)','Croûte de panko mélangé à l''huile, finie sous le gril (Télé-Québec), ou chapelure relevée de paprika fumé (vegourmet)','Émincé végétal, 200 g pour quatre, ajouté aux saucisses (vegan-pratique)','Bouillon lié à la farine et déglacé au vin blanc, avec céleri branche et sarriette (Télé-Québec)','Cuisson en deux jours, comme le parent : une heure de four la veille, refroidissement complet, puis la croûte de chapelure au moment de servir']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-053","variants":["Cassoulet aux légumes variés, sans protéine de remplacement : poireau, navet, pomme de terre, champignons de Paris et olives noires cuits avec les haricots (marmiton) ; aubergine, courgette, poivron et céleri branche (lacuisinedemamere) — deux des trois pages solides du dossier, écartées ici parce qu''elles retirent la protéine au lieu de la remplacer","Aux saucisses végétales au blé ou seitan plutôt qu''au tofu : le dossier ne dit jamais de quoi ses saucisses sont faites, et le classeur Ciqual mesure les deux séparément","Haricots blancs en conserve, égouttés et rincés, qui ramènent le plat à quarante minutes mais le privent de son bouillon de cuisson (Télé-Québec, vegourmet)","Croûte de panko mélangé à l''huile, finie sous le gril (Télé-Québec), ou chapelure relevée de paprika fumé (vegourmet)","Émincé végétal, 200 g pour quatre, ajouté aux saucisses (vegan-pratique)","Bouillon lié à la farine et déglacé au vin blanc, avec céleri branche et sarriette (Télé-Québec)","Cuisson en deux jours, comme le parent : une heure de four la veille, refroidissement complet, puis la croûte de chapelure au moment de servir"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-053', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('f6338405d59b2fb89f7483634ba4e92c'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":0,"intensity":3},"dominant_flavors":["haricot blanc","tomate cuite","fumé","ail"],"aroma_families":["haricot","tomate_cuite","fumé","ail"],"target_textures":["haricot fondant à peau intacte","croûte de chapelure cassante","jus lié par l''amidon"],"signature_ingredients":["Haricot blanc sec","Saucisse végétale au tofu","Tofu fumé"],"identity_guardrails":["Les haricots sont secs, trempés la veille et cuits à part dans une eau non salée : en conserve, ils ne donnent pas le bouillon amidonné qui lie le plat","La croûte se forme et se crève plusieurs fois pendant la cuisson au four, puis se refait une dernière fois à la chapelure — c''est le geste qui fait un cassoulet et non un plat de haricots","La protéine est remplacée, pas retirée : sans saucisse végétale ni tofu fumé, c''est un plat de haricots aux légumes, ce que deux pages du dossier proposent et que ce jumeau écarte","Le fumé du tofu tient le rôle de la poitrine et du confit : sans lui, le plat perd la profondeur qui distingue un cassoulet d''un ragoût de haricots"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Tofu teriyaki', 'tofu teriyaki', 'Japon', 'Japon',
     'meal', 'plat sauté', 'named_traditional_dish', 'spicy_umami',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Tofu teriyaki', 'Des tranches de tofu ferme saisies puis laquées dans une réduction de sauce soja, de saké et de sucre parfumée au gingembre — le jumeau végétarien du poulet teriyaki, même laque et même geste.', ds.id, 'JUM-054',
    'Myko', 'editorial', 4, 20, 15, 'facile',
    NULL, NULL,
    'B', 'candidate', 'aa443b815f6136032edea6c6f4017ae5',
    '{"sweet":3,"salty":4,"acidic":1,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":2,"freshness":1,"intensity":3}'::jsonb, ARRAY['soja réduit','sucre caramélisé','gingembre','tofu doré']::text[],
    ARRAY['soja_fermenté','gingembre','caramel','ail']::text[], ARRAY['croûte dorée','cœur ferme et lisse','sauce nappante']::text[],
    ARRAY['Tofu ferme','Sauce soja japonaise','Saké de cuisine']::text[], ARRAY['La sauce se réduit dans la poêle autour du tofu déjà saisi : versée crue sur un tofu blanc, elle le teinte sans jamais laquer','Le tofu est pressé avant d''être saisi, sinon il bout dans son eau et la laque ne prend pas','Trois ingrédients font la laque et pas un de plus — soja, saké, sucre — comme chez le parent ; y ajouter du miel, du jus d''orange ou du vinaigre en fait une autre sauce','On arrête la réduction au nappage : au-delà, le sucre passe en trente secondes du sirop au caramel amer']::text[],
    ARRAY['pressage','saisie','réduction','laquage','repos']::text[], ARRAY['Au mirin, deux à trois cuillerées à soupe avec la sauce soja (chefsimon, 750g) : forme absente du catalogue, remplacée ici comme chez le parent par le couple saké et sucre','Tofu fariné à la fécule avant la saisie, ou sauce liée à la fécule délayée dans un peu d''eau (chefsimon, healthyalie) : la fécule de maïs n''est pas employable au catalogue','Au four : tranches badigeonnées de sauce des deux côtés, 30 à 40 minutes à 200 °C en retournant à mi-cuisson (healthyalie)','Au tofu fumé plutôt que ferme, servi avec des poireaux crayons grillés (chefsimon) ou sur une purée de céleri (750g)','Sauce au jus d''orange, au miel et au vinaigre de riz, avec carottes et brocoli sautés dans la même poêle (chefsimon)','Finition à l''huile de sésame grillé et aux graines de sésame (750g, healthyalie)']::text[], ARRAY['soja','gluten']::text[],
    'Se garde 3 jours au réfrigérateur entre 0 et 4 °C dans une boîte fermée, la laque figée autour des morceaux. Réchauffer deux minutes à la poêle avec une cuillerée à soupe d''eau, qui redonne à la sauce sa fluidité ; le micro-ondes la fait suer et détrempe la croûte. Se mange aussi froid, tranché sur un riz vinaigré. NE SE CONGÈLE PAS : aucune page du dossier ne le dit, et c''est une déduction assumée sur ce que fait physiquement le tofu — l''eau qu''il retient gèle en cristaux qui percent le caillé, et il ressort du congélateur en éponge élastique, spongieuse et striée. Cette texture a ses amateurs, mais ce n''est plus le tofu lisse et ferme que la laque enrobe ici.', '{"fridge_hours":72,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'VAR-032'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
