  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Au mirin, deux à trois cuillerées à soupe avec la sauce soja (chefsimon, 750g) : forme absente du catalogue, remplacée ici comme chez le parent par le couple saké et sucre','Tofu fariné à la fécule avant la saisie, ou sauce liée à la fécule délayée dans un peu d''eau (chefsimon, healthyalie) : la fécule de maïs n''est pas employable au catalogue','Au four : tranches badigeonnées de sauce des deux côtés, 30 à 40 minutes à 200 °C en retournant à mi-cuisson (healthyalie)','Au tofu fumé plutôt que ferme, servi avec des poireaux crayons grillés (chefsimon) ou sur une purée de céleri (750g)','Sauce au jus d''orange, au miel et au vinaigre de riz, avec carottes et brocoli sautés dans la même poêle (chefsimon)','Finition à l''huile de sésame grillé et aux graines de sésame (750g, healthyalie)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-054","variants":["Au mirin, deux à trois cuillerées à soupe avec la sauce soja (chefsimon, 750g) : forme absente du catalogue, remplacée ici comme chez le parent par le couple saké et sucre","Tofu fariné à la fécule avant la saisie, ou sauce liée à la fécule délayée dans un peu d''eau (chefsimon, healthyalie) : la fécule de maïs n''est pas employable au catalogue","Au four : tranches badigeonnées de sauce des deux côtés, 30 à 40 minutes à 200 °C en retournant à mi-cuisson (healthyalie)","Au tofu fumé plutôt que ferme, servi avec des poireaux crayons grillés (chefsimon) ou sur une purée de céleri (750g)","Sauce au jus d''orange, au miel et au vinaigre de riz, avec carottes et brocoli sautés dans la même poêle (chefsimon)","Finition à l''huile de sésame grillé et aux graines de sésame (750g, healthyalie)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-054', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('aa443b815f6136032edea6c6f4017ae5'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"spicy_umami","scores":{"sweet":3,"salty":4,"acidic":1,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":2,"freshness":1,"intensity":3},"dominant_flavors":["soja réduit","sucre caramélisé","gingembre","tofu doré"],"aroma_families":["soja_fermenté","gingembre","caramel","ail"],"target_textures":["croûte dorée","cœur ferme et lisse","sauce nappante"],"signature_ingredients":["Tofu ferme","Sauce soja japonaise","Saké de cuisine"],"identity_guardrails":["La sauce se réduit dans la poêle autour du tofu déjà saisi : versée crue sur un tofu blanc, elle le teinte sans jamais laquer","Le tofu est pressé avant d''être saisi, sinon il bout dans son eau et la laque ne prend pas","Trois ingrédients font la laque et pas un de plus — soja, saké, sucre — comme chez le parent ; y ajouter du miel, du jus d''orange ou du vinaigre en fait une autre sauce","On arrête la réduction au nappage : au-delà, le sucre passe en trente secondes du sirop au caramel amer"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Wok de tofu aux légumes', 'wok de tofu aux legumes', 'France / cuisine domestique d''inspiration asiatique', 'France / cuisine domestique d''inspiration asiatique',
     'meal', 'plat sauté', 'domestic_standard', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Wok de tofu aux légumes', 'Des cubes de tofu dorés au wok, remis sur des légumes sautés dans l''ordre de leur fermeté et enrobés de sauce soja, finis à l''huile de sésame et à la coriandre — le jumeau végétarien du wok de poulet.', ds.id, 'JUM-055',
    'Myko', 'editorial', 4, 20, 15, 'facile',
    NULL, NULL,
    'B', 'candidate', 'b3ff785bf1bfa7bed7590956503c57b4',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":2,"richness":2,"freshness":3,"intensity":3}'::jsonb, ARRAY['soja','gingembre','sésame grillé','légumes croquants']::text[],
    ARRAY['soja_fermenté','gingembre','sésame_toasté','coriandre']::text[], ARRAY['cubes de tofu dorés','légumes croquants','enrobage brillant']::text[],
    ARRAY['Tofu ferme','Sauce soja','Huile de sésame grillé']::text[], ARRAY['Le tofu est doré à part et remis en fin de cuisson : sauté avec les légumes, il s''écrase et ne colore jamais','Les légumes entrent dans l''ordre de leur fermeté, carotte puis poivron puis courgette — c''est ce qui sépare un wok d''une poêlée','L''assaisonnement est la sauce soja seule : la sauce d''huître et la sauce poisson que deux pages emploient sortiraient le plat du végétarien','L''huile de sésame et la coriandre arrivent hors du feu, sinon le parfum grillé et l''herbe fraîche disparaissent']::text[],
    ARRAY['taillage','pressage','saisie vive','sauté','cuisson séquencée par tenue des légumes','finition à l''huile crue']::text[], ARRAY['Brocoli en fleurettes avec les carottes ou à la place de la courgette : quatre pages sur cinq en mettent (marmiton, chefsimon, mon-marché, prunay)','Graines de sésame grillées en finition (lapetitecuisinedenat, prunay, mon-marché) : la forme existe au catalogue, le parent ne la porte pas','Chou-fleur en petits bouquets, chou blanc ciselé et champignons noirs réhydratés quinze minutes (lapetitecuisinedenat)','Pois mange-tout ajoutés avec le poivron (prunay)','Servi sur riz complet thaï, avec un demi-jus de citron et des graines de courge (chefsimon)','Légumes cuits deux minutes à l''eau frémissante dans le wok avant l''ajout du tofu, jusqu''à absorption complète (marmiton)','Sauce d''huître (lapetitecuisinedenat) ou sauce poisson (chefsimon) à la place de la sauce soja : écartées ici, ce ne sont pas des formes végétariennes']::text[], ARRAY['soja','gluten','sésame']::text[],
    'Se garde 2 jours au réfrigérateur entre 0 et 4 °C, mais il faut le dire franchement : dès le lendemain les légumes ont rendu leur eau et le plat est devenu une poêlée tiède, bonne mais différente. Réchauffer à feu très vif et très court, deux minutes au maximum, jamais à couvert. Se congèle mal, et pour deux raisons qui s''ajoutent : la courgette rend beaucoup d''eau à la décongélation, comme le dit déjà le parent, et le tofu congelé se transforme en éponge élastique — c''est la seule différence de conservation entre ce jumeau et le plat de Julien. Aucune page du dossier ne parle de conservation ; ce paragraphe dit ce que ce type de plat fait physiquement.', '{"fridge_hours":48,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'DEN-015'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'tofu ferme' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Tofu ferme', 400, 'g', 'required',
     'protéine', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
