  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Égoutter le tofu, le presser un quart d''heure entre deux linges sous une assiette lestée, puis le tailler en cubes de deux centimètres et les rouler dans le sel, le poivre et le paprika. L''eau qu''il rend au pressage est celle qui, sinon, l''empêcherait de dorer : un cube humide jeté dans un wok brûlant relâche de la vapeur, et la vapeur interdit tout contact sec avec le métal.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Tailler tous les légumes avant d''allumer le feu, à épaisseur régulière : carottes en fines rondelles, courgette en demi-lunes, poivron en lanières. Un wok se conduit en cinq minutes montre en main et ne laisse aucun moment pour couper quoi que ce soit une fois la poêle chaude. Ciseler l''échalote, hacher l''ail, râper le gingembre et réunir ces trois-là dans un même bol : ils entreront ensemble.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chauffer l''huile d''arachide dans le wok jusqu''à ce qu''elle ondule, y coucher les cubes de tofu en une seule couche et les laisser prendre couleur deux minutes sans y toucher, puis les faire sauter jusqu''à ce que trois ou quatre faces soient dorées. Débarrasser dans une assiette. Remué trop tôt, le tofu laisse sa peau collée au fond et se défait en morceaux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Dans le wok resté brûlant, jeter les carottes seules et compter deux minutes, puis le poivron une minute, puis la courgette une minute. L''ordre suit la fermeté et c''est lui qui décide de tout : versés ensemble, la courgette rend son eau pendant que la carotte est encore crue, et l''on obtient une poêlée molle au lieu d''un sauté.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter l''échalote, l''ail et le gingembre et remuer trente secondes, juste le temps qu''ils libèrent leur parfum sans roussir — l''ail brûlé rendrait tout le plat amer et rien ne le rattraperait.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Remettre le tofu et son jus, verser la sauce soja sur les parois chaudes du wok plutôt qu''au centre, pour qu''elle se caramélise en descendant, et faire sauter une minute afin qu''elle enrobe tout. Couper le feu, ajouter l''huile de sésame et la coriandre ciselée, mélanger une dernière fois. L''huile de sésame se met toujours hors du feu : chauffée, elle perd en quelques secondes le parfum grillé qui justifie sa présence.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Servir immédiatement, sur du riz ou des nouilles préparés pendant la taille des légumes. Un wok couvert continue de cuire dans sa propre vapeur et perd son croquant en deux minutes : c''est le seul plat de ce corpus qu''on ne fait pas attendre.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-055', 'recipe_family', 'Wok de tofu aux légumes',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-055', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Brocoli en fleurettes avec les carottes ou à la place de la courgette : quatre pages sur cinq en mettent (marmiton, chefsimon, mon-marché, prunay)','Graines de sésame grillées en finition (lapetitecuisinedenat, prunay, mon-marché) : la forme existe au catalogue, le parent ne la porte pas','Chou-fleur en petits bouquets, chou blanc ciselé et champignons noirs réhydratés quinze minutes (lapetitecuisinedenat)','Pois mange-tout ajoutés avec le poivron (prunay)','Servi sur riz complet thaï, avec un demi-jus de citron et des graines de courge (chefsimon)','Légumes cuits deux minutes à l''eau frémissante dans le wok avant l''ajout du tofu, jusqu''à absorption complète (marmiton)','Sauce d''huître (lapetitecuisinedenat) ou sauce poisson (chefsimon) à la place de la sauce soja : écartées ici, ce ne sont pas des formes végétariennes']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-055","variants":["Brocoli en fleurettes avec les carottes ou à la place de la courgette : quatre pages sur cinq en mettent (marmiton, chefsimon, mon-marché, prunay)","Graines de sésame grillées en finition (lapetitecuisinedenat, prunay, mon-marché) : la forme existe au catalogue, le parent ne la porte pas","Chou-fleur en petits bouquets, chou blanc ciselé et champignons noirs réhydratés quinze minutes (lapetitecuisinedenat)","Pois mange-tout ajoutés avec le poivron (prunay)","Servi sur riz complet thaï, avec un demi-jus de citron et des graines de courge (chefsimon)","Légumes cuits deux minutes à l''eau frémissante dans le wok avant l''ajout du tofu, jusqu''à absorption complète (marmiton)","Sauce d''huître (lapetitecuisinedenat) ou sauce poisson (chefsimon) à la place de la sauce soja : écartées ici, ce ne sont pas des formes végétariennes"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-055', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('b3ff785bf1bfa7bed7590956503c57b4'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":2,"richness":2,"freshness":3,"intensity":3},"dominant_flavors":["soja","gingembre","sésame grillé","légumes croquants"],"aroma_families":["soja_fermenté","gingembre","sésame_toasté","coriandre"],"target_textures":["cubes de tofu dorés","légumes croquants","enrobage brillant"],"signature_ingredients":["Tofu ferme","Sauce soja","Huile de sésame grillé"],"identity_guardrails":["Le tofu est doré à part et remis en fin de cuisson : sauté avec les légumes, il s''écrase et ne colore jamais","Les légumes entrent dans l''ordre de leur fermeté, carotte puis poivron puis courgette — c''est ce qui sépare un wok d''une poêlée","L''assaisonnement est la sauce soja seule : la sauce d''huître et la sauce poisson que deux pages emploient sortiraient le plat du végétarien","L''huile de sésame et la coriandre arrivent hors du feu, sinon le parfum grillé et l''herbe fraîche disparaissent"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Paprikash de champignons', 'paprikash de champignons', 'Hongrie', 'Hongrie',
     'meal', 'champignons au paprika', 'named_traditional_dish', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Paprikash de champignons', 'Des champignons de Paris fondus avec des oignons blondis au paprika doux, liés hors du feu à la crème aigre et à la farine — le gombapaprikás hongrois, jumeau végétarien du chicken paprikash.', ds.id, 'JUM-061',
    'Myko', 'editorial', 6, 25, 40, 'facile',
    NULL, NULL,
    'B', 'candidate', '659b724cddc4c7ade9829b6ec82479b1',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":1,"pungency":2,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['champignon rôti','paprika doux','crème aigre','oignon fondu']::text[],
    ARRAY['champignon','paprika','lacté acidulé','oignon cuit']::text[], ARRAY['lamelles de champignon fermes','sauce nappante et satinée','oignon fondu jusqu''à disparaître']::text[],
    ARRAY['Champignon de Paris frais','Paprika doux hongrois','Crème aigre']::text[], ARRAY['Le paprika entre hors du feu : brûlé, il vire à l''amer et le plat est perdu','La sauce ne bout plus une fois la crème aigre incorporée, sinon elle graine','Les champignons sont saisis à part et à sec avant d''entrer dans la sauce, faute de quoi ils la délavent','Le mouillement est un bouillon de légumes : un bouillon de volaille ferait de ce jumeau une recette carnée sans que rien ne le montre']::text[],
    ARRAY['saisie à sec','fondue d''oignon','paprika ouvert hors du feu','mijotage à découvert','liaison à la crème aigre tempérée']::text[], ARRAY['Avec deux gousses d''ail écrasées ajoutées à l''oignon avant le paprika (sobors, deux pages du même site)','Avec une cuillerée à café de concentré de tomate travaillée dans le paprika, qui fonce la sauce et l''arrondit (mindmegette)','En mélange de champignons — bruns, blancs et pleurotes — pour la mâche, formes absentes du catalogue (sobors)','Les 400 g de penne cuits et mêlés au plat plutôt qu''un féculent servi à côté : c''est alors un plat de pâtes et non plus un paprikash (sobors)','Servi couvert de persil plat ciselé et d''une cuillerée de crème aigre supplémentaire (sobors)','Oignon fondu trente à quarante minutes en le mouillant d''un demi-décilitre d''eau à chaque reprise, ce qui donne une sauce nettement plus douce (kemenytojas)']::text[], ARRAY['lait','gluten']::text[],
    'Se garde 3 jours au réfrigérateur entre 0 et 4 °C, dans un récipient fermé, et se réchauffe doucement à la casserole sans jamais atteindre l''ébullition — la crème aigre, déjà cuite une fois, tranche encore plus facilement à la seconde chauffe. Aucune des quatre pages du dossier ne parle de conservation : ce qui suit est donc ce que ce type de plat fait physiquement, et on le dit. La congélation est déconseillée, pour deux raisons qui s''additionnent : une sauce liée à la crème aigre et à la farine se déphase à la décongélation et rend son eau, et le champignon, gorgé d''eau lui aussi, devient spongieux. Si l''on veut prendre de l''avance, congeler 2 mois à -18 °C la base d''oignon, de poivron et de champignons cuite jusqu''avant le mouillement, et lier à la crème aigre le jour du repas.', '{"fridge_hours":72,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'REAL-296'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'champignon de paris frais' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Champignon de Paris frais', 1200, 'g', 'required',
