  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Brosser les champignons sans les passer sous l''eau et les couper en lamelles épaisses de trois ou quatre millimètres. Épaisses, et non fines : elles vont perdre la moitié de leur volume et des lamelles trop minces finiraient en charpie dans la sauce, là où le parent gardait des morceaux de poulet qu''on retrouve à la fourchette.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Saisir les champignons en deux fois dans une grande poêle très chaude, sans matière grasse et sans les remuer pendant la première minute, jusqu''à ce que l''eau rendue se soit évaporée et que les tranches colorent. Les réserver. Cette étape est ce qui remplace le brunissement du poulet : jetés crus dans la sauce, les champignons y videraient leur eau et donneraient un plat clair et fade, alors qu''ici ils arrivent concentrés et déjà dorés.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Dans la cocotte, chauffer l''huile à feu moyen-doux et y faire fondre l''oignon émincé vingt bonnes minutes avec une pincée de sel, en ajoutant une cuillerée d''eau chaque fois qu''il commence à attacher. Il doit devenir translucide puis franchement blond, jamais brun. C''est le fondement du plat et le seul poste où l''on ne gagne pas de temps : un oignon pressé reste croquant et acide, et la sauce ne s''épaissira pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ajouter le poivron rouge en dés et le laisser fondre cinq minutes avec l''oignon, puis retirer la cocotte du feu et attendre une trentaine de secondes avant d''incorporer le paprika en remuant vivement. Le paprika est une poudre sucrée qui brûle vers 130 °C et devient alors amère au point de rendre le plat immangeable — c''est pourquoi il entre hors du feu, dans un gras encore chaud mais qui a cessé de monter.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Remettre sur le feu, verser le bouillon de légumes, rendre les champignons à la cocotte avec le jus qu''ils ont laissé, saler et poivrer, puis laisser mijoter à découvert une vingtaine de minutes. À découvert, parce que le liquide doit descendre de près d''un tiers : la crème arrivera dans une sauce déjà courte, sinon elle ne fera que la diluer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Pendant ce temps, fouetter la crème aigre avec la farine dans un bol jusqu''à ce qu''il ne reste aucun grumeau, puis y verser deux ou trois louches de jus brûlant en fouettant sans arrêt. Ce détrempage n''est pas une précaution de confort : la crème aigre est acide et tranche si on la jette froide dans un liquide bouillant, et la farine délayée à froid est la seule façon d''obtenir une liaison lisse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Couper le feu, verser la liaison dans la cocotte, remuer et remettre à chauffer deux ou trois minutes en dessous du frémissement, juste assez pour que la farine perde son goût cru et que la sauce nappe la cuillère. Elle ne doit plus jamais bouillir à partir d''ici, sous peine de grainer. Rectifier le sel et servir aussitôt avec des nokedli, du riz ou des pommes de terre à l''eau.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-061', 'recipe_family', 'Paprikash de champignons',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-061', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Avec deux gousses d''ail écrasées ajoutées à l''oignon avant le paprika (sobors, deux pages du même site)','Avec une cuillerée à café de concentré de tomate travaillée dans le paprika, qui fonce la sauce et l''arrondit (mindmegette)','En mélange de champignons — bruns, blancs et pleurotes — pour la mâche, formes absentes du catalogue (sobors)','Les 400 g de penne cuits et mêlés au plat plutôt qu''un féculent servi à côté : c''est alors un plat de pâtes et non plus un paprikash (sobors)','Servi couvert de persil plat ciselé et d''une cuillerée de crème aigre supplémentaire (sobors)','Oignon fondu trente à quarante minutes en le mouillant d''un demi-décilitre d''eau à chaque reprise, ce qui donne une sauce nettement plus douce (kemenytojas)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-061","variants":["Avec deux gousses d''ail écrasées ajoutées à l''oignon avant le paprika (sobors, deux pages du même site)","Avec une cuillerée à café de concentré de tomate travaillée dans le paprika, qui fonce la sauce et l''arrondit (mindmegette)","En mélange de champignons — bruns, blancs et pleurotes — pour la mâche, formes absentes du catalogue (sobors)","Les 400 g de penne cuits et mêlés au plat plutôt qu''un féculent servi à côté : c''est alors un plat de pâtes et non plus un paprikash (sobors)","Servi couvert de persil plat ciselé et d''une cuillerée de crème aigre supplémentaire (sobors)","Oignon fondu trente à quarante minutes en le mouillant d''un demi-décilitre d''eau à chaque reprise, ce qui donne une sauce nettement plus douce (kemenytojas)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-061', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('659b724cddc4c7ade9829b6ec82479b1'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":1,"pungency":2,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["champignon rôti","paprika doux","crème aigre","oignon fondu"],"aroma_families":["champignon","paprika","lacté acidulé","oignon cuit"],"target_textures":["lamelles de champignon fermes","sauce nappante et satinée","oignon fondu jusqu''à disparaître"],"signature_ingredients":["Champignon de Paris frais","Paprika doux hongrois","Crème aigre"],"identity_guardrails":["Le paprika entre hors du feu : brûlé, il vire à l''amer et le plat est perdu","La sauce ne bout plus une fois la crème aigre incorporée, sinon elle graine","Les champignons sont saisis à part et à sec avant d''entrer dans la sauce, faute de quoi ils la délavent","Le mouillement est un bouillon de légumes : un bouillon de volaille ferait de ce jumeau une recette carnée sans que rien ne le montre"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Yassa de tofu', 'yassa de tofu', 'Sénégal', 'Sénégal',
     'meal', 'tofu aux oignons citron', 'named_traditional_dish', 'bright_acidic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Yassa de tofu', 'Du tofu ferme mariné au citron et à la moutarde, saisi puis mijoté dans une compotée d''oignons au piment et au laurier — le yassa sénégalais dans sa version végétarienne.', ds.id, 'JUM-062',
    'Myko', 'editorial', 6, 25, 50, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '9e4f37485043923a69bb9b011d12461d',
    '{"sweet":3,"salty":3,"acidic":4,"bitter":1,"umami":2,"heat":2,"pungency":3,"richness":2,"freshness":3,"intensity":4}'::jsonb, ARRAY['oignon compoté','citron','moutarde','piment']::text[],
    ARRAY['agrume','oignon confit','moutarde','piment']::text[], ARRAY['cubes de tofu croûtés au-dehors et moelleux au-dedans','oignons fondus presque en marmelade','sauce courte et brillante']::text[],
    ARRAY['Oignon jaune cru','Tofu ferme','Jus de citron frais','Moutarde de Dijon']::text[], ARRAY['L''oignon est compoté longuement jusqu''à s''affaisser : sauté dix minutes, il reste croquant et le plat n''est plus un yassa','Le tofu est pressé puis saisi à part avant de retrouver la sauce, sinon il reste blanc et mou','L''acidité du citron doit rester franche à la sortie du feu, c''est elle qui identifie le plat','Le mouillement est un bouillon de légumes, jamais de volaille']::text[],
    ARRAY['marinade','compotage d''oignons','saisie','mijotage','réduction']::text[], ARRAY['Au citron vert plutôt qu''au citron jaune, un fruit entier pour une part (750g)','Avec une tomate fraîche en petits dés fondue avec les oignons, et de la coriandre en poudre ou fraîche au service (750g)','Avec un mélange d''épices yassa du commerce à la place de la moutarde — forme absente du catalogue (notparisienne)','Relevé aux flocons de piment rouge en plus du piment entier, et un tiers de scotch bonnet laissé dans la sauce (eatwithafia)','Tofu passé au gril ou à la poêle sans huile plutôt que frit, pour un plat plus sec (notparisienne)','Servi sur du quinoa au lieu du riz (750g)']::text[], ARRAY['soja','moutarde']::text[],
    'Se garde 3 jours au réfrigérateur entre 0 et 4 °C dans un récipient fermé, et gagne à être réchauffé doucement à la casserole plutôt qu''au micro-ondes : le tofu, qui a bu la sauce, la relâche quand il chauffe trop vite. Aucune des trois pages du dossier ne parle de conservation, et ce qui suit est donc ce que ce type de plat fait physiquement — on le dit plutôt que de le faire passer pour une donnée du dossier. Le plat se congèle 3 mois à -18 °C et le supporte mieux que son parent carné : la compotée d''oignons est une préparation stable, et le tofu, dont l''eau a été pressée avant cuisson, ressort seulement un peu plus ferme et plus spongieux, ce qui dans une sauce est un avantage. Décongeler une nuit au réfrigérateur et réchauffer à couvert avec une cuillerée d''eau.', '{"fridge_hours":72,"eat_immediately":false,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'REAL-154'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'oignon jaune cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Oignon jaune cru', 800, 'g', 'required',
     'base', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'tofu ferme' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Tofu ferme', 750, 'g', 'required',
     'protéine végétale', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'bouillon de legumes' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Bouillon de légumes', 150, 'ml', 'required',
     'mouillement', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
