  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Sortir le tofu de son emballage, l''envelopper dans un linge propre et le presser une demi-heure sous un poids — une casserole d''eau fait l''affaire. Le tofu ferme du commerce est vendu dans sa saumure et contient trop d''eau pour dorer ; pressé, il perd un bon dixième de son poids, se tient à la poêle et surtout laisse la place à la marinade, qu''il boira ensuite comme une éponge.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Fouetter le jus de citron avec la moutarde, l''ail écrasé, le sel et le poivre, puis en enrober les cubes de tofu de trois centimètres et laisser reposer au frais au moins trente minutes, deux heures si l''on a le temps. Verser le reste de la marinade sur les oignons émincés finement et laisser les deux au réfrigérateur côte à côte : dans le parent, cette même marinade travaille le poulet, ici elle a un rôle de plus, car le tofu n''a aucun goût propre et ne tirera que d''elle son acidité.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Dans une cocotte à fond épais, verser un tiers de l''huile et y mettre les oignons égouttés de leur marinade, à feu doux, à demi couverts. Les laisser compoter trente-cinq minutes en remuant de temps en temps : ils doivent s''affaisser, blondir et devenir sirupeux, sans brunir. Si de la buée s''accumule et qu''ils cuisent à la vapeur au lieu de dorer, décaler le couvercle pour laisser l''eau partir. C''est cette compotée qui est le plat ; tout le reste s''y ajoute.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Pendant que les oignons fondent, égoutter les cubes de tofu en gardant la marinade, et les colorer dans le reste de l''huile bien chaude, sur une seule couche, en les retournant face après face jusqu''à ce qu''ils soient dorés et croûtés. Ne pas surcharger la poêle : entassés, ils se mettent à bouillir dans leur propre eau et restent blancs. Cette croûte est ce qui remplace la peau grillée du poulet du parent — elle donne au tofu une surface qui accroche la sauce.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser la marinade réservée sur les oignons compotés, ajouter le bouillon de légumes, les feuilles de laurier et le piment fendu, et laisser reprendre à petits bouillons cinq minutes. La moutarde et le citron doivent cuire un peu à ce moment-là : crus dans la sauce finale, ils gardent une pointe agressive que la cuisson arrondit sans la faire disparaître.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Rendre les cubes de tofu à la cocotte, mélanger délicatement pour les enrober, couvrir à demi et laisser mijoter un quart d''heure à feu doux. C''est le temps qu''il faut au tofu pour absorber la sauce jusqu''au cœur ; agité brutalement, il s''effrite, alors on remue à la spatule et rarement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Retirer le piment et le laurier, goûter, rectifier en sel et en citron, et servir sur du riz blanc. Le piment sort maintenant parce qu''il continuerait à céder son feu dans les restes du lendemain, et un yassa doit être relevé, pas brûlant.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-062', 'recipe_family', 'Yassa de tofu',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-062', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Au citron vert plutôt qu''au citron jaune, un fruit entier pour une part (750g)','Avec une tomate fraîche en petits dés fondue avec les oignons, et de la coriandre en poudre ou fraîche au service (750g)','Avec un mélange d''épices yassa du commerce à la place de la moutarde — forme absente du catalogue (notparisienne)','Relevé aux flocons de piment rouge en plus du piment entier, et un tiers de scotch bonnet laissé dans la sauce (eatwithafia)','Tofu passé au gril ou à la poêle sans huile plutôt que frit, pour un plat plus sec (notparisienne)','Servi sur du quinoa au lieu du riz (750g)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-062","variants":["Au citron vert plutôt qu''au citron jaune, un fruit entier pour une part (750g)","Avec une tomate fraîche en petits dés fondue avec les oignons, et de la coriandre en poudre ou fraîche au service (750g)","Avec un mélange d''épices yassa du commerce à la place de la moutarde — forme absente du catalogue (notparisienne)","Relevé aux flocons de piment rouge en plus du piment entier, et un tiers de scotch bonnet laissé dans la sauce (eatwithafia)","Tofu passé au gril ou à la poêle sans huile plutôt que frit, pour un plat plus sec (notparisienne)","Servi sur du quinoa au lieu du riz (750g)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-062', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('9e4f37485043923a69bb9b011d12461d'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"bright_acidic","scores":{"sweet":3,"salty":3,"acidic":4,"bitter":1,"umami":2,"heat":2,"pungency":3,"richness":2,"freshness":3,"intensity":4},"dominant_flavors":["oignon compoté","citron","moutarde","piment"],"aroma_families":["agrume","oignon confit","moutarde","piment"],"target_textures":["cubes de tofu croûtés au-dehors et moelleux au-dedans","oignons fondus presque en marmelade","sauce courte et brillante"],"signature_ingredients":["Oignon jaune cru","Tofu ferme","Jus de citron frais","Moutarde de Dijon"],"identity_guardrails":["L''oignon est compoté longuement jusqu''à s''affaisser : sauté dix minutes, il reste croquant et le plat n''est plus un yassa","Le tofu est pressé puis saisi à part avant de retrouver la sauce, sinon il reste blanc et mou","L''acidité du citron doit rester franche à la sortie du feu, c''est elle qui identifie le plat","Le mouillement est un bouillon de légumes, jamais de volaille"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Adobo de tofu', 'adobo de tofu', 'Philippines', 'Philippines',
     'meal', 'tofu braisé vinaigré', 'named_traditional_dish', 'fermented_pungent',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Adobo de tofu', 'Des cubes de tofu dorés puis braisés dans un mélange de vinaigre, de sauce soja, d''ail et de laurier réduit jusqu''à napper — l''adobong tokwa philippin, jumeau végétarien du chicken adobo.', ds.id, 'JUM-063',
    'Myko', 'editorial', 6, 20, 35, 'facile',
    NULL, NULL,
    'B', 'candidate', 'a4e9c5b0f463fb04ff444fea6efb6104',
    '{"sweet":2,"salty":4,"acidic":4,"bitter":1,"umami":4,"heat":1,"pungency":4,"richness":2,"freshness":1,"intensity":4}'::jsonb, ARRAY['vinaigre','sauce soja','ail','laurier']::text[],
    ARRAY['vinaigre','soja fermenté','ail grillé','laurier']::text[], ARRAY['cubes de tofu croûtés et gorgés de sauce','sauce courte et sirupeuse','grains de poivre entiers sous la dent']::text[],
    ARRAY['Tofu ferme','Vinaigre blanc','Sauce soja','Ail cru']::text[], ARRAY['Le vinaigre bout deux minutes sans être remué avant tout autre liquide : c''est ce qui fait la rondeur de l''adobo','Le poivre reste en grains entiers, jamais moulu','La sauce doit réduire jusqu''à napper : un adobo noyé n''est plus un adobo','Le tofu est pressé puis doré avant d''entrer dans la sauce, sinon il reste mou et ne prend rien']::text[],
    ARRAY['pressage du tofu','saisie','évaporation du vinaigre','braisage','réduction']::text[], ARRAY['Avec deux pommes de terre rôties au four coupées en demi-lunes, mêlées à la sauce en fin de cuisson (bestofvegan)','Tofu cuit au four ou à l''air chaud vingt-cinq minutes au lieu d''être frit, pour un plat sans friture (healthmylifestyle)','Sauce liée d''une cuillerée de fécule de maïs délayée à l''eau froide et bouillie une minute (healthmylifestyle, ricelifefoodie)','Avec une demi-cuillerée de gingembre frais râpé sauté avec l''ail (ricelifefoodie)','Une cuillerée à café de sauce soja foncée en plus, pour la couleur et le sucré (thefoodietakesflight)','Servi sur du sinangag, le riz frit à l''ail philippin, plutôt que sur du riz nature (thefoodietakesflight)']::text[], ARRAY['soja','gluten']::text[],
    'Se garde 4 jours au réfrigérateur entre 0 et 4 °C dans un récipient fermé, et c''est même un plat qui s''améliore d''un jour sur l''autre : le tofu continue d''absorber la sauce et le vinaigre et le soja, tous deux conservateurs, retardent l''altération — c''est d''ailleurs l''origine du plat, une méthode de conservation avant d''être une recette. Aucune des quatre pages ne chiffre de durée, seulement le fait que le goût gagne au repos ; les 4 jours sont donc notre lecture de ce que fait ce type de plat, et on le dit. Il se congèle 3 mois à -18 °C : la sauce est une réduction sans laitage ni liaison qui ne se déphase pas, et le tofu ressort plus ferme et plus spongieux qu''avant, ce qui dans une sauce nappante est un gain plutôt qu''un défaut. Décongeler une nuit au froid et réchauffer à couvert.', '{"fridge_hours":96,"eat_immediately":false,"freezable":true,"freezer_months":3,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'REAL-259'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'tofu ferme' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Tofu ferme', 800, 'g', 'required',
     'protéine végétale', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
