      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir en grains', 5, 'g', 'required',
     'épice', false, 9);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'feuille de laurier sechee' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Feuille de laurier séchée', 6, 'u', 'required',
     'aromate', false, 10);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Égoutter le tofu, l''envelopper dans un linge et le presser une demi-heure sous une charge, puis le tailler en cubes de trois centimètres. Un tofu gorgé d''eau ne colore pas : il se met à bouillir dans sa propre humidité dès qu''il touche l''huile, et l''adobo a besoin d''une surface dorée pour que la sauce accroche, exactement comme le parent a besoin d''une peau saisie.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Chauffer l''huile dans une sauteuse large et y colorer les cubes de tofu en deux fournées, sur une seule couche, en les retournant sur chaque face jusqu''à ce qu''ils soient dorés et fermes. Les réserver sur du papier absorbant. Deux fournées et pas une seule : entassés, ils se collent, refroidissent l''huile et restent blafards.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Dans la même sauteuse, en ne gardant qu''un fond d''huile, faire tomber l''oignon rouge émincé et l''ail écrasé à feu moyen pendant quatre minutes, puis ajouter les grains de poivre et les remuer une minute. Le poivre entier est grillé à ce moment-là et pas plus tard : la chaleur sèche fait éclater ses huiles, ce qu''un liquide déjà versé empêcherait.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser le vinaigre et le laisser bouillir deux minutes sans y toucher, avant d''ajouter la sauce soja, le bouillon de légumes, le sucre et les feuilles de laurier. Ce temps d''attente est repris du parent, dont l''étape dit d''ajouter le vinaigre sans remuer immédiatement, et il a une raison : l''acide acétique le plus volatil part avec la vapeur, et la sauce passe d''un goût de vinaigre cru à une acidité ronde. Les quatre pages du dossier, elles, mélangent tout de suite ; on suit ici la base plutôt que le dossier, et on le dit dans l''arbitrage.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Laisser frémir la sauce cinq minutes à découvert, goûter et corriger l''équilibre — plus de soja si elle manque de sel, plus de vinaigre si elle est plate, une pointe de sucre si elle est agressive. Ce réglage se fait maintenant, avant que le tofu n''ait bu la sauce : après, tout ce qu''on ajoute reste en surface.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Rendre les cubes de tofu à la sauteuse, les enrober et laisser mijoter à feu doux une douzaine de minutes en les retournant à mi-parcours, jusqu''à ce que la sauce ait réduit de moitié et nappe le dos d''une cuillère. Le tofu se comporte ici comme une éponge : plus il reste dans la sauce, plus il en prend, et c''est ce transfert qui remplace la chair de poulet imprégnée du parent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Couper le feu, retirer les feuilles de laurier et laisser reposer cinq minutes avant de servir sur du riz blanc chaud. Ce repos laisse la sauce épaissir encore un peu et le tofu finir d''absorber ; servi tout de suite, le plat est plus liquide et le riz s''y noie.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-063', 'recipe_family', 'Adobo de tofu',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-063', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Avec deux pommes de terre rôties au four coupées en demi-lunes, mêlées à la sauce en fin de cuisson (bestofvegan)','Tofu cuit au four ou à l''air chaud vingt-cinq minutes au lieu d''être frit, pour un plat sans friture (healthmylifestyle)','Sauce liée d''une cuillerée de fécule de maïs délayée à l''eau froide et bouillie une minute (healthmylifestyle, ricelifefoodie)','Avec une demi-cuillerée de gingembre frais râpé sauté avec l''ail (ricelifefoodie)','Une cuillerée à café de sauce soja foncée en plus, pour la couleur et le sucré (thefoodietakesflight)','Servi sur du sinangag, le riz frit à l''ail philippin, plutôt que sur du riz nature (thefoodietakesflight)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-063","variants":["Avec deux pommes de terre rôties au four coupées en demi-lunes, mêlées à la sauce en fin de cuisson (bestofvegan)","Tofu cuit au four ou à l''air chaud vingt-cinq minutes au lieu d''être frit, pour un plat sans friture (healthmylifestyle)","Sauce liée d''une cuillerée de fécule de maïs délayée à l''eau froide et bouillie une minute (healthmylifestyle, ricelifefoodie)","Avec une demi-cuillerée de gingembre frais râpé sauté avec l''ail (ricelifefoodie)","Une cuillerée à café de sauce soja foncée en plus, pour la couleur et le sucré (thefoodietakesflight)","Servi sur du sinangag, le riz frit à l''ail philippin, plutôt que sur du riz nature (thefoodietakesflight)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-063', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('a4e9c5b0f463fb04ff444fea6efb6104'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"fermented_pungent","scores":{"sweet":2,"salty":4,"acidic":4,"bitter":1,"umami":4,"heat":1,"pungency":4,"richness":2,"freshness":1,"intensity":4},"dominant_flavors":["vinaigre","sauce soja","ail","laurier"],"aroma_families":["vinaigre","soja fermenté","ail grillé","laurier"],"target_textures":["cubes de tofu croûtés et gorgés de sauce","sauce courte et sirupeuse","grains de poivre entiers sous la dent"],"signature_ingredients":["Tofu ferme","Vinaigre blanc","Sauce soja","Ail cru"],"identity_guardrails":["Le vinaigre bout deux minutes sans être remué avant tout autre liquide : c''est ce qui fait la rondeur de l''adobo","Le poivre reste en grains entiers, jamais moulu","La sauce doit réduire jusqu''à napper : un adobo noyé n''est plus un adobo","Le tofu est pressé puis doré avant d''entrer dans la sauce, sinon il reste mou et ne prend rien"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Carbonara végétarienne aux courgettes', 'carbonara vegetarienne aux courgettes', 'France / cuisine domestique internationale', 'France / cuisine domestique internationale',
     'meal', 'pâtes', 'named_traditional_dish', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Carbonara végétarienne aux courgettes', 'Des spaghettis liés hors du feu à une crème de jaunes d''œufs et de pecorino, où des bâtonnets de courgette dorés à l''huile prennent la place du guanciale — la carbonara di zucchine italienne.', ds.id, 'JUM-064',
    'Myko', 'editorial', 4, 15, 15, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'd0e72683b3b2943375da95605bff9ec8',
    '{"sweet":2,"salty":4,"acidic":1,"bitter":1,"umami":4,"heat":0,"pungency":3,"richness":4,"freshness":2,"intensity":4}'::jsonb, ARRAY['pecorino','jaune d''œuf','poivre noir','courgette dorée']::text[],
    ARRAY['fromage de brebis','œuf','poivre','végétal grillé']::text[], ARRAY['pâtes al dente nappées','crème lisse et brillante','bâtonnets de courgette fermes au cœur']::text[],
    ARRAY['Spaghetti secs','Courgette fraîche','Pecorino romano','Jaune d''œuf cru']::text[], ARRAY['La crème est montée à l''eau de cuisson et versée hors du feu : chauffée, elle devient une omelette','La courgette est taillée en bâtonnets et dorée, jamais râpée ni réduite en purée — elle tient le rôle du guanciale','Ni crème fraîche ni beurre : la liaison ne vient que des jaunes, du fromage et de l''eau de cuisson','Le poivre est écrasé au dernier moment et présent en quantité, c''est un ingrédient et non un assaisonnement']::text[],
    ARRAY['taille en bâtonnets','coloration à feu vif','cuisson al dente','crème d''œufs montée à l''eau de cuisson','liaison hors du feu']::text[], ARRAY['Avec une gousse d''ail écrasée mise à chauffer dans l''huile avant les courgettes et retirée ensuite (tavolartegusto, ilcuoreinpentola)','Avec quelques feuilles de menthe fraîche ciselées sur les courgettes, usage génois (ilcuoreinpentola)','Aux mezze maniche, rigatoni ou bucatini plutôt qu''aux spaghettis, le format court étant l''usage romain (blog.giallozafferano, tavolartegusto, petitchef)','Courgettes cuites trois minutes seulement, croquantes et à peine colorées (tavolartegusto)','Aux jaunes seuls, sans œuf entier, pour une crème plus jaune et plus grasse (tavolartegusto, blog.giallozafferano)','Au parmesan à la place du pecorino, pour un plat moins salé (petitchef)']::text[], ARRAY['gluten','œuf','lait']::text[],
    'Ne se garde pas : cette recette se mange dans les minutes qui suivent la liaison, comme son parent, dont la fiche dit déjà « à consommer immédiatement ». Aucune des six pages ne propose de conservation et ce qui suit est la physique du plat. Une crème de jaunes et de pecorino tenue par la seule température des pâtes se casse en refroidissant, l''amidon des spaghettis rétrograde et la sauce redevient granuleuse ; réchauffée, elle coagule franchement. Si un reste doit être gardé, il tient 24 heures au réfrigérateur à 4 °C mais ne retrouvera pas sa texture. La congélation est exclue, et pour deux raisons plutôt qu''une : l''œuf lié se déphase au dégel et la courgette, gorgée d''eau, se défait complètement.', '{"fridge_hours":24,"eat_immediately":true,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'IT-003'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
