  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 8, 'g', 'required',
     'assaisonnement', false, 11);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre blanc moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre blanc moulu', 2, 'g', 'required',
     'épice', false, 12);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Verser l''eau tiède en filet sur la farine en mélangeant à la baguette ou à la fourchette, puis pétrir dix minutes jusqu''à obtenir une boule souple qui ne colle plus aux doigts. Couvrir d''un linge humide et laisser reposer une heure. Ce repos n''est pas facultatif : le gluten détendu permet d''étaler des disques très fins qui ne se rétractent pas, et une pâte travaillée aussitôt refuse de s''étaler et se déchire au pliage.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Émincer le chou chinois très finement, le saler de deux grammes et le laisser dégorger vingt minutes, puis le presser à pleines mains dans un linge pour en extraire l''eau. C''est le geste qui décide de la réussite : un chou non essoré relâche son eau dans la farce, celle-ci détrempe la pâte par l''intérieur et les raviolis crèvent à la cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Hacher les champignons au couteau en petits dés et les faire sauter cinq à six minutes à feu vif dans la moitié de l''huile, sans sel, jusqu''à ce que toute l''eau rendue se soit évaporée et qu''ils commencent à colorer. Les laisser refroidir. Ils remplacent le porc et doivent donc arriver concentrés : crus, ils ne pèseraient rien en goût et rendraient leur eau dans le ravioli.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Battre les œufs, les brouiller à feu doux dans un filet d''huile jusqu''à ce qu''ils forment de petits caillots secs, et les hacher grossièrement. Les deux pages du dossier qui portent l''œuf le versent cru dans la farce ; le brouiller d''abord est notre choix et il tient à la texture : cru, il lie la farce en un appareil compact, tandis que les caillots cuits restent visibles et gardent leur mâche entre le chou et les champignons.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Réunir dans un saladier le chou pressé, les champignons refroidis, l''œuf, la ciboulette chinoise ciselée et le gingembre râpé, puis assaisonner de sauce soja, d''huile de sésame, du sel restant et du poivre blanc. Mélanger longuement toujours dans le même sens, deux bonnes minutes. Ce brassage directionnel est celui du parent : il rend la farce cohésive et elle se tient alors à la cuillère au lieu de s''éparpiller sur le disque.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Rouler la pâte en boudins de deux centimètres, les trancher en une quarantaine de tronçons, écraser chacun sous la paume et l''étaler au rouleau en disque de huit centimètres, plus épais au centre qu''au bord. Cette différence d''épaisseur a une fonction : le fond, qui porte la farce, ne doit pas percer, et les bords, plus minces, se soudent sans faire un bourrelet de pâte crue.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Déposer une bonne cuillerée à café de farce au milieu d''un disque, humecter la moitié du bord, replier et sceller en pinçant fermement, en formant trois ou quatre plis d''un seul côté. Chasser l''air en pressant du centre vers l''extérieur avant de fermer : une poche d''air se dilate à la chaleur et fait éclater le ravioli. Poser les pièces au fur et à mesure sur un plateau fariné, sans qu''elles se touchent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Cuire au choix. Pochés : les jeter dans une grande casserole d''eau bouillante, remuer doucement pour décoller le fond, puis les retirer une minute après qu''ils se sont mis à flotter, lorsque leur enveloppe a viré au translucide et laisse deviner la farce. Poêlés : les ranger dans une poêle antiadhésive avec un peu d''huile, les laisser brunir deux minutes, verser un demi-verre d''eau, couvrir aussitôt et attendre que toute l''eau soit partie — la vapeur cuit la farce pendant que le dessous se croustille.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-065', 'recipe_family', 'Jiaozi végétariens au chou et aux champignons',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-065', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Avec une carotte râpée sautée avec les champignons, pour la douceur et la couleur (thewoksoflife, carolinescooking, biancazapatka, redhousespice)','Avec un oignon en dés fondu avant les champignons (thewoksoflife, biancazapatka)','Farce parfumée d''une cuillerée de vin de Shaoxing et d''une pincée de sucre — forme absente du catalogue (thewoksoflife, carolinescooking)','Pâte en deux couleurs, une part teintée au jus d''épinard et enroulée autour de la pâte blanche (redhousespice)','Farce aux vermicelles de haricot mungo réhydratés et coupés court, qui absorbent l''eau du chou — forme absente du catalogue (redhousespice)','Farce aux pousses de bambou, germes de soja, poireau et champignons noirs déshydratés (marmiton)','Poivre du Sichuan moulu à la place du poivre blanc (redhousespice)','Servis avec une sauce à tremper au vinaigre noir, soja, sirop d''agave et graines de sésame (biancazapatka)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-065","variants":["Avec une carotte râpée sautée avec les champignons, pour la douceur et la couleur (thewoksoflife, carolinescooking, biancazapatka, redhousespice)","Avec un oignon en dés fondu avant les champignons (thewoksoflife, biancazapatka)","Farce parfumée d''une cuillerée de vin de Shaoxing et d''une pincée de sucre — forme absente du catalogue (thewoksoflife, carolinescooking)","Pâte en deux couleurs, une part teintée au jus d''épinard et enroulée autour de la pâte blanche (redhousespice)","Farce aux vermicelles de haricot mungo réhydratés et coupés court, qui absorbent l''eau du chou — forme absente du catalogue (redhousespice)","Farce aux pousses de bambou, germes de soja, poireau et champignons noirs déshydratés (marmiton)","Poivre du Sichuan moulu à la place du poivre blanc (redhousespice)","Servis avec une sauce à tremper au vinaigre noir, soja, sirop d''agave et graines de sésame (biancazapatka)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-065', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('88025906bcfe636806a2ccc17ae89a6b'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":2,"salty":3,"acidic":1,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":2,"freshness":2,"intensity":3},"dominant_flavors":["chou chinois","champignon","ciboulette chinoise","sésame grillé"],"aroma_families":["sésame","gingembre","ail des jiucai","champignon"],"target_textures":["pâte souple et translucide","fond croustillant si poêlés","farce moelleuse et non compacte"],"signature_ingredients":["Farine de blé T55","Chou chinois frais","Champignon de Paris frais","Ciboulette chinoise fraîche"],"identity_guardrails":["Le chou est salé, dégorgé puis pressé : sans cela la farce mouille la pâte et les raviolis crèvent","Les champignons sont sautés jusqu''à évaporation complète avant d''entrer dans la farce","La farce est brassée toujours dans le même sens jusqu''à devenir cohésive, comme la farce de porc du parent","Le disque reste plus épais au centre qu''au bord, sinon il perce sous la farce","Aucune sauce d''huître au service : c''est un extrait de fruit de mer, et il ferait sortir la recette du végétarien"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Minestrone végétarien', 'minestrone vegetarien', 'Italie', 'Italie',
     'meal', 'soupe complète', 'named_traditional_dish', 'brothy_umami',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Minestrone végétarien', 'Soupe de sept légumes mouillée au bouillon de légumes, portant ses haricots blancs et ses petites pâtes dans le même bol — le jumeau végétarien du minestrone, dont seul le bouillon rendait la lignée carnée.', ds.id, 'JUM-071',
    'Myko', 'editorial', 8, 30, 50, 'facile',
    NULL, NULL,
    'B', 'candidate', 'f1e42a5158c41b30c9f015689fb9285e',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":2,"heat":0,"pungency":1,"richness":2,"freshness":3,"intensity":3}'::jsonb, ARRAY['bouillon de légumes','tomate','haricot blanc','basilic']::text[],
    ARRAY['bouillon','tomate_cuite','oignon_compoté','basilic','céleri']::text[], ARRAY['légumes_tendres_distincts','bouillon_lié','pâtes_fermes']::text[],
    ARRAY['Haricot blanc cuit, égoutté','Petites pâtes sèches','Tomate fraîche mûre','Bouillon de légumes']::text[], ARRAY['Le bouillon est de légumes et rien d''autre : c''est la seule ligne qui séparait ce plat de son parent, et un cube de volaille le ramènerait dans la lignée carnée sans que rien ne le montre','Aucune salaison, pas même en option — le parent laissait le lardon facultatif, et c''est précisément ce genre d''option qui fait classer un plat végétarien à tort','Un minestrone porte à la fois une légumineuse et un féculent en grain, haricot blanc et petites pâtes : sans eux il n''est plus qu''une soupe de légumes, et ici le haricot est la seule protéine du bol','Les légumes restent en dés distincts sous la cuillère : mixé, le plat devient un velouté et perd la définition qui fait son nom','Les pâtes cuisent dans le bouillon et non à part, leur amidon étant le seul liant de la soupe']::text[],
    ARRAY['suer','cuisson séquencée par tenue des légumes','cuisson des pâtes dans le bouillon','finition à l''huile crue']::text[], ARRAY['Pesto de persil monté à l''huile et servi à part, à la place du basilic déchiré (chefsimon)','Version croquante : haricots verts, petits pois, radis et jeunes asperges à peine pochés dans le bouillon, avec des spaghettis cassés (chefsimon)','Fenouil et tomates cerises coupées en deux à la place de la tomate mûre, deux brins de menthe et des flocons de piment en finition (biendecheznous)','Trois cent cinquante grammes de macaronis pour quatre, soit près de trois fois le féculent retenu ici (menu-vegetarien) — écarté parce que la soupe devient alors un plat de pâtes en bouillon','Haricots borlotti frais à la place du haricot blanc, avec des blettes et une croûte de parmesan fondue dans le bouillon (mangioquindisono, salepepe)','Navets ronds et navets boule d''or avec les légumes durs (chefsimon, salepepe)','Origan séché et persil haché ajoutés avec le basilic (menu-vegetarien)','Poireau émincé dans la base aromatique (salepepe, et le parent le porte déjà en variante)']::text[], ARRAY['gluten','céleri','lait']::text[],
    'Se garde 4 jours au réfrigérateur dans un récipient fermé, et la soupe est meilleure le lendemain, le temps que le bouillon prenne le goût des légumes. Une réserve, et c''est la même que chez le parent : les pâtes continuent de boire au froid et le minestrone se resserre en plat épais — rallonger d''un demi-litre de bouillon au réchauffage, ou mieux, cuire les pâtes à la portion et garder le reste de la soupe sans elles. Se congèle 3 mois à -18 °C, mais sans les pâtes ni la pomme de terre, qui se délitent au dégel ; la base congelée sans elles ne perd rien. Aucune page du dossier ne parle de conservation : ce qui est écrit ici décrit ce que fait physiquement une soupe de légumes portant un féculent en grain, et l''échange du bouillon n''y change rien.', '{"fridge_hours":96,"eat_immediately":false,"freezable":true,"freezer_months":3,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'IT-008'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'bouillon de legumes' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Bouillon de légumes', 2000, 'ml', 'required',
     'mouillement', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'tomate fraiche mure' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Tomate fraîche mûre', 600, 'g', 'required',
     'base', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'haricot blanc cuit egoutte' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Haricot blanc cuit, égoutté', 600, 'g', 'required',
     'protéine', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'courgette fraiche' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Courgette fraîche', 400, 'g', 'required',
     'légume tendre', false, 4);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'pomme de terre crue epluchee' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Pomme de terre crue, épluchée', 350, 'g', 'required',
     'féculent', false, 5);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'carotte crue' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Carotte crue', 250, 'g', 'required',
     'légume dur', false, 6);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'petites pates seches' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Petites pâtes sèches', 250, 'g', 'required',
     'féculent', false, 7);

  INSERT INTO culinary.recipe_ingredient_requirements
