  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Émincer l''oignon très fin et le faire blondir dans l''huile d''olive au fond d''une grande marmite, cinq à six minutes à feu moyen, jusqu''à ce qu''il devienne translucide puis prenne une couleur dorée. Il n''y a plus de viande à saisir en premier : cet oignon est désormais tout le fond de la soupe, et bâclé, il laisse un bouillon maigre que rien ne rattrapera ensuite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Ajouter le concentré de tomate, le paprika, la cannelle et le poivre, et remuer deux minutes sur le feu jusqu''à ce que le concentré fonce et se mette à sentir le grillé. Versé cru dans l''eau, il garderait jusqu''au bout un arrière-goût métallique de conserve — et cette soupe-là n''a plus de gras de viande pour le masquer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Verser les tomates râpées ou concassées ainsi que le céleri finement haché avec ses feuilles, puis laisser réduire dix minutes à découvert, jusqu''à voir l''huile remonter en surface. C''est le signe que l''eau des tomates est partie et que la base est prête à recevoir le mouillement. Le céleri entre ici et non plus tard : ses feuilles ont besoin de fondre dans le gras pour donner ce qu''elles ont.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Mouiller de toute l''eau, ajouter les pois chiches rincés et égouttés, puis porter à frémissement et écumer la mousse blanche des premières minutes. Les pois chiches entrent maintenant et non à la fin : ce sont eux la protéine du bol, et vingt minutes passées dans ce bouillon leur font prendre le goût du plat au lieu d''y flotter comme un ajout.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Mettre les carottes en rondelles et les pommes de terre en dés, compter quinze minutes à petits bouillons, puis ajouter les courgettes en dés et compter dix minutes de plus. Cet échelonnement est ce qui sépare une chorba d''un potage : chaque légume doit se reconnaître sous la cuillère, et tous versés ensemble, la courgette aurait disparu quand la carotte serait encore dure.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Verser les vermicelles en pluie dans le bouillon à gros bouillons, en remuant pour qu''ils ne s''agglomèrent pas au fond, et ne les laisser que trois à quatre minutes. Hors du feu ils gonflent encore : cuits à point dans la marmite, ils rendront à table une soupe épaisse et sans liquide.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Couper le feu et saler seulement maintenant — les pois chiches en conserve ont déjà apporté du sel, et une soupe salée en début de cuisson devient impossible à corriger après réduction. Ciseler la coriandre et la menthe, les jeter dans la marmite, couvrir et laisser infuser cinq minutes sans rallumer : bouillies, ces deux herbes noircissent et perdent en une minute ce qui fait l''accent algérois du plat. Servir brûlant en assiette creuse.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-072', 'recipe_family', 'Chorba végétarienne',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-072', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Chorba frik : 80 g de blé vert concassé pour six à la place des vermicelles (amourdecuisine) — c''est une chorba frik, que le parent porte déjà en variante','Soupe mixée : retirer les légumes cuits, les passer au moulin et les remettre dans la marmite avant les vermicelles, en gardant les pois chiches entiers (mesinspirations, marciatack, ptitchef) — écartée parce que le parent, et cette recette avec lui, tient à des légumes reconnaissables sous la cuillère','Curcuma et cumin à la place du paprika et de la cannelle, avec du coulis de tomate en plus des tomates concassées (chefsimon)','Persil plat à la place de la coriandre fraîche (ptitchef)','Piment frais entier cuit dans le bouillon puis retiré au moment de servir (amourdecuisine)','Menthe séchée émiettée au service à la place de la menthe fraîche ciselée (chefsimon, mesinspirations)','Quartier de citron pressé dans l''assiette au service (amourdecuisine, chefsimon, marciatack)','Pois chiches secs trempés la veille et cuits dans le bouillon lui-même, ce qui allonge la cuisson d''une heure mais donne un bouillon plus épais (mesinspirations, amourdecuisine)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-072","variants":["Chorba frik : 80 g de blé vert concassé pour six à la place des vermicelles (amourdecuisine) — c''est une chorba frik, que le parent porte déjà en variante","Soupe mixée : retirer les légumes cuits, les passer au moulin et les remettre dans la marmite avant les vermicelles, en gardant les pois chiches entiers (mesinspirations, marciatack, ptitchef) — écartée parce que le parent, et cette recette avec lui, tient à des légumes reconnaissables sous la cuillère","Curcuma et cumin à la place du paprika et de la cannelle, avec du coulis de tomate en plus des tomates concassées (chefsimon)","Persil plat à la place de la coriandre fraîche (ptitchef)","Piment frais entier cuit dans le bouillon puis retiré au moment de servir (amourdecuisine)","Menthe séchée émiettée au service à la place de la menthe fraîche ciselée (chefsimon, mesinspirations)","Quartier de citron pressé dans l''assiette au service (amourdecuisine, chefsimon, marciatack)","Pois chiches secs trempés la veille et cuits dans le bouillon lui-même, ce qui allonge la cuisson d''une heure mais donne un bouillon plus épais (mesinspirations, amourdecuisine)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-072', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('93fd90ce9a57638f882b8b557a0accb8'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"brothy_umami","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":2,"heat":1,"pungency":2,"richness":2,"freshness":3,"intensity":3},"dominant_flavors":["pois chiche","coriandre fraîche","tomate","cannelle"],"aroma_families":["coriandre","cannelle","tomate_cuite","paprika"],"target_textures":["bouillon_clair","légumes fondants","vermicelles tendres"],"signature_ingredients":["Pois chiche cuit, égoutté","Coriandre fraîche","Vermicelle fin sec"],"identity_guardrails":["Coriandre fraîche et menthe jetées hors du feu : ce sont elles qui font l''algéroise, et bouillies elles noircissent","Le pois chiche est doublé par rapport au parent parce qu''il est désormais la seule protéine du bol : ramené à la quantité du parent, ce n''est plus le même plat dans l''assiette","Vermicelles trois à quatre minutes seulement — ils continuent de gonfler hors du feu et boivent tout le bouillon","Le concentré de tomate se fait revenir avant d''être mouillé, sans quoi il garde son goût de boîte, que rien ne masque plus ici","Les légumes restent en morceaux : mixée, comme le font trois pages du dossier, la chorba devient un velouté et perd sa mâche"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Bortsch végétarien', 'bortsch vegetarien', 'Russie', 'Russie',
     'meal', 'soupe complète', 'named_traditional_dish', 'brothy_umami',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Bortsch végétarien', 'Soupe de betterave râpée, de chou blanc et de pommes de terre, acidulée au vinaigre et portée par des haricots blancs à la place du bœuf — le bortsch maigre, servi avec sa cuillerée de crème aigre.', ds.id, 'JUM-073',
    'Myko', 'editorial', 6, 25, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', '009d6ad1c8509c6cbcd34ff5fe1cd4c4',
    '{"sweet":3,"salty":3,"acidic":4,"bitter":1,"umami":2,"heat":0,"pungency":1,"richness":2,"freshness":2,"intensity":3}'::jsonb, ARRAY['betterave','vinaigre','chou','aneth']::text[],
    ARRAY['betterave','végétal cuit','vinaigre','aneth']::text[], ARRAY['bouillon_clair','légumes fondants','haricots fondants']::text[],
    ARRAY['Betterave crue','Chou blanc frais','Haricot blanc cuit, égoutté']::text[], ARRAY['Sans betterave il n''y a pas de bortsch, et sans haricot blanc ce jumeau n''est plus qu''une soupe de betterave : les deux sont indissociables ici','La betterave se fait revenir avec le vinaigre et le concentré, à part, et entre en dernier — sinon la couleur vire au brun','La soupe doit rester franchement acidulée : c''est l''acidité qui distingue un bortsch d''une soupe de racines','Le bouillon est de légumes : un cube de bœuf ferait basculer la lignée du côté carné sans que rien ne le montre au planificateur','La crème aigre se dépose dans l''assiette, jamais dans la marmite, où elle trancherait']::text[],
    ARRAY['sauté de la betterave à l''acide','mijotage','cuisson séquencée','repos']::text[], ARRAY['Lentilles vertes, 180 g pour quatre, à la place des haricots blancs, avec chou rouge et moutarde (menu-vegetarien) — écartée : la lentille se défait et trouble un bouillon dont la limpidité fait l''intérêt, et le reste du dossier est unanime sur le haricot blanc','Poivron vert taillé avec les légumes durs (ifoodreal, inspirationsforall, marmiton)','Une cuillerée à café de sucre pour arrondir l''acidité (ifoodreal, cookedandloved, marmiton)','Vinaigre de cidre ou jus de citron à la place du vinaigre de vin rouge (gettystewart, cookedandloved, inspirationsforall)','Graines de carvi et céleri branche dans la base aromatique (gettystewart, nirvanacakery)','Chou rouge à la place du chou blanc, qui donne un bortsch plus sombre (feastingathome, nirvanacakery, menu-vegetarien)','Betteraves déjà cuites avec leur jus, versées seulement dix minutes avant la fin — variante que le parent porte déjà','Yaourt à la grecque ou yaourt de coco à la place de la crème aigre (ifoodreal, cookedandloved, menu-vegetarien)','Fanes et tiges de betterave hachées ajoutées avec le chou (feastingathome)']::text[], ARRAY['lait']::text[],
    'Se garde 4 jours au réfrigérateur et gagne à attendre un jour : l''acidité se répartit et la betterave achève de colorer le bouillon. Réchauffer à feu doux, sans faire bouillir, ce qui préserve le rouge. Se congèle 3 mois à -18 °C en retirant d''abord les pommes de terre, qui ressortent granuleuses ; les haricots blancs, eux, supportent le gel sans dommage, ce qui rend ce jumeau plus commode à congeler que le plat carné dont il vient, où c''était la viande qu''il fallait ménager. Jamais avec la crème aigre, qui tranche au dégel comme à l''ébullition. Aucune page du dossier ne chiffre de durée : ces valeurs décrivent ce que fait une soupe de racines acidulée, et elles reprennent celles du parent, dont la structure est ici identique.', '{"fridge_hours":96,"eat_immediately":false,"freezable":true,"freezer_months":3,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'VAR-026'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

