  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-073', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('009d6ad1c8509c6cbcd34ff5fe1cd4c4'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"brothy_umami","scores":{"sweet":3,"salty":3,"acidic":4,"bitter":1,"umami":2,"heat":0,"pungency":1,"richness":2,"freshness":2,"intensity":3},"dominant_flavors":["betterave","vinaigre","chou","aneth"],"aroma_families":["betterave","végétal cuit","vinaigre","aneth"],"target_textures":["bouillon_clair","légumes fondants","haricots fondants"],"signature_ingredients":["Betterave crue","Chou blanc frais","Haricot blanc cuit, égoutté"],"identity_guardrails":["Sans betterave il n''y a pas de bortsch, et sans haricot blanc ce jumeau n''est plus qu''une soupe de betterave : les deux sont indissociables ici","La betterave se fait revenir avec le vinaigre et le concentré, à part, et entre en dernier — sinon la couleur vire au brun","La soupe doit rester franchement acidulée : c''est l''acidité qui distingue un bortsch d''une soupe de racines","Le bouillon est de légumes : un cube de bœuf ferait basculer la lignée du côté carné sans que rien ne le montre au planificateur","La crème aigre se dépose dans l''assiette, jamais dans la marmite, où elle trancherait"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Quiche lorraine végétarienne au tofu fumé', 'quiche lorraine vegetarienne au tofu fume', 'France / cuisine domestique internationale', 'France / cuisine domestique internationale',
     'meal', 'tarte salée', 'domestic_standard', 'creamy_delicate',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Quiche lorraine végétarienne au tofu fumé', 'Fond de pâte brisée garni de dés de tofu fumé rissolés et de gruyère, noyés dans l''appareil œufs-crème-lait de la quiche lorraine — le jumeau végétarien du plat, dont seuls les lardons étaient carnés.', ds.id, 'JUM-074',
    'Myko', 'editorial', 6, 25, 40, 'facile',
    NULL, NULL,
    'B', 'candidate', '02dc8b0e783230a5fb583cb6e5c09cb8',
    '{"sweet":1,"salty":3,"acidic":1,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['fumé','crémeux','fromage']::text[],
    ARRAY['lacté','fumé','herbes séchées']::text[], ARRAY['dessus_doré','intérieur_fondant_ou_crémeux','dés croustillants']::text[],
    ARRAY['Pâte brisée crue','Tofu fumé','Œuf cru','Crème fraîche liquide entière']::text[], ARRAY['Le tofu fumé se rissole avant d''entrer dans la tarte : cru, il rend son eau dans l''appareil et détrempe le fond de pâte','C''est le fumé qui fait le plat, pas le tofu : un tofu nature à la place du fumé donne une quiche au fromage, et l''écart nutritionnel est réel — le fumé porte trente fois plus de sel','L''appareil reste celui du parent, œufs, crème et lait dans les mêmes proportions : c''est lui l''identité de la quiche lorraine, la garniture n''en est que la signature','La cuisson s''arrête sur un centre encore tremblant, sinon l''appareil devient granuleux en refroidissant']::text[],
    ARRAY['fonçage','précuisson de garniture','appareil à crème prise','cuisson au four','repos']::text[], ARRAY['Sans fromage, comme le parent : appareil œufs-crème-lait seul, le tofu fumé pour toute garniture — c''est la version canonique de la quiche lorraine, et elle reste faisable telle quelle','Pâte feuilletée à la place de la pâte brisée (cookpad)','Oignon jaune fondu à l''huile avec le tofu et persil plat ciselé dans la garniture (lacuisinedegeraldine)','Deux cents grammes de tofu fumé pour six, soit un tiers de plus que la quantité retenue (lacuisinedegeraldine)','Brocoli en petites fleurettes sauté avec le tofu (cuisine-addict) — ce n''est plus une quiche lorraine mais une quiche au brocoli, et c''est pour cela que l''audit écarte cette page','Cheddar râpé à la place du gruyère (cuisine-addict)','Pâte brisée maison : 200 g de farine, 100 g de beurre, 60 ml d''eau et 5 g de sel, reposée trente minutes, cuite à blanc dix à quinze minutes avant garniture (lacuisinedegeraldine)','Tofu fumé rissolé à la sauce soja plutôt qu''à l''huile seule, pour un dé plus foncé et plus salé (variante courante des pages écartées faute de balisage lisible)']::text[], ARRAY['gluten','lait','œuf','soja']::text[],
    'Se garde 3 jours au réfrigérateur, filmée, et se réchauffe 12 minutes à 180 °C — jamais au micro-ondes, qui ramollit la pâte. Elle se mange aussi froide, ce qui en fait un déjeuner transportable. Se congèle 2 mois à -18 °C, en parts filmées séparément, et se réchauffe sans décongélation en 20 minutes à 180 °C. Une précision qui n''appartient qu''à ce jumeau : le tofu fumé change de texture au gel, il ressort plus ferme et plus spongieux qu''avant. Ici c''est sans conséquence, parce qu''il a déjà été rissolé et qu''il est pris dans un appareil, mais il ne faut pas attendre d''une part décongelée la tenue du premier jour. Aucune page du dossier ne parle de conservation, et je le dis plutôt que de leur prêter une source. Ces durées ne sont pas pour autant écrites au jugé : elles sont le profil que le corpus donne déjà à toutes ses quiches à appareil œufs-crème — VAR-035, VAR-036, VAR-037 et VAR-038 portent les mêmes trois jours, les mêmes douze minutes à 180 °C, le même refus du micro-ondes et les mêmes deux mois de congélation en parts filmées réchauffées sans décongélation. Seule la note sur la texture du tofu fumé au gel appartient à ce jumeau.', '{"fridge_hours":72,"eat_immediately":false,"freezable":true,"freezer_months":2,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'FR-005'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
