  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Foncer le moule avec la pâte brisée, piquer le fond à la fourchette et remettre au froid vingt minutes. Une pâte détendue se rétracte au four et laisse l''appareil déborder par-dessus le bord : ce quart d''heure de repos est ce qui tient la tarte, et il ne se rattrape pas ensuite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Couper le tofu fumé en petits dés du calibre d''un lardon, puis les faire colorer cinq à six minutes dans l''huile d''olive bien chaude, en les retournant, jusqu''à ce qu''ils croustillent sur toutes leurs faces. Ce geste remplace le rissolage des lardons du parent et il n''est pas facultatif : sorti de son paquet, le tofu fumé apporte le goût de fumé mais reste mou et gorgé d''eau, et jeté cru dans l''appareil il la rendra pendant la cuisson, au fond de la pâte.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Poudrer les dés d''herbes de Provence hors du feu et les laisser tiédir sur un papier absorbant. Les herbes séchées brûlent en quelques secondes dans une poêle très chaude et deviennent amères ; posées sur un tofu encore brûlant, elles s''ouvrent sans risque.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Battre les œufs à la fourchette, ajouter la crème, le lait, la muscade, le sel et le poivre, et mélanger jusqu''à l''homogène sans faire mousser. Un appareil fouetté trop fort gonfle au four puis retombe en se fendant : on cherche un mélange lisse, pas une mousse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Répartir les dés de tofu et le gruyère râpé sur le fond de pâte, puis verser l''appareil par-dessus. Le fromage est ici une décision assumée et non un ajout de confort : la quiche lorraine est canoniquement sans fromage, mais le tofu ne fond pas la graisse que les lardons donnaient à l''appareil, et les deux pages du dossier qui font exactement cette quiche en mettent toutes les deux, cent grammes pour six.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Enfourner à 180 °C pour trente-cinq à quarante minutes. La cuisson est juste quand le dessus est doré et que le centre tremble encore un peu si l''on secoue le moule : pris jusqu''au cœur dans le four, l''appareil finira granuleux une fois refroidi.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Laisser reposer dix minutes avant de couper. L''appareil achève de prendre en refroidissant, et une part coupée à la sortie du four s''affaisse dans l''assiette.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-074', 'recipe_family', 'Quiche lorraine végétarienne au tofu fumé',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-074', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
