  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Sans fromage, comme le parent : appareil œufs-crème-lait seul, le tofu fumé pour toute garniture — c''est la version canonique de la quiche lorraine, et elle reste faisable telle quelle','Pâte feuilletée à la place de la pâte brisée (cookpad)','Oignon jaune fondu à l''huile avec le tofu et persil plat ciselé dans la garniture (lacuisinedegeraldine)','Deux cents grammes de tofu fumé pour six, soit un tiers de plus que la quantité retenue (lacuisinedegeraldine)','Brocoli en petites fleurettes sauté avec le tofu (cuisine-addict) — ce n''est plus une quiche lorraine mais une quiche au brocoli, et c''est pour cela que l''audit écarte cette page','Cheddar râpé à la place du gruyère (cuisine-addict)','Pâte brisée maison : 200 g de farine, 100 g de beurre, 60 ml d''eau et 5 g de sel, reposée trente minutes, cuite à blanc dix à quinze minutes avant garniture (lacuisinedegeraldine)','Tofu fumé rissolé à la sauce soja plutôt qu''à l''huile seule, pour un dé plus foncé et plus salé (variante courante des pages écartées faute de balisage lisible)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-074","variants":["Sans fromage, comme le parent : appareil œufs-crème-lait seul, le tofu fumé pour toute garniture — c''est la version canonique de la quiche lorraine, et elle reste faisable telle quelle","Pâte feuilletée à la place de la pâte brisée (cookpad)","Oignon jaune fondu à l''huile avec le tofu et persil plat ciselé dans la garniture (lacuisinedegeraldine)","Deux cents grammes de tofu fumé pour six, soit un tiers de plus que la quantité retenue (lacuisinedegeraldine)","Brocoli en petites fleurettes sauté avec le tofu (cuisine-addict) — ce n''est plus une quiche lorraine mais une quiche au brocoli, et c''est pour cela que l''audit écarte cette page","Cheddar râpé à la place du gruyère (cuisine-addict)","Pâte brisée maison : 200 g de farine, 100 g de beurre, 60 ml d''eau et 5 g de sel, reposée trente minutes, cuite à blanc dix à quinze minutes avant garniture (lacuisinedegeraldine)","Tofu fumé rissolé à la sauce soja plutôt qu''à l''huile seule, pour un dé plus foncé et plus salé (variante courante des pages écartées faute de balisage lisible)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-074', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('02dc8b0e783230a5fb583cb6e5c09cb8'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_delicate","scores":{"sweet":1,"salty":3,"acidic":1,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["fumé","crémeux","fromage"],"aroma_families":["lacté","fumé","herbes séchées"],"target_textures":["dessus_doré","intérieur_fondant_ou_crémeux","dés croustillants"],"signature_ingredients":["Pâte brisée crue","Tofu fumé","Œuf cru","Crème fraîche liquide entière"],"identity_guardrails":["Le tofu fumé se rissole avant d''entrer dans la tarte : cru, il rend son eau dans l''appareil et détrempe le fond de pâte","C''est le fumé qui fait le plat, pas le tofu : un tofu nature à la place du fumé donne une quiche au fromage, et l''écart nutritionnel est réel — le fumé porte trente fois plus de sel","L''appareil reste celui du parent, œufs, crème et lait dans les mêmes proportions : c''est lui l''identité de la quiche lorraine, la garniture n''en est que la signature","La cuisson s''arrête sur un centre encore tremblant, sinon l''appareil devient granuleux en refroidissant"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Œufs à la basquaise', 'oeufs a la basquaise', 'France / cuisine domestique internationale', 'France / cuisine domestique internationale',
     'meal', 'plat mijoté', 'named_traditional_dish', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Œufs à la basquaise', 'Compotée de poivrons rouges et verts, d''oignon et de tomate au piment d''Espelette, dans laquelle les œufs finissent de cuire à couvert — le jumeau végétarien du poulet basquaise, dont seule la volaille était carnée.', ds.id, 'JUM-081',
    'Myko', 'editorial', 4, 20, 40, 'facile',
    NULL, NULL,
    'B', 'candidate', '9cb5f54d3a4ea559fd84040879988200',
    '{"sweet":3,"salty":2,"acidic":3,"bitter":1,"umami":3,"heat":2,"pungency":2,"richness":2,"freshness":2,"intensity":3}'::jsonb, ARRAY['poivron compoté','tomate cuite','piment d''Espelette','œuf']::text[],
    ARRAY['poivron','tomate_cuite','piment','huile_olive']::text[], ARRAY['légumes fondants','sauce_épaisse','jaune d''œuf coulant']::text[],
    ARRAY['Œuf cru','Poivron rouge frais','Piment d''Espelette moulu']::text[], ARRAY['Les œufs cuisent DANS la compotée, comme le poulet du parent cuit dans sa sauce : brouillés ou pochés à côté, ce n''est plus le même plat','La compotée doit tenir au sillon avant que les œufs n''y entrent, sinon ils se noient','Le piment d''Espelette entre dans le gras chaud, avant la tomate, sinon il ne donne que sa couleur','Deux couleurs de poivron, comme chez le parent : le vert apporte l''amertume que le rouge n''a pas']::text[],
    ARRAY['suer','cuisson à couvert','déglaçage','compotage','œufs pochés en sauce']::text[], ARRAY['Aux œufs brouillés, versés sur la compotée hors du feu et remués jusqu''à la prise (marmiton, 750g)','Aux œufs pochés à l''eau vinaigrée et nappés de la compotée au service (marmiton)','En cocottes individuelles, un œuf par cocotte, huit minutes au four au bain-marie sous le gril (750g)','Aux olives noires dénoyautées et au fromage de brebis en dés fondu sur les œufs, forme absente du catalogue (750g)','Adoucie d''un morceau de sucre pour corriger l''acidité de la tomate (marmiton, 750g)','Au chorizo ou aux lardons poêlés à part et ajoutés au service — c''est alors le plat carné, pas ce jumeau (marmiton)']::text[], ARRAY['œuf']::text[],
    'Aucune page du dossier ne parle de conservation : ce qui suit décrit ce que fait physiquement le plat. La compotée seule, sans les œufs, se garde 4 jours au réfrigérateur dans un récipient fermé et gagne au deuxième jour, le temps que le poivron et la tomate se répondent ; elle se congèle 3 mois à -18 °C sans rien perdre, ce qui en fait une base à doubler. Le plat monté, lui, ne se conserve pas : un jaune d''œuf déjà cuit devient sableux au réchauffage et le blanc rend son eau dans la sauce. On garde donc la compotée et on casse les œufs au moment de servir — c''est aussi ce qui permet de cuire une seule sauce pour deux assiettes, celle du parent et celle-ci.', '{"fridge_hours":96,"eat_immediately":true,"freezable":true,"freezer_months":3,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'FR-008'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
