  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Épépiner les poivrons et les tailler en lanières d''un centimètre, émincer l''oignon finement, hacher l''ail. Prendre une sauteuse large plutôt qu''une casserole : la compotée devra réduire à découvert, puis recevoir huit œufs côte à côte sans qu''ils se chevauchent, et c''est le diamètre du récipient qui décide des deux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire fondre l''oignon dix minutes dans l''huile d''olive à feu doux, sans le laisser prendre couleur, puis ajouter les lanières de poivron, couvrir et poursuivre un quart d''heure. Le poivron rend son eau sous le couvercle et s''attendrit sans griller : c''est ce passage à couvert qui sépare une basquaise d''une poêlée de poivrons, et il ne se raccourcit pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Découvrir, ajouter l''ail haché, le thym effeuillé et le piment d''Espelette, remuer une demi-minute, puis verser le vin blanc et laisser l''alcool s''évaporer à feu vif. L''Espelette n''est pas un piment de force mais de parfum : jeté dans le gras chaud avant le liquide, il donne son goût fruité, versé à la fin il ne donne que sa couleur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser les tomates concassées, saler, poivrer, et laisser compoter vingt-cinq minutes à découvert, à petits frémissements, jusqu''à ce qu''une spatule passée au fond laisse un sillon qui tient deux ou trois secondes. Une compotée encore liquide noierait les œufs et les ferait pocher au lieu de les prendre : le sillon est le seul test qui vaille, et il vient plus tard qu''on ne croit.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Creuser huit nids dans la compotée avec le dos d''une cuillère, en dégageant bien le fond de la sauteuse, et casser un œuf dans chacun. Les nids ne sont pas une décoration : ils posent le blanc au contact de la fonte chaude, là où il prend vite, pendant que le jaune reste porté par la sauce, plus tiède.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Couvrir et laisser cuire six à huit minutes à feu doux, jusqu''à ce que les blancs soient opaques et les jaunes encore tremblants. La vapeur retenue par le couvercle voile le dessus des jaunes et achève les blancs par le haut ; au-delà de huit minutes le jaune se fige et le plat perd ce qui en fait un plat du soir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Couper le feu, laisser reposer deux minutes à couvert et servir dans la sauteuse, avec du pain grillé ou du riz. Ce court repos suffit à ce que la chaleur résiduelle finisse les blancs les plus épais, sans que les jaunes en pâtissent — on ne rattrape jamais un œuf trop cuit, on peut toujours en attendre un peu plus.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-081', 'recipe_family', 'Œufs à la basquaise',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-081', 'missing_required_count', v_missing), 'open');
  END IF;

