  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Chauffer une poêle à sec et y faire tourner les graines de coriandre et de cumin, les clous de girofle, le bâton de cannelle brisé et les piments rouges séchés, une à deux minutes, jusqu''à ce que l''odeur monte et que les graines commencent à craquer. La torréfaction est le premier geste du parent et elle ne change pas : ce sont les huiles essentielles des graines qui font le vindaloo, et elles ne sortent qu''à la chaleur sèche.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Verser les épices tièdes dans un mixeur avec le vinaigre, l''ail, le gingembre, le curcuma, le paprika, le poivre et le concentré de tomate, et mixer jusqu''à obtenir une pâte lisse. Le vinaigre n''est pas ici un assaisonnement de fin mais le liquide qui porte la pâte : c''est de lui que le plat tient son nom et son acidité franche.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Émincer l''oignon et le faire fondre douze minutes dans une cocotte à feu moyen, en mouillant d''une cuillerée de bouillon dès qu''il attache. On cuit sans matière grasse, comme la page qui s''en passe : sans viande à saisir, il n''y a pas de gras à récupérer, et la pâte acide qui suit n''a pas besoin d''huile pour s''ouvrir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ajouter la pâte et la cuire cinq à six minutes en remuant sans arrêt, jusqu''à ce qu''elle fonce et se détache du fond. Une pâte crue garde un goût de vinaigre brut et d''ail piquant ; c''est cette cuisson qui la transforme en sauce, et c''est le seul moment du plat où il ne faut pas quitter la cocotte des yeux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser le bouillon, ajouter les pommes de terre en dés de deux centimètres, porter à frémissement et laisser cuire vingt minutes à couvert partiel. Les dés cuisent dans la sauce et non à l''eau : ils s''y colorent, et l''amidon qu''ils lâchent épaissit le curry, ce que la viande du parent ne faisait pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Ajouter les pois chiches rincés, les tomates concassées et le jaggery, saler, et poursuivre vingt minutes à petits bouillons, à découvert. Le sucre de canne n''adoucit pas le piment, il équilibre l''acide : sans lui, le vinaigre reste en pointe sur la langue au lieu de se fondre au piment.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Goûter, rectifier le sel et l''acidité, couper le feu et parsemer de coriandre ciselée. Un vindaloo se goûte à la fin seulement : les quarante minutes de mijotage ont arrondi la pâte, et ce qui paraissait violent au départ s''est rangé.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Laisser reposer un quart d''heure à couvert avant de servir avec du riz. Le repos n''est pas une politesse : les pois chiches, qui sont entrés cuits, boivent alors la sauce et cessent d''être un ingrédient posé dedans.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-082', 'recipe_family', 'Vindaloo de pois chiches et pommes de terre',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-082', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Aux légumes plutôt qu''aux pois chiches : chou-fleur, haricots verts et poivron rouge à la place de la légumineuse (pickyeaterblog)','Moitié pomme de terre, moitié patate douce (monkeyandmekitchenadventures)','Aux pois chiches secs trempés la veille et cuits dans le plat, quarante minutes de plus (yupitsvegan, onegreenplanet)','Pâte enrichie de cardamome verte et de graines de fenugrec, deux pages sur trois (yupitsvegan, pickyeaterblog)','Ouverture des épices à l''huile de coco, forme absente du catalogue (yupitsvegan, pickyeaterblog)','Épinards frais tombés dans la sauce en fin de cuisson (monkeyandmekitchenadventures)','Garam masala et piment de Cayenne ajoutés au dernier moment pour relever (pickyeaterblog, monkeyandmekitchenadventures)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-082","variants":["Aux légumes plutôt qu''aux pois chiches : chou-fleur, haricots verts et poivron rouge à la place de la légumineuse (pickyeaterblog)","Moitié pomme de terre, moitié patate douce (monkeyandmekitchenadventures)","Aux pois chiches secs trempés la veille et cuits dans le plat, quarante minutes de plus (yupitsvegan, onegreenplanet)","Pâte enrichie de cardamome verte et de graines de fenugrec, deux pages sur trois (yupitsvegan, pickyeaterblog)","Ouverture des épices à l''huile de coco, forme absente du catalogue (yupitsvegan, pickyeaterblog)","Épinards frais tombés dans la sauce en fin de cuisson (monkeyandmekitchenadventures)","Garam masala et piment de Cayenne ajoutés au dernier moment pour relever (pickyeaterblog, monkeyandmekitchenadventures)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-082', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('095db5a31786a0a9fd7a81e2d03c3626'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"spicy_umami","scores":{"sweet":2,"salty":2,"acidic":4,"bitter":1,"umami":3,"heat":4,"pungency":4,"richness":1,"freshness":2,"intensity":5},"dominant_flavors":["vinaigre","piment rouge","cumin torréfié","pois chiche"],"aroma_families":["vinaigre","piment","cumin","gingembre","cannelle"],"target_textures":["pomme de terre fondante","sauce_épaisse","dés fondants gardant leur forme"],"signature_ingredients":["Vinaigre de palmier ou cidre","Piment rouge séché","Pois chiche cuit, égoutté"],"identity_guardrails":["Le vinaigre entre dans la pâte, pas à la fin : c''est le liquide qui porte les épices, comme chez le parent","Les épices entières se torréfient à sec avant d''être mixées — une poudre toute prête donne un autre plat","La pâte se cuit jusqu''à ce qu''elle fonce, sinon l''ail reste piquant et le vinaigre brut","Le jaggery équilibre l''acide et ne sucre pas : le supprimer déséquilibre le plat, le doubler en fait un curry sucré"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Galette de sarrasin aux champignons, œuf et fromage', 'galette de sarrasin aux champignons oeuf et fromage', 'France (Bretagne)', 'France (Bretagne)',
     'meal', 'galette', 'named_traditional_dish', 'nutty_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Galette de sarrasin aux champignons, œuf et fromage', 'Galette de sarrasin garnie de champignons de Paris poêlés à l''échalote, d''un œuf miroir et de fromage râpé — le jumeau végétarien de la galette complète, dont seul le jambon était carné.', ds.id, 'JUM-083',
    'Myko', 'editorial', 4, 25, 20, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '82041231f8bec5f94dba39923d6f531c',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3}'::jsonb, ARRAY['sarrasin grillé','champignon poêlé','beurre','fromage fondu']::text[],
    ARRAY['céréalier','champignon_terreux','beurre','fromage_affiné']::text[], ARRAY['bords_grillés','jaune d''œuf coulant','lamelles de champignon tendres','fromage fondant']::text[],
    ARRAY['Farine de sarrasin','Champignon de Paris frais','Œuf cru']::text[], ARRAY['Les champignons perdent toute leur eau à la poêle avant d''entrer dans la galette, sinon le fond se détrempe','L''œuf reste coulant : c''est lui qui fait la sauce du plat, il n''y en a pas d''autre','La galette se garnit sur sa seconde face, jamais avant d''être retournée','Elle se mange à la sortie de la poêle — une galette garnie qui attend n''est plus la même chose']::text[],
    ARRAY['mélange','repos','évaporation des champignons','poêlage','pliage']::text[], ARRAY['Aux champignons des bois — chanterelles, pleurotes, champignons bruns — plutôt qu''aux champignons de Paris (chefsimon)','À la crème : blanc de poireau fondu, vin blanc, crème et muscade avec les champignons (chefsimon)','Sans échalote, les champignons poêlés seuls à l''ail (supertoinette)','Aux épinards frais tombés avec les champignons (ptitchef)','Pâte au lait ribot avec une pointe de levure, plus souple à étaler (ptitchef)','Avec une tranche de jambon ajoutée sous l''œuf — c''est alors la galette complète du parent, pas ce jumeau (jow, supertoinette, ptitchef)']::text[], ARRAY['gluten','œuf','lait']::text[],
    'Le dossier ne dit rien de la conservation ; ce qui suit vaut pour ce type de galette et rejoint ce que dit le parent. La pâte crue se garde 3 jours au réfrigérateur et s''améliore même au deuxième jour, le sarrasin ayant fini de boire : c''est l''intérêt d''en faire une grande quantité. Les galettes NATURE, cuites sans garniture, se gardent 3 jours empilées avec un papier entre chacune, et se congèlent 2 mois à -18 °C ; on les garnit alors directement à la poêle, ce qui ramène le plat à cinq minutes. La poêlée de champignons se garde 48 heures à part et se réchauffe à la poêle. La galette garnie, en revanche, ne se conserve pas du tout : l''œuf coulant est le plat, et il ne se réchauffe pas.', '{"fridge_hours":48,"eat_immediately":true,"freezable":true,"freezer_months":2,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'RAP-044'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'eau' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Eau', 480, 'ml', 'required',
     'pâte', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'farine de sarrasin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Farine de sarrasin', 210, 'g', 'required',
     'pâte', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'champignon de paris frais' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Champignon de Paris frais', 200, 'g', 'required',
     'garniture', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'gruyere rape' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Gruyère râpé', 100, 'g', 'required',
     'garniture', false, 4);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'beurre doux' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Beurre doux', 60, 'g', 'required',
     'cuisson', false, 5);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'oeuf cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Œuf cru', 5, 'u', 'required',
     'garniture', false, 6);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'echalote crue' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Échalote crue', 40, 'g', 'required',
     'aromatique', false, 7);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 5, 'g', 'required',
     'pâte', false, 8);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'required',
     'assaisonnement', false, 9);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Mélanger la farine de sarrasin et le sel dans un saladier, creuser un puits, y casser un œuf et verser l''eau petit à petit en fouettant, jusqu''à une pâte lisse et fluide. Verser l''eau en une fois donnerait des grumeaux que le fouet ne rattrape plus : la farine doit être mouillée progressivement pour que l''amidon se disperse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Couvrir et laisser reposer la pâte au moins deux heures, et jusqu''à une nuit au réfrigérateur. Le sarrasin n''a pas de gluten et ne se détend donc pas comme une pâte de blé : ce qu''on attend du repos, c''est que ses grains gonflent d''eau, sans quoi la galette se déchire à l''étalement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Émincer l''échalote, nettoyer les champignons et les tailler en lamelles de trois ou quatre millimètres. Ne pas les passer sous l''eau : un champignon de Paris se brosse ou s''essuie, il boit ce qu''on lui donne et rendra tout à la poêle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Faire fondre une noix de beurre dans une poêle bien chaude, y jeter l''échalote une minute puis les champignons, et les cuire à feu vif huit minutes sans couvrir, en remuant, jusqu''à ce que l''eau rendue soit entièrement partie et qu''ils colorent. C''est l''étape qui décide de la garniture : des champignons retirés trop tôt lâcheraient leur eau dans la galette et la ramolliraient sous l''œuf. Saler et poivrer hors du feu, réserver.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Beurrer une crêpière ou une poêle large sur feu moyen-vif, verser une petite louche de pâte et l''étaler en couche mince, puis laisser cuire jusqu''à ce que les bords se décollent et se colorent. Une galette se cuit d''abord seule et sans garniture : c''est la face qui prend la couleur, et elle deviendra le dessous de l''assiette.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Retourner la galette, casser un œuf en son centre sans crever le jaune, poudrer de fromage râpé autour du blanc et répartir un quart de la poêlée de champignons. L''ordre compte : le fromage posé sur la galette brûlante fond et colle la garniture, alors que jeté sur les champignons il resterait en surface.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Laisser cuire trois minutes à feu moyen, le temps que le blanc devienne opaque et que le jaune reste coulant, puis rabattre les quatre bords sur la garniture en laissant le jaune apparent. Le pli n''est pas décoratif : il tient la chaleur autour du fromage pendant que l''œuf finit, et il fait tenir la galette à la fourchette.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Servir immédiatement, et recommencer pour les trois autres galettes. Une galette garnie ne se garde pas au chaud : le jaune continue de cuire, le fond ramollit sous la vapeur, et c''est exactement ce que ce plat n''est pas.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-083', 'recipe_family', 'Galette de sarrasin aux champignons, œuf et fromage',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-083', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Aux champignons des bois — chanterelles, pleurotes, champignons bruns — plutôt qu''aux champignons de Paris (chefsimon)','À la crème : blanc de poireau fondu, vin blanc, crème et muscade avec les champignons (chefsimon)','Sans échalote, les champignons poêlés seuls à l''ail (supertoinette)','Aux épinards frais tombés avec les champignons (ptitchef)','Pâte au lait ribot avec une pointe de levure, plus souple à étaler (ptitchef)','Avec une tranche de jambon ajoutée sous l''œuf — c''est alors la galette complète du parent, pas ce jumeau (jow, supertoinette, ptitchef)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-083","variants":["Aux champignons des bois — chanterelles, pleurotes, champignons bruns — plutôt qu''aux champignons de Paris (chefsimon)","À la crème : blanc de poireau fondu, vin blanc, crème et muscade avec les champignons (chefsimon)","Sans échalote, les champignons poêlés seuls à l''ail (supertoinette)","Aux épinards frais tombés avec les champignons (ptitchef)","Pâte au lait ribot avec une pointe de levure, plus souple à étaler (ptitchef)","Avec une tranche de jambon ajoutée sous l''œuf — c''est alors la galette complète du parent, pas ce jumeau (jow, supertoinette, ptitchef)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-083', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('82041231f8bec5f94dba39923d6f531c'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"nutty_savory","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3},"dominant_flavors":["sarrasin grillé","champignon poêlé","beurre","fromage fondu"],"aroma_families":["céréalier","champignon_terreux","beurre","fromage_affiné"],"target_textures":["bords_grillés","jaune d''œuf coulant","lamelles de champignon tendres","fromage fondant"],"signature_ingredients":["Farine de sarrasin","Champignon de Paris frais","Œuf cru"],"identity_guardrails":["Les champignons perdent toute leur eau à la poêle avant d''entrer dans la galette, sinon le fond se détrempe","L''œuf reste coulant : c''est lui qui fait la sauce du plat, il n''y en a pas d''autre","La galette se garnit sur sa seconde face, jamais avant d''être retournée","Elle se mange à la sortie de la poêle — une galette garnie qui attend n''est plus la même chose"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Gratin d''endives à la béchamel', 'gratin d endives a la bechamel', 'France / cuisine domestique internationale', 'France / cuisine domestique internationale',
     'meal', 'gratin complet', 'domestic_standard', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Gratin d''endives à la béchamel', 'Endives braisées jusqu''à ce qu''elles soient tendres, nappées d''une béchamel muscadée où fond le fromage, puis gratinées — le jumeau végétarien des endives au jambon, dont le fromage prend la place des tranches.', ds.id, 'JUM-084',
    'Myko', 'editorial', 4, 20, 50, 'facile',
    NULL, NULL,
    'B', 'candidate', '32aac48b6078daee2254ba1e01a98031',
    '{"sweet":2,"salty":3,"acidic":0,"bitter":2,"umami":3,"heat":0,"pungency":0,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['endive braisée','béchamel muscadée','comté','beurre']::text[],
    ARRAY['lacté','muscade','fromage_affiné','beurre']::text[], ARRAY['feuilles fondantes','nappant','croûte gratinée']::text[],
    ARRAY['Endive fraîche','Comté','Lait demi-écrémé']::text[], ARRAY['Les endives sont pressées après braisage : l''eau qu''on leur laisse délaye la béchamel au four','Le fromage de la sauce fond hors du feu, sinon il se sépare et rend son gras','Le talon amer est retiré avant cuisson, on ne le corrige plus après','La béchamel reste celle du parent — lait, roux blanc, muscade : la crème et la maïzena des pages du dossier lient un autre plat']::text[],
    ARRAY['braisage','évaporation','béchamel','montage en couches','gratinage']::text[], ARRAY['À la fourme de Montbrison écrasée à la fourchette dans une sauce lait-crème liée à la maïzena, forme absente du catalogue (chefsimon)','Au bleu d''Auvergne fondu dans un appareil œuf-lait, avec des noix concassées, forme absente du catalogue (ptitchef)','À la fourme d''Ambert et à la crème, avec des pommes de terre en lamelles sous les endives (marmiton)','Au fromage de chèvre bûche en rondelles posées avant le gratinage : trois pages du dossier le font, mais toutes avec du jambon ou des lardons — la version sans viande n''est attestée par aucune','Aux endives émincées et fondues à l''huile d''olive plutôt que braisées entières (ptitchef, marmiton)','Sucrée-salée, au miel, à l''orange et au pain d''épices émietté sur le dessus (marmiton)']::text[], ARRAY['gluten','lait']::text[],
    'Aucune des quatre pages sans viande ne parle de conservation ; ce qui suit décrit ce que fait un gratin de légume à la béchamel, et rejoint les 3 jours annoncés par le parent. Se garde 3 jours au réfrigérateur, filmé, et se réchauffe 15 minutes à 180 °C plutôt qu''au micro-ondes, qui fait bouillir la sauce et la fait trancher. Ne se congèle pas : l''endive est faite d''eau tenue par des feuilles qui éclatent au gel, et la béchamel, elle, se déphase au dégel — on retrouve un légume filandreux dans une sauce granuleuse. Ce qui se prépare d''avance, en revanche, c''est le plat monté et cru de gratinage : braisées la veille et nappées le jour même, les endives passent au four sans rien perdre.', '{"fridge_hours":72,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'FR-022'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

