     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-084","variants":["À la fourme de Montbrison écrasée à la fourchette dans une sauce lait-crème liée à la maïzena, forme absente du catalogue (chefsimon)","Au bleu d''Auvergne fondu dans un appareil œuf-lait, avec des noix concassées, forme absente du catalogue (ptitchef)","À la fourme d''Ambert et à la crème, avec des pommes de terre en lamelles sous les endives (marmiton)","Au fromage de chèvre bûche en rondelles posées avant le gratinage : trois pages du dossier le font, mais toutes avec du jambon ou des lardons — la version sans viande n''est attestée par aucune","Aux endives émincées et fondues à l''huile d''olive plutôt que braisées entières (ptitchef, marmiton)","Sucrée-salée, au miel, à l''orange et au pain d''épices émietté sur le dessus (marmiton)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-084', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('32aac48b6078daee2254ba1e01a98031'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":2,"salty":3,"acidic":0,"bitter":2,"umami":3,"heat":0,"pungency":0,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["endive braisée","béchamel muscadée","comté","beurre"],"aroma_families":["lacté","muscade","fromage_affiné","beurre"],"target_textures":["feuilles fondantes","nappant","croûte gratinée"],"signature_ingredients":["Endive fraîche","Comté","Lait demi-écrémé"],"identity_guardrails":["Les endives sont pressées après braisage : l''eau qu''on leur laisse délaye la béchamel au four","Le fromage de la sauce fond hors du feu, sinon il se sépare et rend son gras","Le talon amer est retiré avant cuisson, on ne le corrige plus après","La béchamel reste celle du parent — lait, roux blanc, muscade : la crème et la maïzena des pages du dossier lient un autre plat"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Jerk tofu', 'jerk tofu', 'Jamaïque', 'Jamaïque',
     'meal', 'tofu grillé épicé', 'named_traditional_dish', 'spicy_umami',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Jerk tofu', 'Tofu ferme pressé, mariné une nuit dans une purée de piment scotch bonnet, piment de la Jamaïque, thym et ciboule, puis grillé jusqu''à ce que la marinade caramélise', ds.id, 'JUM-091',
    'Myko', 'editorial', 4, 15, 20, 'facile',
    NULL, NULL,
    'B', 'candidate', '98f8ebf917620a976e2dbd35d8f0a36f',
    '{"sweet":3,"salty":4,"acidic":3,"bitter":1,"umami":4,"heat":5,"pungency":4,"richness":2,"freshness":2,"intensity":5}'::jsonb, ARRAY['pimenté','allspice','thym','soja fermenté']::text[],
    ARRAY['piment','allspice','thym','ail','agrume','gingembre','soja_fermenté','grillé']::text[], ARRAY['croûte_caramélisée','cœur_ferme']::text[],
    ARRAY['Tofu ferme','Piment scotch bonnet','Piment de la Jamaïque moulu','Thym frais']::text[], ARRAY['Le tofu se presse avant de mariner : sans cela la marinade n''entre pas et le plat n''a de goût qu''en surface','Scotch bonnet, piment de la Jamaïque et thym ensemble — retirer l''un des trois donne un autre plat qui n''est plus jerk','Marinade d''une nuit, jamais d''une demi-heure : c''est le temps qui fait le goût là où la volaille avait son gras','Feu moyen et non vif : le sucre de la marinade noircit avant que le tofu ne chauffe','Le tofu est ferme, jamais soyeux : le soyeux ne tient pas sur une grille']::text[],
    ARRAY['pressage du tofu','mixage','marinade longue','grillade à feu modéré','réduction de la marinade']::text[], ARRAY['Tofu congelé puis décongelé avant pressage, pour une texture plus spongieuse et plus absorbante (makeitdairyfree, seule page du dossier à le faire)','Au four, 15 minutes à 200 °C par face, plutôt qu''au gril (kathysvegankitchen)','À la friteuse à air, 10 à 15 minutes à 190 °C en secouant le panier (kathysvegankitchen)','Sirop d''érable à la place du sucre brun, une cuillerée et demie à soupe (kathysvegankitchen, tastingtable, veganwithgusto)','Mélasse à la place du sucre brun, deux cuillerées à soupe (makeitdairyfree, connoisseurusveg)','Habanero à la place du scotch bonnet (kathysvegankitchen, tastingtable, connoisseurusveg)','Vinaigre de cidre ou vinaigre blanc dans la marinade, une à trois cuillerées à soupe (makeitdairyfree, oaktownspiceshop)','Servi en bol sur du riz aux haricots rouges et lait de coco (connoisseurusveg, kathysvegankitchen)','Avec une salsa d''ananas, tomate, oignon rouge et coriandre (kathysvegankitchen)','Sauté à la poêle avec des dés d''ananas caramélisés à la fin (connoisseurusveg)']::text[], ARRAY['soja']::text[],
    'Se garde 4 jours au réfrigérateur dans un récipient fermé, avec sa marinade réduite versée dessus : c''est un plat qui gagne au deuxième jour, le piment s''arrondissant et le thym se diffusant dans toute l''épaisseur. Aucune page du dossier ne parle de congélation ; ce que fait physiquement un tofu congelé est en revanche connu et l''une d''elles s''en sert exprès — l''eau qu''il contient gèle en cristaux, ouvre la matière et la rend spongieuse. Le plat cuit se congèle donc 2 mois sans risque sanitaire, mais il ressort avec une texture nettement plus lâche : à réserver au tofu émietté dans une farce ou un sandwich, pas au pavé servi entier. C''est une déduction de la physique du produit et non une consigne des sources, et elle est écrite comme telle. La marinade crue, elle, ne se garde pas plus de 24 heures et ne se réutilise jamais d''une fournée sur l''autre. Réchauffage : 6 minutes à la poêle à feu doux, ou 10 minutes au four à 180 °C ; le micro-ondes rend le tofu caoutchouteux.', '{"fridge_hours":96,"eat_immediately":false,"freezable":true,"freezer_months":2,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'REAL-288'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

