  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-091', 'recipe_family', 'Jerk tofu',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-091', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Tofu congelé puis décongelé avant pressage, pour une texture plus spongieuse et plus absorbante (makeitdairyfree, seule page du dossier à le faire)','Au four, 15 minutes à 200 °C par face, plutôt qu''au gril (kathysvegankitchen)','À la friteuse à air, 10 à 15 minutes à 190 °C en secouant le panier (kathysvegankitchen)','Sirop d''érable à la place du sucre brun, une cuillerée et demie à soupe (kathysvegankitchen, tastingtable, veganwithgusto)','Mélasse à la place du sucre brun, deux cuillerées à soupe (makeitdairyfree, connoisseurusveg)','Habanero à la place du scotch bonnet (kathysvegankitchen, tastingtable, connoisseurusveg)','Vinaigre de cidre ou vinaigre blanc dans la marinade, une à trois cuillerées à soupe (makeitdairyfree, oaktownspiceshop)','Servi en bol sur du riz aux haricots rouges et lait de coco (connoisseurusveg, kathysvegankitchen)','Avec une salsa d''ananas, tomate, oignon rouge et coriandre (kathysvegankitchen)','Sauté à la poêle avec des dés d''ananas caramélisés à la fin (connoisseurusveg)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-091","variants":["Tofu congelé puis décongelé avant pressage, pour une texture plus spongieuse et plus absorbante (makeitdairyfree, seule page du dossier à le faire)","Au four, 15 minutes à 200 °C par face, plutôt qu''au gril (kathysvegankitchen)","À la friteuse à air, 10 à 15 minutes à 190 °C en secouant le panier (kathysvegankitchen)","Sirop d''érable à la place du sucre brun, une cuillerée et demie à soupe (kathysvegankitchen, tastingtable, veganwithgusto)","Mélasse à la place du sucre brun, deux cuillerées à soupe (makeitdairyfree, connoisseurusveg)","Habanero à la place du scotch bonnet (kathysvegankitchen, tastingtable, connoisseurusveg)","Vinaigre de cidre ou vinaigre blanc dans la marinade, une à trois cuillerées à soupe (makeitdairyfree, oaktownspiceshop)","Servi en bol sur du riz aux haricots rouges et lait de coco (connoisseurusveg, kathysvegankitchen)","Avec une salsa d''ananas, tomate, oignon rouge et coriandre (kathysvegankitchen)","Sauté à la poêle avec des dés d''ananas caramélisés à la fin (connoisseurusveg)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-091', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('98f8ebf917620a976e2dbd35d8f0a36f'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"spicy_umami","scores":{"sweet":3,"salty":4,"acidic":3,"bitter":1,"umami":4,"heat":5,"pungency":4,"richness":2,"freshness":2,"intensity":5},"dominant_flavors":["pimenté","allspice","thym","soja fermenté"],"aroma_families":["piment","allspice","thym","ail","agrume","gingembre","soja_fermenté","grillé"],"target_textures":["croûte_caramélisée","cœur_ferme"],"signature_ingredients":["Tofu ferme","Piment scotch bonnet","Piment de la Jamaïque moulu","Thym frais"],"identity_guardrails":["Le tofu se presse avant de mariner : sans cela la marinade n''entre pas et le plat n''a de goût qu''en surface","Scotch bonnet, piment de la Jamaïque et thym ensemble — retirer l''un des trois donne un autre plat qui n''est plus jerk","Marinade d''une nuit, jamais d''une demi-heure : c''est le temps qui fait le goût là où la volaille avait son gras","Feu moyen et non vif : le sucre de la marinade noircit avant que le tofu ne chauffe","Le tofu est ferme, jamais soyeux : le soyeux ne tient pas sur une grille"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('San bei doufu', 'san bei doufu', 'Taïwan', 'Taïwan',
     'meal', 'tofu trois tasses', 'named_traditional_dish', 'spicy_umami',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'San bei doufu', 'Tranches de tofu ferme dorées à la fécule puis glacées dans les trois liquides taïwanais — huile de sésame, sauce soja et vin de riz — avec de l''ail entier, du gingembre et une poignée de basilic jetée hors du feu', ds.id, 'JUM-092',
    'Myko', 'editorial', 4, 20, 25, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'e4c524fd1fd6c3bf125c8894ab9c5013',
    '{"sweet":2,"salty":4,"acidic":1,"bitter":1,"umami":5,"heat":2,"pungency":3,"richness":4,"freshness":3,"intensity":4}'::jsonb, ARRAY['sésame grillé','soja fermenté','basilic thaï','ail confit']::text[],
    ARRAY['sésame_toasté','soja_fermenté','basilic','ail','gingembre']::text[], ARRAY['tofu_glacé','peau_de_fécule','ail_fondant','basilic_frais']::text[],
    ARRAY['Tofu ferme','Huile de sésame grillé','Sauce soja légère','Vin de riz taïwanais']::text[], ARRAY['Volumes égaux d''huile de sésame, de sauce soja et de vin de riz : c''est le nom du plat, et le déséquilibrer lui fait perdre son identité','L''huile de sésame ne chauffe jamais vivement, sous peine d''amertume','Le tofu se dore à part avant la sauce : il n''a ni peau ni gras pour se colorer dedans','L''ail reste en gousses entières, jamais haché','Le basilic entre hors du feu, en une fois, et le plat part à table dans la minute']::text[],
    ARRAY['enrobage à la fécule','friture peu profonde','sauté aromatique','braisage à découvert','glaçage']::text[], ARRAY['Tofu congelé puis décongelé et essoré, cassé en gros morceaux irréguliers plutôt que tranché (thefoodietakesflight)','Tofu blanchi cinq minutes à l''eau frémissante puis poêlé sans fécule (homenaturallymade)','Tofu enrobé et cuit à la friteuse à air, 4 à 8 minutes à 190 °C (woonheng)','Une part de sauce soja foncée pour la couleur, une cuillerée et demie à soupe (homenaturallymade, browngirlveganeats)','Finition en marmite de terre, tofu et basilic couverts deux minutes sur feu doux pour un fond légèrement grillé (woonheng)','Piments séchés à la place du piment frais (thefoodietakesflight)','Ciboule ciselée ajoutée avec le basilic (thefoodietakesflight, woonheng)','Liaison finale à la fécule délayée, une cuillerée à soupe dans un peu d''eau (browngirlveganeats)']::text[], ARRAY['soja','sésame']::text[],
    'Se garde 3 jours au réfrigérateur, et c''est le seul plat de ce lot qui perd au deuxième jour plutôt que d''y gagner : la peau de fécule se détend dans la sauce et le basilic vire au brun. Aucune page du dossier ne parle de conservation — les quatre disent de servir aussitôt — et ce qui est écrit ici est donc ce que fait physiquement le plat : le glaçage tient à la fécule, qui se réhydrate au froid. Ne se congèle pas : le tofu poêlé et sauté devient spongieux à la décongélation et rend l''eau qu''il a rendue, ce qui délave la sauce. Réchauffer trois minutes à la poêle à feu vif, à découvert, pour reprendre un peu de glaçage, et jeter cinq feuilles de basilic frais au dernier moment — c''est ce qui rattrape le mieux un reste.', '{"fridge_hours":72,"eat_immediately":true,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'REAL-210'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
