  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Égoutter le tofu, l''éponger et le détailler en tranches d''un centimètre d''épaisseur. Épaisseur régulière et non dés minuscules : chaque face doit pouvoir dorer à plat, et un dé de tofu n''a que des arêtes qui cassent quand on le retourne.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Rouler chaque tranche dans la fécule et tapoter pour n''en garder qu''un voile. C''est ce voile qui remplace la peau du poulet de la recette d''origine : il forme à la cuisson une pellicule qui retient la sauce au lieu de la laisser glisser, et sans lui le tofu ressort pâle et la sauce reste au fond de la casserole.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chauffer l''huile de colza dans une grande poêle antiadhésive à feu moyen-vif et dorer les tranches deux à trois minutes par face, en deux fournées plutôt qu''en une. Une poêle chargée retombe en température, la fécule boit alors l''huile au lieu de sécher, et l''on obtient un tofu gras et mou. Réserver sur une grille.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Vider l''huile de friture de la poêle, l''essuyer et y verser l''huile de sésame grillé sur feu doux. Cette huile ne supporte pas la chaleur vive — c''est une huile de parfum, pas une huile de cuisson — et elle devient amère si on la fume, ce qui coûterait au plat un de ses trois piliers.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Faire blondir doucement dans le sésame les gousses d''ail entières épluchées et le gingembre en fines lamelles, deux à trois minutes, jusqu''à ce que les gousses dorent sur leurs faces. L''ail entier fond et devient sucré ; haché il brûlerait dans le même temps et donnerait un fond âcre à toute la sauce.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Verser la sauce soja légère, le vin de riz et le sucre candi, ajouter le piment fendu et six cuillerées à soupe d''eau, et laisser bouillonner deux minutes pour dissoudre le sucre. L''eau n''est pas une quatrième tasse : elle donne à la réduction le temps de se faire sans que le soja ne devienne salant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Remettre le tofu doré dans la poêle, le retourner plusieurs fois dans la sauce et laisser réduire huit à dix minutes à découvert, à feu moyen, jusqu''à ce que la sauce nappe et brille. C''est le glaçage qui fait le plat : tant qu''il reste du liquide clair au fond, ce n''est pas fini, et si la sauce colle avant que le tofu ne soit enrobé, ajouter deux cuillerées d''eau plutôt que de baisser trop tôt.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Couper le feu, jeter le basilic thaï en une fois et remuer trois ou quatre fois sous le couvercle avant de servir aussitôt. Le basilic doit tomber dans une casserole hors du feu : cuit, il noircit et perd en trente secondes l''arôme anisé qui est la signature du plat, et c''est la faute la plus fréquente sur un trois-tasses.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-092', 'recipe_family', 'San bei doufu',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-092', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Tofu congelé puis décongelé et essoré, cassé en gros morceaux irréguliers plutôt que tranché (thefoodietakesflight)','Tofu blanchi cinq minutes à l''eau frémissante puis poêlé sans fécule (homenaturallymade)','Tofu enrobé et cuit à la friteuse à air, 4 à 8 minutes à 190 °C (woonheng)','Une part de sauce soja foncée pour la couleur, une cuillerée et demie à soupe (homenaturallymade, browngirlveganeats)','Finition en marmite de terre, tofu et basilic couverts deux minutes sur feu doux pour un fond légèrement grillé (woonheng)','Piments séchés à la place du piment frais (thefoodietakesflight)','Ciboule ciselée ajoutée avec le basilic (thefoodietakesflight, woonheng)','Liaison finale à la fécule délayée, une cuillerée à soupe dans un peu d''eau (browngirlveganeats)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-092","variants":["Tofu congelé puis décongelé et essoré, cassé en gros morceaux irréguliers plutôt que tranché (thefoodietakesflight)","Tofu blanchi cinq minutes à l''eau frémissante puis poêlé sans fécule (homenaturallymade)","Tofu enrobé et cuit à la friteuse à air, 4 à 8 minutes à 190 °C (woonheng)","Une part de sauce soja foncée pour la couleur, une cuillerée et demie à soupe (homenaturallymade, browngirlveganeats)","Finition en marmite de terre, tofu et basilic couverts deux minutes sur feu doux pour un fond légèrement grillé (woonheng)","Piments séchés à la place du piment frais (thefoodietakesflight)","Ciboule ciselée ajoutée avec le basilic (thefoodietakesflight, woonheng)","Liaison finale à la fécule délayée, une cuillerée à soupe dans un peu d''eau (browngirlveganeats)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-092', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('e4c524fd1fd6c3bf125c8894ab9c5013'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"spicy_umami","scores":{"sweet":2,"salty":4,"acidic":1,"bitter":1,"umami":5,"heat":2,"pungency":3,"richness":4,"freshness":3,"intensity":4},"dominant_flavors":["sésame grillé","soja fermenté","basilic thaï","ail confit"],"aroma_families":["sésame_toasté","soja_fermenté","basilic","ail","gingembre"],"target_textures":["tofu_glacé","peau_de_fécule","ail_fondant","basilic_frais"],"signature_ingredients":["Tofu ferme","Huile de sésame grillé","Sauce soja légère","Vin de riz taïwanais"],"identity_guardrails":["Volumes égaux d''huile de sésame, de sauce soja et de vin de riz : c''est le nom du plat, et le déséquilibrer lui fait perdre son identité","L''huile de sésame ne chauffe jamais vivement, sous peine d''amertume","Le tofu se dore à part avant la sauce : il n''a ni peau ni gras pour se colorer dedans","L''ail reste en gousses entières, jamais haché","Le basilic entre hors du feu, en une fois, et le plat part à table dans la minute"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Salade César aux pois chiches rôtis', 'salade cesar aux pois chiches rotis', 'États-Unis / Mexique', 'États-Unis / Mexique',
     'meal', 'salade complète', 'named_traditional_dish', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Salade César aux pois chiches rôtis', 'La César sans poulet : romaine, croûtons de pain frottés à l''ail et pois chiches rôtis au paprika, liés d''une sauce montée au jaune d''œuf, moutarde et parmesan', ds.id, 'JUM-093',
    'Myko', 'editorial', 4, 20, 30, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '0735d0a95cfa9b2c309f7423a56dc0e2',
    '{"sweet":1,"salty":4,"acidic":3,"bitter":1,"umami":3,"heat":1,"pungency":3,"richness":5,"freshness":3,"intensity":4}'::jsonb, ARRAY['parmesan','moutarde','citron','paprika fumé']::text[],
    ARRAY['fromage_affiné','moutarde','agrume','fumé','grillé']::text[], ARRAY['feuilles croquantes','pois chiches croustillants','pain croustillant','crémeux']::text[],
    ARRAY['Pois chiche cuit, égoutté','Laitue fraîche','Parmesan affiné','Jaune d''œuf cru']::text[], ARRAY['La sauce se monte au jaune d''œuf comme une mayonnaise : une vinaigrette n''en est pas une','Les pois chiches sont séchés puis rôtis jusqu''au croquant — versés mous, ils ne remplacent rien','Romaine et non mesclun : c''est la nervure croquante qui tient la sauce','On assemble au dernier moment, sinon feuilles, croûtons et pois chiches s''affaissent ensemble','Aucun anchois ni sauce Worcestershire d''anchois : c''est ce qui fait de cette César un jumeau végétarien']::text[],
    ARRAY['rôtissage à sec','croûtons au four','émulsion au jaune d''œuf','assemblage au dernier moment']::text[], ARRAY['Sauce sur une mayonnaise du commerce allongée de yaourt grec, un tiers de tasse de chacun (planbouffe)','Sauce végane à la crème de soja et aux câpres écrasées, sans jaune d''œuf, avec du parmesan végane (patateetcornichon)','Vinaigre de vin rouge à la place du jus de citron, deux cuillerées à soupe (soscuisine)','Cinq gouttes de Tabasco dans la sauce (soscuisine)','Carottes râpées ou en spirales, trois moyennes, mélangées à la laitue (planbouffe)','Tranches d''avocat ajoutées à la dernière minute (planbouffe)','Zeste d''un citron sur les pois chiches avant rôtissage (planbouffe)','Câpres, une cuillerée à soupe écrasée à la fourchette dans la sauce (patateetcornichon)','Sans croûtons de pain, les pois chiches rôtis tenant seuls le rôle du croquant (planbouffe)']::text[], ARRAY['gluten','œuf','lait','moutarde']::text[],
    'Assemblée, elle ne se garde pas : compter vingt minutes avant que les croûtons et les pois chiches ramollissent au contact de la sauce. Chaque élément se prépare en revanche d''avance, et une des trois pages du dossier est écrite pour cela : elle répartit salade, garniture et vinaigrette dans des boîtes à emporter, la sauce à part, et les pois chiches rôtis par-dessus au dernier moment. Elle ne donne aucune durée, et AUCUNE page du dossier n''en donne — ce qui suit est donc une déduction, écrite comme telle : la sauce 2 jours au réfrigérateur, borne fixée par ses deux jaunes crus et non par son goût ; les croûtons 3 jours en boîte hermétique à température ambiante ; les pois chiches rôtis 2 à 3 jours dans un récipient laissé entrouvert, un couvercle fermé les faisant transpirer et leur reprenant en une nuit le croquant qu''une heure de four leur a donné. Le montage prend alors cinq minutes. La sauce porte deux jaunes crus : 48 heures au maximum, et à écarter pour les publics sensibles. Ne se congèle pas, et pas parce que ce serait risqué : la laitue gèle en cellules éclatées et ressort en chiffon, la sauce émulsionnée tranche.', '{"fridge_hours":48,"eat_immediately":true,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'RAP-027'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
