  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Rincer les pois chiches, les égoutter et les rouler longuement dans un torchon jusqu''à ce qu''ils soient parfaitement secs, en ôtant au passage les peaux qui se détachent. C''est l''étape qui décide de tout le reste : un pois chiche humide cuit à la vapeur de sa propre eau au lieu de rôtir, et il ressort mou après une heure de four comme après quinze minutes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Les étaler sur une plaque, les enrober de deux cuillerées à soupe d''huile prélevées sur le total, du paprika fumé et d''une pincée de sel, et les rôtir 30 minutes à 200 °C en secouant la plaque toutes les dix minutes. Ils doivent sonner sec sous la cuillère et non rester tendres au centre : c''est ce croquant qui remplace, dans l''assiette, la mâche du poulet grillé de la recette d''origine.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Couper le pain en cubes de deux centimètres, croûte comprise, les arroser d''une cuillerée d''huile et les faire dorer dix minutes au four à côté des pois chiches. Les frotter chauds avec la moitié d''une gousse d''ail crue : l''ail fond au contact du pain brûlant et parfume sans jamais brûler, ce qu''il ferait si on l''ajoutait avant la cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Monter la sauce comme une mayonnaise : les deux jaunes d''œuf, la moutarde, le reste de l''ail réduit en purée, le sel et le poivre dans un bol, fouettés vingt secondes, puis l''huile restante versée goutte à goutte au début et en filet ensuite, sans cesser de fouetter. Elle doit devenir ferme et pâle avant qu''on la détende.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'La détendre avec le jus de citron et la moitié du parmesan finement râpé. Elle doit napper la cuillère en coulant lentement : trop épaisse, elle colle en paquets sur les feuilles au lieu de les enrober, et l''allonger d''une cuillerée d''eau froide vaut mieux que d''ajouter du citron, qui déséquilibrerait l''acidité.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Laver et essorer soigneusement la romaine, puis la déchirer à la main en larges morceaux plutôt que de la couper au couteau — la lame oxyde les nervures, qui brunissent en une heure. L''essorage compte autant : une feuille mouillée repousse la sauce, qui glisse au fond du saladier.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Assembler au dernier moment : verser les deux tiers de la sauce sur la salade, mélanger longuement pour enrober chaque feuille, puis ajouter les croûtons, les pois chiches rôtis et le reste de sauce. Finir par les copeaux de parmesan taillés à l''économe. Montée à l''avance, cette César a des croûtons mous et des pois chiches ramollis en vingt minutes — les pois chiches encore plus vite que le pain, parce que leur croûte est plus fine.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-093', 'recipe_family', 'Salade César aux pois chiches rôtis',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-093', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Sauce sur une mayonnaise du commerce allongée de yaourt grec, un tiers de tasse de chacun (planbouffe)','Sauce végane à la crème de soja et aux câpres écrasées, sans jaune d''œuf, avec du parmesan végane (patateetcornichon)','Vinaigre de vin rouge à la place du jus de citron, deux cuillerées à soupe (soscuisine)','Cinq gouttes de Tabasco dans la sauce (soscuisine)','Carottes râpées ou en spirales, trois moyennes, mélangées à la laitue (planbouffe)','Tranches d''avocat ajoutées à la dernière minute (planbouffe)','Zeste d''un citron sur les pois chiches avant rôtissage (planbouffe)','Câpres, une cuillerée à soupe écrasée à la fourchette dans la sauce (patateetcornichon)','Sans croûtons de pain, les pois chiches rôtis tenant seuls le rôle du croquant (planbouffe)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-093","variants":["Sauce sur une mayonnaise du commerce allongée de yaourt grec, un tiers de tasse de chacun (planbouffe)","Sauce végane à la crème de soja et aux câpres écrasées, sans jaune d''œuf, avec du parmesan végane (patateetcornichon)","Vinaigre de vin rouge à la place du jus de citron, deux cuillerées à soupe (soscuisine)","Cinq gouttes de Tabasco dans la sauce (soscuisine)","Carottes râpées ou en spirales, trois moyennes, mélangées à la laitue (planbouffe)","Tranches d''avocat ajoutées à la dernière minute (planbouffe)","Zeste d''un citron sur les pois chiches avant rôtissage (planbouffe)","Câpres, une cuillerée à soupe écrasée à la fourchette dans la sauce (patateetcornichon)","Sans croûtons de pain, les pois chiches rôtis tenant seuls le rôle du croquant (planbouffe)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-093', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('0735d0a95cfa9b2c309f7423a56dc0e2'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":4,"acidic":3,"bitter":1,"umami":3,"heat":1,"pungency":3,"richness":5,"freshness":3,"intensity":4},"dominant_flavors":["parmesan","moutarde","citron","paprika fumé"],"aroma_families":["fromage_affiné","moutarde","agrume","fumé","grillé"],"target_textures":["feuilles croquantes","pois chiches croustillants","pain croustillant","crémeux"],"signature_ingredients":["Pois chiche cuit, égoutté","Laitue fraîche","Parmesan affiné","Jaune d''œuf cru"],"identity_guardrails":["La sauce se monte au jaune d''œuf comme une mayonnaise : une vinaigrette n''en est pas une","Les pois chiches sont séchés puis rôtis jusqu''au croquant — versés mous, ils ne remplacent rien","Romaine et non mesclun : c''est la nervure croquante qui tient la sauce","On assemble au dernier moment, sinon feuilles, croûtons et pois chiches s''affaissent ensemble","Aucun anchois ni sauce Worcestershire d''anchois : c''est ce qui fait de cette César un jumeau végétarien"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Aubergines panées', 'aubergines panees', 'Italie', 'Italie',
     'meal', 'légume pané', 'named_traditional_dish', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Aubergines panées', 'Tranches d''aubergine dégorgées au gros sel, panées à l''anglaise dans une chapelure au parmesan et dorées à la poêle, servies chaudes', ds.id, 'JUM-094',
    'Myko', 'editorial', 4, 25, 15, 'facile',
    NULL, NULL,
    'B', 'candidate', 'f349264c000d0505c4a45c0af2ab102d',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":3,"heat":0,"pungency":0,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['aubergine fondante','parmesan','pain grillé']::text[],
    ARRAY['fromage affiné','pain grillé','huile d''olive','légume rôti']::text[], ARRAY['croûte croustillante','cœur fondant','contraste_fort']::text[],
    ARRAY['Aubergine fraîche','Chapelure de blé','Parmesan affiné']::text[], ARRAY['Les tranches se dégorgent au gros sel puis se rincent : sans cela l''eau de l''aubergine décolle la panure dans la poêle','Panure à l''anglaise en trois temps, farine comprise — sans farine la croûte se détache et le plat n''existe plus','Une tranche d''un demi-centimètre : plus épaisse elle reste crue au centre, plus fine elle s''effondre en pâte','Panées et frites, jamais gratinées à la tomate — ce serait une parmigiana, qui est un autre plat du corpus','Le sel entre dans la chapelure et non sur le légume, qui sort déjà salé du dégorgeage']::text[],
    ARRAY['dégorgeage au gros sel','panure à l''anglaise','repos','friture à la poêle']::text[], ARRAY['Double panure — chapelure, œuf, chapelure de nouveau — pour une croûte plus épaisse (misya, tortelliniandco)','Au four, 20 minutes à 190 °C, retournées à mi-cuisson et arrosées d''huile d''olive sur chaque face (tortelliniandco, marmiton)','À la friteuse à air, 15 minutes à 190 °C (marmiton)','Panure au persil haché et à une demi-gousse d''ail (ilcuoreinpentola, marmiton)','Œufs battus avec cinq cuillerées à soupe de lait à la place des œufs seuls (marmiton)','Sans parmesan dans la chapelure (giallozafferano, tortelliniandco)','Panure enrichie de cinquante grammes de poudre d''amande (chefsimon)','Courgettes taillées de la même façon et panées avec les aubergines, moitié-moitié (marmiton)','Servies avec une sauce tomate chaude et de la semoule (marmiton)','Origan séché dans la chapelure, une cuillerée à café (750g)']::text[], ARRAY['gluten','œuf','lait']::text[],
    'Se mangent dans les minutes qui suivent la poêle : la panure ramollit encore plus vite que sur une escalope, l''aubergine continuant de rendre de la vapeur par en dessous. Une page italienne le dit en toutes lettres — gardées couvertes et au chaud, elles restent bonnes mais perdent leur croûte. Les restes se gardent 2 jours au réfrigérateur, à plat et jamais empilés, et se réchauffent 8 minutes au four à 180 °C posés sur une grille ; le micro-ondes est à proscrire, il rend la croûte élastique. Ne se congèlent pas cuites, pour une raison propre au légume et non à la panure : l''eau que l''aubergine garde en cellules gèle en cristaux qui crèvent sa chair, et la tranche ressort en purée sous une croûte intacte. Panées crues, elles se congèlent en revanche 2 mois séparées par du papier cuisson et se cuisent sans décongélation en allongeant de trois minutes par face — c''est ce que fait la fiche parente avec ses escalopes, et la physique est ici la même puisque c''est la panure qui tient le gel.', '{"fridge_hours":48,"eat_immediately":true,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'VAR-003'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'aubergine fraiche' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Aubergine fraîche', 500, 'g', 'required',
     'légume', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'chapelure de ble' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Chapelure de blé', 100, 'g', 'required',
     'panure', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'parmesan affine' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Parmesan affiné', 50, 'g', 'required',
     'panure', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'farine de ble t55' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Farine de blé T55', 50, 'g', 'required',
     'panure', false, 4);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'oeuf cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Œuf cru', 2, 'u', 'required',
     'panure', false, 5);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'huile d olive vierge extra' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Huile d''olive vierge extra', 40, 'ml', 'required',
     'cuisson', false, 6);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 6, 'g', 'required',
     'assaisonnement', false, 7);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'required',
     'assaisonnement', false, 8);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Laver les aubergines, ôter le pédoncule et les couper en tranches d''un demi-centimètre d''épaisseur régulière, dans le sens de la longueur ou de la largeur selon la forme du légume. Écarter les deux tranches extérieures, presque entièrement peau : elles ne cuisent pas comme les autres et restent coriaces sous la panure.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Ranger les tranches en couches dans une passoire en salant chaque étage de gros sel, poser une assiette et un poids dessus, et laisser dégorger une heure. C''est ce qui remplace l''aplatissement de l''escalope dans la recette d''origine : l''aubergine est une éponge, et l''eau qu''elle ne rend pas maintenant, elle la rendra sous la panure, qu''elle décollera.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Rincer abondamment les tranches à l''eau froide pour ôter tout le sel, puis les éponger entre deux torchons en pressant. Ne pas rincer laisserait un plat immangeable de sel ; ne pas sécher rendrait la farine collante et la panure irrégulière.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Préparer trois assiettes creuses : la farine dans la première, les œufs battus à la fourchette avec le poivre dans la deuxième, la chapelure mélangée au parmesan finement râpé et au sel fin dans la troisième. Le sel va dans la chapelure et non sur l''aubergine, à l''inverse de ce que demande une viande : les tranches sortent du dégorgeage déjà légèrement salées, et les resaler donnerait un plat immangeable.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Passer chaque tranche dans la farine en tapotant pour ôter l''excédent, puis dans l''œuf, puis dans le mélange chapelure-parmesan en appuyant franchement de la paume. La farine sèche la surface pour que l''œuf s''y accroche ; sans elle la panure se décolle en cuisant et il reste une tranche nue au milieu d''une croûte flottante.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Laisser les tranches panées reposer un quart d''heure au frais sur une grille. L''humidité de l''œuf gélifie la chapelure et la soude au légume ; une tranche cuite dans la foulée perd la moitié de sa croûte dans la poêle, et l''aubergine tient encore moins la panure qu''une escalope, faute de fibres pour l''accrocher.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Chauffer l''huile d''olive dans une grande poêle à feu moyen et cuire les tranches en deux fournées, trois à quatre minutes de chaque côté, sans les entasser ni les déplacer pendant la première moitié du temps. La poêle chargée refroidit, la panure boit alors le gras au lieu de le repousser, et l''aubergine ressort grasse et molle. Ajouter un filet d''huile entre les fournées, jamais pendant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Égoutter deux minutes sur une grille — jamais sur du papier absorbant, qui retient la vapeur sous la tranche et ramollit le dessous — et servir aussitôt, chaud ou tiède. C''est un plat qui ne supporte pas l''attente : la vapeur que l''aubergine continue de rendre traverse la croûte de l''intérieur.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-094', 'recipe_family', 'Aubergines panées',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-094', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Double panure — chapelure, œuf, chapelure de nouveau — pour une croûte plus épaisse (misya, tortelliniandco)','Au four, 20 minutes à 190 °C, retournées à mi-cuisson et arrosées d''huile d''olive sur chaque face (tortelliniandco, marmiton)','À la friteuse à air, 15 minutes à 190 °C (marmiton)','Panure au persil haché et à une demi-gousse d''ail (ilcuoreinpentola, marmiton)','Œufs battus avec cinq cuillerées à soupe de lait à la place des œufs seuls (marmiton)','Sans parmesan dans la chapelure (giallozafferano, tortelliniandco)','Panure enrichie de cinquante grammes de poudre d''amande (chefsimon)','Courgettes taillées de la même façon et panées avec les aubergines, moitié-moitié (marmiton)','Servies avec une sauce tomate chaude et de la semoule (marmiton)','Origan séché dans la chapelure, une cuillerée à café (750g)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-094","variants":["Double panure — chapelure, œuf, chapelure de nouveau — pour une croûte plus épaisse (misya, tortelliniandco)","Au four, 20 minutes à 190 °C, retournées à mi-cuisson et arrosées d''huile d''olive sur chaque face (tortelliniandco, marmiton)","À la friteuse à air, 15 minutes à 190 °C (marmiton)","Panure au persil haché et à une demi-gousse d''ail (ilcuoreinpentola, marmiton)","Œufs battus avec cinq cuillerées à soupe de lait à la place des œufs seuls (marmiton)","Sans parmesan dans la chapelure (giallozafferano, tortelliniandco)","Panure enrichie de cinquante grammes de poudre d''amande (chefsimon)","Courgettes taillées de la même façon et panées avec les aubergines, moitié-moitié (marmiton)","Servies avec une sauce tomate chaude et de la semoule (marmiton)","Origan séché dans la chapelure, une cuillerée à café (750g)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-094', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('f349264c000d0505c4a45c0af2ab102d'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":3,"heat":0,"pungency":0,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["aubergine fondante","parmesan","pain grillé"],"aroma_families":["fromage affiné","pain grillé","huile d''olive","légume rôti"],"target_textures":["croûte croustillante","cœur fondant","contraste_fort"],"signature_ingredients":["Aubergine fraîche","Chapelure de blé","Parmesan affiné"],"identity_guardrails":["Les tranches se dégorgent au gros sel puis se rincent : sans cela l''eau de l''aubergine décolle la panure dans la poêle","Panure à l''anglaise en trois temps, farine comprise — sans farine la croûte se détache et le plat n''existe plus","Une tranche d''un demi-centimètre : plus épaisse elle reste crue au centre, plus fine elle s''effondre en pâte","Panées et frites, jamais gratinées à la tomate — ce serait une parmigiana, qui est un autre plat du corpus","Le sel entre dans la chapelure et non sur le légume, qui sort déjà salé du dégorgeage"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Empanadas aux lentilles', 'empanadas aux lentilles', 'Argentine', 'Argentine',
     'meal', 'chaussons', 'named_traditional_dish', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Empanadas aux lentilles', 'Chaussons argentins de pâte à l''huile d''olive, farcis d''un sofrito d''oignon au cumin et au paprika lié de lentilles brunes fondantes, avec des olives vertes, et cuits au four', ds.id, 'JUM-095',
    'Myko', 'editorial', 6, 60, 30, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'c231dacb5f52a683a9e6754d8b521d1e',
    '{"sweet":2,"salty":3,"acidic":1,"bitter":1,"umami":3,"heat":1,"pungency":2,"richness":3,"freshness":1,"intensity":4}'::jsonb, ARRAY['cumin','paprika','oignon compoté','olive']::text[],
    ARRAY['cumin','paprika','oignon_compoté','olive','pâte_cuite']::text[], ARRAY['pâte_croustillante','farce_fondante_et_morceaux']::text[],
    ARRAY['Lentille brune sèche, crue','Farine de blé T55','Oignon jaune cru','Olive verte dénoyautée']::text[], ARRAY['La graisse de la pâte est végétale : le saindoux de la fiche parente est précisément ce qu''un jumeau végétarien ne peut pas garder','Les lentilles se cuisent un peu trop, jusqu''à se tenir à la cuillère — fermes, elles percent la pâte au façonnage','La farce entre froide dans les disques, jamais tiède','Sofrito d''oignon au cumin et au paprika, pas de sauce tomate : c''est ce qui sépare l''empanada argentine de toutes les autres','Repulgue ou bord écrasé à la fourchette, et pas de bulle d''air enfermée']::text[],
    ARRAY['trempage','pâte à l''huile','sofrito','refroidissement de la farce','repulgue','cuisson au four']::text[], ARRAY['Pommes de terre bouillies en petits dés dans la farce, quatre pour douze empanadas (lanacion)','Farine complète à la place de la farine blanche (lanacion)','Trois sortes d''oignons — cébette, oignon blanc, oignon rouge — au lieu du seul oignon jaune (nomadasgourmet)','Raisins secs, une cuillerée à soupe pour douze, à ajouter avec les olives (nomadasgourmet)','Dorure à l''eau colorée au paprika, deux cuillerées d''eau pour un quart de cuillerée à café (nomadasgourmet)','Graines de sésame et deux feuilles de basilic frais dans la farce (receta-vegetariana)','Farine de maïs à la place de la farine de blé pour la pâte (receta-vegetariana)','Chaussons frits plutôt que cuits au four (receta-vegetariana)','Cuisson à four très chaud, 230 °C pendant 15 minutes (nomadasgourmet)']::text[], ARRAY['gluten']::text[],
    'Se gardent 3 jours au réfrigérateur dans une boîte, et se réchauffent 10 minutes au four à 180 °C, jamais au micro-ondes qui détrempe la pâte. Aucune des trois pages ne parle de congélation ; ce que fait ce type de chausson est en revanche connu et vaut d''être écrit comme une déduction et non comme une consigne des sources : une empanada crue, farcie et fermée, se congèle 3 mois à plat sur une plaque puis en sac, et se cuit sans décongélation en ajoutant cinq à huit minutes de four — c''est de loin le meilleur usage, la pâte crue n''ayant encore rien perdu. Cuites, elles se congèlent aussi 2 mois mais ressortent avec une pâte plus sableuse. La farce seule se garde 3 jours au froid et gagne au deuxième jour, le cumin ayant fini de se répartir : c''est elle qu''il vaut mieux préparer d''avance quand on veut étaler le travail sur deux soirs.', '{"fridge_hours":72,"eat_immediately":false,"freezable":true,"freezer_months":2,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'REAL-280'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
