  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 8, 'g', 'required',
     'assaisonnement', false, 15);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 2, 'g', 'required',
     'assaisonnement', false, 16);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Débarrasser les champignons de leur terre avec un papier absorbant humide, sans jamais les passer sous le robinet, puis les tailler au couteau en morceaux d''un demi-centimètre. Un champignon rincé se gorge d''eau qu''il rendra dans la poêle au lieu de colorer ; taillé trop fin il disparaît dans le riz, taillé trop gros il fait un point dur qui ouvre la boule au moment de la frire.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Chauffer l''huile d''olive à feu vif dans une grande poêle, y verser les champignons et les laisser deux minutes sans y toucher avant de les faire sauter cinq à six minutes, jusqu''à ce que leur eau soit entièrement partie et que les bords commencent à brunir. C''est ce moment qui remplace le brunissement de la viande dans le ragù du parent : tant que l''eau est là, la poêle plafonne à cent degrés et rien ne caramélise — un champignon pâle donnera un arancino fade, quelle que soit la suite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Baisser le feu à moyen, ajouter l''oignon haché finement et le laisser fondre trois minutes, puis l''ail écrasé pour une minute de plus. L''ail vient après l''oignon parce qu''il brûle deux fois plus vite et qu''une pointe d''amertume à ce stade traverse tout le plat. Ajouter le persil ciselé hors du feu, saler de moitié, poivrer, débarrasser dans un plat et laisser tiédir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Porter le bouillon de légumes à petits frémissements avec le safran et le reste du sel, y verser le riz d''un seul coup, donner un tour de cuillère et couvrir. Cuire à feu très doux vingt minutes environ, sans remuer, jusqu''à ce que tout le liquide soit bu. On ne mouille pas louche à louche comme pour un risotto : le riz d''un arancino doit finir sec et collant, faute de quoi il ne se tiendra pas dans la paume.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Cinq minutes avant la fin, disperser les petits pois encore glacés à la surface du riz et refermer aussitôt le couvercle. Ils finissent à la vapeur du riz et gardent leur couleur, là où une casserole d''eau bouillante les délaverait et les gorgerait à leur tour d''eau — or tout ce qui apporte de l''eau à ce stade se paiera au façonnage.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Verser le riz sur une plaque, l''étaler en couche mince, y mêler les champignons refroidis à la spatule, et laisser prendre l''air au moins deux heures sans rien poser dessus. Le refroidissement n''est pas une pause : un riz couvert condense et redevient humide, un riz encore tiède fera fondre la mozzarella bien avant l''huile.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Couper la mozzarella en cubes d''un centimètre et les laisser s''égoutter dix minutes sur du papier. Huiler légèrement la paume, y déposer une grosse poignée de riz froid, l''aplatir à un centimètre d''épaisseur, creuser un puits, y loger trois cubes de fromage, puis refermer le riz par-dessus et serrer jusqu''à obtenir une boule lisse — huit boules pour huit parts. La moindre fissure et le fromage s''échappera dans l''huile.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Aligner trois assiettes creuses : la farine, les œufs battus à la fourchette, la chapelure. Rouler chaque boule dans la farine, la tremper dans l''œuf en laissant l''excédent s''égoutter, puis la couvrir de chapelure en pressant du plat de la main. La farine sèche la surface pour que l''œuf s''y accroche ; sans elle la panure glisse sur le riz humide et s''ouvre à la cuisson. Laisser les boules panées un quart d''heure au froid.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Porter un litre et demi d''huile à 170 °C dans une casserole haute et étroite, et frire deux boules à la fois, cinq minutes environ, jusqu''à un brun uniforme. Égoutter sur du papier et attendre deux minutes avant de servir : le cœur sort à une température qui brûle. Plus chaude, l''huile dore la panure avant que le fromage n''ait fondu ; plus froide, la panure la boit et l''arancino sort gras.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-101', 'recipe_family', 'Arancini aux champignons',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-101', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Riz monté en risotto — nacré à l''huile, mouillé louche à louche — plutôt que cuit par absorption (sugarsaltmagic, nodashofgluten, ricettechepassione, saq)','Vin blanc sec pour déglacer avant le bouillon, un demi-verre pour 500 g de riz (nodashofgluten, ricettechepassione, lepassionidima, saq)','Cèpes séchés réhydratés, dont l''eau de trempage filtrée rejoint le bouillon, 5 g pour 145 g de riz (sugarsaltmagic) ou 125 ml de bolets séchés (saq)','Farce liée à une béchamel aux champignons plutôt que champignons mêlés au riz, 150 g de béchamel pour 500 g de riz (ilcaldosaporedelsud, tuorlorosso)','Pâte à frire de farine et d''eau à la place de l''œuf pour la panure (ilcaldosaporedelsud, ricettechepassione)','Double friture, quatre à cinq minutes deux fois, pour une croûte plus résistante (ilcaldosaporedelsud)','Servi avec une sauce tomate rôtie au thym et au vinaigre balsamique (simply-delicious-food), une marinara (nodashofgluten) ou une sauce tomate épicée (saq)','Cœur de caciotta, de provola ou d''emmental à la place de la mozzarella, que deux pages jugent trop peu goûteuse (ilcaldosaporedelsud)','Mélange de champignons — pleurotes, cardoncelli, portobello — plutôt que champignons de Paris seuls (lepassionidima, ilcaldosaporedelsud)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-101","variants":["Riz monté en risotto — nacré à l''huile, mouillé louche à louche — plutôt que cuit par absorption (sugarsaltmagic, nodashofgluten, ricettechepassione, saq)","Vin blanc sec pour déglacer avant le bouillon, un demi-verre pour 500 g de riz (nodashofgluten, ricettechepassione, lepassionidima, saq)","Cèpes séchés réhydratés, dont l''eau de trempage filtrée rejoint le bouillon, 5 g pour 145 g de riz (sugarsaltmagic) ou 125 ml de bolets séchés (saq)","Farce liée à une béchamel aux champignons plutôt que champignons mêlés au riz, 150 g de béchamel pour 500 g de riz (ilcaldosaporedelsud, tuorlorosso)","Pâte à frire de farine et d''eau à la place de l''œuf pour la panure (ilcaldosaporedelsud, ricettechepassione)","Double friture, quatre à cinq minutes deux fois, pour une croûte plus résistante (ilcaldosaporedelsud)","Servi avec une sauce tomate rôtie au thym et au vinaigre balsamique (simply-delicious-food), une marinara (nodashofgluten) ou une sauce tomate épicée (saq)","Cœur de caciotta, de provola ou d''emmental à la place de la mozzarella, que deux pages jugent trop peu goûteuse (ilcaldosaporedelsud)","Mélange de champignons — pleurotes, cardoncelli, portobello — plutôt que champignons de Paris seuls (lepassionidima, ilcaldosaporedelsud)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-101', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('d22b1b3e02730c4194ff978c44cd0496'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":3,"acidic":1,"bitter":1,"umami":4,"heat":1,"pungency":2,"richness":4,"freshness":2,"intensity":4},"dominant_flavors":["champignon rôti","croustillant","safran"],"aroma_families":["champignon","ail","safran","persil","mozzarella","riz_frit"],"target_textures":["croûte_croustillante","riz_moelleux","cœur_fondant"],"signature_ingredients":["Riz arborio cru","Champignon de Paris frais","Mozzarella","Safran"],"identity_guardrails":["Les champignons se poêlent jusqu''à ce que leur eau soit partie : humides, ils détrempent le riz et la boule s''ouvre dans l''huile","Le riz se cuit par absorption et refroidit à découvert au moins deux heures — c''est ce qui le rend moulable, et rien ne remplace ce temps","Le cœur de mozzarella et la panure font l''arancino : sans farce centrale, c''est une boulette de riz","Le bouillon est de légumes, jamais de volaille — c''est ce qui distingue ce jumeau de sa base carnée","Le safran teint le riz du parent et reste : un arancino blanc n''est plus sicilien"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Croquetas de champignons', 'croquetas de champignons', 'Espagne', 'Espagne',
     'meal', 'tapas frits', 'named_traditional_dish', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Croquetas de champignons', 'Croquettes espagnoles à la béchamel très épaisse, où les champignons poêlés à sec remplacent le jambon serrano ; panées, frites, coulantes à cœur.', ds.id, 'JUM-102',
    'Myko', 'editorial', 8, 40, 30, 'difficile',
    NULL, NULL,
    'B', 'candidate', '8c001d60e67b1457584d2e690d9c85b2',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":4,"heat":1,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['champignon','beurre','muscade']::text[],
    ARRAY['champignon','beurre','béchamel','noix_muscade']::text[], ARRAY['croûte_croustillante','cœur_très_crémeux']::text[],
    ARRAY['Champignon de Paris frais','Lait entier','Farine de blé T55','Beurre doux']::text[], ARRAY['Les champignons sont poêlés à sec jusqu''à évaporation complète avant d''entrer dans la béchamel : sinon la masa ne prend jamais','La béchamel est très épaisse et refroidie quatre heures au minimum — c''est elle, et non la friture, qui fait la croqueta','Le cœur doit rester coulant à la sortie de l''huile : une croqueta ferme à cœur est une croqueta ratée','Panure et friture en bain profond, jamais au four : la croûte fine est ce qui tient le cœur liquide']::text[],
    ARRAY['sauté','roux','béchamel','refroidissement','façonnage','panure','friture']::text[], ARRAY['Mélange de bolets et de portobellos à la place du champignon de Paris, moitié-moitié (paulasapron)','Champignons surgelés, dont l''eau de décongélation remplace une partie du lait dans la béchamel (paulasapron)','Sauce soja et une cuillerée de vinaigre balsamique dans la masa, pour renforcer l''umami (comeztier)','Ail haché à la place de l''oignon, une gousse pour 500 ml de lait, avec du persil (okdiario)','Poivre blanc plutôt que noir, pour ne pas moucheter une béchamel claire (paulasapron)','Masa passée au mixeur plongeant avant le repos, pour une texture entièrement lisse (comeztier)','Passage à la farine avant l''œuf et la chapelure, soit une panure en trois temps (comeztier, paulasapron)','Servies avec une confiture de tomate et des copeaux de fromage affiné (comeztier)']::text[], ARRAY['gluten','lait','œuf']::text[],
    'La masa crue se garde 24 heures au réfrigérateur, filmée au contact, et gagne à y passer la nuit : elle se roule beaucoup mieux le lendemain. Les croquettes panées et non frites se congèlent 2 mois à plat sur une plaque avant d''être mises en sac, et se plongent dans l''huile encore gelées, en comptant une minute de plus — c''est ce que fait une des pages du dossier et c''est aussi ce que dit la fiche parente. Frites, elles se gardent 2 jours au réfrigérateur et se réchauffent dix minutes à 180 °C, mais le cœur n''a plus jamais tout à fait le même coulant : la béchamel a raffermi une première fois.', '{"fridge_hours":48,"eat_immediately":false,"freezable":true,"freezer_months":2,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'REAL-109'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'champignon de paris frais' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Champignon de Paris frais', 370, 'g', 'required',
     'garniture', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'lait entier' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Lait entier', 700, 'ml', 'required',
     'béchamel', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
