     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 2, 'g', 'required',
     'assaisonnement', false, 11);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Essuyer les champignons au papier absorbant et les hacher très fin, presque en grains. Une croqueta se mange en deux bouchées et le fondant est tout ce qu''on lui demande : un morceau de champignon qui se distingue sous la dent casse cette texture, et c''est la seule raison de hacher aussi menu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Chauffer une poêle large à feu vif sans matière grasse, y jeter les champignons et les laisser rendre leur eau en remuant peu, six à huit minutes, jusqu''à ce que la poêle soit sèche et que les grains commencent à dorer. C''est l''étape qui décide de tout : chaque gramme d''eau qui reste ici s''ajoutera au lait et rendra la masa trop molle pour être roulée, quelle que soit la durée du repos au froid.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Dans une casserole à fond épais, fondre le beurre à feu doux et y faire suer l''oignon haché fin cinq minutes, sans le laisser prendre couleur. Il remplace ce que le jambon apportait tout seul dans la recette d''origine — du sel, du sucre et un fond de goût — et une coloration brune ici tacherait une béchamel qui doit rester ivoire.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser la farine d''un coup sur le beurre et l''oignon, et remuer sans arrêt deux bonnes minutes à feu doux. Le roux doit sentir le biscuit et non la farine crue : c''est un temps qu''on ne rattrape pas ensuite, le lait fige le goût de farine tel qu''il est au moment où on le verse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Retirer la casserole du feu et verser le lait froid d''un seul coup en fouettant énergiquement. Le contraste de température est le tour de main des croquetas : un roux chaud noyé de lait froid se dissout sans grumeau, là où un lait chaud sur un roux chaud prend en paquets qu''aucun fouet ne rattrape.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Remettre sur feu moyen-doux et cuire de quinze à vingt minutes en remuant presque sans cesse avec une spatule, en raclant bien le fond et les angles. La masa est prête quand elle se décolle en bloc de la paroi et qu''un sillon tracé au milieu tient une seconde avant de se refermer. Ajouter alors les champignons, la muscade, le sel et le poivre, et poursuivre cinq minutes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Étaler la masa dans un plat sur deux centimètres d''épaisseur, poser un film au contact et laisser refroidir, puis réfrigérer quatre heures au minimum, une nuit de préférence. Le film touche la surface pour empêcher une peau de se former ; le froid n''est pas un repos de confort mais l''étape qui rend la masa manipulable — tiède, elle colle aux mains et ne prend aucune forme.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Prélever la masa à la cuillère et rouler seize croquettes courtes entre les paumes légèrement humides, puis les passer une à une dans l''œuf battu en les égouttant, et les rouler dans la chapelure en pressant pour qu''elle adhère partout. Le moindre défaut d''enrobage est une fuite : la béchamel s''échappera par là dès qu''elle fondra.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Porter un litre d''huile à 180 °C dans une casserole haute et frire quatre croquettes à la fois, deux minutes environ, jusqu''à une couleur noisette. Peu à la fois, sinon la température chute et la panure boit au lieu de saisir. Égoutter sur du papier et servir sans attendre : le cœur doit être coulant, ce qu''il cesse d''être en refroidissant.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-102', 'recipe_family', 'Croquetas de champignons',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-102', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Mélange de bolets et de portobellos à la place du champignon de Paris, moitié-moitié (paulasapron)','Champignons surgelés, dont l''eau de décongélation remplace une partie du lait dans la béchamel (paulasapron)','Sauce soja et une cuillerée de vinaigre balsamique dans la masa, pour renforcer l''umami (comeztier)','Ail haché à la place de l''oignon, une gousse pour 500 ml de lait, avec du persil (okdiario)','Poivre blanc plutôt que noir, pour ne pas moucheter une béchamel claire (paulasapron)','Masa passée au mixeur plongeant avant le repos, pour une texture entièrement lisse (comeztier)','Passage à la farine avant l''œuf et la chapelure, soit une panure en trois temps (comeztier, paulasapron)','Servies avec une confiture de tomate et des copeaux de fromage affiné (comeztier)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-102","variants":["Mélange de bolets et de portobellos à la place du champignon de Paris, moitié-moitié (paulasapron)","Champignons surgelés, dont l''eau de décongélation remplace une partie du lait dans la béchamel (paulasapron)","Sauce soja et une cuillerée de vinaigre balsamique dans la masa, pour renforcer l''umami (comeztier)","Ail haché à la place de l''oignon, une gousse pour 500 ml de lait, avec du persil (okdiario)","Poivre blanc plutôt que noir, pour ne pas moucheter une béchamel claire (paulasapron)","Masa passée au mixeur plongeant avant le repos, pour une texture entièrement lisse (comeztier)","Passage à la farine avant l''œuf et la chapelure, soit une panure en trois temps (comeztier, paulasapron)","Servies avec une confiture de tomate et des copeaux de fromage affiné (comeztier)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-102', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('8c001d60e67b1457584d2e690d9c85b2'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":4,"heat":1,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["champignon","beurre","muscade"],"aroma_families":["champignon","beurre","béchamel","noix_muscade"],"target_textures":["croûte_croustillante","cœur_très_crémeux"],"signature_ingredients":["Champignon de Paris frais","Lait entier","Farine de blé T55","Beurre doux"],"identity_guardrails":["Les champignons sont poêlés à sec jusqu''à évaporation complète avant d''entrer dans la béchamel : sinon la masa ne prend jamais","La béchamel est très épaisse et refroidie quatre heures au minimum — c''est elle, et non la friture, qui fait la croqueta","Le cœur doit rester coulant à la sortie de l''huile : une croqueta ferme à cœur est une croqueta ratée","Panure et friture en bain profond, jamais au four : la croûte fine est ce qui tient le cœur liquide"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Omelette aux pommes de terre et oignons', 'omelette aux pommes de terre et oignons', 'France', 'France',
     'meal', 'omelette', 'domestic_standard', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Omelette aux pommes de terre et oignons', 'L''omelette paysanne sans son lard : pommes de terre rissolées, oignons blondis, œufs roulés encore crémeux et ciboulette ciselée.', ds.id, 'JUM-103',
    'Myko', 'editorial', 4, 15, 12, 'facile',
    NULL, NULL,
    'B', 'candidate', 'c750cdca2040772f2a0e3e1a16fc6203',
    '{"sweet":1,"salty":2,"acidic":0,"bitter":0,"umami":2,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":2}'::jsonb, ARRAY['œuf','oignon fondu','ciboulette']::text[],
    ARRAY['œuf cuit','alliacé frais','pomme de terre rissolée','beurre']::text[], ARRAY['moelleux','baveux à cœur','rondelles dorées']::text[],
    ARRAY['Œuf cru','Pomme de terre cuite','Oignon jaune cru']::text[], ARRAY['Les pommes de terre colorent à part avant d''être noyées dans l''œuf : versées crues ou molles, elles rendent leur eau dans l''omelette','L''oignon est doublé par rapport à la version au lard, parce qu''il en devient le seul aromate — le réduire donne une omelette de pommes de terre nature','L''omelette quitte le feu encore crémeuse au centre : trop cuite, elle devient sèche et caoutchouteuse','Il faut saler plus qu''à la paysanne : sans lardons, personne n''apporte le sel à sa place']::text[],
    ARRAY['saisie','rissolage','omelette roulée']::text[], ARRAY['Version marmiton.org à l''ancienne : ajouter 100 g de lardons aux oignons, une cuillerée de moutarde à l''ancienne et 10 cl de crème semi-épaisse aux œufs, et parsemer de gruyère — c''est la recette parente, lardons compris','Ail en semoule ou ail frais avec les pommes de terre, et persil à la place de la ciboulette (chefsimon.com, marmiton.org)','Comté en fines lamelles ajouté aux œufs battus, 150 g pour six parts (marmiton.org)','Gruyère râpé sur les pommes de terre avant de verser les œufs, 120 g pour quatre parts (750g.com)','Version espagnole plate : poivrons rouges et tomates concassées étuvés avec les oignons, pimenton fumé, cuisson terminée au four à 150 °C et omelette retournée sur assiette (chefsimon.com)','Version allégée : pommes de terre râpées crues, deux cuillerées de farine, du lait et les blancs montés en neige incorporés en dernier (750g.com)']::text[], ARRAY['œuf','lait']::text[],
    'Se mange dans la minute qui suit la cuisson, quand le cœur est encore crémeux — c''est vrai de toutes les omelettes et le retrait des lardons n''y change rien. À défaut, elle se garde 24 heures au réfrigérateur entre 0 et 4 °C dans une boîte hermétique, et se mange froide, coupée en lanières ou dans un sandwich ; réchauffée, elle durcit. Aucune page du dossier ne parle de congélation, et ce que fait physiquement un œuf coagulé est connu : il rend son eau à la décongélation et la texture devient spongieuse et caoutchouteuse. Ne se congèle donc pas, et c''est un constat de matière plutôt qu''une lecture du dossier.', '{"fridge_hours":24,"eat_immediately":true,"freezable":null,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-016'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'oeuf cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Œuf cru', 300, 'g', 'required',
     'protéine', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'pomme de terre cuite' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Pomme de terre cuite', 400, 'g', 'required',
     'féculent', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
