  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Débarrasser les champignons de leur terre avec un papier humide, couper le bout terreux du pied, puis les tailler en lamelles de trois à quatre millimètres. Ne jamais les passer sous le robinet : ils se gorgent d''une eau qu''ils rendront dans la poêle. Des lamelles plus fines disparaîtraient sous la garniture, alors qu''elles doivent faire dans le pita la couche que faisait le poulet.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Mêler dans un saladier l''huile d''olive, la sauce soja, la moitié du jus de citron, la moitié de l''ail haché, le paprika, le cumin, l''origan et le poivre. Y retourner les lamelles et laisser trente minutes à température ambiante. Trente minutes suffisent là où le poulet du parent en demandait deux : le champignon n''a pas de fibre à détendre, il boit tout de suite — et une marinade salée prolongée le ferait rendre son eau avant même d''avoir vu la poêle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pendant la marinade, verser le yaourt dans une passoire garnie d''un linge et le laisser perdre son eau une heure au réfrigérateur. Il y prend la densité du yaourt grec dont se servent les sources et que le catalogue ne porte pas ; faute de quoi la sauce file du pain dès la première bouchée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Râper le concombre à la grosse grille, le saler d''une pincée, attendre vingt minutes puis le presser à pleines mains au-dessus de l''évier : on en tire deux bonnes cuillerées d''eau, qui seraient parties dans la sauce. Le mélanger au yaourt égoutté avec l''ail et le jus de citron restants, poivrer et garder au froid.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Détailler le poivron en lanières et le passer cinq à six minutes à la poêle bien chaude : il doit prendre quelques marques noires et rester ferme au centre. Ajouté cru, il n''apporte que de l''eau et une note verte ; poussé trop loin, il s''avachit et mouille le pain de l''intérieur. Le débarrasser.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Égoutter les champignons de leur marinade, en gardant celle-ci, et les verser dans la même poêle brûlante — en deux fois, pour ne pas la charger. Les laisser deux minutes sans y toucher, puis les sauter cinq à six minutes : ils rendent d''abord leur eau, la poêle blanchit, et ce n''est qu''une fois cette eau partie que les bords colorent. Tant qu''elle est là, rien ne peut brunir, la poêle plafonnant à cent degrés. Verser la marinade réservée en fin de cuisson, laisser réduire trente secondes, goûter et saler seulement si nécessaire.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Réchauffer les pitas une trentaine de secondes de chaque côté, à sec, dans la poêle qui vient de servir. Ils regonflent et retrouvent leur souplesse : froids ils se fendent au pliage, trop longtemps chauffés ils sèchent et s''effritent entre les doigts.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Monter chaque pita dans cet ordre : une cuillerée de sauce, la laitue ciselée, les champignons, les poivrons, la tomate en dés, l''oignon rouge en fines lamelles, et une seconde cuillerée de sauce par-dessus. Celle du dessous isole le pain du jus des légumes, celle du dessus retient la garniture quand on roule. Rouler serré et manger tout de suite.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-111', 'recipe_family', 'Gyros végétarien aux champignons',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-111', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Pleurotes effilochées à la fourchette plutôt que champignons de Paris en lamelles, 510 à 600 g pour quatre (mypureplants, lazycatkitchen, biancazapatka, lovingitvegan)','Champignons marinés puis rôtis au four à 200-220 °C, vingt-cinq à quarante minutes, jusqu''aux bords croustillants, au lieu de la poêle (mypureplants, biancazapatka)','Sauce sans lait, montée au tofu soyeux ou aux graines de tournesol trempées, citron, ail et aneth, pour une version végane (veganricha, lazycatkitchen)','Feta émiettée dans le pita au moment de rouler (liveeatlearn, forkinthekitchen, therealfooddietitians)','Champignon « pulled » : concentré de tomate, sirop d''érable et une pointe de fumée liquide avec les épices, pour une garniture plus sombre et plus sucrée (biancazapatka, lovingitvegan, elavegan)','Cannelle et clou de girofle en pointe dans le mélange d''épices, à la façon du gyros de rôtissoire (biancazapatka, lovingitvegan, veggiesociety)','Cœurs d''artichaut marinés mêlés aux champignons, 200 g pour 400 g de champignons (biancazapatka, lovingitvegan)','Radis en rondelles dans la garniture (liveeatlearn, biancazapatka, lovingitvegan), et aneth frais dans la sauce au yaourt (veganricha, therealfooddietitians, brandnewvegan) — lazycatkitchen, à qui la première rédaction attribuait les deux, ne porte ni l''un ni l''autre mais de la menthe séchée','Version française du dossier : aubergines panées à la chapelure et au parmesan, roquette et tzatziki dans un wrap (chefsimon)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-111","variants":["Pleurotes effilochées à la fourchette plutôt que champignons de Paris en lamelles, 510 à 600 g pour quatre (mypureplants, lazycatkitchen, biancazapatka, lovingitvegan)","Champignons marinés puis rôtis au four à 200-220 °C, vingt-cinq à quarante minutes, jusqu''aux bords croustillants, au lieu de la poêle (mypureplants, biancazapatka)","Sauce sans lait, montée au tofu soyeux ou aux graines de tournesol trempées, citron, ail et aneth, pour une version végane (veganricha, lazycatkitchen)","Feta émiettée dans le pita au moment de rouler (liveeatlearn, forkinthekitchen, therealfooddietitians)","Champignon « pulled » : concentré de tomate, sirop d''érable et une pointe de fumée liquide avec les épices, pour une garniture plus sombre et plus sucrée (biancazapatka, lovingitvegan, elavegan)","Cannelle et clou de girofle en pointe dans le mélange d''épices, à la façon du gyros de rôtissoire (biancazapatka, lovingitvegan, veggiesociety)","Cœurs d''artichaut marinés mêlés aux champignons, 200 g pour 400 g de champignons (biancazapatka, lovingitvegan)","Radis en rondelles dans la garniture (liveeatlearn, biancazapatka, lovingitvegan), et aneth frais dans la sauce au yaourt (veganricha, therealfooddietitians, brandnewvegan) — lazycatkitchen, à qui la première rédaction attribuait les deux, ne porte ni l''un ni l''autre mais de la menthe séchée","Version française du dossier : aubergines panées à la chapelure et au parmesan, roquette et tzatziki dans un wrap (chefsimon)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-111', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('646369e0beb12ef55191921604f1ce6c'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":3,"acidic":3,"bitter":1,"umami":4,"heat":1,"pungency":3,"richness":3,"freshness":3,"intensity":4},"dominant_flavors":["champignon grillé","yaourt à l''ail","citron","paprika"],"aroma_families":["origan","cumin","ail","champignon","agrume"],"target_textures":["pain moelleux","champignon doré aux bords fermes","crudités croquantes"],"signature_ingredients":["Champignon de Paris frais","Pain pita","Yaourt nature"],"identity_guardrails":["Les champignons se saisissent en deux fois dans une poêle brûlante : entassés, ils bouillent dans leur eau et sortent gris, sans les bords grillés qui font le gyros","Le yaourt s''égoutte une heure — non égoutté, la sauce traverse le pain","Le concombre se dégorge et se presse, sinon il liquéfie la sauce","Marinade au paprika, au cumin et à l''origan : c''est elle, et non la protéine, qui donne au pita son goût de gyros","Aucune forme d''origine animale hors le yaourt : la sauce soja remplace ici le glutamate que la volaille apportait"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Lentilles au tofu fumé', 'lentilles au tofu fume', 'France', 'France',
     'meal', 'plat mijoté', 'named_traditional_dish', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Lentilles au tofu fumé', 'Les lentilles au lard de SRC-042 avec du tofu fumé à la place des lardons : mêmes lentilles vertes, mêmes carottes, oignon, thym, laurier et girofle, même cocotte.', ds.id, 'JUM-112',
    'Myko', 'editorial', 4, 20, 40, 'facile',
    NULL, NULL,
    'B', 'candidate', 'ef5d3ead1d16f7883162fee976339159',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3}'::jsonb, ARRAY['fumé','terreux']::text[],
    ARRAY['fumé','herbacé sec','végétal cuit']::text[], ARRAY['lentille fondante restée entière','dés de tofu dorés aux arêtes fermes','jus court et légèrement lié']::text[],
    ARRAY['Lentille verte sèche, crue','Tofu fumé','Thym séché']::text[], ARRAY['Le fumé fait la moitié du nom du plat : un tofu nature à la place du tofu fumé donnerait des lentilles mijotées sans caractère','Le tofu se dore à part et ne revient que dix minutes avant la fin — mijoté quarante minutes, il devient une éponge grise','Les grains doivent tenir entiers : passé au mixeur, le plat bascule en velouté et change d''identité','Le sel ne s''ajoute qu''en fin de cuisson, le tofu fumé salant déjà le bouillon','Mouillé à l''eau et jamais à un bouillon de volaille : c''est ce qui sépare ce jumeau de sa base']::text[],
    ARRAY['saisie','mijotage','réduction']::text[], ARRAY['Avec 200 g de champignons de Paris ajoutés au mouillement, ou six champignons bruns émincés (lacerisesurlemaillot, marie.cooking)','Navet et céleri branche taillés en dés avec la carotte, 300 g de chacun pour 500 g de lentilles (cuisine-alcaline)','Une cuillerée à soupe de concentré de tomate dans l''eau de mouillement, pour un jus plus rond et plus sombre (lacerisesurlemaillot)','Sauce soja à la place du sel, versée en fin de cuisson (cuisine-alcaline)','Un verre de vin blanc sec pour déglacer après avoir doré le tofu (marie.cooking, healthylalou)','Romarin ajouté au thym et au laurier (marie.cooking, healthylalou)','Crème végétale à la place de la crème fraîche, pour une version végane (marie.cooking)','Deux cuillerées de miso brun en fin de cuisson à la place du tofu fumé, avec une sauce à la moutarde : c''est le petit salé végétalien de healthylalou, un autre plat que celui-ci','Version veloutée héritée du parent : mixer la moitié de la cocotte, remonter à la crème et remettre les dés de tofu par-dessus']::text[], ARRAY['lait','soja']::text[],
    'Trois jours au réfrigérateur à 4 °C en boîte fermée, et le plat est meilleur le lendemain, le fumé du tofu ayant eu la nuit pour passer dans le jus. Les lentilles boivent ce jus en refroidissant : rallonger d''un fond d''eau à la réchauffe douce. Congélation 2 mois, à condition de n''avoir pas versé la crème, qui tranche à la décongélation — la verser plutôt après réchauffage. Le tofu fumé y gagne plutôt qu''il n''y perd : le gel ouvre sa trame et il ressort plus ferme, donc plus apte à boire le jus. Aucune des quatre pages ne parle de conservation ; c''est ce que fait ce type de mijoté.', '{"fridge_hours":72,"eat_immediately":false,"freezable":true,"freezer_months":2,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-042'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'lentille verte seche crue' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Lentille verte sèche, crue', 320, 'g', 'required',
     'légumineuse', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'tofu fume' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Tofu fumé', 260, 'g', 'required',
     'protéine', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
