  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Rincer les lentilles à l''eau froide dans une passoire, puis les faire glisser en couche mince sur la main pour repérer un gravillon — il s''en cache un dans un paquet sur trois, et il se signale toujours sous la dent de quelqu''un. Pas de trempage : la peau s''attendrit, les grains s''ouvrent au mijotage, et tout ce plat repose sur des grains entiers.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Peler et détailler carotte, oignon et échalote au format d''un grain de lentille, pour que rien ne se mange à part. Prévoir à l''achat 210 g de carottes et 170 g d''oignon, les épluchures emportant la différence ; l''ail se pèse gousses nues, soit trois à quatre gousses. Couper enfin le tofu fumé en dés d''un centimètre et les sécher dans un linge — humide, il colle au fond de la cocotte et se déchire au premier retournement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chauffer la moitié de l''huile dans une cocotte à fond épais et y colorer les dés de tofu à feu moyen-vif, cinq à six minutes, en ne les retournant que lorsqu''ils se détachent seuls. C''est le geste qui remplace le lard rendant sa graisse : le tofu n''en rend aucune, il faut la lui donner, et c''est cette croûte-là qui portera le fumé dans le jus. Les débarrasser dans une assiette.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Remettre la cocotte à feu moyen avec le reste de l''huile et y laisser tomber carotte, oignon et échalote une dizaine de minutes, sans jamais les laisser prendre couleur : on cherche ici le fondant, la coloration étant déjà venue avec le tofu. Jeter l''ail haché à la toute fin, trente secondes, et pas avant — il brûle deux fois plus vite que l''oignon.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser les lentilles égouttées et les tourner une minute dans les légumes gras : elles se laquent et prennent le fond de cocotte avant de rencontrer le moindre liquide. Mouiller alors d''un litre d''eau froide, deux doigts au-dessus des grains, et glisser thym, laurier et clous de girofle. Amener à ébullition, redescendre au frémissement, couvrir aux trois quarts, compter trente-cinq à quarante minutes. Toujours rien de salé à ce stade.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Remettre les dés de tofu dix minutes avant la fin seulement. Plus tôt, ils boivent le jus et redeviennent mous : c''est le même calcul que pour les lardons du parent, à ceci près qu''un lardon avait encore du gras à donner au bouillon, quand le tofu n''a plus rien à échanger une fois doré.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Prélever un grain et le goûter : il doit se défaire sous la dent sans perdre sa peau. Retirer alors le laurier et les girofles, saler, poivrer, et verser la crème pour qui veut un jus rond, en laissant frémir trois minutes qu''elle s''y lie. Persil ciselé au dernier moment, hors du feu.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-112', 'recipe_family', 'Lentilles au tofu fumé',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-112', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Avec 200 g de champignons de Paris ajoutés au mouillement, ou six champignons bruns émincés (lacerisesurlemaillot, marie.cooking)','Navet et céleri branche taillés en dés avec la carotte, 300 g de chacun pour 500 g de lentilles (cuisine-alcaline)','Une cuillerée à soupe de concentré de tomate dans l''eau de mouillement, pour un jus plus rond et plus sombre (lacerisesurlemaillot)','Sauce soja à la place du sel, versée en fin de cuisson (cuisine-alcaline)','Un verre de vin blanc sec pour déglacer après avoir doré le tofu (marie.cooking, healthylalou)','Romarin ajouté au thym et au laurier (marie.cooking, healthylalou)','Crème végétale à la place de la crème fraîche, pour une version végane (marie.cooking)','Deux cuillerées de miso brun en fin de cuisson à la place du tofu fumé, avec une sauce à la moutarde : c''est le petit salé végétalien de healthylalou, un autre plat que celui-ci','Version veloutée héritée du parent : mixer la moitié de la cocotte, remonter à la crème et remettre les dés de tofu par-dessus']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-112","variants":["Avec 200 g de champignons de Paris ajoutés au mouillement, ou six champignons bruns émincés (lacerisesurlemaillot, marie.cooking)","Navet et céleri branche taillés en dés avec la carotte, 300 g de chacun pour 500 g de lentilles (cuisine-alcaline)","Une cuillerée à soupe de concentré de tomate dans l''eau de mouillement, pour un jus plus rond et plus sombre (lacerisesurlemaillot)","Sauce soja à la place du sel, versée en fin de cuisson (cuisine-alcaline)","Un verre de vin blanc sec pour déglacer après avoir doré le tofu (marie.cooking, healthylalou)","Romarin ajouté au thym et au laurier (marie.cooking, healthylalou)","Crème végétale à la place de la crème fraîche, pour une version végane (marie.cooking)","Deux cuillerées de miso brun en fin de cuisson à la place du tofu fumé, avec une sauce à la moutarde : c''est le petit salé végétalien de healthylalou, un autre plat que celui-ci","Version veloutée héritée du parent : mixer la moitié de la cocotte, remonter à la crème et remettre les dés de tofu par-dessus"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-112', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('ef5d3ead1d16f7883162fee976339159'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3},"dominant_flavors":["fumé","terreux"],"aroma_families":["fumé","herbacé sec","végétal cuit"],"target_textures":["lentille fondante restée entière","dés de tofu dorés aux arêtes fermes","jus court et légèrement lié"],"signature_ingredients":["Lentille verte sèche, crue","Tofu fumé","Thym séché"],"identity_guardrails":["Le fumé fait la moitié du nom du plat : un tofu nature à la place du tofu fumé donnerait des lentilles mijotées sans caractère","Le tofu se dore à part et ne revient que dix minutes avant la fin — mijoté quarante minutes, il devient une éponge grise","Les grains doivent tenir entiers : passé au mixeur, le plat bascule en velouté et change d''identité","Le sel ne s''ajoute qu''en fin de cuisson, le tofu fumé salant déjà le bouillon","Mouillé à l''eau et jamais à un bouillon de volaille : c''est ce qui sépare ce jumeau de sa base"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Amatriciana végétarienne', 'amatriciana vegetarienne', 'Italie', 'Italie',
     'meal', 'pâtes en sauce', 'named_traditional_dish', 'tomato_herbal',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Amatriciana végétarienne', 'Les bucatini all''amatriciana de REAL-101 avec du tofu fumé à la place du guanciale : même tomate pelée, même pecorino, même pâte creuse finie dans la sauce.', ds.id, 'JUM-113',
    'Myko', 'editorial', 4, 15, 30, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '53ac4a3f577b75f126237fd9fd9aae49',
    '{"sweet":2,"salty":3,"acidic":3,"bitter":0,"umami":4,"heat":1,"pungency":2,"richness":2,"freshness":2,"intensity":4}'::jsonb, ARRAY['tomate','fumé','acidulé']::text[],
    ARRAY['tomate_cuite','fumé','piment','pecorino']::text[], ARRAY['pâtes_fermes','sauce_brillante','dés de tofu croustillants']::text[],
    ARRAY['Bucatini secs','Tofu fumé','Pecorino romano','Tomate entière pelée en conserve']::text[], ARRAY['Le tofu se colore franchement avant la tomate : sans cette croûte il reste blanc et mou dans la sauce, et le plat perd ce que le guanciale lui donnait','Pas de crème : la sauce se lie à l''eau de cuisson des pâtes et à rien d''autre','L''oignon reste discret — 15 g par personne — et fondu sans coloration : dominant, ce n''est plus une amatriciana','Le pecorino s''ajoute hors du feu, sinon il file et la sauce graine','Le tofu est fumé et non nature : c''est le fumé qui tient le rôle du guanciale']::text[],
    ARRAY['saisie','réduction','cuisson al dente','mantecatura']::text[], ARRAY['Spaghetti ou pâtes courtes à la place des bucatini, 320 g pour quatre (primochef, mammachechef, vegolosi)','Levure maltée en paillettes ou « parmesan végane » à la place du pecorino, pour une version végane — c''est ce que font les trois pages du dossier (primochef, mammachechef)','Une cuillerée à soupe de sauce soja avec le vin blanc, pour appuyer l''umami du tofu (mammachechef)','Passata rustique seule à la place des tomates pelées écrasées (vegolosi, primochef)','Sans oignon du tout, à la façon de l''amatriciana traditionnelle : le tofu est alors coloré directement dans l''huile']::text[], ARRAY['gluten','lait','soja','sulfites']::text[],
    '3 jours au réfrigérateur, comme le parent, et pour la sauce seule : c''est elle qu''il faut mettre de côté quand on cuisine à l''avance. Les pâtes déjà sautées dans la sauce tiennent 2 jours au froid et se réchauffent à la poêle avec une cuillerée d''eau, jamais au micro-ondes qui les rend cotonneuses ; elles ne se congèlent pas, un bucatino décongelé se casse et rend son eau. UNE PAGE PARLE DE CONSERVATION, contrairement à ce que la première rédaction affirmait, et il faut la citer précisément parce qu''elle dit l''inverse de ce qui arrangeait : primochef consacre un paragraphe « Conservazione » à déconseiller la garde ET la congélation, le plat se mangeant dès que les pâtes sont enrobées de leur sauce. On ne s''autorise donc aucune durée plus longue que celle du parent, et on ne déclare pas la congélation de la sauce, que ni le dossier ni REAL-101 ne portent.', '{"fridge_hours":48,"eat_immediately":false,"freezable":false,"freezer_months":null,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'REAL-101'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

