  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'ail cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Ail cru', 6, 'g', 'required',
     'aromatique', false, 5);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'vinaigre de xeres' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Vinaigre de xérès', 20, 'ml', 'required',
     'acidité', false, 6);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 6, 'g', 'required',
     'assaisonnement', false, 7);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Inciser les tomates d''une croix, les plonger trente à soixante secondes dans l''eau bouillante puis aussitôt dans l''eau glacée : la peau se retire alors seule. Mixée, cette peau laisse des points qui ne fondent jamais et donnent au salmorejo un grain qu''il n''admet pas — c''est l''une des choses qui le séparent d''un gaspacho.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Mixer les tomates pelées et grossièrement coupées jusqu''à obtenir un jus lisse. Ôter la croûte du pain rassis, déchirer la mie en morceaux et la laisser cinq minutes dans ce jus avant de relancer le mixeur : la mie doit boire d''abord, sinon elle reste en grumeaux que rien ne rattrape ensuite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Ajouter l''ail dégermé, le vinaigre de xérès et le sel, puis mixer longuement, une bonne minute, jusqu''à une crème parfaitement lisse. Le germe de l''ail est amer et il ne cuit pas ici : rien ne viendra corriger ce qu''on aura laissé passer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Moteur en marche à vitesse moyenne, verser l''huile d''olive en filet mince. C''est une émulsion et elle se voit : la purée passe du rouge à un rose orangé et s''épaissit franchement. S''arrêter dès que la couleur a tourné — trop travaillée, l''huile d''olive devient amère, et c''est irréversible.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Couvrir et laisser au moins une heure au réfrigérateur, davantage si l''on peut. Le salmorejo se sert froid, et il continue d''épaissir en refroidissant : le détendre au moment de servir avec un peu d''eau glacée s''il est devenu trop dense pour la cuillère.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Cuire les œufs dix minutes à l''eau bouillante, les rafraîchir, les écaler et les écraser à la fourchette plutôt que de les trancher. Répartir la soupe en assiettes creuses, disposer l''œuf émietté au centre et finir d''un filet d''huile d''olive. Émietté, l''œuf tient à la surface de cette crème épaisse ; en rondelles, il s''enfonce et on le mange à part — or, le jambon parti, il est ici la seule garniture et doit se retrouver dans chaque cuillerée.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-114', 'recipe_family', 'Salmorejo aux œufs durs',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-114', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Croûtons de mie frits à l''huile d''olive à la place du jambon, deux tranches de pain pour quatre parts (secretosdelsur)','Un œuf dur mixé dans la soupe elle-même, en plus de celui de la garniture, pour une crème encore plus dense (spanishsabores)','Tomates non mondées, quand le mixeur est assez puissant pour ne rien laisser passer (secretosdelsur, fussfreeflavours)','Sans vinaigre du tout, la crème ne tenant son acidité que de la tomate (directoalpaladar)','Poivre noir au moulin dans la soupe et sur l''assiette (themediterraneandish)','Version végane du dossier, qui est un autre plat : tofu ferme, avocat, amandes, noix et pistaches mixés avec la tomate, relevés de curry et de curcuma (turecetavegana)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"JUM-114","variants":["Croûtons de mie frits à l''huile d''olive à la place du jambon, deux tranches de pain pour quatre parts (secretosdelsur)","Un œuf dur mixé dans la soupe elle-même, en plus de celui de la garniture, pour une crème encore plus dense (spanishsabores)","Tomates non mondées, quand le mixeur est assez puissant pour ne rien laisser passer (secretosdelsur, fussfreeflavours)","Sans vinaigre du tout, la crème ne tenant son acidité que de la tomate (directoalpaladar)","Poivre noir au moulin dans la soupe et sur l''assiette (themediterraneandish)","Version végane du dossier, qui est un autre plat : tofu ferme, avocat, amandes, noix et pistaches mixés avec la tomate, relevés de curry et de curcuma (turecetavegana)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-114', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('8d41d5bf12dee135bad6ea51c0b0e922'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"fresh_acidic","scores":{"sweet":1,"salty":2,"acidic":5,"bitter":1,"umami":2,"heat":0,"pungency":2,"richness":1,"freshness":5,"intensity":3},"dominant_flavors":["tomate crue","huile d''olive","acidulé"],"aroma_families":["tomate","huile_olive","ail","vinaigre"],"target_textures":["très_épais_et_soyeux","œuf émietté distinct"],"signature_ingredients":["Tomate fraîche mûre","Pain blanc rassis","Huile d''olive vierge extra","Œuf dur"],"identity_guardrails":["Plus épais qu''un gaspacho : c''est le pain, et non l''eau, qui fait la texture","L''huile se verse en filet dans le mixeur en marche — versée d''un coup, elle ne s''émulsionne pas et le plat reste rouge et liquide","Ne pas sur-mixer après l''huile : elle vire à l''amertume et rien ne la rattrape","Se sert froid, jamais à température : une heure de réfrigérateur au minimum, et le plat gagne à attendre plus","L''œuf dur est ici la seule garniture — le jambon du plat d''origine est ce que ce jumeau retire, et rien ne le remplace"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Tofu sauté aux poivrons', 'tofu saute aux poivrons', 'France / cuisine domestique internationale', 'France / cuisine domestique internationale',
     'meal', 'plat sauté', 'domestic_standard', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, conservation_profile, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation, corpus_poured_on)
  SELECT
    v_family, 3, 'Tofu sauté aux poivrons', 'Le poulet aux poivrons de RAP-035 avec du tofu ferme à la place de la volaille : mêmes trois couleurs de poivron, même oignon, même ail et même gingembre, même feu vif.', ds.id, 'JUM-115',
    'Myko', 'editorial', 4, 20, 20, 'facile',
    NULL, NULL,
    'B', 'candidate', 'f8998881b1e1a1a41b34b478bfed4369',
    '{"sweet":3,"salty":3,"acidic":1,"bitter":1,"umami":4,"heat":1,"pungency":3,"richness":2,"freshness":2,"intensity":3}'::jsonb, ARRAY['poivron','sauce soja','gingembre','oignon']::text[],
    ARRAY['végétal grillé','gingembre','allium','soja']::text[], ARRAY['poivrons croquants','cubes de tofu dorés','bords_grillés']::text[],
    ARRAY['Tofu ferme','Poivron rouge frais','Gingembre frais']::text[], ARRAY['Le tofu se presse vingt minutes avant tout : non pressé, il bout dans son eau et ne dore jamais','Feu vif du début à la fin : à feu doux les poivrons compotent et le plat change de nature','Le tofu est saisi puis réservé, il ne cuit pas avec les légumes','Trois couleurs de poivron, comme chez la base carnée','Ail et gingembre entrent en dernier, pour ne pas brûler','Pas de sauce liée à la fécule : le jus des légumes et la sauce soja suffisent, sans quoi ce n''est plus le sauté de RAP-035']::text[],
    ARRAY['pressage du tofu','saisie','sauté','cuisson courte']::text[], ARRAY['Tofu roulé dans la fécule de maïs avant la poêle, pour une croûte plus franche (littlespicejar, rainbowplantlife)','Tofu tranché fin, badigeonné de sauce et rôti au four à 220 °C, dix minutes par face, au lieu de la sauteuse (plantbasedrdblog)','Sauce montée en fin de cuisson : sirop d''érable ou sucre, hoisin ou vinaigre de riz (livinglou, plantbasedrdblog, createmindfully), liée d''une cuillerée de fécule délayée dans l''eau chez la seule plantbasedrdblog','Huile de sésame grillé dans la marinade et graines de sésame en finition (livinglou) — littlespicejar, à qui la première rédaction les attribuait aussi, n''en porte ni dans sa liste ni dans sa méthode','Carottes en julienne et champignons bruns ajoutés aux poivrons (createmindfully)','Piment frais — serrano, fresno — ou flocons de piment avec l''ail et le gingembre (livinglou, createmindfully, littlespicejar)','Échalotes émincées à la place de l''oignon (littlespicejar)','Tofu fumé et poivron vert seul, à la façon du wok français écarté du dossier (kintaki)']::text[], ARRAY['soja']::text[],
    'Deux jours au réfrigérateur, pas plus, et avec la même réserve que la version au poulet : les poivrons y perdent leur croquant, qui est tout l''intérêt du plat. Le réemploi le plus juste est froid, en salade ou dans un wrap, plutôt que réchauffé ; à la poêle très chaude et brièvement si l''on tient au chaud, jamais au micro-ondes. La congélation est possible 2 mois mais elle change le tofu plus qu''elle ne le conserve : l''eau qu''il porte gèle en cristaux qui percent sa trame et il ressort spongieux — certains cuisiniers congèlent d''ailleurs leur tofu exprès pour cela, mais ce n''est plus la texture de ce plat-ci.', '{"fridge_hours":48,"eat_immediately":false,"freezable":true,"freezer_months":2,"serve_cold":null,"source":"parsed"}'::jsonb, false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'RAP-035'), '{}'::jsonb, DATE '2026-09-04'
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    conservation_profile = EXCLUDED.conservation_profile,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation,
    -- Le coalesce DANS CET ORDRE, et c'est la règle qui compte : le registre
    -- l'emporte quand il sait, et une date déjà en base n'est JAMAIS effacée
    -- par un registre qui ne sait pas. Un rechargement de corpus ne doit pas
    -- faire disparaître les nouveautés d'un lot passé.
    corpus_poured_on = coalesce(EXCLUDED.corpus_poured_on, culinary.recipe_versions.corpus_poured_on)
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
