  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 9, 'g', 'required',
     'assaisonnement', false, 14);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 2, 'g', 'required',
     'assaisonnement', false, 15);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Couvrir les haricots rouges secs de trois fois leur volume d''eau froide et les oublier dix à douze heures, une nuit entière de préférence, puis jeter cette eau et les rincer. Le trempage n''est pas une commodité : sans lui la cuisson dépasse trois heures, et la peau se fend longtemps avant que le cœur du grain n''ait cédé.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Mettre les grains dans une casserole, les couvrir largement d''eau froide sans sel avec une des deux feuilles de laurier et la moitié du thym, donner dix minutes de gros bouillons puis baisser à frémissement pour une heure environ, jusqu''à ce qu''un grain s''écrase sans effort. Ne saler qu''à mi-parcours : le sel du départ raffermit la peau et la cuisson n''en finit plus. Égoutter en gardant un bol de l''eau de cuisson, qui est chargée d''amidon.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chauffer l''huile d''olive dans une cocotte et y faire suer à feu moyen l''oignon, le poivron et le céleri taillés en petits dés — la trinité créole —, une dizaine de minutes, jusqu''à ce qu''ils rendent leur eau et s''affaissent sans colorer. La version au poulet fait suer cette même trinité à sec, sous des morceaux de volaille qui lui rendent leur graisse au four ; privée de volaille, elle n''a plus rien à boire, accroche et brûle. C''est la seule raison pour laquelle ce jumeau porte de l''huile là où sa base n''en portait pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ajouter l''ail haché, le paprika fumé et le piment, et remuer une trentaine de secondes seulement, casserole tirée sur le bord le plus doux du feu. Une épice en poudre brûle en quelques secondes et vire à l''amer, et c''est irrattrapable dans un plat qui va ensuite mijoter une demi-heure. Écraser les tomates pelées à la main au-dessus de la cocotte, ajouter le reste du thym et la seconde feuille de laurier.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser les haricots égouttés, le bouillon de légumes et deux louches de leur eau de cuisson, saler, poivrer et laisser mijoter à découvert une vingtaine de minutes. Écraser à la cuillère un cinquième des grains contre la paroi de la cocotte : l''amidon qu''ils relâchent épaissit le jus et lie le plat. C''est ce qui remplace ici le jus du poulet rôti, qui liait la version carnée en tombant sur les haricots.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Pendant ce temps, cuire le riz long à grande eau bouillante salée, l''égoutter et le laisser sécher deux minutes hors du feu, couvercle posé de travers. Répartir le riz dans les assiettes et verser les haricots par-dessus, sans mélanger : le grain doit rester distinct pour boire la sauce au fur et à mesure, et non se gorger d''un coup dans la cocotte. Retirer les feuilles de laurier avant de servir.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'JUM-123', 'recipe_family', 'Haricots rouges et riz à la créole',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'JUM-123', 'missing_required_count', v_missing), 'open');
  END IF;

