  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Une cuillerée à café d''origan séché avec le paprika, présente dans les deux sources solides (acouplecooks, themountainkitchen)','Un trait de vinaigre en fin de cuisson — vinaigre de vin rouge ou de cidre — pour réveiller le mijoté (themountainkitchen, fromthecomfortofmybowl)','Une demi-tasse de carotte en dés dans la trinité, soit environ 60 g pour quatre (themountainkitchen)','Haricots rouges en conserve à la place des grains secs, deux boîtes égouttées pour quatre : la cuisson tombe à vingt minutes et le plat devient un plat de semaine (acouplecooks, themountainkitchen)','Riz complet à la place du riz long blanc (acouplecooks)','Saucisses végétales tranchées et colorées avant la trinité, quatre pour quatre parts (fromthecomfortofmybowl)','Deux cuillerées à soupe de mélange cajun tout prêt à la place du paprika fumé et du piment (fromthecomfortofmybowl)','Un filet de sauce piquante et du persil plat ciselé au service (acouplecooks, themountainkitchen)']::text[]) AS variant(name);

