  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:JUM-123', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('0d965fd43e3c139b083bb894cd844e13'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"smoky_sweet","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":3,"heat":3,"pungency":3,"richness":2,"freshness":2,"intensity":4},"dominant_flavors":["paprika fumé","poivron","haricot rouge"],"aroma_families":["paprika_fume","thym","poivron","celeri","oignon_compoté","laurier"],"target_textures":["haricot fondant à peau intacte","sauce_épaisse","riz_moelleux"],"signature_ingredients":["Haricot rouge sec","Riz long blanc cru","Paprika fumé","Poivron vert frais"],"identity_guardrails":["La trinité oignon-poivron-céleri est la base du plat : sans elle, ce sont des haricots en sauce, pas un plat créole de Louisiane","Pas de roux : la liaison vient de l''amidon des grains écrasés contre la paroi, jamais d''une farine","Le mijotage se fait à découvert, pour que le jus réduise et enrobe au lieu de rester clair","Le riz reste à part et reçoit les haricots dans l''assiette : mélangé en cocotte, il se gorge et le plat devient une bouillie","Aucun bouillon de volaille ni aucune charcuterie fumée : le fumé vient du paprika, et c''est ce qui fait de cette fiche le jumeau de sa base"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '618171d8e85b66e7e7897406ad4c9f62' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

-- Composition réelle : le croque-monsieur utilise une béchamel maison
-- dimensionnée à 240 g pour la recette de référence (4 personnes).
DO $composition$
DECLARE
  v_parent uuid;
  v_child uuid;
  v_component uuid;
BEGIN
  SELECT rv.id INTO v_parent
  FROM culinary.recipe_versions rv
  JOIN ops.source_datasets ds ON ds.id = rv.source_dataset_id
  WHERE ds.code = 'myko_editorial_v3' AND rv.source_record_key = 'FR-023';

  SELECT rv.id INTO v_child
  FROM culinary.recipe_versions rv
  JOIN ops.source_datasets ds ON ds.id = rv.source_dataset_id
  WHERE ds.code = 'myko_editorial_v3' AND rv.source_record_key = 'FR-024';

  IF v_parent IS NOT NULL AND v_child IS NOT NULL THEN
    INSERT INTO culinary.recipe_components
      (recipe_version_id, name, component_role, position, sub_recipe_version_id,
       required_quantity, required_unit)
    VALUES
      (v_parent, 'Béchamel maison', 'sauce', 2, v_child, 240, 'g')
    RETURNING id INTO v_component;

    UPDATE culinary.recipe_ingredient_requirements
    SET component_id = v_component,
        requirement_type = 'sub_recipe'
    WHERE recipe_version_id = v_parent
      AND source_name = 'Béchamel préparée';
  END IF;
END
$composition$;

-- 77 lien(s) de base partagée sur 71 plat(s).
--
-- Les liens voyagent en CTE, et non par une table temporaire. Une table
-- `CREATE TEMP TABLE ... ON COMMIT DROP` disparaît à la fin de l'instruction
-- qui la crée dès lors qu'aucune transaction n'est ouverte — et c'est
-- exactement le cas ici : la CI charge ce fichier avec
-- `psql -v ON_ERROR_STOP=1 -f`, sans `--single-transaction` et sans `BEGIN`,
-- donc en autocommit. L'`INSERT` suivant ne trouvait plus la table
-- (« relation "_liens_corpus" does not exist ») et le chargeur entier
-- s'arrêtait là. Une CTE ne dépend ni de la transaction ni de la session : elle
-- tient dans son instruction, et les deux chemins — le fichier d'un seul tenant
-- et les tranches de `build-corpus-migration.mjs` — la portent à l'identique.
