UPDATE culinary.recipe_ingredient_requirements exigence
SET component_id = composant.id, requirement_type = 'sub_recipe'
FROM lien
JOIN ops.source_datasets dataset ON dataset.code = 'myko_editorial_v3'
JOIN culinary.recipe_versions parent
  ON parent.source_dataset_id = dataset.id AND upper(parent.source_record_key) = lien.parent_code
JOIN culinary.recipe_versions enfant
  ON enfant.source_dataset_id = dataset.id AND upper(enfant.source_record_key) = lien.base_code
JOIN culinary.recipe_components composant
  ON composant.recipe_version_id = parent.id AND composant.sub_recipe_version_id = enfant.id
WHERE exigence.recipe_version_id = parent.id
  AND exigence.position = lien.ingredient_pos::integer
  AND exigence.source_name = lien.ingredient_name
  AND (exigence.component_id IS DISTINCT FROM composant.id
       OR exigence.requirement_type IS DISTINCT FROM 'sub_recipe');

-- Retrait de FR-007 — Ratatouille provençale
UPDATE culinary.recipe_versions rv
SET quality_level = 'D',
    planning_eligible = false,
    eligibility_issues = jsonb_build_array(jsonb_build_object(
      'code', 'recipe_retired',
      'family', 'Ratatouille provençale',
      'reason', 'Doublon de SRC-051 « Ratatouille », écrite depuis un dossier de sept sources. Garder les deux mettait le même plat deux fois au corpus, que le moteur de diversité comptait comme deux plats distincts dans une semaine. Le retrait ne supprime rien en base : vingt-deux créneaux planifiés référencent FR-007 — neuf repas distincts, dont trois à venir sur le plan vivant — et chacun garde son instantané d''exécution, ingrédients, étapes et nutrition figés au moment de la planification, ce qui les rend lisibles sans elle.'
    ))
FROM ops.source_datasets ds
WHERE ds.id = rv.source_dataset_id
  AND ds.code = 'myko_editorial_v3'
  AND upper(rv.source_record_key) = 'FR-007';
